#!/data/data/com.termux/files/usr/bin/bash
# يضيف الأيقونة الخامسة (الخرائط الذهنية) ودروس الثالثة تسيير واقتصاد إلى مشروع zad-1am
set -e
cd ~/zad-1am/www || { echo "لم أجد المجلد ~/zad-1am/www"; exit 1; }
cp -n index.html index.html.bak_maps 2>/dev/null || true

cat > lessons_3as_ge.js <<'ZAD_EOF'
/* دروس الثالثة ثانوي (تسيير واقتصاد): تستبدل العلوم الإسلامية والاقتصاد والمناجمنت. يُحمَّل بعد lessons.js */
(function(){
  if(typeof LESSONS_DB==='undefined')return;
  var A=LESSONS_DB.AS3=LESSONS_DB.AS3||{};
  var isl=[{"title":"وسائل القرآن الكريم في تثبيت العقيدة الإسلامية","content":"▸ الفكرة العامة\n• القرآن يخاطب العقل والوجدان بأساليب متنوعة، ويقدم الحجة والبرهان.\n▸ أهم الوسائل\n• لفت النظر إلى الكون والتأمل فيه\n• مخاطبة العقل وإقامة الحجة والبرهان\n• ضرب الأمثال\n• القصص القرآني\n• الترغيب والترهيب\n• الجدال بالتي هي أحسن\n▸ الهدف منها\n• الوصول إلى اليقين لا التقليد\n• تثبيت الإيمان بالله وحده\n• إبطال الشرك والخرافة\n▸ أهم المصطلحات\n• العقيدة\n• الحجة والبرهان\n• الاستدلال\n• التأمل في الكون\n▸ شرح موسّع\n• من أبرز وسائل القرآن دعوته إلى النظر في الكون: السماء والأرض والإبل والجبال، لأن في إتقان الخلق دليلًا على وجود الخالق ووحدانيته. كما يستعمل البرهان العقلي في بيان بطلان تعدد الآلهة، ويضرب الأمثال لتقريب المعاني المجردة إلى الأذهان، ويروي قصص الأنبياء والأمم السابقة للعبرة وتثبيت قلوب المؤمنين. ويجمع بين الترغيب في الجنة والترهيب من النار لتحريك الوجدان، ويأمر بمجادلة المخالفين بالأسلوب الحسن.\n▸ الدليل\n• ﴿أَفَلَا يَنظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ﴾ (الغاشية 17)\n• ﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾ (الأنبياء 22)\n• ﴿وَجَادِلْهُم بِالَّتِي هِيَ أَحْسَنُ﴾ (النحل 125)\n▸ للحفظ\n• القرآن يخاطب العقل (بالبرهان) والقلب (بالقصة والترغيب والترهيب) ليبلغ باليقين."},{"title":"موقف القرآن الكريم من العقل","content":"▸ الفكرة العامة\n• كرّم القرآن العقل وجعله مناط التكليف وأداة للتدبر وطلب الحقيقة.\n▸ مظاهر تكريم العقل\n• الدعوة إلى التفكر والتدبر والتعقل\n• ذم تعطيل العقل\n• جعل العقل شرطًا للتكليف\n• طلب البرهان من المدعي\n• تحريم ما يغيّب العقل\n▸ ما ينهى عنه القرآن\n• التقليد الأعمى للآباء\n• اتباع الظن والهوى\n• القول بغير علم\n▸ أهم المصطلحات\n• العقل\n• التفكر\n• التقليد\n• البرهان\n• مناط التكليف\n▸ شرح موسّع\n• تتكرر في القرآن عبارات مثل «أفلا يعقلون» و«أفلا يتفكرون» و«لقوم يعقلون»، وهي دعوة صريحة إلى استعمال العقل. وبما أن العقل مناط التكليف فلا يُكلَّف المجنون ولا غير المميز. وقد ذم القرآن المقلدين الذين يرفضون الحق لمجرد أنه خالف ما ورثوه عن آبائهم، ونهى عن اتباع الظن والقول بلا علم. وللعقل حدود: فهو لا يستقل بإدراك الغيبيات كحقيقة الروح وتفاصيل الآخرة، وهنا يأتي دور الوحي ليكمل العقل ولا يعارضه. ومن حفظ العقل تحريم الخمر والمخدرات.\n▸ الدليل\n• ﴿قُلْ هَاتُوا بُرْهَانَكُمْ إِن كُنتُمْ صَادِقِينَ﴾ (البقرة 111)\n• ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾ (الإسراء 36)\n• ﴿بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾ (البقرة 170) في ذم التقليد\n▸ للحفظ\n• العقل مناط التكليف، والإسلام يدعو إلى التفكر ويذم التقليد الأعمى واتباع الظن."},{"title":"الصحة النفسية والجسمية في القرآن الكريم","content":"▸ الفكرة العامة\n• اعتنى الإسلام بصحة الإنسان البدنية والنفسية معًا لأن سلامتهما شرط للعبادة والاستخلاف.\n▸ الصحة الجسمية\n• الاعتدال في الأكل والشرب\n• النظافة والطهارة\n• تحريم الخبائث والمسكرات\n• الأخذ بأسباب العلاج\n• النهي عن إلقاء النفس إلى التهلكة\n▸ الصحة النفسية\n• الإيمان والطمأنينة بذكر الله\n• الصبر والرضا بالقضاء\n• التوكل على الله\n• تجنب الحقد والحسد والقلق\n▸ أهم المصطلحات\n• الصحة\n• الطمأنينة\n• السكينة\n• الاعتدال\n▸ شرح موسّع\n• تظهر عناية الإسلام بالجسم في دعوته إلى الطهارة والوضوء، والاعتدال في المأكل والمشرب، وتحريم ما يضر كالخمر والميتة ولحم الخنزير والدم. كما أمر بالتداوي وجعل الصحة من أعظم النعم. وتظهر عنايته بالنفس في ربط القلب بالله، فالإيمان يمنح السكينة ويقلل القلق والخوف، والصبر يعين على الابتلاءات. ويؤكد الإسلام التوازن بين حاجات الروح والجسد دون إفراط ولا تفريط، فلا رهبانية تعطل الجسد ولا انغماس في الشهوات.\n▸ الدليل\n• ﴿وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا﴾ (الأعراف 31)\n• ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾ (البقرة 195)\n• ﴿أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾ (الرعد 28)\n• «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف» (رواه مسلم)\n▸ للحفظ\n• الإسلام يحفظ البدن بالاعتدال والطهارة والتداوي، ويحفظ النفس بالإيمان والذكر والصبر."},{"title":"القيم في القرآن الكريم","content":"▸ الفكرة العامة\n• مبادئ ومثل عليا توجه سلوك الفرد والمجتمع، جاء بها القرآن في منظومة متكاملة.\n▸ أنواع القيم\n• إيمانية: التوحيد والإخلاص والتقوى\n• أخلاقية: الصدق والأمانة والوفاء\n• اجتماعية: التعاون والعدل والتسامح\n• اقتصادية: الكسب الحلال والإنفاق\n▸ خصائص القيم القرآنية\n• ربانية المصدر\n• شمولية\n• ثابتة في أصولها\n• تحقق سعادة الدنيا والآخرة\n▸ أهم المصطلحات\n• القيم\n• الأخلاق\n• العدل\n• الأمانة\n• الإحسان\n▸ شرح موسّع\n• القيم في الإسلام ليست مجرد عادات اجتماعية متغيرة، بل هي أحكام وتوجيهات مصدرها الوحي، لذلك تتميز بالثبات والشمول. وتشمل علاقة الإنسان بربه (الإخلاص والتقوى)، وبنفسه (الصدق والعفة)، وبغيره (العدل والإحسان والرحمة)، وبالمال (الكسب الحلال وتجنب الغش). والقيم تحفظ تماسك المجتمع وتحمي أفراده من الفساد، ويعد الالتزام بها دليلًا على صدق الإيمان.\n▸ الدليل\n• ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾ (القلم 4)\n• ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَىٰ﴾ (النحل 90)\n• ﴿وَأَوْفُوا بِالْعَهْدِ إِنَّ الْعَهْدَ كَانَ مَسْئُولًا﴾ (الإسراء 34)\n▸ للحفظ\n• القيم القرآنية ربانية المصدر شاملة ثابتة، وتنظم علاقة الإنسان بربه ونفسه وغيره."},{"title":"المساواة أمام أحكام الشريعة الإسلامية","content":"▸ الفكرة العامة\n• الناس سواسية أمام أحكام الشريعة، لا فضل لأحد بنسبه أو ماله أو جاهه إلا بالتقوى.\n▸ أساس المساواة\n• وحدة الأصل الإنساني\n• العبودية لله وحده\n• التقوى هي معيار التفاضل\n▸ مجالات المساواة\n• أمام القضاء\n• في الحقوق والواجبات\n• في التكليف والجزاء\n• في الكرامة الإنسانية\n▸ أهم المصطلحات\n• المساواة\n• العدل\n• القضاء\n• التقوى\n▸ شرح موسّع\n• تقوم المساواة في الإسلام على وحدة الأصل: فالناس جميعًا من آدم، وآدم من تراب. ولذلك ألغى الإسلام الفوارق القائمة على اللون والجنس والنسب. وتظهر المساواة عمليًا في القضاء، فالشريف والضعيف أمام الحكم سواء، كما في قصة المرأة المخزومية التي سرقت فأراد بعض الناس الشفاعة لها لشرفها، فغضب النبي ﷺ وأكد تطبيق الحد على الجميع. والمساواة لا تعني التطابق في كل شيء، فقد يختلف توزيع بعض الأحكام بحسب طبيعة كل طرف ووظيفته مع حفظ العدل والكرامة للجميع.\n▸ الدليل\n• ﴿يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا ۚ إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ﴾ (الحجرات 13)\n• حديث المخزومية: «وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها» (متفق عليه)\n▸ للحفظ\n• الناس سواسية أمام الشريعة، والتفاضل بالتقوى والعمل الصالح فقط."},{"title":"العمل والإنتاج في الإسلام ومشكلة البطالة","content":"▸ مكانة العمل\n• عبادة إذا صحت النية\n• أمر به القرآن وحث عليه\n• الكسب الحلال فريضة\n• الاعتماد على النفس\n▸ ضوابط العمل\n• أن يكون مشروعًا (حلالًا)\n• الإتقان والإخلاص\n• عدم الإضرار بالغير\n• عدم إلهائه عن العبادات\n▸ أسباب البطالة\n• الكسل والتواكل\n• ضعف التكوين والمهارة\n• قلة فرص العمل\n• سوء توزيع الثروة\n▸ علاج الإسلام للبطالة\n• الحث على العمل وذم التسول\n• التكوين والتعلم\n• الزكاة والصدقات للعاجز\n• دور الدولة في توفير الفرص\n▸ شرح موسّع\n• يعد الإسلام العمل واجبًا ومصدر عزة، ويذم الكسل والاتكال على الآخرين، فالنبي ﷺ علّم الناس أن الكسب بجهد اليد خير من سؤال الناس. ومع ذلك لا يهمل الإسلام العاجز عن العمل، فجعل له حقًا في الزكاة. ولمعالجة البطالة جمع الإسلام بين تحفيز الفرد على السعي، وإلزام المجتمع والدولة بتوفير فرص العمل والتكوين وتشجيع الاستثمار وإحياء الأرض الموات، وتحقيق التكافل حتى لا يبقى محتاج بلا مورد.\n▸ الدليل\n• ﴿وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ﴾ (التوبة 105)\n• ﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ﴾ (الجمعة 10)\n• «ما أكل أحد طعامًا قط خيرًا من أن يأكل من عمل يده» (رواه البخاري)\n▸ للحفظ\n• العمل عبادة وواجب، والإسلام يعالج البطالة بتحفيز الفرد وتكافل المجتمع ودور الدولة."},{"title":"حقوق العمال وواجباتهم في الإسلام","content":"▸ حقوق العامل\n• أجر عادل في وقته\n• عدم تكليفه فوق طاقته\n• معاملته بكرامة واحترام\n• توفير ظروف عمل آمنة\n• الراحة والعناية به\n▸ واجبات العامل\n• إتقان العمل وإحسانه\n• الأمانة في أداء المهمة\n• الالتزام بالوقت والعقد\n• المحافظة على أدوات العمل\n▸ واجبات صاحب العمل\n• الوفاء بشروط العقد\n• عدم الظلم والغش\n• تحديد الأجر قبل العمل\n▸ أهم المصطلحات\n• الأجير\n• عقد الإجارة\n• الأجر\n• الإتقان\n• الأمانة\n▸ شرح موسّع\n• العلاقة بين العامل وصاحب العمل في الإسلام علاقة تعاقدية قائمة على العدل والأخوة، وتسمى «الإجارة». فللعامل حق في أجر معلوم يُدفع دون تأخير، وفي معاملة كريمة لا إذلال فيها، ولا يُكلَّف إلا بما يطيق. وعليه في المقابل أداء عمله بأمانة وإتقان. وصفتا القوة (الكفاءة) والأمانة (الخُلق) هما أساس اختيار العامل. وبهذا يتحقق التوازن بين مصلحة العامل ورب العمل ومصلحة المجتمع.\n▸ الدليل\n• ﴿إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ﴾ (القصص 26)\n• «أعطوا الأجير أجره قبل أن يجف عرقه» (رواه ابن ماجه)\n• «ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم» (متفق عليه)\n▸ للحفظ\n• حقوق العامل: أجر عادل ومعاملة كريمة. واجباته: الأمانة والإتقان. والمعيار: القوي الأمين."},{"title":"مشروعية الوقف","content":"▸ تعريف الوقف\n• حبس الأصل وتسبيل المنفعة: منع التصرف في العين الموقوفة وجعل ثمرتها في وجوه الخير.\n▸ أركان الوقف\n• الواقف\n• الموقوف (المال)\n• الموقوف عليه\n• الصيغة\n▸ أنواع الوقف\n• وقف خيري (عام)\n• وقف أهلي (ذري)\n• وقف مشترك\n▸ حكمته وآثاره\n• صدقة جارية يتصل أجرها\n• تحقيق التكافل الاجتماعي\n• تمويل التعليم والصحة والمساجد\n• حفظ المال من التبديد\n▸ شرح موسّع\n• الوقف من أعظم صور الإنفاق في سبيل الله لأن أصله يبقى وثمرته تتجدد. وقد ثبتت مشروعيته بالسنة، ومن أشهر أدلته وقف عمر بن الخطاب رضي الله عنه أرضه بخيبر بإرشاد النبي ﷺ. ويشترط في الواقف أن يكون أهلًا للتبرع، وفي الموقوف أن يكون مالًا مملوكًا ينتفع به مع بقاء عينه. وللوقف دور كبير في تاريخ الحضارة الإسلامية: المدارس والمستشفيات والمكتبات والعيون. وقد نظّمت الجزائر الأوقاف بقانون خاص (قانون الأوقاف 10-91).\n▸ الدليل\n• قال النبي ﷺ لعمر: «إن شئت حبست أصلها وتصدقت بها» (متفق عليه)\n• «إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له» (رواه مسلم)\n• ﴿لَن تَنَالُوا الْبِرَّ حَتَّىٰ تُنفِقُوا مِمَّا تُحِبُّونَ﴾ (آل عمران 92)\n▸ للحفظ\n• الوقف = حبس الأصل وتسبيل المنفعة، وهو صدقة جارية تعين على التكافل."},{"title":"الحريات الشخصية وعلاقتها بحقوق الآخرين","content":"▸ مفهوم الحرية\n• قدرة الإنسان على التصرف باختياره في حدود الشريعة دون إلحاق ضرر بغيره.\n▸ أنواع الحريات\n• حرية الاعتقاد\n• حرية الرأي والتعبير\n• حرية التملك والتصرف\n• حرية التنقل والعمل\n▸ ضوابط الحرية\n• عدم الإضرار بالغير\n• عدم مخالفة أحكام الشرع\n• احترام النظام العام والآداب\n• تحمل المسؤولية عن التصرفات\n▸ أهم المصطلحات\n• الحرية\n• الضرر\n• الحق\n• المسؤولية\n▸ شرح موسّع\n• كرّم الله الإنسان وأعطاه حرية الاختيار، لكنه قرن الحرية بالمسؤولية. فحرية الفرد تنتهي حيث تبدأ حقوق غيره، لذلك لا يجوز لأحد أن يستعمل حريته لإيذاء الآخرين أو الإضرار بالمجتمع. وقاعدة «لا ضرر ولا ضرار» تضبط كل تصرف. وفي مجال الاعتقاد قرر القرآن عدم الإكراه في الدين. ويُقدَّم الحق العام عند التعارض مع الحق الخاص حفاظًا على المصلحة العامة، كمنع الاحتكار والغش.\n▸ الدليل\n• ﴿لَا إِكْرَاهَ فِي الدِّينِ﴾ (البقرة 256)\n• ﴿وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ﴾ (الإسراء 70)\n• «لا ضرر ولا ضرار» (رواه ابن ماجه)\n• ﴿فَمَن شَاءَ فَلْيُؤْمِن وَمَن شَاءَ فَلْيَكْفُرْ﴾ (الكهف 29) في بيان حرية الاختيار مع تحمل المسؤولية\n▸ للحفظ\n• الحرية مكفولة بشرط عدم الإضرار بالغير وعدم مخالفة الشرع: «لا ضرر ولا ضرار»."},{"title":"حقوق الإنسان في مجال العلاقات العامة والتعامل الدولي","content":"▸ مبادئ التعامل الدولي\n• الوفاء بالعهود والمواثيق\n• السلم هو الأصل\n• حماية الرسل والمستأمنين\n• حسن معاملة الأسرى\n• التعاون على الخير\n▸ حقوق في العلاقات العامة\n• حفظ الكرامة الإنسانية\n• حرمة الدم والمال والعرض\n• حسن الجوار\n• العدل مع الجميع\n▸ أهم المصطلحات\n• حقوق الإنسان\n• المعاهدة\n• الأمان\n• التعايش\n• السلم\n▸ شرح موسّع\n• أقرّ الإسلام حقوق الإنسان قبل المواثيق الدولية الحديثة بقرون، وأساسها تكريم الإنسان لإنسانيته بغض النظر عن دينه أو جنسه. وفي العلاقات الدولية الأصل هو السلم والتعارف، والحرب استثناء لدفع العدوان. ويوجب الإسلام الوفاء بالعهود والمعاهدات، ويحمي من دخل بلاد المسلمين بأمان (المستأمن)، ويأمر بحسن معاملة الأسرى، ويحرّم قتل النساء والأطفال والشيوخ وغير المقاتلين، ويحث على التعاون الإنساني.\n▸ الدليل\n• ﴿وَإِن جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا﴾ (الأنفال 61)\n• ﴿وَإِنْ أَحَدٌ مِّنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللَّهِ﴾ (التوبة 6)\n• ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ﴾ (الممتحنة 8)\n▸ للحفظ\n• السلم هو الأصل، والوفاء بالعهود واجب، وكرامة الإنسان محفوظة في كل الأحوال."},{"title":"آثار التوحيد في حياة الفرد والمجتمع","content":"▸ معنى التوحيد\n• إفراد الله تعالى بالعبادة والربوبية والأسماء والصفات وعدم الإشراك به.\n▸ آثاره في الفرد\n• التحرر من الخوف والخرافة والعبودية للبشر\n• الطمأنينة والأمن النفسي\n• الاستقامة والإخلاص\n• الشعور بالمسؤولية ومراقبة الله\n▸ آثاره في المجتمع\n• وحدة الأمة وتماسكها\n• المساواة بين الناس\n• قيام العدل والتعاون\n• محاربة الفساد والظلم\n▸ أهم المصطلحات\n• التوحيد\n• الشرك\n• الإخلاص\n• التقوى\n▸ شرح موسّع\n• التوحيد هو أساس العقيدة الإسلامية، وله أثر عميق في بناء الإنسان والمجتمع. فالموحد لا يخاف إلا من الله ولا يرجو سواه، فيتحرر من الخوف من البشر ومن الخرافات والسحر والتنجيم. ويمنحه الإيمان بالله سكينة في الأزمات. وعلى مستوى المجتمع يوحد التوحيد الصفوف لأن الجميع عباد لله، فلا طبقية ولا تمييز، ويقوي الشعور بالمسؤولية، فيعمل الفرد لمصلحة مجتمعه ويراقب الله في السر والعلن.\n▸ الدليل\n• ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُم مُّهْتَدُونَ﴾ (الأنعام 82)\n• ﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾ (الأحقاف 13)\n▸ للحفظ\n• التوحيد يحرر الفرد من الخوف والخرافة، ويوحد المجتمع على العدل والمساواة."},{"title":"الإسلام والرسالات السماوية السابقة","content":"▸ وحدة الرسالات\n• مصدرها واحد هو الله\n• جوهرها واحد: التوحيد\n• الأنبياء إخوة في الدعوة\n• الإيمان بجميع الرسل والكتب واجب\n▸ موقف الإسلام منها\n• تصديق أصل الرسالات السابقة\n• القرآن مهيمن على الكتب السابقة\n• تحريف ما حُرّف من الكتب\n• الإسلام خاتم الرسالات وناسخها\n▸ أهم الكتب والرسل\n• التوراة (موسى)\n• الإنجيل (عيسى)\n• الزبور (داود)\n• القرآن (محمد ﷺ)\n▸ أهم المصطلحات\n• الرسالة\n• الوحي\n• التحريف\n• الهيمنة\n• خاتم النبيين\n▸ شرح موسّع\n• يؤمن المسلم بجميع الأنبياء والكتب المنزلة، ولا يفرق بين أحد من الرسل، فمصدر الرسالات واحد وأصلها دعوة الناس إلى عبادة الله وحده. وقد تعرضت الكتب السابقة للتحريف والتبديل، فجاء القرآن مصدّقًا لما صح فيها ومهيمنًا عليها، أي حاكمًا ومبينًا لما حُرّف. وجاءت الشريعة الإسلامية خاتمة وشاملة صالحة لكل زمان ومكان، وبها كمُل الدين. ومن هذا الموقف ينبع احترام أهل الكتاب وحسن التعامل معهم.\n▸ الدليل\n• ﴿آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ﴾ (البقرة 285)\n• ﴿وَأَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾ (المائدة 48)\n▸ للحفظ\n• الرسالات مصدرها واحد وجوهرها التوحيد، والإسلام مصدّق لها ومهيمن عليها وخاتم لها."},{"title":"مقاصد الشريعة الإسلامية","content":"▸ تعريفها\n• الغايات والحكم التي قصدها الشارع من تشريع الأحكام لتحقيق مصالح العباد في الدنيا والآخرة.\n▸ الضروريات الخمس\n• حفظ الدين\n• حفظ النفس\n• حفظ العقل\n• حفظ النسل (العرض)\n• حفظ المال\n▸ مراتب المقاصد\n• الضروريات: لا تقوم الحياة بدونها\n• الحاجيات: رفع الحرج والمشقة\n• التحسينيات: مكارم الأخلاق والكمال\n▸ أهميتها\n• فهم النصوص وتطبيقها\n• الاجتهاد في المستجدات\n• الترجيح بين الأدلة\n▸ شرح موسّع\n• تقوم الشريعة على قاعدة جلب المصالح ودرء المفاسد. فكل حكم شرعي وراءه مقصد، وأعلى المقاصد الضروريات الخمس. مثال: تشريع القصاص يحفظ النفس، وتحريم الخمر يحفظ العقل، وتحريم الزنا يحفظ النسل، وتحريم السرقة والربا يحفظ المال، والجهاد المشروع ودعوة الناس تحفظ الدين. وأما الحاجيات فمثل الرخص في السفر والمرض، والتحسينيات كآداب الأكل والطهارة. وقد اهتم العلماء بهذا العلم، ومنهم الشاطبي في كتابه «الموافقات».\n▸ الدليل\n• ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ﴾ (الأنبياء 107)\n• ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ يَا أُولِي الْأَلْبَابِ﴾ (البقرة 179) مثال لمقصد حفظ النفس\n▸ للحفظ\n• الضروريات الخمس: الدين، النفس، العقل، النسل، المال. والقاعدة: جلب المصالح ودرء المفاسد."},{"title":"الإجماع والقياس والمصالح المرسلة","content":"▸ الإجماع\n• اتفاق مجتهدي الأمة بعد وفاة النبي ﷺ في عصر على حكم شرعي\n• حجة شرعية ملزمة\n• مثاله: توريث الجدة السدس\n▸ القياس\n• إلحاق فرع بأصل في حكم لعلة مشتركة\n• أركانه: الأصل، الفرع، العلة، الحكم\n• مثاله: المخدرات على الخمر بعلة الإسكار\n▸ المصالح المرسلة\n• مصلحة لم يرد نص بإلغائها ولا باعتبارها\n• شرطها: ملاءمة مقاصد الشرع\n• مثالها: توثيق العقود وجمع المصحف\n▸ أهم المصطلحات\n• الإجماع\n• القياس\n• العلة\n• الاجتهاد\n• المصلحة\n▸ شرح موسّع\n• بعد الكتاب والسنة تأتي أدلة اجتهادية يعتمد عليها الفقهاء في استخراج الأحكام للمسائل الجديدة. فالإجماع يمثل اتفاق العلماء المجتهدين، وهو دليل قطعي أو ظني بحسب نوعه. والقياس هو إلحاق مسألة جديدة لا نص فيها بمسألة منصوص على حكمها لاشتراكهما في العلة، كتحريم كل مسكر قياسًا على الخمر. أما المصالح المرسلة فهي الأمور التي تحقق نفعًا للناس ولم يرد فيها نص بالاعتبار أو الإلغاء، كاعتماد السجلات الرسمية وتنظيم المرور، بشرط ألا تخالف نصًا شرعيًا.\n▸ الدليل\n• من أدلة حجية الإجماع: ﴿وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّىٰ﴾ (النساء 115)\n• من أدلة القياس الاعتبار: ﴿فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ﴾ (الحشر 2)\n▸ للحفظ\n• الإجماع = اتفاق المجتهدين، القياس = إلحاق فرع بأصل لعلة جامعة، المصلحة المرسلة = مصلحة لا نص فيها."},{"title":"النسب والتبني والكفالة","content":"▸ النسب\n• انتماء الولد إلى أبيه وأمه\n• أسبابه: الزواج الصحيح، الإقرار، البينة\n• تترتب عليه حقوق: النفقة والإرث والولاية\n▸ التبني\n• نسبة ولد معروف النسب إلى غير أبيه\n• محرّم في الإسلام\n• لا تترتب عليه أحكام البنوة\n▸ الكفالة\n• التزام برعاية طفل والإنفاق عليه وتربيته\n• مشروعة ومرغّب فيها\n• لا يُنسب المكفول إلى الكافل بالبنوة\n• ينظمها قانون الأسرة الجزائري\n▸ أهم المصطلحات\n• النسب\n• التبني\n• الكفالة\n• اليتيم\n• مجهول النسب\n▸ شرح موسّع\n• حفظ النسب من مقاصد الشريعة الكبرى، لذلك أبطل الإسلام التبني الذي كان معروفًا في الجاهلية لأنه يخلط الأنساب ويمنح الدعيّ حقوق الابن الحقيقي من إرث ومحرمية. وفي المقابل شجع على كفالة اليتيم ومجهول النسب برعايته ماديًا ومعنويًا دون أن يُنسب إليه، فيحفظ للطفل حقه في الحياة الكريمة ويحفظ للأنساب نقاءها. وللمكفول أن يحمل اسمًا مناسبًا، ويجوز للكافل أن يوصي له في حدود الثلث.\n▸ الدليل\n• ﴿وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ﴾ (الأحزاب 4)\n• ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِندَ اللَّهِ﴾ (الأحزاب 5)\n• «أنا وكافل اليتيم في الجنة هكذا» وأشار بالسبابة والوسطى (رواه البخاري)\n▸ للحفظ\n• التبني محرّم لأنه يخلط الأنساب، والكفالة مشروعة ومرغّب فيها دون نسبة الولد للكافل."},{"title":"الربا ومشكلة الفائدة","content":"▸ تعريف الربا\n• الزيادة المشروطة في القرض، أو الزيادة في بيع بعض الأموال بجنسها.\n▸ أنواع الربا\n• ربا النسيئة: زيادة مقابل التأجيل\n• ربا الفضل: زيادة في بيع الجنس بجنسه\n▸ حكمه وحكمة تحريمه\n• محرّم بنص القرآن والسنة\n• استغلال حاجة المحتاج\n• يؤدي إلى تراكم الديون والتضخم\n• يفسد العدالة بين الدائن والمدين\n▸ الفائدة والبدائل\n• الفائدة المصرفية على القروض: رأي المجامع الفقهية أنها من الربا\n• البدائل: المرابحة، المشاركة، المضاربة، القرض الحسن\n• البنوك والنوافذ الإسلامية\n▸ شرح موسّع\n• الربا من كبائر الذنوب، وقد حرمه القرآن بشدة وأعلن الحرب على المصرّين عليه. وأشهر صوره ربا الجاهلية: يحل الدين على المدين فيقول له الدائن: أتقضي أم تُربي؟ فيزيد الدين على المدين مع الأجل. ويرى جمهور الفقهاء والمجامع الفقهية المعاصرة أن الفائدة التي تأخذها البنوك التقليدية على القروض داخلة في الربا لأنها زيادة مشروطة على القرض. وقد ظهرت المصارف الإسلامية لتقديم بدائل تقوم على المشاركة في الربح والخسارة وعلى البيع الحقيقي للسلع.\n▸ الدليل\n• ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ (البقرة 275)\n• ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا﴾ (البقرة 278)\n• «لعن رسول الله ﷺ آكل الربا وموكله وكاتبه وشاهديه، وقال: هم سواء» (رواه مسلم)\n▸ للحفظ\n• الربا = زيادة مشروطة محرمة، وأنواعه: النسيئة والفضل، وبدائله: المرابحة والمشاركة والمضاربة."},{"title":"الوصية ومدخل إلى علم الميراث","content":"▸ الوصية\n• تمليك مضاف إلى ما بعد الموت بطريق التبرع\n• تجوز في حدود ثلث التركة\n• لا وصية لوارث إلا بإجازة الورثة\n• أركانها: الموصي، الموصى له، الموصى به، الصيغة\n▸ الميراث (الفرائض)\n• انتقال أموال المتوفى إلى ورثته الشرعيين\n• أركانه: المورِّث، الوارث، الحق الموروث\n▸ أسباب الإرث\n• الزوجية\n• القرابة (النسب)\n• الولاء\n▸ موانع الإرث\n• القتل العمد\n• اختلاف الدين\n▸ شرح موسّع\n• قبل تقسيم التركة تتعلق بها حقوق مرتبة: أولًا مؤونة تجهيز الميت ودفنه، ثم سداد ديونه، ثم تنفيذ وصيته في حدود الثلث، ثم تقسيم الباقي على الورثة حسب الأنصبة الشرعية التي حددها القرآن (الفروض المقدرة: النصف والربع والثمن والثلثان والثلث والسدس). وقد عُرف علم الميراث بعلم الفرائض، وحث النبي ﷺ على تعلمه. وحكمة الوصية أن تمكّن الإنسان من البر بمن لا يرث، كالأقارب المحتاجين والجهات الخيرية.\n▸ الدليل\n• ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ﴾ (النساء 11)\n• «إن الله قد أعطى كل ذي حق حقه، فلا وصية لوارث» (رواه أبو داود والترمذي)\n• قال ﷺ لسعد: «الثلث، والثلث كثير» (متفق عليه)\n▸ للحفظ\n• ترتيب الحقوق في التركة: التجهيز، الديون، الوصية (≤ الثلث)، ثم الميراث."},{"title":"من المعاملات المالية الجائزة: المرابحة والتقسيط والصرف","content":"▸ المرابحة\n• بيع السلعة بثمنها الأول مع ربح معلوم\n• يشترط علم المشتري بالثمن والربح\n• ملكية البائع للسلعة قبل بيعها\n▸ التقسيط\n• بيع بثمن مؤجل يُسدَّد على أقساط\n• جائز بشرط تحديد الثمن عند العقد\n• لا تجوز زيادة الثمن عند التأخر في السداد\n▸ الصرف\n• بيع نقد بنقد (عملة بعملة)\n• التقابض في مجلس العقد\n• التماثل إذا اتحد الجنس\n▸ أهم المصطلحات\n• البيع\n• الثمن المؤجل\n• التقابض\n• رأس المال\n• الربح\n▸ شرح موسّع\n• هذه المعاملات من صور البيع المشروع التي تحقق مصلحة الطرفين بعيدًا عن الربا والغرر. فالمرابحة صيغة تعتمدها البنوك الإسلامية: تشتري السلعة ثم تبيعها للعميل بثمن الشراء مع ربح متفق عليه. والتقسيط يتيح للمشتري الدفع على مراحل، والثمن المؤجل قد يزيد عن الثمن الحاضر إن حُدد عند العقد وانتهى المجلس على ثمن واحد. أما إن اشترطت زيادة عند التأخر عن الدفع فهي ربا محرم. والصرف يقتضي التقابض الفوري، فلا يجوز تأجيل أحد البدلين.\n▸ الدليل\n• قال النبي ﷺ: «الذهب بالذهب، والفضة بالفضة ... مثلًا بمثل، سواءً بسواء، يدًا بيد، فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يدًا بيد» (رواه مسلم)\n• ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ﴾ (البقرة 275)\n▸ للحفظ\n• المرابحة: ثمن + ربح معلوم. التقسيط: ثمن محدد مؤجل. الصرف: تقابض فوري في المجلس."},{"title":"الشركة في الفقه الإسلامي","content":"▸ تعريفها\n• عقد بين اثنين أو أكثر على الاشتراك في رأس المال أو العمل لتحقيق الربح.\n▸ أنواعها\n• شركة الأموال (العنان)\n• شركة الأعمال (الأبدان)\n• شركة الوجوه\n• المضاربة\n▸ أركانها\n• العاقدان (الشريكان)\n• الصيغة (الإيجاب والقبول)\n• المحل (المال أو العمل)\n▸ أحكام الربح والخسارة\n• الربح حسب النسب المتفق عليها\n• الخسارة بقدر رأس المال\n• الأمانة في تسيير الشركة\n▸ شرح موسّع\n• تعد الشركة من أهم أدوات الاستثمار المشروع، لأنها تجمع الأموال والخبرات وتقسم الربح والخسارة بالعدل. فشركة العنان تقوم على أن يساهم الشركاء بأموال ويعملون فيها، وشركة الأبدان على اشتراك أصحاب مهنة بجهودهم، والمضاربة أن يقدم أحد الطرفين المال والآخر العمل، فيقتسمان الربح بنسبة شائعة يتفقان عليها، ويتحمل صاحب المال الخسارة المالية ويخسر المضارب جهده. ويجب على الشريك الأمانة والوفاء بالاتفاق وتجنب الغش.\n▸ الدليل\n• ﴿وَإِنَّ كَثِيرًا مِّنَ الْخُلَطَاءِ لَيَبْغِي بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ (ص 24)\n• ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ﴾ (المائدة 1)\n▸ للحفظ\n• الشركة: اشتراك في المال أو العمل. الربح حسب الاتفاق، والخسارة بقدر رأس المال."},{"title":"تحليل وثيقة خطبة الرسول ﷺ في حجة الوداع","content":"▸ الظروف\n• السنة العاشرة للهجرة\n• في عرفة بمناسبة حجة الوداع\n• أمام جموع المسلمين\n▸ أهم ما تضمنته\n• حرمة الدماء والأموال والأعراض\n• وضع ربا الجاهلية ودماء الجاهلية\n• الوصية بالنساء خيرًا\n• المساواة: لا فضل لعربي على أعجمي إلا بالتقوى\n• التمسك بكتاب الله وسنة نبيه\n▸ القيم المستفادة\n• حفظ حقوق الإنسان\n• العدالة الاجتماعية والاقتصادية\n• وحدة المسلمين\n▸ أهم المصطلحات\n• حجة الوداع\n• الدماء\n• الأموال\n• الأعراض\n• الأمانة\n▸ شرح موسّع\n• تعد خطبة الوداع وثيقة جامعة لمبادئ الإسلام الكبرى ودستورًا للعلاقات الإنسانية. أعلن فيها النبي ﷺ أن دماء الناس وأموالهم وأعراضهم محرمة كحرمة يوم عرفة وشهر ذي الحجة والبلد الحرام، وألغى مظالم الجاهلية من الثأر والربا، وأوصى بالنساء، وقرر المساواة بين الناس. وختمها بالتأكيد على الاعتصام بكتاب الله وبتبليغ الرسالة: «ألا هل بلغت؟». وتظهر فيها منهجية التشريع القائمة على حفظ الضروريات الخمس.\n▸ الدليل\n• «إن دماءكم وأموالكم وأعراضكم عليكم حرام كحرمة يومكم هذا في شهركم هذا في بلدكم هذا» (رواه مسلم)\n• «وربا الجاهلية موضوع» · «فاتقوا الله في النساء»\n• «لا فضل لعربي على أعجمي ولا لعجمي على عربي إلا بالتقوى» (رواه أحمد)\n▸ للحفظ\n• الخطبة تقرر: حرمة الدماء والأموال والأعراض، إلغاء الربا والثأر، المساواة، والتمسك بالقرآن."},{"title":"العلاقات الاجتماعية بين المسلمين وغيرهم","content":"▸ أساس العلاقة\n• البر والقسط والعدل\n• التعارف والتعايش\n• الكرامة الإنسانية للجميع\n▸ مظاهر حسن التعامل\n• حسن الجوار\n• التعامل التجاري المشروع\n• جواز أكل طعام أهل الكتاب\n• الحوار بالتي هي أحسن\n• حماية أموالهم وأعراضهم\n▸ حدود العلاقة\n• عدم الموالاة فيما يضر بالدين\n• عدم التنازل عن العقيدة\n▸ نماذج تطبيقية\n• صحيفة المدينة\n• معاملة النبي ﷺ لأهل الكتاب\n• عهد عمر لأهل إيلياء\n▸ شرح موسّع\n• علاقة المسلمين بغيرهم قائمة على العدل والإحسان ما لم يكن اعتداء. وتظهر في تاريخ المسلمين نماذج حية، كصحيفة المدينة التي نظمت العيش المشترك بين المسلمين واليهود وقبائل المدينة، وضمنت حرية العقيدة وحق الدفاع المشترك عن المدينة. وأباح الإسلام التعامل التجاري مع غير المسلمين، وأكل طعام أهل الكتاب، والزواج من نسائهم. وفي المقابل يحافظ المسلم على هويته وعقيدته دون إكراه لغيره.\n▸ الدليل\n• ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَارِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ﴾ (الممتحنة 8)\n• ﴿وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَىٰ أَلَّا تَعْدِلُوا﴾ (المائدة 8)\n• «من قتل معاهدًا لم يرح رائحة الجنة» (رواه البخاري)\n▸ للحفظ\n• العلاقة مع غير المسلمين: بر وقسط وعدل وحوار، مع حفظ الهوية الدينية دون إكراه."}];
  var eco=[{"title":"النقود والكتلة النقدية","content":"▸ تعريف النقود\n• كل شيء يحظى بقبول عام في التعامل ويستعمل وسيطًا للتبادل ومقياسًا لقيم السلع ووسيلة لحفظها\n▸ وظائف النقود\n• وسيط للتبادل\n• مقياس للقيمة\n• مستودع للقيمة\n• وسيلة للدفع المؤجل\n▸ أشكال النقود\n• نقدية (سلعية)\n• معدنية\n• ورقية\n• كتابية\n• إلكترونية\n▸ أهميتها\n• تسهيل المبادلات\n• تنشيط الإنتاج وتنويع الاستهلاك\n• تسهيل الادخار والاستثمار\n• المساهمة في تطور الاقتصاد\n▸ إصدار النقود\n• يتولى بنك الجزائر إصدار النقد (الأوراق النقدية والقطع المعدنية) وفق الإطار القانوني\n▸ أهم المصطلحات\n• النقود\n• الكتلة النقدية\n• بنك الجزائر\n• التضخم\n▸ للحفظ\n• وظائف النقود الأربع: وسيط للتبادل، مقياس للقيمة، مستودع للقيمة، وسيلة للدفع المؤجل."},{"title":"السوق والأسعار","content":"▸ تعريف السوق\n• مكان أو إطار يتم فيه تبادل السلع والخدمات بين البائعين والمشترين\n▸ أنواع السوق\n• تنافسي\n• احتكاري\n• احتكار القلة\n• مختلط\n▸ العرض والطلب\n• العرض: الكمية المعروضة من السلعة\n• الطلب: الكمية المطلوبة من السلعة\n• السعر والكمية المطلوبة: علاقة عكسية\n• السعر والكمية المعروضة: علاقة طردية\n▸ سعر التوازن\n• يتحدد عند تساوي العرض والطلب\n▸ مرونة الطلب\n• مدى استجابة الكمية المطلوبة لتغير السعر (مرنة أو غير مرنة)\n▸ أهم المصطلحات\n• الطلب\n• العرض\n• السوق\n• سعر التوازن\n• مرونة الطلب\n▸ للحفظ\n• السعر يرتفع ← الكمية المطلوبة تنخفض (عكسية)، والكمية المعروضة ترتفع (طردية)."},{"title":"النظام المصرفي","content":"▸ تعريف النظام المصرفي\n• مجموعة البنوك والمؤسسات المالية التي تتولى الوساطة المالية في الاقتصاد\n▸ أنواع البنوك\n• بنك الجزائر\n• بنوك تجارية\n• بنوك خاصة\n• بنوك متخصصة\n▸ البنك المركزي\n• أعلى سلطة نقدية ومصرفية في الدولة (بنك الجزائر)\n▸ وظائف البنوك\n• استقبال الودائع\n• منح القروض\n• تسهيل المدفوعات\n• تقديم خدمات متنوعة\n▸ البنوك التجارية\n• تجمع الودائع وتمنح القروض وتقدم خدمات الدفع\n▸ أهم المصطلحات\n• بنك الجزائر\n• بنك تجاري\n• ودائع\n• قروض\n• سيولة\n▸ للحفظ\n• بنك الجزائر = بنك البنوك وهو الذي يصدر النقد، والبنوك التجارية تتعامل مع الأفراد والمؤسسات."},{"title":"الصرف","content":"▸ تعريف الصرف\n• تبادل عملة بأخرى أو تحويل عملة وطنية إلى عملة أجنبية\n▸ أنواع سوق الصرف\n• سوق رسمي\n• سوق موازية\n• سوق دولية\n▸ أسعار الصرف\n• سعر الصرف الرسمي\n• سعر الصرف الحقيقي\n• سعر الصرف الفعلي\n▸ العوامل المؤثرة\n• التضخم\n• الميزان التجاري\n• السياسات الاقتصادية\n▸ أهمية الصرف\n• دعم التجارة الخارجية\n• استقرار الأسعار\n• جذب الاستثمارات\n▸ أهم المصطلحات\n• سعر الصرف\n• سوق الصرف\n• العملة\n• توازن العملة\n▸ للحفظ\n• الصرف الرسمي يتم عبر البنوك والمؤسسات المعتمدة، أما الموازي فخارج القنوات الرسمية."},{"title":"التجارة الخارجية","content":"▸ تعريفها\n• تبادل السلع والخدمات بين الدول\n▸ أنواعها\n• صادرات\n• واردات\n• إعادة التصدير\n• إعادة الاستيراد\n▸ أسبابها\n• الفائض الإنتاجي\n• تنوع الحاجات\n• التخصص وتقسيم العمل\n▸ وسائل التسوية\n• النقد\n• التحويل البنكي\n• الاعتمادات المستندية\n▸ آثارها\n• زيادة النمو الاقتصادي\n• توفير السلع\n• خلق مناصب الشغل\n▸ أهم المصطلحات\n• الصادرات\n• الواردات\n• ميزان التجارة\n• الاعتماد المستندي\n▸ للحفظ\n• الميزان التجاري = الصادرات − الواردات."},{"title":"البطالة","content":"▸ تعريفها\n• عدم القدرة على الحصول على عمل رغم الرغبة فيه والقدرة عليه\n▸ أنواعها\n• هيكلية\n• دورية\n• موسمية\n• احتكاكية\n• مقنعة\n▸ أسبابها\n• نمو السكان\n• التطور التكنولوجي\n• ضعف الاستثمار\n• الأزمات الاقتصادية\n▸ آثارها\n• اجتماعية\n• اقتصادية\n• نفسية\n▸ طرق معالجتها\n• تشجيع الاستثمار\n• دعم المؤسسات الصغيرة\n• تطوير التكوين المهني\n▸ أهم المصطلحات\n• معدل البطالة\n• البطّال\n• العمالة\n• التشغيل\n▸ للحفظ\n• معدل البطالة = (عدد البطالين ÷ السكان النشيطين) × 100."},{"title":"الموارد البشرية","content":"▸ تعريفها\n• مجموعة الأفراد المؤهلين الذين يساهمون في تحقيق أهداف المؤسسة\n▸ تسييرها\n• التكوين\n• التوظيف\n• التقييم\n• التحفيز\n▸ تقييمها\n• تحديد الكفاءات\n• قياس الأداء\n• تطوير المهارات\n▸ أهميتها\n• تحقيق الأهداف\n• زيادة الإنتاجية\n• تحسين الأداء\n▸ أهم المصطلحات\n• المورد البشري\n• التكوين\n• التحفيز\n• التقييم\n▸ للحفظ\n• التسيير: توظيف ← تكوين ← تقييم ← تحفيز."},{"title":"الإنتاج والإنتاجية","content":"▸ تعريفه\n• تحويل الموارد إلى سلع وخدمات تلبي الحاجات\n▸ أنواعه\n• الإنتاج المادي\n• الإنتاج الخدمي\n• الإنتاج الفلاحي\n▸ عناصره\n• العمل\n• رأس المال\n• المواد الأولية\n• التكنولوجيا\n▸ أهدافه\n• زيادة الثروة\n• تحسين الجودة\n• خفض التكاليف\n▸ تنظيم العملية الإنتاجية\n• التخطيط\n• التنفيذ\n• المراقبة\n• التقييم\n▸ أهم المصطلحات\n• الإنتاج\n• عوامل الإنتاج\n• العملية الإنتاجية\n▸ للحفظ\n• الإنتاجية = المخرجات ÷ المدخلات."},{"title":"التقييس والجودة","content":"▸ تعريفه\n• وضع معايير ومواصفات موحدة للمنتجات والخدمات\n▸ أهدافه\n• تحسين الجودة\n• تسهيل التبادل\n• حماية المستهلك\n▸ أنواعه\n• تقييس وطني\n• تقييس إقليمي\n• تقييس دولي\n▸ أهميته\n• رفع القدرة التنافسية\n• تحسين السلامة\n• دعم الصادرات\n▸ أدواته\n• المواصفات\n• المقاييس\n• الاختبارات\n• الاعتماد\n▸ أهم المصطلحات\n• التقييس\n• المواصفة\n• المقياس\n• الجودة\n▸ للحفظ\n• التقييس يخدم ثلاثة أطراف: المؤسسة (جودة)، المستهلك (حماية)، الاقتصاد (تبادل)."},{"title":"التمويل","content":"▸ تعريفه\n• توفير الموارد المالية اللازمة لاستغلالها في تسيير واستثمارات المؤسسة وتطويرها\n▸ مصادر التمويل\n• داخلية (الذاتية)\n• خارجية (قروض، إصدار أسهم)\n▸ احتياجات المؤسسة\n• الاستثمار\n• التسيير\n• التجديد\n▸ أشكال التمويل\n• قصير الأجل\n• متوسط الأجل\n• طويل الأجل\n▸ أهدافه\n• بقاء المؤسسة\n• توسعها ونموها\n• تحقيق الربحية\n▸ أهم المصطلحات\n• التمويل\n• مصادر التمويل\n• الاحتياجات المالية\n• القروض\n▸ للحفظ\n• التمويل الذاتي = مصدر داخلي، القروض والأسهم = مصادر خارجية."},{"title":"الاتصال داخل المؤسسة","content":"▸ تعريفه\n• تبادل المعلومات والأفكار بين الأفراد أو الجماعات\n▸ أنواعه\n• رسمي\n• غير رسمي\n• خارجي\n• داخلي\n▸ وسائله\n• شفهي\n• كتابي\n• إلكتروني\n• سمعي بصري\n▸ معوقاته\n• لغة\n• نفسية\n• تنظيمية\n• بيئية\n▸ أهميته\n• تحقيق الفهم المشترك\n• تحسين اتخاذ القرار\n• دعم العلاقات\n▸ أهم المصطلحات\n• المرسل\n• الرسالة\n• المستقبل\n• التغذية الراجعة\n• المعوق\n▸ للحفظ\n• عناصر الاتصال: مرسل ← رسالة ← وسيلة ← مستقبل ← تغذية راجعة."},{"title":"القيادة والتحفيز","content":"▸ تعريفها\n• تأثير القائد في الآخرين لتوجيههم نحو تحقيق أهداف المؤسسة\n▸ أنماط القيادة\n• السلطوي\n• الديمقراطي\n• التشاركي\n• الحر\n▸ التحفيز\n• مادي\n• معنوي\n• فردي\n• جماعي\n▸ نظريات التحفيز\n• ماسلو (هرم الحاجات)\n• هرزبرغ (نظرية العاملين)\n▸ أهميتها\n• زيادة الإنتاجية\n• تحقيق التوافق\n• تحسين المناخ التنظيمي\n▸ أهم المصطلحات\n• القيادة\n• التحفيز\n• الدافعية\n• الأنماط\n▸ للحفظ\n• ماسلو: فيزيولوجية ← أمان ← اجتماعية ← تقدير ← تحقيق الذات."},{"title":"الرقابة والتقييم","content":"▸ تعريفها\n• مقارنة النتائج بالأهداف وتصحيح الانحرافات\n▸ أنواعها\n• داخلية\n• خارجية\n• قبلية\n• بعدية\n▸ مراحلها\n• تحديد المعايير\n• قياس الأداء\n• مقارنة النتائج بالمعايير\n• اتخاذ الإجراءات\n▸ أهدافها\n• ضمان الجودة\n• ترشيد الموارد\n• تحقيق الأهداف\n▸ أهميتها\n• تحسين الأداء\n• تقليل المخاطر\n• دعم اتخاذ القرار\n▸ أهم المصطلحات\n• المعايير\n• الرقابة\n• الانحرافات\n• التصحيح\n▸ للحفظ\n• الانحراف = النتائج الفعلية − الأهداف المخططة."}];
  var sci=[{"title":"وسائل القرآن الكريم في تثبيت العقيدة الإسلامية","content":"▸ الفكرة العامة\n• القرآن يخاطب العقل والوجدان بأساليب متنوعة، ويقدم الحجة والبرهان.\n▸ أهم الوسائل\n• لفت النظر إلى الكون والتأمل فيه\n• مخاطبة العقل وإقامة الحجة والبرهان\n• ضرب الأمثال\n• القصص القرآني\n• الترغيب والترهيب\n• الجدال بالتي هي أحسن\n▸ الهدف منها\n• الوصول إلى اليقين لا التقليد\n• تثبيت الإيمان بالله وحده\n• إبطال الشرك والخرافة\n▸ أهم المصطلحات\n• العقيدة\n• الحجة والبرهان\n• الاستدلال\n• التأمل في الكون\n▸ شرح موسّع\n• من أبرز وسائل القرآن دعوته إلى النظر في الكون: السماء والأرض والإبل والجبال، لأن في إتقان الخلق دليلًا على وجود الخالق ووحدانيته. كما يستعمل البرهان العقلي في بيان بطلان تعدد الآلهة، ويضرب الأمثال لتقريب المعاني المجردة إلى الأذهان، ويروي قصص الأنبياء والأمم السابقة للعبرة وتثبيت قلوب المؤمنين. ويجمع بين الترغيب في الجنة والترهيب من النار لتحريك الوجدان، ويأمر بمجادلة المخالفين بالأسلوب الحسن.\n▸ الدليل\n• ﴿أَفَلَا يَنظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ﴾ (الغاشية 17)\n• ﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾ (الأنبياء 22)\n• ﴿وَجَادِلْهُم بِالَّتِي هِيَ أَحْسَنُ﴾ (النحل 125)\n▸ للحفظ\n• القرآن يخاطب العقل (بالبرهان) والقلب (بالقصة والترغيب والترهيب) ليبلغ باليقين.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"موقف القرآن الكريم من العقل","content":"▸ الفكرة العامة\n• كرّم القرآن العقل وجعله مناط التكليف وأداة للتدبر وطلب الحقيقة.\n▸ مظاهر تكريم العقل\n• الدعوة إلى التفكر والتدبر والتعقل\n• ذم تعطيل العقل\n• جعل العقل شرطًا للتكليف\n• طلب البرهان من المدعي\n• تحريم ما يغيّب العقل\n▸ ما ينهى عنه القرآن\n• التقليد الأعمى للآباء\n• اتباع الظن والهوى\n• القول بغير علم\n▸ أهم المصطلحات\n• العقل\n• التفكر\n• التقليد\n• البرهان\n• مناط التكليف\n▸ شرح موسّع\n• تتكرر في القرآن عبارات مثل «أفلا يعقلون» و«أفلا يتفكرون» و«لقوم يعقلون»، وهي دعوة صريحة إلى استعمال العقل. وبما أن العقل مناط التكليف فلا يُكلَّف المجنون ولا غير المميز. وقد ذم القرآن المقلدين الذين يرفضون الحق لمجرد أنه خالف ما ورثوه عن آبائهم، ونهى عن اتباع الظن والقول بلا علم. وللعقل حدود: فهو لا يستقل بإدراك الغيبيات كحقيقة الروح وتفاصيل الآخرة، وهنا يأتي دور الوحي ليكمل العقل ولا يعارضه. ومن حفظ العقل تحريم الخمر والمخدرات.\n▸ الدليل\n• ﴿قُلْ هَاتُوا بُرْهَانَكُمْ إِن كُنتُمْ صَادِقِينَ﴾ (البقرة 111)\n• ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾ (الإسراء 36)\n• ﴿بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾ (البقرة 170) في ذم التقليد\n▸ للحفظ\n• العقل مناط التكليف، والإسلام يدعو إلى التفكر ويذم التقليد الأعمى واتباع الظن.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الصحة النفسية والجسمية في القرآن الكريم","content":"▸ الفكرة العامة\n• اعتنى الإسلام بصحة الإنسان البدنية والنفسية معًا لأن سلامتهما شرط للعبادة والاستخلاف.\n▸ الصحة الجسمية\n• الاعتدال في الأكل والشرب\n• النظافة والطهارة\n• تحريم الخبائث والمسكرات\n• الأخذ بأسباب العلاج\n• النهي عن إلقاء النفس إلى التهلكة\n▸ الصحة النفسية\n• الإيمان والطمأنينة بذكر الله\n• الصبر والرضا بالقضاء\n• التوكل على الله\n• تجنب الحقد والحسد والقلق\n▸ أهم المصطلحات\n• الصحة\n• الطمأنينة\n• السكينة\n• الاعتدال\n▸ شرح موسّع\n• تظهر عناية الإسلام بالجسم في دعوته إلى الطهارة والوضوء، والاعتدال في المأكل والمشرب، وتحريم ما يضر كالخمر والميتة ولحم الخنزير والدم. كما أمر بالتداوي وجعل الصحة من أعظم النعم. وتظهر عنايته بالنفس في ربط القلب بالله، فالإيمان يمنح السكينة ويقلل القلق والخوف، والصبر يعين على الابتلاءات. ويؤكد الإسلام التوازن بين حاجات الروح والجسد دون إفراط ولا تفريط، فلا رهبانية تعطل الجسد ولا انغماس في الشهوات.\n▸ الدليل\n• ﴿وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا﴾ (الأعراف 31)\n• ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾ (البقرة 195)\n• ﴿أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾ (الرعد 28)\n• «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف» (رواه مسلم)\n▸ للحفظ\n• الإسلام يحفظ البدن بالاعتدال والطهارة والتداوي، ويحفظ النفس بالإيمان والذكر والصبر.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"القيم في القرآن الكريم","content":"▸ الفكرة العامة\n• مبادئ ومثل عليا توجه سلوك الفرد والمجتمع، جاء بها القرآن في منظومة متكاملة.\n▸ أنواع القيم\n• إيمانية: التوحيد والإخلاص والتقوى\n• أخلاقية: الصدق والأمانة والوفاء\n• اجتماعية: التعاون والعدل والتسامح\n• اقتصادية: الكسب الحلال والإنفاق\n▸ خصائص القيم القرآنية\n• ربانية المصدر\n• شمولية\n• ثابتة في أصولها\n• تحقق سعادة الدنيا والآخرة\n▸ أهم المصطلحات\n• القيم\n• الأخلاق\n• العدل\n• الأمانة\n• الإحسان\n▸ شرح موسّع\n• القيم في الإسلام ليست مجرد عادات اجتماعية متغيرة، بل هي أحكام وتوجيهات مصدرها الوحي، لذلك تتميز بالثبات والشمول. وتشمل علاقة الإنسان بربه (الإخلاص والتقوى)، وبنفسه (الصدق والعفة)، وبغيره (العدل والإحسان والرحمة)، وبالمال (الكسب الحلال وتجنب الغش). والقيم تحفظ تماسك المجتمع وتحمي أفراده من الفساد، ويعد الالتزام بها دليلًا على صدق الإيمان.\n▸ الدليل\n• ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾ (القلم 4)\n• ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَىٰ﴾ (النحل 90)\n• ﴿وَأَوْفُوا بِالْعَهْدِ إِنَّ الْعَهْدَ كَانَ مَسْئُولًا﴾ (الإسراء 34)\n▸ للحفظ\n• القيم القرآنية ربانية المصدر شاملة ثابتة، وتنظم علاقة الإنسان بربه ونفسه وغيره.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"المساواة أمام أحكام الشريعة الإسلامية","content":"▸ الفكرة العامة\n• الناس سواسية أمام أحكام الشريعة، لا فضل لأحد بنسبه أو ماله أو جاهه إلا بالتقوى.\n▸ أساس المساواة\n• وحدة الأصل الإنساني\n• العبودية لله وحده\n• التقوى هي معيار التفاضل\n▸ مجالات المساواة\n• أمام القضاء\n• في الحقوق والواجبات\n• في التكليف والجزاء\n• في الكرامة الإنسانية\n▸ أهم المصطلحات\n• المساواة\n• العدل\n• القضاء\n• التقوى\n▸ شرح موسّع\n• تقوم المساواة في الإسلام على وحدة الأصل: فالناس جميعًا من آدم، وآدم من تراب. ولذلك ألغى الإسلام الفوارق القائمة على اللون والجنس والنسب. وتظهر المساواة عمليًا في القضاء، فالشريف والضعيف أمام الحكم سواء، كما في قصة المرأة المخزومية التي سرقت فأراد بعض الناس الشفاعة لها لشرفها، فغضب النبي ﷺ وأكد تطبيق الحد على الجميع. والمساواة لا تعني التطابق في كل شيء، فقد يختلف توزيع بعض الأحكام بحسب طبيعة كل طرف ووظيفته مع حفظ العدل والكرامة للجميع.\n▸ الدليل\n• ﴿يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا ۚ إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ﴾ (الحجرات 13)\n• حديث المخزومية: «وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها» (متفق عليه)\n▸ للحفظ\n• الناس سواسية أمام الشريعة، والتفاضل بالتقوى والعمل الصالح فقط.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"العمل والإنتاج في الإسلام ومشكلة البطالة","content":"▸ مكانة العمل\n• عبادة إذا صحت النية\n• أمر به القرآن وحث عليه\n• الكسب الحلال فريضة\n• الاعتماد على النفس\n▸ ضوابط العمل\n• أن يكون مشروعًا (حلالًا)\n• الإتقان والإخلاص\n• عدم الإضرار بالغير\n• عدم إلهائه عن العبادات\n▸ أسباب البطالة\n• الكسل والتواكل\n• ضعف التكوين والمهارة\n• قلة فرص العمل\n• سوء توزيع الثروة\n▸ علاج الإسلام للبطالة\n• الحث على العمل وذم التسول\n• التكوين والتعلم\n• الزكاة والصدقات للعاجز\n• دور الدولة في توفير الفرص\n▸ شرح موسّع\n• يعد الإسلام العمل واجبًا ومصدر عزة، ويذم الكسل والاتكال على الآخرين، فالنبي ﷺ علّم الناس أن الكسب بجهد اليد خير من سؤال الناس. ومع ذلك لا يهمل الإسلام العاجز عن العمل، فجعل له حقًا في الزكاة. ولمعالجة البطالة جمع الإسلام بين تحفيز الفرد على السعي، وإلزام المجتمع والدولة بتوفير فرص العمل والتكوين وتشجيع الاستثمار وإحياء الأرض الموات، وتحقيق التكافل حتى لا يبقى محتاج بلا مورد.\n▸ الدليل\n• ﴿وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ﴾ (التوبة 105)\n• ﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ﴾ (الجمعة 10)\n• «ما أكل أحد طعامًا قط خيرًا من أن يأكل من عمل يده» (رواه البخاري)\n▸ للحفظ\n• العمل عبادة وواجب، والإسلام يعالج البطالة بتحفيز الفرد وتكافل المجتمع ودور الدولة.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"حقوق العمال وواجباتهم في الإسلام","content":"▸ حقوق العامل\n• أجر عادل في وقته\n• عدم تكليفه فوق طاقته\n• معاملته بكرامة واحترام\n• توفير ظروف عمل آمنة\n• الراحة والعناية به\n▸ واجبات العامل\n• إتقان العمل وإحسانه\n• الأمانة في أداء المهمة\n• الالتزام بالوقت والعقد\n• المحافظة على أدوات العمل\n▸ واجبات صاحب العمل\n• الوفاء بشروط العقد\n• عدم الظلم والغش\n• تحديد الأجر قبل العمل\n▸ أهم المصطلحات\n• الأجير\n• عقد الإجارة\n• الأجر\n• الإتقان\n• الأمانة\n▸ شرح موسّع\n• العلاقة بين العامل وصاحب العمل في الإسلام علاقة تعاقدية قائمة على العدل والأخوة، وتسمى «الإجارة». فللعامل حق في أجر معلوم يُدفع دون تأخير، وفي معاملة كريمة لا إذلال فيها، ولا يُكلَّف إلا بما يطيق. وعليه في المقابل أداء عمله بأمانة وإتقان. وصفتا القوة (الكفاءة) والأمانة (الخُلق) هما أساس اختيار العامل. وبهذا يتحقق التوازن بين مصلحة العامل ورب العمل ومصلحة المجتمع.\n▸ الدليل\n• ﴿إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ﴾ (القصص 26)\n• «أعطوا الأجير أجره قبل أن يجف عرقه» (رواه ابن ماجه)\n• «ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم» (متفق عليه)\n▸ للحفظ\n• حقوق العامل: أجر عادل ومعاملة كريمة. واجباته: الأمانة والإتقان. والمعيار: القوي الأمين.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"مشروعية الوقف","content":"▸ تعريف الوقف\n• حبس الأصل وتسبيل المنفعة: منع التصرف في العين الموقوفة وجعل ثمرتها في وجوه الخير.\n▸ أركان الوقف\n• الواقف\n• الموقوف (المال)\n• الموقوف عليه\n• الصيغة\n▸ أنواع الوقف\n• وقف خيري (عام)\n• وقف أهلي (ذري)\n• وقف مشترك\n▸ حكمته وآثاره\n• صدقة جارية يتصل أجرها\n• تحقيق التكافل الاجتماعي\n• تمويل التعليم والصحة والمساجد\n• حفظ المال من التبديد\n▸ شرح موسّع\n• الوقف من أعظم صور الإنفاق في سبيل الله لأن أصله يبقى وثمرته تتجدد. وقد ثبتت مشروعيته بالسنة، ومن أشهر أدلته وقف عمر بن الخطاب رضي الله عنه أرضه بخيبر بإرشاد النبي ﷺ. ويشترط في الواقف أن يكون أهلًا للتبرع، وفي الموقوف أن يكون مالًا مملوكًا ينتفع به مع بقاء عينه. وللوقف دور كبير في تاريخ الحضارة الإسلامية: المدارس والمستشفيات والمكتبات والعيون. وقد نظّمت الجزائر الأوقاف بقانون خاص (قانون الأوقاف 10-91).\n▸ الدليل\n• قال النبي ﷺ لعمر: «إن شئت حبست أصلها وتصدقت بها» (متفق عليه)\n• «إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له» (رواه مسلم)\n• ﴿لَن تَنَالُوا الْبِرَّ حَتَّىٰ تُنفِقُوا مِمَّا تُحِبُّونَ﴾ (آل عمران 92)\n▸ للحفظ\n• الوقف = حبس الأصل وتسبيل المنفعة، وهو صدقة جارية تعين على التكافل.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الحريات الشخصية وعلاقتها بحقوق الآخرين","content":"▸ مفهوم الحرية\n• قدرة الإنسان على التصرف باختياره في حدود الشريعة دون إلحاق ضرر بغيره.\n▸ أنواع الحريات\n• حرية الاعتقاد\n• حرية الرأي والتعبير\n• حرية التملك والتصرف\n• حرية التنقل والعمل\n▸ ضوابط الحرية\n• عدم الإضرار بالغير\n• عدم مخالفة أحكام الشرع\n• احترام النظام العام والآداب\n• تحمل المسؤولية عن التصرفات\n▸ أهم المصطلحات\n• الحرية\n• الضرر\n• الحق\n• المسؤولية\n▸ شرح موسّع\n• كرّم الله الإنسان وأعطاه حرية الاختيار، لكنه قرن الحرية بالمسؤولية. فحرية الفرد تنتهي حيث تبدأ حقوق غيره، لذلك لا يجوز لأحد أن يستعمل حريته لإيذاء الآخرين أو الإضرار بالمجتمع. وقاعدة «لا ضرر ولا ضرار» تضبط كل تصرف. وفي مجال الاعتقاد قرر القرآن عدم الإكراه في الدين. ويُقدَّم الحق العام عند التعارض مع الحق الخاص حفاظًا على المصلحة العامة، كمنع الاحتكار والغش.\n▸ الدليل\n• ﴿لَا إِكْرَاهَ فِي الدِّينِ﴾ (البقرة 256)\n• ﴿وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ﴾ (الإسراء 70)\n• «لا ضرر ولا ضرار» (رواه ابن ماجه)\n• ﴿فَمَن شَاءَ فَلْيُؤْمِن وَمَن شَاءَ فَلْيَكْفُرْ﴾ (الكهف 29) في بيان حرية الاختيار مع تحمل المسؤولية\n▸ للحفظ\n• الحرية مكفولة بشرط عدم الإضرار بالغير وعدم مخالفة الشرع: «لا ضرر ولا ضرار».\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"حقوق الإنسان في مجال العلاقات العامة والتعامل الدولي","content":"▸ مبادئ التعامل الدولي\n• الوفاء بالعهود والمواثيق\n• السلم هو الأصل\n• حماية الرسل والمستأمنين\n• حسن معاملة الأسرى\n• التعاون على الخير\n▸ حقوق في العلاقات العامة\n• حفظ الكرامة الإنسانية\n• حرمة الدم والمال والعرض\n• حسن الجوار\n• العدل مع الجميع\n▸ أهم المصطلحات\n• حقوق الإنسان\n• المعاهدة\n• الأمان\n• التعايش\n• السلم\n▸ شرح موسّع\n• أقرّ الإسلام حقوق الإنسان قبل المواثيق الدولية الحديثة بقرون، وأساسها تكريم الإنسان لإنسانيته بغض النظر عن دينه أو جنسه. وفي العلاقات الدولية الأصل هو السلم والتعارف، والحرب استثناء لدفع العدوان. ويوجب الإسلام الوفاء بالعهود والمعاهدات، ويحمي من دخل بلاد المسلمين بأمان (المستأمن)، ويأمر بحسن معاملة الأسرى، ويحرّم قتل النساء والأطفال والشيوخ وغير المقاتلين، ويحث على التعاون الإنساني.\n▸ الدليل\n• ﴿وَإِن جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا﴾ (الأنفال 61)\n• ﴿وَإِنْ أَحَدٌ مِّنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللَّهِ﴾ (التوبة 6)\n• ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ﴾ (الممتحنة 8)\n▸ للحفظ\n• السلم هو الأصل، والوفاء بالعهود واجب، وكرامة الإنسان محفوظة في كل الأحوال.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"آثار التوحيد في حياة الفرد والمجتمع","content":"▸ معنى التوحيد\n• إفراد الله تعالى بالعبادة والربوبية والأسماء والصفات وعدم الإشراك به.\n▸ آثاره في الفرد\n• التحرر من الخوف والخرافة والعبودية للبشر\n• الطمأنينة والأمن النفسي\n• الاستقامة والإخلاص\n• الشعور بالمسؤولية ومراقبة الله\n▸ آثاره في المجتمع\n• وحدة الأمة وتماسكها\n• المساواة بين الناس\n• قيام العدل والتعاون\n• محاربة الفساد والظلم\n▸ أهم المصطلحات\n• التوحيد\n• الشرك\n• الإخلاص\n• التقوى\n▸ شرح موسّع\n• التوحيد هو أساس العقيدة الإسلامية، وله أثر عميق في بناء الإنسان والمجتمع. فالموحد لا يخاف إلا من الله ولا يرجو سواه، فيتحرر من الخوف من البشر ومن الخرافات والسحر والتنجيم. ويمنحه الإيمان بالله سكينة في الأزمات. وعلى مستوى المجتمع يوحد التوحيد الصفوف لأن الجميع عباد لله، فلا طبقية ولا تمييز، ويقوي الشعور بالمسؤولية، فيعمل الفرد لمصلحة مجتمعه ويراقب الله في السر والعلن.\n▸ الدليل\n• ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُم مُّهْتَدُونَ﴾ (الأنعام 82)\n• ﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ﴾ (الأحقاف 13)\n▸ للحفظ\n• التوحيد يحرر الفرد من الخوف والخرافة، ويوحد المجتمع على العدل والمساواة.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الإسلام والرسالات السماوية السابقة","content":"▸ وحدة الرسالات\n• مصدرها واحد هو الله\n• جوهرها واحد: التوحيد\n• الأنبياء إخوة في الدعوة\n• الإيمان بجميع الرسل والكتب واجب\n▸ موقف الإسلام منها\n• تصديق أصل الرسالات السابقة\n• القرآن مهيمن على الكتب السابقة\n• تحريف ما حُرّف من الكتب\n• الإسلام خاتم الرسالات وناسخها\n▸ أهم الكتب والرسل\n• التوراة (موسى)\n• الإنجيل (عيسى)\n• الزبور (داود)\n• القرآن (محمد ﷺ)\n▸ أهم المصطلحات\n• الرسالة\n• الوحي\n• التحريف\n• الهيمنة\n• خاتم النبيين\n▸ شرح موسّع\n• يؤمن المسلم بجميع الأنبياء والكتب المنزلة، ولا يفرق بين أحد من الرسل، فمصدر الرسالات واحد وأصلها دعوة الناس إلى عبادة الله وحده. وقد تعرضت الكتب السابقة للتحريف والتبديل، فجاء القرآن مصدّقًا لما صح فيها ومهيمنًا عليها، أي حاكمًا ومبينًا لما حُرّف. وجاءت الشريعة الإسلامية خاتمة وشاملة صالحة لكل زمان ومكان، وبها كمُل الدين. ومن هذا الموقف ينبع احترام أهل الكتاب وحسن التعامل معهم.\n▸ الدليل\n• ﴿آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ﴾ (البقرة 285)\n• ﴿وَأَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾ (المائدة 48)\n▸ للحفظ\n• الرسالات مصدرها واحد وجوهرها التوحيد، والإسلام مصدّق لها ومهيمن عليها وخاتم لها.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"مقاصد الشريعة الإسلامية","content":"▸ تعريفها\n• الغايات والحكم التي قصدها الشارع من تشريع الأحكام لتحقيق مصالح العباد في الدنيا والآخرة.\n▸ الضروريات الخمس\n• حفظ الدين\n• حفظ النفس\n• حفظ العقل\n• حفظ النسل (العرض)\n• حفظ المال\n▸ مراتب المقاصد\n• الضروريات: لا تقوم الحياة بدونها\n• الحاجيات: رفع الحرج والمشقة\n• التحسينيات: مكارم الأخلاق والكمال\n▸ أهميتها\n• فهم النصوص وتطبيقها\n• الاجتهاد في المستجدات\n• الترجيح بين الأدلة\n▸ شرح موسّع\n• تقوم الشريعة على قاعدة جلب المصالح ودرء المفاسد. فكل حكم شرعي وراءه مقصد، وأعلى المقاصد الضروريات الخمس. مثال: تشريع القصاص يحفظ النفس، وتحريم الخمر يحفظ العقل، وتحريم الزنا يحفظ النسل، وتحريم السرقة والربا يحفظ المال، والجهاد المشروع ودعوة الناس تحفظ الدين. وأما الحاجيات فمثل الرخص في السفر والمرض، والتحسينيات كآداب الأكل والطهارة. وقد اهتم العلماء بهذا العلم، ومنهم الشاطبي في كتابه «الموافقات».\n▸ الدليل\n• ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ﴾ (الأنبياء 107)\n• ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ يَا أُولِي الْأَلْبَابِ﴾ (البقرة 179) مثال لمقصد حفظ النفس\n▸ للحفظ\n• الضروريات الخمس: الدين، النفس، العقل، النسل، المال. والقاعدة: جلب المصالح ودرء المفاسد.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الإجماع والقياس والمصالح المرسلة","content":"▸ الإجماع\n• اتفاق مجتهدي الأمة بعد وفاة النبي ﷺ في عصر على حكم شرعي\n• حجة شرعية ملزمة\n• مثاله: توريث الجدة السدس\n▸ القياس\n• إلحاق فرع بأصل في حكم لعلة مشتركة\n• أركانه: الأصل، الفرع، العلة، الحكم\n• مثاله: المخدرات على الخمر بعلة الإسكار\n▸ المصالح المرسلة\n• مصلحة لم يرد نص بإلغائها ولا باعتبارها\n• شرطها: ملاءمة مقاصد الشرع\n• مثالها: توثيق العقود وجمع المصحف\n▸ أهم المصطلحات\n• الإجماع\n• القياس\n• العلة\n• الاجتهاد\n• المصلحة\n▸ شرح موسّع\n• بعد الكتاب والسنة تأتي أدلة اجتهادية يعتمد عليها الفقهاء في استخراج الأحكام للمسائل الجديدة. فالإجماع يمثل اتفاق العلماء المجتهدين، وهو دليل قطعي أو ظني بحسب نوعه. والقياس هو إلحاق مسألة جديدة لا نص فيها بمسألة منصوص على حكمها لاشتراكهما في العلة، كتحريم كل مسكر قياسًا على الخمر. أما المصالح المرسلة فهي الأمور التي تحقق نفعًا للناس ولم يرد فيها نص بالاعتبار أو الإلغاء، كاعتماد السجلات الرسمية وتنظيم المرور، بشرط ألا تخالف نصًا شرعيًا.\n▸ الدليل\n• من أدلة حجية الإجماع: ﴿وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّىٰ﴾ (النساء 115)\n• من أدلة القياس الاعتبار: ﴿فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ﴾ (الحشر 2)\n▸ للحفظ\n• الإجماع = اتفاق المجتهدين، القياس = إلحاق فرع بأصل لعلة جامعة، المصلحة المرسلة = مصلحة لا نص فيها.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"النسب والتبني والكفالة","content":"▸ النسب\n• انتماء الولد إلى أبيه وأمه\n• أسبابه: الزواج الصحيح، الإقرار، البينة\n• تترتب عليه حقوق: النفقة والإرث والولاية\n▸ التبني\n• نسبة ولد معروف النسب إلى غير أبيه\n• محرّم في الإسلام\n• لا تترتب عليه أحكام البنوة\n▸ الكفالة\n• التزام برعاية طفل والإنفاق عليه وتربيته\n• مشروعة ومرغّب فيها\n• لا يُنسب المكفول إلى الكافل بالبنوة\n• ينظمها قانون الأسرة الجزائري\n▸ أهم المصطلحات\n• النسب\n• التبني\n• الكفالة\n• اليتيم\n• مجهول النسب\n▸ شرح موسّع\n• حفظ النسب من مقاصد الشريعة الكبرى، لذلك أبطل الإسلام التبني الذي كان معروفًا في الجاهلية لأنه يخلط الأنساب ويمنح الدعيّ حقوق الابن الحقيقي من إرث ومحرمية. وفي المقابل شجع على كفالة اليتيم ومجهول النسب برعايته ماديًا ومعنويًا دون أن يُنسب إليه، فيحفظ للطفل حقه في الحياة الكريمة ويحفظ للأنساب نقاءها. وللمكفول أن يحمل اسمًا مناسبًا، ويجوز للكافل أن يوصي له في حدود الثلث.\n▸ الدليل\n• ﴿وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ﴾ (الأحزاب 4)\n• ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِندَ اللَّهِ﴾ (الأحزاب 5)\n• «أنا وكافل اليتيم في الجنة هكذا» وأشار بالسبابة والوسطى (رواه البخاري)\n▸ للحفظ\n• التبني محرّم لأنه يخلط الأنساب، والكفالة مشروعة ومرغّب فيها دون نسبة الولد للكافل.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الربا ومشكلة الفائدة","content":"▸ تعريف الربا\n• الزيادة المشروطة في القرض، أو الزيادة في بيع بعض الأموال بجنسها.\n▸ أنواع الربا\n• ربا النسيئة: زيادة مقابل التأجيل\n• ربا الفضل: زيادة في بيع الجنس بجنسه\n▸ حكمه وحكمة تحريمه\n• محرّم بنص القرآن والسنة\n• استغلال حاجة المحتاج\n• يؤدي إلى تراكم الديون والتضخم\n• يفسد العدالة بين الدائن والمدين\n▸ الفائدة والبدائل\n• الفائدة المصرفية على القروض: رأي المجامع الفقهية أنها من الربا\n• البدائل: المرابحة، المشاركة، المضاربة، القرض الحسن\n• البنوك والنوافذ الإسلامية\n▸ شرح موسّع\n• الربا من كبائر الذنوب، وقد حرمه القرآن بشدة وأعلن الحرب على المصرّين عليه. وأشهر صوره ربا الجاهلية: يحل الدين على المدين فيقول له الدائن: أتقضي أم تُربي؟ فيزيد الدين على المدين مع الأجل. ويرى جمهور الفقهاء والمجامع الفقهية المعاصرة أن الفائدة التي تأخذها البنوك التقليدية على القروض داخلة في الربا لأنها زيادة مشروطة على القرض. وقد ظهرت المصارف الإسلامية لتقديم بدائل تقوم على المشاركة في الربح والخسارة وعلى البيع الحقيقي للسلع.\n▸ الدليل\n• ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ (البقرة 275)\n• ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا﴾ (البقرة 278)\n• «لعن رسول الله ﷺ آكل الربا وموكله وكاتبه وشاهديه، وقال: هم سواء» (رواه مسلم)\n▸ للحفظ\n• الربا = زيادة مشروطة محرمة، وأنواعه: النسيئة والفضل، وبدائله: المرابحة والمشاركة والمضاربة.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الوصية ومدخل إلى علم الميراث","content":"▸ الوصية\n• تمليك مضاف إلى ما بعد الموت بطريق التبرع\n• تجوز في حدود ثلث التركة\n• لا وصية لوارث إلا بإجازة الورثة\n• أركانها: الموصي، الموصى له، الموصى به، الصيغة\n▸ الميراث (الفرائض)\n• انتقال أموال المتوفى إلى ورثته الشرعيين\n• أركانه: المورِّث، الوارث، الحق الموروث\n▸ أسباب الإرث\n• الزوجية\n• القرابة (النسب)\n• الولاء\n▸ موانع الإرث\n• القتل العمد\n• اختلاف الدين\n▸ شرح موسّع\n• قبل تقسيم التركة تتعلق بها حقوق مرتبة: أولًا مؤونة تجهيز الميت ودفنه، ثم سداد ديونه، ثم تنفيذ وصيته في حدود الثلث، ثم تقسيم الباقي على الورثة حسب الأنصبة الشرعية التي حددها القرآن (الفروض المقدرة: النصف والربع والثمن والثلثان والثلث والسدس). وقد عُرف علم الميراث بعلم الفرائض، وحث النبي ﷺ على تعلمه. وحكمة الوصية أن تمكّن الإنسان من البر بمن لا يرث، كالأقارب المحتاجين والجهات الخيرية.\n▸ الدليل\n• ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ﴾ (النساء 11)\n• «إن الله قد أعطى كل ذي حق حقه، فلا وصية لوارث» (رواه أبو داود والترمذي)\n• قال ﷺ لسعد: «الثلث، والثلث كثير» (متفق عليه)\n▸ للحفظ\n• ترتيب الحقوق في التركة: التجهيز، الديون، الوصية (≤ الثلث)، ثم الميراث.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"من المعاملات المالية الجائزة: المرابحة والتقسيط والصرف","content":"▸ المرابحة\n• بيع السلعة بثمنها الأول مع ربح معلوم\n• يشترط علم المشتري بالثمن والربح\n• ملكية البائع للسلعة قبل بيعها\n▸ التقسيط\n• بيع بثمن مؤجل يُسدَّد على أقساط\n• جائز بشرط تحديد الثمن عند العقد\n• لا تجوز زيادة الثمن عند التأخر في السداد\n▸ الصرف\n• بيع نقد بنقد (عملة بعملة)\n• التقابض في مجلس العقد\n• التماثل إذا اتحد الجنس\n▸ أهم المصطلحات\n• البيع\n• الثمن المؤجل\n• التقابض\n• رأس المال\n• الربح\n▸ شرح موسّع\n• هذه المعاملات من صور البيع المشروع التي تحقق مصلحة الطرفين بعيدًا عن الربا والغرر. فالمرابحة صيغة تعتمدها البنوك الإسلامية: تشتري السلعة ثم تبيعها للعميل بثمن الشراء مع ربح متفق عليه. والتقسيط يتيح للمشتري الدفع على مراحل، والثمن المؤجل قد يزيد عن الثمن الحاضر إن حُدد عند العقد وانتهى المجلس على ثمن واحد. أما إن اشترطت زيادة عند التأخر عن الدفع فهي ربا محرم. والصرف يقتضي التقابض الفوري، فلا يجوز تأجيل أحد البدلين.\n▸ الدليل\n• قال النبي ﷺ: «الذهب بالذهب، والفضة بالفضة ... مثلًا بمثل، سواءً بسواء، يدًا بيد، فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يدًا بيد» (رواه مسلم)\n• ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ﴾ (البقرة 275)\n▸ للحفظ\n• المرابحة: ثمن + ربح معلوم. التقسيط: ثمن محدد مؤجل. الصرف: تقابض فوري في المجلس.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"الشركة في الفقه الإسلامي","content":"▸ تعريفها\n• عقد بين اثنين أو أكثر على الاشتراك في رأس المال أو العمل لتحقيق الربح.\n▸ أنواعها\n• شركة الأموال (العنان)\n• شركة الأعمال (الأبدان)\n• شركة الوجوه\n• المضاربة\n▸ أركانها\n• العاقدان (الشريكان)\n• الصيغة (الإيجاب والقبول)\n• المحل (المال أو العمل)\n▸ أحكام الربح والخسارة\n• الربح حسب النسب المتفق عليها\n• الخسارة بقدر رأس المال\n• الأمانة في تسيير الشركة\n▸ شرح موسّع\n• تعد الشركة من أهم أدوات الاستثمار المشروع، لأنها تجمع الأموال والخبرات وتقسم الربح والخسارة بالعدل. فشركة العنان تقوم على أن يساهم الشركاء بأموال ويعملون فيها، وشركة الأبدان على اشتراك أصحاب مهنة بجهودهم، والمضاربة أن يقدم أحد الطرفين المال والآخر العمل، فيقتسمان الربح بنسبة شائعة يتفقان عليها، ويتحمل صاحب المال الخسارة المالية ويخسر المضارب جهده. ويجب على الشريك الأمانة والوفاء بالاتفاق وتجنب الغش.\n▸ الدليل\n• ﴿وَإِنَّ كَثِيرًا مِّنَ الْخُلَطَاءِ لَيَبْغِي بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ (ص 24)\n• ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ﴾ (المائدة 1)\n▸ للحفظ\n• الشركة: اشتراك في المال أو العمل. الربح حسب الاتفاق، والخسارة بقدر رأس المال.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"تحليل وثيقة خطبة الرسول ﷺ في حجة الوداع","content":"▸ الظروف\n• السنة العاشرة للهجرة\n• في عرفة بمناسبة حجة الوداع\n• أمام جموع المسلمين\n▸ أهم ما تضمنته\n• حرمة الدماء والأموال والأعراض\n• وضع ربا الجاهلية ودماء الجاهلية\n• الوصية بالنساء خيرًا\n• المساواة: لا فضل لعربي على أعجمي إلا بالتقوى\n• التمسك بكتاب الله وسنة نبيه\n▸ القيم المستفادة\n• حفظ حقوق الإنسان\n• العدالة الاجتماعية والاقتصادية\n• وحدة المسلمين\n▸ أهم المصطلحات\n• حجة الوداع\n• الدماء\n• الأموال\n• الأعراض\n• الأمانة\n▸ شرح موسّع\n• تعد خطبة الوداع وثيقة جامعة لمبادئ الإسلام الكبرى ودستورًا للعلاقات الإنسانية. أعلن فيها النبي ﷺ أن دماء الناس وأموالهم وأعراضهم محرمة كحرمة يوم عرفة وشهر ذي الحجة والبلد الحرام، وألغى مظالم الجاهلية من الثأر والربا، وأوصى بالنساء، وقرر المساواة بين الناس. وختمها بالتأكيد على الاعتصام بكتاب الله وبتبليغ الرسالة: «ألا هل بلغت؟». وتظهر فيها منهجية التشريع القائمة على حفظ الضروريات الخمس.\n▸ الدليل\n• «إن دماءكم وأموالكم وأعراضكم عليكم حرام كحرمة يومكم هذا في شهركم هذا في بلدكم هذا» (رواه مسلم)\n• «وربا الجاهلية موضوع» · «فاتقوا الله في النساء»\n• «لا فضل لعربي على أعجمي ولا لعجمي على عربي إلا بالتقوى» (رواه أحمد)\n▸ للحفظ\n• الخطبة تقرر: حرمة الدماء والأموال والأعراض، إلغاء الربا والثأر، المساواة، والتمسك بالقرآن.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."},{"title":"العلاقات الاجتماعية بين المسلمين وغيرهم","content":"▸ أساس العلاقة\n• البر والقسط والعدل\n• التعارف والتعايش\n• الكرامة الإنسانية للجميع\n▸ مظاهر حسن التعامل\n• حسن الجوار\n• التعامل التجاري المشروع\n• جواز أكل طعام أهل الكتاب\n• الحوار بالتي هي أحسن\n• حماية أموالهم وأعراضهم\n▸ حدود العلاقة\n• عدم الموالاة فيما يضر بالدين\n• عدم التنازل عن العقيدة\n▸ نماذج تطبيقية\n• صحيفة المدينة\n• معاملة النبي ﷺ لأهل الكتاب\n• عهد عمر لأهل إيلياء\n▸ شرح موسّع\n• علاقة المسلمين بغيرهم قائمة على العدل والإحسان ما لم يكن اعتداء. وتظهر في تاريخ المسلمين نماذج حية، كصحيفة المدينة التي نظمت العيش المشترك بين المسلمين واليهود وقبائل المدينة، وضمنت حرية العقيدة وحق الدفاع المشترك عن المدينة. وأباح الإسلام التعامل التجاري مع غير المسلمين، وأكل طعام أهل الكتاب، والزواج من نسائهم. وفي المقابل يحافظ المسلم على هويته وعقيدته دون إكراه لغيره.\n▸ الدليل\n• ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَارِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ﴾ (الممتحنة 8)\n• ﴿وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَىٰ أَلَّا تَعْدِلُوا﴾ (المائدة 8)\n• «من قتل معاهدًا لم يرح رائحة الجنة» (رواه البخاري)\n▸ للحفظ\n• العلاقة مع غير المسلمين: بر وقسط وعدل وحوار، مع حفظ الهوية الدينية دون إكراه.\n▸ ملاحظة\n• هذه الدروس ملخصة من بطاقات الثالثة ثانوي تسيير واقتصاد؛ طابقها مع كتاب أستاذك وبرنامج شعبتك."}];
