  /* الفلسفة: أدبي = 22 درسًا، علمي/تقني = 14 درسًا. يُسجَّل حسب اسم الشعبة في قاعدة المواد */
  var pLit={name:'الفلسفة',lessons:[{"title":"1. أهمية الفلسفة","content":"▸ هل للفلسفة قيمة في عصر العلم والتقنية؟ (جدلية)\n▸ المشكلة المطروحة\n• ما الفلسفة؟ وهل لها فائدة في عصر العلم والتقنية؟\n▸ مفهوم الفلسفة\n• كلمة يونانية: فيلو (محبة) + صوفيا (حكمة)\n• طلب الحقيقة بالتأمل العقلي النقدي\n• تطرح أسئلة كلية: الوجود، المعرفة، القيم\n▸ خصائص التفكير الفلسفي\n• الدهشة والتساؤل\n• النقد وعدم التسليم الأعمى\n• الشمول والكلية\n• الاعتماد على العقل والحجة\n▸ قيمتها\n• تحرير العقل من التقليد والخرافة\n• تنمية روح النقد والحوار\n• تأسيس القيم والمعرفة\n• فهم الذات والعالم\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: الفلسفة ليست بلا فائدة: هي أصل العلوم وتؤسس للنقد والحوار\n• نقد الأطروحة الثانية: الدفاع المطلق يتجاهل أنها لا تقدم نتائج تجريبية قابلة للتحقق\n▸ أهم المصطلحات\n• الفلسفة\n• الدهشة\n• النقد\n• الحكمة\n• الإشكالية\n▸ مقالات مقترحة\n• هل للفلسفة قيمة في عصر العلم والتقنية؟ (جدلية)\n• الفلسفة أسئلة أم أجوبة؟ (جدلية)\n• دافع عن الأطروحة القائلة بأن الفلسفة ضرورية (استقصاء بالوضع)\n▸ شرح موسّع\n• تبدأ الفلسفة عند أرسطو من الدهشة، فالإنسان يتعجب مما حوله فيسأل ثم يبحث. وهي تختلف عن الرأي العادي بأنها تطلب الدليل وتقبل المراجعة. ويرى بعض المنتقدين أنها بلا نتائج نهائية بخلاف العلوم، لكن قيمتها ليست في الأجوبة الجاهزة بل في الأسئلة التي توسع الأفق وتحمي العقل من الجمود. وقد قال كانط إننا لا نتعلم فلسفة جاهزة بل نتعلم كيف نتفلسف. وللفلسفة أثر عملي في بناء الإنسان الحر المسؤول، وفي نشأة العلوم نفسها التي خرجت من رحمها.\n▸ الفلاسفة والأمثلة\n• سقراط: «اعرف نفسك بنفسك».\n• أفلاطون وأرسطو: «الفلسفة تبدأ بالدهشة».\n• ديكارت: الفلسفة كشجرة جذورها الميتافيزيقا وجذعها الفيزياء وفروعها بقية العلوم.\n▸ للحفظ\n• الفلسفة = محبة الحكمة وطلب الحقيقة بالعقل النقدي، وقيمتها في الأسئلة والنقد وتحرير العقل."},{"title":"2. الإدراك والإحساس","content":"▸ هل الإدراك ظاهرة حسية أم عقلية؟\n▸ المشكلة المطروحة\n• ما العلاقة بين الإحساس والإدراك؟ وهل يدرك الإنسان العالم بالحواس وحدها أم بالعقل؟\n▸ المفاهيم\n• الإحساس: انطباع حسي بسيط ناتج عن مؤثر خارجي\n• الإدراك: تأويل ذهني للمعطيات الحسية وتنظيمها\n• الحواس الخمس والمخ\n▸ الأطروحة العقلية\n• العقل هو الذي يدرك الماهية\n• ديكارت: قطعة الشمع تتغير حسيًا وتبقى هي نفسها\n• الحواس تخدع (العصا المنكسرة في الماء)\n▸ الأطروحة الحسية\n• الإدراك مجموع إحساسات (هيوم)\n• كل معرفة أصلها الحس (لوك)\n• التمييز بين الشدة والمكان من الحس\n▸ التركيب (الجشطالت)\n• الإدراك كل منظم قبل الأجزاء\n• يتأثر بالخبرة والثقافة والانتباه\n• الحواس والعقل متكاملان\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تهمل دور الحواس: لا إدراك بدون معطيات حسية\n• نقد الأطروحة الثانية: تتجاهل تنظيم العقل وأخطاء الحواس التي يصححها العقل\n▸ مقالات مقترحة\n• هل الإدراك ظاهرة حسية أم عقلية؟\n• ما أهمية العقل في عملية الإدراك؟\n• قارن بين الإحساس والإدراك\n▸ شرح موسّع\n• يقرر العقليون أن الإحساس وحده لا يعطي معرفة موثوقة، فالحواس تخدع كما في العصا التي تبدو منكسرة في الماء وهي مستقيمة، والذي يصحح الخطأ هو العقل. ويستدل ديكارت بقطعة شمع تذوب وتتغير كل صفاتها الحسية ومع ذلك نحكم بأنها الشمع نفسه، فالحكم عقلي. وفي المقابل يرى التجريبيون أن الإدراك ليس إلا تجميعًا للإحساسات المتتابعة، وأن كل ما في الذهن أصله حسي. وتأتي مدرسة الجشطالت لتبين أننا ندرك الأشياء كأشكال كلية منظمة لا كأجزاء متفرقة، وأن الخبرة والانتباه والعوامل الاجتماعية تؤثر في إدراكنا. وقد رأى ابن الهيثم أن الإدراك البصري يجمع الحس والذاكرة والاستدلال.\n▸ الفلاسفة والأمثلة\n• ديكارت (التأمل الثاني): إدراك الشمع «ليس عملًا بصريًا ولا لمسيًا، بل هو معاينة للعقل وحده».\n• هيوم: الإدراك حزمة من الانطباعات الحسية المتتابعة.\n• العصا المنكسرة: مثال لخطأ الحواس يصححه العقل.\n▸ للحفظ\n• الإدراك = إحساس + تأويل عقلي منظم، والحواس والعقل متكاملان."},{"title":"3. الذاكرة","content":"▸ المشكلة المطروحة\n▸ المشكلة المطروحة\n• ما طبيعة الذاكرة؟ هل هي ظاهرة عضوية أم نفسية أم اجتماعية؟\n▸ المفهوم\n• القدرة على حفظ الماضي واستحضاره\n• عمليات: التثبيت، الحفظ، الاسترجاع، التعرف\n• النسيان ظاهرة مصاحبة\n▸ الأطروحة العضوية (ريبو)\n• الذكريات آثار في الدماغ\n• تلف الدماغ يفقد الذاكرة\n• قانون الارتداد: ينسى الحديث قبل القديم\n▸ الأطروحة الروحية (برغسون)\n• ذاكرة العادة (آلية) وذاكرة الذكريات (نفسية)\n• الذكريات محفوظة في الروح\n• الدماغ أداة اختيار لا مخزن\n▸ الأطروحة الاجتماعية (هالبواكس)\n• الذاكرة تعتمد على أطر اجتماعية: اللغة، الأسرة، الجماعة\n• نتذكر داخل المجتمع\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: لا تفسر الجانب الشخصي للذكريات ولا بقاءها رغم تلف الدماغ أحيانًا\n• نقد الأطروحة الثانية: تتجاهل دور الدماغ الثابت علميًا في الحفظ والاسترجاع\n▸ مقالات مقترحة\n• هل الذاكرة ظاهرة عضوية أم روحية؟\n• هل الذاكرة فردية أم اجتماعية؟\n• دافع عن الأطروحة القائلة بأن الذاكرة مرتبطة بالدماغ\n▸ شرح موسّع\n• يعد ريبو الذاكرة وظيفة بيولوجية مرتبطة بالجهاز العصبي، ويستدل بأن إصابة بعض مناطق الدماغ تؤدي إلى فقدان الذكريات، وأن النسيان يبدأ بالأحدث ثم الأقدم. أما برغسون فيميز بين ذاكرة العادة المكتسبة بالتكرار وذاكرة الذكريات الخالصة التي تحفظ الأحداث الشخصية، ويرى أن الدماغ مجرد أداة لاستدعاء ما يناسب الحاضر. وأضاف هالبواكس بعدًا اجتماعيًا إذ نتذكر بفضل اللغة والجماعة التي ننتمي إليها. والموقف المتكامل أن الذاكرة ظاهرة مركبة يشترك فيها العضوي والنفسي والاجتماعي.\n▸ الفلاسفة والأمثلة\n• ريبو: «أمراض الذاكرة»، يبين أن فقدان الذاكرة يتدرج من الحديث إلى القديم.\n• برغسون: «المادة والذاكرة».\n• هالبواكس: «الأطر الاجتماعية للذاكرة».\n▸ للحفظ\n• الذاكرة: عضوية (ريبو) وروحية (برغسون) واجتماعية (هالبواكس)، والموقف الأمثل التركيب بينها."},{"title":"4. الخيال","content":"▸ المشكلة المطروحة\n▸ المشكلة المطروحة\n• هل الخيال وهم يضلل الإنسان أم قدرة إبداعية تبني المعرفة والحضارة؟\n▸ المفهوم\n• القدرة على تكوين صور ذهنية\n• خيال استرجاعي (يستعيد ما أدركناه)\n• خيال إبداعي (يبتكر صورًا جديدة)\n▸ الأطروحة السلبية\n• باسكال: المخيلة سيدة الخطأ\n• تضلل وتبتعد عن الواقع\n• مالبرانش: «مجنونة البيت»\n▸ الأطروحة الإيجابية\n• أساس الإبداع الفني والعلمي\n• أينشتاين: الخيال أهم من المعرفة\n• سارتر: الخيال حرية وتجاوز للواقع\n▸ التركيب\n• الخيال المنضبط بالعقل منتج\n• الخيال المنفلت وهم\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تتجاهل دور الخيال في الإبداع والاختراع\n• نقد الأطروحة الثانية: تغفل خطر الخيال المنفلت الذي يشوه إدراك الواقع\n▸ مقالات مقترحة\n• هل الخيال مصدر للوهم أم للإبداع؟\n• ما قيمة الخيال في حياة الإنسان؟\n• دافع عن أطروحة أن الخيال شرط الإبداع\n▸ شرح موسّع\n• اتهم بعض الفلاسفة الخيال بأنه يعيق الوصول إلى الحقيقة لأنه يتأثر بالانفعال والرغبة فيقدم صورًا غير مطابقة للواقع، وقد سماه باسكال سيدة الخطأ. غير أن العلماء والفنانين يعتمدون عليه في بناء الفرضيات والاختراعات واللوحات والروايات، فالفرضية العلمية فكرة خيالية يتحقق منها بالتجربة. ويرى سارتر أن الخيال هو ما يتيح للوعي أن يتجاوز الواقع ويتخيل ما ليس موجودًا، وفي ذلك مظهر لحرية الإنسان. فالخيال ذو وجهين، يصير نافعًا حين يضبطه العقل والتجربة.\n▸ الفلاسفة والأمثلة\n• باسكال: الخيال «سيد الخطأ والزيف».\n• أينشتاين: «الخيال أهم من المعرفة».\n• مثال: خيال العالم في صياغة الفرضية قبل اختبارها.\n▸ للحفظ\n• الخيال أداة للإبداع إذا انضبط بالعقل، ومصدر وهم إذا انفلت منه."},{"title":"5. الشعور واللاشعور","content":"▸ هل الحياة النفسية شعورية فقط؟\n▸ المشكلة المطروحة\n• هل الحياة النفسية كلها شعورية أم أن للاشعور دورًا فيها؟\n▸ المفاهيم\n• الشعور: معرفة الإنسان بما يجري في نفسه\n• اللاشعور: ما يؤثر في السلوك دون وعي به\n▸ الأطروحة الشعورية\n• ديكارت: الأنا أفكر إذن أنا موجود\n• النفس والوعي متطابقان\n• السلوك قابل للتفسير بالشعور وحده\n▸ الأطروحة اللاشعورية (فرويد)\n• الجهاز النفسي: الهو والأنا والأنا الأعلى\n• أدلة: الأحلام، زلات اللسان، النسيان، الأعراض العصابية\n• الكبت والرغبات المكبوتة\n▸ التركيب\n• الشعور جزء من الحياة النفسية\n• للاشعور تأثير يقر به علم النفس الحديث\n• الإنسان أكبر من وعيه\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: يعجز عن تفسير الأحلام وزلات اللسان والدوافع الخفية\n• نقد الأطروحة الثانية: اللاشعور فرضية يصعب التحقق منها وفرويد بالغ في تعميمه\n▸ مقالات مقترحة\n• هل الحياة النفسية شعورية فقط؟\n• هل يمكن إثبات وجود اللاشعور؟\n• دافع عن أطروحة وجود اللاشعور (استقصاء بالوضع)\n▸ شرح موسّع\n• اعتبر ديكارت أن النفس لا تفكر إلا وهي واعية، فجعل الوعي جوهر الأنا. وجاء فرويد ليبين أن كثيرًا من سلوكنا يتحرك بدوافع لا نعيها، وأدلته: الأحلام التي هي حسب رأيه تحقيق مقنّع لرغبات مكبوتة، وزلات اللسان والنسيان التي تكشف معاني خفية، والأعراض العصابية التي تزول عند استحضار الصدمة المكبوتة. ونقد المعارضون هذا الرأي فقالوا إن اللاشعور فرضية يصعب إثباتها تجريبيًا وإنه مجرد شعور غير ملاحظ. والصواب أن للاشعور دورًا لكنه ليس المسيّر الوحيد للإنسان.\n▸ الفلاسفة والأمثلة\n• ديكارت: «أنا أفكر إذن أنا موجود».\n• فرويد: «الأنا ليس سيد بيته».\n• مثال: زلة اللسان التي تكشف فكرة لم يُرد قائلها إعلانها.\n▸ للحفظ\n• الشعور هو مجال الوعي والإرادة، واللاشعور مجال الدوافع الخفية، وهما معًا يكونان الحياة النفسية."},{"title":"6. العادة","content":"▸ المشكلة المطروحة\n▸ المشكلة المطروحة\n• هل العادة تحرر الإنسان وتيسر حياته أم تقيده وتعطل وعيه؟\n▸ المفهوم\n• استعداد مكتسب بالتكرار لأداء سلوك بسهولة وآلية\n• تختلف عن الغريزة (فطرية)\n• طبيعة ثانية (أرسطو)\n▸ الأطروحة السلبية\n• تجمد السلوك وتقتل الإبداع\n• تضعف الإحساس والانتباه\n• روسو: لا نعلّم الطفل أي عادة\n▸ الأطروحة الإيجابية\n• توفر الجهد والوقت\n• تيسر التعلم والمهارات\n• وليم جيمس: العجلة الضخمة للمجتمع\n• أرسطو: الفضائل عادات\n▸ التركيب\n• العادة سلاح ذو حدين\n• المفيد منها ما يخضع للإرادة والوعي\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تغفل أن العادة توفر الجهد وتكوّن المهارات والفضائل\n• نقد الأطروحة الثانية: تتجاهل خطر الجمود والإدمان وتعطيل الوعي\n▸ مقالات مقترحة\n• هل العادة تقيد الإنسان أم تحرره؟\n• ما قيمة العادة في السلوك الإنساني؟\n• قارن بين العادة والغريزة\n▸ شرح موسّع\n• العادة تجعلنا نؤدي أفعالًا معقدة كالكتابة والقيادة بسهولة ودون استحضار الانتباه، فتفرغ الذهن لأمور أخرى، وبها تتكون المهارات والأخلاق. لكنها قد تقود إلى الجمود والروتين وتضعف التجديد، وقد تتحول إلى إدمان على سلوك ضار. ويفرق بين العادة والغريزة بأن الغريزة فطرية موروثة عند كل أفراد النوع، أما العادة فمكتسبة تختلف بين الأفراد وتقبل التغيير. والعادة الجيدة هي التي نصنعها بوعي وتخدم أهدافنا.\n▸ الفلاسفة والأمثلة\n• أرسطو: «الفضيلة عادة».\n• وليم جيمس: العادة هي «العجلة الضخمة المنظمة للمجتمع».\n• روسو: العادة الوحيدة التي ينبغي أن تُغرس في الطفل ألا يكتسب أي عادة.\n▸ للحفظ\n• العادة: تيسير وتوفير للجهد، وخطر الجمود، والمعيار: إخضاعها للوعي والإرادة."},{"title":"7. اللغة والفكر","content":"▸ هل اللغة شرط ضروري للتفكير؟ (جدلية)\n▸ المشكلة المطروحة\n• ما العلاقة بين اللغة والفكر؟ هل اللغة شرط ضروري للتفكير أم مجرد وسيلة للتعبير عنه؟\n▸ الموقف الأول: الاقتران\n• الفكر لا يوجد دون لغة\n• اللغة هي الفكر المنطوق\n• هيجل: نفكر داخل الكلمات\n▸ الموقف الثاني: الانفصال\n• الفكر سابق على اللغة\n• الصم والبكم يفكرون\n• الطفل يفكر قبل أن يتكلم\n• برجسون: الكلمات تقيد الفكر\n▸ التركيب\n• علاقة تأثير وتأثر متبادل\n• اللغة قالب الفكر وأداته\n• الفكر يطور اللغة ويغنيها\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: الصم البكم والأطفال يفكرون دون لغة منطوقة\n• نقد الأطروحة الثانية: الفكر لا يتبلور ولا ينتقل إلى الغير إلا بالألفاظ\n▸ أهم المصطلحات\n• اللغة\n• الفكر\n• الرمز\n• التجريد\n• التواصل\n▸ مقالات مقترحة\n• هل اللغة شرط ضروري للتفكير؟ (جدلية)\n• هل اللغة مجرد أداة للتعبير عن الفكر؟\n• دافع عن أطروحة العلاقة الوثيقة بين اللغة والفكر\n▸ شرح موسّع\n• يرى أنصار الاقتران أن الفكرة تتحدد بالألفاظ، فلا نفكر بوضوح إلا حين نصوغ أفكارنا في كلمات، ولهذا تعتبر اللغة مرآة الفكر ووسيلة التجريد وتكوين المفاهيم. أما أنصار الانفصال فيستدلون بأن الإنسان قد يدرك فكرة ثم يعجز عن التعبير عنها، وبأن الصم البكم والأطفال قبل النطق يمارسون نوعًا من الذكاء. والصواب أن بين اللغة والفكر ارتباطًا وثيقًا دون تطابق تام: الفكر يسبق التعبير في ميلاده، لكنه لا يكتمل ولا ينتقل إلى الآخرين إلا باللغة.\n▸ الفلاسفة والأمثلة\n• هيجل: «نحن نفكر داخل الكلمات».\n• بياجيه: الذكاء الحسي الحركي يظهر عند الطفل قبل اللغة.\n• في الاستعمال اليومي نقول: «على طرف لساني» حين نملك الفكرة ولا نجد اللفظ.\n▸ للحفظ\n• اللغة والفكر متكاملان: الفكر روح اللغة، واللغة جسد الفكر."},{"title":"8. الدال والمدلول ولغة الإنسان والحيوان","content":"▸ هل العلاقة بين الدال والمدلول اعتباطية؟\n▸ المشكلة المطروحة\n• ما طبيعة العلامة اللغوية؟ وبماذا تتميز لغة الإنسان عن وسائل تواصل الحيوان؟\n▸ العلامة اللغوية (دي سوسير)\n• الدال: الصورة الصوتية (اللفظ)\n• المدلول: المعنى أو المفهوم\n• العلاقة بينهما اعتباطية (اصطلاحية)\n▸ لغة الإنسان\n• مزدوجة التمفصل (أصوات ثم كلمات)\n• إبداعية: جمل لا متناهية\n• رمزية مجردة\n• مكتسبة اجتماعيًا ومتغيرة\n▸ تواصل الحيوان\n• إشارات غريزية وراثية\n• محدودة ومرتبطة بالموقف\n• لا تعبر عن الماضي والمستقبل\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: الاعتباطية نسبية: وجود ألفاظ محاكية للأصوات والاشتقاق\n• نقد الأطروحة الثانية: تواصل الحيوان غريزي محدود ولا يبلغ لغة رمزية مبدعة\n▸ أهم المصطلحات\n• الدال\n• المدلول\n• الاعتباطية\n• التمفصل المزدوج\n▸ مقالات مقترحة\n• هل العلاقة بين الدال والمدلول اعتباطية؟\n• قارن بين لغة الإنسان ووسائل تواصل الحيوان\n• هل يمكن القول إن للحيوان لغة؟\n▸ شرح موسّع\n• اللغة نظام من العلامات، وكل علامة وجه ذو شقين: دال ومدلول، كما أن الورقة لها وجهان لا ينفصلان. وتسمية الشيء بلفظ معين عرف متفق عليه، ولذلك تختلف الألفاظ من لغة إلى أخرى للمعنى الواحد. أما لغة الإنسان فتتميز بالتمفصل المزدوج الذي تحدث عنه مارتينيه: نركّب بعدد محدود من الأصوات كلمات، وبالكلمات جملًا بلا حصر. وفي المقابل تظل رقصات النحل التي درسها كارل فون فريش وسيلة تواصل فطرية ثابتة تدل على مكان الغذاء دون إبداع.\n▸ الفلاسفة والأمثلة\n• كارل فون فريش: رقصة النحل تدل على اتجاه الغذاء وبعده، لكنها لا تتغير ولا تتعلمها النحلة.\n• دي سوسير: العلامة اللغوية «ليست ربطًا بين اسم وشيء بل بين مفهوم وصورة سمعية».\n▸ للحفظ\n• الدال + المدلول = علامة، واللغة الإنسانية رمزية مجردة مبدعة، وتواصل الحيوان غريزي محدود."},{"title":"9. المنطق الصوري","content":"▸ المشكلة المطروحة\n▸ المشكلة المطروحة\n• ما قيمة المنطق الصوري الأرسطي؟ هل يضمن صدق الفكر وإنتاج معرفة جديدة؟\n▸ تعريفه\n• علم يدرس صورة الفكر لا مادته\n• أسسه أرسطو\n• غايته: ضمان اتساق الفكر مع نفسه\n▸ قوانين الفكر\n• الهوية: أ هو أ\n• عدم التناقض\n• الثالث المرفوع\n▸ القياس\n• مقدمتان ونتيجة\n• مثال: كل إنسان فانٍ، سقراط إنسان، إذن سقراط فانٍ\n• يشترط حد أوسط وقواعد شكلية\n▸ النقد\n• عقم النتيجة: لا يضيف جديدًا\n• المصادرة على المطلوب (ميل)\n• بيكون: غير صالح لكشف الطبيعة\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: يقتصر على الشكل ولا ينتج معرفة جديدة (عقيم)\n• نقد الأطروحة الثانية: يبقى ضروريًا لضمان اتساق الفكر وكشف المغالطات\n▸ مقالات مقترحة\n• هل المنطق الصوري قادر على إنتاج معرفة جديدة؟\n• ما قيمة القياس الأرسطي؟\n• قارن بين الاستدلال الصوري والاستدلال التجريبي\n▸ شرح موسّع\n• يهتم المنطق الصوري بشكل الاستدلال ولا يعنى بمطابقة الأفكار للواقع، فهو يضمن اتساق النتيجة مع المقدمات. ويقوم القياس على اندراج الحالة الجزئية تحت قضية كلية. وقد أفاد في تنظيم الفكر وكشف المغالطات وتدريس العلوم. لكن بيكون رأى أنه لا يصلح للكشف عن حقائق الطبيعة، وبيّن ستيوارت ميل أن القياس يقع في مصادرة على المطلوب لأن المقدمة الكبرى تفترض النتيجة سلفًا. ولذلك ظهر المنهج التجريبي والمنطق الرياضي الحديث ليكملا ما عجز عنه.\n▸ الفلاسفة والأمثلة\n• القياس الأرسطي: كل إنسان فانٍ (مقدمة كبرى) - سقراط إنسان (مقدمة صغرى) - إذن سقراط فانٍ (نتيجة).\n• ميل: قولنا «كل إنسان فانٍ» يفترض أن سقراط فانٍ من قبل، فالقياس دور.\n▸ للحفظ\n• المنطق الصوري يضمن سلامة الاستدلال شكليًا لكنه لا ينتج معرفة جديدة، وقوانينه: الهوية وعدم التناقض والثالث المرفوع."},{"title":"10. الرياضيات: أصلها والاستدلال الرياضي","content":"▸ هل أصل الرياضيات العقل أم الحواس؟ (جدلية)\n▸ المشكلة المطروحة\n• ما مصدر المعرفة الرياضية: العقل أم التجربة؟ وما خصائص الاستدلال الرياضي؟\n▸ الموقف العقلي\n• الرياضيات من العقل وحده\n• أفكار فطرية (أفلاطون، ديكارت)\n• مبادئ قبلية (كانط)\n▸ الموقف التجريبي\n• الرياضيات مستمدة من التجربة والحواس\n• ستيوارت ميل: الاستقراء\n• الهندسة نشأت من قياس الأراضي\n▸ خصائص الاستدلال الرياضي\n• استنباطي من مسلمات وتعريفات\n• يقيني ومجرد\n• يلتزم بقواعد البرهان\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: الأعداد والأشكال نشأت من الواقع (العد، قياس الأراضي)\n• نقد الأطروحة الثانية: التجربة لا تفسر يقينية الرياضيات ولا مفاهيمها المجردة\n▸ أهم المصطلحات\n• المسلمة\n• البديهية\n• البرهان\n• الاستنباط\n• التجريد\n▸ مقالات مقترحة\n• هل أصل الرياضيات العقل أم الحواس؟ (جدلية)\n• ما خصائص الاستدلال الرياضي؟ (تحليل نص بلانشي)\n• دافع عن الأطروحة القائلة بعقلانية الرياضيات\n▸ شرح موسّع\n• يرى العقليون أن الأعداد والأشكال الهندسية المثالية لا وجود لها في الواقع الحسي، فالدائرة الكاملة مثلًا لا نراها بالعين، لذا مصدرها العقل. ويعارضهم التجريبيون بأن الطفل يتعلم العد من الأشياء الحسية، وأن الهندسة بدأت بحاجات الحياة. والموقف الأقرب أن الرياضيات تنطلق من الواقع ثم يجردها العقل ويبني عليها بناءً استنباطيًا مستقلًا. وفي الاستدلال الرياضي ننطلق من مسلمات وتعريفات ونصل بالبرهان إلى نتائج لازمة، ويكون البناء الاستنتاجي كما بيّن بلانشي في نصه.\n▸ الفلاسفة والأمثلة\n• ديكارت: الأفكار الواضحة المتميزة فطرية في العقل.\n• ستيوارت ميل: القضايا الرياضية تعميمات من التجربة.\n• كانط: الزمان والمكان صورتان قبليتان للحساسية، يقوم عليهما الحساب والهندسة.\n▸ للحفظ\n• الرياضيات: عقل (العقليون) أو تجربة (التجريبيون)، والتركيب: انطلاق من الواقع وتجريد عقلي وبناء استنباطي."},{"title":"11. المنهج التجريبي وقيمة الفرضية","content":"▸ هل المنهج التجريبي مقياس العلم؟\n▸ المشكلة المطروحة\n• كيف يصل العالم إلى القوانين العلمية؟ وما قيمة الفرضية في المنهج التجريبي؟\n▸ خطواته\n• الملاحظة\n• الفرضية\n• التجربة (التحقق)\n• القانون\n▸ الفرضية\n• تفسير مؤقت للظاهرة\n• يبتكرها خيال العالم المنضبط\n• تحتاج إلى تحقق وتجريب\n• قيمتها: توجه البحث\n▸ شروط الفرضية\n• قابلة للاختبار\n• غير متناقضة مع حقائق ثابتة\n• بسيطة\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: المنهج التجريبي لا يناسب كل الظواهر كالرياضيات والإنسانيات\n• نقد الأطروحة الثانية: الفرضية دون تحقق تجريبي تبقى مجرد تخمين\n▸ أهم المصطلحات\n• الملاحظة\n• الفرضية\n• التجربة\n• القانون العلمي\n• الحتمية\n▸ مقالات مقترحة\n• هل المنهج التجريبي مقياس العلم؟\n• هل يمكن الاستغناء عن الفرضية في المنهج التجريبي؟\n• قارن بين المنهج التجريبي والمنهج الرياضي\n▸ شرح موسّع\n• يبدأ البحث التجريبي بملاحظة ظاهرة تثير سؤالًا، ثم يضع الباحث فرضية تفسرها، ثم يتحقق منها بتجربة مضبوطة يغير فيها عاملًا ويثبّت بقية العوامل. فإن أيدت النتائج الفرضية صارت قانونًا، وإن ناقضتها عُدّلت أو أُبطلت. وقد أكد كلود برنار أن الفرضية ضرورية لأن الملاحظة دون فكرة موجهة تبقى عمياء. ومن أشهر الأمثلة تجربة باسكال في جبل بوي دي دوم لإثبات أن عمود الزئبق يتأثر بالضغط الجوي. ولا يقوم المنهج على الاستقراء وحده بل على تكامل العقل والتجربة.\n▸ الفلاسفة والأمثلة\n• كلود برنار: «الفكرة هي مبدأ كل برهان، ومصدر كل اختراع».\n• تجربة باسكال: انخفاض ارتفاع الزئبق كلما صعدنا الجبل، فثبتت فرضية الضغط الجوي.\n▸ للحفظ\n• خطوات المنهج التجريبي: ملاحظة ثم فرضية ثم تجربة ثم قانون، والفرضية روحه."},{"title":"12. الاستقراء وتبريره","content":"▸ هل أساس الاستقراء تجريبي أم عقلي؟\n▸ المشكلة المطروحة\n• على ماذا يعتمد تعميم النتائج الجزئية في الاستقراء؟ وهل يمكن تبريره؟\n▸ تعريفه\n• الانتقال من الجزئيات إلى حكم كلي\n• تام (يشمل كل الحالات)\n• ناقص (يعمم من عينة)\n▸ مبررات الاستقراء\n• مبدأ السببية\n• مبدأ اطراد الحوادث وثبات قوانين الطبيعة (ميل)\n• مبدأ الحتمية\n▸ نقد الاستقراء\n• هيوم: مجرد عادة نفسية لا يقين فيه\n• بوبر: بديل التكذيب بدل التحقق\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: مبدأ السببية افتراض لا دليل منطقي عليه\n• نقد الأطروحة الثانية: إنكار السببية يهدم العلم الذي حقق نجاحًا عمليًا\n▸ أهم المصطلحات\n• الاستقراء\n• التعميم\n• السببية\n• الحتمية\n• التكذيب\n▸ مقالات مقترحة\n• هل أساس الاستقراء تجريبي أم عقلي؟\n• كيف نبرر الانتقال من الجزئي إلى الكلي في الاستقراء؟\n• دافع عن مشروعية الاستقراء\n▸ شرح موسّع\n• الاستقراء الناقص هو الذي تعتمد عليه العلوم التجريبية، فنقول مثلًا: كل الحديد يتمدد بالحرارة بعد تجريبه على عينات. وقد طرح الفلاسفة سؤال: بماذا نبرر هذا التعميم؟ فأجاب التجريبيون كميل بأن الطبيعة منتظمة تسير بقوانين ثابتة، وأن لكل حادثة سببًا. أما هيوم فعدّ فكرة السببية عادة ذهنية تولدت من تكرار التتابع، فلا يقين منطقيًا في التعميم. وجاء بوبر ليقول إن العلم يتقدم بمحاولات التفنيد والتكذيب لا بتكديس الشواهد.\n▸ الفلاسفة والأمثلة\n• المثال: «الحديد يتمدد بالحرارة» حكم عام انطلقنا فيه من تجارب جزئية.\n• هيوم: لأننا رأينا الشمس تشرق كل يوم نتوقع شروقها غدًا بحكم العادة.\n• بوبر: ألف شاهد لا يثبت نظرية، وشاهد واحد قد يدحضها.\n▸ للحفظ\n• الاستقراء يقوم على السببية والحتمية، وقد انتقده هيوم وجاء بوبر بمعيار التكذيب."},{"title":"13. العلوم الإنسانية والظاهرة الإنسانية","content":"▸ هل يمكن دراسة الظاهرة الإنسانية بمنهج علمي؟\n▸ المشكلة المطروحة\n• هل يمكن دراسة الظاهرة الإنسانية بمنهج علمي موضوعي؟\n▸ الظاهرة الإنسانية\n• نفسية واجتماعية وتاريخية واقتصادية\n• معقدة ومتغيرة\n• مرتبطة بالوعي والحرية والقيم\n▸ الصعوبات\n• الذاتية: الباحث جزء من الموضوع\n• صعوبة التجريب والتكرار\n• تعدد العوامل\n• تأثر الظاهرة بالملاحظة\n▸ محاولات الموضوعية\n• دوركايم: تعامل الظواهر كأشياء\n• الاستبيان والمقابلة والإحصاء\n• دراسة الحالة\n• الجمع بين التفسير والفهم\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: الصعوبات لا تلغي إمكان الموضوعية بمناهج مناسبة\n• نقد الأطروحة الثانية: الإنسان واعٍ حر يصعب إخضاعه لقوانين صارمة\n▸ أهم المصطلحات\n• الظاهرة الإنسانية\n• الموضوعية\n• الذاتية\n• التفسير\n• الفهم\n▸ مقالات مقترحة\n• هل يمكن دراسة الظاهرة الإنسانية بمنهج علمي؟\n• ما صعوبات العلوم الإنسانية؟\n• قارن بين الظاهرة الإنسانية والظاهرة الطبيعية\n▸ شرح موسّع\n• تهتم العلوم الإنسانية (علم النفس، علم الاجتماع، التاريخ، الاقتصاد) بالإنسان وسلوكه. ويرى المعارضون أن الإنسان كائن واعٍ حر يتغير يوميًا، فلا يمكن إخضاعه لقوانين صارمة كما في الفيزياء. لكن علماء مثل دوركايم نادوا بدراسة الظواهر الاجتماعية بموضوعية كأنها أشياء، مبتعدين عن الأحكام المسبقة، واستعانوا بالإحصاء والمقارنة. وقد أضاف ديلتاي الفهم الداخلي لمقاصد الإنسان إلى التفسير السببي. فالمنهج التجريبي ممكن بدرجة، وتكتمل صورته بمناهج مكملة كالمنهج التاريخي والكيفي.\n▸ الفلاسفة والأمثلة\n• دوركايم في دراسته للانتحار اعتمد الإحصاءات للربط بين معدلاته وظروف المجتمع.\n• ديلتاي: «الطبيعة نفسرها، والحياة النفسية نفهمها».\n▸ للحفظ\n• العلوم الإنسانية تدرس الإنسان بمنهج يجمع الموضوعية والفهم ويتكيف مع خصوصية الظاهرة."},{"title":"14. المنهج التجريبي والمادة الحية","content":"▸ هل يمكن تطبيق المنهج التجريبي على المادة الحية؟\n▸ المشكلة المطروحة\n• هل يمكن تطبيق المنهج التجريبي على المادة الحية كما يطبق على المادة الجامدة؟\n▸ الصعوبات\n• تعقيد الكائن الحي وترابط أعضائه\n• الاختلاف الفردي بين الكائنات\n• التجريب قد يؤدي إلى موت الحي أو تغير سلوكه\n• الاعتبارات الأخلاقية\n▸ ردود العلماء\n• الحتمية تسري على الحي والجامد (كلود برنار)\n• الوسط الداخلي ثابت نسبيًا\n• استعمال الإحصاء والحيوانات والمجاهر والتصوير\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تقدم العلم وفّر وسائل تتجاوز كثيرًا من هذه الصعوبات\n• نقد الأطروحة الثانية: خصوصية الحي والضوابط الأخلاقية تفرض قيودًا على التجريب\n▸ أهم المصطلحات\n• المادة الحية\n• التشريح\n• الوسط الداخلي\n• الحتمية\n▸ مقالات مقترحة\n• هل يمكن تطبيق المنهج التجريبي على المادة الحية؟\n• قارن بين تطبيق المنهج التجريبي على الحي والجامد\n▸ شرح موسّع\n• يرى بعضهم أن للحياة خصوصية تمنع إخضاعها للتجريب، فلكل كائن حي وحدة عضوية كلية إن فُكّك فقد حياته، ولا تتكرر التجربة بنفس الشروط. ويرد كلود برنار بأن الحتمية العلمية قائمة في الظواهر الحيوية كما في الجامدة، وأن هناك وسطًا داخليًا ثابتًا يمكن دراسته، وأن التطور التقني أتاح وسائل جديدة كالتشريح الحي والتحاليل والإحصاء. ويبقى الأمر مقيدًا بضوابط أخلاقية تحمي الإنسان والحيوان من أي أذى لا مبرر له.\n▸ الفلاسفة والأمثلة\n• كلود برنار: درس وظيفة الكبد وإفراز السكر (الوظيفة الغليكوجينية) بتجارب على الحيوان، وأقرّ الحتمية في الفيزيولوجيا.\n• ومن الأمثلة اللقاحات لدى باستور.\n▸ للحفظ\n• تطبيق المنهج التجريبي على الحي ممكن مع مراعاة خصوصيته وضوابطه الأخلاقية."},{"title":"15. الحقيقة: مطلقة أم نسبية؟","content":"▸ هل الحقيقة مطلقة أم نسبية؟\n▸ المشكلة المطروحة\n• هل الحقيقة ثابتة مطلقة في كل زمان ومكان أم نسبية تتغير بتغير الأفراد والظروف؟\n▸ الأطروحة المطلقة\n• الحقائق العقلية ثابتة (الرياضيات، المنطق)\n• ديكارت: الحقائق الواضحة المتميزة\n• أفلاطون: عالم المثل الثابت\n▸ الأطروحة النسبية\n• البراغماتية (وليم جيمس): الحقيقة ما ينفع ويحقق النجاح\n• الوجودية (كيركغارد، سارتر): الحقيقة ذاتية تُعاش\n• العلم الحديث يعدل نظرياته (نيوتن ثم أينشتاين)\n▸ التركيب\n• حقائق مطلقة في الرياضيات والمنطق\n• حقائق نسبية في العلوم التجريبية والإنسانية\n• الحقيقة تتطور وتقترب من المطلق\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: العلم يعدل نظرياته فلا مطلق في التجريبيات\n• نقد الأطروحة الثانية: النسبية المطلقة تهدم اليقين في الرياضيات والمنطق\n▸ أهم المصطلحات\n• الحقيقة\n• المطلق\n• النسبي\n• البراغماتية\n• الوجودية\n▸ مقالات مقترحة\n• هل الحقيقة مطلقة أم نسبية؟\n• قارن بين المذهب البراغماتي والمذهب الوجودي\n• دافع عن الأطروحة القائلة بنسبية الحقيقة\n▸ شرح موسّع\n• يرى العقلانيون أن هناك حقائق مطلقة لا تتغير كقولنا إن المثلث له ثلاث زوايا، لأنها تقوم على البداهة العقلية. بينما يرى البراغماتيون أن الفكرة تكون حقيقية بقدر ما تنجح في التطبيق وتحقق المنفعة، ويؤكد الوجوديون أن الحقيقة تجربة فردية معاشة لا قوالب جاهزة. والمعطيات العلمية تؤكد النسبية لأن النظريات تتطور، كما حل أينشتاين محل نيوتن في بعض التفسيرات. فالحقيقة مطلقة في المجالات الصورية ونسبية في المجالات التجريبية والإنسانية.\n▸ الفلاسفة والأمثلة\n• وليم جيمس: «الفكرة الصادقة هي التي تنجح في الاختبار العملي».\n• كيركغارد: «الحقيقة هي الذاتية».\n• مثال: نظرية نيوتن في الجاذبية صحيحة في نطاق معين ثم دقّقتها النسبية.\n▸ للحفظ\n• الحقيقة: مطلقة في الرياضيات والمنطق، نسبية في التجريب والعلوم الإنسانية."},{"title":"16. القيمة الخلقية: مطلقة أم نسبية؟","content":"▸ هل القيم الأخلاقية ثابتة مطلقة أم نسبية متغيرة؟\n▸ المشكلة المطروحة\n• هل القيم الأخلاقية ثابتة مطلقة أم نسبية تتغير بتغير المجتمعات والأزمنة؟\n▸ الموقف المطلق\n• مصدرها العقل أو الدين أو الفطرة\n• كونية وثابتة\n• كانط: الأمر المطلق والواجب\n▸ الموقف النسبي\n• مصدرها المجتمع والبيئة\n• تختلف باختلاف الثقافات\n• دوركايم: الأخلاق ظاهرة اجتماعية\n• الماركسية: انعكاس للبنية الاقتصادية\n▸ التركيب\n• ثبات المبادئ العامة (العدل، الصدق)\n• تغير صيغ التطبيق بتغير الظروف\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تغفل اختلاف الأعراف والثقافات\n• نقد الأطروحة الثانية: تجعل الأخلاق مجرد ذوق رغم وجود قيم مشتركة\n▸ أهم المصطلحات\n• القيمة الخلقية\n• الواجب\n• الضمير\n• النسبية\n• الإلزام\n▸ مقالات مقترحة\n• هل القيم الأخلاقية ثابتة مطلقة أم نسبية متغيرة؟\n• ما مصدر الإلزام الأخلاقي؟\n• قارن بين الأخلاق العقلية والأخلاق الاجتماعية\n▸ شرح موسّع\n• يرى كانط أن الأخلاق لا تقوم على النتائج بل على النية الحسنة واحترام الواجب لذاته، وأن القاعدة الأخلاقية كونية: افعل بحيث تعامل الإنسانية في شخصك وفي غيرك غاية لا وسيلة. في المقابل يرى دوركايم أن المجتمع هو مصدر الإلزام الخلقي، ولذلك تتغير القيم من مجتمع إلى آخر. وتبين المقارنة أن هناك قيمًا مشتركة بين الشعوب كتحريم القتل والكذب والخيانة وتقدير العدل، لكن الأعراف التفصيلية تتنوع. فالقيمة الخلقية ثابتة في جوهرها نسبية في صورها.\n▸ الفلاسفة والأمثلة\n• كانط: «افعل بحيث تعامل الإنسانية، في شخصك وفي شخص غيرك، دائمًا كغاية وليس كوسيلة فقط».\n• دوركايم: الواجب الأخلاقي يفرضه المجتمع بما له من سلطة معنوية على الأفراد.\n▸ للحفظ\n• القيم الأخلاقية: مبادئ ثابتة (كانط) وتطبيقات متغيرة (دوركايم)، والعدل والصدق قيمتان مشتركتان."},{"title":"17. الأسرة (العلاقات الأسرية)","content":"▸ هل الأسرة مؤسسة اجتماعية ضرورية؟\n▸ المشكلة المطروحة\n• هل الأسرة مؤسسة اجتماعية ضرورية أم أنها شكل اجتماعي يمكن الاستغناء عنه؟\n▸ مفهوم الأسرة\n• جماعة تربطها صلة الزواج والدم\n• نواة المجتمع\n• أشكالها: نووية وممتدة\n▸ الأطروحة: الأسرة ضرورية\n• وظيفة بيولوجية وتربوية ونفسية واقتصادية\n• دوركايم: الأسرة نظام اجتماعي أساسي\n• مصدر الأمن والتنشئة الاجتماعية\n▸ الأطروحة: الأسرة غير ضرورية\n• أفلاطون: إلغاؤها عند الحراس\n• إنجلز: الأسرة نتاج الملكية الخاصة\n• دافيد كوبر: انتقاد الأسرة\n• تجارب جماعية (كالكيبوتس)\n▸ التركيب\n• الأسرة ضرورية في وظيفتها، متغيرة في شكلها\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: تتجاهل تغير أشكال الأسرة واختلال بعضها\n• نقد الأطروحة الثانية: لا بديل عنها في التنشئة والأمان النفسي\n▸ مقالات مقترحة\n• هل الأسرة مؤسسة اجتماعية ضرورية؟\n• ما وظائف الأسرة؟\n• دافع عن ضرورة الأسرة (استقصاء بالوضع)\n▸ شرح موسّع\n• تؤدي الأسرة وظائف متعددة: إنجاب الأطفال، التنشئة الاجتماعية وتعليم اللغة والقيم، الإشباع العاطفي، والتضامن الاقتصادي. ويرى دوركايم أنها جماعة تضمن استمرار المجتمع. ويعارض بعضهم ضرورتها، فأفلاطون في «الجمهورية» رأى أن الحراس يجب أن يتخلوا عن الأسرة الخاصة تفاديًا للأنانية، وماركس وإنجلز ربطا نشأتها بالملكية الخاصة وانتقدا أشكالها. لكن التجارب الحديثة تبين أن غياب الأسرة يضعف التنشئة والأمان النفسي. وما يتغير هو شكل الأسرة وأدوارها، لا الحاجة إليها.\n▸ الفلاسفة والأمثلة\n• دوركايم: الأسرة هي أول وسط اجتماعي يتعلم فيه الطفل.\n• إنجلز: «أصل العائلة والملكية الخاصة والدولة».\n• أفلاطون: «الجمهورية» (الكتاب الخامس) في إلغاء الأسرة عند الحراس.\n▸ للحفظ\n• الأسرة ضرورية لوظائفها (بيولوجية، تربوية، نفسية)، وشكلها يتغير بتغير المجتمعات."},{"title":"18. الدولة","content":"▸ المشكلة المطروحة\n▸ المشكلة المطروحة\n• هل قيام الدولة ضروري للإنسان والمجتمع؟\n▸ مفهوم الدولة\n• شعب وإقليم وسلطة سياسية ذات سيادة\n• تحتكر القوة المشروعة\n• تنظم الحقوق والواجبات\n▸ الأطروحة: الدولة ضرورية\n• أرسطو وابن خلدون: الإنسان مدني بالطبع\n• هوبز: حالة الطبيعة حرب الجميع ضد الجميع\n• روسو ولوك: العقد الاجتماعي\n▸ الأطروحة: الدولة غير ضرورية\n• الماركسية: أداة طبقية تزول بزوال الطبقات\n• الفوضوية (برودون، باكونين): الدولة قهر للحرية\n▸ التركيب\n• ضرورة الدولة مع مراقبتها وتقييدها بالقانون والديمقراطية\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: قد تتحول إلى استبداد إن غابت الرقابة والقانون\n• نقد الأطروحة الثانية: غياب الدولة يعني الفوضى وضياع الحقوق\n▸ مقالات مقترحة\n• هل قيام الدولة ضروري؟\n• ما أساس الدولة: القوة أم العقد؟\n• دافع عن أطروحة ضرورة الدولة\n▸ شرح موسّع\n• يرى ابن خلدون أن الإنسان لا يعيش وحده فيحتاج إلى التعاون، والتعاون يقتضي وازعًا يمنع التظالم، وهو الحاكم، ومن هنا ظهرت الدولة. ويذهب هوبز إلى أن الناس في الحالة الطبيعية يتصارعون على المصالح، فيتنازلون عن حريتهم للحاكم المطلق مقابل الأمن. أما روسو فيجعل أساسها عقدًا بين الأفراد والإرادة العامة. ويرد المعارضون بأن الدولة قد تصبح أداة استغلال، فيرى ماركس أنها تعبر عن مصالح الطبقة المسيطرة. والموقف المتوازن: الدولة ضرورية لكن شرعيتها بالعدل والقانون ومشاركة المواطنين.\n▸ الفلاسفة والأمثلة\n• هوبز: «الإنسان ذئب لأخيه الإنسان» (الليفياثان).\n• ابن خلدون: «الإنسان مدني بالطبع».\n• روسو: «العقد الاجتماعي»: الإنسان يولد حرًا وهو في كل مكان مقيد بالأغلال.\n▸ للحفظ\n• الدولة ضرورية لتنظيم الحياة وضمان الأمن والعدل، بشرط أن تخضع للقانون وإرادة الشعب."},{"title":"19. العدالة الاجتماعية: مساواة أم تفاوت؟","content":"▸ هل تتحقق العدالة الاجتماعية بالمساواة أم بالتفاوت؟\n▸ المشكلة المطروحة\n• هل تتحقق العدالة الاجتماعية بالمساواة بين الجميع أم بالتفاوت بحسب الاستحقاق؟\n▸ مفهوم العدالة\n• إعطاء كل ذي حق حقه\n• توزيع الحقوق والثروات والفرص\n• ارتباطها بالقانون والأخلاق\n▸ الأطروحة: المساواة\n• الناس متساوون في الكرامة والحقوق\n• روسو: التفاوت مصدر الظلم\n• الفكر الاشتراكي: لكل حسب حاجته\n▸ الأطروحة: التفاوت\n• أرسطو: العدالة توزيع بحسب الاستحقاق\n• الليبرالية: المكافأة بحسب الجهد والكفاءة\n• المساواة المطلقة تقتل الحافز\n▸ التركيب\n• مساواة في الحقوق والفرص، وتفاوت مشروع بحسب الكفاءة والعمل\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: المساواة المطلقة تقتل الحافز وتهمل الاستحقاق\n• نقد الأطروحة الثانية: التفاوت المفرط يولد الظلم ويخل بتكافؤ الفرص\n▸ مقالات مقترحة\n• هل تتحقق العدالة الاجتماعية بالمساواة أم بالتفاوت؟\n• ما معيار العدالة؟\n• دافع عن مبدأ المساواة (استقصاء بالوضع)\n▸ شرح موسّع\n• يعتبر أنصار المساواة أن الناس خُلقوا أحرارًا متساوين، وأن اختلاف الثروات والفرص يولد الظلم ويزرع الأحقاد، لذلك يدعون إلى تقليص الفوارق. بينما يرى أرسطو أن العدالة هي المساواة بين المتساوين وعدم المساواة بين غير المتساوين، أي أن يأخذ كل بحسب استحقاقه ومساهمته. ويحذر الليبراليون من أن المساواة الكاملة تلغي حافز العمل والإبداع. والحل أن تكون العدالة ضمان تكافؤ الفرص والحقوق الأساسية للجميع مع الاعتراف بالتفاوت الناتج عن اختلاف الجهد والكفاءة.\n▸ الفلاسفة والأمثلة\n• أرسطو: العدالة التوزيعية تعطي كل واحد بحسب استحقاقه.\n• ماركس: «من كل حسب طاقته، ولكل حسب حاجته».\n• رولز: يجب أن تكون الفوارق في مصلحة الأقل حظًا.\n▸ للحفظ\n• العدالة = مساواة في الحقوق والفرص + تفاوت مشروع بحسب الاستحقاق."},{"title":"20. السياسة والأخلاق","content":"▸ هل السياسة منفصلة عن الأخلاق؟\n▸ المشكلة المطروحة\n• هل يجب أن تخضع السياسة للأخلاق؟ أم أن للسياسة منطقها الخاص القائم على المصلحة؟\n▸ الموقف الفاصل (الواقعي)\n• السياسة ميدان القوة والمصلحة\n• ميكيافيلي: الحاكم يوازن بين الأخلاق ونجاح الدولة\n• الأخلاق للأفراد لا للدول\n▸ الموقف الرابط\n• السياسة لا تقوم بدون عدالة وشرعية\n• أفلاطون: الحاكم الفيلسوف الفاضل\n• كانط: السلام الدائم\n▸ التركيب\n• أخلاق المسؤولية (فيبر)\n• السياسة وسيلة لتحقيق الخير العام\n• رقابة الشعب والقانون\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: فصل السياسة عن الأخلاق يبرر الظلم ويفقد الحكم شرعيته\n• نقد الأطروحة الثانية: المثالية المحضة قد تهمل ضرورات الواقع والمصلحة العامة\n▸ أهم المصطلحات\n• السياسة\n• الأخلاق\n• المصلحة\n• الشرعية\n• العدالة\n▸ مقالات مقترحة\n• هل السياسة منفصلة عن الأخلاق؟\n• هل يجب أن تخضع السياسة للأخلاق؟\n• دافع عن أطروحة ارتباط السياسة بالأخلاق\n▸ شرح موسّع\n• يقول الواقعيون إن الحاكم الذي يتقيد بالفضائل المطلقة قد يفشل في حماية دولته، لذلك يقدمون المصلحة والفعالية، وهو ما يعرف في الفكر الميكيافيلي. أما المثاليون فيرون أن الحكم بلا أخلاق يتحول إلى استبداد ويفقد شرعيته. ويرى ماكس فيبر أن السياسي يحتاج إلى «أخلاق المسؤولية» أي إلى تحمل نتائج قراراته. والصواب أن السياسة لا تنفصل عن الأخلاق، لأن الغاية من الدولة تحقيق العدل والأمن والخير العام.\n▸ الفلاسفة والأمثلة\n• أفلاطون في «الجمهورية» يرى أن يحكم الفلاسفة لأنهم أعرف بالخير.\n• ميكيافيلي في «الأمير» يشرح كيف يحافظ الحاكم على سلطته ولو خالف الفضائل أحيانًا.\n• كانط في «مشروع السلام الدائم» يرى أن السلام غاية أخلاقية للسياسة.\n▸ للحفظ\n• السياسة تحتاج الأخلاق لتكون عادلة وشرعية، والأخلاق تحتاج السياسة لتتجسد في الواقع."},{"title":"21. الحتمية واللاحتمية","content":"▸ هل مبدأ الحتمية مطلق في العلوم؟\n▸ المشكلة المطروحة\n• هل تخضع الظواهر لقوانين صارمة ثابتة (حتمية) أم يسودها الاحتمال واللايقين؟\n▸ مفهوم الحتمية\n• كل ظاهرة لها سبب، وبنفس الأسباب نفس النتائج\n• لابلاس: العالم قابل للتنبؤ الكامل\n• كلود برنار: حتمية الظواهر الحية والجامدة\n▸ اللاحتمية\n• هايزنبرغ: مبدأ اللايقين في الفيزياء الذرية\n• ميكانيكا الكم: قوانين احتمالية\n• حرية الإنسان تتعارض مع الحتمية الصارمة\n▸ التركيب\n• الحتمية قائمة في الفيزياء الكلاسيكية\n• الاحتمال في الميكروفيزياء\n• الحتمية النسبية لا تلغي العلم\n▸ نقد الأطروحتين\n• نقد الأطروحة الأولى: عجزت أمام اللايقين في فيزياء الذرة وتتعارض مع الحرية\n• نقد الأطروحة الثانية: اللايقين لا يعني غياب القوانين فالاحتمال قانون دقيق\n▸ أهم المصطلحات\n• الحتمية\n• السببية\n• الاحتمال\n• اللايقين\n• القانون العلمي\n▸ مقالات مقترحة\n• هل مبدأ الحتمية مطلق في العلوم؟\n• هل تتعارض الحتمية مع حرية الإنسان؟\n• دافع عن مبدأ الحتمية\n▸ شرح موسّع\n• قامت العلوم الكلاسيكية على أن لكل ظاهرة سببًا ثابتًا، حتى تخيّل لابلاس عقلًا يعرف حالة الكون الآن فيتنبأ بكل ما سيحدث. وجاءت فيزياء الذرة فبينت أن قياس موضع الجسيم وسرعته معًا لا يمكن أن يكون دقيقًا، كما في مبدأ اللايقين لهايزنبرغ، فصارت القوانين احتمالية. ومع ذلك لم يلغِ ذلك العلم، فهو في الظواهر الكبرى ما زال يعتمد على قوانين دقيقة. وفي ميدان الإنسان يفرق الفلاسفة بين الحتمية الطبيعية وحرية الإرادة التي تقتضي إمكان الاختيار.\n▸ الفلاسفة والأمثلة\n• لابلاس: عقل يعرف كل القوى والحالات يستطيع التنبؤ بالمستقبل كالماضي.\n• هايزنبرغ: لا يمكن تحديد موضع الإلكترون وسرعته بدقة في آنٍ واحد.\n• كلود برنار: الحتمية شرط العلم.\n▸ للحفظ\n• الحتمية مبدأ العلم الكلاسيكي، والاحتمال سمة الفيزياء الذرية، والموقف: حتمية نسبية."},{"title":"22. منهجية المقالة الفلسفية وتحليل النص","content":"▸ المشكلة المطروحة\n▸ المقالة الجدلية\n• مقدمة: تمهيد، مشكلة، سؤال\n• عرض الأطروحة الأولى بحججها وأمثلتها ثم نقدها\n• عرض الأطروحة المقابلة ثم نقدها\n• التركيب (الحل المتجاوز)\n• خاتمة: حل المشكلة والموقف الشخصي\n▸ مقالة المقارنة\n• مقدمة تحدد المفهومين\n• أوجه الشبه\n• أوجه الاختلاف\n• العلاقة والتقييم\n• خاتمة\n▸ الاستقصاء بالوضع\n• مقدمة وطرح المشكلة\n• عرض الأطروحة المراد الدفاع عنها\n• الحجج والبراهين والأمثلة\n• الرد على الشبهات والاعتراضات\n• خاتمة\n▸ الاستقصاء بالرفع\n• مقدمة\n• عرض الأطروحة المراد نقضها\n• إبطال حججها وبيان تناقضها\n• عرض البديل\n• خاتمة\n▸ تحليل النص\n• المقدمة: صاحب النص وموضوعه\n• المشكلة والأطروحة\n• الحجج والمفاهيم الأساسية\n• المناقشة (التقييم)\n• الخاتمة\n▸ شرح موسّع\n• ابدأ دائمًا بفهم السؤال وتحديد مفاهيمه وحصر المشكلة الفلسفية قبل الكتابة، ثم ضع خطة واضحة من مقدمة وعرض وخاتمة. اعتمد في كل فقرة على فكرة واحدة مدعومة بالحجة والمثال والمرجع الفلسفي (اسم الفيلسوف وفكرته). تجنب سرد الدرس كما هو، بل اربط المعلومات بسؤال المقالة. وفي الجدلية يجب أن يكون التركيب إضافة جديدة لا تلخيصًا. وفي النص ابدأ بفهم فكرته المحورية قبل التعليق. وتأكد من توزيع الوقت واحترام الترقيم وجودة الأسلوب.\n▸ الفلاسفة والأمثلة\n• نموذج مقدمة جدلية: تمهيد عام عن الموضوع، ثم ظهور التعارض (فمن جهة يرى البعض... ومن جهة أخرى...)، ثم صياغة المشكلة في سؤال: هل... أم...؟\n▸ للحفظ\n• المقالة = مقدمة ثم عرض (أطروحتان وتركيب) ثم خاتمة، مع الاستعانة بأقوال الفلاسفة وأمثلتهم."}],maps:'philo'};
  var pSci={name:'الفلسفة',lessons:[{"title":"1. قيمة الفلسفة","content":"▸ المشكلة المطروحة\n• ما الفلسفة؟ وهل لها فائدة في عصر العلم والتقنية؟\n▸ مفهوم الفلسفة\n• كلمة يونانية: فيلو (محبة) + صوفيا (حكمة)\n• طلب الحقيقة بالتأمل العقلي النقدي\n• تطرح أسئلة كلية: الوجود، المعرفة، القيم\n▸ خصائص التفكير الفلسفي\n• الدهشة والتساؤل\n• النقد وعدم التسليم الأعمى\n• الشمول والكلية\n• الاعتماد على العقل والحجة\n▸ قيمتها\n• تحرير العقل من التقليد والخرافة\n• تنمية روح النقد والحوار\n• تأسيس القيم والمعرفة\n• فهم الذات والعالم\n▸ أهم المصطلحات\n• الفلسفة\n• الدهشة\n• النقد\n• الحكمة\n• الإشكالية\n▸ المقالات المحتملة\n• هل للفلسفة قيمة في عصر العلم والتقنية؟ (جدلية)\n• الفلسفة أسئلة أم أجوبة؟ (جدلية)\n• دافع عن أطروحة ضرورة الفلسفة (استقصاء بالوضع)\n▸ شرح موسّع\n• تبدأ الفلسفة عند أرسطو من الدهشة، فالإنسان يتعجب مما حوله فيسأل ثم يبحث. وهي تختلف عن الرأي العادي بأنها تطلب الدليل وتقبل المراجعة. ويرى بعض المنتقدين أنها بلا نتائج نهائية بخلاف العلوم، لكن قيمتها ليست في الأجوبة الجاهزة بل في الأسئلة التي توسع الأفق وتحمي العقل من الجمود. وقد قال كانط إننا لا نتعلم فلسفة جاهزة بل نتعلم كيف نتفلسف. وللفلسفة أثر عملي في بناء الإنسان الحر المسؤول، وفي نشأة العلوم نفسها التي خرجت من رحمها.\n▸ الفلاسفة والأمثلة\n• قال سقراط: «اعرف نفسك بنفسك». وعند أفلاطون وأرسطو: «الفلسفة تبدأ بالدهشة». وعند ديكارت: الفلسفة كشجرة جذورها الميتافيزيقا وجذعها الفيزياء وفروعها بقية العلوم.\n▸ مقالة نموذجية: هل للفلسفة قيمة في عصر العلم والتقنية؟؟\n• المقدمة: يتميز عصرنا بتقدم العلوم والتقنية حتى ظن بعضهم أن الفلسفة فقدت دورها. وبين من يعتبرها ترفا فكريا ومن يراها ضرورة للعقل، يطرح السؤال: هل للفلسفة قيمة حقيقية في عصر العلم؟\n• لا قيمة لها: يرى أوغست كونت أن الفكر الإنساني مر بثلاث مراحل: اللاهوتية ثم الميتافيزيقية ثم الوضعية، وأن الفلسفة الميتافيزيقية زالت بظهور العلم. فقد استقلت العلوم تدريجيا عن الفلسفة، وصارت العلوم تقدم نتائج قابلة للتحقق، بينما تبقى أجوبة الفلسفة متعددة ومتضاربة.\n• نقد الأطروحة الأولى: الفلسفة ليست بلا فائدة، فهي التي أنجبت العلوم وأسست مناهجها، وتبقى تطرح أسئلة الحياة والمعرفة والقيم.\n• لها قيمة: يؤكد ياسبرز أن الأسئلة في الفلسفة أهم من الأجوبة، فهي التي تنمي الفكر النقدي والاستقلال، وتؤسس القيم، وتراجع مبادئ العلوم نفسها (الإبستمولوجيا). وقد شبه ديكارت الفلسفة بشجرة جذورها الميتافيزيقا وجذعها الفيزياء وفروعها بقية العلوم.\n• نقد الأطروحة الثانية: الدفاع المطلق يتجاهل أن الفلسفة لا تقدم نتائج تجريبية قابلة للتحقق، وقد تضيع في التأملات المجردة.\n• التركيب: الفلسفة والعلم متكاملان: العلم يفسر الظواهر ويتحكم فيها، والفلسفة تنقد وتوجه وتمنح المعنى.\n• الخاتمة: وهكذا تبقى للفلسفة قيمتها في عصر العلم، فهي ضمير العلم وسؤال الإنسان الدائم عن الحقيقة والقيمة.\n▸ للحفظ\n• الفلسفة = محبة الحكمة وطلب الحقيقة بالعقل النقدي، وقيمتها في الأسئلة والنقد وتحرير العقل."},{"title":"2. العلم والفلسفة","content":"▸ المشكلة المطروحة\n• ما الفرق بين العلم والفلسفة؟ وهل هما متعارضان أم متكاملان؟\n▸ العلم\n• يدرس جزءا محددا من الواقع\n• منهج تجريبي رياضي\n• هدفه التفسير والتنبؤ والتحكم\n• نتائجه قابلة للتحقق\n▸ الفلسفة\n• تدرس الوجود والمعرفة والقيم كلها\n• منهج عقلي تأملي نقدي\n• هدفها الفهم والمعنى\n• آراؤها متعددة\n▸ العلاقة\n• الفلسفة سبقت العلوم ومهدت لها\n• الفلسفة تنقد أسس العلوم (الإبستمولوجيا)\n• العلم يمد الفلسفة بمعطيات جديدة\n▸ أهم المصطلحات\n• العلم\n• الفلسفة\n• الإبستمولوجيا\n• التفسير\n• الفهم\n▸ المقالات المحتملة\n• قارن بين العلم والفلسفة (مقارنة)\n• هل العلم والفلسفة متعارضان أم متكاملان؟\n• ما علاقة الفلسفة بالعلوم؟\n▸ شرح موسّع\n• نشأت العلوم داخل الفلسفة عند اليونان، ثم استقل كل علم بموضوعه ومنهجه منذ العصر الحديث. فالعلم يجيب بمنهج تجريبي عن «كيف» تحدث الظواهر، بينما تسأل الفلسفة عن «لماذا» ولأي غاية، وعن قيمة المعرفة العلمية ذاتها. ولا يمكن لأحدهما أن يستغني عن الآخر: العلم يحتاج إلى التفكير النقدي في مبادئه، والفلسفة تحتاج إلى نتائج العلم لتنفصل عن الواقع.\n▸ الفلاسفة والأمثلة\n• ديكارت: الفلسفة كالشجرة: الجذور ميتافيزيقا والجذع فيزياء والفروع بقية العلوم كالطب والميكانيك والأخلاق. مثال: السؤال العلمي: كيف تعمل الخلية؟ السؤال الفلسفي: ما معنى الحياة؟\n▸ مقالة نموذجية: قارن بين العلم والفلسفة؟\n• المقدمة: نشأت العلوم داخل الفلسفة ثم استقل كل علم بمنهجه وموضوعه، فصار الخلط أو الفصل بينهما مشكلا قائما. فما أوجه الشبه والاختلاف بين العلم والفلسفة، وكيف تكون علاقتهما؟\n• أوجه الشبه: كلاهما نشاط عقلي يبحث عن الحقيقة ويعتمد النقد والحجة، وكلاهما يسعى إلى التعميم والبحث عن العلل، وقد نشآ معا عند اليونان.\n• أوجه الاختلاف: يدرس العلم جزءا محددا من الواقع، بينما تدرس الفلسفة الوجود والمعرفة والقيم بنظرة كلية. ويعتمد العلم المنهج التجريبي والرياضي ونتائجه قابلة للتحقق، أما الفلسفة فمنهجها عقلي تأملي ونقدي وآراؤها متعددة. وهدف العلم التفسير والتنبؤ والتحكم، وهدف الفلسفة الفهم وإعطاء المعنى.\n• التركيب: العلاقة والتقييم: لا يستغني أحدهما عن الآخر: فالفلسفة تنقد أسس العلوم (الإبستمولوجيا) وتحدد حدودها، والعلم يمد الفلسفة بمعطيات واقعية تمنعها من التجريد المنفصل عن الواقع.\n• الخاتمة: فالعلم والفلسفة مختلفان في الموضوع والمنهج والغاية لكنهما متكاملان في خدمة المعرفة الإنسانية.\n▸ للحفظ\n• العلم يفسر ويتحكم، والفلسفة تتساءل وتنقد وتتفهم، وهما متكاملان."},{"title":"3. اللغة والفكر","content":"▸ المشكلة المطروحة\n• ما العلاقة بين اللغة والفكر؟ هل اللغة شرط ضروري للتفكير أم مجرد وسيلة للتعبير عنه؟\n▸ الموقف الأول: الاقتران\n• الفكر لا يوجد دون لغة\n• اللغة هي الفكر المنطوق\n• هيجل: نفكر داخل الكلمات\n▸ الموقف الثاني: الانفصال\n• الفكر سابق على اللغة\n• الصم والبكم يفكرون\n• الطفل يفكر قبل أن يتكلم\n• برجسون: الكلمات تقيد الفكر\n▸ التركيب\n• علاقة تأثير وتأثر متبادل\n• اللغة قالب الفكر وأداته\n• الفكر يطور اللغة ويغنيها\n▸ أهم المصطلحات\n• اللغة\n• الفكر\n• الرمز\n• التجريد\n• التواصل\n▸ المقالات المحتملة\n• هل اللغة شرط ضروري للتفكير؟ (جدلية)\n• هل اللغة مجرد أداة للتعبير عن الفكر؟\n• دافع عن أطروحة ارتباط اللغة بالفكر\n▸ شرح موسّع\n• يرى أنصار الاقتران أن الفكرة تتحدد بالألفاظ، فلا نفكر بوضوح إلا حين نصوغ أفكارنا في كلمات، ولهذا تعتبر اللغة مرآة الفكر ووسيلة التجريد وتكوين المفاهيم. أما أنصار الانفصال فيستدلون بأن الإنسان قد يدرك فكرة ثم يعجز عن التعبير عنها، وبأن الصم البكم والأطفال قبل النطق يمارسون نوعا من الذكاء. والصواب أن بين اللغة والفكر ارتباطا وثيقا دون تطابق تام: الفكر يسبق التعبير في ميلاده، لكنه لا يكتمل ولا ينتقل إلى الآخرين إلا باللغة.\n▸ الفلاسفة والأمثلة\n• هيجل: «نحن نفكر داخل الكلمات». بياجيه: الذكاء الحسي الحركي يظهر عند الطفل قبل اللغة. وفي الاستعمال اليومي نقول: «على طرف لساني» حين نملك الفكرة ولا نجد اللفظ.\n▸ مقالة نموذجية: هل اللغة شرط ضروري للتفكير؟؟\n• المقدمة: يتميز الإنسان عن غيره بالفكر واللغة معا، وقد اختلف الفلاسفة في العلاقة بينهما: هل يتوقف التفكير على اللغة أم يستقل عنها؟ وبصيغة أخرى هل اللغة شرط ضروري للتفكير؟\n• اللغة شرط للفكر: يرى أنصار الاقتران ومنهم هيجل أننا نفكر داخل الكلمات، فاللغة هي التي تحول المعاني الغامضة إلى مفاهيم واضحة، وهي وسيلة التجريد والتعميم. ولولا الألفاظ لبقي الفكر إحساسا مبهما.\n• نقد الأطروحة الأولى: الصم البكم يفكرون دون لغة منطوقة، والطفل يمارس ذكاء حسيا حركيا قبل النطق (بياجيه)، ونحن ندرك فكرة قبل أن نجد اللفظ المناسب لها.\n• الفكر سابق على اللغة: يرى برغسون أن الفكر أعمق وأغنى من الكلمات، وأن الألفاظ قوالب جامدة لا تستوعب الحياة النفسية المتدفقة، وأن اللغة مجرد وسيلة للتعبير عن فكر سابق.\n• نقد الأطروحة الثانية: الفكر لا يتبلور ولا يُنقل إلى الغير إلا بالألفاظ، واللغة تغني الفكر وتنميه، فلا انفصال تاما بينهما.\n• التركيب: العلاقة بين اللغة والفكر علاقة تأثير متبادل: الفكر يبدع اللغة وتتطور به، واللغة تنظم الفكر وتوصله.\n• الخاتمة: إذن اللغة ليست شرطا مطلقا لوجود التفكير الأولي لكنها شرط لتجريده وتطوره وتبليغه.\n▸ للحفظ\n• اللغة والفكر متكاملان: الفكر روح اللغة، واللغة جسد الفكر."},{"title":"4. الدال والمدلول ولغة الإنسان والحيوان","content":"▸ المشكلة المطروحة\n• ما طبيعة العلامة اللغوية؟ وبماذا تتميز لغة الإنسان عن وسائل تواصل الحيوان؟\n▸ العلامة اللغوية (دي سوسير)\n• الدال: الصورة الصوتية (اللفظ)\n• المدلول: المعنى أو المفهوم\n• العلاقة بينهما اعتباطية (اصطلاحية)\n▸ لغة الإنسان\n• مزدوجة التمفصل (أصوات ثم كلمات)\n• إبداعية: جمل لا متناهية\n• رمزية مجردة\n• مكتسبة اجتماعيا ومتغيرة\n▸ تواصل الحيوان\n• إشارات غريزية وراثية\n• محدودة ومرتبطة بالموقف\n• لا تعبر عن الماضي والمستقبل\n▸ أهم المصطلحات\n• الدال\n• المدلول\n• الاعتباطية\n• التمفصل المزدوج\n▸ المقالات المحتملة\n• قارن بين لغة الإنسان ووسائل تواصل الحيوان (مقارنة)\n• هل العلاقة بين الدال والمدلول اعتباطية؟\n• هل للحيوان لغة؟\n▸ شرح موسّع\n• اللغة نظام من العلامات، وكل علامة وجه ذو شقين: دال ومدلول، كما أن الورقة لها وجهان لا ينفصلان. وتسمية الشيء بلفظ معين عرف متفق عليه، ولذلك تختلف الألفاظ من لغة إلى أخرى للمعنى الواحد. أما لغة الإنسان فتتميز بالتمفصل المزدوج الذي تحدث عنه مارتينيه: نركب بعدد محدود من الأصوات كلمات، وبالكلمات جملا بلا حصر. وفي المقابل تظل رقصات النحل التي درسها كارل فون فريش وسيلة تواصل فطرية ثابتة تدل على مكان الغذاء دون إبداع.\n▸ الفلاسفة والأمثلة\n• كارل فون فريش: رقصة النحل تدل على اتجاه الغذاء وبعده، لكنها لا تتغير ولا تتعلمها النحلة. دي سوسير: العلامة اللغوية «ليست ربطا بين اسم وشيء بل بين مفهوم وصورة سمعية».\n▸ مقالة نموذجية: قارن بين لغة الإنسان وتواصل الحيوان؟\n• المقدمة: يتواصل الإنسان والحيوان بإشارات وأصوات، فيبدو أن بينهما تشابها كبيرا، غير أن بعض الفلاسفة والعلماء يؤكدون وجود فرق جوهري. فما أوجه الشبه والاختلاف بين لغة الإنسان وتواصل الحيوان؟\n• أوجه الشبه: كلاهما وسيلة لنقل رسائل بين أفراد النوع، ويستعملان أصواتا وحركات وإشارات، ويؤديان وظيفة التواصل والتعبير عن حاجات.\n• أوجه الاختلاف: لغة الإنسان رمزية اعتباطية مزدوجة التمفصل (أصوات ثم كلمات ثم جمل)، ومكتسبة اجتماعيا ومتغيرة، وتنتج جملا لا متناهية وتعبر عن الماضي والمستقبل والمجرد. أما تواصل الحيوان فإشارات غريزية وراثية ثابتة، محدودة بالموقف الحاضر، كرقصة النحل التي درسها فون فريش وتدل على موقع الغذاء دون إبداع.\n• التركيب: التقييم: الفرق بين لغة الإنسان وتواصل الحيوان فرق في النوع لا في الدرجة، فاللغة الإنسانية ترتبط بالعقل والتجريد والرمز.\n• الخاتمة: فالتواصل مشترك بين الكائنات، لكن اللغة بمعناها الرمزي المبدع خاصية إنسانية.\n▸ للحفظ\n• الدال + المدلول = علامة، واللغة الإنسانية رمزية مجردة مبدعة، وتواصل الحيوان غريزي محدود."},{"title":"5. المنطق الصوري","content":"▸ المشكلة المطروحة\n• ما قيمة المنطق الصوري الأرسطي؟ هل يضمن صدق الفكر وإنتاج معرفة جديدة؟\n▸ تعريفه\n• علم يدرس صورة الفكر لا مادته\n• أسسه أرسطو\n• غايته: ضمان اتساق الفكر مع نفسه\n▸ قوانين الفكر\n• الهوية: أ هو أ\n• عدم التناقض\n• الثالث المرفوع\n▸ القياس\n• مقدمتان ونتيجة\n• مثال: كل إنسان فان، سقراط إنسان، إذن سقراط فان\n• يشترط حد أوسط وقواعد شكلية\n▸ النقد\n• عقم النتيجة: لا يضيف جديدا\n• المصادرة على المطلوب (ميل)\n• بيكون: غير صالح لكشف الطبيعة\n▸ المقالات المحتملة\n• هل المنطق الصوري قادر على إنتاج معرفة جديدة؟\n• ما قيمة القياس الأرسطي؟\n• قارن بين الاستدلال الصوري والاستدلال التجريبي\n▸ شرح موسّع\n• يهتم المنطق الصوري بشكل الاستدلال ولا يعنى بمطابقة الأفكار للواقع، فهو يضمن اتساق النتيجة مع المقدمات. ويقوم القياس على اندراج الحالة الجزئية تحت قضية كلية. وقد أفاد في تنظيم الفكر وكشف المغالطات وتدريس العلوم. لكن بيكون رأى أنه لا يصلح للكشف عن حقائق الطبيعة، وبيّن ستيوارت ميل أن القياس يقع في مصادرة على المطلوب لأن المقدمة الكبرى تفترض النتيجة سلفا. ولذلك ظهر المنهج التجريبي والمنطق الرياضي الحديث ليكمل ما عجز عنه.\n▸ الفلاسفة والأمثلة\n• القياس الأرسطي: كل إنسان فان (مقدمة كبرى) - سقراط إنسان (مقدمة صغرى) - إذن سقراط فان (نتيجة). ميل: قولنا «كل إنسان فان» يفترض أن سقراط فان من قبل، فالقياس دور.\n▸ مقالة نموذجية: هل المنطق الصوري قادر على إنتاج معرفة جديدة؟؟\n• المقدمة: أسس أرسطو المنطق الصوري ليكون قانونا يعصم الفكر من الخطأ، وظل قرونا أداة للعلم. غير أن العلماء الجدد شككوا في قدرته على الكشف عن الجديد، فهل ينتج المنطق الصوري معرفة جديدة؟\n• لا ينتج معرفة جديدة: يرى بيكون أن القياس لا يصلح لكشف حقائق الطبيعة، ويرى ستيوارت ميل أن القياس يقع في مصادرة على المطلوب لأن المقدمة الكبرى تتضمن النتيجة سلفا. فنحن نعرف أن سقراط فان قبل أن نقول إن كل إنسان فان.\n• نقد الأطروحة الأولى: المنطق الصوري يبقى ضروريا لضمان سلامة الاستدلال وكشف المغالطات، كما في البراهين الهندسية.\n• يعطي معرفة جديدة: يرى المدافعون عنه أنه يضمن اتساق الفكر وسلامة النتائج، وأن الاستنباط يكشف لوازم المقدمات التي قد لا تكون بديهية في الوعي، فهو أساس البناء الرياضي.\n• نقد الأطروحة الثانية: النتائج التي يصل إليها ليست جديدة بل هي تفصيل لما تحتويه المقدمات، ولا يضيف معرفة بالواقع.\n• التركيب: للمنطق الصوري قيمة شكلية في تنظيم الفكر واتساقه، لكنه يحتاج إلى المنهج التجريبي لتحصيل معرفة جديدة بالواقع.\n• الخاتمة: فالمنطق الصوري أداة ضرورية للصواب الشكلي، لا للإبداع المعرفي.\n▸ للحفظ\n• المنطق الصوري يضمن سلامة الاستدلال شكليا لكنه لا ينتج معرفة جديدة، وقوانينه: الهوية وعدم التناقض والثالث المرفوع."},{"title":"6. الرياضيات: أصلها والاستدلال الرياضي","content":"▸ المشكلة المطروحة\n• ما مصدر المعرفة الرياضية: العقل أم التجربة؟ وما خصائص الاستدلال الرياضي؟\n▸ الموقف العقلي\n• الرياضيات من العقل وحده\n• أفكار فطرية (أفلاطون، ديكارت)\n• مبادئ قبلية (كانط)\n▸ الموقف التجريبي\n• الرياضيات مستمدة من التجربة والحواس\n• ستيوارت ميل: الاستقراء\n• الهندسة نشأت من قياس الأراضي\n▸ خصائص الاستدلال الرياضي\n• استنباطي من مسلمات وتعريفات\n• يقيني ومجرد\n• يلتزم بقواعد البرهان\n▸ أهم المصطلحات\n• المسلمة\n• البديهية\n• البرهان\n• الاستنباط\n• التجريد\n▸ المقالات المحتملة\n• هل أصل الرياضيات العقل أم الحواس؟ (جدلية)\n• ما خصائص الاستدلال الرياضي؟ (تحليل نص)\n• دافع عن عقلانية الرياضيات\n▸ شرح موسّع\n• يرى العقليون أن الأعداد والأشكال الهندسية المثالية لا وجود لها في الواقع الحسي، فالدائرة الكاملة مثلا لا نراها بالعين، لذا مصدرها العقل. ويعارضهم التجريبيون بأن الطفل يتعلم العد من الأشياء الحسية، وأن الهندسة بدأت بحاجات الحياة. والموقف الأقرب أن الرياضيات تنطلق من الواقع ثم يجردها العقل ويبني عليها بناء استنباطيا مستقلا. وفي الاستدلال الرياضي ننطلق من مسلمات وتعريفات ونصل بالبرهان إلى نتائج لازمة، كما بيّن بلانشي في نصه.\n▸ الفلاسفة والأمثلة\n• ديكارت: الأفكار الواضحة المتميزة فطرية في العقل. ستيوارت ميل: القضايا الرياضية تعميمات من التجربة. كانط: الزمان والمكان صورتان قبليتان للحساسية، يقوم عليهما الحساب والهندسة.\n▸ مقالة نموذجية: هل أصل الرياضيات العقل أم الحواس؟؟\n• المقدمة: تتميز الرياضيات بيقينها ودقتها، ولذلك شغلت الفلاسفة في أصلها. فهل تنبع مفاهيمها وقضاياها من العقل وحده، أم أنها مستمدة من التجربة الحسية؟\n• أصلها العقل: يرى العقليون كأفلاطون وديكارت وكانط أن الأعداد والأشكال المثالية كالدائرة التامة لا وجود لها في الواقع الحسي، فهي تصورات عقلية، وأن يقين القضايا الرياضية ضروري كلي لا تفسره الحواس.\n• نقد الأطروحة الأولى: الأعداد والأشكال نشأت من حاجات الواقع كالعد وقياس الأراضي، والطفل يتعلم الحساب بالأشياء المحسوسة.\n• أصلها الحواس: يرى التجريبيون وعلى رأسهم ستيوارت ميل أن المفاهيم الرياضية مستمدة من التجربة بالتجريد والتعميم، فالهندسة بدأت بمسح الأراضي والحساب بعد الأشياء.\n• نقد الأطروحة الثانية: التجربة وحدها لا تفسر يقينية القضايا الرياضية ولا مفاهيمها المجردة، فالتجربة جزئية احتمالية.\n• التركيب: الرياضيات تنطلق من الواقع ثم يجردها العقل ويبني عليها بناء استنباطيا مستقلا، فهي ثمرة تعاون العقل والتجربة.\n• الخاتمة: إذن أصل الرياضيات مزدوج: بداياته من الواقع وبناؤها واستدلالها من العقل.\n▸ للحفظ\n• الرياضيات: عقل (العقليون) أو تجربة (التجريبيون)، والتركيب: انطلاق من الواقع وتجريد عقلي وبناء استنباطي."},{"title":"7. المنهج التجريبي وقيمة الفرضية","content":"▸ المشكلة المطروحة\n• كيف يصل العالم إلى القوانين العلمية؟ وما قيمة الفرضية في المنهج التجريبي؟\n▸ خطواته\n• الملاحظة\n• الفرضية\n• التجربة (التحقق)\n• القانون\n▸ الفرضية\n• تفسير مؤقت للظاهرة\n• يبتكرها خيال العالم المنضبط\n• تحتاج إلى تحقق وتجريب\n• قيمتها: توجه البحث\n▸ شروط الفرضية\n• قابلة للاختبار\n• غير متناقضة مع حقائق ثابتة\n• بسيطة\n▸ أهم المصطلحات\n• الملاحظة\n• الفرضية\n• التجربة\n• القانون العلمي\n• الحتمية\n▸ المقالات المحتملة\n• هل يمكن الاستغناء عن الفرضية في المنهج التجريبي؟\n• هل المنهج التجريبي مقياس العلم؟\n• قارن بين المنهج التجريبي والمنهج الرياضي\n▸ شرح موسّع\n• يبدأ البحث التجريبي بملاحظة ظاهرة تثير سؤالا، ثم يضع الباحث فرضية تفسرها، ثم يتحقق منها بتجربة مضبوطة يغير فيها عاملا ويثبت بقية العوامل. فإن أيدت النتائج الفرضية صارت قانونا، وإن ناقضتها عُدّلت أو أُبطلت. وقد أكد كلود برنار أن الفرضية ضرورية لأن الملاحظة دون فكرة موجهة تبقى عمياء. ومن أشهر الأمثلة تجربة باسكال في جبل بوي دي دوم لإثبات أن عمود الزئبق يتأثر بالضغط الجوي. ولا يقوم المنهج على الاستقراء وحده بل على تكامل العقل والتجربة.\n▸ الفلاسفة والأمثلة\n• كلود برنار: «الفكرة هي مبدأ كل برهان، ومصدر كل اختراع». تجربة باسكال: انخفاض ارتفاع الزئبق كلما صعدنا الجبل، فثبتت فرضية الضغط الجوي.\n▸ مقالة نموذجية: هل يمكن الاستغناء عن الفرضية في المنهج التجريبي؟؟\n• المقدمة: يقوم المنهج التجريبي على الملاحظة والفرضية والتجربة والقانون، لكن قيمة الفرضية اختلف فيها العلماء. فهل يمكن الاستغناء عنها في البحث التجريبي؟\n• يمكن الاستغناء عنها: يرى بعض التجريبيين كبيكون أن على الباحث أن ينطلق من الوقائع نفسها ويتخلص من الأفكار المسبقة التي قد تحجب الحقيقة، وأن الفرضية قد تكون تحيزا مسبقا.\n• نقد الأطروحة الأولى: الملاحظة بلا فكرة موجهة تبقى عمياء، فكلود برنار بين أن الفرضية هي التي توجه الملاحظة وتحدد ما نلاحظ.\n• لا يمكن الاستغناء عنها: يرى كلود برنار أن الفرضية هي مبدأ كل برهان ومصدر كل اختراع، فهي التي تفسر الظاهرة مؤقتا وتوجه التجربة، وبدونها لا يتقدم البحث، كما في فرضية الضغط الجوي عند باسكال.\n• نقد الأطروحة الثانية: الفرضية التي لا تخضع للتحقق التجريبي تبقى تخمينا، وقد يتعلق بها الباحث فيتحيز لها.\n• التركيب: الفرضية ضرورية في المنهج التجريبي بشرط أن تكون قابلة للاختبار، وأن يتخلى عنها الباحث إذا خالفتها التجربة.\n• الخاتمة: فلا غنى عن الفرضية، لكنها تبقى تحت رقابة الواقع.\n▸ مقالة نموذجية: هل المنهج التجريبي مقياس العلم؟؟\n• المقدمة: حقق المنهج التجريبي نجاحا هائلا في العلوم الطبيعية، فاعتبره بعضهم المعيار الوحيد للعلم. فهل المنهج التجريبي مقياس العلم؟\n• هو مقياس العلم: يرى الوضعيون أن العلم ما أمكن التحقق منه بالتجربة، فهو يعطي قوانين دقيقة قابلة للتنبؤ والتطبيق، وأن ما لا يخضع للتجربة لا يعد علما.\n• نقد الأطروحة الأولى: لا يصلح التجريب في كل الميادين، فالرياضيات تقوم على الاستنباط، والعلوم الإنسانية تتعلق بظواهر واعية متغيرة.\n• ليس المقياس الوحيد: للعلوم مناهج متعددة بحسب موضوعاتها: المنهج الاستنباطي في الرياضيات والوصفي والتاريخي في العلوم الإنسانية، فالعلم يقاس بالموضوعية والدقة لا بالتجريب وحده.\n• نقد الأطروحة الثانية: يبقى التجريب أقوى وسيلة للتحقق في العلوم الطبيعية، وهو الذي مكّن من التقدم التقني.\n• التركيب: المنهج التجريبي مقياس العلم في ميدان الظواهر الطبيعية، وتختلف المناهج في الميادين الأخرى مع الاشتراك في روح الموضوعية.\n• الخاتمة: فالعلم يتعدد مناهجه بتعدد موضوعاته، والتجريب أنجح أدواته في الطبيعة.\n▸ للحفظ\n• خطوات المنهج التجريبي: ملاحظة ثم فرضية ثم تجربة ثم قانون، والفرضية روحه."},{"title":"8. الاستقراء وتبريره","content":"▸ المشكلة المطروحة\n• على ماذا يعتمد تعميم النتائج الجزئية في الاستقراء؟ وهل يمكن تبريره؟\n▸ تعريفه\n• الانتقال من الجزئيات إلى حكم كلي\n• تام (يشمل كل الحالات)\n• ناقص (يعمم من عينة)\n▸ مبررات الاستقراء\n• مبدأ السببية\n• مبدأ اطراد الحوادث وثبات قوانين الطبيعة (ميل)\n• مبدأ الحتمية\n▸ نقد الاستقراء\n• هيوم: مجرد عادة نفسية لا يقين فيه\n• بوبر: بديل التكذيب بدل التحقق\n▸ أهم المصطلحات\n• الاستقراء\n• التعميم\n• السببية\n• الحتمية\n• التكذيب\n▸ المقالات المحتملة\n• هل أساس الاستقراء تجريبي أم عقلي؟\n• كيف نبرر الانتقال من الجزئي إلى الكلي؟\n• دافع عن مشروعية الاستقراء\n▸ شرح موسّع\n• الاستقراء الناقص هو الذي تعتمد عليه العلوم التجريبية، فنقول مثلا: كل الحديد يتمدد بالحرارة بعد تجريبه على عينات. وقد طرح الفلاسفة سؤالا: بماذا نبرر هذا التعميم؟ فأجاب التجريبيون كميل بأن الطبيعة منتظمة تسير بقوانين ثابتة، وأن لكل حادثة سببا. أما هيوم فعدّ فكرة السببية عادة ذهنية تولدت من تكرار التتابع، فلا يقين منطقيا في التعميم. وجاء بوبر ليقول إن العلم يتقدم بمحاولات التفنيد والتكذيب لا بتكديس الشواهد.\n▸ الفلاسفة والأمثلة\n• المثال: «الحديد يتمدد بالحرارة» حكم عام انطلقنا فيه من تجارب جزئية. هيوم: لأننا رأينا الشمس تشرق كل يوم نتوقع شروقها غدا بحكم العادة. بوبر: ألف شاهد لا يثبت نظرية، وشاهد واحد قد يدحضها.\n▸ مقالة نموذجية: هل أساس الاستقراء تجريبي أم عقلي؟؟\n• المقدمة: يعمم الاستقراء من حالات جزئية إلى قانون كلي، وهذا الانتقال يطرح سؤال تبريره. فعلى ماذا يعتمد: التجربة أم العقل؟\n• أساسه عقلي: يرى العقليون أن التعميم يقوم على مبدأي السببية والحتمية، وهما مبدآن عقليان قبليان عند كانط، فلولاهما لما جاز تعميم نتائج الجزئيات.\n• نقد الأطروحة الأولى: قد لا تكون السببية مبدأ عقليا قبليا بل عادة ذهنية تولدت من تكرار التتابع كما يرى هيوم.\n• أساسه تجريبي: يرى ستيوارت ميل أن الاستقراء يقوم على اطراد الحوادث وثبات قوانين الطبيعة، وهو مبدأ مستمد من الملاحظة المتكررة. ويرى هيوم أن فكرة السببية ناتجة عن العادة.\n• نقد الأطروحة الثانية: التجربة جزئية ومتناهية، فلا تبرر تعميما كليا دون مبدأ عام يسبقها، ولا يكفي التكرار ليكون يقينا.\n• التركيب: يجمع الاستقراء بين التجربة التي تمده بالوقائع والعقل الذي يمده بمبدأ السببية والتعميم، ويرى بوبر أن العلم يتقدم بمحاولات التفنيد.\n• الخاتمة: فالاستقراء يستند إلى التجربة والعقل معا، وهو مشروع ما دام يخضع للاختبار والتصحيح.\n▸ للحفظ\n• الاستقراء يقوم على السببية والحتمية، وقد انتقده هيوم وجاء بوبر بمعيار التكذيب."},{"title":"9. المنهج التجريبي والمادة الحية","content":"▸ المشكلة المطروحة\n• هل يمكن تطبيق المنهج التجريبي على المادة الحية كما يطبق على المادة الجامدة؟\n▸ الصعوبات\n• تعقيد الكائن الحي وترابط أعضائه\n• الاختلاف الفردي بين الكائنات\n• التجريب قد يؤدي إلى موت الحي أو تغير سلوكه\n• الاعتبارات الأخلاقية\n▸ ردود العلماء\n• الحتمية تسري على الحي والجامد (كلود برنار)\n• الوسط الداخلي ثابت نسبيا\n• استعمال الإحصاء والحيوانات والمجاهر والتصوير\n▸ أهم المصطلحات\n• المادة الحية\n• التشريح\n• الوسط الداخلي\n• الحتمية\n▸ المقالات المحتملة\n• هل يمكن تطبيق المنهج التجريبي على المادة الحية؟\n• قارن بين الحي والجامد في التجريب\n▸ شرح موسّع\n• يرى بعضهم أن للحياة خصوصية تمنع إخضاعها للتجريب، فلكل كائن حي وحدة عضوية كلية إن فُكّك فقد حياته، ولا تتكرر التجربة بنفس الشروط. ويرد كلود برنار بأن الحتمية العلمية قائمة في الظواهر الحيوية كما في الجامدة، وأن هناك وسطا داخليا ثابتا يمكن دراسته، وأن التطور التقني أتاح وسائل جديدة كالتشريح الحي والتحاليل والإحصاء. ويبقى الأمر مقيدا بضوابط أخلاقية تحمي الإنسان والحيوان من أي أذى لا مبرر له.\n▸ الفلاسفة والأمثلة\n• كلود برنار: درس وظيفة الكبد وإفراز السكر (الوظيفة الغليكوجينية) بتجارب على الحيوان، وأقر الحتمية في الفيزيولوجيا. ومن الأمثلة اللقاحات لدى باستور.\n▸ مقالة نموذجية: هل يمكن تطبيق المنهج التجريبي على المادة الحية؟؟\n• المقدمة: نجح المنهج التجريبي في دراسة المادة الجامدة، فهل يصلح لدراسة الكائنات الحية بما فيها من تعقيد وخصوصية؟\n• لا يمكن تطبيقه: يرى بعضهم أن الكائن الحي وحدة عضوية متكاملة تفقد حياتها بتفكيكها، وأن لكل كائن فرديته فلا تتكرر الشروط، وأن التجريب قد يغير سلوكه أو يقتله وهناك قيود أخلاقية.\n• نقد الأطروحة الأولى: تقدم العلم وفر وسائل تتجاوز كثيرا من هذه الصعوبات كالتشريح والتحاليل والإحصاء.\n• يمكن تطبيقه: يؤكد كلود برنار أن الحتمية تسري على الظواهر الحية كما على الجامدة، وأن للكائنات الحية وسطا داخليا ثابتا يمكن دراسته، وقد نجحت الفيزيولوجيا والطب.\n• نقد الأطروحة الثانية: تبقى لخصوصية الحي قيود تفرض تعديل المنهج، كما تفرض الاعتبارات الأخلاقية ضوابط على التجريب.\n• التركيب: يمكن تطبيق المنهج التجريبي على الحي مع مراعاة خصوصيته وضوابطه الأخلاقية.\n• الخاتمة: فالمنهج التجريبي يصلح للحي بعد تكييفه، وهو أساس تقدم الطب.\n▸ للحفظ\n• تطبيق المنهج التجريبي على الحي ممكن مع مراعاة خصوصيته وضوابطه الأخلاقية."},{"title":"10. العلوم الإنسانية والظاهرة الإنسانية","content":"▸ المشكلة المطروحة\n• هل يمكن دراسة الظاهرة الإنسانية بمنهج علمي موضوعي؟\n▸ الظاهرة الإنسانية\n• نفسية واجتماعية وتاريخية واقتصادية\n• معقدة ومتغيرة\n• مرتبطة بالوعي والحرية والقيم\n▸ الصعوبات\n• الذاتية: الباحث جزء من الموضوع\n• صعوبة التجريب والتكرار\n• تعدد العوامل\n• تأثر الظاهرة بالملاحظة\n▸ محاولات الموضوعية\n• دوركايم: تعامل الظواهر كأشياء\n• الاستبيان والمقابلة والإحصاء\n• دراسة الحالة\n• الجمع بين التفسير والفهم\n▸ أهم المصطلحات\n• الظاهرة الإنسانية\n• الموضوعية\n• الذاتية\n• التفسير\n• الفهم\n▸ المقالات المحتملة\n• هل يمكن تطبيق المنهج التجريبي على الظاهرة الإنسانية؟\n• ما صعوبات العلوم الإنسانية؟\n• قارن بين الظاهرة الإنسانية والطبيعية\n▸ شرح موسّع\n• تهتم العلوم الإنسانية (علم النفس، علم الاجتماع، التاريخ، الاقتصاد) بالإنسان وسلوكه. ويرى المعارضون أن الإنسان كائن واع حر يتغير يوميا، فلا يمكن إخضاعه لقوانين صارمة كما في الفيزياء. لكن علماء مثل دوركايم نادوا بدراسة الظواهر الاجتماعية بموضوعية كأنها أشياء، مبتعدين عن الأحكام المسبقة، واستعانوا بالإحصاء والمقارنة. وقد أضاف ديلتاي الفهم الداخلي لمقاصد الإنسان إلى التفسير السببي. فالمنهج التجريبي ممكن بدرجة، وتكتمل صورته بمناهج مكملة كالمنهج التاريخي والكيفي.\n▸ الفلاسفة والأمثلة\n• دوركايم في دراسته للانتحار اعتمد الإحصاءات للربط بين معدلاته وظروف المجتمع. ديلتاي: «الطبيعة نفسرها، والحياة النفسية نفهمها».\n▸ مقالة نموذجية: هل يمكن تطبيق المنهج التجريبي على الظاهرة الإنسانية؟؟\n• المقدمة: بعد نجاح العلوم الطبيعية حاول الباحثون دراسة الإنسان علميا، لكن الظاهرة الإنسانية تتميز بالتعقيد والوعي والحرية. فهل يمكن تطبيق المنهج التجريبي عليها؟\n• لا يمكن: الظاهرة الإنسانية معقدة وذاتية ومتغيرة، والباحث جزء من الموضوع، ويصعب إجراء تجارب مضبوطة وتكرارها، والإنسان واع حر لا يخضع لقوانين صارمة. وهذا ما قال به ديلتاي حين ميّز بين التفسير في الطبيعة والفهم في الإنسان.\n• نقد الأطروحة الأولى: هذه الصعوبات لا تلغي إمكان الدراسة الموضوعية بمناهج مناسبة، وقد حققت العلوم الإنسانية نتائج معتبرة.\n• يمكن: دعا دوركايم إلى دراسة الظواهر الاجتماعية كأشياء وتجرد من الأحكام المسبقة، واستعان بالإحصاء والمقارنة، كما في دراسته للانتحار، فصار علم النفس والاجتماع علمين.\n• نقد الأطروحة الثانية: الإنسان واع حر، وتأويل مقاصده لا يتحقق بالتجريب وحده، وتبقى النتائج احتمالية.\n• التركيب: يمكن تطبيق المنهج التجريبي على الظاهرة الإنسانية بمرونة، مع مكملات كالمنهج التاريخي والكيفي ومنهج الفهم.\n• الخاتمة: فالعلوم الإنسانية ممكنة بشرط تكييف مناهجها مع خصوصية موضوعها.\n▸ للحفظ\n• العلوم الإنسانية تدرس الإنسان بمنهج يجمع الموضوعية والفهم ويتكيف مع خصوصية الظاهرة."},{"title":"11. القيمة الخلقية: مطلقة أم نسبية؟","content":"▸ المشكلة المطروحة\n• هل القيم الأخلاقية ثابتة مطلقة أم نسبية تتغير بتغير المجتمعات والأزمنة؟\n▸ الموقف المطلق\n• مصدرها العقل أو الدين أو الفطرة\n• كونية وثابتة\n• كانط: الأمر المطلق والواجب\n▸ الموقف النسبي\n• مصدرها المجتمع والبيئة\n• تختلف باختلاف الثقافات\n• دوركايم: الأخلاق ظاهرة اجتماعية\n• الماركسية: انعكاس للبنية الاقتصادية\n▸ التركيب\n• ثبات المبادئ العامة (العدل، الصدق)\n• تغير صيغ التطبيق بتغير الظروف\n▸ أهم المصطلحات\n• القيمة الخلقية\n• الواجب\n• الضمير\n• النسبية\n• الإلزام\n▸ المقالات المحتملة\n• هل القيم الأخلاقية ثابتة مطلقة أم نسبية؟\n• ما مصدر الإلزام الأخلاقي؟\n• قارن بين الأخلاق العقلية والاجتماعية\n▸ شرح موسّع\n• يرى كانط أن الأخلاق لا تقوم على النتائج بل على النية الحسنة واحترام الواجب لذاته، وأن القاعدة الأخلاقية كونية: افعل بحيث تعامل الإنسانية في شخصك وفي غيرك غاية لا وسيلة. في المقابل يرى دوركايم أن المجتمع هو مصدر الإلزام الخلقي، ولذلك تتغير القيم من مجتمع إلى آخر. وتبين المقارنة أن هناك قيما مشتركة بين الشعوب كتحريم القتل والكذب والخيانة وتقدير العدل، لكن الأعراف التفصيلية تتنوع. فالقيمة الخلقية ثابتة في جوهرها نسبية في صورها.\n▸ الفلاسفة والأمثلة\n• كانط: «افعل بحيث تعامل الإنسانية في شخصك وفي شخص غيرك دائما كغاية وليس كوسيلة فقط». دوركايم: الواجب الأخلاقي يفرضه المجتمع بما له من سلطة معنوية على الأفراد.\n▸ مقالة نموذجية: هل القيمة الخلقية مطلقة أم نسبية؟؟\n• المقدمة: تختلف الأخلاق بين الشعوب والعصور، ويثير ذلك تساؤلا عن ثبات القيم: هل القيمة الخلقية مطلقة ثابتة أم نسبية متغيرة؟\n• القيمة مطلقة: يرى كانط أن الأخلاق تقوم على العقل والواجب، وأن القاعدة الأخلاقية كونية: افعل بحيث تعامل الإنسانية غاية لا وسيلة، وأنها لا تتغير بتغير الظروف. فمصدرها العقل أو الدين أو الفطرة.\n• نقد الأطروحة الأولى: تغفل اختلاف الأعراف والثقافات في الحكم على الأفعال، وتتجاهل أثر المجتمع في تكوين الضمير.\n• القيمة نسبية: يرى دوركايم أن المجتمع مصدر الإلزام الخلقي، فالقيم تتغير بتغير المجتمعات، وتراها الماركسية انعكاسا للبنية الاقتصادية والطبقية.\n• نقد الأطروحة الثانية: تجعل الأخلاق مجرد ذوق اجتماعي وتبرر كل ممارسة، رغم وجود قيم مشتركة بين الشعوب كالعدل وتحريم القتل.\n• التركيب: القيم ثابتة في مبادئها العامة كالعدل والصدق، نسبية في صيغ تطبيقها بحسب الظروف والثقافات.\n• الخاتمة: فالقيمة الخلقية مطلقة في جوهرها ونسبية في تجلياتها.\n▸ للحفظ\n• القيم الأخلاقية: مبادئ ثابتة (كانط) وتطبيقات متغيرة (دوركايم)، والعدل والصدق قيمتان مشتركتان."},{"title":"12. السياسة والأخلاق","content":"▸ المشكلة المطروحة\n• هل يجب أن تخضع السياسة للأخلاق؟ أم أن للسياسة منطقها الخاص القائم على المصلحة؟\n▸ الموقف الفاصل (الواقعي)\n• السياسة ميدان القوة والمصلحة\n• ميكيافيلي: الحاكم يوازن بين الأخلاق ونجاح الدولة\n• الأخلاق للأفراد لا للدول\n▸ الموقف الرابط\n• السياسة لا تقوم بدون عدالة وشرعية\n• أفلاطون: الحاكم الفيلسوف الفاضل\n• كانط: السلام الدائم\n▸ التركيب\n• أخلاق المسؤولية (فيبر)\n• السياسة وسيلة لتحقيق الخير العام\n• رقابة الشعب والقانون\n▸ أهم المصطلحات\n• السياسة\n• الأخلاق\n• المصلحة\n• الشرعية\n• العدالة\n▸ المقالات المحتملة\n• هل السياسة منفصلة عن الأخلاق؟\n• هل يجب أن تخضع السياسة للأخلاق؟\n• دافع عن ارتباط السياسة بالأخلاق\n▸ شرح موسّع\n• يقول الواقعيون إن الحاكم الذي يتقيد بالفضائل المطلقة قد يفشل في حماية دولته، لذلك يقدمون المصلحة والفعالية، وهو ما يعرف في الفكر الميكيافيلي. أما المثاليون فيرون أن الحكم بلا أخلاق يتحول إلى استبداد ويفقد شرعيته. ويرى ماكس فيبر أن السياسي يحتاج إلى «أخلاق المسؤولية» أي إلى تحمل نتائج قراراته. والصواب أن السياسة لا تنفصل عن الأخلاق، لأن الغاية من الدولة تحقيق العدل والأمن والخير العام.\n▸ الفلاسفة والأمثلة\n• أفلاطون في «الجمهورية» يرى أن يحكم الفلاسفة لأنهم أعرف بالخير. ميكيافيلي في «الأمير» يشرح كيف يحافظ الحاكم على سلطته ولو خالف الفضائل أحيانا. كانط في «مشروع السلام الدائم» يرى أن السلام غاية أخلاقية للسياسة.\n▸ مقالة نموذجية: هل يجب أن تخضع السياسة للأخلاق؟؟\n• المقدمة: تقتضي ممارسة الحكم أحيانا قرارات صعبة تبدو مخالفة للقيم، ويثور الجدل حول العلاقة بين السياسة والأخلاق. فهل يجب أن تخضع السياسة للأخلاق؟\n• السياسة منفصلة عن الأخلاق: يرى الواقعيون كميكيافيلي أن السياسة ميدان المصلحة والقوة، وأن الحاكم الذي يتقيد بالفضائل المطلقة قد يفشل في حماية دولته، فيقدم نجاح الحكم على الاعتبارات الخلقية.\n• نقد الأطروحة الأولى: فصل السياسة عن الأخلاق يبرر الظلم والاستبداد ويفقد الحكم شرعيته وثقة الشعب.\n• السياسة مرتبطة بالأخلاق: يرى أفلاطون أن يحكم الفلاسفة الفضلاء، ويرى كانط أن السلام غاية أخلاقية وأن السياسة الحقة يجب أن تخضع للقانون الأخلاقي. فالدولة وجدت لتحقيق العدل والخير العام.\n• نقد الأطروحة الثانية: المثالية المحضة قد تهمل ضرورات الواقع والمصلحة العامة وتعجز عن مواجهة الأخطار.\n• التركيب: يحتاج السياسي إلى أخلاق المسؤولية (ماكس فيبر)، أي أن يوازن بين القيم والواقع ويتحمل نتائج قراراته.\n• الخاتمة: فالسياسة لا تنفصل عن الأخلاق، لأن غاية الدولة تحقيق العدل والأمن والخير العام.\n▸ للحفظ\n• السياسة تحتاج الأخلاق لتكون عادلة وشرعية، والأخلاق تحتاج السياسة لتتجسد في الواقع."},{"title":"13. العادة","content":"▸ المشكلة المطروحة\n• هل العادة تحرر الإنسان وتيسر حياته أم تقيده وتعطل وعيه؟\n▸ المفهوم\n• استعداد مكتسب بالتكرار لأداء سلوك بسهولة وآلية\n• تختلف عن الغريزة (فطرية)\n• طبيعة ثانية (أرسطو)\n▸ الأطروحة السلبية\n• تجمد السلوك وتقتل الإبداع\n• تضعف الإحساس والانتباه\n• روسو: لا نعلم الطفل أي عادة\n▸ الأطروحة الإيجابية\n• توفر الجهد والوقت\n• تيسر التعلم والمهارات\n• وليم جيمس: العجلة الضخمة للمجتمع\n• أرسطو: الفضائل عادات\n▸ التركيب\n• العادة سلاح ذو حدين\n• المفيد منها ما يخضع للإرادة والوعي\n▸ المقالات المحتملة\n• هل العادة تقيد الإنسان أم تحرره؟\n• ما قيمة العادة في السلوك الإنساني؟\n• قارن بين العادة والغريزة\n▸ شرح موسّع\n• العادة تجعلنا نؤدي أفعالا معقدة كالكتابة والقيادة بسهولة ودون استحضار الانتباه، فتفرغ الذهن لأمور أخرى، وبها تتكون المهارات والأخلاق. لكنها قد تقود إلى الجمود والروتين وتضعف التجديد، وقد تتحول إلى إدمان على سلوك ضار. ويفرق بين العادة والغريزة بأن الغريزة فطرية موروثة عند كل أفراد النوع، أما العادة فمكتسبة تختلف بين الأفراد وتقبل التغيير. والعادة الجيدة هي التي نصنعها بوعي وتخدم أهدافنا.\n▸ الفلاسفة والأمثلة\n• أرسطو: «الفضيلة عادة». وليم جيمس: العادة هي «العجلة الضخمة المنظمة للمجتمع». روسو: العادة الوحيدة التي ينبغي أن تُغرس في الطفل ألا يكتسب أي عادة.\n▸ مقالة نموذجية: هل العادة تقيد الإنسان أم تحرره؟؟\n• المقدمة: يكتسب الإنسان بالتكرار عادات تصبح مع الزمن آلية، فيثار السؤال عن أثرها: هل تقيد الإنسان وتضعف وعيه أم تحرره وتيسر حياته؟\n• العادة تقيد: العادة تجمد السلوك وتقتل الإبداع وتضعف الانتباه والإحساس، ويقول روسو إن العادة الوحيدة التي ينبغي أن نغرسها في الطفل ألا يكتسب أي عادة. وقد تتحول إلى إدمان يستعبد الإنسان.\n• نقد الأطروحة الأولى: تغفل أن العادة توفر الجهد والمهارات والفضائل، وبدونها يبقى الإنسان مشغولا بتفاصيل كل فعل.\n• العادة تحرر: تيسر العادة الأداء وتوفر الوقت والجهد وتفرغ الذهن للإبداع، وبعدها أرسطو طبيعة ثانية تنشأ بها الفضائل، ويرى وليم جيمس أنها العجلة الكبيرة المنظمة للمجتمع.\n• نقد الأطروحة الثانية: تتجاهل خطر الجمود والتكرار الأعمى والإدمان الذي يعطل الوعي والإرادة.\n• التركيب: العادة سلاح ذو حدين: تحرر إذا خضعت للوعي والإرادة، وتقيد إذا تحولت إلى آلية عمياء.\n• الخاتمة: فالمهم أن نصنع عاداتنا بوعي وأن نراجعها باستمرار.\n▸ للحفظ\n• العادة: تيسير وتوفير للجهد، وخطر الجمود، والمعيار: إخضاعها للوعي والإرادة."},{"title":"14. الحتمية واللاحتمية","content":"▸ المشكلة المطروحة\n• هل تخضع الظواهر لقوانين صارمة ثابتة (حتمية) أم يسودها الاحتمال واللايقين؟\n▸ مفهوم الحتمية\n• كل ظاهرة لها سبب، وبنفس الأسباب نفس النتائج\n• لابلاس: العالم قابل للتنبؤ الكامل\n• كلود برنار: حتمية الظواهر الحية والجامدة\n▸ اللاحتمية\n• هايزنبرغ: مبدأ اللايقين في الفيزياء الذرية\n• ميكانيكا الكم: قوانين احتمالية\n• حرية الإنسان تتعارض مع الحتمية الصارمة\n▸ التركيب\n• الحتمية قائمة في الفيزياء الكلاسيكية\n• الاحتمال في الميكروفيزياء\n• الحتمية النسبية لا تلغي العلم\n▸ أهم المصطلحات\n• الحتمية\n• السببية\n• الاحتمال\n• اللايقين\n• القانون العلمي\n▸ المقالات المحتملة\n• هل مبدأ الحتمية مطلق في العلوم؟\n• هل تتعارض الحتمية مع حرية الإنسان؟\n• دافع عن مبدأ الحتمية\n▸ شرح موسّع\n• قامت العلوم الكلاسيكية على أن لكل ظاهرة سببا ثابتا، حتى تخيّل لابلاس عقلا يعرف حالة الكون الآن فيتنبأ بكل ما سيحدث. وجاءت فيزياء الذرة فبينت أن قياس موضع الجسيم وسرعته معا لا يمكن أن يكون دقيقا، كما في مبدأ اللايقين لهايزنبرغ، فصارت القوانين احتمالية. ومع ذلك لم يلغِ ذلك العلم، فهو في الظواهر الكبرى ما زال يعتمد على قوانين دقيقة. وفي ميدان الإنسان يفرق الفلاسفة بين الحتمية الطبيعية وحرية الإرادة التي تقتضي إمكان الاختيار.\n▸ الفلاسفة والأمثلة\n• لابلاس: عقل يعرف كل القوى والحالات يستطيع التنبؤ بالمستقبل كالماضي. هايزنبرغ: لا يمكن تحديد موضع الإلكترون وسرعته بدقة في آن واحد. كلود برنار: الحتمية شرط العلم.\n▸ مقالة نموذجية: هل مبدأ الحتمية مطلق في العلوم؟؟\n• المقدمة: قام العلم الحديث على مبدأ الحتمية الذي يعد كل ظاهرة نتيجة لأسباب ثابتة، غير أن اكتشافات الفيزياء الحديثة طرحت تساؤلا حول إطلاقه. فهل مبدأ الحتمية مطلق في العلوم؟\n• الحتمية مطلقة: قرر لابلاس أن عقلا يعرف كل القوى والحالات في لحظة يستطيع التنبؤ بكل المستقبل، وأكد كلود برنار أن الحتمية شرط العلم في الظواهر الجامدة والحية. فبدونها لا قوانين ولا تنبؤ.\n• نقد الأطروحة الأولى: عجزت أمام اللايقين في فيزياء الذرة، وتتعارض مع حرية الإنسان إذا أطلقناها.\n• اللاحتمية: بين هايزنبرغ في مبدأ اللايقين أنه لا يمكن تحديد موضع الجسيم وسرعته في آن واحد بدقة، وصارت قوانين ميكانيكا الكم احتمالية، وهذا يدل على أن الحتمية ليست مطلقة.\n• نقد الأطروحة الثانية: اللايقين لا يعني غياب القوانين، فالاحتمال نفسه يخضع لقوانين إحصائية دقيقة.\n• التركيب: الحتمية قائمة بدقة في الظواهر الكبرى، ونسبية واحتمالية في الميكروفيزياء، فهي مبدأ مرن يتكيف مع ميدان الدراسة.\n• الخاتمة: إذن الحتمية ليست مطلقة لكنها تظل أساس العلم ما دام الاحتمال نفسه منضبطا بقوانين.\n▸ للحفظ\n• الحتمية مبدأ العلم الكلاسيكي، والاحتمال سمة الفيزياء الذرية، والموقف: حتمية نسبية."}],maps:'philoS'};
  var pAr={name:'اللغة العربية',lessons:[{"title":"1. عصر الضعف: لمحة تاريخية","content":"▸ الحدود الزمنية\n• من سقوط بغداد (656هـ / 1258م)\n• إلى حملة نابليون على مصر (1213هـ / 1798م)\n• يسمى أيضا عصر الانحطاط أو العصر المملوكي والعثماني\n▸ الحياة السياسية\n• سقوط بغداد على يد المغول\n• حكم المماليك في مصر والشام\n• ثم الحكم العثماني (1517م)\n• الحروب والاضطرابات وتفكك الوحدة\n▸ الحياة الاجتماعية والثقافية\n• الظلم والفقر وانتشار الأمراض\n• انتشار التصوف والطرق الصوفية\n• مصر والشام ملجأ العلماء\n• ظهور الموسوعات وجمع التراث\n▸ خصائص الأدب\n• انحصار موضوعاته في المديح النبوي والزهد\n• التقليد والاقتباس وقلة التجديد\n• الإفراط في المحسنات البديعية\n• ضعف العاطفة والصدق الفني\n▸ أهم المصطلحات\n• عصر الضعف\n• المماليك\n• الصنعة\n• التصوف\n▸ شرح موسّع\n• سمي هذا العصر بعصر الضعف لما أصاب الأمة الإسلامية من تفكك سياسي وتراجع علمي وأدبي بعد سقوط بغداد. غير أن العلماء يرون أنه لم يخل من حركة علمية نشطة، فقد ألفت فيه الموسوعات الكبرى وحفظ التراث. وفي الأدب سيطر التقليد والتكلف والصنعة اللفظية، وانصرف الشعراء إلى المديح النبوي والزهد، وانتشر النثر المسجوع. وقد ساعد انتشار التصوف على ازدهار شعر الزهد والمدائح. وانتهى هذا العصر بحملة نابليون على مصر التي أيقظت الأمة ومهدت لحركة النهضة.\n▸ أمثلة وتطبيقات\n• من أبرز شعراء العصر: البوصيري في المديح النبوي، وابن نباتة المصري وابن الوردي في الزهد والحكمة، وصفي الدين الحلي في البديعيات.\n▸ للحفظ\n• عصر الضعف: 656هـ - 1213هـ، سمته التقليد والصنعة، وموضوعاته الكبرى: المديح النبوي والزهد."},{"title":"2. شعر الزهد في عصر الضعف","content":"▸ تعريف الزهد\n• الإعراض عن زينة الدنيا وملذاتها طلبا للآخرة والتزاما بالقناعة والتقوى.\n▸ أسباب انتشاره\n• اضطراب الأوضاع السياسية والحروب\n• الظلم والفقر والأوبئة\n• انتشار التصوف\n• رد فعل على الترف واللهو\n▸ الخصائص الفكرية\n• ذم الدنيا والتحذير من غرورها\n• تذكير بالموت والآخرة\n• الدعوة إلى التوبة والقناعة\n• الوعظ والإرشاد\n▸ الخصائص الفنية\n• لغة سهلة وأسلوب تقريري\n• الاقتباس من القرآن والحديث\n• المحسنات البديعية كالطباق والجناس\n• الصور التقليدية والحكمة\n▸ أهم الشعراء\n• ابن نباتة المصري (686 - 768هـ)\n• ابن الوردي\n• البوصيري\n▸ أهم المصطلحات\n• الزهد\n• الوعظ\n• الاقتباس\n• التصوف\n▸ شرح موسّع\n• يعبر شعر الزهد عن موقف الإنسان من الدنيا في زمن الفتن، فيحذر الشاعر من فتنتها ويذكر القارئ بزوالها، داعيا إلى العمل للآخرة. ومن أعلامه ابن نباتة المصري، وهو محمد بن محمد بن الحسن الجذامي الفارقي المصري (686 - 768هـ)، شاعر وكاتب له ديوان كبير مرتب على حروف الهجاء. ويغلب على لغة هذا الشعر الوضوح والمباشرة، وتكثر فيه ألفاظ الموت والفناء والقبر، ويستعين الشاعر بالطباق مثل: حياة وموت، وبالجناس لتقوية الإيقاع، لكن عاطفته قد تبدو أحيانا مصطنعة.\n▸ أمثلة وتطبيقات\n• في تحليل أي نص زهدي: حدد الفكرة (ذم الدنيا أو الدعوة للتوبة)، ثم أبرز القيمة الدينية والخلقية، ثم الأساليب (طباق، اقتباس، تقرير).\n▸ للحفظ\n• الزهد: ذم الدنيا + تذكير بالآخرة، بلغة سهلة تقريرية وفيها وعظ واقتباس."},{"title":"3. المديح النبوي في عصر الضعف","content":"▸ التعريف\n• غرض شعري يعدد فيه الشاعر صفات الرسول ﷺ وشمائله ومعجزاته وسيرته، ظهر منذ صدر الإسلام على يد حسان بن ثابت.\n▸ أسباب ازدهاره\n• الحملات الصليبية التي شككت في دعوة الرسول\n• انتشار التصوف وحب الرسول\n• الدفاع عن الإسلام\n• الحنين إلى الأماكن المقدسة\n▸ الخصائص الفكرية\n• تعداد شمائل الرسول ومعجزاته\n• الحنين إلى الحجاز والبقاع المقدسة\n• التوسل والتوبة\n• الدعوة إلى اتباع السنة\n▸ الخصائص الفنية\n• صدق العاطفة والحرارة\n• الاقتباس من القرآن والسيرة\n• المحسنات البديعية\n• افتتاح القصيدة بالغزل التقليدي\n▸ أعلامه\n• البوصيري (الكواكب الدرية المعروفة بالبردة)\n• صفي الدين الحلي\n• ابن نباتة وابن الوردي\n▸ أهم المصطلحات\n• المديح النبوي\n• البردة\n• الشمائل\n• المعجزة\n▸ شرح موسّع\n• يعد المديح النبوي من أبرز الأغراض في عصر الضعف، وقد ارتبط بحاجة الأمة إلى التمسك بدينها أمام الحملات الصليبية والتتار. واشتهرت فيه بردة البوصيري التي نظمها على البحر البسيط ونالت شهرة عظيمة وشرحها كثير من العلماء. وغالبا ما يفتتح الشاعر قصيدته بالنسيب (الغزل التقليدي) ثم يتخلص إلى المديح. ويميل المدح إلى سرد المعجزات وتعداد الأخلاق، مع شوق وحنين إلى المدينة المنورة، وتظهر فيه عناية بالبديع والتنميق.\n▸ أمثلة وتطبيقات\n• المطلوب في التقويم النقدي: ذكر قيمة النص الدينية (حب الرسول والدفاع عن الإسلام) وقيمته الفنية (صدق العاطفة وقلة الابتكار).\n▸ للحفظ\n• المديح النبوي: عاطفة دينية صادقة، ومضمون متكرر وتقليد في الشكل، ومن أعلامه البوصيري."},{"title":"4. الاتجاه الكلاسيكي: الإحياء والبعث","content":"▸ التعريف\n• حركة شعرية حديثة أعادت للشعر العربي جزالته ومتانته محاكية الشعراء القدامى.\n▸ نشأته\n• بعد حملة نابليون على مصر (1798م)\n• حركة الطباعة والصحافة والبعثات\n• الاحتكاك بالثقافة الأوروبية\n• رائده محمود سامي البارودي (1839 - 1904)\n▸ أعلامه\n• البارودي\n• أحمد شوقي (1868 - 1932) أمير الشعراء\n• حافظ إبراهيم (1872 - 1932) شاعر النيل\n• معروف الرصافي والزهاوي في العراق\n▸ الخصائص الفكرية\n• معارضة القدماء في أغراضهم\n• المديح والرثاء والفخر\n• القضايا الوطنية والاجتماعية\n• الدفاع عن الإسلام والعروبة\n▸ الخصائص الفنية\n• الالتزام بعمود الشعر\n• جزالة اللفظ وفخامة الأسلوب\n• وحدة البيت لا وحدة القصيدة\n• الصور المستمدة من التراث\n▸ أهم المصطلحات\n• الإحياء والبعث\n• المعارضة\n• عمود الشعر\n• الشوقيات\n▸ شرح موسّع\n• ابتدأ البارودي النهضة الشعرية فاختار شعراء العصر العباسي نماذج يحتذيها، فأعاد للشعر قوته وبلاغته بعد قرون من الضعف. ثم جاء شوقي وحافظ فواصلا المسيرة. وقد اهتم هذا الاتجاه بقضايا الأمة السياسية والاجتماعية، وعارض القصائد المشهورة كقصيدة البحتري في وصف إيوان كسرى. ويؤخذ على الاتجاه الإحيائي أنه ظل أسير النموذج القديم في الشكل، فجاءت القصيدة متفككة الوحدة العضوية، وتأخر في التعبير عن الوجدان الذاتي، فكان ذلك سببا لظهور الاتجاه الرومانسي.\n▸ أمثلة وتطبيقات\n• من الأمثلة: «الشوقيات» ديوان أحمد شوقي، و«ديوان البارودي»، و«ديوان حافظ إبراهيم».\n▸ للحفظ\n• الكلاسيكي = تقليد القدماء في الشكل مع مضامين وطنية واجتماعية جديدة، ورائده البارودي."},{"title":"5. الاتجاه الرومانسي (الشعر الوجداني)","content":"▸ التعريف\n• اتجاه أدبي يجعل الذات والعاطفة محور الشعر، ويعبر عن الوجدان والطبيعة.\n▸ نشأته ومدارسه\n• جماعة الديوان (1921): العقاد والمازني وشكري\n• جماعة أبولو (1932): أحمد زكي أبو شادي\n• الأدب المهجري والرابطة القلمية\n• تأثر بالرومانسية الأوروبية\n▸ أعلامه\n• أبو القاسم الشابي\n• إبراهيم ناجي\n• علي محمود طه\n• إيليا أبو ماضي\n▸ الخصائص الفكرية\n• التعبير عن الذات والوجدان\n• الحزن والألم والحنين\n• التغني بالطبيعة\n• الدعوة إلى الحرية والتجديد\n▸ الخصائص الفنية\n• وحدة القصيدة العضوية\n• لغة موحية وبساطة التعبير\n• الصور الشعرية المبتكرة\n• الموسيقى الهادئة والأوزان المتنوعة\n▸ أهم المصطلحات\n• الوجدان\n• الوحدة العضوية\n• الطبيعة\n• الذاتية\n▸ شرح موسّع\n• ظهر الاتجاه الرومانسي ردا على جمود الاتجاه الإحيائي، فدعا إلى أن يكون الشعر تعبيرا صادقا عن تجربة الشاعر، لا مجرد محاكاة للقدماء. وتصدر هذا الاتجاه جماعة الديوان التي نادت بالتجديد ونقد شوقي، ثم جماعة أبولو التي اهتمت بالوجدان والطبيعة. ومن سمات القصيدة الرومانسية وحدتها العضوية: فكل بيت جزء من بناء متكامل. وتظهر فيها الطبيعة صديقة للشاعر ومرآة لأحاسيسه.\n▸ أمثلة وتطبيقات\n• من نماذجه: «إرادة الحياة» للشابي، و«الأطلال» لإبراهيم ناجي، وقصائد أبي ماضي في التأمل والتفاؤل.\n▸ للحفظ\n• الرومانسي = ذات + وجدان + طبيعة + وحدة عضوية + لغة موحية."},{"title":"6. الأدب المهجري","content":"▸ التعريف\n• أدب الشاميين المهاجرين إلى أمريكا الشمالية والجنوبية في أوائل القرن العشرين.\n▸ المدارس\n• الرابطة القلمية (نيويورك 1920): جبران ونعيمة وأبو ماضي\n• العصبة الأندلسية (ساوباولو 1933): الشاعر القروي وإلياس فرحات\n▸ الخصائص الفكرية\n• النزعة الإنسانية والروحية\n• التأمل في الوجود والمصير\n• الحنين إلى الوطن\n• الدعوة إلى التجديد والحرية\n▸ الخصائص الفنية\n• التحرر من القيود التقليدية\n• اللغة السهلة الموحية\n• الرمز والصورة\n• التجديد في الأوزان والقوافي\n▸ أعلامه\n• جبران خليل جبران\n• ميخائيل نعيمة\n• إيليا أبو ماضي\n• رشيد أيوب\n▸ أهم المصطلحات\n• الرابطة القلمية\n• العصبة الأندلسية\n• الغربة\n• النزعة الروحية\n▸ شرح موسّع\n• دفع الاغتراب شعراء المهجر إلى التأمل في الإنسان والحياة، فحملوا نزعة إنسانية وروحية. وأسس جبران وأصدقاؤه الرابطة القلمية لتحرير الأدب العربي من الجمود وجعله صادقا مرتبطا بالحياة، بينما اهتمت العصبة الأندلسية في البرازيل بالحفاظ على اللغة العربية والبعد عن التقعر. وتميز أدبهم بالصور الجديدة والتجديد فيه. ويظهر الحنين إلى الوطن في قصائدهم بوضوح وصدق.\n▸ أمثلة وتطبيقات\n• جبران: «النبي» و«الأجنحة المتكسرة»، ونعيمة: «الغربال»، وأبو ماضي: «الجداول»، وهي أمثلة على إنتاج الرابطة.\n▸ للحفظ\n• المهجر: تجديد وتأمل وحنين، في رابطتين: القلمية بنيويورك، والأندلسية بالبرازيل."},{"title":"7. الشعر الحر (الشعر الجديد)","content":"▸ التعريف\n• شعر يتحرر من نظام الشطرين والقافية الموحدة ويعتمد التفعيلة والسطر الشعري.\n▸ نشأته\n• العراق عام 1947\n• نازك الملائكة: «الكوليرا»\n• بدر شاكر السياب: «هل كان حبا؟»\n• امتد إلى سائر البلاد العربية\n▸ الرواد\n• بدر شاكر السياب\n• نازك الملائكة\n• عبد الوهاب البياتي\n• صلاح عبد الصبور\n• أبو القاسم سعد الله في الجزائر\n▸ الخصائص الفنية\n• وحدة التفعيلة\n• تنوع القوافي وطول الأسطر\n• الرمز والأسطورة\n• اللغة اليومية والصورة المركبة\n▸ الخصائص الفكرية\n• قضايا الإنسان والمجتمع\n• الواقعية والالتزام\n• الهم القومي والسياسي\n• الغربة والأزمة الحضارية\n▸ أهم المصطلحات\n• التفعيلة\n• السطر الشعري\n• الرمز\n• الأسطورة\n▸ شرح موسّع\n• ظهر الشعر الحر بوصفه ثورة على القصيدة العمودية، ورأى رواده أن الوزن والقافية الموحدة قيود تكبل المعنى. فاعتمدوا تفعيلة واحدة تتكرر بعدد غير ثابت بحسب الدفقة الشعورية، وجعلوا السطر الشعري وحدة الإيقاع. وارتبط بالواقعية فعبر عن أزمة الإنسان المعاصر، واعتمد الرمز والأسطورة لإثراء الدلالة. وهو ما يشرحه درس العروض: نشأة الشعر الحر.\n▸ أمثلة وتطبيقات\n• نموذج للقراءة: قصائد السياب مثل «أنشودة المطر» التي تعتمد تفعيلة واحدة وصورا رمزية.\n▸ للحفظ\n• الشعر الحر: تفعيلة واحدة + سطر شعري + رمز + واقعية، بدأ في العراق عام 1947."},{"title":"8. الأدب الجزائري الحديث: الإصلاح والثورة","content":"▸ الاتجاه الإصلاحي\n• جمعية العلماء المسلمين الجزائريين (1931)\n• ابن باديس والإبراهيمي\n• شعراء: محمد العيد\n• الدعوة إلى العلم والدين واللغة\n▸ الاتجاه الثوري\n• الثورة التحريرية (1954)\n• شعراء: مفدي زكريا\n• الحماس والتمجيد والتضحية\n• النشيد الوطني «قسما»\n▸ الخصائص الفكرية\n• الوطنية والهوية\n• الدفاع عن العربية والإسلام\n• الدعوة إلى الحرية\n• العدالة والكرامة\n▸ الخصائص الفنية\n• الالتزام بعمود الشعر غالبا\n• جزالة اللفظ والصور الملحمية\n• الخطابية والمباشرة\n• الاقتباس من القرآن والتراث\n▸ الثورة في الشعر العربي\n• تأثر الشعراء العرب بالثورة الجزائرية\n• كقصيدة «جميلة بوحيرد» لنزار قباني\n▸ أهم المصطلحات\n• الإصلاح\n• الثورة\n• الهوية\n• الالتزام\n▸ شرح موسّع\n• ارتبط الأدب الجزائري الحديث بالمعركة من أجل الاستقلال. ففي مرحلة الإصلاح جعلت جمعية العلماء الأدب في خدمة الدين واللغة والتعليم، وكانت لغتهم متينة وقصائدهم تدعو إلى النهضة. ثم أشعلت الثورة التحريرية قرائح الشعراء فكتبوا عن بطولات الشعب، وقد كان صدى الثورة الجزائرية في الشعر العربي كبيرا، إذ تغنى بها شعراء المشرق. ويتميز هذا الأدب بالالتزام والصدق والتعبير عن آمال الشعب.\n▸ أمثلة وتطبيقات\n• مفدي زكريا: «اللهب المقدس». محمد العيد: ديوانه. الإبراهيمي: مقالاته الإصلاحية. وهي نماذج من الإنتاج: إصلاحي وثوري.\n▸ للحفظ\n• الجزائري الحديث: إصلاح (علم وهوية) ثم ثورة (حرية واستقلال) بلغة جزلة وقيم وطنية."},{"title":"9. المقالة الأدبية","content":"▸ التعريف\n• قطعة نثرية متوسطة الطول تعالج موضوعا بأسلوب ذاتي وفكر منظم.\n▸ أنواعها\n• ذاتية (أدبية)\n• موضوعية (علمية أو فكرية)\n• إصلاحية\n• نقدية\n▸ عناصرها\n• الفكرة\n• العرض\n• الأسلوب\n• اللغة\n▸ نشأتها\n• ارتبطت بنشأة الصحافة\n• رواد: محمد عبده، الكواكبي\n• ثم: العقاد وطه حسين وأحمد أمين\n• في الجزائر: الإبراهيمي وابن باديس\n▸ خصائصها\n• الوحدة الموضوعية\n• الوضوح والإيجاز\n• الأسلوب المقنع\n• الصدق وبصمة الكاتب\n▸ شرح موسّع\n• ظهرت المقالة بصورتها الحديثة مع الصحافة في القرن التاسع عشر، فأصبحت وسيلة لنشر الفكر الإصلاحي والاجتماعي. وهي تبدأ بمقدمة تثير الموضوع، ثم عرض متسلسل بحجج وأمثلة، ثم خاتمة تلخص. وتختلف المقالة الأدبية الذاتية عن العلمية بأن الأولى تبرز شخصية الكاتب وعاطفته، والثانية تقدم المعلومة بموضوعية. وتعد مقالات الإبراهيمي في «البصائر» نموذجا للمقالة الإصلاحية الجزائرية.\n▸ أمثلة وتطبيقات\n• عند تحليل مقالة: حدد الفكرة العامة، ثم الأفكار الأساسية، ثم النمط (حجاجي أو تفسيري)، ثم خصائص الأسلوب.\n▸ للحفظ\n• المقالة: فكرة منظمة + أسلوب مقنع + بنية (مقدمة، عرض، خاتمة)."},{"title":"10. القصة والمسرحية","content":"▸ القصة\n• سرد أحداث تقع لشخصيات في زمان ومكان\n• عناصرها: الحدث، الشخصيات، الزمان والمكان، الحبكة\n• تنقسم إلى قصة قصيرة ورواية\n• رواد: محمود تيمور، نجيب محفوظ\n▸ في الجزائر\n• الرواية الجزائرية المعربة\n• من رواد: عبد الحميد بن هدوقة\n• رواية «ريح الجنوب»\n▸ المسرحية\n• نص حواري يمثل على الخشبة\n• عناصرها: الحوار، الصراع، الشخصيات، الحبكة (العقدة والحل)\n• رواد: توفيق الحكيم وأحمد شوقي\n▸ المسرح الجزائري\n• رواده: علالو ورشيد قسنطيني ومصطفى كاتب\n• يعالج قضايا اجتماعية ووطنية\n▸ أهم المصطلحات\n• الحبكة\n• العقدة\n• الصراع\n• الحوار\n• الشخصية\n▸ شرح موسّع\n• تعد القصة والمسرحية من الفنون النثرية التي دخلت الأدب العربي الحديث متأثرة بالأدب الغربي. فالقصة تقوم على حدث ينمو عبر شخصيات وتتصاعد فيه الأزمة حتى العقدة ثم الحل، وتكتب بالحوار والصراع، والمسرحية تتميز بالحوار والصراع وتكتب لتمثل على الخشبة. وقد جعل توفيق الحكيم المسرح الذهني وسيلة للتفكير في قضايا الإنسان، في حين اهتم المسرح الجزائري بقضايا الشعب. وتحلل القصة والمسرحية بتحديد الحدث والشخصيات والصراع والزمان والمكان.\n▸ أمثلة وتطبيقات\n• تحليل نموذجي: الشخصية الرئيسية، دافعها، الصراع (داخلي أو خارجي)، وتطور الأحداث.\n▸ للحفظ\n• القصة والمسرحية: حدث + شخصيات + زمان ومكان + حبكة، والمسرحية تتميز بالحوار."},{"title":"11. الإعراب اللفظي والإعراب التقديري","content":"▸ الإعراب اللفظي\n• العلامة ظاهرة على آخر الكلمة\n• مثل: جاء الرجلُ، رأيت الرجلَ، مررت بالرجلِ\n▸ الإعراب التقديري\n• تقدر العلامة ولا تظهر لتعذر النطق بها أو لثقلها أو لاشتغال المحل بحركة المناسبة.\n▸ التعذر\n• الاسم المقصور: الفتى\n• الرفع والنصب والجر بعلامة مقدرة للتعذر\n• الفعل المضارع المعتل بالألف: يسعى (رفع ونصب)\n▸ النقل\n• الاسم المنقوص: القاضي (الرفع والجر)\n• الفعل المعتل بالواو أو الياء: يدعو، يرمي (الرفع)\n• النصب بالفتحة الظاهرة\n▸ المناسبة\n• المضاف إلى ياء المتكلم: كتابي\n• ياء المتكلم تقتضي كسر ما قبلها\n▸ أهم المصطلحات\n• المقصور\n• المنقوص\n• التعذر\n• الثقل\n• المناسبة\n▸ شرح موسّع\n• الإعراب نوعان: لفظي تظهر فيه علامة الإعراب على آخر الكلمة، وتقديري تقدر فيه العلامة. فالاسم المقصور ينتهي بألف لازمة، والألف لا تقبل الحركة، فتقدر عليها الضمة والفتحة والكسرة للتعذر: «جاء الفتى»: الفتى فاعل مرفوع وعلامة رفعه ضمة مقدرة على الألف. أما المنقوص فينتهي بياء لازمة، فتقدر عليه الضمة والكسرة للثقل وتظهر الفتحة: «جاء القاضي»، «مررت بالقاضي»، «رأيت القاضيَ». وفي المضاف إلى ياء المتكلم تقدر الحركة منع من ظهورها اشتغال المحل بحركة المناسبة.\n▸ أمثلة وتطبيقات\n• «هذا الفتى كريم»: الفتى بدل أو خبر مرفوع بضمة مقدرة. «لن يسعى المرء إلا لرزقه»: يسعى فعل مضارع منصوب بلن وعلامة نصبه فتحة مقدرة للتعذر.\n▸ للحفظ\n• المقدر: تعذر (المقصور)، ثقل (المنقوص)، مناسبة (ياء المتكلم)."},{"title":"12. إعراب المعتل الآخر: المقصور والمنقوص والممدود","content":"▸ المقصور\n• اسم معرب آخره ألف لازمة\n• مثل: الفتى، الهدى، العصا\n• إعرابه بحركات مقدرة للتعذر\n▸ المنقوص\n• اسم معرب آخره ياء لازمة قبلها كسرة\n• مثل: القاضي، الداعي، الهادي\n• الضمة والكسرة مقدرتان للثقل والفتحة ظاهرة\n▸ الممدود\n• اسم معرب آخره همزة بعد ألف زائدة\n• مثل: سماء، صحراء، علماء\n• يعرب بحركات ظاهرة\n▸ حالة التنوين\n• المنقوص المنون تحذف ياؤه في الرفع والجر\n• هذا قاضٍ ومررت بقاضٍ\n• ويقال: رأيت قاضيا\n▸ التثنية\n• تقلب ألف المقصور ياء أو واوا\n• فتى: فتيان / عصا: عصوان\n▸ أهم المصطلحات\n• المقصور\n• المنقوص\n• الممدود\n• الحركة المقدرة\n▸ شرح موسّع\n• ينقسم المعتل الآخر في الأسماء إلى مقصور ومنقوص وممدود. فالمقصور يعرب بحركات مقدرة على الألف في كل الحالات، والمنقوص تقدر فيه الضمة والكسرة وتظهر الفتحة، والممدود يعرب كالصحيح بحركات ظاهرة. أما إذا نون المنقوص حذفت ياؤه في الرفع والجر وعوض عنها بالتنوين ويعرب بحركة مقدرة على الياء المحذوفة: «هذا قاضٍ»: قاض خبر مرفوع بضمة مقدرة على الياء المحذوفة منع من ظهورها الثقل.\n▸ أمثلة وتطبيقات\n• «زار الداعي الصحراءَ»: الداعي فاعل مرفوع بضمة مقدرة على الياء للثقل، الصحراء مفعول به منصوب بفتحة ظاهرة لأنه ممدود.\n▸ للحفظ\n• مقصور: كل الحركات مقدرة. منقوص: ضمة وكسرة مقدرتان. ممدود: حركات ظاهرة."},{"title":"13. إعراب المضاف إلى ياء المتكلم","content":"▸ المفهوم\n• اسم أضيف إلى ياء المتكلم فتكسر آخره غالبا لمناسبة الياء.\n▸ الاسم الصحيح\n• الحركات الثلاث مقدرة للمناسبة\n• هذا كتابي (ضمة مقدرة)\n• رأيت كتابي (فتحة مقدرة)\n• قرأت في كتابي (كسرة مقدرة)\n▸ المقصور والمنقوص\n• المقصور: عصاي (حركات مقدرة للتعذر)\n• المنقوص: قاضيَّ في الجر والنصب\n▸ المثنى وجمع المذكر\n• المثنى: غلامايَ (رفع بالألف)\n• جمع المذكر: معلميَّ (جاء معلميَّ)\n• تدغم الواو والياء في ياء المتكلم\n▸ إعراب الياء\n• ضمير متصل مبني على الفتح (أو السكون) في محل جر بالإضافة.\n▸ شرح موسّع\n• إذا أضيف الاسم المعرب إلى ياء المتكلم كسر آخره، فلا تظهر عليه علامات الإعراب. فنقول: «هذا كتابي»: كتاب مرفوع وعلامة رفعه ضمة مقدرة منع من ظهورها اشتغال المحل بحركة المناسبة، وهو مضاف والياء ضمير متصل في محل جر مضاف إليه. وإذا كان المضاف مقصورا أو مثنى أو جمع مذكر سالم بقيت الياء ساكنة أو مفتوحة وأدغم: «جاء معلميَّ»، فتكون علامة الرفع الواو المدغمة في الياء. وتعرب الأسماء الخمسة المضافة إلى الياء بحركات مقدرة كذلك: «هذا أبي».\n▸ أمثلة وتطبيقات\n• «هذا أستاذي»: أستاذ خبر مرفوع بضمة مقدرة. «قرأت كتابي»: كتاب مفعول به منصوب بفتحة مقدرة. «ذهبت إلى مدرستي»: مدرسة اسم مجرور بكسرة مقدرة.\n▸ للحفظ\n• المضاف إلى ياء المتكلم: حركة مقدرة للمناسبة، والياء ضمير في محل جر مضاف إليه."},{"title":"14. البدل وعطف البيان","content":"▸ البدل\n• تابع يمهد له بالمتبوع ويقصد بالحكم دونه.\n▸ أنواع البدل\n• مطابق (كل من كل): جاء الخليفة عمرُ\n• بعض من كل: أكلت الرغيفَ نصفَه\n• اشتمال: أعجبني المعلمُ علمُه\n• إضراب (غلط): نادر\n▸ عطف البيان\n• تابع جامد يوضح متبوعه ويشبه النعت\n• مثل: أقسم بالله أبو حفص عمرُ\n• يتبع المتبوع في كل شيء\n▸ الفرق بينهما\n• البدل يصح أن يحل محل المبدل منه\n• عطف البيان لا يحل محله غالبا\n▸ الإعراب\n• البدل: بدل من... مرفوع/منصوب/مجرور\n• عطف البيان: عطف بيان على...\n▸ شرح موسّع\n• البدل والنعت والتوكيد والعطف تسمى التوابع. والبدل تابع يذكر بعد المتبوع (المبدل منه) لتوضيحه أو تفصيله، ويحل محله في الحكم: «حضر الأستاذ محمدٌ»: محمد بدل مطابق مرفوع. وإذا كان المتبوع جزءا أو متعلقا به سمي بدل بعض أو اشتمال. أما عطف البيان فيشبه النعت لكنه جامد، ويستعمل للإيضاح، كقول القائل: «زارني أخوك خالدٌ». ويتبع المبدل منه في الإعراب (رفعا ونصبا وجرا).\n▸ أمثلة وتطبيقات\n• «أحببت الشاعرَ الشابيَّ»: الشابي بدل مطابق منصوب. «أعجبني القمرُ نورُه»: نوره بدل اشتمال مرفوع، والهاء مضاف إليه.\n▸ للحفظ\n• البدل: مطابق، بعض من كل، اشتمال. وهو يحل محل المبدل منه، عكس عطف البيان."},{"title":"15. التوابع: النعت والعطف","content":"▸ النعت\n• تابع يبين صفة في متبوعه أو في ما يتعلق به\n• حقيقي: جاء رجلٌ كريمٌ\n• سببي: جاء رجلٌ كريمٌ أبوه\n▸ مطابقة النعت\n• النعت الحقيقي يطابق منعوته في التذكير والتأنيث والإفراد والتعريف والإعراب\n• النعت السببي يطابقه في الإعراب والتعريف ويوافق ما بعده\n▸ العطف\n• تابع يتوسط بينه وبين متبوعه حرف عطف.\n▸ حروف العطف\n• الواو: لمطلق الجمع\n• الفاء: للترتيب والتعقيب\n• ثم: للترتيب والتراخي\n• أو، أم: للتخيير والشك\n• بل، لكن، لا: للإضراب والاستدراك\n▸ أهم المصطلحات\n• التوابع\n• المنعوت\n• المعطوف\n• المعطوف عليه\n▸ شرح موسّع\n• التوابع أربعة: النعت والتوكيد والبدل والعطف، وهي تتبع المتبوع في إعرابه. والنعت الحقيقي يبين صفة في المنعوت نفسه، مثل: «مررت بشاعرٍ عذبٍ شعرُه»: عذب نعت مجرور، وشعره فاعل. أما النعت السببي فيصف اسما بعده له علاقة بالمنعوت: «قرأت قصيدةً رائعةً». وحروف العطف تجمع بين المعطوف والمعطوف عليه في الحكم، فنقول: «جاء الأستاذ والطلاب». ويعرب المعطوف تابعا للمعطوف عليه.\n▸ أمثلة وتطبيقات\n• «جاء الطالب المجتهد»: المجتهد نعت مرفوع. «نجح علي فخالد»: خالد معطوف على علي مرفوع بالضمة.\n▸ للحفظ\n• النعت يطابق منعوته، والعطف يجمع بحرف، وكلاهما يتبع المتبوع في الإعراب."},{"title":"16. الممنوع من الصرف","content":"▸ التعريف\n• اسم لا يدخله التنوين ويجر بالفتحة نيابة عن الكسرة.\n▸ أسبابه\n• العلمية مع التأنيث: فاطمة\n• العلمية مع العجمة: إبراهيم\n• العلمية مع زيادة الألف والنون: عثمان\n• العلمية مع وزن الفعل: أحمد\n• العلمية مع التركيب المزجي: بعلبك\n▸ بدون علمية\n• صيغة منتهى الجموع: مساجد\n• الوصف على وزن أفعل: أحمر\n• الوصف على فعلان: عطشان\n• ألف التأنيث: حمراء، ذكرى\n▸ إعرابه\n• يرفع بالضمة وينصب بالفتحة\n• يجر بالفتحة نيابة عن الكسرة\n▸ حالات دخول الكسرة\n• إذا أضيف: بأحسنِ صورة\n• إذا دخلت عليه أل: بالأحمرِ\n▸ شرح موسّع\n• يمنع الاسم من الصرف (أي من التنوين) إذا وجد فيه سبب واحد قوي أو علتان من علل تسع فرعية. فالعلم المؤنث مثل «فاطمة» ممنوع للعلمية والتأنيث، والأعجمي مثل «إبراهيم» للعلمية والعجمة، وصيغة منتهى الجموع مثل «مساجد» ممنوعة بذاتها. فنقول: «مررت بفاطمةَ»: فاطمة اسم مجرور وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف. فإذا أضيف أو دخلت عليه «أل» جُر بالكسرة: «مررت بالأحمرِ».\n▸ أمثلة وتطبيقات\n• «سلمت على أحمدَ»: أحمد اسم مجرور وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف. «زرت المساجدَ»: مساجد مفعول به منصوب بالفتحة.\n▸ للحفظ\n• الممنوع من الصرف: لا تنوين، يجر بالفتحة، إلا إذا أضيف أو عُرِّف بأل فيجر بالكسرة."},{"title":"17. الاستثناء","content":"▸ التعريف\n• إخراج ما بعد الأداة من حكم ما قبلها.\n▸ الأدوات\n• إلا\n• غير وسوى\n• خلا وعدا وحاشا\n▸ إلا: تام مثبت\n• يجب نصب المستثنى\n• حضر الطلاب إلا زيدا\n▸ إلا: تام منفي\n• يجوز الإتباع والنصب\n• ما حضر الطلاب إلا زيدٌ (بدل) أو زيدا\n▸ إلا: ناقص (مفرغ)\n• يعرب حسب موقعه\n• ما جاء إلا زيدٌ (فاعل)\n▸ غير وسوى\n• تعربان إعراب المستثنى بعد إلا\n• ويجر ما بعدهما بالإضافة\n▸ شرح موسّع\n• يتكون أسلوب الاستثناء من مستثنى منه وأداة ومستثنى، ويتغير إعراب المستثنى بحسب نوع الاستثناء: تام مثبت (ذكر المستثنى منه ولم يسبق بنفي) فينصب المستثنى وجوبا. وتام منفي (سبق بنفي أو شبهه) فيجوز فيه الإتباع على البدلية وهو الأفضل، والنصب. وناقص (لم يذكر المستثنى منه) فيعرب على حسب موقعه، فإن كان فاعلا رفع. وأما «غير» و«سوى» فتعربان بحسب الجملة، والاسم بعدهما مضاف إليه مجرور.\n▸ أمثلة وتطبيقات\n• «ما نجح إلا الطالبُ المجتهدُ»: إلا أداة حصر، الطالب فاعل مرفوع. «حضر الأساتذة غيرَ واحدٍ»: غير مستثنى منصوب وهو مضاف، واحد مضاف إليه.\n▸ للحفظ\n• التام المثبت: نصب. التام المنفي: بدل أو نصب. الناقص: حسب الموقع."},{"title":"18. أساليب: الإغراء والتحذير والاختصاص","content":"▸ الإغراء\n• تنبيه المخاطب على أمر محمود ليلزمه\n• الجدَّ الجدَّ\n• منصوب بفعل محذوف تقديره الزم\n▸ التحذير\n• تنبيه المخاطب على أمر مذموم ليتجنبه\n• إياك والكذبَ\n• إياك: مفعول به لفعل محذوف تقديره احذر\n▸ الاختصاص\n• تخصيص الحكم بالاسم الظاهر بعد ضمير\n• نحن العربَ نكرم الضيف\n• العرب: منصوب بفعل محذوف تقديره أخص\n▸ أهم المصطلحات\n• الفعل المحذوف\n• المغرى به\n• المحذر منه\n• المخصوص\n▸ شرح موسّع\n• هذه أساليب نحوية يحذف فيها الفعل وجوبا ويقام معمولها مقامه. ففي الإغراء نقول: «الصدقَ الصدقَ»: الصدق مفعول به لفعل محذوف تقديره الزم. وفي التحذير: «إياك والنميمةَ»: إياك ضمير منفصل في محل نصب مفعول به لفعل محذوف تقديره احذر، والواو عاطفة، النميمة معطوف منصوب. أما الاختصاص فيأتي بعد ضمير متكلم: «نحن المسلمين نحب الخير»: المسلمين منصوب على الاختصاص بفعل محذوف تقديره أخص.\n▸ أمثلة وتطبيقات\n• «الأمانةَ الأمانةَ»: إغراء. «إياك والغرورَ»: تحذير. «نحن الطلبةَ نجتهد»: اختصاص.\n▸ للحفظ\n• إغراء: الزم، تحذير: احذر، اختصاص: أخص، والفعل محذوف وجوبا في الثلاثة."},{"title":"19. النواسخ: كان وإن ولا النافية للجنس","content":"▸ كان وأخواتها\n• ترفع المبتدأ ويسمى اسمها\n• وتنصب الخبر ويسمى خبرها\n• كان، أصبح، أضحى، ظل، بات، صار، ليس، ما زال\n▸ إن وأخواتها\n• تنصب المبتدأ ويسمى اسمها\n• وترفع الخبر ويسمى خبرها\n• إن، أن، كأن، لكن، ليت، لعل\n▸ لا النافية للجنس\n• تنفي الحكم عن الجنس كله\n• تعمل عمل إن\n• لا طالبَ مهملٌ\n• اسمها المفرد مبني على الفتح في محل نصب\n▸ الإعراب\n• كان الجو جميلا: كان فعل ماض ناقص، الجو اسمها مرفوع، جميلا خبرها منصوب\n• إن العلم نور: إن حرف توكيد ونصب، العلم اسمها منصوب، نور خبرها مرفوع\n▸ شرح موسّع\n• تدخل النواسخ على الجملة الاسمية فتغير إعرابها. فكان وأخواتها أفعال ناقصة ترفع المبتدأ وتنصب الخبر، مثل: «أصبح الجو باردا». وإن وأخواتها حروف تنصب الاسم وترفع الخبر: «ليت الشباب يعود». أما لا النافية للجنس فتنفي الجنس بأكمله: «لا طالبَ مهملٌ»: لا حرف نفي للجنس، طالب اسم لا مبني على الفتح في محل نصب، مهمل خبر لا مرفوع. وإذا كان اسمها مضافا أو شبيها بالمضاف أعرب منصوبا: «لا حافظَ دروسِه خاسرٌ».\n▸ أمثلة وتطبيقات\n• «كان الأمر سهلا»، «إن الصبر مفتاح الفرج»، «لا إله إلا الله»: لا نافية للجنس، إله اسمها مبني على الفتح.\n▸ للحفظ\n• كان: ترفع الاسم وتنصب الخبر. إن: تنصب الاسم وترفع الخبر. لا النافية للجنس: واسمها المفرد مبني على الفتح."},{"title":"20. علم البيان: التشبيه","content":"▸ التعريف\n• الدلالة على مشاركة أمر لأمر آخر في صفة بأداة من أدوات التشبيه.\n▸ أركان التشبيه\n• المشبه\n• المشبه به\n• أداة التشبيه\n• وجه الشبه\n▸ أنواعه\n• تشبيه تام: ذكرت أركانه كلها\n• مرسل: ذكرت الأداة\n• مؤكد: حذفت الأداة\n• مجمل: حذف وجه الشبه\n• بليغ: حذفت الأداة ووجه الشبه\n▸ أغراضه\n• توضيح الصورة\n• التزيين أو التقبيح\n• المبالغة\n▸ أهم المصطلحات\n• المشبه\n• المشبه به\n• الأداة\n• وجه الشبه\n▸ شرح موسّع\n• التشبيه أقدم صور البيان ويقوم على المقارنة بين طرفين يشتركان في صفة. فإذا قلنا: «العلم كالنور في الهداية» فالعلم مشبه، والنور مشبه به، والكاف أداة، والهداية وجه الشبه، وهو تشبيه تام. وإذا قلنا: «العلم نور» حذفنا الأداة والوجه فصار تشبيها بليغا وهو أقوى أنواعه لأنه يجعل المشبه عين المشبه به. وللتشبيه أثره في التوضيح والإقناع وجمال التصوير. ويحلل التشبيه بذكر أركانه ونوعه وسر جماله.\n▸ أمثلة وتطبيقات\n• «العلم نور»: تشبيه بليغ. «الصديق كالمرآة في الصدق»: تشبيه تام. «الصبر مرّ»: تشبيه بليغ (حذفت الأداة والوجه).\n▸ للحفظ\n• التشبيه: أركانه أربعة، وأقواه البليغ (حذف الأداة والوجه)."},{"title":"21. علم البيان: الاستعارة والمجاز المرسل والكناية","content":"▸ الاستعارة\n• تشبيه حذف أحد طرفيه\n• تصريحية: صرح بالمشبه به\n• مكنية: حذف المشبه به ورمز له بلازمة\n▸ مثال الاستعارة\n• رأيت أسدا يخطب (تصريحية)\n• أنشبت المنية أظفارها (مكنية)\n▸ المجاز المرسل\n• كلمة استعملت في غير معناها لعلاقة غير المشابهة\n• علاقاته: السببية، المسببية، الجزئية، الكلية، اعتبار ما كان، المحلية\n▸ الكناية\n• لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي\n• مثل: كثير الرماد: كناية عن الكرم\n▸ أهم المصطلحات\n• الاستعارة\n• القرينة\n• العلاقة\n• الكناية\n▸ شرح موسّع\n• الاستعارة تشبيه بليغ حذف أحد طرفيه، فإن ذكر المشبه به فهي تصريحية، وإن حذف ورمز إليه بشيء من لوازمه فهي مكنية. في قولنا «رأيت أسدا يخطب» شبه الرجل الشجاع بالأسد وصرح بالمشبه به، والقرينة «يخطب». وفي «أنشبت المنية أظفارها» شبهت المنية بوحش ذي أظفار وحذف المشبه به وبقي لازمه الأظفار. أما المجاز المرسل فعلاقته غير المشابهة، كقولنا «رعت الماشية الغيث» أي النبات، والعلاقة السببية. والكناية تعبر عن المعنى بلازمه، فتقول «فلان طويل النجاد» كناية عن طول القامة.\n▸ أمثلة وتطبيقات\n• «شربت كأسا»: مجاز مرسل علاقته المحلية (المراد ما في الكأس). «أرسل القائد عيونه»: مجاز مرسل علاقته الجزئية (العين تدل على الجاسوس). احذر الخلط بين الاستعارة (علاقتها المشابهة) والمجاز المرسل (علاقته غير المشابهة).\n▸ للحفظ\n• الاستعارة: مشابهة (تصريحية/مكنية). المجاز المرسل: علاقة غير المشابهة. الكناية: لازم المعنى."},{"title":"22. علم البديع: المحسنات المعنوية واللفظية","content":"▸ الطباق\n• الجمع بين الشيء وضده\n• طباق إيجاب: ضدان غير منفيين (الحياة والموت)\n• طباق سلب: فعل مثبت وآخر منفي (يعلمون ولا يعلمون)\n▸ المقابلة\n• الجمع بين معنيين أو أكثر ثم ما يقابلهما على الترتيب\n• مثل: يأمر بالعدل وينهى عن الظلم\n▸ الجناس\n• اتفاق اللفظين في النطق واختلافهما في المعنى\n• تام: اتفقا في الحروف والعدد والهيئة والترتيب\n• ناقص: اختلف في واحد منها\n▸ السجع\n• توافق الفاصلتين في الحرف الأخير\n• يحسن إذا جاء عفوا\n▸ أغراضها\n• تقوية المعنى\n• إحداث الموسيقى\n• لفت الانتباه\n▸ شرح موسّع\n• تضيف المحسنات البديعية جمالا إلى الأسلوب، وهي معنوية كالطباق والمقابلة، ولفظية كالجناس والسجع. ففي قوله تعالى: ﴿وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ﴾ جناس تام بين الساعة (القيامة) وساعة (الوقت)، لاتفاقهما لفظا واختلافهما معنى. وفي قولهم: «اللهم أعط منفقا خلفا وأعط ممسكا تلفا» سجع بين خلفا وتلفا، وطباق بين منفق وممسك. وحين نحلل النص لا نكتفي بتسمية المحسن بل نبين أثره في المعنى.\n▸ أمثلة وتطبيقات\n• «الصدق ينجي والكذب يهلك»: طباق بين الصدق والكذب وينجي ويهلك، ومقابلة. «قد تبكي العين فرحا وحزنا»: طباق.\n▸ للحفظ\n• طباق = ضدان، مقابلة = تقابل معنيين، جناس = اتفاق لفظ واختلاف معنى، سجع = توافق الفواصل."},{"title":"23. علم المعاني: الخبر والإنشاء","content":"▸ الخبر\n• كلام يحتمل الصدق والكذب\n• ضروبه: ابتدائي، طلبي، إنكاري\n• أغراضه: فائدة الخبر، لازمه، الفخر، المدح\n▸ الإنشاء الطلبي\n• الأمر\n• النهي\n• الاستفهام\n• التمني\n• النداء\n▸ الإنشاء غير الطلبي\n• التعجب\n• القسم\n• المدح والذم\n• الرجاء\n• صيغ العقود\n▸ أغراض بلاغية\n• الأمر: النصح، الدعاء، الالتماس\n• النهي: التحذير\n• الاستفهام: الإنكار، التعجب، التقرير\n• النداء: التحسر، الاستغاثة\n▸ أهم المصطلحات\n• الخبر\n• الإنشاء\n• الغرض البلاغي\n• الطلب\n▸ شرح موسّع\n• يقسم علم المعاني الكلام إلى خبر وإنشاء. فالخبر يمكن الحكم عليه بالصدق أو الكذب، ويؤكد بحسب حال المخاطب: خالي الذهن لا يحتاج إلى توكيد، والمتردد يؤكد له بمؤكد واحد، والمنكر يؤكد له بأكثر من مؤكد. أما الإنشاء فلا يحتمل الصدق والكذب، وقد يكون طلبيا يستدعي مطلوبا غير حاصل وقت الطلب. وكثيرا ما تخرج الأساليب الإنشائية عن معناها الحقيقي إلى أغراض بلاغية: فالأمر في «ربنا اغفر لنا» دعاء، والاستفهام في «أتخافون ربكم؟» إنكار.\n▸ أمثلة وتطبيقات\n• «أتنتهون في دروسك؟»: استفهام خرج إلى معنى اللوم. «اجتهد»: أمر حقيقي. «ليت الشباب يعود»: تمن.\n▸ للحفظ\n• الخبر يحتمل الصدق والكذب، والإنشاء لا يحتملهما، وللأساليب أغراض بلاغية."},{"title":"24. العروض: التفعيلات والزحافات","content":"▸ تعريف العروض\n• علم يعرف به أوزان الشعر العربي وما يعتريها من تغيير.\n• وضعه الخليل بن أحمد الفراهيدي.\n▸ التفعيلات الأصلية\n• فعولن، مفاعيلن\n• فاعلن، فاعلاتن\n• مستفعلن، متفاعلن\n• مفاعلتن، مفعولات\n▸ الزحاف\n• تغيير يصيب ثواني الأسباب\n• كالخبن (حذف الثاني الساكن) والقبض (حذف الخامس الساكن)\n• لا يلزم\n▸ العلة\n• تغيير يصيب العروض والضرب\n• كالحذف والقطع\n• تلزم القصيدة غالبا\n▸ خطوات التقطيع\n• كتابة البيت كما ينطق\n• تقسيمه إلى مقاطع ثم تفعيلات\n• تسمية البحر\n▸ شرح موسّع\n• يعتمد التقطيع العروضي على الكتابة العروضية: نكتب ما ينطق ونحذف ما لا ينطق، فننون التنوين ونحذف همزة الوصل وننطق الحروف المشددة حرفين. وتتألف التفعيلة من أسباب وأوتاد: فالسبب خفيف (متحرك فساكن) أو ثقيل (متحركان)، والوتد مجموع (متحركان فساكن) أو مفروق. ثم نقابل المقاطع بالتفعيلات لنعرف البحر. وتعرف القصيدة العمودية بوزنها وقافيتها، أما الشعر الحر فيعتمد على تفعيلة واحدة تتكرر بعدد غير ثابت.\n▸ أمثلة وتطبيقات\n• للتدرب: اكتب البيت كما ينطق، ضع علامة (/ للمتحرك و o للساكن)، ثم قسمه إلى مقاطع تطابق التفعيلات، وطبق ذلك على أبيات كتابك المدرسي.\n▸ للحفظ\n• الخطوات: كتابة عروضية ← مقاطع ← تفعيلات ← اسم البحر."},{"title":"25. أشهر البحور الشعرية","content":"▸ الطويل\n• فعولن مفاعيلن فعولن مفاعلن (مرتين)\n▸ البسيط\n• مستفعلن فاعلن مستفعلن فعلن (مرتين)\n▸ الكامل\n• متفاعلن متفاعلن متفاعلن (مرتين)\n▸ الوافر\n• مفاعلتن مفاعلتن فعولن (مرتين)\n▸ الخفيف\n• فاعلاتن مستفعلن فاعلاتن (مرتين)\n▸ أبحر أخرى\n• الرجز: مستفعلن ×6\n• الرمل: فاعلاتن ×6\n• المتقارب: فعولن ×8\n• السريع، المنسرح، الهزج\n▸ شرح موسّع\n• تختلف البحور في عدد تفعيلاتها وترتيبها، ولكل بحر موسيقاه: فالطويل هادئ يتسع للفخر والوصف والحكمة، والبسيط ممتد فخم، والكامل غني بالحركات يناسب الحماسة، والوافر سريع قليل الحشو، والخفيف رشيق. أما الشعر الحر فيقوم على تفعيلة واحدة كالرجز والكامل والمتقارب وتتغير فيه عدد التفعيلات من سطر لآخر. ويدرس الطلاب تقطيع أبيات عمودية ثم تحديد البحر والتفعيلات.\n▸ أمثلة وتطبيقات\n• مثال من الشعر الحر: القصائد المكتوبة على المتقارب (فعولن) أو الرمل (فاعلاتن) في دواوين الحداثة الشعرية.\n▸ للحفظ\n• اربط كل بحر بتفعيلته: طويل = فعولن مفاعيلن، بسيط = مستفعلن فاعلن، كامل = متفاعلن، وافر = مفاعلتن."},{"title":"26. النمط التفسيري","content":"▸ التعريف\n• نمط يهدف إلى شرح فكرة أو ظاهرة أو تقديم معلومات وتبسيطها للقارئ.\n▸ الغرض\n• الإخبار والإعلام\n• التوضيح والتعليل\n• الإفهام\n▸ المؤشرات اللغوية\n• أسلوب التعريف والتقسيم\n• الجمل الخبرية والفعل المضارع\n• أدوات التعليل: لأن، بسبب، نتيجة\n• أدوات الربط والتفسير: أي، أعني، يعني\n▸ بنيته\n• مقدمة تطرح الموضوع\n• عرض بالتحليل والأمثلة\n• خاتمة تلخص\n▸ أهم المصطلحات\n• الشرح\n• التعليل\n• المعلومة\n• التبسيط\n▸ شرح موسّع\n• يتميز النمط التفسيري بالموضوعية والوضوح، فصاحبه لا يحاول إقناع القارئ بوجهة نظر بل نقل معلومة وبيانها. ولذلك يغلب فيه ضمير الغائب والأسلوب الخبري والتعابير العلمية الدقيقة. وتستعمل فيه الأمثلة والمقارنات والجداول لتقريب الفهم. ويظهر في الكتب المدرسية والموسوعات والمقالات العلمية.\n▸ أمثلة وتطبيقات\n• مثال: «الاتصال هو عملية تبادل المعلومات والأفكار بين الأفراد»: جملة تعريفية تؤكد النمط التفسيري.\n▸ للحفظ\n• التفسيري = تعريف وتعليل وتوضيح بأسلوب موضوعي."},{"title":"27. النمط الوصفي","content":"▸ التعريف\n• نمط يصور الأشياء والأشخاص والأماكن بذكر صفاتها وهيئتها.\n▸ الغرض\n• تقريب الصورة للمتلقي\n• التأثير الوجداني\n• إبراز التفاصيل\n▸ المؤشرات اللغوية\n• كثرة النعوت والأحوال\n• الأفعال المضارعة والجمل الاسمية\n• ظروف المكان والزمان\n• الصور البلاغية (تشبيه، استعارة)\n▸ أنواعه\n• وصف موضوعي (علمي)\n• وصف ذاتي (أدبي)\n▸ أهم المصطلحات\n• الصفة\n• الحال\n• الصورة\n• الوصف\n▸ شرح موسّع\n• يعتمد الوصف على الحواس: البصر والسمع واللمس، فيقدم لوحة مفصلة. وفي الوصف الأدبي يتدخل الكاتب بوجدانه فيستعمل التشبيه والاستعارة والألفاظ الموحية، بينما يلتزم الوصف العلمي بالدقة والحياد. ويمكن أن يرد الوصف داخل نص سردي ليرسم الأماكن والشخصيات.\n▸ أمثلة وتطبيقات\n• مثال: وصف الشابي للطبيعة في قصائده يقوم على الصور الحية، وهو وصف ذاتي.\n▸ للحفظ\n• الوصفي = صفات وصور وجمل اسمية ونعوت."},{"title":"28. النمط الحجاجي","content":"▸ التعريف\n• نمط يهدف إلى إقناع المتلقي بفكرة أو موقف باستعمال الحجج والبراهين.\n▸ الغرض\n• الإقناع والتأثير\n• الدفاع عن رأي أو دحض رأي آخر\n▸ بنيته\n• الأطروحة (الدعوى)\n• الحجج والأدلة والأمثلة\n• الاستنتاج\n▸ المؤشرات اللغوية\n• أدوات التوكيد: إن، قد، حقا\n• أدوات التعليل: لأن، إذ\n• أدوات الشرط والنتيجة: إذن، لذلك\n• الأمثلة والاستشهاد\n▸ أنواع الحجج\n• حجة منطقية\n• حجة بالشواهد والأمثلة\n• حجة بالسلطة (قول عالم أو نص مقدس)\n• حجة بالتجربة والمقارنة\n▸ شرح موسّع\n• يقوم الحجاج على علاقة بين مرسل يحاول الإقناع ومتلق يراد التأثير فيه، فيبني الكاتب نصه على دعوى ثم يدعمها بحجج متدرجة من الأضعف إلى الأقوى غالبا، وقد يستبق الاعتراضات فيردها. ويكثر في المقالات الصحفية والخطب والمناظرات. وفي التحليل نستخرج الأطروحة، ثم نحصي الحجج ونصنفها ونحدد الروابط المنطقية التي تنظمها.\n▸ أمثلة وتطبيقات\n• مثال: يقول الكاتب إن التعليم أساس النهضة لأن الأمم المتقدمة بنت حضارتها على العلم: دعوى + حجة تعليلية.\n▸ للحفظ\n• الحجاجي = أطروحة + حجج + روابط منطقية بهدف الإقناع."},{"title":"29. النمط الإرشادي (الإيعازي)","content":"▸ التعريف\n• نمط يوجه المتلقي إلى فعل شيء أو تركه بأوامر ونصائح.\n▸ الغرض\n• التوجيه والإرشاد\n• التعليم والتنبيه\n• الوعظ\n▸ المؤشرات اللغوية\n• أفعال الأمر والنهي\n• المضارع المقرون بلام الأمر\n• أسلوب الإغراء والتحذير\n• الأعداد الترتيبية: أولا، ثانيا\n▸ مجالاته\n• وصفات الطبخ\n• دليل الاستعمال\n• النصائح الصحية\n• الوصايا\n▸ أهم المصطلحات\n• الأمر\n• النهي\n• النصيحة\n• الإرشاد\n▸ شرح موسّع\n• يتميز هذا النمط بالمباشرة، فالكاتب يخاطب القارئ مباشرة بضمير المخاطب. ويرتب الخطوات ترتيبا منطقيا مع استعمال علامات الترتيب. ويحذف الكاتب غالبا المقدمات الطويلة ويدخل في الموضوع مباشرة. ويظهر في الإعلانات ونشرات الصحة وإرشادات السلامة.\n▸ أمثلة وتطبيقات\n• مثال: «اغسل يديك قبل الأكل، ولا تسرف في الطعام»: أمر ونهي يدلان على النمط الإرشادي.\n▸ للحفظ\n• الإرشادي = أمر ونهي وترتيب للخطوات بخطاب مباشر."},{"title":"30. النمط الحواري","content":"▸ التعريف\n• نمط يقوم على تبادل الكلام بين شخصين أو أكثر.\n▸ الغرض\n• تقديم وجهات النظر\n• الكشف عن شخصية المتحاورين\n• تحريك الحدث\n▸ المؤشرات اللغوية\n• الأفعال: قال، سأل، أجاب\n• علامات الترقيم: النقطتان والشرطة\n• ضمائر المخاطب والمتكلم\n• أسلوب الاستفهام\n▸ مجالاته\n• المسرحية\n• القصة\n• المقابلة الصحفية\n• المناظرة\n▸ أهم المصطلحات\n• الحوار\n• السؤال والجواب\n• المتحاوران\n• الأسلوب المباشر\n▸ شرح موسّع\n• يقدم الحوار الشخصيات بألسنتها، فيمنح النص حيوية وواقعية. ويتميز بالقصر والجمل البسيطة والأساليب الإنشائية كالاستفهام والنداء. وقد يكون الحوار خارجيا بين شخصين أو داخليا (مناجاة). ويتناسب مستوى اللغة فيه مع طبيعة الشخصية.\n▸ أمثلة وتطبيقات\n• مثال: «قال: ما اسمك؟ قلت: أحمد»: حوار مباشر يدل على التبادل الكلامي.\n▸ للحفظ\n• الحواري = تبادل الأقوال بين متحاورين بأساليب الاستفهام والجمل القصيرة."},{"title":"31. منهجية تحليل النص والتقويم النقدي","content":"▸ فهم النص\n• قراءة النص واستخراج الفكرة العامة\n• تحديد الأفكار الأساسية والفرعية\n• شرح المفردات الغامضة\n▸ الاتساق والانسجام\n• أدوات الاتساق: العطف، الإحالة، الضمائر\n• الحقول الدلالية\n• تسلسل الأفكار\n▸ الدراسة الفنية\n• الصور البيانية وأثرها\n• المحسنات البديعية\n• الأساليب الخبرية والإنشائية\n▸ التقويم النقدي\n• تحديد قيمة النص الفكرية\n• تحديد قيمته الفنية\n• إبداء رأي معلل مع الاستشهاد\n▸ أهم المصطلحات\n• الفكرة العامة\n• الحقل الدلالي\n• الاتساق\n• التقويم\n▸ شرح موسّع\n• يطلب في البكالوريا غالبا فهم النص وإبراز بنيته، فأبدأ بقراءة النص مرتين وأحدد موضوعه ونمطه، ثم أجيب عن أسئلة الفهم بجمل كاملة مستشهدا بعبارات من النص. وفي الدراسة الفنية أذكر الظاهرة ثم أمثل لها ثم أبين أثرها. وفي التقويم أحكم على النص من حيث المضمون (صدق الفكرة وأهميتها) والشكل (قوة الأسلوب وجمال التصوير) مع تعليل الحكم. ومن المهم ربط النص بصاحبه واتجاهه الأدبي، كأن أذكر أنه رومانسي أو إصلاحي.\n▸ أمثلة وتطبيقات\n• مثال إجابة: «النمط السائد حجاجي: يظهر ذلك في وجود الأطروحة والحجج والروابط المنطقية مثل لأن وإذن».\n▸ للحفظ\n• الإجابة الجيدة: ظاهرة + مثال من النص + أثر."},{"title":"32. منهجية الإنتاج الكتابي والإعراب","content":"▸ الإنتاج الكتابي\n• مقدمة: تمهيد وطرح الموضوع\n• عرض: أفكار مرتبة مع أمثلة\n• خاتمة: نتيجة وموقف\n▸ شروط الكتابة\n• احترام النمط المطلوب\n• سلامة اللغة\n• وضوح الأفكار وتسلسلها\n• استعمال الروابط\n▸ إعراب الجمل\n• حدد الكلمة ثم موقعها\n• اذكر العلامة والسبب\n• أعرب الجملة ومحلها\n▸ الأخطاء الشائعة\n• الخلط بين الحال والتمييز\n• نسيان علامة الإعراب الفرعية\n• إهمال محل الجملة\n▸ نصائح\n• خصص زمنا لكل سؤال\n• اعتن بالخط\n• راجع الإجابة\n▸ شرح موسّع\n• يطلب من الطالب في الإنتاج الكتابي تحرير نص قصير يحترم نمطا معينا كالحجاجي أو التفسيري أو الوصفي، فيبدأ بمقدمة تثير الموضوع، ثم يعرض أفكاره مدعمة بالأمثلة، ثم يختم بنتيجة. ويراعي سلامة العبارة والترقيم. أما الإعراب فيتطلب حفظ علامات الإعراب وتدريبا يوميا: فأحدد نوع الكلمة (اسم، فعل، حرف)، ثم موقعها من الجملة، ثم علامة إعرابها وسببها. وفي الجمل التي لها محل أذكر نوعها (خبر، صفة، حال...).\n▸ أمثلة وتطبيقات\n• مثال إعراب: «جاء الطلابُ مسرعين»: جاء فعل ماض، الطلاب فاعل مرفوع، مسرعين حال منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم.\n▸ للحفظ\n• الكتابة: مقدمة، عرض، خاتمة. الإعراب: الكلمة + الموقع + العلامة + السبب."}],maps:'arab'};
  var pArS={name:'اللغة العربية',lessons:[{"title":"1. المدارس والاتجاهات الأدبية في العصر الحديث","content":"▸ الاتجاه الكلاسيكي (الإحياء والبعث)\n• العودة إلى النموذج الشعري القديم\n• رواده: البارودي، شوقي، حافظ إبراهيم\n• جزالة اللفظ ووحدة البيت والقافية\n• أغراض تقليدية وأخرى وطنية واجتماعية\n▸ الاتجاه الرومانسي\n• التعبير عن الذات والوجدان\n• الطبيعة والحنين والحزن والتأمل\n• وحدة القصيدة وبساطة اللغة\n• من أعلامه: الشابي، جماعة الديوان، أبولو، الرابطة القلمية\n▸ الأدب المهجري\n• أدباء الشام في أمريكا الشمالية والجنوبية\n• الرابطة القلمية (نيويورك) والعصبة الأندلسية\n• التجديد في الشكل والمضمون\n• من أعلام الرابطة: جبران، نعيمة، إيليا أبو ماضي\n▸ الاتجاه الإصلاحي والاجتماعي\n• الدعوة إلى النهضة ومحاربة الجهل والاستبداد\n• ارتباط الأدب بقضايا المجتمع\n• من أعلامه: الكواكبي، الإبراهيمي، الرصافي، محمد العيد\n▸ الأدب الجزائري الحديث\n• الاتجاه الإصلاحي (جمعية العلماء)\n• الاتجاه الثوري (شعر الثورة)\n• من أعلامه: محمد العيد، مفدي زكريا، الإبراهيمي\n▸ أهم المصطلحات\n• الإحياء والبعث\n• الرومانسية\n• المهجر\n• الرابطة القلمية\n• الإصلاح\n▸ شرح موسّع\n• شهد الأدب العربي في العصر الحديث نهضة بعد قرون الضعف، بدأت بحركة الإحياء التي أعادت للشعر ديباجته القديمة وربطته بقضايا الأمة. ثم تأثر الأدباء بالآداب الغربية فظهرت الاتجاهات الرومانسية التي جعلت الذات والوجدان مصدر التعبير، وجاء الأدب المهجري الذي حمل روح التجديد والتأمل الفلسفي في الحياة. وفي الجزائر ارتبط الأدب بحركة الإصلاح الاجتماعي والسياسي الذي واجه الاستبداد والاستعمار والجهل، ثم ارتبط بالثورة التحريرية، فكان صوت الشعب ووسيلة لحفظ الهوية.\n▸ أمثلة وتطبيقات\n• لتحليل أي نص: حدد أولا انتماء صاحبه (إحيائي أم رومانسي أم إصلاحي) ثم استخرج من النص ما يؤكد هذا الانتماء من الألفاظ والصور والأفكار.\n▸ للحفظ\n• كلاسيكي = تقليد وجزالة، رومانسي = ذات وطبيعة، مهجري = تجديد وتأمل، إصلاحي = مجتمع ونهضة."},{"title":"2. إيليا أبو ماضي","content":"▸ التعريف\n• شاعر لبناني مهجري (1889 - 1957)\n• هاجر إلى مصر ثم إلى أمريكا\n• عضو الرابطة القلمية\n▸ أهم آثاره\n• الجداول\n• الخمائل\n• تبر وتراب\n• تذكار الماضي\n• أصدر مجلة السمير\n▸ الاتجاه\n• مدرسة المهجر (الاتجاه الرومانسي التأملي) ضمن الرابطة القلمية.\n▸ الخصائص الفكرية\n• التفاؤل والدعوة إلى الاستمتاع بالجمال\n• التأمل الفلسفي في الحياة والموت\n• الدعوة إلى الحب والتسامح\n• قضايا الإنسانية والعدالة\n▸ الخصائص الفنية\n• لغة سهلة موحية قريبة من الحياة\n• الصور الشعرية والرمز\n• الأسلوب القصصي والحواري\n• الموسيقى العذبة والأوزان القصيرة\n▸ أهم المصطلحات\n• الرابطة القلمية\n• المهجر\n• التفاؤل\n• التأمل\n▸ شرح موسّع\n• يعد إيليا أبو ماضي من كبار شعراء المهجر، وقد صور في شعره قلق الإنسان أمام الوجود، ودعا إلى النظر إلى الحياة بعين الجمال والأمل، فكان من أشد الشعراء تفاؤلا. ويمتاز أسلوبه بالبساطة والوضوح مع العمق الفلسفي، حتى إن قارئه يحس أنه يحاور الحياة نفسها. ويستعمل الحوار والتساؤل في بناء قصائده، كما في قصيدته المشهورة «الطلاسم» التي تطرح أسئلة الوجود والمصير. وقد تأثر بالفكر الإنساني والرومانسي، فكان شعره نقلة نوعية في التعبير الوجداني.\n▸ أمثلة وتطبيقات\n• من قصائده المشهورة: «الطلاسم» (أسئلة الوجود)، و«فلسفة الحياة» (دعوة إلى التفاؤل)، و«كن بلسما». وهي تدل على مزج الفلسفة بالشعر.\n▸ للحفظ\n• أبو ماضي: مهجري تفاؤلي تأملي، لغته سهلة موحية وأسلوبه حواري."},{"title":"3. مفدي زكريا","content":"▸ التعريف\n• شاعر الثورة الجزائرية (1908 - 1977)\n• ولد في بني يزقن بغرداية\n• اعتقله الاستعمار الفرنسي وسُجن\n• كتب نشيد «قسما» (1955) في السجن\n▸ أهم آثاره\n• اللهب المقدس\n• من وحي الأطلس\n• إلياذة الجزائر\n• تحت ظلال الزيتون\n▸ الاتجاه\n• الاتجاه الثوري في الشعر الجزائري مع جذور كلاسيكية في اللغة والبناء.\n▸ الخصائص الفكرية\n• تمجيد الثورة والتضحية\n• الدعوة إلى الحرية والاستقلال\n• الاعتزاز بالهوية والتاريخ\n• الجانب الوطني والقومي\n▸ الخصائص الفنية\n• جزالة اللفظ وقوة العبارة\n• الصور الملحمية\n• الإيقاع الحماسي والتراكيب الخطابية\n• التزام عمود الشعر غالبا\n▸ أهم المصطلحات\n• شعر الثورة\n• النشيد الوطني\n• الملحمة\n• الالتزام\n▸ شرح موسّع\n• يمثل مفدي زكريا صوت الجزائر في كفاحها ضد الاستعمار، فكان شعره لسان الثورة التحريرية وأغنيتها. جمع بين الشاعر والمناضل، فصور في قصائده بطولات الشعب وآلام السجون، وختم هذا الجهد بنشيد «قسما» الذي صار النشيد الوطني. ويغلب على أسلوبه الجزالة والصور الملحمية وطول النفس، مع إيقاع حماسي يناسب موضوعات البطولة. وفي «إلياذة الجزائر» تتبع تاريخ البلاد في مسيرة شعرية طويلة تتغنى بالأمجاد.\n▸ أمثلة وتطبيقات\n• النشيد الوطني الجزائري «قسما» كتبه في سجن بربروس (1955) ثم لحنه محمد فوزي، وهو مثال على توظيف الشعر في خدمة الثورة.\n▸ للحفظ\n• مفدي زكريا: شاعر الثورة الجزائرية، أسلوبه جزل حماسي ملحمي."},{"title":"4. أبو القاسم الشابي","content":"▸ التعريف\n• شاعر تونسي (1909 - 1934)\n• ولد بتوزر ومات شابا في الخامسة والعشرين\n• درس بجامع الزيتونة وتأثر بالأدب الحديث\n▸ أهم آثاره\n• أغاني الحياة (ديوانه)\n• الخيال الشعري عند العرب (محاضرة)\n• قصائد: إرادة الحياة، نشيد الجبار\n▸ الاتجاه\n• الاتجاه الرومانسي (تأثر بمدرسة أبولو والأدب المهجري).\n▸ الخصائص الفكرية\n• الثورة على الجمود والاستبداد\n• الحب والطبيعة\n• الدعوة إلى الحرية والإرادة\n• الحزن والتأمل ونزعة التمرد\n▸ الخصائص الفنية\n• الصور المبتكرة المستمدة من الطبيعة\n• العاطفة الجياشة\n• الخيال الواسع\n• وحدة القصيدة والأسلوب الغنائي\n▸ أهم المصطلحات\n• الرومانسية\n• إرادة الحياة\n• الطبيعة\n• الخيال\n▸ شرح موسّع\n• اشتهر الشابي بقصيدة «إرادة الحياة» التي صارت شعارا للشعوب المناضلة، ومنها: «إذا الشعب يوما أراد الحياة فلا بد أن يستجيب القدر». كان رومانسيا بامتياز: يتخذ الطبيعة صديقا ومرآة لنفسه، ويعبر عن آلامه وأحلامه بصدق وحرارة. وفي كتابه «الخيال الشعري عند العرب» انتقد الجمود في الأدب القديم ودعا إلى شعر يعبر عن العصر وأحاسيس الإنسان. وقصر عمره وإصابته بمرض القلب أضفيا على شعره حزنا عميقا ورغبة في الخلود بالفن.\n▸ أمثلة وتطبيقات\n• ﴿إذا الشعب يوما أراد الحياة فلا بد أن يستجيب القدر﴾ من قصيدة «إرادة الحياة»، وهي تجمع العاطفة الوطنية بالتفاؤل والإرادة.\n▸ للحفظ\n• الشابي: رومانسي تونسي، شعره غنائي مفعم بالطبيعة والتمرد وإرادة الحياة."},{"title":"5. ميخائيل نعيمة","content":"▸ التعريف\n• أديب وناقد لبناني (1889 - 1988)\n• ولد في بسكنتا ودرس في روسيا وأمريكا\n• من مؤسسي الرابطة القلمية\n▸ أهم آثاره\n• الغربال (نقد)\n• همس الجفون (شعر)\n• جبران خليل جبران (سيرة)\n• مرداد\n• سبعون (سيرته)\n▸ الاتجاه\n• مدرسة المهجر: النزعة الروحية والتأملية والتجديدية.\n▸ الخصائص الفكرية\n• التأمل في الوجود والنفس والكون\n• النزعة الصوفية الإنسانية\n• الدعوة إلى التجديد ونبذ التقليد\n• الإيمان بوحدة الوجود\n▸ الخصائص الفنية\n• لغة بسيطة عميقة\n• التحرر من قيود التقليد\n• الرمز والتأمل\n• النثر الفني الموحي\n▸ أهم المصطلحات\n• النزعة الروحية\n• الغربال\n• الرابطة القلمية\n• التجديد\n▸ شرح موسّع\n• كان ميخائيل نعيمة ناقدا ومفكرا إلى جانب كونه شاعرا، وقد أرسى في «الغربال» أسسا نقدية جديدة تدعو إلى الصدق في الأدب وإلى الاهتمام بمضمونه وبعمق التجربة. وفي شعره ونثره مال إلى التأمل والروحانية وعمق التفكير الإنساني. وكان من أنصار التجديد فهاجم التقليد وحذر من الجمود. وتتميز كتابته بالبساطة والنفس الهادئ والعمق، مع قدرة على تحويل الأفكار الفلسفية إلى صور شعرية.\n▸ أمثلة وتطبيقات\n• «الغربال» يمثل ركنا من أركان النقد المهجري؛ يدعو فيه إلى غربلة التراث والإبقاء على ما فيه حياة وصدق.\n▸ للحفظ\n• نعيمة: مهجري تأملي ناقد، نزعته روحية، وأسلوبه بسيط عميق."},{"title":"6. محمد البشير الإبراهيمي","content":"▸ التعريف\n• عالم وأديب جزائري (1889 - 1965)\n• رئيس جمعية العلماء المسلمين الجزائريين بعد ابن باديس\n• رائد النثر الإصلاحي\n▸ أهم آثاره\n• عيون البصائر\n• سجل مؤتمر جمعية العلماء\n• مقالاته في جريدة البصائر\n▸ الاتجاه\n• الاتجاه الإصلاحي: الدفاع عن الإسلام والعربية والهوية الوطنية.\n▸ الخصائص الفكرية\n• الدعوة إلى الإصلاح الديني والاجتماعي\n• الدفاع عن اللغة العربية والهوية\n• محاربة الجهل والاستعمار والخرافة\n• الاعتزاز بالعروبة والإسلام\n▸ الخصائص الفنية\n• جزالة العبارة وقوة البيان\n• السجع والازدواج والمحسنات\n• التأثر بالقرآن والأدب القديم\n• حرارة العاطفة والأسلوب الخطابي\n▸ أهم المصطلحات\n• الإصلاح\n• جمعية العلماء\n• المقالة\n• الهوية\n▸ شرح موسّع\n• يعد الإبراهيمي من أعظم كتاب النثر الجزائري، فقد حمل في مقالاته هم الأمة وواجه الاحتلال الفرنسي بالقلم واللسان. وجمعت لغته بين الفصاحة القديمة وروح العصر، فجاءت الألفاظ قوية محكمة السبك، وتظهر فيها المحسنات من سجع وطباق مع الغنى بالمعاني. وتستحضر مقالاته القرآن والحديث والشعر القديم. وهو إلى ذلك قائد إصلاحي أسهم في بناء المدارس الحرة وإحياء العربية في الجزائر.\n▸ أمثلة وتطبيقات\n• مقالاته في جريدة «البصائر» ومجموعة «عيون البصائر» نموذج للنثر الإصلاحي الذي يجمع بين الفكر والعاطفة.\n▸ للحفظ\n• الإبراهيمي: كاتب إصلاحي جزائري، أسلوبه جزل مسجوع قوي الحجة والعاطفة."},{"title":"7. أحمد أمين","content":"▸ التعريف\n• أديب ومؤرخ ومفكر مصري (1886 - 1954)\n• قاض ثم أستاذ بكلية الآداب\n• أسس لجنة التأليف والترجمة والنشر\n▸ أهم آثاره\n• فجر الإسلام\n• ضحى الإسلام\n• ظهر الإسلام\n• فيض الخاطر\n• حياتي\n▸ الاتجاه\n• النثر الأدبي والفكري ذو المنهج النقدي والتحليلي.\n▸ الخصائص الفكرية\n• دراسة الحضارة الإسلامية دراسة علمية\n• الجمع بين الأصالة والمعاصرة\n• الدعوة إلى التسامح والفكر الحر\n• تحليل المجتمع وأخلاقه\n▸ الخصائص الفنية\n• سهولة العبارة ووضوحها\n• الإيجاز والدقة\n• المنهج التحليلي المنظم\n• الانتقال من الجزئيات إلى الكليات\n▸ أهم المصطلحات\n• الحضارة الإسلامية\n• المنهج النقدي\n• فيض الخاطر\n• المقالة الأدبية\n▸ شرح موسّع\n• اشتهر أحمد أمين بموسوعته في تاريخ الثقافة الإسلامية (فجر الإسلام وضحاه وظهره)، وفيها حلل العوامل الثقافية والاجتماعية المؤثرة في الفكر العربي بمنهج علمي هادئ. وفي «فيض الخاطر» كتب مقالات أدبية قصيرة تتأمل في النفس والمجتمع بأسلوب بسيط عذب. ويتصف نثره بالوضوح والبعد عن التكلف، فيؤثر في القارئ بالفكرة لا بالزخرف، وهو بذلك من رواد المقالة الحديثة.\n▸ أمثلة وتطبيقات\n• «فجر الإسلام» و«ضحى الإسلام» دراسة للحياة العقلية في صدر الإسلام والعصر العباسي، تتسم بالتتبع التاريخي والتحليل.\n▸ للحفظ\n• أحمد أمين: مفكر مصري ومؤرخ، نثره سهل دقيق منهجي."},{"title":"8. محمد العيد آل خليفة","content":"▸ التعريف\n• شاعر جزائري (1904 - 1979)\n• من رواد الشعر الإصلاحي\n• عضو في جمعية العلماء المسلمين الجزائريين\n▸ أهم آثاره\n• ديوان محمد العيد\n• قصائد في الإصلاح والتعليم والوطن\n▸ الاتجاه\n• الاتجاه الإصلاحي الكلاسيكي في الشعر الجزائري.\n▸ الخصائص الفكرية\n• الدعوة إلى العلم والتعليم\n• محاربة الجهل والخرافة والاستعمار\n• الاعتزاز بالإسلام والعروبة\n• التغني بالوطن والتاريخ\n▸ الخصائص الفنية\n• الالتزام بعمود الشعر\n• الألفاظ الجزلة والتراكيب المحكمة\n• الأسلوب الخطابي المباشر\n• الاقتباس من القرآن والتراث\n▸ أهم المصطلحات\n• الشعر الإصلاحي\n• عمود الشعر\n• جمعية العلماء\n• التعليم\n▸ شرح موسّع\n• لقب محمد العيد بأمير شعراء الجزائر لما حظي به من مكانة بين شعراء الإصلاح. ربط شعره بمسيرة النهضة الجزائرية: فدعا إلى فتح المدارس وتعليم العربية وإحياء الهوية، وانتقد الاستعمار والجهل والخرافات. وهو كلاسيكي في بناء القصيدة، يحافظ على وحدة الوزن والقافية، لكنه يملأ القوالب القديمة بمضامين جديدة تعبر عن قضايا عصره. ويتميز أسلوبه بالوضوح والمباشرة التي تناسب وظيفة التوجيه والإصلاح.\n▸ أمثلة وتطبيقات\n• شعره يوازي مقالات الإبراهيمي في الغاية، فكلاهما ينشد الإصلاح لكن عبر الشعر العمودي بدل النثر.\n▸ للحفظ\n• محمد العيد: شاعر الإصلاح الجزائري، كلاسيكي الشكل إصلاحي المضمون."},{"title":"9. عبد الرحمن الكواكبي","content":"▸ التعريف\n• مفكر ومصلح سوري (1855 - 1902)\n• ولد في حلب وصحفي\n• توفي بالقاهرة\n▸ أهم آثاره\n• طبائع الاستبداد ومصارع الاستعباد\n• أم القرى\n▸ الاتجاه\n• الاتجاه الإصلاحي (الفكر السياسي والاجتماعي).\n▸ الخصائص الفكرية\n• مقاومة الاستبداد السياسي والديني\n• الدعوة إلى الحرية والشورى\n• ربط التخلف بالاستبداد\n• الدعوة إلى النهضة العربية\n▸ الخصائص الفنية\n• الأسلوب الجدلي المنطقي\n• الجمل المحكمة والمصطلح الدقيق\n• التعليل والحجاج\n• البعد عن الزخرف\n▸ أهم المصطلحات\n• الاستبداد\n• الحرية\n• الشورى\n• النهضة\n▸ شرح موسّع\n• في «طبائع الاستبداد» حلل الكواكبي آثار الاستبداد على الأخلاق والعلم والاقتصاد والدين، وبين أن الاستبداد أصل كل فساد وأن الشعوب تتحرر بالعلم والوعي. وكان أسلوبه مقنعا يقوم على تقديم الحجة وعرض الأسباب والنتائج، مما جعل كتاباته أقرب إلى الفكر السياسي الحديث. وقد وضع أسسا لحوار بين الدين والحرية، وكان له أثر في دعاة النهضة العربية.\n▸ أمثلة وتطبيقات\n• «طبائع الاستبداد»: يعرف الاستبداد بأنه تصرف فرد أو جماعة في حقوق قوم بالمشيئة وبلا خوف تبعة، ويحلل أثره في المجتمع.\n▸ للحفظ\n• الكواكبي: مصلح سوري مناهض للاستبداد، أسلوبه حجاجي منطقي."},{"title":"10. طه حسين","content":"▸ التعريف\n• أديب وناقد مصري (1889 - 1973)\n• فقد بصره صغيرا\n• عميد الأدب العربي ووزير المعارف\n• درس في الأزهر والجامعة المصرية والسوربون\n▸ أهم آثاره\n• الأيام\n• في الشعر الجاهلي\n• على هامش السيرة\n• مستقبل الثقافة في مصر\n• دعاء الكروان\n▸ الاتجاه\n• التجديد في الفكر والنقد والرواية، والمنهج العقلي الديكارتي.\n▸ الخصائص الفكرية\n• الدعوة إلى الشك المنهجي في دراسة التراث\n• نشر التعليم وتحرير العقل\n• ربط الثقافة المصرية بأوروبا والعالم\n• العناية بالإنسان والقضايا الاجتماعية\n▸ الخصائص الفنية\n• أسلوب سلس يجمع الجمال والوضوح\n• التكرار والموسيقى الداخلية\n• الحوار والسرد القصصي\n• العبارة الموحية والصور\n▸ أهم المصطلحات\n• عميد الأدب\n• الشك المنهجي\n• السيرة الذاتية\n• التجديد\n▸ شرح موسّع\n• اشتهر طه حسين بسيرته الذاتية «الأيام» التي صور فيها طفولته وكفاحه رغم العمى بأسلوب شائق. وفي «في الشعر الجاهلي» طبق منهج الشك على التراث الأدبي فأثار جدلا واسعا. وكان من دعاة تعميم التعليم وجعله حقا للجميع. ويمتاز أسلوبه بعذوبة العبارة وانسياب الجمل وموسيقاها، وقد أبدع في القصة والرواية والنقد والتاريخ. وهو من أبرز أعلام التجديد في الأدب العربي الحديث.\n▸ أمثلة وتطبيقات\n• «الأيام» مثال للنثر الفني: يستعمل ضمير الغائب «الفتى» ويعرض حياته بأسلوب قصصي مؤثر.\n▸ للحفظ\n• طه حسين: عميد الأدب العربي، منهجه عقلي نقدي، وأسلوبه سلس موسيقي."},{"title":"11. معروف الرصافي","content":"▸ التعريف\n• شاعر عراقي (1875 - 1945)\n• ولد في بغداد\n• من شعراء الاتجاه الاجتماعي الإصلاحي\n▸ أهم آثاره\n• ديوان الرصافي\n• دفع الهجنة في ارتضاخ اللكنة\n• الشخصية المحمدية\n▸ الاتجاه\n• الاتجاه الإصلاحي الاجتماعي مع أسلوب كلاسيكي.\n▸ الخصائص الفكرية\n• نصرة الفقراء والمظلومين\n• الدعوة إلى تعليم المرأة وتحريرها\n• نقد الاستبداد والجهل والتقاليد البالية\n• الدعوة إلى العلم والإصلاح\n▸ الخصائص الفنية\n• الأسلوب الخطابي المباشر\n• الواقعية وبساطة الألفاظ\n• الصور الجديدة المستمدة من واقع الناس\n• الالتزام بالقصيدة العمودية\n▸ أهم المصطلحات\n• الشعر الاجتماعي\n• الواقعية\n• الإصلاح\n• تحرير المرأة\n▸ شرح موسّع\n• اتجه الرصافي بشعره إلى قضايا المجتمع العراقي والعربي، فتحدث عن الفقر والجهل وحقوق المرأة وأهمية العلم، وكان ينتقد الظلم السياسي ويدعو إلى العدالة. وهو بذلك شاعر الشعب، ويستخدم لغة واضحة قريبة من الجمهور ليحقق التأثير في المتلقي. ويجمع في شعره بين الصورة الكلاسيكية للقصيدة والمضمون الاجتماعي الجديد، فهو جسر بين القديم والحديث.\n▸ أمثلة وتطبيقات\n• قصيدته «الأرملة المرضعة» وقصائده في حق المرأة والتعليم تعبر عن تعاطفه مع الفئات الضعيفة ودعوته إلى الإصلاح.\n▸ للحفظ\n• الرصافي: شاعر اجتماعي إصلاحي، واقعي الأسلوب، يدعو إلى العلم وتحرير المرأة."},{"title":"12. النمط التفسيري","content":"▸ التعريف\n• نمط يهدف إلى شرح فكرة أو ظاهرة أو تقديم معلومات وتبسيطها للقارئ.\n▸ الغرض\n• الإخبار والإعلام\n• التوضيح والتعليل\n• الإفهام\n▸ المؤشرات اللغوية\n• أسلوب التعريف والتقسيم\n• الجمل الخبرية والفعل المضارع\n• أدوات التعليل: لأن، بسبب، نتيجة\n• أدوات الربط والتفسير: أي، أعني، يعني\n▸ بنيته\n• مقدمة تطرح الموضوع\n• عرض بالتحليل والأمثلة\n• خاتمة تلخص\n▸ أهم المصطلحات\n• الشرح\n• التعليل\n• المعلومة\n• التبسيط\n▸ شرح موسّع\n• يتميز النمط التفسيري بالموضوعية والوضوح، فصاحبه لا يحاول إقناع القارئ بوجهة نظر بل نقل معلومة وبيانها. ولذلك يغلب فيه ضمير الغائب والأسلوب الخبري والتعابير العلمية الدقيقة. وتستعمل فيه الأمثلة والمقارنات والجداول لتقريب الفهم. ويظهر في الكتب المدرسية والموسوعات والمقالات العلمية.\n▸ أمثلة وتطبيقات\n• مثال: «الاتصال هو عملية تبادل المعلومات والأفكار بين الأفراد»: جملة تعريفية تؤكد النمط التفسيري.\n▸ للحفظ\n• التفسيري = تعريف وتعليل وتوضيح بأسلوب موضوعي."},{"title":"13. النمط الوصفي","content":"▸ التعريف\n• نمط يصور الأشياء والأشخاص والأماكن بذكر صفاتها وهيئتها.\n▸ الغرض\n• تقريب الصورة للمتلقي\n• التأثير الوجداني\n• إبراز التفاصيل\n▸ المؤشرات اللغوية\n• كثرة النعوت والأحوال\n• الأفعال المضارعة والجمل الاسمية\n• ظروف المكان والزمان\n• الصور البلاغية (تشبيه، استعارة)\n▸ أنواعه\n• وصف موضوعي (علمي)\n• وصف ذاتي (أدبي)\n▸ أهم المصطلحات\n• الصفة\n• الحال\n• الصورة\n• الوصف\n▸ شرح موسّع\n• يعتمد الوصف على الحواس: البصر والسمع واللمس، فيقدم لوحة مفصلة. وفي الوصف الأدبي يتدخل الكاتب بوجدانه فيستعمل التشبيه والاستعارة والألفاظ الموحية، بينما يلتزم الوصف العلمي بالدقة والحياد. ويمكن أن يرد الوصف داخل نص سردي ليرسم الأماكن والشخصيات.\n▸ أمثلة وتطبيقات\n• مثال: وصف الشابي للطبيعة في قصائده يقوم على الصور الحية، وهو وصف ذاتي.\n▸ للحفظ\n• الوصفي = صفات وصور وجمل اسمية ونعوت."},{"title":"14. النمط الحجاجي","content":"▸ التعريف\n• نمط يهدف إلى إقناع المتلقي بفكرة أو موقف باستعمال الحجج والبراهين.\n▸ الغرض\n• الإقناع والتأثير\n• الدفاع عن رأي أو دحض رأي آخر\n▸ بنيته\n• الأطروحة (الدعوى)\n• الحجج والأدلة والأمثلة\n• الاستنتاج\n▸ المؤشرات اللغوية\n• أدوات التوكيد: إن، قد، حقا\n• أدوات التعليل: لأن، إذ\n• أدوات الشرط والنتيجة: إذن، لذلك\n• الأمثلة والاستشهاد\n▸ أنواع الحجج\n• حجة منطقية\n• حجة بالشواهد والأمثلة\n• حجة بالسلطة (قول عالم أو نص مقدس)\n• حجة بالتجربة والمقارنة\n▸ شرح موسّع\n• يقوم الحجاج على علاقة بين مرسل يحاول الإقناع ومتلق يراد التأثير فيه، فيبني الكاتب نصه على دعوى ثم يدعمها بحجج متدرجة من الأضعف إلى الأقوى غالبا، وقد يستبق الاعتراضات فيردها. ويكثر في المقالات الصحفية والخطب والمناظرات. وفي التحليل نستخرج الأطروحة، ثم نحصي الحجج ونصنفها ونحدد الروابط المنطقية التي تنظمها.\n▸ أمثلة وتطبيقات\n• مثال: يقول الكاتب إن التعليم أساس النهضة لأن الأمم المتقدمة بنت حضارتها على العلم: دعوى + حجة تعليلية.\n▸ للحفظ\n• الحجاجي = أطروحة + حجج + روابط منطقية بهدف الإقناع."},{"title":"15. النمط الإرشادي (الإيعازي)","content":"▸ التعريف\n• نمط يوجه المتلقي إلى فعل شيء أو تركه بأوامر ونصائح.\n▸ الغرض\n• التوجيه والإرشاد\n• التعليم والتنبيه\n• الوعظ\n▸ المؤشرات اللغوية\n• أفعال الأمر والنهي\n• المضارع المقرون بلام الأمر\n• أسلوب الإغراء والتحذير\n• الأعداد الترتيبية: أولا، ثانيا\n▸ مجالاته\n• وصفات الطبخ\n• دليل الاستعمال\n• النصائح الصحية\n• الوصايا\n▸ أهم المصطلحات\n• الأمر\n• النهي\n• النصيحة\n• الإرشاد\n▸ شرح موسّع\n• يتميز هذا النمط بالمباشرة، فالكاتب يخاطب القارئ مباشرة بضمير المخاطب. ويرتب الخطوات ترتيبا منطقيا مع استعمال علامات الترتيب. ويحذف الكاتب غالبا المقدمات الطويلة ويدخل في الموضوع مباشرة. ويظهر في الإعلانات ونشرات الصحة وإرشادات السلامة.\n▸ أمثلة وتطبيقات\n• مثال: «اغسل يديك قبل الأكل، ولا تسرف في الطعام»: أمر ونهي يدلان على النمط الإرشادي.\n▸ للحفظ\n• الإرشادي = أمر ونهي وترتيب للخطوات بخطاب مباشر."},{"title":"16. النمط الحواري","content":"▸ التعريف\n• نمط يقوم على تبادل الكلام بين شخصين أو أكثر.\n▸ الغرض\n• تقديم وجهات النظر\n• الكشف عن شخصية المتحاورين\n• تحريك الحدث\n▸ المؤشرات اللغوية\n• الأفعال: قال، سأل، أجاب\n• علامات الترقيم: النقطتان والشرطة\n• ضمائر المخاطب والمتكلم\n• أسلوب الاستفهام\n▸ مجالاته\n• المسرحية\n• القصة\n• المقابلة الصحفية\n• المناظرة\n▸ أهم المصطلحات\n• الحوار\n• السؤال والجواب\n• المتحاوران\n• الأسلوب المباشر\n▸ شرح موسّع\n• يقدم الحوار الشخصيات بألسنتها، فيمنح النص حيوية وواقعية. ويتميز بالقصر والجمل البسيطة والأساليب الإنشائية كالاستفهام والنداء. وقد يكون الحوار خارجيا بين شخصين أو داخليا (مناجاة). ويتناسب مستوى اللغة فيه مع طبيعة الشخصية.\n▸ أمثلة وتطبيقات\n• مثال: «قال: ما اسمك؟ قلت: أحمد»: حوار مباشر يدل على التبادل الكلامي.\n▸ للحفظ\n• الحواري = تبادل الأقوال بين متحاورين بأساليب الاستفهام والجمل القصيرة."},{"title":"17. بديهيات في القواعد: الإعراب والبناء","content":"▸ المفاهيم\n• الإعراب: تغيير أواخر الكلمات لاختلاف العوامل\n• البناء: لزوم آخر الكلمة حالة واحدة\n• المعرب: الأسماء المتمكنة والفعل المضارع غير المتصل بالنون\n▸ علامات الرفع\n• الأصلية: الضمة\n• الواو: الأسماء الخمسة وجمع المذكر السالم\n• الألف: المثنى\n• ثبوت النون: الأفعال الخمسة\n▸ علامات النصب\n• الأصلية: الفتحة\n• الألف: الأسماء الخمسة\n• الكسرة: جمع المؤنث السالم\n• الياء: المثنى وجمع المذكر السالم\n• حذف النون: الأفعال الخمسة\n▸ علامات الجر والجزم\n• الجر: الكسرة، والياء، والفتحة للممنوع من الصرف\n• الجزم: السكون، وحذف حرف العلة، وحذف النون\n▸ أهم المصطلحات\n• المرفوعات\n• المنصوبات\n• المجرورات\n• المبني\n• الممنوع من الصرف\n▸ شرح موسّع\n• تقوم الجملة العربية على ركنين: جملة اسمية تبدأ باسم (مبتدأ وخبر)، وجملة فعلية تبدأ بفعل (فعل وفاعل). والإعراب يكشف وظيفة الكلمة في الجملة ويحدد علامتها حسب موقعها. فالأسماء الخمسة (أبو، أخو، حمو، فو، ذو) ترفع بالواو وتنصب بالألف وتجر بالياء. والمثنى يرفع بالألف ويجر وينصب بالياء. وجمع المذكر السالم يرفع بالواو وينصب ويجر بالياء. والممنوع من الصرف يجر بالفتحة نيابة عن الكسرة ما لم يضف أو تدخل عليه أل.\n▸ أمثلة وتطبيقات\n• مثال: «جاء أبو أحمد»: أبو فاعل مرفوع وعلامة رفعه الواو لأنه من الأسماء الخمسة. «مررت بالمعلمين»: المعلمين اسم مجرور وعلامة جره الياء لأنه جمع مذكر سالم.\n▸ للحفظ\n• حفظ علامات الإعراب الفرعية: واو، ألف، ياء، كسرة، حذف نون."},{"title":"18. إعراب: إذ، إذا، إذن","content":"▸ إذ\n• ظرف للزمن الماضي\n• مبني على السكون في محل نصب\n• تضاف إلى الجملة بعدها (في محل جر)\n▸ إذا\n• ظرف لما يستقبل من الزمان فيه معنى الشرط\n• مبني في محل نصب\n• جوابها جملة تتعلق بها\n• إذا الفجائية: حرف مفاجأة\n▸ إذن\n• حرف جواب وجزاء\n• ينصب المضارع إن تصدرت\n• وكان الفعل بعدها مستقبلا\n• وألا يفصل بينها وبينه فاصل غير القسم أو لا النافية\n▸ حالات إلغاء إذن\n• تقع حشوا في الجملة: أنا إذن أكرمك\n• يكون الفعل بعدها للحال: إذن أظنك صادقا\n▸ أهم المصطلحات\n• الظرف\n• الشرط\n• حرف جواب\n• المفاجأة\n▸ شرح موسّع\n• «إذ» ظرف للماضي مضاف إلى جملة، كقولنا: «زرتك إذ طلع الفجر»: إذ ظرف زمان مبني على السكون في محل نصب مفعول فيه، وجملة طلع الفجر في محل جر بالإضافة. و«إذا» تدل على المستقبل وتتضمن معنى الشرط: «إذا جاء نصر الله والفتح». أما «إذن» فحرف جواب وجزاء ينصب المضارع إذا تصدر وكان للاستقبال، ولم يفصل بينه وبين الفعل فاصل غير القسم أو «لا» النافية. وإذا لم تتوافر الشروط الثلاثة أُهملت ورُفع المضارع بعدها.\n▸ أمثلة وتطبيقات\n• مثال: قال رجل: «سأزورك». فتقول: «إذن أكرمَك»: إذن حرف جواب وجزاء ونصب، وأكرمك فعل مضارع منصوب بإذن. وفي «فإذا الأسد واقف»: إذا فجائية حرف، والأسد مبتدأ.\n▸ للحفظ\n• إذ للماضي، إذا للمستقبل والشرط، إذن حرف جواب ينصب المضارع بشروط."},{"title":"19. إعراب: لو ولولا","content":"▸ لو\n• حرف شرط غير جازم\n• يفيد امتناع الجواب لامتناع الشرط\n• يليها فعل ماض غالبا\n• جوابها اللام + ماض أو ماض منفي بما\n▸ استعمالات لو\n• شرطية: لو اجتهدت لنجحت\n• مصدرية بعد ود ويود: ودوا لو تدهن\n• للتمني: لو أن لي كرة\n▸ لولا الشرطية\n• حرف امتناع لوجود\n• تدخل على المبتدأ\n• خبره محذوف وجوبا\n• جوابها اللام + ماض\n▸ لولا التحضيضية\n• تدخل على الفعل\n• تفيد الحث والطلب\n• تفيد العرض أيضا\n• لا جواب لها\n▸ أهم المصطلحات\n• حرف شرط غير جازم\n• امتناع لامتناع\n• امتناع لوجود\n• التحضيض\n▸ شرح موسّع\n• «لو» تربط جملة الشرط بجملة الجواب وتدل على أن الجواب لم يقع لأن الشرط لم يقع: «لو اجتهدت لنجحت» أي لم تجتهد فلم تنجح. وإعرابها: لو حرف شرط غير جازم مبني على السكون لا محل له، وجملة اجتهدت (فعل الشرط) لا محل لها من الإعراب، واللام واقعة في جواب لو، وجملة نجحت جواب شرط غير جازم لا محل لها. أما «لولا» فتدل على أن الجواب امتنع لوجود الشرط: «لولا العلم لهلك الناس»: لولا حرف شرط غير جازم يفيد امتناع الجواب لوجود الشرط، والعلم مبتدأ مرفوع وخبره محذوف وجوبا تقديره موجود. وإذا دخلت على الفعل صارت للحث: «لولا تستغفرون الله»: حرف تحضيض.\n▸ أمثلة وتطبيقات\n• «لولا أنتم لكنا مؤمنين»: لولا حرف شرط غير جازم، أنتم ضمير منفصل في محل رفع مبتدأ خبره محذوف وجوبا. «لولا تذاكر دروسك»: لولا حرف تحضيض لا محل له من الإعراب.\n▸ للحفظ\n• لو: امتناع لامتناع. لولا + اسم: امتناع لوجود. لولا + فعل: تحضيض."},{"title":"20. صيغتا التعجب","content":"▸ ما أفعله\n• ما: نكرة تامة بمعنى شيء، مبتدأ\n• أفعل: فعل ماض جامد لإنشاء التعجب\n• فاعله ضمير مستتر وجوبا\n• المتعجب منه: مفعول به\n▸ أفعل به\n• أفعل: فعل ماض بلفظ الأمر\n• الباء حرف جر زائد\n• المتعجب منه: مجرور لفظا مرفوع محلا فاعل\n▸ شروط فعل التعجب\n• ثلاثي\n• تام\n• مثبت\n• مبني للمعلوم\n• قابل للتفاضل\n• غير دال على لون أو عيب\n▸ التعجب من غير المستوفي\n• نتوصل بفعل مساعد: أشد، أكثر، أحسن\n• ثم نأتي بالمصدر منصوبا: ما أشد استخراجه\n▸ أهم المصطلحات\n• التعجب\n• المتعجب منه\n• الفعل الجامد\n• الباء الزائدة\n▸ شرح موسّع\n• للتعجب صيغتان قياسيتان: «ما أفعله» و«أفعِل به». ففي «ما أجملَ السماءَ!» ما نكرة تامة بمعنى شيء عظيم مبتدأ، وأجمل فعل ماض مبني على الفتح، وفاعله ضمير مستتر وجوبا تقديره هو يعود على ما، والسماء مفعول به، وجملة أجمل السماء في محل رفع خبر. وفي «أجمِلْ بالسماءِ!» أجمل فعل ماض جاء على صيغة الأمر، والباء حرف جر زائد، والسماء اسم مجرور لفظا مرفوع محلا فاعل. وإذا كان الفعل غير مستوف للشروط نستعمل صيغة مساعدة، فنقول: «ما أشدَّ سوادَ الليل» لأن السواد لون.\n▸ أمثلة وتطبيقات\n• «ما أروع الصدقَ!»: ما نكرة تامة مبتدأ، أروع فعل ماض جامد، الصدق مفعول به. «أكرِمْ بالعلمِ!»: أكرم فعل ماض جاء بصيغة الأمر، الباء زائدة، العلم فاعل مرفوع محلا.\n▸ للحفظ\n• ما أفعل + منصوب، أفعل به + مجرور بباء زائدة، والشروط: ثلاثي تام مثبت قابل للتفاضل."},{"title":"21. الحال","content":"▸ التعريف\n• وصف فضلة منصوب يبين هيئة صاحبه وقت وقوع الفعل.\n▸ أنواعه\n• مفرد: جاء الطالب مسرعا\n• جملة اسمية: جاء والشمس طالعة\n• جملة فعلية: جاء يبكي\n• شبه جملة: رأيته في الدار\n▸ شروط صاحب الحال\n• يكون معرفة غالبا\n• ويقع نكرة بمسوغ\n▸ شروط الحال\n• نكرة غالبا\n• منصوب\n• مشتق غالبا\n▸ أهم المصطلحات\n• صاحب الحال\n• الجملة الحالية\n• الواو الحالية\n• هيئة\n▸ شرح موسّع\n• الحال فضلة أي ليست ركنا أساسيا في الجملة، لكنها تزيدها معنى. فإن قلنا: «عاد الجنود فرحين» فكلمة فرحين تبين هيئة الجنود عند العودة، وهي حال منصوبة وعلامة نصبها الياء لأنها جمع مذكر سالم. وإذا جاءت جملة اسمية رُبطت بالواو أو الضمير: «دخل المعلم والتلاميذ ينتظرونه». وإذا جاءت جملة فعلية مضارعة مثبتة فتكفي الضمير: «جاء الطفل يبكي». وتعرب الجملة الحالية: في محل نصب حال.\n▸ أمثلة وتطبيقات\n• «رجع الطالب مسرورا»: رجع فعل ماض، الطالب فاعل، مسرورا حال منصوبة وعلامة نصبها الفتحة. «جاء الرجل وهو يضحك»: الواو حالية، وجملة هو يضحك في محل نصب حال.\n▸ للحفظ\n• الحال: هيئة صاحبها، منصوب، نكرة غالبا، ويأتي مفردا وجملة وشبه جملة."},{"title":"22. التوكيد","content":"▸ التعريف\n• تابع يذكر لتقوية معنى المتبوع ورفع الاحتمال عنه.\n▸ التوكيد اللفظي\n• تكرار اللفظ نفسه: جاء جاء الأمير\n• تكرار المعنى بمرادف\n• يتبع المؤكد في الإعراب\n▸ التوكيد المعنوي\n• النفس والعين: جاء الأمير نفسه\n• كل وجميع وعامة: حضر الطلاب كلهم\n• كلا وكلتا للمثنى\n▸ حكم ألفاظه\n• يجب اتصالها بضمير يطابق المؤكد\n• تتبع المؤكد رفعا ونصبا وجرا\n▸ أهم المصطلحات\n• المؤكد\n• التابع\n• النفس\n• كل\n▸ شرح موسّع\n• التوكيد من التوابع الأربعة (النعت، التوكيد، البدل، العطف). فإذا قلت: «قرأت الكتاب كله» فكلمة كل توكيد معنوي تفيد الشمول، وتعرب: توكيد معنوي منصوب وعلامة نصبه الفتحة، وهو مضاف والهاء مضاف إليه. ويكون التوكيد المعنوي بالنفس والعين لرفع احتمال المجاز: «جاء الوزير نفسه»، وبكل وجميع وعامة لتأكيد الشمول، وبكلا وكلتا للمثنى. أما اللفظي فيكون بتكرار اللفظ أو معناه لتقوية الأثر كقولك: «أسرع أسرع».\n▸ أمثلة وتطبيقات\n• «حضر المعلمون كلهم»: كلهم توكيد معنوي مرفوع وعلامة رفعه الضمة، وهو مضاف والهاء ضمير في محل جر مضاف إليه. «جاء جاء الأمير»: جاء الثانية توكيد لفظي.\n▸ للحفظ\n• التوكيد: لفظي (تكرار) ومعنوي (نفس، عين، كل، جميع، كلا، كلتا) ويتبع المؤكد."},{"title":"23. المنادى","content":"▸ التعريف\n• اسم يطلب الإقبال عليه بحرف نداء ظاهر أو مقدر.\n▸ أحرف النداء\n• يا\n• أيا\n• هيا\n• أي\n• الهمزة\n• وا للندبة\n▸ المنادى المبني\n• المفرد العلم: يا محمد (على الضم)\n• النكرة المقصودة: يا رجل\n• المثنى والجمع: يا طاليان (بالألف)\n▸ المنادى المنصوب\n• المضاف: يا عبد الله\n• الشبيه بالمضاف: يا طالعا جبلا\n• النكرة غير المقصودة: يا غافلا\n▸ أهم المصطلحات\n• حرف النداء\n• المنادى\n• المفرد العلم\n• الندبة\n▸ شرح موسّع\n• المنادى بعد أداة النداء إما مبني وإما منصوب. فالمفرد العلم والنكرة المقصودة يبنيان على ما يرفعان به لو كانا معربين: «يا محمدُ» مبني على الضم في محل نصب. والمضاف والشبيه به والنكرة غير المقصودة منصوبة: «يا عبدَ الله». ويعرب: يا حرف نداء، محمد منادى مفرد علم مبني على الضم في محل نصب. وفي «يا أيها الناس» أي منادى مبني على الضم، وها للتنبيه، والناس نعت أو بدل مرفوع. وللنداء أغراض بلاغية كالتحسر والتنبيه والاستغاثة.\n▸ أمثلة وتطبيقات\n• «يا محمدُ تعال»: يا حرف نداء، محمد منادى مفرد علم مبني على الضم في محل نصب. «يا طالبَ العلم»: طالب منادى مضاف منصوب وعلامة نصبه الفتحة، العلم مضاف إليه مجرور.\n▸ للحفظ\n• المبني: مفرد علم ونكرة مقصودة. المنصوب: المضاف وشبهه والنكرة غير المقصودة."},{"title":"24. أسماء الاستفهام","content":"▸ المفهوم\n• أسماء يستفهم بها عن الشخص أو الشيء أو الزمان أو المكان أو الحال أو العدد.\n▸ أهمها\n• من: للعاقل\n• ما وماذا: لغير العاقل\n• متى وأيان: للزمان\n• أين وأنى: للمكان\n• كيف: للحال\n• كم: للعدد\n• أي: بحسب ما تضاف إليه\n▸ أحكامها\n• لها الصدارة في الجملة\n• مبنية إلا أي (معربة)\n• إعرابها بحسب موقعها\n• قد تجر بحرف جر: بكم، عمن\n▸ كم الاستفهامية\n• تمييزها منصوب مفرد: كم كتابا قرأت؟\n• قد يجر بمن: كم من كتاب\n▸ أهم المصطلحات\n• الاستفهام\n• الصدارة\n• التمييز\n• الظرف\n▸ شرح موسّع\n• أسماء الاستفهام أسماء مبنية يتحدد إعرابها بحسب موقعها في الجملة: فإن كان بعدها اسم فقد تكون خبرا مقدما: «من أنت؟»: من اسم استفهام مبني في محل رفع خبر مقدم. وإن كان بعدها فعل لازم فقد تكون مبتدأ، وإن كان متعديا فقد تكون مفعولا به: «ماذا فعلت؟»: ماذا اسم استفهام في محل نصب مفعول به. وإن كانت ظرفا فمنصوبة: «متى سافرت؟» متى اسم استفهام مبني في محل نصب ظرف زمان. وأما كيف فتعرب خبرا مقدما أو حالا بحسب السياق.\n▸ أمثلة وتطبيقات\n• «كيف حالك؟»: كيف اسم استفهام مبني في محل رفع خبر مقدم، حالك مبتدأ مؤخر. «كم كتابا قرأت؟»: كم في محل نصب مفعول به مقدم، كتابا تمييز منصوب.\n▸ للحفظ\n• أسماء الاستفهام لها الصدارة وإعرابها حسب موقعها: خبر مقدم، مفعول، ظرف، مبتدأ."},{"title":"25. إعراب: رُبَّ وربما","content":"▸ رُبَّ\n• حرف جر شبيه بالزائد\n• تجر النكرة\n• تفيد التقليل أو التكثير\n• مجرورها مبتدأ في المحل\n▸ شروط رب\n• يكون مجرورها نكرة\n• يتقدمها فعل مضي أو يحذف الفعل\n• لها الصدارة\n▸ ربما\n• رب + ما الكافة\n• كفت رب عن العمل\n• تدخل على الجملة الفعلية غالبا\n• فتصير حرف تقليل أو تكثير\n▸ الإعراب\n• رب: حرف جر شبيه بالزائد\n• ما: كافة ومكفوفة\n• الجملة بعدها لا محل لها أو في المحل المناسب\n▸ أهم المصطلحات\n• حرف جر زائد\n• ما الكافة\n• التقليل\n• التكثير\n▸ شرح موسّع\n• «رب» حرف جر خاص بالنكرات، يفيد غالبا التقليل أو التكثير بحسب السياق، ويعد شبيها بالزائد لأن حذفه لا يؤثر في الإسناد، ولذلك يعرب مجروره مبتدأ مرفوعا محلا. مثال: «رُبَّ أخٍ لك لم تلده أمك»: رب حرف جر شبيه بالزائد، أخ اسم مجرور لفظا مبتدأ مرفوع محلا، وجملة لم تلده أمك صفة. وإذا اتصلت بها «ما» الكافة صارت «ربما» وكفتها عن العمل فتدخل على الجمل: «ربما يود الذين كفروا لو كانوا مسلمين»: ربما: رب حرف تقليل، ما كافة، يود فعل مضارع مرفوع.\n▸ أمثلة وتطبيقات\n• «ربَّ كلمةٍ قالت لصاحبها دعني»: رب حرف جر شبيه بالزائد، كلمة اسم مجرور لفظا مبتدأ مرفوع محلا. «ربما يضحك الحزين»: ربما حرف كاف ومكفوف، يضحك فعل مضارع.\n▸ للحفظ\n• رب تجر النكرة (تقليل/تكثير)، وربما: رب + ما الكافة فتدخل على الجملة."},{"title":"26. علم البيان: التشبيه","content":"▸ التعريف\n• الدلالة على مشاركة أمر لأمر آخر في صفة بأداة من أدوات التشبيه.\n▸ أركان التشبيه\n• المشبه\n• المشبه به\n• أداة التشبيه\n• وجه الشبه\n▸ أنواعه\n• تشبيه تام: ذكرت أركانه كلها\n• مرسل: ذكرت الأداة\n• مؤكد: حذفت الأداة\n• مجمل: حذف وجه الشبه\n• بليغ: حذفت الأداة ووجه الشبه\n▸ أغراضه\n• توضيح الصورة\n• التزيين أو التقبيح\n• المبالغة\n▸ أهم المصطلحات\n• المشبه\n• المشبه به\n• الأداة\n• وجه الشبه\n▸ شرح موسّع\n• التشبيه أقدم صور البيان ويقوم على المقارنة بين طرفين يشتركان في صفة. فإذا قلنا: «العلم كالنور في الهداية» فالعلم مشبه، والنور مشبه به، والكاف أداة، والهداية وجه الشبه، وهو تشبيه تام. وإذا قلنا: «العلم نور» حذفنا الأداة والوجه فصار تشبيها بليغا وهو أقوى أنواعه لأنه يجعل المشبه عين المشبه به. وللتشبيه أثره في التوضيح والإقناع وجمال التصوير. ويحلل التشبيه بذكر أركانه ونوعه وسر جماله.\n▸ أمثلة وتطبيقات\n• «العلم نور»: تشبيه بليغ. «الصديق كالمرآة في الصدق»: تشبيه تام. «الصبر مرّ»: تشبيه بليغ (حذفت الأداة والوجه).\n▸ للحفظ\n• التشبيه: أركانه أربعة، وأقواه البليغ (حذف الأداة والوجه)."},{"title":"27. علم البيان: الاستعارة والمجاز المرسل والكناية","content":"▸ الاستعارة\n• تشبيه حذف أحد طرفيه\n• تصريحية: صرح بالمشبه به\n• مكنية: حذف المشبه به ورمز له بلازمة\n▸ مثال الاستعارة\n• رأيت أسدا يخطب (تصريحية)\n• أنشبت المنية أظفارها (مكنية)\n▸ المجاز المرسل\n• كلمة استعملت في غير معناها لعلاقة غير المشابهة\n• علاقاته: السببية، المسببية، الجزئية، الكلية، اعتبار ما كان، المحلية\n▸ الكناية\n• لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي\n• مثل: كثير الرماد: كناية عن الكرم\n▸ أهم المصطلحات\n• الاستعارة\n• القرينة\n• العلاقة\n• الكناية\n▸ شرح موسّع\n• الاستعارة تشبيه بليغ حذف أحد طرفيه، فإن ذكر المشبه به فهي تصريحية، وإن حذف ورمز إليه بشيء من لوازمه فهي مكنية. في قولنا «رأيت أسدا يخطب» شبه الرجل الشجاع بالأسد وصرح بالمشبه به، والقرينة «يخطب». وفي «أنشبت المنية أظفارها» شبهت المنية بوحش ذي أظفار وحذف المشبه به وبقي لازمه الأظفار. أما المجاز المرسل فعلاقته غير المشابهة، كقولنا «رعت الماشية الغيث» أي النبات، والعلاقة السببية. والكناية تعبر عن المعنى بلازمه، فتقول «فلان طويل النجاد» كناية عن طول القامة.\n▸ أمثلة وتطبيقات\n• «شربت كأسا»: مجاز مرسل علاقته المحلية (المراد ما في الكأس). «أرسل القائد عيونه»: مجاز مرسل علاقته الجزئية (العين تدل على الجاسوس). احذر الخلط بين الاستعارة (علاقتها المشابهة) والمجاز المرسل (علاقته غير المشابهة).\n▸ للحفظ\n• الاستعارة: مشابهة (تصريحية/مكنية). المجاز المرسل: علاقة غير المشابهة. الكناية: لازم المعنى."},{"title":"28. علم البديع: المحسنات المعنوية واللفظية","content":"▸ الطباق\n• الجمع بين الشيء وضده\n• طباق إيجاب: ضدان غير منفيين (الحياة والموت)\n• طباق سلب: فعل مثبت وآخر منفي (يعلمون ولا يعلمون)\n▸ المقابلة\n• الجمع بين معنيين أو أكثر ثم ما يقابلهما على الترتيب\n• مثل: يأمر بالعدل وينهى عن الظلم\n▸ الجناس\n• اتفاق اللفظين في النطق واختلافهما في المعنى\n• تام: اتفقا في الحروف والعدد والهيئة والترتيب\n• ناقص: اختلف في واحد منها\n▸ السجع\n• توافق الفاصلتين في الحرف الأخير\n• يحسن إذا جاء عفوا\n▸ أغراضها\n• تقوية المعنى\n• إحداث الموسيقى\n• لفت الانتباه\n▸ شرح موسّع\n• تضيف المحسنات البديعية جمالا إلى الأسلوب، وهي معنوية كالطباق والمقابلة، ولفظية كالجناس والسجع. ففي قوله تعالى: ﴿وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ﴾ جناس تام بين الساعة (القيامة) وساعة (الوقت)، لاتفاقهما لفظا واختلافهما معنى. وفي قولهم: «اللهم أعط منفقا خلفا وأعط ممسكا تلفا» سجع بين خلفا وتلفا، وطباق بين منفق وممسك. وحين نحلل النص لا نكتفي بتسمية المحسن بل نبين أثره في المعنى.\n▸ أمثلة وتطبيقات\n• «الصدق ينجي والكذب يهلك»: طباق بين الصدق والكذب وينجي ويهلك، ومقابلة. «قد تبكي العين فرحا وحزنا»: طباق.\n▸ للحفظ\n• طباق = ضدان، مقابلة = تقابل معنيين، جناس = اتفاق لفظ واختلاف معنى، سجع = توافق الفواصل."},{"title":"29. علم المعاني: الخبر والإنشاء","content":"▸ الخبر\n• كلام يحتمل الصدق والكذب\n• ضروبه: ابتدائي، طلبي، إنكاري\n• أغراضه: فائدة الخبر، لازمه، الفخر، المدح\n▸ الإنشاء الطلبي\n• الأمر\n• النهي\n• الاستفهام\n• التمني\n• النداء\n▸ الإنشاء غير الطلبي\n• التعجب\n• القسم\n• المدح والذم\n• الرجاء\n• صيغ العقود\n▸ أغراض بلاغية\n• الأمر: النصح، الدعاء، الالتماس\n• النهي: التحذير\n• الاستفهام: الإنكار، التعجب، التقرير\n• النداء: التحسر، الاستغاثة\n▸ أهم المصطلحات\n• الخبر\n• الإنشاء\n• الغرض البلاغي\n• الطلب\n▸ شرح موسّع\n• يقسم علم المعاني الكلام إلى خبر وإنشاء. فالخبر يمكن الحكم عليه بالصدق أو الكذب، ويؤكد بحسب حال المخاطب: خالي الذهن لا يحتاج إلى توكيد، والمتردد يؤكد له بمؤكد واحد، والمنكر يؤكد له بأكثر من مؤكد. أما الإنشاء فلا يحتمل الصدق والكذب، وقد يكون طلبيا يستدعي مطلوبا غير حاصل وقت الطلب. وكثيرا ما تخرج الأساليب الإنشائية عن معناها الحقيقي إلى أغراض بلاغية: فالأمر في «ربنا اغفر لنا» دعاء، والاستفهام في «أتخافون ربكم؟» إنكار.\n▸ أمثلة وتطبيقات\n• «أتنتهون في دروسك؟»: استفهام خرج إلى معنى اللوم. «اجتهد»: أمر حقيقي. «ليت الشباب يعود»: تمن.\n▸ للحفظ\n• الخبر يحتمل الصدق والكذب، والإنشاء لا يحتملهما، وللأساليب أغراض بلاغية."},{"title":"30. العروض: التفعيلات والزحافات","content":"▸ تعريف العروض\n• علم يعرف به أوزان الشعر العربي وما يعتريها من تغيير.\n• وضعه الخليل بن أحمد الفراهيدي.\n▸ التفعيلات الأصلية\n• فعولن، مفاعيلن\n• فاعلن، فاعلاتن\n• مستفعلن، متفاعلن\n• مفاعلتن، مفعولات\n▸ الزحاف\n• تغيير يصيب ثواني الأسباب\n• كالخبن (حذف الثاني الساكن) والقبض (حذف الخامس الساكن)\n• لا يلزم\n▸ العلة\n• تغيير يصيب العروض والضرب\n• كالحذف والقطع\n• تلزم القصيدة غالبا\n▸ خطوات التقطيع\n• كتابة البيت كما ينطق\n• تقسيمه إلى مقاطع ثم تفعيلات\n• تسمية البحر\n▸ شرح موسّع\n• يعتمد التقطيع العروضي على الكتابة العروضية: نكتب ما ينطق ونحذف ما لا ينطق، فننون التنوين ونحذف همزة الوصل وننطق الحروف المشددة حرفين. وتتألف التفعيلة من أسباب وأوتاد: فالسبب خفيف (متحرك فساكن) أو ثقيل (متحركان)، والوتد مجموع (متحركان فساكن) أو مفروق. ثم نقابل المقاطع بالتفعيلات لنعرف البحر. وتعرف القصيدة العمودية بوزنها وقافيتها، أما الشعر الحر فيعتمد على تفعيلة واحدة تتكرر بعدد غير ثابت.\n▸ أمثلة وتطبيقات\n• للتدرب: اكتب البيت كما ينطق، ضع علامة (/ للمتحرك و o للساكن)، ثم قسمه إلى مقاطع تطابق التفعيلات، وطبق ذلك على أبيات كتابك المدرسي.\n▸ للحفظ\n• الخطوات: كتابة عروضية ← مقاطع ← تفعيلات ← اسم البحر."},{"title":"31. أشهر البحور الشعرية","content":"▸ الطويل\n• فعولن مفاعيلن فعولن مفاعلن (مرتين)\n▸ البسيط\n• مستفعلن فاعلن مستفعلن فعلن (مرتين)\n▸ الكامل\n• متفاعلن متفاعلن متفاعلن (مرتين)\n▸ الوافر\n• مفاعلتن مفاعلتن فعولن (مرتين)\n▸ الخفيف\n• فاعلاتن مستفعلن فاعلاتن (مرتين)\n▸ أبحر أخرى\n• الرجز: مستفعلن ×6\n• الرمل: فاعلاتن ×6\n• المتقارب: فعولن ×8\n• السريع، المنسرح، الهزج\n▸ شرح موسّع\n• تختلف البحور في عدد تفعيلاتها وترتيبها، ولكل بحر موسيقاه: فالطويل هادئ يتسع للفخر والوصف والحكمة، والبسيط ممتد فخم، والكامل غني بالحركات يناسب الحماسة، والوافر سريع قليل الحشو، والخفيف رشيق. أما الشعر الحر فيقوم على تفعيلة واحدة كالرجز والكامل والمتقارب وتتغير فيه عدد التفعيلات من سطر لآخر. ويدرس الطلاب تقطيع أبيات عمودية ثم تحديد البحر والتفعيلات.\n▸ أمثلة وتطبيقات\n• مثال من الشعر الحر: القصائد المكتوبة على المتقارب (فعولن) أو الرمل (فاعلاتن) في دواوين الحداثة الشعرية.\n▸ للحفظ\n• اربط كل بحر بتفعيلته: طويل = فعولن مفاعيلن، بسيط = مستفعلن فاعلن، كامل = متفاعلن، وافر = مفاعلتن."},{"title":"32. منهجية تحليل النص والتقويم النقدي","content":"▸ فهم النص\n• قراءة النص واستخراج الفكرة العامة\n• تحديد الأفكار الأساسية والفرعية\n• شرح المفردات الغامضة\n▸ الاتساق والانسجام\n• أدوات الاتساق: العطف، الإحالة، الضمائر\n• الحقول الدلالية\n• تسلسل الأفكار\n▸ الدراسة الفنية\n• الصور البيانية وأثرها\n• المحسنات البديعية\n• الأساليب الخبرية والإنشائية\n▸ التقويم النقدي\n• تحديد قيمة النص الفكرية\n• تحديد قيمته الفنية\n• إبداء رأي معلل مع الاستشهاد\n▸ أهم المصطلحات\n• الفكرة العامة\n• الحقل الدلالي\n• الاتساق\n• التقويم\n▸ شرح موسّع\n• يطلب في البكالوريا غالبا فهم النص وإبراز بنيته، فأبدأ بقراءة النص مرتين وأحدد موضوعه ونمطه، ثم أجيب عن أسئلة الفهم بجمل كاملة مستشهدا بعبارات من النص. وفي الدراسة الفنية أذكر الظاهرة ثم أمثل لها ثم أبين أثرها. وفي التقويم أحكم على النص من حيث المضمون (صدق الفكرة وأهميتها) والشكل (قوة الأسلوب وجمال التصوير) مع تعليل الحكم. ومن المهم ربط النص بصاحبه واتجاهه الأدبي، كأن أذكر أنه رومانسي أو إصلاحي.\n▸ أمثلة وتطبيقات\n• مثال إجابة: «النمط السائد حجاجي: يظهر ذلك في وجود الأطروحة والحجج والروابط المنطقية مثل لأن وإذن».\n▸ للحفظ\n• الإجابة الجيدة: ظاهرة + مثال من النص + أثر."},{"title":"33. منهجية الإنتاج الكتابي والإعراب","content":"▸ الإنتاج الكتابي\n• مقدمة: تمهيد وطرح الموضوع\n• عرض: أفكار مرتبة مع أمثلة\n• خاتمة: نتيجة وموقف\n▸ شروط الكتابة\n• احترام النمط المطلوب\n• سلامة اللغة\n• وضوح الأفكار وتسلسلها\n• استعمال الروابط\n▸ إعراب الجمل\n• حدد الكلمة ثم موقعها\n• اذكر العلامة والسبب\n• أعرب الجملة ومحلها\n▸ الأخطاء الشائعة\n• الخلط بين الحال والتمييز\n• نسيان علامة الإعراب الفرعية\n• إهمال محل الجملة\n▸ نصائح\n• خصص زمنا لكل سؤال\n• اعتن بالخط\n• راجع الإجابة\n▸ شرح موسّع\n• يطلب من الطالب في الإنتاج الكتابي تحرير نص قصير يحترم نمطا معينا كالحجاجي أو التفسيري أو الوصفي، فيبدأ بمقدمة تثير الموضوع، ثم يعرض أفكاره مدعمة بالأمثلة، ثم يختم بنتيجة. ويراعي سلامة العبارة والترقيم. أما الإعراب فيتطلب حفظ علامات الإعراب وتدريبا يوميا: فأحدد نوع الكلمة (اسم، فعل، حرف)، ثم موقعها من الجملة، ثم علامة إعرابها وسببها. وفي الجمل التي لها محل أذكر نوعها (خبر، صفة، حال...).\n▸ أمثلة وتطبيقات\n• مثال إعراب: «جاء الطلابُ مسرعين»: جاء فعل ماض، الطلاب فاعل مرفوع، مسرعين حال منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم.\n▸ للحفظ\n• الكتابة: مقدمة، عرض، خاتمة. الإعراب: الكلمة + الموقع + العلامة + السبب."}],maps:'arabS'};
  A.philo=Object.assign({},A.philo||{},pLit);
  var pMath={name:'الرياضيات',lessons:[{"title":"1. مفهوم المتتالية العددية","content":"▸ التعريف\n• المتتالية ⁦(uₙ)⁩ دالة تقرن بكل عدد طبيعي ⁦n⁩ عددا حقيقيا ⁦uₙ⁩\n• ⁦uₙ⁩ هو الحد العام و ⁦u₀⁩ الحد الأول\n• نقول: المتتالية معرفة على ⁦ℕ⁩ أو من رتبة معينة\n▸ الصيغة الصريحة\n• ⁦uₙ = f(n)⁩\n• نحسب أي حد مباشرة بالتعويض\n• مثال: ⁦uₙ = 2n + 3⁩ فـ ⁦u₅ = 13⁩\n▸ الصيغة التراجعية\n• نعطي الحد الأول وعلاقة تربط ⁦uₙ₊₁⁩ بـ ⁦uₙ⁩\n• لحساب ⁦u₅⁩ نحسب ⁦u₁⁩ ثم ⁦u₂⁩ ... حتى ⁦u₅⁩\n• مثال: ⁦u₀ = 1⁩ و ⁦uₙ₊₁ = 2uₙ + 1⁩\n▸ فرق مهم في الكتابة\n• ⁦uₙ₊₁⁩ هو الحد التالي (نعوض n بـ n+1)\n• ⁦uₙ + 1⁩ هو الحد نفسه مضافا إليه 1\n• ⁦u₂ₙ⁩ ليس ⁦2uₙ⁩\n▸ أخطاء شائعة\n• الخلط بين ⁦uₙ₊₁⁩ و ⁦uₙ + 1⁩\n• نسيان أن الترقيم يبدأ من 0 (أو 1)\n• التعويض في الصيغة الصريحة بدل التراجعية\n▸ شرح مبسط\n• المتتالية ببساطة قائمة أعداد مرتبة: الحد الأول ثم الثاني ثم الثالث وهكذا. كل عدد له رقم (رتبة) n. الصيغة الصريحة تشبه الدالة: تعطيها رقم الحد فتعطيك قيمته فورا. أما الصيغة التراجعية فتشبه قاعدة لعبة: كل حد يُحسب من الحد الذي قبله، فلا بد من المرور بالحدود واحدا بعد الآخر.\n▸ الطرق والنصائح\n• لحساب حد في صيغة صريحة: عوّض قيمة n.\n• لحساب حد في صيغة تراجعية: احسب الحدود بالترتيب.\n• اقرأ دائما من أي رتبة تبدأ المتتالية.\n▸ تمارين محلولة\n• تمرين 1: المتتالية ⁦uₙ = n² - 3n + 1⁩. احسب ⁦u₀, u₁, u₂, u₃⁩.\n• الحل:\n   – ⁦u₀ = 1⁩، ⁦u₁ = 1 - 3 + 1 = -1⁩، ⁦u₂ = 4 - 6 + 1 = -1⁩، ⁦u₃ = 9 - 9 + 1 = 1⁩\n• تمرين 2: ⁦u₀ = 2⁩ و ⁦uₙ₊₁ = 3uₙ - 1⁩. احسب ⁦u₁, u₂, u₃⁩.\n• الحل:\n   – ⁦u₁ = 3×2 - 1 = 5⁩، ⁦u₂ = 3×5 - 1 = 14⁩، ⁦u₃ = 3×14 - 1 = 41⁩\n• تمرين 3: هل العدد 23 حد من حدود ⁦uₙ = 4n + 3⁩؟\n• الحل:\n   – نحل ⁦4n + 3 = 23⁩ فـ ⁦n = 5⁩ عدد طبيعي، إذن نعم: ⁦u₅ = 23⁩\n   – أما 24 فـ ⁦4n = 21⁩ وهذا مستحيل في ℕ\n▸ للحفظ\n• المتتالية = قائمة مرتبة. صريحة⁦: uₙ = f(n)⁩. تراجعية⁦: uₙ₊₁⁩ بدلالة ⁦uₙ⁩."},{"title":"2. اتجاه تغير متتالية","content":"▸ التعريف\n• متزايدة: ⁦uₙ₊₁ ≥ uₙ⁩ لكل n\n• متناقصة: ⁦uₙ₊₁ ≤ uₙ⁩ لكل n\n• ثابتة: ⁦uₙ₊₁ = uₙ⁩ لكل n\n• رتيبة: متزايدة أو متناقصة (واحدة منهما فقط)\n▸ الطريقة 1: الفرق\n• احسب ⁦uₙ₊₁ - uₙ⁩ وادرس إشارته\n• موجب ⇒ متزايدة\n• سالب ⇒ متناقصة\n• يتغير الإشارة ⇒ ليست رتيبة\n▸ الطريقة 2: النسبة\n• إذا كانت كل الحدود موجبة تماما:\n• ⁦uₙ₊₁/uₙ > 1⁩ ⇒ متزايدة\n• ⁦uₙ₊₁/uₙ < 1⁩ ⇒ متناقصة\n▸ الطريقة 3: الدالة\n• إذا كان ⁦uₙ = f(n)⁩ و f رتيبة على ⁦[0 ; +∞[⁩\n• فالمتتالية لها نفس اتجاه تغير f\n▸ أخطاء شائعة\n• الاكتفاء بحساب 3 حدود لاستنتاج الاتجاه\n• نسيان أن الإشارة قد تتغير من رتبة معينة\n• قسمة على حد قد يكون سالبا أو معدوما\n▸ شرح مبسط\n• نسأل: هل الأعداد تكبر أم تصغر كلما تقدمنا؟ الأسهل غالبا أن نحسب الفرق بين حد وسابقه: إن كان دائما موجبا فالأعداد تكبر. وإذا كانت الإشارة تتغير من رتبة معينة نقول: المتتالية متزايدة ابتداء من هذه الرتبة، وليست رتيبة على كل ℕ.\n▸ الطرق والنصائح\n• اكتب ⁦uₙ₊₁⁩ بدلالة n ثم احسب الفرق وبسّطه.\n• حلل الفرق إلى جداء عوامل لتعرف إشارته.\n• اذكر النتيجة بدقة: متزايدة تماما، أو ابتداء من رتبة معينة.\n▸ تمارين محلولة\n• تمرين 1: ادرس اتجاه تغير ⁦uₙ = n² - 4n + 3⁩.\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = (n+1)² - 4(n+1) + 3 - n² + 4n - 3 = 2n - 3⁩\n   – من أجل ⁦n = 0⁩ و ⁦n = 1⁩ الفرق سالب (u_0=3، u_1=0، u_2=-1)\n   – ومن أجل ⁦n ≥ 2⁩ الفرق موجب\n   – إذن المتتالية ليست رتيبة على ℕ، لكنها متزايدة تماما ابتداء من ⁦u₂⁩\n• تمرين 2: ادرس اتجاه تغير ⁦uₙ = 5/(n+1)⁩.\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = 5/(n+2) - 5/(n+1) = -5/((n+1)(n+2)) < 0⁩\n   – إذن المتتالية متناقصة تماما\n• تمرين 3: ⁦uₙ = 2×3ⁿ⁩. ادرس اتجاه تغيرها.\n• الحل:\n   – الحدود موجبة و ⁦uₙ₊₁/uₙ = 3 > 1⁩\n   – إذن المتتالية متزايدة تماما\n▸ للحفظ\n• ادرس إشارة ⁦uₙ₊₁ − uₙ⁩. موجبة = متزايدة، سالبة = متناقصة."},{"title":"3. المتتالية الحسابية","content":"▸ التعريف\n• ⁦uₙ₊₁ = uₙ + r⁩ لكل n\n• العدد ⁦r⁩ هو الأساس\n• لإثبات أنها حسابية: بيّن أن ⁦uₙ₊₁ - uₙ⁩ ثابت\n▸ الحد العام\n• ⁦uₙ = u₀ + n·r⁩\n• وبصفة عامة ⁦uₙ = uₚ + (n - p)·r⁩\n• مثال: ⁦u₃ = 7⁩ و ⁦r = 2⁩ ⇒ ⁦u₈ = 7 + 5×2 = 17⁩\n▸ المجموع\n• المجموع = عدد الحدود × (الأول + الأخير) ÷ 2\n• عدد الحدود من ⁦p⁩ إلى ⁦n⁩ هو ⁦n - p + 1⁩\n• ⁦1 + 2 + ... + n = n(n+1)/2⁩\n▸ اتجاه التغير\n• ⁦r > 0⁩ ⇒ متزايدة\n• ⁦r < 0⁩ ⇒ متناقصة\n• ⁦r = 0⁩ ⇒ ثابتة\n▸ خاصية الوسط\n• إذا كانت ⁦a, b, c⁩ حدودا متتالية حسابية فـ ⁦2b = a + c⁩\n• تفيد في إيجاد 3 أعداد متتالية في تتابع حسابي\n▸ شرح مبسط\n• المتتالية الحسابية هي التي نضيف في كل مرة العدد نفسه r للانتقال من حد إلى التالي. مثل مدخرات تزيد 200 دج كل شهر. للمجموع نستعمل حيلة غاوس: نجمع الأول مع الأخير ونضرب في عدد الحدود ونقسم على 2.\n▸ الطرق والنصائح\n• لإيجاد r من حدين: ⁦r = (uₙ - uₚ)/(n - p)⁩.\n• لا تخطئ في عدد الحدود: من ⁦u₀⁩ إلى ⁦u₁0⁩ يوجد 11 حدا.\n• للمجموع: احسب الحد الأخير أولا.\n▸ تمارين محلولة\n• تمرين 1: حسابية فيها ⁦u₃ = 7⁩ و ⁦u₈ = 22⁩. احسب r و ⁦u₀⁩ ثم ⁦uₙ⁩ ثم ⁦S = u₀ + ... + u₁0⁩.\n• الحل:\n   – ⁦u₈ = u₃ + 5r⁩ فـ ⁦22 = 7 + 5r⁩ و ⁦r = 3⁩\n   – ⁦u₀ = u₃ - 3r = 7 - 9 = -2⁩\n   – ⁦uₙ = -2 + 3n⁩\n   – ⁦u₁0 = 28⁩ وعدد الحدود 11، فـ ⁦S = 11×(-2 + 28)/2 = 143⁩\n• تمرين 2: بيّن أن ⁦vₙ = 3n + 5⁩ حسابية واحسب مجموع الحدود العشرين الأولى.\n• الحل:\n   – ⁦vₙ₊₁ - vₙ = 3(n+1) + 5 - 3n - 5 = 3⁩ ثابت، إذن حسابية أساسها 3\n   – ⁦v₀ = 5⁩ و ⁦v₁9 = 62⁩ فـ ⁦S = 20×(5 + 62)/2 = 670⁩\n• تمرين 3: ثلاثة أعداد حدود متتالية لمتتالية حسابية، مجموعها 21 وجداؤها 315. أوجدها.\n• الحل:\n   – نضع الأعداد ⁦a - r, a, a + r⁩\n   – المجموع ⁦3a = 21⁩ فـ ⁦a = 7⁩\n   – الجداء ⁦7(49 - r²) = 315⁩ فـ ⁦49 - r² = 45⁩ و ⁦r = ±2⁩\n   – الأعداد: 5 ، 7 ، 9\n▸ للحفظ\n• حسابية⁦: uₙ = uₚ + (n−p)r⁩. المجموع = عدد الحدود × (الأول+الأخير⁦) / 2⁩."},{"title":"4. المتتالية الهندسية","content":"▸ التعريف\n• ⁦uₙ₊₁ = q·uₙ⁩ لكل n\n• العدد ⁦q⁩ هو الأساس\n• لإثبات أنها هندسية: بيّن أن ⁦uₙ₊₁/uₙ⁩ ثابت\n▸ الحد العام\n• ⁦uₙ = u₀·qⁿ⁩\n• وبصفة عامة ⁦uₙ = uₚ·qⁿ⁻ᵖ⁩\n• مثال: ⁦u₀ = 3⁩ و ⁦q = 2⁩ ⇒ ⁦u₄ = 48⁩\n▸ المجموع\n• ⁦S = uₚ × (1 - qᵏ) / (1 - q)⁩ بشرط ⁦q ≠ 1⁩ حيث ⁦k⁩ عدد الحدود و ⁦uₚ⁩ أول حد في المجموع\n• إذا ⁦q = 1⁩ فالمجموع = عدد الحدود × الحد الأول\n• ⁦1 + q + ... + qⁿ = (1 - qⁿ⁺¹)/(1 - q)⁩\n▸ اتجاه التغير (u_0 > 0)\n• ⁦q > 1⁩ ⇒ متزايدة\n• ⁦0 < q < 1⁩ ⇒ متناقصة\n• ⁦q < 0⁩ ⇒ ليست رتيبة (الإشارة تتناوب)\n• إذا ⁦u₀ < 0⁩ ينعكس الاتجاه\n▸ تطبيقات\n• زيادة بنسبة t% ⇒ نضرب في ⁦1 + t/100⁩\n• نقصان بنسبة t% ⇒ نضرب في ⁦1 - t/100⁩\n▸ شرح مبسط\n• المتتالية الهندسية هي التي نضرب في كل مرة في العدد نفسه q. مثل سكان مدينة يزيدون 3% كل سنة: نضرب في 1.03 كل سنة. التزايد هنا أسرع من الحسابي لأنه يتراكم.\n▸ الطرق والنصائح\n• لإيجاد q من حدين: ⁦qⁿ⁻ᵖ = uₙ/uₚ⁩.\n• إذا كانت الحدود موجبة نختار ⁦q > 0⁩.\n• انتبه لعدد الحدود في المجموع.\n▸ تمارين محلولة\n• تمرين 1: هندسية حدودها موجبة فيها ⁦v₂ = 12⁩ و ⁦v₄ = 48⁩. احسب q و ⁦v₀⁩ ثم ⁦vₙ⁩ و ⁦S = v₀ + ... + v₆⁩.\n• الحل:\n   – ⁦v₄ = v₂·q²⁩ فـ ⁦q² = 4⁩ و ⁦q = 2⁩ (الحدود موجبة)\n   – ⁦v₀ = 12/4 = 3⁩\n   – ⁦vₙ = 3·2ⁿ⁩\n   – عدد الحدود 7: ⁦S = 3×(1 - 2⁷)/(1 - 2) = 3×127 = 381⁩\n• تمرين 2: ⁦u₀ = 2⁩ و ⁦q = 3⁩. أوجد أصغر ⁦n⁩ يحقق ⁦uₙ > 1000⁩.\n• الحل:\n   – ⁦2×3ⁿ > 1000⁩ أي ⁦3ⁿ > 500⁩\n   – ⁦3⁵ = 243⁩ و ⁦3⁶ = 729⁩\n   – إذن ⁦n = 6⁩ (لأن ⁦u₆ = 1458⁩ و ⁦u₅ = 486⁩)\n• تمرين 3: سعر سيارة 1 800 000 دج ينقص 10% كل سنة. ما سعرها بعد 3 سنوات؟\n• الحل:\n   – السعر متتالية هندسية أساسها 0.9\n   – بعد 3 سنوات: ⁦1800000 × 0.9³ = 1800000 × 0.729 = 1 312 200⁩ دج\n▸ للحفظ\n• هندسية: ⁦uₙ = uₚ·qⁿ⁻ᵖ⁩. المجموع: ⁦S = uₚ·(1 - qᵏ)/(1 - q)⁩ حيث k عدد الحدود."},{"title":"5. المتتالية ⁦uₙ₊₁ = a·uₙ + b⁩","content":"▸ الشكل\n• ⁦uₙ₊₁ = a·uₙ + b⁩ مع ⁦a ≠ 1⁩ و ⁦b ≠ 0⁩\n• إذا ⁦a = 1⁩ فهي حسابية\n• إذا ⁦b = 0⁩ فهي هندسية\n▸ الخطوة 1: العدد α\n• نحل ⁦α = a·α + b⁩\n• فنجد ⁦α = b/(1 - a)⁩\n• هو العدد الثابت الذي لا يتغير بالعلاقة\n▸ الخطوة 2: متتالية مساعدة\n• نضع ⁦vₙ = uₙ - α⁩\n• نبرهن أنها هندسية أساسها a\n• ⁦vₙ₊₁ = a·vₙ⁩\n▸ الخطوة 3: الحد العام\n• ⁦vₙ = v₀·aⁿ⁩ مع ⁦v₀ = u₀ - α⁩\n• ثم ⁦uₙ = α + (u₀ - α)·aⁿ⁩\n• المجموع: نجمع الثابت α ونجمع الهندسية\n▸ أخطاء شائعة\n• نسيان إثبات أن ⁦vₙ₊₁ = a·vₙ⁩\n• الخطأ في إشارة α\n• استعمال ⁦u₀ - α⁩ بدل ⁦u₀ + α⁩\n▸ شرح مبسط\n• الفكرة ذكية: بدل أن نتعامل مع علاقة فيها ضرب وجمع، نزيح المتتالية بالعدد α فتصبح علاقة ضرب فقط، أي هندسية نعرف حلها. ثم نعود إلى المتتالية الأصلية بإضافة α.\n▸ الطرق والنصائح\n• احسب α من المعادلة ⁦α = aα + b⁩.\n• عرّف ⁦vₙ = uₙ - α⁩ ثم أثبت ⁦vₙ₊₁ = a·vₙ⁩.\n• اكتب ⁦vₙ⁩ ثم ⁦uₙ = vₙ + α⁩.\n• تحقق بحساب ⁦u₁⁩ بالطريقتين.\n▸ تمارين محلولة\n• تمرين 1: ⁦u₀ = 1⁩ و ⁦uₙ₊₁ = (1/2)uₙ + 3⁩. أوجد ⁦uₙ⁩ بدلالة n.\n• الحل:\n   – ⁦α = α/2 + 3⁩ فـ ⁦α = 6⁩\n   – ⁦vₙ = uₙ - 6⁩: ⁦vₙ₊₁ = uₙ₊₁ - 6 = (1/2)uₙ - 3 = (1/2)(uₙ - 6) = (1/2)vₙ⁩\n   – هندسية أساسها 1/2 وحدها الأول ⁦v₀ = -5⁩\n   – إذن ⁦vₙ = -5(1/2)ⁿ⁩ و ⁦uₙ = 6 - 5(1/2)ⁿ⁩\n   – تحقق: ⁦u₁ = 6 - 2.5 = 3.5⁩ و ⁦0.5 + 3 = 3.5⁩\n• تمرين 2: ⁦u₀ = 5⁩ و ⁦uₙ₊₁ = 2uₙ - 3⁩. أوجد ⁦uₙ⁩ ثم احسب ⁦u₀ + u₁ + u₂ + u₃⁩.\n• الحل:\n   – ⁦α = 2α - 3⁩ فـ ⁦α = 3⁩\n   – ⁦vₙ = uₙ - 3⁩ هندسية أساسها 2 و ⁦v₀ = 2⁩ فـ ⁦vₙ = 2ⁿ⁺¹⁩\n   – إذن ⁦uₙ = 3 + 2ⁿ⁺¹⁩\n   – الحدود: 5 ، 7 ، 11 ، 19 والمجموع 42\n• تمرين 3: مبلغ 10 000 دج يزيد 5% سنويا مع إضافة 1000 دج كل سنة: ⁦uₙ₊₁ = 1.05uₙ + 1000⁩. أوجد ⁦uₙ⁩.\n• الحل:\n   – ⁦α = 1.05α + 1000⁩ فـ ⁦α = -20000⁩\n   – ⁦vₙ = uₙ + 20000⁩ هندسية أساسها 1.05 و ⁦v₀ = 30000⁩\n   – إذن ⁦uₙ = 30000×1.05ⁿ - 20000⁩\n   – تحقق: ⁦u₁ = 31500 - 20000 = 11500⁩\n▸ للحفظ\n• ⁦α = b/(1−a). vₙ = uₙ − α⁩ هندسية أساسها ⁦a. uₙ = α + (u₀−α)aⁿ⁩."},{"title":"6. الاستدلال بالتراجع","content":"▸ الفكرة\n• لإثبات خاصية ⁦P(n)⁩ من أجل كل ⁦n ≥ n₀⁩\n• كأننا نسقط أحجار الدومينو: الحجر الأول ثم كل حجر يُسقط التالي\n▸ المرحلة 1: التحقق\n• نبين أن ⁦P(n₀)⁩ صحيحة\n• نعوض ⁦n = n₀⁩ في الخاصية\n▸ المرحلة 2: الوراثة\n• نفرض ⁦P(n)⁩ صحيحة من أجل عدد n ما\n• نبرهن أن ⁦P(n+1)⁩ صحيحة\n• هذا الفرض يسمى فرض التراجع\n▸ المرحلة 3: الاستنتاج\n• ⁦P(n)⁩ صحيحة من أجل كل ⁦n ≥ n₀⁩\n▸ أخطاء شائعة\n• تجاهل التحقق الأول\n• استعمال الخاصية المطلوب إثباتها دون فرض\n• نسيان كتابة جملة الاستنتاج\n▸ شرح مبسط\n• نحن لا نستطيع اختبار كل الأعداد. لذلك نختبر الأول، ثم نثبت أنه كلما صحت الخاصية عند عدد صحّت عند التالي. إذن تصح عند الأول فتصح عند الثاني فالثالث وهكذا إلى ما لا نهاية.\n▸ الطرق والنصائح\n• اكتب الخاصية ⁦P(n)⁩ بوضوح.\n• اكتب ⁦P(n+1)⁩ بالتعويض n بـ n+1.\n• في الوراثة ابدأ من طرف ⁦P(n+1)⁩ واستعمل فرض التراجع.\n• اختم بجملة الاستنتاج.\n▸ تمارين محلولة\n• تمرين 1: برهن أن ⁦1 + 3 + 5 + ... + (2n - 1) = n²⁩ لكل ⁦n ≥ 1⁩.\n• الحل:\n   – التحقق: ⁦n = 1⁩: الطرفان يساويان 1\n   – الوراثة: نفرض `1 + 3 + .\n   – + (2n-1) = n^2⁦، فنجد ⁩1 + 3 + .\n   – + (2n-1) + (2n+1) = n^2 + 2n + 1 = (n+1)^2`\n   – إذن P(n+1) صحيحة\n   – الاستنتاج: الخاصية صحيحة لكل ⁦n ≥ 1⁩\n• تمرين 2: برهن أن ⁦4ⁿ - 1⁩ يقبل القسمة على 3 لكل n.\n• الحل:\n   – التحقق: ⁦n = 0⁩ فـ ⁦4⁰ - 1 = 0⁩ مضاعف للعدد 3\n   – الوراثة: إذا ⁦4ⁿ - 1 = 3k⁩ فـ ⁦4ⁿ⁺¹ - 1 = 4(4ⁿ - 1) + 3 = 12k + 3 = 3(4k + 1)⁩\n   – إذن مضاعف للعدد 3\n• تمرين 3: ⁦u₀ = 2⁩ و ⁦uₙ₊₁ = 3uₙ - 2⁩. برهن أن ⁦uₙ = 3ⁿ + 1⁩.\n• الحل:\n   – التحقق: ⁦n = 0⁩ فـ ⁦3⁰ + 1 = 2 = u₀⁩\n   – الوراثة: إذا ⁦uₙ = 3ⁿ + 1⁩ فـ ⁦uₙ₊₁ = 3(3ⁿ + 1) - 2 = 3ⁿ⁺¹ + 1⁩\n   – وهذا هو المطلوب\n▸ للحفظ\n• تحقق + وراثة + استنتاج. لا تنس فرض التراجع وجملة الاستنتاج."},{"title":"7. مسائل على المتتاليات","content":"▸ خطوات الحل\n• 1) حدد المتتالية: ما هو ⁦u₀⁩ وما هو n؟\n• 2) هل الزيادة ثابتة (حسابية) أم نسبة (هندسية)؟\n• 3) اكتب العلاقة التراجعية\n• 4) استعمل صيغة الحد العام والمجموع\n• 5) أجب بجملة تناسب السياق\n▸ ادخار بمبلغ ثابت\n• كل شهر نضيف مبلغا ثابتا ⇒ حسابية\n• الحد الأول هو المبلغ الأول والأساس هو الزيادة\n▸ نسبة مئوية\n• زيادة t% كل سنة ⇒ هندسية أساسها ⁦1 + t/100⁩\n• نقصان t% ⇒ أساسها ⁦1 - t/100⁩\n▸ علاقة من الشكل a·u+b\n• زيادة نسبة مع إضافة ثابتة ⇒ ⁦uₙ₊₁ = a·uₙ + b⁩\n• نستعمل المتتالية المساعدة ⁦vₙ = uₙ - α⁩\n▸ تنبيه\n• اربط n بالزمن بدقة: بعد 5 سنوات هي ⁦u₅⁩ إذا بدأنا بـ ⁦u₀⁩\n• قرّب النتيجة في آخر مرحلة فقط\n▸ شرح مبسط\n• المسائل الواقعية تختبر ثلاثة أشياء: فهم النص، والتعرف على النوع (حسابية أم هندسية)، وحسن استعمال الصيغة. اقرأ النص وحدد: هل يتغير المقدار بجمع عدد ثابت أم بضرب في عدد ثابت.\n▸ الطرق والنصائح\n• زيادة بمبلغ ثابت ⇒ حسابية.\n• زيادة بنسبة مئوية ⇒ هندسية.\n• نسبة مع إضافة ⇒ المتتالية المساعدة.\n▸ تمارين محلولة\n• تمرين 1: يدخر شخص 1000 دج في الشهر الأول ويزيد 200 دج كل شهر. 1) ما المبلغ المدخر في الشهر 12؟ 2) ما مجموع ما ادخره خلال 12 شهرا؟\n• الحل:\n   – حسابية حدها الأول 1000 وأساسها 200\n   – 1) الحد 12: ⁦1000 + 11×200 = 3200⁩ دج\n   – 2) المجموع: ⁦12×(1000 + 3200)/2 = 25200⁩ دج\n• تمرين 2: عدد سكان مدينة 50 000 نسمة ويتزايد بنسبة 3% كل سنة. احسب عددهم بعد 5 سنوات.\n• الحل:\n   – هندسية أساسها 1.03 وحدها الأول 50000\n   – بعد 5 سنوات: ⁦50000×1.03⁵ ≈ 50000×1.1593 ≈ 57964⁩ نسمة تقريبا\n• تمرين 3: وضعنا 100 000 دج في بنك بفائدة مركبة 5% سنويا. ما المبلغ بعد 3 سنوات؟\n• الحل:\n   – هندسية أساسها 1.05: ⁦100000×1.05³ = 100000×1.157625 = 115 762.5⁩ دج\n▸ للحفظ\n• مبلغ ثابت = حسابية. نسبة مئوية = هندسية (نضرب في ⁦1 ± t/100)⁩."},{"title":"8. النهايات والمستقيمات المقاربة","content":"▸ كثير حدود عند ∞\n• النهاية هي نهاية الحد ذي أكبر درجة\n• ⁦lim (x³ - 3x² + 2) = +∞⁩ عند ⁦+∞⁩ و ⁦-∞⁩ عند ⁦-∞⁩\n• ⁦lim (-2x² + 4x + 1) = -∞⁩ عند ⁦±∞⁩\n▸ دالة ناطقة عند ∞\n• نهاية حاصل قسمة الحدين ذوي أكبر درجة في البسط والمقام\n• ⁦lim (2x+1)/(x-1) = 2⁩ عند ⁦±∞⁩\n▸ عند عدد a يعدم المقام\n• نبسّط إن أمكن، وإلا ندرس إشارة المقام يمينا ويسارا\n• النتيجة ⁦+∞⁩ أو ⁦-∞⁩ ⇒ مستقيم مقارب عمودي ⁦x = a⁩\n▸ المستقيمات المقاربة\n• إذا ⁦lim f(x) = L⁩ عند ⁦±∞⁩ ⇒ ⁦y = L⁩ مقارب أفقي\n• إذا ⁦lim f(x) = ±∞⁩ عند ⁦a⁩ ⇒ ⁦x = a⁩ مقارب عمودي\n▸ أخطاء شائعة\n• كتابة ⁦∞ - ∞⁩ كأنها 0 (حالة عدم تعيين: نخرج الحد الأكبر عاملا مشتركا)\n• نسيان إشارة المقام عند الاقتراب من a\n• قسمة بسط على مقام عند ∞ دون اختيار أكبر درجة\n▸ شرح مبسط\n• النهاية تجيب عن سؤال: إلى ماذا تقترب f(x) عندما يصبح x كبيرا جدا (أو يقترب من قيمة معينة). في كثير الحدود يكفي أن ننظر إلى الحد الأقوى لأنه يطغى على الباقي. وفي الدالة الناطقة نأخذ الحد الأقوى في البسط والحد الأقوى في المقام.\n▸ الطرق والنصائح\n• عند ±∞: احتفظ بالحد الأكبر درجة فقط.\n• عند a (المقام يعدم): ادرس إشارة المقام عن اليمين وعن اليسار.\n• اكتب دائما المستقيم المقارب بمعادلته.\n▸ تمارين محلولة\n• تمرين 1: ⁦f(x) = (3x - 1)/(x + 2)⁩. جد مجموعة التعريف والنهايات والمستقيمين المقاربين.\n• الحل:\n   – ⁦D = ℝ \\ {-2}⁩\n   – عند ⁦±∞⁩: ⁦3x/x = 3⁩ فـ ⁦y = 3⁩ مقارب أفقي\n   – عند ⁦-2⁩: البسط ⁦→ -7⁩\n   – على يمين -2 المقام موجب فالنهاية ⁦-∞⁩، وعلى اليسار المقام سالب فالنهاية ⁦+∞⁩\n   – إذن ⁦x = -2⁩ مقارب عمودي\n• تمرين 2: احسب نهاية ⁦f(x) = x³ - 3x + 1⁩ عند ⁦+∞⁩ وعند ⁦-∞⁩.\n• الحل:\n   – الحد الأكبر درجة ⁦x³⁩: النهاية ⁦+∞⁩ عند ⁦+∞⁩ و ⁦-∞⁩ عند ⁦-∞⁩\n• تمرين 3: احسب ⁦lim (x² - 1)/(x² + 1)⁩ عند ⁦+∞⁩.\n• الحل:\n   – حاصل الحدين الأكبرين ⁦x²/x² = 1⁩\n   – النهاية 1 ومنه ⁦y = 1⁩ مقارب أفقي\n▸ للحفظ\n• عند ∞ الحد الأكبر درجة يحكم. المقام يعدم ⇒ ادرس إشارته ⇒ مقارب عمودي."},{"title":"9. الاشتقاق والمماس","content":"▸ مشتقات أساسية\n• ⁦(k)' = 0⁩ و ⁦(x)' = 1⁩\n• ⁦(xⁿ)' = n·xⁿ⁻¹⁩\n• ⁦(1/x)' = -1/x²⁩ و ⁦(√x)' = 1/(2√x)⁩\n▸ العمليات\n• ⁦(u + v)' = u' + v'⁩ و ⁦(k·u)' = k·u'⁩\n• ⁦(u·v)' = u'v + uv'⁩\n• ⁦(u/v)' = (u'v - uv')/v²⁩\n▸ المماس\n• معادلة المماس عند ⁦a⁩:\n• ⁦y = f'(a)(x - a) + f(a)⁩\n• ⁦f'(a)⁩ هو ميل المماس\n▸ اتجاه التغير\n• ⁦f' > 0⁩ على مجال ⇒ f متزايدة عليه\n• ⁦f' < 0⁩ ⇒ f متناقصة\n• تنعدم f' مع تغير الإشارة ⇒ قيمة حدية محلية\n▸ أخطاء شائعة\n• نسيان ⁦f(a)⁩ في معادلة المماس\n• اشتقاق الجداء كجداء المشتقات\n• في المقام: نسيان تربيعه\n▸ شرح مبسط\n• المشتق عند a هو ميل المماس للمنحنى عند النقطة ذات الفاصلة a. إذا كان الميل موجبا فالمنحنى يصعد، وإذا كان سالبا فينزل. لذلك ندرس إشارة المشتق لمعرفة اتجاه تغير الدالة.\n▸ الطرق والنصائح\n• احسب ⁦f(a)⁩ ثم ⁦f'(x)⁩ ثم ⁦f'(a)⁩.\n• عوّض في ⁦y = f'(a)(x - a) + f(a)⁩ وبسّط.\n• لمماس أفقي: حل ⁦f'(x) = 0⁩. لمماس يوازي مستقيما ميله m: حل ⁦f'(x) = m⁩.\n▸ تمارين محلولة\n• تمرين 1: ⁦f(x) = x² - 4x + 1⁩. اكتب معادلة المماس عند ⁦x = 3⁩.\n• الحل:\n   – ⁦f(3) = 9 - 12 + 1 = -2⁩ و ⁦f'(x) = 2x - 4⁩ فـ ⁦f'(3) = 2⁩\n   – ⁦y = 2(x - 3) - 2 = 2x - 8⁩\n• تمرين 2: ⁦f(x) = x³ - 3x⁩. أين يكون المماس أفقيا؟\n• الحل:\n   – ⁦f'(x) = 3x² - 3 = 0⁩ فـ ⁦x = ±1⁩\n   – النقطتان ⁦(1 ; -2)⁩ و ⁦(-1 ; 2)⁩\n• تمرين 3: ⁦f(x) = x² - 4x + 1⁩. أوجد نقطة يوازي عندها المماس المستقيم ⁦y = 2x⁩.\n• الحل:\n   – ⁦f'(x) = 2⁩ فـ ⁦2x - 4 = 2⁩ و ⁦x = 3⁩\n   – النقطة ⁦(3 ; -2)⁩\n• تمرين 4: احسب مشتقة ⁦g(x) = (2x + 1)/(x - 1)⁩.\n• الحل:\n   – ⁦g'(x) = (2(x-1) - (2x+1)×1)/(x-1)² = -3/(x-1)²⁩\n▸ للحفظ\n• المماس⁦: y = f′(a)(x−a) + f(a)⁩. إشارة ⁦f′⁩ تحدد اتجاه تغير f."},{"title":"10. دراسة كثير حدود (الدرجة 2 و3) ونقطة الانعطاف","content":"▸ الدرجة 2: ax²+bx+c\n• الرأس: ⁦x = -b/(2a)⁩\n• ⁦a > 0⁩ ⇒ قيمة صغرى، ⁦a < 0⁩ ⇒ قيمة عظمى\n• الجذور: ⁦Δ = b² - 4ac⁩ ثم ⁦x = (-b ± √Δ)/(2a)⁩\n▸ الدرجة 3\n• ⁦f'⁩ كثير حدود من الدرجة 2\n• نحل ⁦f'(x) = 0⁩ وندرس إشارتها\n• نكمل جدول التغيرات وقيم f الحدية\n▸ نقطة الانعطاف\n• ⁦f''(x) = 0⁩ مع تغير إشارتها\n• لكثير حدود من الدرجة 3: ⁦x = -b/(3a)⁩\n• هي مركز تناظر المنحنى\n▸ خطوات الدراسة\n• 1) مجموعة التعريف ⁦ℝ⁩\n• 2) النهايات عند ⁦±∞⁩\n• 3) المشتق وإشارته\n• 4) جدول التغيرات\n• 5) نقاط خاصة والمماسات والرسم\n▸ أخطاء شائعة\n• نسيان نهايات ±∞ في الجدول\n• حساب ⁦f⁩ عند الحدود بدل نقاط التغير\n• رسم المنحنى دون جدول\n▸ شرح مبسط\n• نتعامل مع كثير الحدود كرحلة: ننظر أين تبدأ (نهاية -∞) وأين تنتهي (+∞)، وأين يرتفع المنحنى وأين ينزل (إشارة المشتق). ونقطة الانعطاف هي النقطة التي يتغير عندها شكل الانحناء، وهي وسط المنحنى في الدرجة الثالثة.\n▸ الطرق والنصائح\n• اشتق وحلل ⁦f'⁩ إلى عوامل.\n• أنجز جدول الإشارات ثم التغيرات.\n• احسب الصور بدقة: ⁦f(0)⁩ و ⁦f(2)⁩ ...\n• لإيجاد الجذور جرب أعدادا بسيطة: 1 أو -1 أو 2.\n▸ تمارين محلولة\n• تمرين 1: ⁦f(x) = x³ - 3x² + 2⁩. ادرس تغيراتها وجد نقطة الانعطاف وحل ⁦f(x) = 0⁩.\n• الحل:\n   – ⁦f'(x) = 3x² - 6x = 3x(x - 2)⁩: موجبة قبل 0 وبعد 2، سالبة بينهما\n   – ⁦f(0) = 2⁩ (عظمى محلية) و ⁦f(2) = 8 - 12 + 2 = -2⁩ (صغرى محلية)\n   – الجدول: ⁦x: -∞ , 0 , 2 , +∞⁩ و ⁦f: -∞ ↗ 2 ↘ -2 ↗ +∞⁩\n   – ⁦f''(x) = 6x - 6⁩ تنعدم عند 1 و ⁦f(1) = 0⁩ فالانعطاف ⁦(1 ; 0)⁩\n   – الجذور: ⁦x = 1⁩ جذر، ثم ⁦f(x) = (x - 1)(x² - 2x - 2)⁩ و ⁦Δ = 12⁩ فالجذران ⁦1 ± √3⁩\n   – المجموعة ⁦{1 - √3 ; 1 ; 1 + √3}⁩\n• تمرين 2: ⁦g(x) = -2x² + 4x + 1⁩. ادرس تغيرات g واحسب قيمتها الحدية وحل ⁦g(x) = 0⁩.\n• الحل:\n   – ⁦g'(x) = -4x + 4⁩ تنعدم عند 1: موجبة قبله وسالبة بعده\n   – g متزايدة على ⁦]-∞ ; 1]⁩ ومتناقصة على ⁦[1 ; +∞[⁩ وقيمتها العظمى ⁦g(1) = -2 + 4 + 1 = 3⁩\n   – المعادلة: ⁦Δ = 16 + 8 = 24⁩ فـ ⁦x = (-4 ± 2√6)/(-4) = 1 ∓ √6/2⁩\n• تمرين 3: ⁦f(x) = x³ - 3x⁩. ادرس تغيراتها وحدد نقطة الانعطاف.\n• الحل:\n   – ⁦f'(x) = 3(x² - 1)⁩ تنعدم عند ±1\n   – ⁦f(-1) = 2⁩ عظمى و ⁦f(1) = -2⁩ صغرى\n   – ⁦f''(x) = 6x⁩ فالانعطاف عند ⁦0⁩ وهو ⁦(0 ; 0)⁩\n   – وتتقاطع مع محور الفواصل عند ⁦0 , ±√3⁩\n• تمرين 4: بيّن أن ⁦h(x) = x³ + 3x⁩ متزايدة على ℝ.\n• الحل:\n   – ⁦h'(x) = 3x² + 3 > 0⁩ دائما فـ h متزايدة تماما ولا قيمة حدية لها\n   – الانعطاف عند 0\n▸ للحفظ\n• ⁦f′ = 0 ⇒⁩ قيم حدية⁦. f⁩″ ⁦= 0 ⇒⁩ انعطاف. للدرجة 3: انعطاف عند ⁦x = −b/(3a)⁩."},{"title":"11. الدوال الناطقة (التناظرية)","content":"▸ الدالة المتجانسة\n• ⁦f(x) = (ax + b)/(cx + d)⁩\n• ⁦D = ℝ \\ {-d/c}⁩\n• مقاربان: ⁦x = -d/c⁩ و ⁦y = a/c⁩\n▸ المشتقة\n• ⁦f'(x) = (ad - bc)/(cx + d)²⁩\n• الإشارة ثابتة هي إشارة ⁦ad - bc⁩\n• ⁦ad - bc > 0⁩ ⇒ متزايدة على كل مجال\n• ⁦ad - bc < 0⁩ ⇒ متناقصة على كل مجال\n▸ خطوات الدراسة\n• 1) مجموعة التعريف (المقام ≠ 0)\n• 2) النهايات عند أطراف D ⇒ المقاربان\n• 3) المشتق وإشارته ⇒ جدول التغيرات\n• 4) نقاط خاصة والمماسات ⇒ الرسم\n▸ ملاحظات\n• المنحنى يتكون من فرعين\n• نقطة تقاطع المقاربين هي مركز التناظر\n▸ أخطاء شائعة\n• إدخال القيمة الممنوعة في D\n• خطأ في إشارة ⁦ad - bc⁩\n• الخلط بين المقاربين الأفقي والعمودي\n▸ شرح مبسط\n• الدالة الناطقة كسر بسط ومقام. المشكلة الوحيدة هي القيمة التي تعدم المقام: الدالة غير معرفة عندها والمنحنى يقترب منها دون ملامستها (مقارب عمودي). أما عند ∞ فيقترب المنحنى من الخط الأفقي (مقارب أفقي).\n▸ الطرق والنصائح\n• احسب ⁦ad - bc⁩ مباشرة تعرف اتجاه التغير.\n• احسب 2 أو 3 نقاط (تقاطع المحورين) للرسم.\n• اكتب جدول التغيرات بعمودين (فرعين).\n▸ تمارين محلولة\n• تمرين 1: ⁦h(x) = (2x + 1)/(x - 1)⁩ على ⁦ℝ \\ {1}⁩. استنتج المقاربين وادرس التغيرات واكتب معادلة المماس عند 0.\n• الحل:\n   – عند ⁦±∞⁩ النهاية 2 فـ ⁦y = 2⁩\n   – عند 1: البسط 3؛ يمينا النهاية ⁦+∞⁩ ويسارا ⁦-∞⁩ فـ ⁦x = 1⁩\n   – ⁦h'(x) = -3/(x-1)² < 0⁩ فـ h متناقصة على ⁦]-∞ ; 1[⁩ وعلى ⁦]1 ; +∞[⁩\n   – ⁦h(0) = -1⁩ و ⁦h'(0) = -3⁩: ⁦y = -3x - 1⁩\n• تمرين 2: ⁦f(x) = (x + 3)/(x - 2)⁩. ادرس تغيراتها.\n• الحل:\n   – ⁦ad - bc = 1×(-2) - 3×1 = -5 < 0⁩ فـ f متناقصة على كل مجال\n   – المقاربان ⁦x = 2⁩ و ⁦y = 1⁩\n• تمرين 3: ⁦g(x) = (2x - 3)/(x + 1)⁩. ادرس تغيراتها.\n• الحل:\n   – ⁦ad - bc = 2×1 - (-3)×1 = 5 > 0⁩ فـ g متزايدة على ⁦]-∞ ; -1[⁩ وعلى ⁦]-1 ; +∞[⁩\n   – المقاربان ⁦x = -1⁩ و ⁦y = 2⁩\n• تمرين 4: (إضافي) ⁦f(x) = x + 1/x⁩ على ⁦ℝ*⁩.\n• الحل:\n   – ⁦f'(x) = 1 - 1/x² = (x² - 1)/x²⁩: تنعدم عند ±1\n   – ⁦f(1) = 2⁩ صغرى محلية و ⁦f(-1) = -2⁩ عظمى محلية\n▸ للحفظ\n• ⁦f(x)=(ax+b)/(cx+d)⁩: مقاربان ⁦x=−d/c⁩ و ⁦y=a/c⁩، وإشارة المشتق = إشارة ⁦ad−bc⁩."},{"title":"12. القراءة البيانية","content":"▸ ماذا نقرأ من المنحنى؟\n• مجموعة التعريف: على محور الفواصل\n• القيم الحدية: القمم والقيعان\n• اتجاه التغير: صعود أو نزول\n• الصورة ⁦f(a)⁩: ارتفاع النقطة ذات الفاصلة a\n▸ حل ⁦f(x) = k⁩\n• نرسم المستقيم الأفقي ⁦y = k⁩\n• عدد نقاط التقاطع هو عدد الحلول\n• فواصل التقاطع هي الحلول\n▸ حل ⁦f(x) ≥ k⁩\n• المجالات التي يكون فيها المنحنى فوق المستقيم ⁦y = k⁩ أو عليه\n▸ من الجدول إلى المنحنى\n• كل سهم يعطي قطعة من المنحنى\n• النهايات تعطي سلوك المنحنى عند الأطراف\n• المقاربات تحدد حدود الرسم\n▸ المماس بيانيا\n• ميل المماس = ⁦f'(a)⁩\n• مماس أفقي ⇒ ⁦f'(a) = 0⁩\n• المنحنى فوق مماسه أو تحته يحدد نوع الانحناء\n▸ شرح مبسط\n• المنحنى صورة جدول التغيرات. إذا استطعت قراءة جدول التغيرات ورسمت المنحنى في ذهنك، فكل الأسئلة (عدد الحلول، الإشارة، القيم الحدية) تصبح مجرد نظر إلى الشكل.\n▸ الطرق والنصائح\n• ارسم تقريبيا ما يقوله جدول التغيرات.\n• على كل مجال رتابة تأخذ الدالة كل قيمة مرة واحدة على الأكثر.\n• لا تنس الجواب بمجالات مغلقة أو مفتوحة بدقة.\n▸ تمارين محلولة\n• تمرين 1: f متزايدة على ⁦]-∞ ; -1]⁩ وعلى ⁦[2 ; +∞[⁩، متناقصة على ⁦[-1 ; 2]⁩، مع ⁦f(-1) = 3⁩ و ⁦f(2) = -1⁩، وتؤول إلى ⁦-∞⁩ عند ⁦-∞⁩ وإلى ⁦+∞⁩ عند ⁦+∞⁩. كم حلا للمعادلة ⁦f(x) = 0⁩؟ ⁦f(x) = 3⁩؟ ⁦f(x) = 5⁩؟\n• الحل:\n   – ⁦f(x) = 0⁩: 3 حلول (واحد في كل مجال رتابة لأن 0 بين القيم)\n   – ⁦f(x) = 3⁩: حلان (⁦x = -1⁩ وحل في ⁦[2 ; +∞[⁩)\n   – ⁦f(x) = 5⁩: حل واحد في ⁦[2 ; +∞[⁩ لأن العظمى المحلية 3 < 5\n• تمرين 2: من نفس الدالة: ما مجموعة حلول ⁦f(x) ≥ 3⁩؟\n• الحل:\n   – ⁦f(x) = 3⁩ عند ⁦x = -1⁩ وعند حل ⁦x₀⁩ في ⁦]2 ; +∞[⁩\n   – على ⁦]-∞ ; -1[⁩ القيم أقل من 3، وعلى ⁦[-1 ; 2]⁩ أقل أو تساوي 3 (تنقص)\n   – إذن ⁦f(x) ≥ 3⁩ على ⁦{-1} ∪ [x₀ ; +∞[⁩\n▸ للحفظ\n• عدد حلول ⁦f(x) = k⁩ هو عدد تقاطعات المنحنى مع المستقيم ⁦y = k⁩."},{"title":"13. حل معادلات ومتراجحات بيانيا ومناقشتها","content":"▸ f(x) = g(x)\n• الحلول هي فواصل نقاط تقاطع المنحنيين\n• مثال: ⁦x³ - 3x = x⁩ ⇒ ⁦x(x² - 4) = 0⁩ ⇒ ⁦x = 0 , ±2⁩\n▸ f(x) > g(x)\n• المجالات التي يكون فيها منحنى f فوق منحنى g\n▸ مناقشة معادلة ⁦f(x) = m⁩\n• m وسيط حقيقي\n• نحرك المستقيم الأفقي ⁦y = m⁩\n• نحصي نقاط التقاطع حسب قيم m\n▸ حالات مناقشة دالة من الدرجة 3\n• للدالة قيمتان حديتان M (العظمى) و N (الصغرى):\n• ⁦m > M⁩ أو ⁦m < N⁩: حل واحد\n• ⁦m = M⁩ أو ⁦m = N⁩: حلان\n• ⁦N < m < M⁩: ثلاثة حلول\n▸ أخطاء شائعة\n• نسيان الحالات الحدية ⁦m = M⁩ أو ⁦m = n⁩\n• قراءة قيم M و n بالعين بدل الحساب\n▸ شرح مبسط\n• المناقشة هي أن نسأل: كم حلا للمعادلة؟ والجواب يتغير حسب m. نتخيل خطا أفقيا يتحرك من الأسفل إلى الأعلى فيقطع المنحنى مرة ثم مرتين ثم ثلاث مرات وهكذا.\n▸ الطرق والنصائح\n• ادرس الدالة وأنجز جدول التغيرات أولا.\n• حدد القيم الحدية وأطراف المجالات.\n• قسّم الجواب إلى حالات حسب m.\n▸ تمارين محلولة\n• تمرين 1: ⁦f(x) = x³ - 3x⁩ (قيمتاها الحديتان 2 و -2). ناقش عدد حلول ⁦x³ - 3x = m⁩.\n• الحل:\n   – ⁦m > 2⁩ أو ⁦m < -2⁩: حل واحد\n   – ⁦m = 2⁩ أو ⁦m = -2⁩: حلان\n   – ⁦-2 < m < 2⁩: ثلاثة حلول\n• تمرين 2: حل بيانيا ⁦f(x) ≥ 0⁩ من نفس الدالة (جذورها ⁦-√3 ، 0 ، √3⁩).\n• الحل:\n   – المنحنى فوق محور الفواصل على ⁦[-√3 ; 0]⁩ وعلى ⁦[√3 ; +∞[⁩\n   – الحلول: ⁦[-√3 ; 0] ∪ [√3 ; +∞[⁩\n• تمرين 3: ⁦f(x) = x² - 4x + 1⁩. ناقش عدد حلول ⁦f(x) = m⁩.\n• الحل:\n   – الدالة صغراها ⁦f(2) = -3⁩\n   – ⁦m < -3⁩: لا حل\n   – ⁦m = -3⁩: حل واحد\n   – ⁦m > -3⁩: حلان\n▸ للحفظ\n• ناقش بتحريك المستقيم الأفقي ⁦y = m⁩ ومقارنته بالقيم الحدية."},{"title":"14. الاستمثال (أكبر وأصغر قيمة)","content":"▸ الفكرة\n• نبحث عن أكبر أو أصغر قيمة لمقدار (مساحة، ربح، تكلفة...)\n• نحوله إلى دالة في متغير واحد\n▸ الخطوات\n• 1) اختر المتغير x وحدد مجاله\n• 2) عبّر عن المقدار بدلالة x\n• 3) احسب المشتق ودرس إشارته\n• 4) جدول التغيرات: القيمة العظمى أو الصغرى\n• 5) أجب بجملة تناسب المسألة\n▸ أمثلة شائعة\n• مستطيل بمحيط ثابت ⇒ أكبر مساحة عند المربع\n• ربح ⁦B(x)⁩ قطعي ⇒ الأعظم عند رأس القطع\n• علبة بحجم ⇒ أكبر حجم\n▸ تنبيه\n• x يجب أن يكون ضمن مجال المسألة (موجب مثلا)\n• لا تكتب القيمة فقط بل الأبعاد والمعنى\n▸ شرح مبسط\n• هذه الدروس هي أجمل تطبيقات المشتق: بدل التجريب نحسب بالضبط. نكتب المقدار المطلوب بدلالة متغير واحد ثم نبحث أين ينعدم المشتق وتتغير إشارته، فنقطة التغير هي القيمة المثلى.\n▸ الطرق والنصائح\n• عبّر عن كل شيء بدلالة متغير واحد.\n• انتبه لمجال x.\n• اقرأ السؤال في النهاية: ما المطلوب بالضبط؟\n▸ تمارين محلولة\n• تمرين 1: مستطيل محيطه 40 م. أوجد بعديه ليكون أكبر مساحة ممكنة.\n• الحل:\n   – العرض x والطول ⁦20 - x⁩ مع ⁦0 < x < 20⁩\n   – ⁦A(x) = x(20 - x) = -x² + 20x⁩\n   – ⁦A'(x) = -2x + 20⁩ تنعدم عند 10، موجبة قبلها وسالبة بعدها\n   – إذن العظمى ⁦A(10) = 100⁩ م²\n   – البعدان 10 م و 10 م (مربع)\n• تمرين 2: ربح مؤسسة (بالآلاف دج) عند إنتاج x وحدة: ⁦B(x) = -x² + 60x - 500⁩ مع ⁦x ≥ 0⁩. 1) أوجد الإنتاج المحقق لأكبر ربح. 2) أوجد مجال الإنتاج الذي يحقق ربحا موجبا.\n• الحل:\n   – 1) ⁦B'(x) = -2x + 60⁩ تنعدم عند 30\n   – ⁦B(30) = -900 + 1800 - 500 = 400⁩ أي 400 ألف دج\n   – 2) ⁦B(x) = 0⁩ فـ ⁦Δ = 3600 - 2000 = 1600⁩ والجذران ⁦x = 10⁩ أو ⁦x = 50⁩\n   – الربح موجب من أجل ⁦10 < x < 50⁩\n• تمرين 3: مزارع لديه 100 م من السياج ليسيّج حقلا مستطيلا ملاصقا لجدار (4 جهات منها 3 بسياج). أوجد أبعاد أكبر مساحة.\n• الحل:\n   – العرض x (جهتان) والطول ⁦100 - 2x⁩\n   – ⁦A(x) = x(100 - 2x) = -2x² + 100x⁩\n   – ⁦A'(x) = -4x + 100⁩ تنعدم عند 25\n   – ⁦A(25) = 25×50 = 1250⁩ م²\n   – البعدان 25 م و 50 م\n• تمرين 4: (متقدم) علبة من ورقة مربعة 12 سم نقص من أركانها مربعات ضلعها x. أوجد x لأكبر حجم.\n• الحل:\n   – الحجم ⁦V(x) = x(12 - 2x)² = 4x³ - 48x² + 144x⁩ مع ⁦0 < x < 6⁩\n   – ⁦V'(x) = 12(x - 2)(x - 6)⁩: موجبة على ⁦]0 ; 2[⁩ وسالبة على ⁦]2 ; 6[⁩\n   – العظمى ⁦V(2) = 2×8² = 128⁩ سم³ عند ⁦x = 2⁩\n▸ للحفظ\n• نكتب المقدار بدلالة متغير واحد ثم نحل ⁦f′(x)=0⁩ وندرس الإشارة."},{"title":"15. محاكاة تجربة عشوائية","content":"▸ التعريف\n• المحاكاة: تقليد تجربة عشوائية باستعمال مولد أعداد عشوائية\n• تغنينا عن تكرار التجربة يدويا آلاف المرات\n▸ الأدوات\n• الآلة الحاسبة: ⁦Ran#⁩ أو ⁦RanInt⁩\n• المجدول: ⁦ALEA()⁩ أو ⁦RANDBETWEEN(1,6)⁩\n• الحاسوب أو الهاتف\n▸ أمثلة\n• نرد: عدد صحيح عشوائي من 1 إلى 6\n• قطعة نقدية: 0 أو 1\n• صندوق 3 حمراء و2 زرقاء: عدد من 1 إلى 5 (1-3 حمراء، 4-5 زرقاء)\n▸ استنتاج\n• تتقارب تواترات الحدث من احتماله كلما زاد عدد التكرار\n• التواتر ⁦f⁩ = عدد مرات تحقق الحدث ÷ عدد التكرارات\n▸ أخطاء شائعة\n• اعتبار نتيجة 10 تكرارات دقيقة\n• الخلط بين التواتر (تجربة) والاحتمال (نظري)\n▸ شرح مبسط\n• نريد أن نعرف احتمال حدث، لكن قد لا نستطيع حسابه. فنُجري التجربة بالحاسوب آلاف المرات ونحسب نسبة نجاح الحدث، وهذه النسبة تقترب من الاحتمال الحقيقي كلما كررنا أكثر.\n▸ الطرق والنصائح\n• حوّل التجربة إلى عدد عشوائي.\n• حدد العلاقة بين الأعداد والنتائج.\n• كرر عددا كبيرا ثم احسب التواتر.\n▸ تمارين محلولة\n• تمرين 1: كيف تحاكي رمي نرد متوازن؟\n• الحل:\n   – نولد عددا صحيحا عشوائيا بين 1 و 6: في المجدول ⁦RANDBETWEEN(1,6)⁩ وفي الحاسبة ⁦RanInt#(1,6)⁩\n• تمرين 2: صندوق فيه 3 كريات حمراء و2 زرقاء. كيف تحاكي سحب كرية؟\n• الحل:\n   – نولد عددا من 1 إلى 5: الأعداد 1 و2 و3 تعني حمراء والعددان 4 و5 زرقاء\n   – احتمال الحمراء 3/5\n• تمرين 3: رمينا قطعة نقدية 100 مرة بالمحاكاة فكان عدد الوجوه 46. ما التواتر؟\n• الحل:\n   – ⁦f = 46/100 = 0.46⁩ وهو قريب من الاحتمال النظري 0.5\n▸ للحفظ\n• التواتر يقترب من الاحتمال عند تكرار التجربة مرات كبيرة."},{"title":"16. قانون الاحتمال لتجربة عشوائية","content":"▸ المفردات\n• مجموعة الإمكانيات ⁦Ω⁩\n• حدث: جزء من ⁦Ω⁩\n• حدث ابتدائي: عنصر واحد\n▸ قانون الاحتمال\n• ⁦0 ≤ pᵢ ≤ 1⁩ لكل نتيجة\n• مجموع احتمالات النتائج = 1\n• ⁦P(A)⁩ = مجموع احتمالات نتائج الحدث A\n▸ تساوي الاحتمال\n• ⁦P(A)⁩ = عدد الحالات الملائمة ÷ عدد الحالات الممكنة\n▸ القوانين\n• العكس: ⁦P(Ā) = 1 - P(A)⁩\n• الاتحاد: ⁦P(A ∪ B) = P(A) + P(B) - P(A ∩ B)⁩\n• غير متلائمين: ⁦P(A ∩ B) = 0⁩\n▸ جدول القانون\n• جدول يضم النتائج واحتمال كل منها\n• نتحقق دائما أن المجموع 1\n▸ شرح مبسط\n• الاحتمال عدد بين 0 و1 يقيس حظ وقوع الحدث. إذا كانت كل النتائج متساوية الحظ فالاحتمال هو نسبة الحالات المناسبة إلى كل الحالات. وإذا لم تكن متساوية فنأخذ احتمال كل نتيجة ونجمعها.\n▸ الطرق والنصائح\n• عدّ الحالات بدقة (جدول أو شجرة).\n• تحقق أن المجموع 1.\n• ⁦P(Ā)⁩ تختصر الكثير من الحسابات (حدث \"على الأقل\").\n▸ تمارين محلولة\n• تمرين 1: نرد غير متوازن: احتمال ظهور 6 ضعف احتمال ظهور كل وجه آخر (متساوية). أوجد قانون الاحتمال واحتمال أن يكون الوجه زوجيا.\n• الحل:\n   – لكل وجه من 1 إلى 5 الاحتمال ⁦p⁩، و ⁦P(6) = 2p⁩\n   – ⁦7p = 1⁩ فـ ⁦p = 1/7⁩ و ⁦P(6) = 2/7⁩\n   – احتمال الزوجي = ⁦P(2) + P(4) + P(6) = 1/7 + 1/7 + 2/7 = 4/7⁩\n• تمرين 2: نرمي نردين متوازنين ونجمع النتيجتين. احسب احتمال المجموع 7 والمجموع ⁦≥ 10⁩.\n• الحل:\n   – إمكانيات 36\n   – المجموع 7: 6 حالات فـ ⁦P = 6/36 = 1/6⁩\n   – المجموع ⁦≥ 10⁩: 10 (3 حالات) و11 (حالتان) و12 (حالة) = 6 حالات فـ ⁦P = 6/36 = 1/6⁩\n• تمرين 3: نرمي قطعة نقدية مرتين. أوجد قانون X = عدد الوجوه.\n• الحل:\n   – النتائج: PP, PF, FP, FF (4 متساوية)\n   – ⁦X = 0⁩ باحتمال 1/4، ⁦X = 1⁩ باحتمال 1/2، ⁦X = 2⁩ باحتمال 1/4\n   – المجموع 1\n▸ للحفظ\n• ⁦P(A) =⁩ الملائمة / الممكنة⁦. P(⁩Ā⁦) = 1 − P(A)⁩. مجموع الاحتمالات ⁦= 1⁩."},{"title":"17. الأمل الرياضياتي والتباين","content":"▸ المتغير العشوائي X\n• يرفق بكل نتيجة عددا (ربح، عدد وجوه...)\n• قانونه: جدول القيم ⁦xᵢ⁩ واحتمالاتها ⁦pᵢ⁩\n▸ الأمل الرياضياتي\n• ⁦E(X) = Σ xᵢ·pᵢ = x₁p₁ + x₂p₂ + ...⁩\n• هو متوسط النتائج على المدى الطويل\n▸ التباين والانحراف المعياري\n• ⁦V(X) = Σ pᵢ·xᵢ² - E(X)²⁩\n• ⁦σ = √V(X)⁩\n• يقيس تشتت القيم حول الأمل\n▸ خواص\n• ⁦E(aX + b) = a·E(X) + b⁩\n• ⁦V(aX + b) = a²·V(X)⁩\n▸ لعبة عادلة\n• لعبة عادلة إذا ⁦E(X) = 0⁩ (X الربح الجبري)\n• ⁦E(X) > 0⁩ في صالح اللاعب، ⁦E(X) < 0⁩ في صالح المنظم\n▸ شرح مبسط\n• الأمل الرياضياتي هو \"الربح المتوقع في المتوسط\": لو لعبت اللعبة آلاف المرات فكم تربح في الجولة الواحدة؟ والتباين يقيس مدى تشتت النتائج: لعبتان لهما الأمل نفسه قد تختلفان كثيرا في الخطر.\n▸ الطرق والنصائح\n• اكتب جدول القانون وتحقق أن مجموع الاحتمالات 1.\n• احسب ⁦E(X)⁩ ثم ⁦E(X²)⁩ ثم التباين.\n• الربح الجبري يكون سالبا في حالة الخسارة.\n▸ تمارين محلولة\n• تمرين 1: نرمي نردا متوازنا: نربح 10 دج إذا ظهر 6، ونربح 2 دج إذا ظهر 4 أو 5، ونخسر 3 دج في الحالات الأخرى. أعط قانون X واحسب أمله الرياضياتي.\n• الحل:\n   – القيم: 10 باحتمال 1/6، 2 باحتمال 2/6، -3 باحتمال 3/6\n   – ⁦E(X) = (10 + 4 - 9)/6 = 5/6 ≈ 0.83⁩ دج\n   – الأمل موجب فاللعبة في صالح اللاعب\n• تمرين 2: احسب تباين وانحراف المتغير السابق.\n• الحل:\n   – ⁦E(X²) = (100×1 + 4×2 + 9×3)/6 = 135/6 = 22.5⁩\n   – ⁦V = 22.5 - (5/6)² = 785/36 ≈ 21.81⁩ و ⁦σ ≈ 4.67⁩\n• تمرين 3: نرد متوازن X = العدد الظاهر. احسب ⁦E(X)⁩ و ⁦V(X)⁩.\n• الحل:\n   – ⁦E(X) = (1+2+3+4+5+6)/6 = 3.5⁩\n   – ⁦E(X²) = 91/6⁩\n   – ⁦V(X) = 91/6 - 49/4 = 35/12 ≈ 2.92⁩\n• تمرين 4: سحب 1000 تذكرة، جائزة واحدة قيمتها 500 دج، وثمن التذكرة 2 دج. احسب الأمل الرياضياتي لربح المشتري.\n• الحل:\n   – X = 498 باحتمال 1/1000 و X = -2 باحتمال 999/1000\n   – ⁦E(X) = (498 - 1998)/1000 = -1.5⁩ دج\n   – اللعبة في صالح المنظم\n▸ للحفظ\n• ⁦E(X) =⁩ Σ ⁦xᵢ pᵢ. V =⁩ Σ ⁦pᵢ xᵢ² − E²⁩. لعبة عادلة ⁦⇔ E = 0⁩."},{"title":"18. الاحتمال الشرطي وشجرة الاحتمالات","content":"▸ الشجرة\n• نضرب الاحتمالات على طول المسار\n• نجمع المسارات المؤدية إلى الحدث\n• مجموع احتمالات فروع نفس العقدة = 1\n▸ الاحتمال الشرطي\n• ⁦P_(B)(A) = P(A ∩ B) / P(B)⁩\n• احتمال A علما أن B وقع\n▸ الاحتمال الكلي\n• ⁦P(D) = P(A)P_(A)(D) + P(B)P_(B)(D)⁩\n▸ سحب بإرجاع وبدون إرجاع\n• بإرجاع: الاحتمالات ثابتة، السحبتان مستقلتان\n• دون إرجاع: يتغير عدد الكريات في السحب الثاني\n▸ أخطاء شائعة\n• الخلط بين ⁦P_(B)(A)⁩ و ⁦P_(A)(B)⁩\n• نسيان إرجاع/عدم إرجاع الكرية\n• جمع الاحتمالات على طول المسار بدل ضربها\n▸ شرح مبسط\n• الشجرة تنظم الحساب: كل مسار هو نتيجة محتملة، واحتماله هو حاصل ضرب احتمالات فروعه. وإذا أردت احتمال حدث فاجمع احتمالات المسارات التي تحققه. والاحتمال الشرطي يغيّر \"الكون\" ليصبح الحدث المعلوم.\n▸ الطرق والنصائح\n• ارسم الشجرة أولا.\n• اكتب الاحتمال على كل فرع.\n• اضرب على المسار واجمع بين المسارات.\n▸ تمارين محلولة\n• تمرين 1: كيس: 5 حمراء و3 زرقاء و2 خضراء. نسحب كريتين على التوالي. احسب احتمال كريتين من اللون نفسه مع الإرجاع ثم دون إرجاع.\n• الحل:\n   – مع الإرجاع: ⁦P(RR) = 0.5×0.5 = 0.25⁩ و ⁦P(BB) = 0.09⁩ و ⁦P(GG) = 0.04⁩ فالمجموع 0.38\n   – دون إرجاع: ⁦5/10×4/9 = 2/9⁩ و ⁦3/10×2/9 = 1/15⁩ و ⁦2/10×1/9 = 1/45⁩\n   – المجموع ⁦(10 + 3 + 1)/45 = 14/45⁩\n• تمرين 2: مصنع: الآلة A تنتج 60% ونسبة العيوب 5%، والآلة B تنتج 40% ونسبة العيوب 10%. نختار قطعة. احسب احتمال أن تكون معيبة. وإذا كانت معيبة فما احتمال أن تكون من A؟\n• الحل:\n   – ⁦P(D) = 0.6×0.05 + 0.4×0.10 = 0.03 + 0.04 = 0.07⁩\n   – ⁦P_(D)(A) = 0.03/0.07 = 3/7 ≈ 0.43⁩\n• تمرين 3: نرمي نردا: A «الوجه زوجي» و B «مضاعف للعدد 3». احسب ⁦P(A)⁩ و ⁦P(B)⁩ و ⁦P(A ∩ B)⁩ و ⁦P(A ∪ B)⁩.\n• الحل:\n   – ⁦P(A) = 3/6 = 1/2⁩ و ⁦P(B) = 2/6 = 1/3⁩\n   – ⁦A ∩ B = {6}⁩ فـ ⁦P(A ∩ B) = 1/6⁩\n   – ⁦P(A ∪ B) = 1/2 + 1/3 - 1/6 = 2/3⁩\n▸ للحفظ\n• شجرة: نضرب على المسار ونجمع بين المسارات⁦. P_(B)(A) = P(A⁩∩⁦B)/P(B)⁩."},{"title":"19. الإحصاء: المتوسط والوسيط والتباين","content":"▸ المتوسط\n• ⁦x̄ = Σ nᵢ xᵢ / N⁩\n• في سلسلة مبوبة نستعمل مراكز الفئات\n▸ الوسيط والربيعيات\n• الوسيط يقسم السلسلة المرتبة إلى نصفين\n• ⁦Q₁⁩ و ⁦Q₃⁩ الربيع الأول والثالث\n• المدى الربيعي ⁦Q₃ - Q₁⁩\n▸ التباين والانحراف\n• ⁦V = Σ nᵢ xᵢ² / N - x̄²⁩\n• ⁦σ = √V⁩\n▸ سلسلة مبوبة\n• نحسب التكرارات المتجمعة\n• نحدد فئة الوسيط (التي تحوي ⁦N/2⁩)\n• الاستكمال الخطي لتحديد قيمته\n▸ أخطاء شائعة\n• نسيان ترتيب السلسلة قبل الوسيط\n• استعمال حدود الفئات بدل المراكز\n• نسيان الجذر في الانحراف المعياري\n▸ شرح مبسط\n• نلخص سلسلة طويلة من الأعداد بعدد أو عددين: المتوسط يعطي \"المركز\"، والانحراف المعياري يعطي \"التشتت\". الوسيط هو القيمة التي في الوسط تماما.\n▸ الطرق والنصائح\n• رتّب القيم أولا.\n• في الفئات: احسب المراكز.\n• تحقق: ⁦V ≥ 0⁩ دائما.\n▸ تمارين محلولة\n• تمرين 1: السلسلة 2، 4، 4، 5، 5، 6، 8، 10. احسب المتوسط والوسيط والربيعين والتباين والانحراف.\n• الحل:\n   – ⁦N = 8⁩ والمجموع 44: ⁦x̄ = 5.5⁩\n   – الوسيط ⁦(5 + 5)/2 = 5⁩\n   – ⁦Q₁ = (4 + 4)/2 = 4⁩ و ⁦Q₃ = (6 + 8)/2 = 7⁩\n   – مجموع المربعات 286: ⁦V = 286/8 - 5.5² = 35.75 - 30.25 = 5.5⁩ و ⁦σ ≈ 2.35⁩\n• تمرين 2: الأجور (آلاف دج) لـ 40 عاملا: ⁦]0;10]⁩:4، ⁦]10;20]⁩:10، ⁦]20;30]⁩:16، ⁦]30;40]⁩:10. احسب المتوسط والانحراف المعياري وقدّر الوسيط.\n• الحل:\n   – المراكز 5، 15، 25، 35\n   – ⁦x̄ = 920/40 = 23⁩\n   – ⁦Σ n x² = 24600⁩ فـ ⁦V = 615 - 529 = 86⁩ و ⁦σ ≈ 9.27⁩\n   – التكرارات المتجمعة: 4، 14، 30، 40 و ⁦N/2 = 20⁩ في ⁦]20 ; 30]⁩: الوسيط ⁦20 + 10×(20 - 14)/16 = 23.75⁩\n▸ للحفظ\n• المتوسط للمركز، الانحراف للتشتت، الوسيط يقسم السلسلة إلى نصفين."},{"title":"20. تذبذب العينات ومجال الثقة (إضافي)","content":"▸ تذبذب العينات\n• عند سحب عينات حجمها n من مجتمع نسبة خاصية فيه p\n• يتغير تواتر الخاصية ⁦f⁩ من عينة لأخرى\n▸ مجال التذبذب (95%)\n• ⁦[ p - 1/√n ; p + 1/√n ]⁩\n• بشرط ⁦n ≥ 25⁩ و ⁦0.2 ≤ p ≤ 0.8⁩\n▸ مجال الثقة (95%)\n• إذا كان التواتر المشاهد ⁦f⁩:\n• ⁦[ f - 1/√n ; f + 1/√n ]⁩\n• يقدّر النسبة المجهولة p\n▸ اتخاذ القرار\n• إذا كان ⁦f⁩ خارج مجال التذبذب نرفض الفرضية\n• وإلا لا نرفضها (بمستوى ثقة 95%)\n▸ شرح مبسط\n• قطعة نقدية متوازنة لا تعطي دائما نصف وجوه بالضبط. فإذا رميناها 100 مرة قد نحصل على 46 أو 54 وجها. مجال التذبذب يحدد المجال المعقول للنتائج. وإذا خرجنا منه فربما القطعة غير متوازنة.\n▸ الطرق والنصائح\n• احسب ⁦1/√n⁩ أولا.\n• أنشئ المجال ثم قارن ⁦f⁩ به.\n▸ تمارين محلولة\n• تمرين 1: نرمي قطعة نقدية 100 مرة فنحصل على 62 وجها. أوجد مجال التذبذب عند 95% وهل نشك في القطعة؟\n• الحل:\n   – ⁦p = 0.5⁩ و ⁦n = 100⁩ فـ ⁦1/√n = 0.1⁩ والمجال ⁦[0.4 ; 0.6]⁩\n   – التواتر ⁦f = 0.62⁩ خارجه، فنشك (بمستوى ثقة 95%) في أن القطعة غير نظامية\n• تمرين 2: في استطلاع 400 شخص أيّد 220 منهم مشروعا. قدّر نسبة المؤيدين.\n• الحل:\n   – ⁦f = 220/400 = 0.55⁩ و ⁦1/√400 = 0.05⁩\n   – مجال الثقة ⁦[0.50 ; 0.60]⁩\n   – نقدّر أن النسبة بين 50% و60% تقريبا\n▸ للحفظ\n• مجال التذبذب ⁦[p ± 1/√n]⁩. مجال الثقة ⁦[f ± 1/√n]⁩."},{"title":"21. منهجية الإجابة في الرياضيات","content":"▸ قبل الحل\n• اقرأ الموضوع كاملا\n• ابدأ بالتمرين الأسهل\n• ارسم جدولا أو شكلا عند الحاجة\n▸ أثناء الحل\n• اكتب القانون قبل التعويض\n• اشرح كل خطوة بجملة قصيرة\n• لا تحذف خطوات الحساب\n▸ أخطاء قاتلة\n• نسيان أن ⁦n⁩ طبيعي في المتتاليات\n• نسيان مجال التعريف في الدوال\n• استعمال الجداء بدل المجموع في المشتق\n• اختيار الحل السالب في مسألة هندسية\n▸ قبل التسليم\n• تحقق من الأجوبة بتعويضها\n• اقرأ السؤال مرة أخرى\n• قدّر هل الجواب منطقي (مساحة موجبة، احتمال بين 0 و1)\n▸ ملخص القوانين\n• حسابية: ⁦uₙ = uₚ + (n-p)r⁩\n• هندسية: ⁦uₙ = uₚ qⁿ⁻ᵖ⁩\n• مماس: ⁦y = f'(a)(x-a) + f(a)⁩\n• احتمال: ⁦P(Ā) = 1 - P(A)⁩\n• أمل: ⁦E = Σ xᵢ pᵢ⁩\n▸ شرح مبسط\n• الرياضيات ليست حفظا فقط بل ترتيب أفكار. العلامة الكاملة تأتي من اتباع خطوات واضحة: تعريف الرموز، القانون، التعويض، النتيجة، الجملة النهائية. وكل خطأ حساب بسيط يمكن تفاديه بالمراجعة.\n▸ الطرق والنصائح\n• أعط كل نتيجة وحدة (دج، م²).\n• اكتب الجملة النهائية.\n• ابدأ بالأسئلة التي تعرفها.\n▸ تمارين محلولة\n• تمرين 1: كيف أتعرف على نوع المتتالية؟\n• الحل:\n   – احسب ⁦uₙ₊₁ - uₙ⁩: ثابت ⇒ حسابية\n   – احسب ⁦uₙ₊₁/uₙ⁩: ثابت ⇒ هندسية\n   – وإلا فالعلاقة من الشكل ⁦a·uₙ + b⁩ أو متتالية أخرى\n• تمرين 2: كيف أدرس دالة؟\n• الحل:\n   – مجموعة التعريف ثم النهايات ثم المشتق وإشارته ثم جدول التغيرات ثم النقاط الخاصة ثم الرسم\n▸ للحفظ\n• اقرأ، اكتب القانون، عوّض، احسب، أجب بجملة، ثم تحقق."}],maps:'math'};
  var pMM={name:'الرياضيات',lessons:[{"title":"1. النهايات وأشكال عدم التعيين","content":"▸ أشكال عدم التعيين\n• ⁦∞ - ∞⁩ ، ⁦0 × ∞⁩ ، ⁦∞/∞⁩ ، ⁦0/0⁩\n• لا نعطي النتيجة مباشرة بل نرفع عدم التعيين\n• النتيجة قد تكون أي عدد أو ⁦±∞⁩\n▸ كثير حدود وناطقة عند ∞\n• كثير حدود: نهاية الحد الأعلى درجة\n• ناطقة: حاصل قسمة الحدين الأعلى درجة\n• ⁦lim (2x² + x)/(x² - 1) = 2⁩ عند ⁦+∞⁩\n▸ المرافق (الجذور)\n• نضرب ونقسم على ⁦√A + √B⁩ عند وجود ⁦√A - √B⁩\n• ⁦(√A - √B)(√A + √B) = A - B⁩\n• بعد التبسيط نقسم على أعلى قوة لـ x\n▸ عند عدد a\n• ⁦0/0⁩: نحلل ونختصر أو نستعمل العدد المشتق\n• المقام يعدم: ندرس إشارته عن اليمين واليسار\n• النتيجة ⁦±∞⁩ ⇒ مقارب عمودي\n▸ كيف نبرهن؟\n• اكتب شكل عدم التعيين بوضوح\n• اختر الطريقة: تحليل، مرافق، إخراج الحد الأعلى\n• احسب بعد التبسيط واذكر النتيجة بجملة\n▸ شرح مبسط\n• النهاية تصف سلوك الدالة عند طرف مجال تعريفها. أصعب الحالات هي أشكال عدم التعيين، حيث تتصارع الأجزاء في العبارة (مثل ∞ - ∞) فلا نعرف من الأقوى. نكسر هذا التعادل بتغيير شكل العبارة: تحليل أو مرافق أو إخراج الحد الأعلى درجة عاملا مشتركا.\n▸ طرق وقواعد\n• عوّض أولا: إن لم يظهر عدم تعيين فالنتيجة مباشرة.\n• جذر مطروح من جذر أو من عدد ⇒ المرافق.\n• ⁦x → ∞⁩ وكسر ⇒ أخرج أعلى قوة في البسط والمقام.\n• ⁦0/0⁩ في كثير حدود ⇒ حلل واختصر.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦lim (√(x² + x) - x)⁩ عند ⁦+∞⁩.\n• الحل:\n   – شكل عدم التعيين ⁦∞ - ∞⁩\n   – نضرب ونقسم على المرافق: ⁦√(x²+x) - x = ((x² + x) - x²)/(√(x²+x) + x) = x/(√(x²+x) + x)⁩\n   – نقسم البسط والمقام على x (حيث ⁦x > 0⁩): ⁦= 1/(√(1 + 1/x) + 1)⁩\n   – وبما أن ⁦1/x → 0⁩ فالنهاية ⁦1/2⁩\n• تمرين 2: احسب ⁦lim (x² - 1)/(x - 1)⁩ عند 1.\n• الحل:\n   – شكل ⁦0/0⁩\n   – نحلل: ⁦x² - 1 = (x - 1)(x + 1)⁩\n   – بعد الاختصار نجد ⁦x + 1⁩ فالنهاية 2\n• تمرين 3: احسب ⁦lim (x - √(x² + 1))⁩ عند ⁦+∞⁩.\n• الحل:\n   – شكل ⁦∞ - ∞⁩\n   – المرافق: ⁦x - √(x²+1) = (x² - (x²+1))/(x + √(x²+1)) = -1/(x + √(x²+1))⁩\n   – المقام يؤول إلى ⁦+∞⁩ فالنهاية 0\n• تمرين 4: احسب ⁦lim (3x² - x + 1)/(x² + 2)⁩ عند ⁦+∞⁩.\n• الحل:\n   – شكل ⁦∞/∞⁩\n   – الحدان الأعلى درجة ⁦3x²⁩ و ⁦x²⁩ فالنهاية ⁦3⁩\n▸ للحفظ\n• عدم التعيين لا يُحسب مباشرة: حلّل، أو المرافق، أو أخرج الحد الأعلى درجة."},{"title":"2. مبرهنات الحصر والمقارنة والنهايات المرجعية","content":"▸ مبرهنة الحصر\n• إذا ⁦g(x) ≤ f(x) ≤ h(x)⁩\n• و ⁦lim g = lim h = L⁩\n• فإن ⁦lim f = L⁩\n▸ مبرهنة المقارنة\n• ⁦f ≥ g⁩ و ⁦lim g = +∞⁩ ⇒ ⁦lim f = +∞⁩\n• ⁦f ≤ g⁩ و ⁦lim g = -∞⁩ ⇒ ⁦lim f = -∞⁩\n▸ نهايات مرجعية\n• ⁦lim sin(x)/x = 1⁩ و ⁦lim (eˣ - 1)/x = 1⁩ عند 0\n• ⁦lim ln(1+x)/x = 1⁩ عند 0\n• ⁦lim eˣ/xⁿ = +∞⁩ و ⁦lim ln x/xⁿ = 0⁩ عند ⁦+∞⁩\n• ⁦lim x·ln x = 0⁩ عند ⁦0^+⁩\n▸ نهاية دالة مركبة\n• إذا ⁦lim u = b⁩ و ⁦lim f = L⁩ عند b\n• فإن ⁦lim f(u(x)) = L⁩\n• نستعمل تغيير المتغير ⁦t = u(x)⁩\n▸ كيف نبرهن؟\n• اكتب حصرا واضحا للدالة\n• تحقق أن الطرفين لهما نفس النهاية\n• اختم: حسب مبرهنة الحصر النهاية ...\n▸ شرح مبسط\n• عندما تكون الدالة معقدة (فيها جيب أو جيب تمام) لا نستطيع حساب نهايتها مباشرة، لكن نعرف أنها محصورة بين دالتين بسيطتين تؤولان إلى القيمة نفسها. فلا خيار لها إلا أن تؤول إلى تلك القيمة أيضا.\n▸ طرق وقواعد\n• ⁦-1 ≤ sin x ≤ 1⁩ و ⁦-1 ≤ cos x ≤ 1⁩ أساس أغلب الحصر.\n• نضرب الحصر في عدد موجب (مثل x) دون عكس المتباينة.\n• للمقارنة: دالة تتجاوز دالة تؤول إلى ∞.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦lim sin(x)/x⁩ عند ⁦+∞⁩.\n• الحل:\n   – لدينا ⁦-1 ≤ sin x ≤ 1⁩\n   – من أجل ⁦x > 0⁩: ⁦-1/x ≤ sin(x)/x ≤ 1/x⁩\n   – الطرفان يؤولان إلى 0، فحسب مبرهنة الحصر النهاية 0\n• تمرين 2: احسب ⁦lim (x + cos x)⁩ عند ⁦+∞⁩.\n• الحل:\n   – ⁦cos x ≥ -1⁩ فـ ⁦x + cos x ≥ x - 1⁩\n   – و ⁦x - 1 → +∞⁩ فحسب المقارنة النهاية ⁦+∞⁩\n• تمرين 3: احسب ⁦lim x·sin(1/x)⁩ عند ⁦+∞⁩.\n• الحل:\n   – نضع ⁦t = 1/x⁩ فـ ⁦t → 0^+⁩ والعبارة تصبح ⁦sin(t)/t⁩ ونهايتها 1\n• تمرين 4: احسب ⁦lim (2 + sin x)/x⁩ عند ⁦+∞⁩.\n• الحل:\n   – ⁦1 ≤ 2 + sin x ≤ 3⁩ فـ ⁦1/x ≤ (2 + sin x)/x ≤ 3/x⁩ والطرفان يؤولان إلى 0، فالنهاية 0\n▸ للحفظ\n• حصر⁦: g ≤ f ≤ h⁩ ونهايتا g و h متساويتان ⁦⇒ f⁩ لها النهاية نفسها."},{"title":"3. الاستمرارية ومبرهنة القيم المتوسطة","content":"▸ الاستمرارية\n• f مستمرة عند a إذا ⁦lim f(x) = f(a)⁩\n• كثيرات الحدود والناطقة والجذر وsin وcos وexp وln مستمرة على مجالات تعريفها\n• المجموع والجداء والتركيب يحافظان على الاستمرارية\n• كل دالة اشتقاقية مستمرة (العكس خاطئ)\n▸ مبرهنة القيم المتوسطة\n• f مستمرة على ⁦[a ; b]⁩ و k بين ⁦f(a)⁩ و ⁦f(b)⁩\n• المعادلة ⁦f(x) = k⁩ لها حل على الأقل في ⁦[a ; b]⁩\n▸ حل وحيد\n• إذا كانت f أيضا رتيبة تماما\n• يكون الحل وحيدا\n• حالة خاصة: ⁦f(a)·f(b) < 0⁩ ⇒ حل وحيد للمعادلة ⁦f(x) = 0⁩\n▸ التأطير (التنصيف)\n• نحسب f عند قيم متتالية حتى تتغير الإشارة\n• نضيّق المجال تدريجيا للحصول على سعة معينة\n▸ كيف نبرهن؟\n• 1) f مستمرة على المجال\n• 2) f رتيبة تماما (إشارة المشتق)\n• 3) ⁦f(a)·f(b) < 0⁩\n• 4) إذن حسب مبرهنة القيم المتوسطة يوجد حل وحيد\n▸ شرح مبسط\n• الدالة المستمرة هي التي يمكن رسم منحناها دون رفع القلم. فإذا بدأ المنحنى تحت محور الفواصل وانتهى فوقه فلا بد أنه قطعه. وإذا كانت الدالة تصعد فقط (رتيبة) فهي تقطعه مرة واحدة فقط. هذه هي فكرة الحل الوحيد.\n▸ طرق وقواعد\n• اذكر الاستمرارية والرتابة صراحة في كل برهان.\n• للتأطير: احسب f على قيم بخطوة 0.1 ثم 0.01.\n• لإثبات استمرارية دالة مجزأة عند a: قارن النهاية اليمنى واليسرى مع ⁦f(a)⁩.\n▸ تمارين محلولة\n• تمرين 1: بيّن أن المعادلة ⁦x³ + x - 1 = 0⁩ تقبل حلا وحيدا α في ⁦[0 ; 1]⁩ ثم أعط تأطيرا له سعته 0.01.\n• الحل:\n   – نضع ⁦f(x) = x³ + x - 1⁩\n   – (1) f مستمرة (كثير حدود)\n   – (2) ⁦f′(x) = 3x² + 1 > 0⁩ فهي متزايدة تماما\n   – (3) ⁦f(0) = -1 < 0⁩ و ⁦f(1) = 1 > 0⁩\n   – إذن يوجد حل وحيد α في ⁦]0 ; 1[⁩\n   – التأطير: ⁦f(0.6) = -0.184 < 0⁩ و ⁦f(0.7) = 0.043 > 0⁩ فـ ⁦0.6 < α < 0.7⁩\n   – ثم ⁦f(0.68) ≈ -0.0056 < 0⁩ و ⁦f(0.69) ≈ 0.0185 > 0⁩ فـ ⁦0.68 < α < 0.69⁩\n• تمرين 2: بيّن أن المعادلة ⁦x = cos x⁩ تقبل حلا وحيدا في ⁦[0 ; 1]⁩.\n• الحل:\n   – نضع ⁦g(x) = x - cos x⁩ المستمرة\n   – ⁦g′(x) = 1 + sin x ≥ 1 > 0⁩ على ⁦[0 ; 1]⁩ لأن ⁦sin x ≥ 0⁩ فيه\n   – فهي متزايدة تماما\n   – ⁦g(0) = -1 < 0⁩ و ⁦g(1) = 1 - cos 1 > 0⁩\n   – إذن حل وحيد\n• تمرين 3: ⁦f(x) = (x² - 1)/(x - 1)⁩ من أجل ⁦x ≠ 1⁩ و ⁦f(1) = a⁩. عيّن a لتكون f مستمرة عند 1.\n• الحل:\n   – ⁦lim f(x) = lim (x + 1) = 2⁩ عند 1\n   – الاستمرارية تتطلب ⁦f(1) = 2⁩ أي ⁦a = 2⁩\n▸ للحفظ\n• مستمرة + رتيبة تماما ⁦+ f(a)·f(b) < 0 ⇒⁩ حل وحيد في ⁦[a ; b]⁩."},{"title":"4. الاشتقاق ومشتقات الدوال المركبة","content":"▸ العدد المشتق\n• ⁦f′(a) = lim (f(x) - f(a))/(x - a)⁩ عند a\n• يوجد إذا وُجدت النهاية وكانت منتهية\n• ميل المماس عند النقطة ذات الفاصلة a\n▸ مشتقات المركب\n• ⁦(uⁿ)′ = n·u′·uⁿ⁻¹⁩\n• ⁦(√u)′ = u′/(2√u)⁩ و ⁦(1/u)′ = -u′/u²⁩\n• ⁦(sin u)′ = u′·cos u⁩ و ⁦(cos u)′ = -u′·sin u⁩\n• ⁦(f(ax+b))′ = a·f′(ax+b)⁩\n▸ المماس\n• ⁦y = f′(a)(x - a) + f(a)⁩\n• إذا كان f غير اشتقاقي عند a لكن نهايتا النسبة موجودتان فيوجد نصفا مماس\n▸ عدم الاشتقاقية\n• ⁦|x|⁩ غير اشتقاقية عند 0: النهاية اليمنى 1 واليسرى -1\n• الدالة المستمرة قد لا تكون اشتقاقية\n▸ كيف نبرهن؟\n• قابلية الاشتقاق عند a: احسب نهاية النسبة وبيّن أنها منتهية\n• إذا اختلفت النهايتان اليمنى واليسرى فغير اشتقاقية\n▸ شرح مبسط\n• المشتق هو معدل التغير اللحظي. ولمشتق دالة معقدة نستعمل قاعدة السلسلة: نشتق الدالة الخارجية ثم نضرب في مشتق الداخلية. مثلا مشتق ⁦(x² + 1)³⁩ هو ⁦3 × (2x) × (x² + 1)²⁩.\n▸ طرق وقواعد\n• حدد الدالة الداخلية u والخارجية قبل الاشتقاق.\n• تحقق من مجال الاشتقاق (الجذر والمقام).\n• قارن مع القاعدة: مشتق الجداء ليس جداء المشتقات.\n▸ تمارين محلولة\n• تمرين 1: احسب مشتقة ⁦f(x) = (x² + 1)³⁩ و ⁦g(x) = √(x² + 1)⁩ و ⁦h(x) = sin(2x + 1)⁩.\n• الحل:\n   – ⁦f′(x) = 3×2x×(x²+1)² = 6x(x²+1)²⁩\n   – ⁦g′(x) = 2x/(2√(x²+1)) = x/√(x²+1)⁩\n   – ⁦h′(x) = 2cos(2x + 1)⁩\n• تمرين 2: اكتب معادلة المماس لـ ⁦f(x) = √x⁩ عند ⁦x = 4⁩.\n• الحل:\n   – ⁦f(4) = 2⁩ و ⁦f′(x) = 1/(2√x)⁩ فـ ⁦f′(4) = 1/4⁩\n   – ⁦y = (x - 4)/4 + 2 = x/4 + 1⁩\n• تمرين 3: بيّن أن ⁦f(x) = |x|⁩ غير اشتقاقية عند 0.\n• الحل:\n   – ⁦(f(x) - f(0))/x = |x|/x⁩\n   – على اليمين تساوي 1 وعلى اليسار -1\n   – النهايتان مختلفتان فغير اشتقاقية عند 0\n▸ للحفظ\n• ⁦(uⁿ)′ = n u′ uⁿ⁩⁻¹ ، ⁦(√u)′ = u′/(2√u)⁩ ، ⁦(sin u)′ = u′cos u⁩."},{"title":"5. منهج دراسة دالة كاملة","content":"▸ الخطوات\n• 1) مجموعة التعريف والتناظر\n• 2) النهايات والمقاربات\n• 3) المشتق وإشارته\n• 4) جدول التغيرات\n• 5) المشتق الثاني وانعطاف (إن طُلب)\n• 6) المماسات والوضعية والرسم\n▸ المقاربات\n• عمودي: ⁦lim f = ±∞⁩ عند a\n• أفقي: ⁦lim f = L⁩ عند ⁦±∞⁩\n• مائل: ⁦lim [f(x) - (ax + b)] = 0⁩\n• الوضعية: إشارة ⁦f(x) - (ax + b)⁩\n▸ التقعر والانعطاف\n• ⁦f″ > 0⁩ ⇒ محدب (فوق مماساته)\n• ⁦f″ < 0⁩ ⇒ مقعر\n• انعطاف: ⁦f″⁩ تنعدم وتغير إشارتها\n▸ القيم الحدية\n• ⁦f′⁩ تنعدم وتغير الإشارة ⇒ قيمة حدية محلية\n• نحسب ⁦f⁩ عند هذه القيم\n▸ الرسم\n• نرسم المقاربات أولا\n• ثم النقاط الخاصة والمماسات\n• ثم نصل المنحنى حسب جدول التغيرات\n▸ شرح مبسط\n• دراسة الدالة هي سيرة ذاتية للمنحنى: أين يبدأ وأين ينتهي (النهايات)، وأين يصعد وأين ينزل (المشتق)، وأين يقترب من خط دون أن يلمسه (المقاربات). لا ترسم شيئا قبل أن تنجز الجدول.\n▸ طرق وقواعد\n• ابدأ بمجموعة التعريف دائما.\n• اكتب جدول التغيرات كاملا بالنهايات.\n• عند وجود مقارب مائل ادرس الوضعية.\n▸ تمارين محلولة\n• تمرين 1: ادرس ⁦f(x) = x + 1/(x - 1)⁩ على ⁦ℝ \\ {1}⁩.\n• الحل:\n   – ⁦lim f = ±∞⁩ عند ⁦1^±⁩ (⁦+∞⁩ على اليمين و ⁦-∞⁩ على اليسار) فالمقارب ⁦x = 1⁩\n   – و ⁦f(x) - x = 1/(x-1) → 0⁩ عند ⁦±∞⁩ فالمقارب المائل ⁦y = x⁩\n   – ⁦f′(x) = 1 - 1/(x-1)² = x(x - 2)/(x-1)²⁩: موجبة على ⁦]-∞ ; 0[⁩ و ⁦]2 ; +∞[⁩ وسالبة على ⁦]0 ; 1[⁩ و ⁦]1 ; 2[⁩\n   – القيمة العظمى المحلية ⁦f(0) = -1⁩ والصغرى ⁦f(2) = 3⁩\n   – الوضعية: ⁦f(x) - x = 1/(x-1)⁩ موجب عند ⁦x > 1⁩ فالمنحنى فوق المقارب، وسالب عند ⁦x < 1⁩\n• تمرين 2: ادرس ⁦f(x) = x³ - 6x² + 9x⁩ واذكر نقطة الانعطاف.\n• الحل:\n   – ⁦f′(x) = 3x² - 12x + 9 = 3(x-1)(x-3)⁩\n   – ⁦f(1) = 4⁩ (عظمى محلية) و ⁦f(3) = 0⁩ (صغرى محلية)\n   – ⁦f″(x) = 6x - 12⁩ تنعدم وتغير الإشارة عند 2 و ⁦f(2) = 2⁩ فالانعطاف ⁦(2 ; 2)⁩\n▸ للحفظ\n• التعريف ← النهايات ← المشتق ← جدول التغيرات ← المقاربات ← الرسم."},{"title":"6. التناظر والمقارب المائل وإثبات المتباينات","content":"▸ مركز تناظر Ω(a ; b)\n• نبين أن ⁦f(2a - x) + f(x) = 2b⁩\n• مع كون ⁦2a - x⁩ في المجال لكل x منه\n▸ محور تناظر x = a\n• نبين أن ⁦f(2a - x) = f(x)⁩\n• مع كون ⁦2a - x⁩ في المجال\n▸ مقارب مائل y = ax + b\n• نبين أن ⁦lim [f(x) - (ax + b)] = 0⁩\n• نحدد وضعية المنحنى من إشارة ⁦f(x) - (ax + b)⁩\n▸ إثبات متباينة f(x) ≥ g(x)\n• نضع ⁦h = f - g⁩\n• ندرس تغيرات h ونبين أن أصغر قيمة موجبة\n• أو ندرس إشارة ⁦h(x)⁩ مباشرة\n▸ أخطاء شائعة\n• نسيان التحقق من أن ⁦2a - x⁩ ينتمي للمجال\n• استعمال متباينة من درس دون برهان\n• نسيان ذكر الاستمرارية والرتابة\n▸ شرح مبسط\n• عندما يطلب منك البرهان على متباينة، حوّلها إلى سؤال عن إشارة دالة جديدة ⁦h = f - g⁩. وبدراسة تغيرات h وإيجاد أصغر قيمة لها ننتهي: إن كانت الأصغر موجبة فالمتباينة صحيحة.\n▸ طرق وقواعد\n• لمركز التناظر احسب ⁦f(2a - x)⁩ بعناية ثم اجمع.\n• للمقارب المائل: أوجد a و b من ⁦f(x)/x⁩ ثم ⁦f(x) - ax⁩.\n• للمتباينة: ⁦h(a) = 0⁩ عند نقطة البداية يعطي h ≥ 0 إذا كانت متزايدة.\n▸ تمارين محلولة\n• تمرين 1: بيّن أن ⁦Ω(1 ; 0)⁩ مركز تناظر لمنحنى ⁦f(x) = x³ - 3x² + 2⁩.\n• الحل:\n   – المجال ⁦ℝ⁩ متناظر بالنسبة إلى 1\n   – ⁦f(2 - x) = (2-x)³ - 3(2-x)² + 2 = -x³ + 3x² - 2⁩\n   – إذن ⁦f(2 - x) + f(x) = 0 = 2×0⁩ فالنقطة ⁦(1 ; 0)⁩ مركز تناظر\n• تمرين 2: بيّن أن المستقيم ⁦x = 2⁩ محور تناظر لمنحنى ⁦f(x) = x² - 4x + 3⁩.\n• الحل:\n   – ⁦f(4 - x) = (4-x)² - 4(4-x) + 3 = x² - 4x + 3 = f(x)⁩\n   – إذن ⁦x = 2⁩ محور تناظر\n• تمرين 3: بيّن أن ⁦√(1 + x) ≤ 1 + x/2⁩ من أجل ⁦x ≥ 0⁩.\n• الحل:\n   – نضع ⁦h(x) = 1 + x/2 - √(1 + x)⁩\n   – ⁦h′(x) = 1/2 - 1/(2√(1+x)) ≥ 0⁩ لأن ⁦√(1+x) ≥ 1⁩\n   – h متزايدة و ⁦h(0) = 0⁩ فـ ⁦h(x) ≥ 0⁩ أي المتباينة\n• تمرين 4: بيّن أن ⁦y = x + 1⁩ مقارب مائل لـ ⁦f(x) = (x² + x + 1)/x⁩ وادرس الوضعية.\n• الحل:\n   – ⁦f(x) = x + 1 + 1/x⁩\n   – ⁦f(x) - (x + 1) = 1/x → 0⁩ عند ⁦±∞⁩\n   – إذا ⁦x > 0⁩ فالفرق موجب (المنحنى فوق المقارب) وإذا ⁦x < 0⁩ فتحته\n▸ للحفظ\n• مركز⁦: f(2a−x)+f(x)=2b⁩. محور⁦: f(2a−x)=f(x)⁩. متباينة: ادرس ⁦h = f − g⁩."},{"title":"7. دالة اللوغاريتم النيبيري ln","content":"▸ التعريف\n• ⁦ln⁩ معرفة على ⁦]0 ; +∞[⁩\n• ⁦(ln x)′ = 1/x⁩ و ⁦ln 1 = 0⁩ و ⁦ln e = 1⁩\n• ⁦ln x = y ⇔ x = eʸ⁩\n▸ الخواص الجبرية\n• ⁦ln(ab) = ln a + ln b⁩\n• ⁦ln(a/b) = ln a - ln b⁩\n• ⁦ln(aⁿ) = n·ln a⁩ و ⁦ln √a = (1/2)ln a⁩\n▸ النهايات\n• ⁦lim ln x = +∞⁩ عند ⁦+∞⁩ و ⁦-∞⁩ عند ⁦0^+⁩\n• ⁦lim ln x/x = 0⁩ عند ⁦+∞⁩\n• ⁦lim x·ln x = 0⁩ عند ⁦0^+⁩\n▸ المتباينات\n• ⁦ln x ≤ x - 1⁩ لكل ⁦x > 0⁩\n• متزايدة تماما: ⁦ln a < ln b ⇔ a < b⁩\n▸ مشتق مركب\n• ⁦(ln u)′ = u′/u⁩ حيث ⁦u > 0⁩\n• ⁦(ln|u|)′ = u′/u⁩ أيضا\n▸ شرح مبسط\n• اللوغاريتم هو الدالة العكسية للأسية: يحول الجداء إلى مجموع. ولهذا يسهل حل المعادلات التي فيها قوى. قاعدة ذهبية: قبل أي حل اكتب مجال التعريف (ما بداخل ln موجب تماما)، وبعد الحل تحقق من المجال.\n▸ طرق وقواعد\n• اكتب مجال التعريف أولا.\n• وحّد الطرفين بصيغة ⁦ln A = ln B⁩ ثم ⁦A = B⁩.\n• لحل المتراجحة نستعمل الرتابة (دون عكس الاتجاه).\n▸ تمارين محلولة\n• تمرين 1: بيّن أن ⁦ln x ≤ x - 1⁩ لكل ⁦x > 0⁩.\n• الحل:\n   – نضع ⁦g(x) = x - 1 - ln x⁩ على ⁦]0 ; +∞[⁩\n   – ⁦g′(x) = 1 - 1/x = (x - 1)/x⁩: سالبة على ⁦]0 ; 1[⁩ وموجبة على ⁦]1 ; +∞[⁩\n   – فـ g تبلغ أصغر قيمة عند 1: ⁦g(1) = 0⁩\n   – إذن ⁦g(x) ≥ 0⁩ أي ⁦ln x ≤ x - 1⁩\n• تمرين 2: حل ⁦ln(x - 1) + ln(x + 1) = ln 3⁩.\n• الحل:\n   – المجال: ⁦x > 1⁩\n   – المعادلة ⁦ln((x-1)(x+1)) = ln 3⁩ أي ⁦x² - 1 = 3⁩ فـ ⁦x = 2⁩ أو ⁦x = -2⁩\n   – نرفض -2 (خارج المجال)\n   – الحل ⁦x = 2⁩\n• تمرين 3: حل ⁦ln(2x - 1) ≤ 1⁩.\n• الحل:\n   – المجال ⁦x > 1/2⁩\n   – ⁦ln(2x - 1) ≤ ln e⁩ فـ ⁦2x - 1 ≤ e⁩ أي ⁦x ≤ (1 + e)/2⁩\n   – الحلول: ⁦1/2 < x ≤ (1 + e)/2⁩\n• تمرين 4: احسب مشتقة ⁦f(x) = ln(x² + 1)⁩.\n• الحل:\n   – ⁦f′(x) = 2x/(x² + 1)⁩\n▸ للحفظ\n• ⁦ln(ab) = ln a + ln b⁩. المجال أولا⁦. (ln u)′ = u′/u. ln x ≤ x − 1⁩."},{"title":"8. الدالة الأسية exp","content":"▸ التعريف\n• ⁦exp⁩ معرفة على ⁦ℝ⁩ وموجبة تماما: ⁦eˣ > 0⁩\n• ⁦(eˣ)′ = eˣ⁩\n• ⁦eˣ = y ⇔ x = ln y⁩ (من أجل ⁦y > 0⁩)\n▸ الخواص الجبرية\n• ⁦eᵃ⁺ᵇ = eᵃ·eᵇ⁩\n• ⁦eᵃ⁻ᵇ = eᵃ/eᵇ⁩\n• ⁦(eᵃ)ⁿ = eⁿᵃ⁩\n▸ النهايات\n• ⁦lim eˣ = +∞⁩ عند ⁦+∞⁩ و ⁦0⁩ عند ⁦-∞⁩\n• ⁦lim eˣ/xⁿ = +∞⁩ عند ⁦+∞⁩\n• ⁦lim xⁿ·e⁻ˣ = 0⁩ عند ⁦+∞⁩\n• ⁦lim (eˣ - 1)/x = 1⁩ عند 0\n▸ المتباينات\n• ⁦eˣ ≥ x + 1⁩ لكل x\n• متزايدة تماما: ⁦eᵃ < eᵇ ⇔ a < b⁩\n▸ مشتق مركب\n• ⁦(eᵘ)′ = u′·eᵘ⁩\n• ⁦(eᵃˣ)′ = a·eᵃˣ⁩\n▸ شرح مبسط\n• الدالة الأسية تنمو بسرعة هائلة: أسرع من أي كثير حدود. وهي دائما موجبة تماما، وهذا مهم جدا في إشارة المشتق: إذا كان في المشتق عامل ⁦eˣ⁩ فإشارته لا تتأثر به.\n▸ طرق وقواعد\n• العامل ⁦eᵘ⁩ لا يؤثر في إشارة المشتق.\n• عند ∞ الأسية تغلب القوى: ناتج نهايات مرجعية.\n• لحل ⁦eˣ = k⁩ نأخذ ⁦ln⁩: ⁦x = ln k⁩ إذا ⁦k > 0⁩.\n▸ تمارين محلولة\n• تمرين 1: بيّن أن ⁦eˣ ≥ x + 1⁩ لكل x.\n• الحل:\n   – نضع ⁦g(x) = eˣ - x - 1⁩\n   – ⁦g′(x) = eˣ - 1⁩: سالبة على ⁦]-∞ ; 0[⁩ وموجبة على ⁦]0 ; +∞[⁩\n   – أصغر قيمة ⁦g(0) = 0⁩ فـ ⁦g ≥ 0⁩\n• تمرين 2: احسب مشتقة ⁦f(x) = x·e⁻ˣ⁩ واستنتج تغيراتها.\n• الحل:\n   – ⁦f′(x) = e⁻ˣ - x·e⁻ˣ = (1 - x)e⁻ˣ⁩\n   – إشارتها إشارة ⁦1 - x⁩: موجبة على ⁦]-∞ ; 1[⁩ وسالبة بعد 1\n   – العظمى ⁦f(1) = 1/e⁩\n   – النهايات: 0 عند ⁦+∞⁩ و ⁦-∞⁩ عند ⁦-∞⁩\n• تمرين 3: حل ⁦eˣ > 2⁩.\n• الحل:\n   – ⁦eˣ > e^(ln 2)⁩ فـ ⁦x > ln 2⁩\n▸ للحفظ\n• ⁦eˣ > 0⁩ دائما⁦. (eᵘ)′ = u′eᵘ. eˣ ≥ x + 1⁩. نهايات⁦: eˣ/xⁿ⁩ → +∞."},{"title":"9. معادلات ومتراجحات ln و exp وتغيير المتغير","content":"▸ معادلة فيها ln\n• اكتب مجال التعريف\n• وحّد الطرفين: ⁦ln A = ln B ⇒ A = B⁩\n• تحقق من أن الحلول ضمن المجال\n▸ معادلة فيها e^x و e^{2x}\n• ضع ⁦t = eˣ⁩ مع ⁦t > 0⁩\n• حل المعادلة في t\n• ثم ⁦x = ln t⁩ (للقيم الموجبة فقط)\n▸ معادلة فيها (ln x)²\n• ضع ⁦t = ln x⁩\n• حل في t ثم ⁦x = eᵗ⁩\n▸ متراجحات\n• نستعمل الرتابة: ln و exp متزايدتان\n• نتخلص من الأسية بـ ln وبالعكس\n• لا نعكس الاتجاه\n▸ أخطاء شائعة\n• نسيان ⁦t > 0⁩ عند وضع ⁦t = eˣ⁩\n• نسيان مجال ln\n• إبقاء الحلول المرفوضة\n▸ شرح مبسط\n• معظم المعادلات هنا معادلات من الدرجة الثانية متنكرة: ضع t بدل ⁦eˣ⁩ أو ⁦ln x⁩ فتصبح عادية. ثم لا تنس أن تعود للمتغير الأصلي وأن تتحقق من الشروط (t موجب).\n▸ طرق وقواعد\n• اكتب المجال أولا ثم حل.\n• بعد الحل في t ارفض القيم غير المقبولة.\n• تحقق بالتعويض في المعادلة الأصلية.\n▸ تمارين محلولة\n• تمرين 1: حل ⁦e²ˣ - 5eˣ + 6 = 0⁩.\n• الحل:\n   – نضع ⁦t = eˣ⁩ (⁦t > 0⁩): ⁦t² - 5t + 6 = 0⁩ أي ⁦(t - 2)(t - 3) = 0⁩ فـ ⁦t = 2⁩ أو ⁦t = 3⁩\n   – إذن ⁦x = ln 2⁩ أو ⁦x = ln 3⁩\n• تمرين 2: حل ⁦(ln x)² - 3 ln x + 2 = 0⁩.\n• الحل:\n   – المجال ⁦x > 0⁩\n   – نضع ⁦t = ln x⁩: ⁦t² - 3t + 2 = 0⁩ فـ ⁦t = 1⁩ أو ⁦t = 2⁩\n   – إذن ⁦x = e⁩ أو ⁦x = e²⁩\n• تمرين 3: حل ⁦eˣ - 2e⁻ˣ = 1⁩.\n• الحل:\n   – نضرب في ⁦eˣ⁩: ⁦t - 2/t = 1⁩ مع ⁦t = eˣ⁩: ⁦t² - t - 2 = 0⁩ فـ ⁦t = 2⁩ أو ⁦t = -1⁩\n   – نرفض -1 (لأن ⁦t > 0⁩)\n   – ⁦x = ln 2⁩\n• تمرين 4: حل ⁦e²ˣ - eˣ - 2 ≥ 0⁩.\n• الحل:\n   – ⁦t = eˣ > 0⁩: ⁦t² - t - 2 ≥ 0⁩ أي ⁦(t - 2)(t + 1) ≥ 0⁩ فـ ⁦t ≥ 2⁩ لأن ⁦t + 1 > 0⁩\n   – إذن ⁦x ≥ ln 2⁩\n▸ للحفظ\n• ضع ⁦t = eˣ (t > 0)⁩ أو ⁦t = ln x⁩، ثم حل، وتحقق من الشروط."},{"title":"10. دراسة دوال تحتوي ln و exp","content":"▸ الخطوات\n• المجال، النهايات، المقاربات\n• المشتق: عامل ⁦eˣ⁩ أو ⁦1/x⁩ موجب غالبا\n• جدول التغيرات واستنتاج المقاربات\n▸ نهايات تستعمل\n• ⁦ln x/x → 0⁩ و ⁦x·ln x → 0^-⁩\n• ⁦eˣ/x → +∞⁩ و ⁦x·e⁻ˣ → 0⁩\n▸ مقاربات\n• ⁦f(x) = x + e⁻ˣ⁩: المقارب المائل ⁦y = x⁩ عند ⁦+∞⁩\n• ⁦ln x⁩ قرب 0: مقارب عمودي ⁦x = 0⁩\n▸ كيف نبرهن؟\n• إشارة المشتق: حلل إلى عوامل\n• عامل ⁦eˣ⁩ موجب دائما\n• عامل ⁦ln x⁩ يتغير إشارته عند 1\n▸ شرح مبسط\n• دراسة هذه الدوال مثل غيرها، لكن النهايات تحتاج النهايات المرجعية. ومشتقاتها غالبا تحتوي عوامل موجبة (مثل ⁦eˣ⁩ أو ⁦1/x⁩) فتصبح إشارة المشتق من إشارة عامل بسيط.\n▸ طرق وقواعد\n• استعمل ⁦ln x/x⁩ و ⁦x ln x⁩ عند الحاجة.\n• حلل المشتق إلى جداء عوامل.\n• لا تنس النهاية عند ⁦0^+⁩ عندما يكون ln حاضرا.\n▸ تمارين محلولة\n• تمرين 1: ادرس ⁦f(x) = ln x / x⁩ على ⁦]0 ; +∞[⁩.\n• الحل:\n   – عند ⁦0^+⁩: ⁦ln x → -∞⁩ و ⁦1/x → +∞⁩ فالنهاية ⁦-∞⁩ والمقارب ⁦x = 0⁩\n   – عند ⁦+∞⁩: 0 والمقارب ⁦y = 0⁩\n   – ⁦f′(x) = (1 - ln x)/x²⁩: موجبة على ⁦]0 ; e[⁩ وسالبة بعدها\n   – القيمة العظمى ⁦f(e) = 1/e⁩\n• تمرين 2: ادرس ⁦f(x) = x - ln x⁩ على ⁦]0 ; +∞[⁩.\n• الحل:\n   – ⁦f′(x) = 1 - 1/x = (x - 1)/x⁩: سالبة قبل 1 وموجبة بعده\n   – الصغرى ⁦f(1) = 1⁩\n   – النهايات: ⁦+∞⁩ عند ⁦0^+⁩ (لأن ⁦-ln x → +∞⁩) وعند ⁦+∞⁩ (لأن ⁦x - ln x = x(1 - ln x/x)⁩)\n• تمرين 3: ادرس ⁦f(x) = x + e⁻ˣ⁩ وبيّن أن ⁦y = x⁩ مقارب مائل عند ⁦+∞⁩.\n• الحل:\n   – ⁦f(x) - x = e⁻ˣ → 0⁩ عند ⁦+∞⁩ فـ ⁦y = x⁩ مقارب مائل والمنحنى فوقه لأن ⁦e⁻ˣ > 0⁩\n   – ⁦f′(x) = 1 - e⁻ˣ⁩ تنعدم عند 0: سالبة قبله وموجبة بعده\n   – الصغرى ⁦f(0) = 1⁩\n▸ للحفظ\n• نهايات مرجعية + مشتق بعوامل موجبة + جدول تغيرات + مقاربات."},{"title":"11. المعادلات التفاضلية y′ = ay + b","content":"▸ y′ = ay\n• الحلول: ⁦y = C·eᵃˣ⁩\n• الشرط الابتدائي يحدد C\n▸ y′ = ay + b (a ≠ 0)\n• الحلول: ⁦y = C·eᵃˣ - b/a⁩\n• الحل الثابت ⁦y = -b/a⁩\n• الشرط الابتدائي يحدد C\n▸ خطوات الحل\n• اكتب المعادلة على الشكل ⁦y′ = ay + b⁩\n• اكتب الحل العام\n• عوّض الشرط الابتدائي لإيجاد C\n• تحقق: اشتق وعوّض\n▸ تطبيقات\n• تبريد جسم: ⁦T′ = -k(T - Tₐ)⁩\n• النشاط الإشعاعي: ⁦N′ = -λN⁩\n• نمو سكاني\n▸ كيف نبرهن أن f حل؟\n• نشتق ⁦f⁩ ونتحقق أن ⁦f′ = af + b⁩\n▸ شرح مبسط\n• معادلة تفاضلية معناها: معدل تغير الدالة يتناسب مع قيمتها. حلها دائما أسية: ⁦Ceᵃˣ⁩، بإضافة ثابت إذا كان هناك الحد b. والثابت C نحدده من القيمة الابتدائية.\n▸ طرق وقواعد\n• حل ⁦y′ = ay + b⁩: ⁦y = Ceᵃˣ - b/a⁩.\n• C من الشرط الابتدائي.\n• اختبر الحل بالتعويض.\n▸ تمارين محلولة\n• تمرين 1: حل ⁦y′ = 2y + 4⁩ مع ⁦y(0) = 1⁩.\n• الحل:\n   – الحل العام ⁦y = Ce²ˣ - 4/2 = Ce²ˣ - 2⁩\n   – الشرط: ⁦y(0) = C - 2 = 1⁩ فـ ⁦C = 3⁩\n   – ⁦y(x) = 3e²ˣ - 2⁩\n   – تحقق: ⁦y′ = 6e²ˣ⁩ و ⁦2y + 4 = 6e²ˣ - 4 + 4 = 6e²ˣ⁩ ✓\n• تمرين 2: حل ⁦y′ + 2y = 6⁩ مع ⁦y(0) = 0⁩.\n• الحل:\n   – نكتب ⁦y′ = -2y + 6⁩ فالحل العام ⁦y = Ce⁻²ˣ + 3⁩\n   – ⁦y(0) = C + 3 = 0⁩ فـ ⁦C = -3⁩\n   – ⁦y(x) = 3 - 3e⁻²ˣ⁩\n• تمرين 3: درجة حرارة فنجان ⁦T′ = -0.1(T - 20)⁩ و ⁦T(0) = 90⁩. أوجد ⁦T(t)⁩.\n• الحل:\n   – ⁦T′ = -0.1T + 2⁩ فالحل ⁦T = Ce^(-0.1t) + 20⁩\n   – ⁦T(0) = C + 20 = 90⁩ فـ ⁦C = 70⁩\n   – ⁦T(t) = 20 + 70e^(-0.1t)⁩ وتؤول إلى 20 (حرارة الغرفة)\n▸ للحفظ\n• ⁦y′ = ay + b ⇒ y = Ceᵃˣ − b/a. C⁩ من الشرط الابتدائي."},{"title":"12. الدوال الأصلية","content":"▸ التعريف\n• F دالة أصلية لـ f على مجال I إذا ⁦F′ = f⁩\n• لكل دالة مستمرة دوال أصلية\n• دالتان أصليتان تختلفان بثابت: ⁦F + C⁩\n▸ جدول الدوال الأصلية\n• ⁦xⁿ → xⁿ⁺¹/(n+1)⁩ و ⁦1/x → ln|x|⁩\n• ⁦eᵃˣ → eᵃˣ/a⁩ و ⁦sin → -cos⁩ و ⁦cos → sin⁩\n• ⁦u′·eᵘ → eᵘ⁩ و ⁦u′/u → ln|u|⁩ و ⁦u′·uⁿ → uⁿ⁺¹/(n+1)⁩\n▸ الشرط الابتدائي\n• الدالة الأصلية التي تحقق ⁦F(a) = b⁩ وحيدة\n• نكتب ⁦F + C⁩ ثم نعين C\n▸ كيف نبرهن؟\n• أن F أصلية لـ f: نشتق F ونجد f\n• نتعرف على الشكل ⁦u′·g(u)⁩\n▸ أخطاء شائعة\n• نسيان الثابت C\n• الخلط بين ⁦xⁿ⁩ و ⁦(ax+b)ⁿ⁩\n• نسيان القسمة على المعامل a\n▸ شرح مبسط\n• إيجاد الدالة الأصلية هو عكس الاشتقاق: لدينا السرعة ونريد المسافة. نتعرف على الشكل: إذا رأيت جداء دالة في مشتق دالة أخرى (مثل ⁦x·e^(x^2)⁩) فهو غالبا من الشكل ⁦u′eᵘ⁩.\n▸ طرق وقواعد\n• اشتق الجواب للتأكد.\n• جرّب أن تتعرف على ⁦u′⁩ داخل العبارة.\n• للشرط الابتدائي استعمل ⁦F(a) = b⁩.\n▸ تمارين محلولة\n• تمرين 1: أوجد الدالة الأصلية لـ ⁦f(x) = 2x + 1⁩ التي تأخذ القيمة 3 عند 0.\n• الحل:\n   – ⁦F(x) = x² + x + C⁩\n   – ⁦F(0) = C = 3⁩ فـ ⁦F(x) = x² + x + 3⁩\n• تمرين 2: أوجد دالة أصلية لـ ⁦f(x) = x·e^(x^2)⁩.\n• الحل:\n   – ⁦f(x) = (1/2)·(2x)·e^(x^2)⁩ من الشكل ⁦(1/2)u′eᵘ⁩ فـ ⁦F(x) = (1/2)e^(x^2)⁩\n• تمرين 3: أوجد دالة أصلية لـ ⁦f(x) = 2x/(x² + 1)⁩.\n• الحل:\n   – من الشكل ⁦u′/u⁩ فـ ⁦F(x) = ln(x² + 1)⁩\n• تمرين 4: بيّن أن ⁦F(x) = x·ln x - x⁩ دالة أصلية لـ ⁦ln x⁩ على ⁦]0 ; +∞[⁩.\n• الحل:\n   – ⁦F′(x) = ln x + x·(1/x) - 1 = ln x⁩\n   – إذن F دالة أصلية\n▸ للحفظ\n• F أصلية لـ ⁦f ⇔ F′ = f⁩. لا تنس ⁦+ C⁩. تعرف على ⁦u′·g(u)⁩."},{"title":"13. التكامل وخواصه والتكامل بالتجزئة","content":"▸ التعريف\n• ⁦∫ₐᵇ f(x)dx = F(b) - F(a)⁩\n• F أي دالة أصلية لـ f\n• يرمز ⁦[F(x)]ₐᵇ⁩ للفرق\n▸ الخواص\n• خطي: ⁦∫(αf + βg) = α∫f + β∫g⁩\n• شال: ⁦∫ₐᵇ + ∫_(b)^(c) = ∫ₐ^(c)⁩\n• ⁦∫ₐᵃ f = 0⁩ و ⁦∫_(b)ᵃ f = -∫ₐᵇ f⁩\n▸ الترتيب\n• ⁦f ≥ 0⁩ على ⁦[a;b]⁩ ⇒ ⁦∫f ≥ 0⁩\n• ⁦f ≤ g⁩ ⇒ ⁦∫f ≤ ∫g⁩\n• ⁦|∫f| ≤ ∫|f|⁩\n▸ التكامل بالتجزئة\n• ⁦∫ₐᵇ u·v′ = [u·v]ₐᵇ - ∫ₐᵇ u′·v⁩\n• نستعملها عند جداء كثير حدود في ⁦eˣ⁩ أو ⁦sin⁩ أو ⁦cos⁩ أو عند ⁦ln⁩\n▸ كيف نختار u و v′؟\n• كثير الحدود هو ⁦u⁩ (يبسط بالاشتقاق)\n• عند ln: ⁦u = ln x⁩ و ⁦v′ = 1⁩\n▸ شرح مبسط\n• التكامل المحدد يعطي عددا يمثل مساحة (موجبة إذا كانت الدالة فوق المحور). نحسبه بالدالة الأصلية: القيمة عند الطرف الأعلى ناقص القيمة عند الأدنى. والتجزئة تحول تكاملا صعبا إلى آخر أبسط.\n▸ طرق وقواعد\n• احسب الدالة الأصلية ثم عوّض الحدين.\n• عند التجزئة اكتب ⁦u⁩ و ⁦v⁩ و ⁦u′⁩ و ⁦v′⁩ في سطر.\n• احسب التكامل الجديد بعد التجزئة.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦∫₀¹ x·eˣ dx⁩.\n• الحل:\n   – ⁦u = x⁩ و ⁦v′ = eˣ⁩ فـ ⁦u′ = 1⁩ و ⁦v = eˣ⁩\n   – ⁦[x·eˣ]₀¹ - ∫₀¹ eˣ dx = e - (e - 1) = 1⁩\n• تمرين 2: احسب ⁦∫₁^(e) ln x dx⁩.\n• الحل:\n   – ⁦u = ln x⁩ و ⁦v′ = 1⁩ فـ ⁦u′ = 1/x⁩ و ⁦v = x⁩\n   – ⁦[x ln x]₁^(e) - ∫₁^(e) 1 dx = e - (e - 1) = 1⁩\n• تمرين 3: احسب ⁦∫₀^(π/2) x·cos x dx⁩.\n• الحل:\n   – ⁦u = x⁩ و ⁦v′ = cos x⁩ فـ ⁦v = sin x⁩\n   – ⁦[x sin x]₀^(π/2) - ∫₀^(π/2) sin x dx = π/2 - 1⁩\n• تمرين 4: احسب ⁦∫₀¹ (3x² + 2x) dx⁩.\n• الحل:\n   – دالة أصلية ⁦x³ + x²⁩\n   – القيمة ⁦(1 + 1) - 0 = 2⁩\n▸ للحفظ\n• ⁦∫f = F(b) − F(a)⁩. التجزئة⁦: ∫uv′ = [uv] − ∫u′v⁩."},{"title":"14. المساحة والحجم والقيمة المتوسطة","content":"▸ المساحة بين منحنى والمحور\n• ⁦A = ∫ₐᵇ |f(x)| dx⁩ (بوحدة المساحة)\n• إن تغيرت إشارة f قسّم التكامل عند الجذور\n▸ بين منحنيين\n• ⁦A = ∫ₐᵇ |f(x) - g(x)| dx⁩\n• ⁦f ≥ g⁩ على المجال: ⁦A = ∫(f - g)⁩\n▸ الحجم الدوراني\n• حول محور الفواصل: ⁦V = π∫ₐᵇ [f(x)]² dx⁩\n• وحدة الحجم\n▸ القيمة المتوسطة\n• ⁦μ = (1/(b - a))·∫ₐᵇ f(x) dx⁩\n• تحقق ⁦m ≤ μ ≤ M⁩ إذا ⁦m ≤ f ≤ M⁩\n▸ وحدة المساحة\n• وحدة المساحة = ⁦‖i‖ × ‖j‖⁩ (بـ cm² أو دج حسب المعلم)\n▸ شرح مبسط\n• نحسب المساحة بتكامل الدالة، لكن نأخذ القيمة المطلقة إذا كان المنحنى تحت المحور. والحجم الدوراني: نتخيل شرائح دائرية رقيقة مساحة كل منها ⁦π f(x)²⁩ ونجمعها.\n▸ طرق وقواعد\n• حدد أي دالة فوق الأخرى قبل حساب الفرق.\n• أوجد حدود التكامل من تقاطع المنحنيين أو من المعطيات.\n• اذكر الوحدة في الجواب.\n▸ تمارين محلولة\n• تمرين 1: احسب مساحة الحيز المحصور بين ⁦y = x⁩ و ⁦y = x²⁩ بين ⁦x = 0⁩ و ⁦x = 1⁩.\n• الحل:\n   – على ⁦[0 ; 1]⁩ لدينا ⁦x ≥ x²⁩\n   – المساحة ⁦∫₀¹(x - x²)dx = [x²/2 - x³/3]₀¹ = 1/2 - 1/3 = 1/6⁩ وحدة مساحة\n• تمرين 2: احسب حجم المجسم الناتج عن دوران منحنى ⁦f(x) = √x⁩ حول محور الفواصل بين 0 و 4.\n• الحل:\n   – ⁦V = π∫₀⁴ (√x)² dx = π∫₀⁴ x dx = π[x²/2]₀⁴ = 8π⁩ وحدة حجم\n• تمرين 3: احسب القيمة المتوسطة لـ ⁦f(x) = x²⁩ على ⁦[0 ; 3]⁩.\n• الحل:\n   – ⁦μ = (1/3)∫₀³ x² dx = (1/3)×9 = 3⁩\n• تمرين 4: احسب مساحة الحيز تحت ⁦y = eˣ⁩ بين 0 و ⁦ln 2⁩.\n• الحل:\n   – ⁦∫₀^(ln 2) eˣ dx = e^(ln 2) - 1 = 2 - 1 = 1⁩ وحدة مساحة\n▸ للحفظ\n• ⁦A = ∫|f|⁩. بين منحنيين⁦: ∫(f − g)⁩. الحجم ⁦= π∫f²⁩. المتوسطة ⁦= ∫f/(b−a)⁩."},{"title":"15. رتابة وتقارب متتالية","content":"▸ الرتابة\n• ندرس إشارة ⁦uₙ₊₁ - uₙ⁩\n• أو نقارن ⁦uₙ₊₁/uₙ⁩ بـ 1 (حدود موجبة)\n• أو نستعمل الاستدلال بالتراجع\n▸ مبرهنات التقارب\n• كل متتالية متزايدة ومحدودة من الأعلى متقاربة\n• كل متتالية متناقصة ومحدودة من الأسفل متقاربة\n• متتالية متزايدة غير محدودة من الأعلى تؤول إلى ⁦+∞⁩\n▸ المتتالية الهندسية\n• ⁦qⁿ → 0⁩ إذا ⁦|q| < 1⁩\n• ⁦qⁿ → +∞⁩ إذا ⁦q > 1⁩\n• لا نهاية إذا ⁦q ≤ -1⁩\n▸ الحصر والمقارنة\n• ⁦|uₙ| ≤ vₙ⁩ و ⁦vₙ → 0⁩ ⇒ ⁦uₙ → 0⁩\n• ⁦uₙ ≥ vₙ⁩ و ⁦vₙ → +∞⁩ ⇒ ⁦uₙ → +∞⁩\n▸ كيف نبرهن التقارب؟\n• 1) محدودة (بالتراجع)\n• 2) رتيبة\n• 3) إذن متقاربة\n• 4) نحسب النهاية من ⁦f(ℓ) = ℓ⁩\n▸ شرح مبسط\n• إذا كنت تصعد سلما ولا يمكنك تجاوز سقف معين فستتوقف عند عدد ما: هذه فكرة المتتالية المتزايدة المحدودة من الأعلى. لا نعرف قيمة النهاية من المبرهنة، لكن نعرف أنها موجودة، ثم نحسبها من العلاقة التراجعية.\n▸ طرق وقواعد\n• اكتب الحد الأعلى بوضوح (مثلا ⁦uₙ < 2⁩).\n• أثبت الحد بالتراجع.\n• النهاية ℓ تحقق ⁦ℓ = f(ℓ)⁩: احسب ℓ ثم اختر القيمة المناسبة.\n▸ تمارين محلولة\n• تمرين 1: ⁦u₀ = 1⁩ و ⁦uₙ₊₁ = √(2 + uₙ)⁩. بيّن أنها متقاربة واحسب نهايتها.\n• الحل:\n   – (1) بالتراجع ⁦0 < uₙ < 2⁩: ⁦u₀ = 1⁩ ✓\n   – إذا ⁦0 < uₙ < 2⁩ فـ ⁦2 < 2 + uₙ < 4⁩ فـ ⁦0 < uₙ₊₁ < 2⁩ ✓\n   – (2) الرتابة: ⁦uₙ₊₁² - uₙ² = 2 + uₙ - uₙ² = (2 - uₙ)(1 + uₙ) > 0⁩ فهي متزايدة\n   – (3) متزايدة ومحدودة من الأعلى بـ 2 فهي متقاربة نحو ℓ\n   – ⁦ℓ = √(2 + ℓ)⁩ فـ ⁦ℓ² - ℓ - 2 = 0⁩ أي ⁦ℓ = 2⁩ أو ⁦ℓ = -1⁩\n   – نرفض -1 لأن ⁦ℓ ≥ 0⁩\n   – إذن ⁦lim uₙ = 2⁩\n• تمرين 2: بيّن أن ⁦uₙ = (2n + 1)/(n + 2)⁩ متقاربة.\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = (2n+3)/(n+3) - (2n+1)/(n+2) = 3/((n+2)(n+3)) > 0⁩ فهي متزايدة\n   – و ⁦uₙ < 2⁩ لأن ⁦2n + 1 < 2n + 4⁩\n   – متزايدة ومحدودة من الأعلى فهي متقاربة، ونهايتها 2\n• تمرين 3: ⁦uₙ = (-1)ⁿ / n⁩. احسب نهايتها.\n• الحل:\n   – ⁦|uₙ| = 1/n⁩ فـ ⁦-1/n ≤ uₙ ≤ 1/n⁩ والطرفان يؤولان إلى 0، فحسب الحصر ⁦lim uₙ = 0⁩\n▸ للحفظ\n• متزايدة + محدودة من الأعلى ⇒ متقاربة. ثم النهاية من ⁦f(ℓ) = ℓ⁩."},{"title":"16. المتتاليتان المتجاورتان","content":"▸ التعريف\n• ⁦(uₙ)⁩ متزايدة و ⁦(vₙ)⁩ متناقصة\n• ⁦vₙ - uₙ → 0⁩\n• فهما متجاورتان\n▸ المبرهنة\n• كل متتاليتين متجاورتين متقاربتان\n• ولهما النهاية نفسها ⁦ℓ⁩\n• ⁦uₙ ≤ ℓ ≤ vₙ⁩ لكل n\n▸ كيف نبرهن؟\n• 1) رتابة ⁦uₙ⁩ (فرق موجب)\n• 2) رتابة ⁦vₙ⁩ (فرق سالب)\n• 3) ⁦lim (vₙ - uₙ) = 0⁩\n• 4) إذن متجاورتان\n▸ تطبيق\n• حصر النهاية: ⁦uₙ ≤ ℓ ≤ vₙ⁩\n• التقريب العددي لعدد ما\n▸ شرح مبسط\n• تخيل شخصين يقتربان من بعضهما من طرفين مختلفين: أحدهما يصعد والآخر ينزل والمسافة بينهما تؤول إلى 0. لا بد أنهما يلتقيان عند نقطة واحدة. هذه النقطة هي النهاية المشتركة.\n▸ طرق وقواعد\n• ادرس رتابة كل متتالية على حدة.\n• احسب ⁦vₙ - uₙ⁩ ثم نهايتها.\n• اختم بذكر المبرهنة.\n▸ تمارين محلولة\n• تمرين 1: بيّن أن ⁦uₙ = 1 - 1/n⁩ و ⁦vₙ = 1 + 1/n⁩ (⁦n ≥ 1⁩) متجاورتان.\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = 1/n - 1/(n+1) > 0⁩ فـ ⁦uₙ⁩ متزايدة\n   – ⁦vₙ₊₁ - vₙ = 1/(n+1) - 1/n < 0⁩ فـ ⁦vₙ⁩ متناقصة\n   – ⁦vₙ - uₙ = 2/n → 0⁩\n   – إذن متجاورتان ونهايتهما المشتركة 1\n• تمرين 2: ⁦uₙ = 1 - 1/(n+1)⁩ و ⁦vₙ = 1 + 1/(n+1)⁩. هل هما متجاورتان؟\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = 1/(n+1) - 1/(n+2) > 0⁩ متزايدة\n   – ⁦vₙ⁩ متناقصة بالمثل\n   – ⁦vₙ - uₙ = 2/(n+1) → 0⁩\n   – نعم متجاورتان ونهايتهما 1\n▸ للحفظ\n• متجاورتان: واحدة متزايدة وأخرى متناقصة وفرقهما يؤول إلى ⁦0 ⇒⁩ لهما نفس النهاية."},{"title":"17. المتتالية u_{n+1} = f(u_n) والحسابية الهندسية","content":"▸ u_{n+1} = a·u_n + b\n• ⁦ℓ = b/(1 - a)⁩ (النقطة الثابتة)\n• ⁦vₙ = uₙ - ℓ⁩ هندسية أساسها a\n• ⁦uₙ = ℓ + (u₀ - ℓ)·aⁿ⁩\n▸ u_{n+1} = f(u_n)\n• إذا تقاربت نحو ℓ و f مستمرة فإن ⁦f(ℓ) = ℓ⁩\n• إذا كانت f متزايدة و ⁦u₁ ≥ u₀⁩ فالمتتالية متزايدة (بالتراجع)\n• إذا كانت f متناقصة فالمتتاليتان الزوجية والفردية رتيبتان باتجاهين متعاكسين\n▸ التمثيل البياني\n• نرسم ⁦y = f(x)⁩ و ⁦y = x⁩\n• نرسم \"الدرج\" لتخمين الرتابة والنهاية\n▸ نتيجة النهاية\n• ⁦|a| < 1⁩: ⁦uₙ → ℓ⁩\n• ⁦a > 1⁩: لا تتقارب غالبا (تؤول إلى ∞ إذا ⁦u₀ > ℓ⁩)\n▸ شرح مبسط\n• المتتالية الحسابية-الهندسية تخلط بين الجمع والضرب، لكن إزاحتها بالنقطة الثابتة ℓ تحولها إلى هندسية صافية. أما ⁦uₙ₊₁ = f(uₙ)⁩ العامة فنقرأ رتابتها من رسم الدرج ثم نبرهنها بالتراجع.\n▸ طرق وقواعد\n• احسب ℓ من المعادلة ⁦ℓ = aℓ + b⁩.\n• ضع ⁦vₙ = uₙ - ℓ⁩ وبيّن أنها هندسية.\n• عد إلى ⁦uₙ = vₙ + ℓ⁩.\n▸ تمارين محلولة\n• تمرين 1: ⁦u₀ = 0⁩ و ⁦uₙ₊₁ = (1/2)uₙ + 1⁩. أوجد ⁦uₙ⁩ ونهايتها.\n• الحل:\n   – ⁦ℓ = ℓ/2 + 1⁩ فـ ⁦ℓ = 2⁩\n   – ⁦vₙ = uₙ - 2⁩ هندسية أساسها 1/2 وحدها الأول ⁦v₀ = -2⁩\n   – ⁦vₙ = -2(1/2)ⁿ⁩ و ⁦uₙ = 2 - 2(1/2)ⁿ → 2⁩\n• تمرين 2: ⁦u₀ = 3⁩ و ⁦uₙ₊₁ = 3uₙ - 4⁩. أوجد ⁦uₙ⁩ وادرس تقاربها.\n• الحل:\n   – ⁦ℓ = 3ℓ - 4⁩ فـ ⁦ℓ = 2⁩\n   – ⁦vₙ = uₙ - 2⁩ هندسية أساسها 3 و ⁦v₀ = 1⁩\n   – ⁦vₙ = 3ⁿ⁩ و ⁦uₙ = 2 + 3ⁿ → +∞⁩\n   – لا تتقارب\n• تمرين 3: ⁦f(x) = √(2x + 3)⁩ و ⁦u₀ = 0⁩, ⁦uₙ₊₁ = f(uₙ)⁩. بيّن أن ⁦0 ≤ uₙ ≤ 3⁩.\n• الحل:\n   – بالتراجع: ⁦u₀ = 0⁩ ✓\n   – إذا ⁦0 ≤ uₙ ≤ 3⁩ فـ ⁦3 ≤ 2uₙ + 3 ≤ 9⁩ فـ ⁦√3 ≤ uₙ₊₁ ≤ 3⁩ فهي محصورة بين 0 و 3 ✓\n▸ للحفظ\n• نقطة ثابتة ⁦ℓ = f(ℓ). vₙ = uₙ − ℓ⁩ هندسية⁦. f⁩ متزايدة و ⁦u₁ ≥ u₀ ⇒⁩ متزايدة."},{"title":"18. الاستدلال بالتراجع (قوالب)","content":"▸ القالب الأساسي\n• التحقق: ⁦P(n₀)⁩ صحيحة\n• الوراثة: ⁦P(n) ⇒ P(n+1)⁩\n• الاستنتاج: ⁦P(n)⁩ صحيحة لكل ⁦n ≥ n₀⁩\n▸ أنواع الخواص\n• مجموع: ⁦1 + 2 + ... + n = n(n+1)/2⁩\n• متباينة: ⁦2ⁿ ≥ n + 1⁩\n• قابلية قسمة: ⁦7 | 2³ⁿ - 1⁩\n• صيغة متتالية: ⁦uₙ = ...⁩\n▸ حيل الوراثة\n• في المتباينة: اضرب في عدد موجب ثم قارن\n• في القسمة: اكتب ⁦aⁿ⁺¹ - 1 = a(aⁿ - 1) + (a - 1)⁩\n• في المجموع: أضف الحد الأخير\n▸ أخطاء شائعة\n• نسيان التحقق\n• عدم استعمال فرض التراجع\n• نسيان جملة الاستنتاج\n▸ شرح مبسط\n• الاستدلال بالتراجع يشبه سلم: نتأكد أننا نقف على الدرجة الأولى، ثم نبيّن أنه من كل درجة نستطيع الصعود للتالية. فنصل إلى أي درجة نريد.\n▸ طرق وقواعد\n• اكتب ⁦P(n)⁩ و ⁦P(n+1)⁩ أولا.\n• ابدأ الوراثة بطرف ⁦P(n+1)⁩ المعقد.\n• ضع إطارا لجملة الاستنتاج.\n▸ تمارين محلولة\n• تمرين 1: برهن أن ⁦1 + 2 + ... + n = n(n + 1)/2⁩ لكل ⁦n ≥ 1⁩.\n• الحل:\n   – التحقق: ⁦n = 1⁩: ⁦1 = 1×2/2⁩ ✓\n   – الوراثة: `1 + .\n   – + n + (n+1) = n(n+1)/2 + (n+1) = (n+1)(n+2)/2`\n   – الاستنتاج: صحيحة لكل ⁦n ≥ 1⁩\n• تمرين 2: برهن أن ⁦3ⁿ ≥ 2n + 1⁩ لكل n.\n• الحل:\n   – التحقق: ⁦n = 0⁩: ⁦1 ≥ 1⁩ ✓\n   – الوراثة: ⁦3ⁿ⁺¹ = 3·3ⁿ ≥ 3(2n + 1) = 6n + 3 ≥ 2n + 3 = 2(n+1) + 1⁩ لأن ⁦4n ≥ 0⁩\n   – الاستنتاج صحيح\n• تمرين 3: برهن أن ⁦7⁩ يقسم ⁦2³ⁿ - 1⁩.\n• الحل:\n   – التحقق: ⁦n = 0⁩: ⁦0⁩ ✓\n   – الوراثة: ⁦2^(3(n+1)) - 1 = 8·2³ⁿ - 1 = 8(2³ⁿ - 1) + 7⁩\n   – وهو مضاعف للعدد 7 بفرض التراجع\n• تمرين 4: برهن (برنولي) ⁦(1 + a)ⁿ ≥ 1 + na⁩ من أجل ⁦a ≥ -1⁩.\n• الحل:\n   – التحقق: ⁦n = 0⁩ ✓\n   – الوراثة: ⁦(1+a)ⁿ⁺¹ = (1+a)(1+a)ⁿ ≥ (1+a)(1+na) = 1 + (n+1)a + na² ≥ 1 + (n+1)a⁩ لأن ⁦1 + a ≥ 0⁩ و ⁦na² ≥ 0⁩\n▸ للحفظ\n• تحقق + وراثة + استنتاج. استعمل فرض التراجع ضمن الوراثة."},{"title":"19. الأعداد المركبة: الشكل الجبري والمرافق والطويلة","content":"▸ الشكل الجبري\n• ⁦z = a + ib⁩ مع ⁦i² = -1⁩\n• الجزء الحقيقي a والتخيلي b\n• ⁦z⁩ حقيقي ⇔ ⁦b = 0⁩ و تخيلي صرف ⇔ ⁦a = 0⁩\n▸ المرافق\n• ⁦z̄ = a - ib⁩\n• ⁦z + z̄ = 2a⁩ و ⁦z - z̄ = 2ib⁩\n• ⁦مرافق الجداء = جداء المرافقين⁩\n▸ الطويلة\n• ⁦|z| = √(a² + b²)⁩\n• ⁦z·z̄ = |z|²⁩\n• ⁦|z1 z2| = |z1||z2|⁩ و ⁦|z1/z2| = |z1|/|z2|⁩\n▸ القسمة\n• نضرب البسط والمقام في مرافق المقام\n• ⁦1/z = z̄/|z|²⁩\n▸ كيف نبرهن؟\n• z حقيقي: ⁦z = z̄⁩\n• z تخيلي صرف: ⁦z = -z̄⁩\n• حل معادلة: نضع ⁦z = x + iy⁩ ونطابق\n▸ شرح مبسط\n• العدد المركب نقطة في المستوي: فاصلتها جزؤه الحقيقي وترتيبها جزؤه التخيلي. المرافق هو نظير النقطة بالنسبة لمحور الفواصل، والطويلة هي المسافة إلى المبدأ. قاعدة ذهبية للقسمة: اضرب في مرافق المقام فيصبح المقام حقيقيا.\n▸ طرق وقواعد\n• للقسمة: اضرب في مرافق المقام.\n• لمعادلة فيها z و z̄: ضع ⁦z = x + iy⁩.\n• ⁦i² = -1⁩ و ⁦i³ = -i⁩ و ⁦i⁴ = 1⁩.\n▸ تمارين محلولة\n• تمرين 1: اكتب ⁦(3 + 2i)/(1 - i)⁩ على الشكل الجبري.\n• الحل:\n   – نضرب في ⁦1 + i⁩: ⁦(3 + 2i)(1 + i)/2 = (3 + 3i + 2i - 2)/2 = (1 + 5i)/2⁩\n• تمرين 2: حل ⁦z + 2z̄ = 3 + i⁩.\n• الحل:\n   – نضع ⁦z = a + ib⁩: ⁦a + ib + 2a - 2ib = 3a - ib = 3 + i⁩ فـ ⁦a = 1⁩ و ⁦b = -1⁩\n   – ⁦z = 1 - i⁩\n• تمرين 3: بيّن أن ⁦(1 + i)/(1 - i) = i⁩.\n• الحل:\n   – ⁦(1 + i)²/((1 - i)(1 + i)) = 2i/2 = i⁩\n▸ للحفظ\n• ⁦z·z⁩̄ ⁦= |z|²⁩. القسمة: اضرب في مرافق المقام. حقيقي⁦: z = z⁩̄. تخيلي صرف⁦: z = −z⁩̄."},{"title":"20. الشكل المثلثي والأسي ودي موافر وأويلر","content":"▸ الشكل المثلثي\n• ⁦z = r(cos θ + i sin θ)⁩\n• ⁦r = |z|⁩ و ⁦θ = arg z⁩ (بترديد ⁦2π⁩)\n▸ الشكل الأسي\n• ⁦z = r·eⁱᶿ⁩\n• ⁦eⁱᶿ = cos θ + i sin θ⁩\n• ⁦|eⁱᶿ| = 1⁩\n▸ الخواص\n• ⁦arg(z1 z2) = arg z1 + arg z2⁩\n• ⁦arg(z1/z2) = arg z1 - arg z2⁩\n• ⁦arg(zⁿ) = n·arg z⁩\n▸ دي موافر وأويلر\n• ⁦(cos θ + i sin θ)ⁿ = cos nθ + i sin nθ⁩\n• ⁦cos θ = (eⁱᶿ + e⁻ⁱᶿ)/2⁩\n• ⁦sin θ = (eⁱᶿ - e⁻ⁱᶿ)/(2i)⁩\n▸ كيف نجد θ؟\n• ⁦cos θ = a/r⁩ و ⁦sin θ = b/r⁩\n• اختر الزاوية المناسبة للربع\n▸ شرح مبسط\n• الشكل الأسي يحول ضرب الأعداد المركبة إلى جمع زواياها وضرب طويلاتها. لذلك يسهل حساب القوى الكبيرة: نرفع الطويلة للقوة ونضرب الزاوية في القوة.\n▸ طرق وقواعد\n• اكتب ⁦z = r eⁱᶿ⁩ أولا.\n• القوى: ⁦zⁿ = rⁿ eⁱⁿᶿ⁩.\n• رتّب الزاوية إلى ⁦]-π ; π]⁩ للوضوح.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦(1 + i)⁸⁩.\n• الحل:\n   – ⁦|1 + i| = √2⁩ و ⁦arg = π/4⁩ فـ ⁦1 + i = √2 e^(iπ/4)⁩\n   – ⁦(1 + i)⁸ = (√2)⁸ e^(i2π) = 16×1 = 16⁩\n• تمرين 2: اكتب ⁦1 + i√3⁩ على الشكل الأسي واحسب ⁦(1 + i√3)⁶⁩.\n• الحل:\n   – ⁦r = 2⁩ و ⁦cos θ = 1/2⁩ و ⁦sin θ = √3/2⁩ فـ ⁦θ = π/3⁩ أي ⁦2e^(iπ/3)⁩\n   – ⁦(1 + i√3)⁶ = 2⁶ e^(i2π) = 64⁩\n• تمرين 3: احسب ⁦(-1 + i)¹²⁩.\n• الحل:\n   – ⁦|-1 + i| = √2⁩ و ⁦arg = 3π/4⁩\n   – ⁦(√2)¹² e^(i·9π) = 64×e^(iπ) = -64⁩\n• تمرين 4: اكتب ⁦cos² θ⁩ بدلالة ⁦cos 2θ⁩.\n• الحل:\n   – ⁦cos² θ = ((eⁱᶿ + e⁻ⁱᶿ)/2)² = (e²ⁱᶿ + 2 + e⁻²ⁱᶿ)/4 = (1 + cos 2θ)/2⁩\n▸ للحفظ\n• ⁦z = r eⁱᶿ. zⁿ = rⁿ eⁱⁿᶿ. arg(z1z2) = arg z1 + arg z2⁩."},{"title":"21. المعادلات في ℂ","content":"▸ الدرجة الثانية\n• ⁦az² + bz + c = 0⁩ و ⁦Δ = b² - 4ac⁩\n• ⁦Δ > 0⁩: حلان حقيقيان\n• ⁦Δ = 0⁩: حل مضاعف\n• ⁦Δ < 0⁩: حلان مترافقان ⁦z = (-b ± i√|Δ|)/(2a)⁩\n▸ كثيرات حدود\n• إذا كان ⁦z₀⁩ جذرا فـ ⁦P(z) = (z - z₀)Q(z)⁩\n• نبحث عن جذر بسيط (1 أو -1 أو i)\n▸ جذور الوحدة\n• ⁦zⁿ = 1⁩ ⇒ ⁦z = e^(2ikπ/n)⁩\n• ⁦z² = 1⁩: ±1 و ⁦z⁴ = 1⁩: ±1, ±i\n▸ معادلة بالمرافق\n• نضع ⁦z = x + iy⁩ ونطابق الجزءين\n▸ أخطاء شائعة\n• ⁦√(-16) = 4i⁩ وليس ⁦-4⁩\n• نسيان الحل المرافق\n▸ شرح مبسط\n• في ℂ كل معادلة من الدرجة الثانية لها حلان دائما. إذا كان المميز سالبا نكتب ⁦Δ = (i√|Δ|)²⁩ فنحصل على حلين مترافقين.\n▸ طرق وقواعد\n• احسب Δ أولا ثم صنف الحالة.\n• للمقارنة: الحلان المترافقان ⁦z⁩ و ⁦z̄⁩.\n• تحقق بالتعويض.\n▸ تمارين محلولة\n• تمرين 1: حل في ℂ: ⁦z² - 2z + 5 = 0⁩.\n• الحل:\n   – ⁦Δ = 4 - 20 = -16 = (4i)²⁩\n   – ⁦z = (2 ± 4i)/2 = 1 ± 2i⁩\n• تمرين 2: حل ⁦z² + z + 1 = 0⁩.\n• الحل:\n   – ⁦Δ = -3 = (i√3)²⁩\n   – ⁦z = (-1 ± i√3)/2 = e^(±2iπ/3)⁩\n• تمرين 3: حل ⁦z³ = 1⁩.\n• الحل:\n   – ⁦z³ - 1 = (z - 1)(z² + z + 1) = 0⁩\n   – الحلول: 1 و ⁦(-1 ± i√3)/2⁩\n▸ للحفظ\n• ⁦Δ < 0 ⇒ z = (−b ± i√|Δ|)/(2a)⁩. الجذر البسيط يخفض الدرجة."},{"title":"22. الأعداد المركبة والهندسة","content":"▸ المسافة والزاوية\n• ⁦AB = |z_(B) - z_(A)|⁩\n• ⁦(AB→ , AC→) = arg((z_(C) - z_(A))/(z_(B) - z_(A)))⁩\n▸ استقامية وتعامد\n• A و B و C على استقامة واحدة ⇔ ⁦(z_(C) - z_(A))/(z_(B) - z_(A))⁩ حقيقي\n• ⁦AB ⊥ AC⁩ ⇔ الحاصل تخيلي صرف\n▸ طبيعة مثلث\n• الحاصل ⁦±i⁩: قائم ومتساوي الساقين في A\n• الحاصل ⁦e^(±iπ/3)⁩: متقايس الأضلاع\n▸ مجموعات نقط\n• ⁦|z - ω| = R⁩: دائرة\n• ⁦|z - a| = |z - b|⁩: محور القطعة\n• نكتب ⁦z = x + iy⁩ ونستخرج معادلة\n▸ شرح مبسط\n• اللغة المركبة تترجم الهندسة إلى جبر. المسافة هي طويلة الفرق، والزاوية هي عمدة حاصل قسمة. وإذا كان حاصل القسمة ⁦(z_(C) - z_(A))/(z_(B) - z_(A))⁩ حقيقيا فالنقط على استقامة، وإذا كان تخيليا صرفا فالمستقيمان متعامدان.\n▸ طرق وقواعد\n• احسب ⁦(z_(C) - z_(A))/(z_(B) - z_(A))⁩ ثم حلله.\n• لمجموعة النقط: ⁦z = x + iy⁩ ثم ربّع الطويلة.\n▸ تمارين محلولة\n• تمرين 1: ⁦A(1)⁩, ⁦B(2 + i)⁩, ⁦C(i)⁩. ما طبيعة المثلث ABC؟\n• الحل:\n   – ⁦(z_(C) - z_(A))/(z_(B) - z_(A)) = (i - 1)/(1 + i) = (i - 1)(1 - i)/2 = 2i/2 = i⁩\n   – فالطويلة 1 أي ⁦AC = AB⁩ والعمدة ⁦π/2⁩ أي ⁦AB ⊥ AC⁩\n   – المثلث قائم ومتساوي الساقين في A\n• تمرين 2: عيّن مجموعة النقط M(z) التي تحقق ⁦|z - 1| = |z + i|⁩.\n• الحل:\n   – ⁦(x - 1)² + y² = x² + (y + 1)²⁩ فـ ⁦-2x + 1 = 2y + 1⁩ أي ⁦y = -x⁩\n   – هي محور القطعة بين ⁦A(1)⁩ و ⁦B(-i)⁩: المستقيم ⁦y = -x⁩\n• تمرين 3: ⁦A(0)⁩, ⁦B(2)⁩, ⁦C(1 + i√3)⁩. بيّن أن ABC متقايس الأضلاع.\n• الحل:\n   – ⁦(z_(C) - z_(A))/(z_(B) - z_(A)) = (1 + i√3)/2 = e^(iπ/3)⁩ فالطويلة 1 والعمدة ⁦π/3⁩\n   – إذن ⁦AC = AB⁩ والزاوية ⁦60°⁩، فالمثلث متقايس الأضلاع\n• تمرين 4: عيّن مجموعة النقط التي تحقق ⁦|z - 2i| = 3⁩.\n• الحل:\n   – دائرة مركزها ⁦Ω(0 ; 2)⁩ ونصف قطرها 3\n▸ للحفظ\n• ⁦(z_(C)−z_(A))/(z_(B)−z_(A))⁩: حقيقي ⇒ استقامية، تخيلي صرف ⇒ تعامد، ⁦e^(iπ/3) ⇒⁩ متقايس الأضلاع."},{"title":"23. التحويلات النقطية في المستوي المركب","content":"▸ الانسحاب\n• ⁦z′ = z + b⁩\n• شعاعه ⁦b⁩\n▸ التحاكي\n• ⁦z′ - ω = k(z - ω)⁩ مركزه ⁦Ω(ω)⁩ ونسبته ⁦k⁩\n• ⁦z′ = kz + (1-k)ω⁩\n▸ الدوران\n• ⁦z′ - ω = eⁱᶿ(z - ω)⁩ مركزه ⁦Ω(ω)⁩ وزاويته ⁦θ⁩\n▸ التشابه المباشر\n• ⁦z′ = az + b⁩ مع ⁦a ≠ 0, 1⁩\n• النسبة ⁦|a|⁩ والزاوية ⁦arg a⁩\n• المركز ⁦ω = b/(1 - a)⁩\n▸ كيف نبرهن؟\n• نكتب العبارة المركبة من تعريف التحويل\n• نعوض z لإيجاد الصورة\n▸ شرح مبسط\n• كل تحويل نقطي يُكتب بعبارة مركبة بسيطة. الدوران ضرب في عدد طويلته 1، والتحاكي ضرب في عدد حقيقي، والتشابه المباشر ضرب في عدد مركب أي تحاك مع دوران.\n▸ طرق وقواعد\n• حدد المركز من الثابت ⁦ω = b/(1 - a)⁩.\n• ⁦|a|⁩ هي النسبة و ⁦arg a⁩ هي الزاوية.\n▸ تمارين محلولة\n• تمرين 1: اكتب العبارة المركبة للدوران الذي مركزه ⁦ω = 1⁩ وزاويته ⁦π/2⁩ ثم أوجد صورة ⁦M(3 + i)⁩.\n• الحل:\n   – ⁦z′ - 1 = i(z - 1)⁩ أي ⁦z′ = i(z - 1) + 1⁩\n   – من أجل ⁦z = 3 + i⁩: ⁦z′ = i(2 + i) + 1 = 2i - 1 + 1 = 2i⁩\n   – الصورة ⁦M′(2i)⁩\n• تمرين 2: حدد عناصر التشابه ⁦z′ = (1 + i)z + 2⁩.\n• الحل:\n   – النسبة ⁦|1 + i| = √2⁩ والزاوية ⁦π/4⁩\n   – المركز ⁦ω = 2/(1 - (1 + i)) = 2/(-i) = 2i⁩\n   – تحقق: ⁦(1 + i)(2i) + 2 = 2i - 2 + 2 = 2i⁩ ✓\n• تمرين 3: اكتب العبارة المركبة للتحاكي الذي مركزه ⁦1 + i⁩ ونسبته 2 وأوجد صورة النقطة 3.\n• الحل:\n   – ⁦z′ - (1 + i) = 2(z - (1 + i))⁩ فـ ⁦z′ = 2z - 1 - i⁩\n   – من أجل ⁦z = 3⁩: ⁦z′ = 5 - i⁩\n▸ للحفظ\n• دوران⁦: z′−⁩ω ⁦= eⁱᶿ(z−⁩ω). تحاك⁦: z′−⁩ω ⁦= k(z−⁩ω). تشابه⁦: z′ = az+b⁩، ω ⁦= b/(1−a)⁩."},{"title":"24. القسمة الإقليدية والموافقات (توسع)","content":"▸ القسمة الإقليدية\n• ⁦a = bq + r⁩ مع ⁦0 ≤ r < b⁩\n• الزوج ⁦(q ; r)⁩ وحيد\n▸ الموافقات\n• ⁦a ≡ b [n]⁩ ⇔ ⁦n | (a - b)⁩\n• تتوافق مع الجمع والضرب والقوى\n• لا تُقسَم الموافقات دون شرط\n▸ باقي قوة\n• نبحث عن الدور: أول قوة تساوي 1\n• نكتب الأس ⁦= q×(الدور) + r⁩\n• ⁦a^(kq + r) ≡ a^(r) [n]⁩\n▸ قابلية القسمة\n• ندرس البواقي الممكنة في جدول\n• نستعمل ⁦a ≡ ±1⁩ لتبسيط القوى\n▸ كيف نبرهن؟\n• \"ندرس البواقي الممكنة بترديد m: ...\"\n• \"في كل الحالات ⁦A ≡ 0 [m]⁩ إذن m يقسم A\"\n▸ شرح مبسط\n• الموافقة تسمح لنا بالعمل مع البواقي فقط بدل الأعداد الضخمة. فبدل حساب ⁦3²⁰²⁵⁩ نبحث عن دورة بواقي قوى 3: بعد 4 قوى تعود إلى 1، فيكفي أن نعرف الباقي عند قسمة 2025 على 4.\n▸ طرق وقواعد\n• ابحث عن الدور (أول قوة ≡ 1).\n• عند البرهان على القابلية ادرس كل الحالات.\n• ⁦a ≡ -1 [n]⁩ يفيد في القوى الفردية.\n▸ تمارين محلولة\n• تمرين 1: ما باقي قسمة ⁦3²⁰²⁵⁩ على 10؟\n• الحل:\n   – قوى 3 بترديد 10: ⁦3¹ ≡ 3⁩ ، ⁦3² ≡ 9⁩ ، ⁦3³ ≡ 7⁩ ، ⁦3⁴ ≡ 1⁩\n   – الدور 4\n   – ⁦2025 = 4×506 + 1⁩ فـ ⁦3²⁰²⁵ = (3⁴)⁵⁰⁶·3 ≡ 3 [10]⁩\n   – الباقي 3\n• تمرين 2: بيّن أن ⁦n³ - n⁩ يقبل القسمة على 6.\n• الحل:\n   – ⁦n³ - n = (n - 1)n(n + 1)⁩ جداء ثلاثة أعداد متتالية: أحدها زوجي وأحدها مضاعف للعدد 3\n   – وبما أن 2 و 3 أوليان فيما بينهما فهو يقبل القسمة على 6\n• تمرين 3: بيّن أن 11 يقسم ⁦10²ⁿ⁺¹ + 1⁩.\n• الحل:\n   – ⁦10 ≡ -1 [11]⁩ فـ ⁦10²ⁿ⁺¹ ≡ (-1)²ⁿ⁺¹ = -1 [11]⁩\n   – إذن ⁦10²ⁿ⁺¹ + 1 ≡ 0 [11]⁩\n• تمرين 4: بيّن أن مربع كل عدد فردي يوافق 1 بترديد 8.\n• الحل:\n   – ⁦n = 2k + 1⁩ فـ ⁦n² = 4k(k+1) + 1⁩\n   – و ⁦k(k+1)⁩ زوجي فـ ⁦4k(k+1)⁩ مضاعف للعدد 8\n   – إذن ⁦n² ≡ 1 [8]⁩\n▸ للحفظ\n• ابحث عن الدور في القوى. القابلية: ادرس كل البواقي الممكنة."},{"title":"25. القاسم المشترك الأكبر وخوارزمية إقليدس","content":"▸ التعريف\n• ⁦PGCD(a ; b)⁩ أكبر قاسم مشترك\n• ⁦PGCD(a ; b) = PGCD(b ; r)⁩ حيث r باقي قسمة a على b\n▸ الخوارزمية\n• نقسم a على b ثم b على الباقي ...\n• آخر باقي غير معدوم هو PGCD\n▸ خواص\n• ⁦PGCD(ka ; kb) = k·PGCD(a ; b)⁩\n• a و b أوليان فيما بينهما ⇔ ⁦PGCD = 1⁩\n• ⁦a × b = PGCD × PPCM⁩\n▸ كيف نبرهن؟\n• قاسم مشترك لـ a و b يقسم ⁦a - b⁩ و ⁦a + b⁩\n• لإثبات ⁦PGCD = 1⁩: نبين أن القواسم المشتركة تقسم 1\n▸ شرح مبسط\n• خوارزمية إقليدس هي أسرع طريقة لإيجاد القاسم المشترك الأكبر: نكرر القسمة على الباقي حتى ينعدم الباقي، فيكون آخر باقي غير معدوم هو الجواب.\n▸ طرق وقواعد\n• اكتب كل قسمة بصيغة ⁦a = bq + r⁩.\n• احسب PPCM بالعلاقة ⁦a·b = PGCD·PPCM⁩.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦PGCD(252 ; 198)⁩ و ⁦PPCM(252 ; 198)⁩.\n• الحل:\n   – ⁦252 = 198 + 54⁩ ثم ⁦198 = 3×54 + 36⁩ ثم ⁦54 = 36 + 18⁩ ثم ⁦36 = 2×18 + 0⁩\n   – آخر باقي غير معدوم 18 فـ ⁦PGCD = 18⁩\n   – ⁦PPCM = 252×198/18 = 2772⁩\n• تمرين 2: بيّن أن ⁦n⁩ و ⁦n + 1⁩ أوليان فيما بينهما.\n• الحل:\n   – كل قاسم مشترك لـ n و ⁦n + 1⁩ يقسم الفرق ⁦(n + 1) - n = 1⁩\n   – إذن ⁦PGCD = 1⁩\n• تمرين 3: احسب ⁦PGCD(2n + 1 ; n)⁩ من أجل ⁦n ≥ 1⁩.\n• الحل:\n   – ⁦2n + 1 = 2·n + 1⁩\n   – الباقي 1 فـ ⁦PGCD = PGCD(n ; 1) = 1⁩\n▸ للحفظ\n• ⁦PGCD(a,b) = PGCD(b,r)⁩. آخر باقي غير معدوم⁦. a·b = PGCD·PPCM⁩."},{"title":"26. مبرهنتا بيزو وغوص والمعادلة ax + by = c","content":"▸ مبرهنة بيزو\n• a و b أوليان فيما بينهما ⇔ يوجد ⁦u, v⁩ صحيحان بحيث ⁦au + bv = 1⁩\n• نجدهما بعكس خوارزمية إقليدس\n▸ مبرهنة غوص\n• إذا ⁦a | bc⁩ و a أولي مع b فإن ⁦a | c⁩\n• نستعملها لإثبات أن قاسما يقسم عاملا\n▸ المعادلة ax + by = c\n• لها حلول ⇔ ⁦PGCD(a ; b) | c⁩\n• نجد حلا خاصا ⁦(x₀ ; y₀)⁩\n• الحل العام: بالطرح ثم استعمال غوص\n▸ كيف نبرهن؟\n• نحسب PGCD ونتحقق من القابلية\n• نجد حلا خاصا بالتجريب أو إقليدس\n• نطرح ونطبق غوص\n▸ شرح مبسط\n• مبرهنة بيزو تقول: إذا كان العددان أوليين فيما بينهما فيمكن تركيب العدد 1 منهما بمضاعفات صحيحة. وهذا يفتح الباب لحل المعادلات الديوفانتية وإيجاد مقلوب عدد بترديد معين.\n▸ طرق وقواعد\n• حلل الجداء وطبق غوص.\n• عكس إقليدس: عبّر عن 1 بدلالة a و b.\n• أكتب الحل العام بمعامل k صحيح.\n▸ تمارين محلولة\n• تمرين 1: حل في ⁦ℤ²⁩ المعادلة ⁦7x + 5y = 3⁩.\n• الحل:\n   – ⁦PGCD(7 ; 5) = 1⁩ يقسم 3 فالحلول موجودة\n   – حل خاص: ⁦7×(-6) + 5×9 = -42 + 45 = 3⁩ أي ⁦(x₀ ; y₀) = (-6 ; 9)⁩\n   – بالطرح: ⁦7(x + 6) = -5(y - 9)⁩\n   – 5 يقسم ⁦7(x + 6)⁩ وهو أولي مع 7 فحسب غوص ⁦5 | (x + 6)⁩ أي ⁦x = -6 + 5k⁩ ثم ⁦y = 9 - 7k⁩ (⁦k ∈ ℤ⁩)\n• تمرين 2: هل للمعادلة ⁦3x + 6y = 5⁩ حلول؟\n• الحل:\n   – ⁦PGCD(3 ; 6) = 3⁩ ولا يقسم 5\n   – لا حلول\n• تمرين 3: أوجد ⁦u⁩ و ⁦v⁩ بحيث ⁦5u + 17v = 1⁩.\n• الحل:\n   – ⁦17 = 3×5 + 2⁩ و ⁦5 = 2×2 + 1⁩\n   – فـ ⁦1 = 5 - 2×2 = 5 - 2(17 - 3×5) = 7×5 - 2×17⁩\n   – إذن ⁦u = 7⁩ و ⁦v = -2⁩\n• تمرين 4: بيّن أنه إذا كان 7 يقسم ⁦3k⁩ فإن 7 يقسم ⁦k⁩.\n• الحل:\n   – ⁦PGCD(7 ; 3) = 1⁩ فحسب مبرهنة غوص ⁦7 | k⁩\n▸ للحفظ\n• بيزو⁦: PGCD = 1 ⇔ au + bv = 1⁩. غوص⁦: a | bc⁩ و ⁦PGCD(a,b)=1 ⇒ a | c⁩."},{"title":"27. الأعداد الأولية","content":"▸ التعريف\n• عدد أولي: قاسماه 1 ونفسه فقط\n• كل عدد أكبر من 1 يُحلل بشكل وحيد إلى جداء أعداد أولية\n▸ اختبار الأولية\n• نجرب القسمة على الأعداد الأولية ⁦≤ √n⁩\n• إن لم نجد قاسما فهو أولي\n▸ عدد القواسم\n• إذا ⁦n = pᵃ qᵇ r^(c)⁩ فعدد قواسمه ⁦(a+1)(b+1)(c+1)⁩\n▸ خواص\n• الأعداد الأولية لا نهائية\n• ⁦n² - 1 = (n-1)(n+1)⁩ ليس أوليا من أجل ⁦n > 2⁩\n• فيرما: ⁦aᵖ⁻¹ ≡ 1 [p]⁩ إذا p أولي ولا يقسم a (إضافي)\n▸ شرح مبسط\n• الأعداد الأولية هي الذرات التي تبنى منها كل الأعداد. لنعرف هل عدد أولي يكفي أن نجرب القسمة على الأعداد الأولية الأصغر من جذره التربيعي، لأن أي قاسم أكبر يقابله قاسم أصغر.\n▸ طرق وقواعد\n• احسب ⁦√n⁩ لتعرف أين تتوقف.\n• للحصول على عدد القواسم حلل أولا.\n▸ تمارين محلولة\n• تمرين 1: هل 97 أولي؟\n• الحل:\n   – ⁦√97 ≈ 9.8⁩: نجرب 2 و 3 و 5 و 7 فلا أحد منها يقسم 97\n   – إذن 97 أولي\n• تمرين 2: كم قاسما للعدد 360؟\n• الحل:\n   – ⁦360 = 2³ × 3² × 5⁩\n   – عدد القواسم ⁦(3+1)(2+1)(1+1) = 24⁩\n• تمرين 3: بيّن أن ⁦n² - 1⁩ ليس أوليا من أجل ⁦n > 2⁩.\n• الحل:\n   – ⁦n² - 1 = (n - 1)(n + 1)⁩ مع ⁦n - 1 > 1⁩ و ⁦n + 1 > 1⁩\n   – فهو يملك قاسما غير 1 ونفسه\n• تمرين 4: ما باقي قسمة ⁦5¹⁰⁰⁩ على 7؟\n• الحل:\n   – حسب فيرما ⁦5⁶ ≡ 1 [7]⁩\n   – ⁦100 = 6×16 + 4⁩ فـ ⁦5¹⁰⁰ ≡ 5⁴ = 625 ≡ 2 [7]⁩\n▸ للحفظ\n• أولي: قاسماه 1 ونفسه. اختبار حتى ⁦√n⁩. عدد القواسم = جداء (الأسس ⁦+ 1)⁩."},{"title":"28. الاحتمال الشرطي والاستقلال","content":"▸ الاحتمال الشرطي\n• ⁦P_(B)(A) = P(A ∩ B)/P(B)⁩ مع ⁦P(B) ≠ 0⁩\n• ⁦P(A ∩ B) = P(B)·P_(B)(A)⁩\n▸ الشجرة\n• نضرب على المسار ونجمع بين المسارات\n• مجموع احتمالات فروع نفس العقدة = 1\n▸ الاستقلال\n• A و B مستقلان ⇔ ⁦P(A ∩ B) = P(A)·P(B)⁩\n• أي ⁦P_(B)(A) = P(A)⁩\n▸ كيف نبرهن؟\n• استقلال: نحسب ⁦P(A)P(B)⁩ و ⁦P(A∩B)⁩ ونقارن\n• شجرة: نكتب الاحتمال على كل فرع\n▸ شرح مبسط\n• الاحتمال الشرطي هو احتمال A إذا علمنا أن B وقع. فنتحدث عن عالم جديد فقط فيه B. والاستقلال معناه أن معرفة B لا تغير شيئا من احتمال A.\n▸ طرق وقواعد\n• اكتب العلاقات بالرموز قبل الحساب.\n• ارسم الشجرة.\n▸ تمارين محلولة\n• تمرين 1: كيس فيه 3 كريات حمراء و2 زرقاء. نسحب كريتين على التوالي دون إرجاع. احسب ⁦P(R2|R1)⁩ و ⁦P(R1 ∩ R2)⁩.\n• الحل:\n   – ⁦P(R₂ | R₁) = 2/4 = 1/2⁩\n   – ⁦P(R₁ ∩ R₂) = 3/5 × 1/2 = 3/10⁩\n• تمرين 2: نرمي نردا: A «زوجي» و B «≥ 5». هل هما مستقلان؟\n• الحل:\n   – ⁦P(A) = 1/2⁩ و ⁦P(B) = 2/6 = 1/3⁩ و ⁦A ∩ B = {6}⁩ فـ ⁦P(A ∩ B) = 1/6 = P(A)×P(B)⁩\n   – نعم مستقلان\n• تمرين 3: في قسم 60% بنات. 40% من البنات و20% من الذكور يمارسون الرياضة. احسب ⁦P(بنت ∩ رياضة)⁩.\n• الحل:\n   – ⁦P = 0.6 × 0.4 = 0.24⁩\n▸ للحفظ\n• ⁦P_(B)(A) = P(A⁩∩⁦B)/P(B)⁩. مستقلان ⁦⇔ P(A⁩∩⁦B)=P(A)P(B)⁩."},{"title":"29. الاحتمالات الكلية وصيغة بايز","content":"▸ جزئية\n• ⁦B₁, B₂, ...⁩ تشكل جزئية إذا كانت متنافية ومجموعها الكل\n▸ الاحتمال الكلي\n• ⁦P(A) = Σ P(Bᵢ)·P_(B_i)(A)⁩\n▸ صيغة بايز\n• ⁦P_(A)(B) = P(B)·P_(B)(A)/P(A)⁩\n• تنتقل من الاحتمال الشرطي المعروف إلى المعكوس\n▸ كيف نبرهن؟\n• ارسم الشجرة\n• احسب ⁦P(A)⁩ بجمع المسارات\n• ثم بايز بقسمة مسار على المجموع\n▸ شرح مبسط\n• نعرف مثلا احتمال أن يكون الاختبار إيجابيا إذا كان الشخص مصابا، ونريد العكس: احتمال أن يكون مصابا إذا كان الاختبار إيجابيا. هذا هو دور بايز.\n▸ طرق وقواعد\n• ابدأ بالشجرة.\n• ⁦P(A)⁩ هو المقام في بايز.\n▸ تمارين محلولة\n• تمرين 1: نسبة المصابين بمرض 2%. الاختبار إيجابي بـ 95% عند المصاب وبـ 4% عند السليم. إذا كان الاختبار إيجابيا فما احتمال أن يكون الشخص مصابا؟\n• الحل:\n   – ⁦P(T) = 0.02×0.95 + 0.98×0.04 = 0.019 + 0.0392 = 0.0582⁩\n   – ⁦P_(T)(M) = 0.019/0.0582 ≈ 0.327⁩\n   – الاحتمال نحو 32.7% فقط رغم إيجابية الاختبار\n• تمرين 2: مصنع: الآلة A (60%) ونسبة العيوب 5%، و B (40%) و 10%. احسب احتمال القطعة المعيبة، وإذا كانت معيبة فما احتمال أنها من A؟\n• الحل:\n   – ⁦P(D) = 0.6×0.05 + 0.4×0.10 = 0.07⁩\n   – ⁦P_(D)(A) = 0.03/0.07 = 3/7 ≈ 0.43⁩\n• تمرين 3: ثلاثة موردين: 50% بعيب 1%، 30% بعيب 2%، 20% بعيب 5%. إذا كانت قطعة معيبة فما احتمال أنها من المورد الثالث؟\n• الحل:\n   – ⁦P(D) = 0.005 + 0.006 + 0.010 = 0.021⁩\n   – ⁦P_(D)(C) = 0.010/0.021 = 10/21 ≈ 0.476⁩\n▸ للحفظ\n• ⁦P(A) =⁩ Σ⁦P(B⁩ᵢ⁦)P_{B⁩ᵢ⁦}(A)⁩. بايز⁦: P_(A)(B) = P(B)P_(B)(A)/P(A)⁩."},{"title":"30. القانون الثنائي","content":"▸ تجربة برنولي\n• نتيجتان: نجاح (احتمال p) وفشل (احتمال ⁦1 - p⁩)\n▸ مخطط برنولي\n• نكرر n مرة تجربة برنولي مستقلة\n• X = عدد النجاحات: ⁦X ~ B(n ; p)⁩\n▸ القانون\n• ⁦P(X = k) = C(n,k)·pᵏ·(1-p)ⁿ⁻ᵏ⁩\n• ⁦E(X) = np⁩ و ⁦V(X) = np(1-p)⁩\n• ⁦P(X ≥ 1) = 1 - (1-p)ⁿ⁩\n▸ كيف نبرهن؟\n• اذكر: نكرر n مرة تجربة برنولي بشروط مستقلة واحتمال النجاح ثابت p\n• إذن X يتبع القانون الثنائي\n▸ شرح مبسط\n• القانون الثنائي يعد عدد النجاحات في n محاولة مستقلة. مثل عدد الوجوه في 5 رميات. نكتب احتمال k نجاحات بعدد الطرق لاختيار مواضعها ⁦C(n,k)⁩ ثم نضرب باحتمال كل ترتيب.\n▸ طرق وقواعد\n• حدد n و p بوضوح.\n• «على الأقل واحد»: استعمل العكس ⁦1 - (1-p)ⁿ⁩.\n• C(n,k) من المثلث أو الآلة الحاسبة.\n▸ تمارين محلولة\n• تمرين 1: نرمي قطعة نقدية نظامية 5 مرات. احسب احتمال الحصول على وجهين بالضبط، ثم احتمال 3 وجوه على الأقل.\n• الحل:\n   – ⁦X ~ B(5 ; 0.5)⁩\n   – ⁦P(X = 2) = C(5,2)(0.5)⁵ = 10/32 = 5/16 = 0.3125⁩\n   – ⁦P(X ≥ 3) = (10 + 5 + 1)/32 = 16/32 = 1/2⁩\n• تمرين 2: رام يصيب الهدف باحتمال 0.3. يرمي 4 مرات. احسب احتمال الإصابة مرة على الأقل.\n• الحل:\n   – ⁦Y ~ B(4 ; 0.3)⁩\n   – ⁦P(Y ≥ 1) = 1 - 0.7⁴ = 1 - 0.2401 = 0.7599⁩\n• تمرين 3: احسب الأمل والتباين لـ ⁦X ~ B(10 ; 0.4)⁩.\n• الحل:\n   – ⁦E(X) = 10×0.4 = 4⁩ و ⁦V(X) = 10×0.4×0.6 = 2.4⁩\n• تمرين 4: كم مرة نرمي قطعة نقدية على الأقل ليكون احتمال الحصول على وجه واحد على الأقل أكبر من 0.99؟\n• الحل:\n   – ⁦1 - 0.5ⁿ ≥ 0.99⁩ أي ⁦0.5ⁿ ≤ 0.01⁩\n   – ⁦0.5⁶ = 0.0156⁩ و ⁦0.5⁷ = 0.0078⁩\n   – إذن ⁦n ≥ 7⁩\n▸ للحفظ\n• X ~ ⁦B(n;p): P(X=k)=C(n,k)pᵏ(1−p)^(n−k). E=np⁩، ⁦V=np(1−p)⁩."},{"title":"31. الجداء السلمي والاستقامية والتعامد في الفضاء","content":"▸ الإحداثيات\n• ⁦u(x ; y ; z)⁩ و ⁦v(x′ ; y′ ; z′)⁩\n• ⁦‖u‖ = √(x² + y² + z²)⁩\n• ⁦AB(x_(B) - x_(A) ; y_(B) - y_(A) ; z_(B) - z_(A))⁩\n▸ الجداء السلمي\n• ⁦u·v = xx′ + yy′ + zz′⁩\n• ⁦u·v = ‖u‖‖v‖cos θ⁩\n• ⁦u ⊥ v ⇔ u·v = 0⁩\n▸ استقامية وتحاذٍ\n• A و B و C على استقامة ⇔ ⁦AC = k·AB⁩\n• نقط من نفس المستوي ⇔ ⁦AD = αAB + βAC⁩\n▸ كيف نبرهن؟\n• تعامد: نحسب الجداء السلمي ونجده 0\n• استقامية: نجد k يحقق ⁦AC = kAB⁩\n• زاوية: نحسب ⁦cos θ⁩ ونستنتج\n▸ شرح مبسط\n• نتعامل مع الفضاء كما مع المستوي لكن بإحداثي ثالث. الجداء السلمي هو أداة التعامد والزوايا: إن كان صفرا فالمستقيمان متعامدان.\n▸ طرق وقواعد\n• احسب الإحداثيات الشعاعية أولا.\n• احسب الطويلة ثم cos θ للزاوية.\n▸ تمارين محلولة\n• تمرين 1: ⁦A(1,1,0)⁩ و ⁦B(2,1,1)⁩ و ⁦C(1,3,0)⁩. بيّن أن المثلث ABC قائم في A.\n• الحل:\n   – ⁦AB(1 ; 0 ; 1)⁩ و ⁦AC(0 ; 2 ; 0)⁩\n   – الجداء السلمي ⁦0×1 + 2×0 + 0×1 = 0⁩\n   – إذن ⁦AB ⊥ AC⁩ والمثلث قائم في A\n• تمرين 2: احسب الزاوية بين ⁦u(1,1,0)⁩ و ⁦v(0,1,1)⁩.\n• الحل:\n   – ⁦u·v = 1⁩، ⁦‖u‖ = ‖v‖ = √2⁩\n   – ⁦cos θ = 1/2⁩ فـ ⁦θ = 60°⁩\n• تمرين 3: بيّن أن ⁦A(1,2,3)⁩ و ⁦B(2,4,6)⁩ و ⁦C(3,6,9)⁩ على استقامة.\n• الحل:\n   – ⁦AB(1 ; 2 ; 3)⁩ و ⁦AC(2 ; 4 ; 6) = 2AB⁩\n   – إذن على استقامة\n▸ للحفظ\n• ⁦u·v = xx′+yy′+zz′. u⁩ ⊥ ⁦v ⇔ u·v=0⁩. استقامية⁦: AC = k·AB⁩."},{"title":"32. معادلة المستوي والمسافة","content":"▸ شعاع ناظمي\n• مستوٍ P: ⁦ax + by + cz + d = 0⁩ فالناظم ⁦n(a ; b ; c)⁩\n• ⁦n·AM = 0⁩ لكل نقطة M من المستوي\n▸ معادلة المستوي\n• يمر بـ ⁦A⁩ وناظمه ⁦n⁩: ⁦a(x - x_(A)) + b(y - y_(A)) + c(z - z_(A)) = 0⁩\n• من ثلاث نقاط: نجد ناظما بجداء سلمي صفري مع ⁦AB⁩ و ⁦AC⁩\n▸ المسافة\n• ⁦d(M₀ , P) = |ax₀ + by₀ + cz₀ + d|/√(a² + b² + c²)⁩\n▸ توازٍ وتعامد مستويين\n• متوازيان ⇔ ناظماهما على استقامة\n• متعامدان ⇔ ⁦n·n′ = 0⁩\n▸ شرح مبسط\n• المستوي يُحدد بنقطة وشعاع ناظمي (عمودي عليه). المسافة من نقطة إلى مستوٍ هي طول العمود المسقط، وتُحسب بقانون جاهز فيه القيمة المطلقة.\n▸ طرق وقواعد\n• اكتب الناظم من معاملات x و y و z.\n• احسب ⁦d⁩ بالقانون ثم قرّب.\n▸ تمارين محلولة\n• تمرين 1: عيّن معادلة المستوي (P) المار بـ ⁦A(1,0,2)⁩ والناظمي ⁦n(2,-1,3)⁩ ثم احسب بعد ⁦B(0,1,1)⁩ عنه.\n• الحل:\n   – ⁦2(x - 1) - y + 3(z - 2) = 0⁩ أي ⁦2x - y + 3z - 8 = 0⁩\n   – ⁦d(B , P) = |0 - 1 + 3 - 8|/√(4 + 1 + 9) = 6/√14 ≈ 1.60⁩\n• تمرين 2: عيّن معادلة المستوي المار بـ ⁦A(1,0,0)⁩ و ⁦B(0,1,0)⁩ و ⁦C(0,0,1)⁩.\n• الحل:\n   – نخمّن ⁦x + y + z = 1⁩: يحقق النقط الثلاث\n   – فهي المعادلة\n• تمرين 3: بيّن أن المستويين ⁦x + y + z = 0⁩ و ⁦x - y = 0⁩ متعامدان.\n• الحل:\n   – ⁦n(1,1,1)⁩ و ⁦n′(1,-1,0)⁩\n   – ⁦n·n′ = 1 - 1 + 0 = 0⁩\n   – متعامدان\n▸ للحفظ\n• ⁦ax+by+cz+d=0 ⇒⁩ ناظم ⁦n(a,b,c). d = |ax₀+by₀+cz₀+d|/√(a²+b²+c²)⁩."},{"title":"33. المستقيم والمستوي والكرة","content":"▸ تمثيل وسيطي لمستقيم\n• ⁦x = x_(A) + at⁩ و ⁦y = y_(A) + bt⁩ و ⁦z = z_(A) + ct⁩\n• ⁦(a,b,c)⁩ شعاع توجيه\n▸ تقاطع مستقيم ومستوٍ\n• نعوض التمثيل الوسيطي في معادلة المستوي\n• حل وحيد: نقطة تقاطع\n• لا حل: توازٍ\n• كل القيم: المستقيم محتوى في المستوي\n▸ مستقيم عمودي على مستو\n• شعاع توجيهه على استقامة مع الناظم\n• الإسقاط العمودي لنقطة M: ⁦H = M + t·n⁩\n▸ سطح كرة\n• ⁦(x - a)² + (y - b)² + (z - c)² = R²⁩\n• القطع بمستو: دائرة نصف قطرها ⁦√(R² - d²)⁩\n▸ كيف نبرهن؟\n• تقاطع: نحل t ونعوض\n• تعامد مستقيم ومستو: توجيه على استقامة مع الناظم\n▸ شرح مبسط\n• المستقيم يُمثَّل بنقطة وشعاع توجيه. لإيجاد تقاطعه مع مستو نعوض إحداثيات النقطة العامة للمستقيم (بدلالة t) في معادلة المستوي فنحصل على معادلة بسيطة في t.\n▸ طرق وقواعد\n• عوّض التمثيل الوسيطي.\n• ناقش الحالات: حل وحيد أم لا حل أم كل t.\n▸ تمارين محلولة\n• تمرين 1: المستقيم (D): ⁦x = t⁩ ، ⁦y = 1 + t⁩ ، ⁦z = 2 - t⁩ والمستوي ⁦x + y + z = 4⁩. عيّن نقطة التقاطع.\n• الحل:\n   – نعوض: ⁦t + 1 + t + 2 - t = 3 + t = 4⁩ فـ ⁦t = 1⁩\n   – النقطة ⁦(1 ; 2 ; 1)⁩\n• تمرين 2: كرة مركزها ⁦O⁩ ونصف قطرها 5 والمستوي ⁦z = 3⁩. ما طبيعة التقاطع؟\n• الحل:\n   – المسافة ⁦d = 3 < 5⁩\n   – التقاطع دائرة نصف قطرها ⁦√(25 - 9) = 4⁩\n• تمرين 3: عيّن المسقط العمودي للنقطة ⁦M(1,2,3)⁩ على المستوي ⁦x + y + z = 0⁩.\n• الحل:\n   – الناظم ⁦n(1,1,1)⁩\n   – ⁦H = M + t·n = (1 + t ; 2 + t ; 3 + t)⁩\n   – نعوض: ⁦6 + 3t = 0⁩ فـ ⁦t = -2⁩\n   – ⁦H(-1 ; 0 ; 1)⁩\n▸ للحفظ\n• مستقيم ⁦x=x_(A)+at⁩... ؛ تقاطع مع مستو: عوّض وحل t. كرة ⁦(x−a)²+(y−b)²+(z−c)²=R²⁩."},{"title":"34. قوالب جاهزة لكتابة البرهان","content":"▸ وجود حل وحيد\n• «الدالة f مستمرة ورتيبة تماما على [a ; b] و ⁦f(a)·f(b) < 0⁩، إذن حسب مبرهنة القيم المتوسطة المعادلة ⁦f(x) = 0⁩ تقبل حلا وحيدا α في [a ; b]»\n▸ الاستدلال بالتراجع\n• «من أجل n = n₀: ... صحيحة. نفرض P(n) صحيحة ونبرهن P(n+1): ... إذن P(n) صحيحة لكل n ≥ n₀»\n▸ تقارب متتالية\n• «(uₙ) متزايدة ومحدودة من الأعلى إذن متقاربة نحو ℓ. بما أن f مستمرة فإن ℓ = f(ℓ)»\n▸ متباينة\n• «نضع h = f − g وندرس تغيرات h: أصغر قيمة لـ h موجبة إذن f(x) ≥ g(x)»\n▸ استقامية بالمركبة\n• «(z_C − z_A)/(z_B − z_A) عدد حقيقي إذن A و B و C على استقامة واحدة»\n▸ قابلية القسمة\n• «ندرس البواقي الممكنة بترديد m: ... في كل الحالات A ≡ 0 [m] إذن m يقسم A»\n▸ تقاطع مستقيم ومستو\n• «نعوض التمثيل الوسيطي في معادلة المستوي فنجد t = ... إذن نقطة التقاطع هي ...»\n▸ بايز\n• «حسب الاحتمالات الكلية P(A) = ... وحسب صيغة بايز P_A(B) = ...»\n▸ شرح مبسط\n• الأسئلة التي يطرحها الأستاذ في الامتحان تتكرر بأنماط محددة. حفظ العبارات الجاهزة يوفر عليك الوقت ويمنعك من نسيان شرط مهم (الاستمرارية أو الرتابة أو فرض التراجع). اكتب القالب أولا ثم ضع التفاصيل.\n▸ طرق وقواعد\n• اقرأ السؤال وحدد النمط.\n• اكتب القالب ثم اقتبس التفاصيل.\n• لا تنس ذكر الشروط (مستمرة، رتيبة، مجال).\n▸ تمارين محلولة\n• تمرين 1: ما الذي أكتبه في أول سطر عند طلب «بيّن أن المعادلة تقبل حلا وحيدا»؟\n• الحل:\n   – أذكر: الدالة مستمرة، ورتيبة تماما (بإشارة المشتق)، وأن ⁦f(a)·f(b) < 0⁩، ثم أستنتج بمبرهنة القيم المتوسطة\n• تمرين 2: ما الجملة الأخيرة في الاستدلال بالتراجع؟\n• الحل:\n   – «إذن الخاصية P(n) صحيحة من أجل كل n ≥ n₀»\n▸ للحفظ\n• اعرف النمط، اكتب القالب، لا تنس الشروط، واختم بجملة الاستنتاج."}],maps:'mm'};
  A.ge_maths=Object.assign({name:'الرياضيات'},A.ge_maths||{},{lessons:[{"title":"1. النهايات والمقاربات","content":"▸ كثير حدود\n• عند ⁦±∞⁩ يتحكم الحد ذو أكبر أس وحده\n• ⁦3x² - x + 1⁩ تؤول إلى ⁦+∞⁩ عند ⁦+∞⁩\n• ⁦-2x³ + 5⁩ تؤول إلى ⁦-∞⁩ عند ⁦+∞⁩\n▸ دالة ناطقة عند ∞\n• نأخذ حاصل قسمة الحدين الأعلى درجة\n• درجة البسط = درجة المقام ⇒ حاصل المعاملين\n• درجة البسط < درجة المقام ⇒ النهاية 0\n▸ عند عدد a يعدم المقام\n• نحدد إشارة البسط وإشارة المقام من جهتي a\n• النتيجة ⁦+∞⁩ أو ⁦-∞⁩ حسب الإشارة\n• المستقيم ⁦x = a⁩ مقارب عمودي\n▸ المقاربات\n• أفقي: ⁦lim f(x) = L⁩ فالمقارب ⁦y = L⁩\n• عمودي: ⁦lim f(x) = ±∞⁩ عند ⁦a⁩\n• مائل: ⁦f(x) - (ax + b)⁩ يؤول إلى 0\n▸ أخطاء شائعة\n• كتابة ⁦∞ - ∞ = 0⁩ دون رفع عدم التعيين\n• نسيان دراسة النهاية من اليمين واليسار\n• الخلط بين المقارب الأفقي والعمودي\n▸ شرح مبسط\n• النهاية تجيب عن سؤال واحد: أين تذهب قيمة الدالة عندما يقترب x من نقطة أو يكبر كثيرا؟ في كثيرات الحدود الحد الأكبر أسا هو الذي يقرر لأنه يكبر أسرع من الباقي. والمقارب مستقيم يقترب منه المنحنى ولا يلمسه في الأطراف.\n▸ طرق وقواعد\n• لنهاية ناطقة عند اللانهاية: أبق على الحدين الأعلى درجة فقط.\n• عند عدد يعدم المقام: ادرس إشارة المقام على يمين وعلى يسار العدد.\n• لمقارب مائل: اكتب ⁦f(x) = ax + b + g(x)⁩ مع ⁦g(x) → 0⁩.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦lim (-2x³ + x² + 5)⁩ عند ⁦+∞⁩.\n• الحل:\n   – الحد الأعلى درجة هو ⁦-2x³⁩\n   – إذن النهاية ⁦-∞⁩\n• تمرين 2: لتكن ⁦f(x) = (2x + 1)/(x - 3)⁩. احسب النهايات واستنتج المقاربات.\n• الحل:\n   – عند ⁦±∞⁩ النهاية ⁦2x/x = 2⁩ فالمستقيم ⁦y = 2⁩ مقارب أفقي\n   – عند 3 البسط 7 موجب\n   – من اليمين ⁦x - 3⁩ موجب فالنهاية ⁦+∞⁩\n   – من اليسار ⁦x - 3⁩ سالب فالنهاية ⁦-∞⁩\n   – إذن ⁦x = 3⁩ مقارب عمودي\n• تمرين 3: احسب ⁦lim (x² - 4)/(x - 2)⁩ عند 2.\n• الحل:\n   – شكل عدم التعيين ⁦0/0⁩\n   – نحلل ⁦x² - 4 = (x - 2)(x + 2)⁩\n   – نختصر فنجد ⁦x + 2⁩\n   – النهاية 4\n▸ للحفظ\n• ناطقة عند اللانهاية: حاصل الحدين الأعلى درجة. عدم التعيين: حلل أو اختصر. مقارب عمودي ⁦x = a⁩ ومقارب أفقي ⁦y = L⁩."},{"title":"2. الاشتقاق والمماس واتجاه التغير","content":"▸ مشتقات أساسية\n• ⁦(xⁿ)′ = n·xⁿ⁻¹⁩\n• ⁦(u + v)′ = u′ + v′⁩ و ⁦(ku)′ = k·u′⁩\n• ⁦(1/x)′ = -1/x²⁩\n▸ العمليات\n• ⁦(u·v)′ = u′v + uv′⁩\n• ⁦(u/v)′ = (u′v - uv′)/v²⁩\n• ⁦(uⁿ)′ = n·u′·uⁿ⁻¹⁩\n▸ اتجاه التغير\n• ⁦f′ > 0⁩ على مجال ⇒ f متزايدة\n• ⁦f′ < 0⁩ على مجال ⇒ f متناقصة\n• تنعدم ⁦f′⁩ مع تغير الإشارة ⇒ قيمة حدية\n▸ المماس\n• معادلة المماس عند ⁦a⁩: ⁦y = f′(a)(x - a) + f(a)⁩\n• ⁦f′(a)⁩ هو ميل المماس\n• ⁦f′(a) = 0⁩ ⇒ مماس أفقي\n▸ أخطاء شائعة\n• نسيان قاعدة المركب ⁦u′⁩\n• الخلط بين ⁦f(a)⁩ و ⁦f′(a)⁩ في المماس\n• إشارة ⁦f′⁩ تؤخذ من البسط مع المقام الموجب\n▸ شرح مبسط\n• المشتقة تقيس سرعة تغير الدالة. إذا كانت موجبة فالدالة تصعد وإذا كانت سالبة فهي تنزل. وعندما تنعدم وتغير إشارتها نجد أعلى نقطة أو أدنى نقطة. المماس هو المستقيم الذي يلمس المنحنى عند نقطة ويأخذ ميلا يساوي المشتقة هناك.\n▸ طرق وقواعد\n• احسب المشتقة ثم حلل إلى عوامل لدراسة الإشارة.\n• في الكسر ادرس إشارة البسط لأن ⁦v²⁩ موجب.\n• للمماس احسب ⁦f(a)⁩ ثم ⁦f′(a)⁩ ثم عوض في القانون.\n▸ تمارين محلولة\n• تمرين 1: ادرس تغيرات ⁦f(x) = x³ - 3x² + 2⁩.\n• الحل:\n   – ⁦f′(x) = 3x² - 6x = 3x(x - 2)⁩\n   – تنعدم عند 0 و 2\n   – موجبة على ⁦]-∞ ; 0]⁩ وعلى ⁦[2 ; +∞[⁩ وسالبة على ⁦[0 ; 2]⁩\n   – إذن f متزايدة ثم متناقصة ثم متزايدة\n   – ⁦f(0) = 2⁩ قيمة عظمى محلية و ⁦f(2) = 8 - 12 + 2 = -2⁩ قيمة صغرى محلية\n• تمرين 2: احسب مشتقة ⁦f(x) = (2x + 1)/(x - 3)⁩.\n• الحل:\n   – ⁦f′(x) = (2(x - 3) - (2x + 1))/(x - 3)² = -7/(x - 3)²⁩\n   – المشتقة سالبة دائما إذن f متناقصة على كل مجال من مجاليها\n• تمرين 3: اكتب معادلة المماس لـ ⁦f(x) = x² - 4x + 1⁩ عند ⁦a = 3⁩.\n• الحل:\n   – ⁦f(3) = 9 - 12 + 1 = -2⁩\n   – ⁦f′(x) = 2x - 4⁩ فـ ⁦f′(3) = 2⁩\n   – المعادلة ⁦y = 2(x - 3) - 2⁩ أي ⁦y = 2x - 8⁩\n▸ للحفظ\n• ⁦f′ > 0⁩ تزايد و ⁦f′ < 0⁩ تناقص. المماس: ⁦y = f′(a)(x - a) + f(a)⁩. المشتقة الكسرية: ⁦(u′v - uv′)/v²⁩."},{"title":"3. خطوات دراسة دالة وتمثيلها","content":"▸ الخطوات\n• 1) مجموعة التعريف\n• 2) النهايات والمقاربات\n• 3) المشتقة وإشارتها\n• 4) جدول التغيرات\n• 5) المماسات والرسم\n▸ جدول التغيرات\n• سطر x ثم سطر ⁦f′(x)⁩ ثم سطر ⁦f(x)⁩\n• الأسهم تتبع إشارة ⁦f′⁩\n• نكتب النهايات في الأطراف والقيم الحدية\n▸ المقارب المائل\n• نكتب ⁦f(x) = ax + b + g(x)⁩ مع ⁦g(x) → 0⁩\n• ⁦y = ax + b⁩ مقارب مائل\n• إشارة ⁦g⁩ تعطي وضعية المنحنى\n▸ الرسم\n• ارسم المقاربات أولا\n• علّم القيم الحدية وتقاطع المحورين\n• صل بين النقاط وفق جدول التغيرات\n▸ أخطاء شائعة\n• نسيان القيم المحرمة في مجموعة التعريف\n• عدم كتابة ⁦||⁩ عند القيمة المحرمة في الجدول\n• رسم المنحنى يقطع المقارب العمودي\n▸ شرح مبسط\n• دراسة الدالة تشبه فحصا طبيا من خطوات ثابتة: أين تعيش الدالة (المجال)، وماذا يحدث في أطرافها (النهايات)، ومتى تصعد وتنزل (المشتقة)، ثم نلخص كل شيء في جدول ونرسم.\n▸ طرق وقواعد\n• ابدأ دائما بمجموعة التعريف.\n• اكتب المشتقة بشكل جداء عوامل.\n• تحقق من جدولك بقيمة أو قيمتين.\n▸ تمارين محلولة\n• تمرين 1: ادرس ⁦f(x) = (x² - 3x + 3)/(x - 1)⁩.\n• الحل:\n   – المجال ⁦ℝ \\ {1}⁩\n   – نكتب ⁦f(x) = x - 2 + 1/(x - 1)⁩\n   – النهاية عند ⁦±∞⁩ هي ⁦±∞⁩ والمستقيم ⁦y = x - 2⁩ مقارب مائل\n   – عند 1 البسط 1 موجب فالنهاية ⁦+∞⁩ من اليمين و ⁦-∞⁩ من اليسار فـ ⁦x = 1⁩ مقارب عمودي\n   – ⁦f′(x) = 1 - 1/(x - 1)² = x(x - 2)/(x - 1)²⁩\n   – f متزايدة على ⁦]-∞ ; 0]⁩ و ⁦[2 ; +∞[⁩ ومتناقصة على ⁦[0 ; 1[⁩ و ⁦]1 ; 2]⁩\n   – ⁦f(0) = -3⁩ و ⁦f(2) = 1⁩\n• تمرين 2: ادرس ⁦f(x) = -x³ + 3x²⁩.\n• الحل:\n   – المجال ⁦ℝ⁩\n   – ⁦f′(x) = -3x² + 6x = -3x(x - 2)⁩\n   – f متناقصة على ⁦]-∞ ; 0]⁩ ومتزايدة على ⁦[0 ; 2]⁩ ومتناقصة على ⁦[2 ; +∞[⁩\n   – ⁦f(0) = 0⁩ و ⁦f(2) = -8 + 12 = 4⁩\n   – النهاية ⁦+∞⁩ عند ⁦-∞⁩ و ⁦-∞⁩ عند ⁦+∞⁩\n▸ للحفظ\n• المجال ثم النهايات ثم المشتقة ثم الجدول ثم الرسم. للمقارب المائل اكتب ⁦f(x) = ax + b + g(x)⁩."},{"title":"4. التطبيقات الاقتصادية للمشتقة","content":"▸ المفاهيم\n• الإيراد ⁦R(x) = p·x⁩ (السعر × الكمية)\n• الربح ⁦B(x) = R(x) - C(x)⁩\n• التكلفة المتوسطة ⁦Cₘ(x) = C(x)/x⁩\n▸ الدوال الحدية\n• التكلفة الحدية ⁦C′(x)⁩\n• الإيراد الحدي ⁦R′(x)⁩\n• الربح الحدي ⁦B′(x) = R′(x) - C′(x)⁩\n▸ شروط الأمثلية\n• أكبر ربح: ⁦B′(x) = 0⁩ أي ⁦R′ = C′⁩\n• أدنى تكلفة متوسطة: ⁦C′(x) = Cₘ(x)⁩\n• تحقق من تغير الإشارة\n▸ مراحل الحل\n• اكتب الدالة المطلوبة بدلالة x\n• اشتقها وحل ⁦f′ = 0⁩\n• حدد إشارة المشتقة ثم فسر النتيجة\n▸ أخطاء شائعة\n• نسيان ⁦x > 0⁩ لأن الكمية موجبة\n• عدم التحقق أن القيمة المحصلة قيمة عظمى\n• نسيان وحدة القياس في الجواب\n▸ شرح مبسط\n• في الاقتصاد نريد غالبا أكبر ربح أو أقل تكلفة. المشتقة هي الأداة: ننشئ دالة الربح ونبحث أين تنعدم مشتقتها. والمشتقة تسمى هنا الدالة الحدية لأنها تقيس تكلفة أو ربح وحدة إضافية واحدة تقريبا.\n▸ طرق وقواعد\n• ابن دالة الربح ⁦B = R - C⁩ ثم اشتقها.\n• عند أكبر ربح يتساوى الإيراد الحدي والتكلفة الحدية.\n• عند أدنى تكلفة متوسطة تتساوى التكلفة الحدية والمتوسطة.\n▸ تمارين محلولة\n• تمرين 1: تكلفة إنتاج x وحدة: ⁦C(x) = x² + 20x + 400⁩. أوجد الإنتاج الذي يجعل التكلفة المتوسطة أصغر ما يمكن.\n• الحل:\n   – ⁦Cₘ(x) = x + 20 + 400/x⁩ من أجل ⁦x > 0⁩\n   – ⁦Cₘ′(x) = 1 - 400/x² = (x² - 400)/x²⁩\n   – تنعدم عند ⁦x = 20⁩ وهي سالبة قبله وموجبة بعده\n   – إذن أدنى قيمة عند 20 وهي ⁦Cₘ(20) = 20 + 20 + 20 = 60⁩\n   – ونجد ⁦C′(20) = 2×20 + 20 = 60⁩ أي ⁦C′(20) = Cₘ(20)⁩\n• تمرين 2: سعر بيع الوحدة ⁦p(x) = 100 - 2x⁩ والتكلفة السابقة. أوجد الإنتاج الذي يعطي أكبر ربح.\n• الحل:\n   – ⁦R(x) = x·p(x) = 100x - 2x²⁩\n   – ⁦B(x) = R(x) - C(x) = -3x² + 80x - 400⁩\n   – ⁦B′(x) = -6x + 80⁩ تنعدم عند ⁦x = 40/3 ≈ 13.33⁩\n   – موجبة قبلها وسالبة بعدها فهي قيمة عظمى\n   – ⁦B(40/3) = 400/3 ≈ 133.3⁩\n   – تحقق: ⁦R′ = 100 - 4x = 2x + 20 = C′⁩ عند ⁦x = 40/3⁩\n• تمرين 3: في المسألة السابقة أوجد مجال الإنتاج الذي يحقق ربحا موجبا.\n• الحل:\n   – نحل ⁦B(x) > 0⁩ أي ⁦3x² - 80x + 400 < 0⁩\n   – المميز ⁦Δ = 6400 - 4800 = 1600⁩\n   – الجذران ⁦(80 - 40)/6 = 20/3⁩ و ⁦(80 + 40)/6 = 20⁩\n   – الربح موجب من أجل ⁦20/3 < x < 20⁩\n▸ للحفظ\n• الربح ⁦B = R - C⁩. أكبر ربح: ⁦B′ = 0⁩ أي ⁦R′ = C′⁩. أدنى تكلفة متوسطة: ⁦C′ = Cₘ⁩."},{"title":"5. خواص ln ومجال التعريف","content":"▸ التعريف\n• ⁦ln⁩ معرفة على ⁦]0 ; +∞[⁩ فقط\n• ⁦ln 1 = 0⁩ و ⁦ln e = 1⁩\n• متزايدة تماما\n▸ الخواص\n• ⁦ln(ab) = ln a + ln b⁩\n• ⁦ln(a/b) = ln a - ln b⁩\n• ⁦ln(aⁿ) = n·ln a⁩ و ⁦ln(√a) = (1/2)·ln a⁩\n▸ العلاقة مع الأسية\n• ⁦ln(eˣ) = x⁩ من أجل كل x\n• ⁦e^(ln x) = x⁩ من أجل ⁦x > 0⁩\n• ⁦ln x = y ⇔ x = eʸ⁩\n▸ مجال التعريف\n• ⁦ln u(x)⁩ تتطلب ⁦u(x) > 0⁩\n• نحل متراجحة المجال أولا\n• المجال قد يكون اتحاد مجالين\n▸ أخطاء شائعة\n• ⁦ln(a + b) = ln a + ln b⁩ خطأ\n• نسيان شرط الموجب تماما\n• ⁦ln(-3)⁩ غير موجود\n▸ شرح مبسط\n• ln هي «عكس» الدالة الأسية. تحول الجداء إلى مجموع والأس إلى جداء. القاعدة الذهبية: ما بداخل ln يجب أن يكون موجبا تماما، ولا نحل شيئا قبل كتابة المجال.\n▸ طرق وقواعد\n• اكتب المجال قبل أي حل.\n• استعمل ⁦ln(ab)⁩ لتفكيك الجداء إلى مجموع.\n• لا تفكك المجموع داخل ln.\n▸ تمارين محلولة\n• تمرين 1: بسّط ⁦A = ln 8 - 3 ln 2⁩.\n• الحل:\n   – ⁦ln 8 = ln(2³) = 3 ln 2⁩\n   – إذن ⁦A = 3 ln 2 - 3 ln 2 = 0⁩\n• تمرين 2: علما أن ⁦a = ln 2⁩ و ⁦b = ln 3⁩ عبّر عن ⁦ln 12⁩ و ⁦ln(2/3)⁩.\n• الحل:\n   – ⁦ln 12 = ln(4×3) = 2 ln 2 + ln 3 = 2a + b⁩\n   – و ⁦ln(2/3) = ln 2 - ln 3 = a - b⁩\n• تمرين 3: عيّن مجال تعريف ⁦f(x) = ln(x² - 4)⁩ و ⁦g(x) = ln(3 - x)⁩.\n• الحل:\n   – نحل ⁦x² - 4 > 0⁩ أي ⁦x < -2⁩ أو ⁦x > 2⁩\n   – المجال ⁦]-∞ ; -2[ ∪ ]2 ; +∞[⁩\n   – وللثانية ⁦3 - x > 0⁩ أي ⁦x < 3⁩\n   – المجال ⁦]-∞ ; 3[⁩\n▸ للحفظ\n• ⁦ln(ab) = ln a + ln b⁩ و ⁦ln(aⁿ) = n·ln a⁩ و ⁦ln e = 1⁩. المجال: ما داخل ln موجب تماما."},{"title":"6. معادلات ومتراجحات ln","content":"▸ المعادلات\n• ⁦ln a = ln b ⇔ a = b⁩\n• ⁦ln x = k ⇔ x = eᵏ⁩\n• نرفض كل حل خارج المجال\n▸ المتراجحات\n• ⁦ln a ≤ ln b ⇔ a ≤ b⁩ (ln متزايدة)\n• ⁦ln x ≥ k ⇔ x ≥ eᵏ⁩\n• نتقاطع مع المجال\n▸ تغيير المتغير\n• نضع ⁦t = ln x⁩ عندما يظهر ⁦ln²⁩\n• نحل في ⁦t⁩ ثم نعود لـ ⁦x⁩\n• ⁦t⁩ تقبل أي عدد حقيقي\n▸ مراحل الحل\n• 1) المجال\n• 2) توحيد الطرفين بـ ln\n• 3) حذف ln أو الأسية\n• 4) التحقق من المجال\n▸ أخطاء شائعة\n• نسيان رفض الحل غير المقبول\n• قلب المتراجحة دون سبب لأن ln متزايدة\n• عدم كتابة الحل على شكل مجال\n▸ شرح مبسط\n• نحل معادلات ln بثلاث حركات: نكتب المجال، نجمع كل ln في طرف واحد على شكل ⁦ln A = ln B⁩ ثم نقول ⁦A = B⁩، وأخيرا نتفحص هل الحل ضمن المجال. في المتراجحات الاتجاه يبقى كما هو لأن ln متزايدة.\n▸ طرق وقواعد\n• وحّد الحدود: ⁦ln A + ln B = ln(AB)⁩.\n• عند وجود ⁦ln x⁩ مرفوعة للتربيع ضع ⁦t = ln x⁩.\n• ارفض الحلول خارج المجال.\n▸ تمارين محلولة\n• تمرين 1: حل ⁦ln(x - 2) + ln(x + 1) = ln 4⁩.\n• الحل:\n   – المجال ⁦x > 2⁩\n   – المعادلة ⁦ln[(x - 2)(x + 1)] = ln 4⁩ أي ⁦x² - x - 2 = 4⁩ و ⁦x² - x - 6 = 0⁩\n   – الجذران 3 و -2\n   – نرفض -2 لأنه خارج المجال\n   – الحل ⁦x = 3⁩\n• تمرين 2: حل المتراجحة ⁦ln(2x - 4) ≤ ln(x + 1)⁩.\n• الحل:\n   – المجال: ⁦2x - 4 > 0⁩ و ⁦x + 1 > 0⁩ أي ⁦x > 2⁩\n   – المتراجحة تعطي ⁦2x - 4 ≤ x + 1⁩ أي ⁦x ≤ 5⁩\n   – مجموعة الحلول ⁦]2 ; 5]⁩\n• تمرين 3: حل ⁦(ln x)² - 3 ln x + 2 = 0⁩.\n• الحل:\n   – المجال ⁦x > 0⁩\n   – نضع ⁦t = ln x⁩ فنجد ⁦t² - 3t + 2 = 0⁩ أي ⁦t = 1⁩ أو ⁦t = 2⁩\n   – إذن ⁦x = e⁩ أو ⁦x = e²⁩\n▸ للحفظ\n• ⁦ln A = ln B ⇔ A = B⁩ مع ⁦A, B > 0⁩. ⁦ln x = k ⇔ x = eᵏ⁩. تغيير المتغير ⁦t = ln x⁩."},{"title":"7. نهايات ومشتقة ln ودراسة دالة","content":"▸ المشتقة\n• ⁦(ln x)′ = 1/x⁩\n• ⁦(ln u)′ = u′/u⁩\n• المشتقة موجبة فـ ln متزايدة\n▸ النهايات\n• ⁦ln x → +∞⁩ عند ⁦+∞⁩\n• ⁦ln x → -∞⁩ عند ⁦0⁩ من اليمين\n• ⁦ln x / x → 0⁩ عند ⁦+∞⁩\n▸ نهايات مهمة\n• ⁦x·ln x → 0⁩ عند ⁦0⁩ من اليمين\n• ⁦ln x / xⁿ → 0⁩ عند ⁦+∞⁩\n• النمو البطيء لـ ln أمام x\n▸ الدراسة\n• المجال ⁦]0 ; +∞[⁩ غالبا\n• المقارب العمودي ⁦x = 0⁩\n• المماس عند ⁦x = 1⁩: ⁦y = x - 1⁩\n▸ أخطاء شائعة\n• نسيان قاعدة المركب ⁦u′/u⁩\n• حساب ⁦ln 0⁩\n• نسيان أن x·ln x شكل عدم تعيين يُحل بالنهاية المرجعية\n▸ شرح مبسط\n• ln تنمو ببطء شديد: تذهب إلى اللانهاية لكن أبطأ من x. لهذا تفوز x دائما في النهايات المركبة مثل ⁦ln x / x⁩ فنجدها تؤول إلى 0. ودراسة دالة فيها ln تتبع نفس الخطوات: المجال، النهايات، المشتقة (فيها ⁦1/x⁩)، الجدول.\n▸ طرق وقواعد\n• استعمل النهايات المرجعية بدل المحاولة.\n• ⁦(ln u)′ = u′/u⁩ ثم ادرس الإشارة.\n• عند 0 من اليمين ln تؤول إلى ⁦-∞⁩.\n▸ تمارين محلولة\n• تمرين 1: ادرس ⁦f(x) = x - ln x⁩ على ⁦]0 ; +∞[⁩ واستنتج إشارتها.\n• الحل:\n   – ⁦f′(x) = 1 - 1/x = (x - 1)/x⁩\n   – سالبة على ⁦]0 ; 1]⁩ وموجبة على ⁦[1 ; +∞[⁩\n   – القيمة الصغرى ⁦f(1) = 1 > 0⁩\n   – عند ⁦0⁩ من اليمين ⁦-ln x → +∞⁩ فالنهاية ⁦+∞⁩\n   – عند ⁦+∞⁩ نكتب ⁦f(x) = x(1 - ln x / x)⁩ فالنهاية ⁦+∞⁩\n   – بما أن الأصغر موجب فإن ⁦f(x) > 0⁩ من أجل كل ⁦x > 0⁩\n• تمرين 2: ادرس ⁦g(x) = ln x / x⁩ على ⁦]0 ; +∞[⁩.\n• الحل:\n   – ⁦g′(x) = (1 - ln x)/x²⁩\n   – موجبة على ⁦]0 ; e]⁩ وسالبة على ⁦[e ; +∞[⁩\n   – القيمة العظمى ⁦g(e) = 1/e⁩\n   – النهاية عند ⁦+∞⁩ هي 0 فالمستقيم ⁦y = 0⁩ مقارب أفقي\n   – عند ⁦0⁩ من اليمين ⁦ln x → -∞⁩ والمقام موجب فالنهاية ⁦-∞⁩ و ⁦x = 0⁩ مقارب عمودي\n• تمرين 3: احسب مشتقة ⁦h(x) = ln(x² + 1)⁩.\n• الحل:\n   – ⁦h′(x) = 2x/(x² + 1)⁩\n   – إشارتها من إشارة x فـ h متناقصة على ⁦]-∞ ; 0]⁩ ومتزايدة على ⁦[0 ; +∞[⁩\n▸ للحفظ\n• ⁦(ln u)′ = u′/u⁩. ⁦ln x / x → 0⁩ عند ⁦+∞⁩. ⁦x·ln x → 0⁩ عند ⁦0⁩. نمو ln بطيء."},{"title":"8. خواص الدالة الأسية ومشتقتها","content":"▸ التعريف\n• ⁦eˣ > 0⁩ من أجل كل x\n• ⁦e⁰ = 1⁩ و ⁦e¹ = e⁩\n• متزايدة تماما على ⁦ℝ⁩\n▸ الخواص\n• ⁦eᵃ⁺ᵇ = eᵃ·eᵇ⁩\n• ⁦eᵃ⁻ᵇ = eᵃ/eᵇ⁩\n• ⁦(eᵃ)ⁿ = eⁿᵃ⁩\n▸ المشتقة\n• ⁦(eˣ)′ = eˣ⁩\n• ⁦(eᵘ)′ = u′·eᵘ⁩\n• ⁦(eᵃˣ⁺ᵇ)′ = a·eᵃˣ⁺ᵇ⁩\n▸ العلاقة مع ln\n• ⁦ln(eˣ) = x⁩\n• ⁦e^(ln x) = x⁩ من أجل ⁦x > 0⁩\n• الأسية و ln دالتان عكسيتان\n▸ أخطاء شائعة\n• ⁦eᵃ + eᵇ = eᵃ⁺ᵇ⁩ خطأ\n• نسيان أن الأسية موجبة دائما\n• نسيان ⁦u′⁩ في مشتقة المركب\n▸ شرح مبسط\n• الدالة الأسية تمثل النمو السريع: تتضاعف بسرعة كبيرة. ميزتها أن مشتقتها تساوي نفسها. وهي دائما موجبة مهما كان x، وهذا يختصر كثيرا من دراسة الإشارة.\n▸ طرق وقواعد\n• إشارة ⁦eᵘ⁩ موجبة دائما فلا تدخل في الإشارة.\n• لتبسيط جداء أسيات اجمع الأسس.\n• اشتق ⁦eᵘ⁩ بضرب ⁦u′⁩.\n▸ تمارين محلولة\n• تمرين 1: بسّط ⁦A = e²ˣ·e⁻ˣ/eˣ⁺¹⁩.\n• الحل:\n   – نجمع الأسس: ⁦2x - x - (x + 1) = -1⁩\n   – إذن ⁦A = e⁻¹ = 1/e⁩\n• تمرين 2: احسب مشتقة ⁦f(x) = (x + 1)eˣ⁩.\n• الحل:\n   – ⁦f′(x) = eˣ + (x + 1)eˣ = (x + 2)eˣ⁩\n   – الإشارة من ⁦x + 2⁩ لأن ⁦eˣ > 0⁩\n• تمرين 3: احسب مشتقة ⁦g(x) = e⁻²ˣ⁺¹⁩.\n• الحل:\n   – ⁦g′(x) = -2·e⁻²ˣ⁺¹⁩\n   – وهي سالبة دائما فـ g متناقصة على ⁦ℝ⁩\n▸ للحفظ\n• ⁦eˣ > 0⁩ و ⁦eᵃ⁺ᵇ = eᵃ·eᵇ⁩ و ⁦(eᵘ)′ = u′·eᵘ⁩ و ⁦(eˣ)′ = eˣ⁩."},{"title":"9. معادلات ومتراجحات أسية","content":"▸ معادلات بسيطة\n• ⁦e^(A) = e^(B) ⇔ A = B⁩\n• ⁦eˣ = k ⇔ x = ln k⁩ (لـ ⁦k > 0⁩)\n• ⁦eˣ = -2⁩ مستحيلة\n▸ متراجحات\n• ⁦e^(A) ≤ e^(B) ⇔ A ≤ B⁩\n• ⁦eˣ ≥ k ⇔ x ≥ ln k⁩ (لـ ⁦k > 0⁩)\n• الأسية متزايدة فالاتجاه محفوظ\n▸ تغيير المتغير\n• معادلة فيها ⁦e²ˣ⁩ و ⁦eˣ⁩\n• نضع ⁦t = eˣ⁩ مع ⁦t > 0⁩\n• نحل ثم نرفض ⁦t ≤ 0⁩\n▸ مراحل الحل\n• 1) اجعل الطرفين بنفس الشكل\n• 2) استعمل ln إذا لزم\n• 3) تحقق من ⁦t > 0⁩\n▸ أخطاء شائعة\n• قبول ⁦t⁩ سالب في ⁦t = eˣ⁩\n• نسيان تطبيق ln على الطرفين\n• ⁦ln⁩ لعدد سالب أو معدوم\n▸ شرح مبسط\n• لحل معادلة أسية إما نوحّد الأساسين (نقول ⁦e^(A) = e^(B)⁩ فـ ⁦A = B⁩) أو نستعمل ln لنزيل الأسية. وعندما نجد ⁦e²ˣ⁩ مع ⁦eˣ⁩ نضع ⁦t = eˣ⁩ فتتحول المعادلة إلى معادلة من الدرجة الثانية عادية.\n▸ طرق وقواعد\n• تذكّر: ⁦eˣ > 0⁩ فلا حل لـ ⁦eˣ = k⁩ مع ⁦k < 0⁩.\n• طبّق ln على طرفين موجبين فقط.\n• بعد ⁦t = eˣ⁩ ارجع لـ x بـ ⁦x = ln t⁩.\n▸ تمارين محلولة\n• تمرين 1: حل ⁦e²ˣ⁺¹ = e³⁩.\n• الحل:\n   – نتساوى الأسس: ⁦2x + 1 = 3⁩ أي ⁦x = 1⁩\n• تمرين 2: حل ⁦e²ˣ - 5eˣ + 6 = 0⁩.\n• الحل:\n   – نضع ⁦t = eˣ⁩ مع ⁦t > 0⁩ فنجد ⁦t² - 5t + 6 = 0⁩ أي ⁦t = 2⁩ أو ⁦t = 3⁩\n   – إذن ⁦x = ln 2⁩ أو ⁦x = ln 3⁩\n• تمرين 3: حل المتراجحة ⁦eˣ ≥ 4⁩.\n• الحل:\n   – نطبق ln المتزايدة: ⁦x ≥ ln 4 = 2 ln 2⁩\n   – مجموعة الحلول ⁦[ln 4 ; +∞[⁩\n• تمرين 4: حل ⁦eˣ = -2⁩.\n• الحل:\n   – الأسية موجبة تماما دائما إذن المعادلة لا تقبل حلا\n▸ للحفظ\n• ⁦e^(A) = e^(B) ⇔ A = B⁩ و ⁦eˣ = k ⇔ x = ln k⁩ مع ⁦k > 0⁩. نضع ⁦t = eˣ⁩ مع ⁦t > 0⁩."},{"title":"10. نهايات ودراسة دالة أسية","content":"▸ النهايات\n• ⁦eˣ → +∞⁩ عند ⁦+∞⁩\n• ⁦eˣ → 0⁩ عند ⁦-∞⁩\n• ⁦eˣ/x → +∞⁩ عند ⁦+∞⁩\n▸ نهايات مهمة\n• ⁦x·eˣ → 0⁩ عند ⁦-∞⁩\n• ⁦xⁿ·e⁻ˣ → 0⁩ عند ⁦+∞⁩\n• الأسية تفوز على كثير الحدود\n▸ المقارب\n• ⁦y = 0⁩ مقارب أفقي عند ⁦-∞⁩ لـ ⁦eˣ⁩\n• وفي ⁦x·eˣ⁩ عند ⁦-∞⁩ كذلك\n• مقارب مائل إذا وُجد ⁦ax + b⁩\n▸ الدراسة\n• ⁦(eᵘ)′ = u′eᵘ⁩ والإشارة من ⁦u′⁩\n• القيم الحدية من ⁦f′ = 0⁩\n• المماس ثم الرسم\n▸ أخطاء شائعة\n• الخلط بين النهاية عند ⁦+∞⁩ و ⁦-∞⁩\n• نسيان النهاية المرجعية عند ⁦-∞⁩\n• الخطأ في إشارة المشتقة\n▸ شرح مبسط\n• الأسية تنمو أسرع من أي كثير حدود، لذا في النهايات المركبة تفوز الأسية دائما. وعند ⁦-∞⁩ تقترب من الصفر فتعطي مقاربا أفقيا. دراسة الدالة نفس الخطوات: المجال (غالبا ⁦ℝ⁩)، النهايات، المشتقة، الجدول.\n▸ طرق وقواعد\n• عند ⁦-∞⁩ الأسية تؤول إلى 0.\n• ⁦x·eˣ⁩ عند ⁦-∞⁩ تؤول إلى 0 (نهاية مرجعية).\n• إشارة المشتقة تأتي من العامل غير الأسي.\n▸ تمارين محلولة\n• تمرين 1: ادرس ⁦f(x) = (x - 1)eˣ⁩ على ⁦ℝ⁩.\n• الحل:\n   – ⁦f′(x) = eˣ + (x - 1)eˣ = x·eˣ⁩\n   – سالبة على ⁦]-∞ ; 0]⁩ وموجبة على ⁦[0 ; +∞[⁩\n   – ⁦f(0) = -1⁩ قيمة صغرى\n   – عند ⁦+∞⁩ النهاية ⁦+∞⁩\n   – عند ⁦-∞⁩ نكتب ⁦f(x) = x·eˣ - eˣ → 0⁩ فالمستقيم ⁦y = 0⁩ مقارب أفقي\n   – وتنعدم f عند ⁦x = 1⁩\n• تمرين 2: ادرس ⁦g(x) = x + e⁻ˣ⁩ على ⁦ℝ⁩.\n• الحل:\n   – ⁦g′(x) = 1 - e⁻ˣ⁩\n   – تنعدم عند ⁦x = 0⁩ وسالبة على ⁦]-∞ ; 0]⁩ وموجبة على ⁦[0 ; +∞[⁩\n   – القيمة الصغرى ⁦g(0) = 1⁩\n   – النهاية ⁦+∞⁩ عند طرفيها\n   – ⁦g(x) - x = e⁻ˣ → 0⁩ عند ⁦+∞⁩ فالمستقيم ⁦y = x⁩ مقارب مائل\n   – المنحنى فوقه لأن ⁦e⁻ˣ > 0⁩\n▸ للحفظ\n• ⁦eˣ → 0⁩ عند ⁦-∞⁩ و ⁦x·eˣ → 0⁩ عند ⁦-∞⁩ و ⁦eˣ/x → +∞⁩ عند ⁦+∞⁩. مشتقة: ⁦u′·eᵘ⁩."},{"title":"11. المتتالية الحسابية","content":"▸ التعريف\n• ⁦uₙ₊₁ = uₙ + r⁩ حيث r الأساس\n• ⁦r > 0⁩ متزايدة و ⁦r < 0⁩ متناقصة\n• نبرهن بإثبات أن ⁦uₙ₊₁ - uₙ⁩ ثابت\n▸ الحد العام\n• ⁦uₙ = u₀ + n·r⁩\n• ⁦uₙ = uₚ + (n - p)·r⁩\n• مثال: ⁦u₀ = 4⁩ و ⁦r = 3⁩ فـ ⁦u₅ = 19⁩\n▸ المجموع\n• ⁦S = k × (uₚ + uₙ)/2⁩ حيث ⁦k⁩ عدد الحدود\n• عدد الحدود من p إلى n هو ⁦n - p + 1⁩\n• ⁦1 + 2 + ... + n = n(n + 1)/2⁩\n▸ خاصية الوسط\n• ⁦b⁩ وسط حسابي لـ ⁦a⁩ و ⁦c⁩ إذا ⁦2b = a + c⁩\n• الفرق بين حدين متتاليين ثابت\n• تطبيق: الأجور والادخار بزيادة ثابتة\n▸ أخطاء شائعة\n• خطأ في عدد الحدود في المجموع\n• الخلط بين ⁦u₀⁩ و ⁦u₁⁩ كحد أول\n• نسيان ⁦-p⁩ في الصيغة العامة\n▸ شرح مبسط\n• المتتالية الحسابية هي سلم: تصعد (أو تنزل) بنفس الخطوة r في كل مرة. وللمجموع حيلة غاوس المشهورة: نجمع الحد الأول والأخير فنضرب الناتج في نصف عدد الحدود.\n▸ طرق وقواعد\n• اكتب ⁦uₙ⁩ بدلالة حد معلوم.\n• للمجموع احسب عدد الحدود ثم الحد الأخير.\n• لإثبات أنها حسابية احسب ⁦uₙ₊₁ - uₙ⁩.\n▸ تمارين محلولة\n• تمرين 1: متتالية حسابية فيها ⁦u₂ = 5⁩ و ⁦u₇ = 20⁩. أوجد r و ⁦u₀⁩ و ⁦uₙ⁩ ثم مجموع ⁦u₀⁩ إلى ⁦u₉⁩.\n• الحل:\n   – ⁦u₇ = u₂ + 5r⁩ فـ ⁦20 = 5 + 5r⁩ أي ⁦r = 3⁩\n   – ⁦u₀ = u₂ - 2r = 5 - 6 = -1⁩\n   – ⁦uₙ = -1 + 3n⁩\n   – ⁦u₉ = 26⁩\n   – عدد الحدود 10\n   – ⁦S = 10 × (-1 + 26)/2 = 125⁩\n• تمرين 2: راتب موظف في السنة الأولى 30000 دج ويزيد 1500 دج كل سنة. ما راتبه في السنة 10 وما مجموع ما يتقاضاه في 10 سنوات؟\n• الحل:\n   – ⁦u₁ = 30000⁩ و ⁦r = 1500⁩\n   – ⁦u₁₀ = 30000 + 9×1500 = 43500⁩ دج\n   – ⁦S = 10 × (30000 + 43500)/2 = 367500⁩ دج\n• تمرين 3: بيّن أن ⁦uₙ = 5 - 2n⁩ متتالية حسابية.\n• الحل:\n   – ⁦uₙ₊₁ - uₙ = 5 - 2(n + 1) - (5 - 2n) = -2⁩\n   – فرق ثابت إذن حسابية أساسها ⁦-2⁩ وهي متناقصة\n▸ للحفظ\n• حسابية: ⁦uₙ₊₁ = uₙ + r⁩ و ⁦uₙ = uₚ + (n - p)·r⁩. المجموع ⁦S = k × (uₚ + uₙ)/2⁩ حيث k عدد الحدود."},{"title":"12. المتتالية الهندسية","content":"▸ التعريف\n• ⁦uₙ₊₁ = q·uₙ⁩ حيث q الأساس\n• نبرهن بإثبات أن ⁦uₙ₊₁/uₙ⁩ ثابت\n• ⁦q > 1⁩ تزايد، ⁦0 < q < 1⁩ تناقص\n▸ الحد العام\n• ⁦uₙ = u₀·qⁿ⁩\n• ⁦uₙ = uₚ·qⁿ⁻ᵖ⁩\n• مثال: ⁦u₀ = 3⁩ و ⁦q = 2⁩ فـ ⁦u₄ = 48⁩\n▸ المجموع\n• ⁦S = uₚ × (1 - qᵏ)/(1 - q)⁩ لـ ⁦q ≠ 1⁩ حيث ⁦k⁩ عدد الحدود\n• إذا ⁦q = 1⁩ فـ ⁦S = k × uₚ⁩\n• ⁦1 + q + ... + qⁿ = (1 - qⁿ⁺¹)/(1 - q)⁩\n▸ النهاية\n• ⁦|q| < 1⁩ ⇒ ⁦qⁿ → 0⁩\n• ⁦q > 1⁩ ⇒ ⁦qⁿ → +∞⁩\n• تطبيق: تناقص الأسعار وتزايد السكان\n▸ أخطاء شائعة\n• الخلط بين ⁦1 - q⁩ و ⁦q - 1⁩ في المجموع\n• عدد الحدود غير صحيح\n• خطأ في تحويل النسبة المئوية إلى معامل\n▸ شرح مبسط\n• المتتالية الهندسية تُضرب في نفس العدد q في كل خطوة. زيادة بنسبة 3 بالمئة تعني الضرب في 1.03 ونقصان بنسبة 5 بالمئة يعني الضرب في 0.95. وهي الأداة الطبيعية للنمو والتناقص بالنسب.\n▸ طرق وقواعد\n• أساس النسبة: زيادة ⁦t%⁩ ⇒ ⁦q = 1 + t/100⁩، نقصان ⇒ ⁦q = 1 - t/100⁩.\n• لحساب q من حدين: اقسم ثم خذ الجذر المناسب.\n• تحقق من إشارة الحدود قبل اختيار الجذر.\n▸ تمارين محلولة\n• تمرين 1: متتالية هندسية حدودها موجبة فيها ⁦v₁ = 3⁩ و ⁦v₃ = 12⁩. أوجد q و ⁦vₙ⁩ ثم مجموع الحدود الستة الأولى.\n• الحل:\n   – ⁦v₃ = v₁·q²⁩ فـ ⁦q² = 4⁩ و ⁦q = 2⁩ لأن الحدود موجبة\n   – ⁦vₙ = 3·2ⁿ⁻¹⁩\n   – ⁦S = 3×(1 - 2⁶)/(1 - 2) = 3×63 = 189⁩\n• تمرين 2: سعر آلة 20000 دج ينقص 5% كل سنة. احسب سعرها بعد 4 سنوات.\n• الحل:\n   – النقصان 5% يعني الضرب في ⁦0.95⁩\n   – ⁦20000×0.95⁴ = 20000×0.8145 ≈ 16290⁩ دج\n• تمرين 3: متتالية هندسية أساسها ⁦1/2⁩ وحدها الأول 8. احسب ⁦u₅⁩ ومجموع الستة الأولى.\n• الحل:\n   – ⁦u₅ = 8×(1/2)⁵ = 8/32 = 0.25⁩\n   – المجموع ⁦8×(1 - (1/2)⁶)/(1 - 1/2) = 16×(63/64) = 15.75⁩\n▸ للحفظ\n• هندسية: ⁦uₙ₊₁ = q·uₙ⁩ و ⁦uₙ = uₚ·qⁿ⁻ᵖ⁩. المجموع ⁦S = uₚ × (1 - qᵏ)/(1 - q)⁩. زيادة ⁦t%⁩ تعني ⁦q = 1 + t/100⁩."},{"title":"13. المتتالية من الشكل u_{n+1} = a·u_n + b","content":"▸ الفكرة\n• علاقة تراجعية تجمع ضربا وجمعا\n• نبحث عن العدد الثابت ⁦α⁩ الذي يحقق ⁦α = aα + b⁩\n• ⁦α = b/(1 - a)⁩ لـ ⁦a ≠ 1⁩\n▸ المتتالية المساعدة\n• نضع ⁦vₙ = uₙ - α⁩\n• فنحصل على ⁦vₙ₊₁ = a·vₙ⁩\n• إذن ⁦(vₙ)⁩ هندسية أساسها a\n▸ الحد العام\n• ⁦vₙ = v₀·aⁿ⁩\n• ⁦uₙ = α + (u₀ - α)·aⁿ⁩\n• النهاية ⁦α⁩ إذا ⁦|a| < 1⁩\n▸ خطوات الحل\n• 1) احسب α\n• 2) عرّف ⁦vₙ⁩ وأثبت أنها هندسية\n• 3) اكتب ⁦vₙ⁩ ثم ⁦uₙ⁩\n▸ أخطاء شائعة\n• خطأ في حساب α\n• نسيان أن ⁦v₀ = u₀ - α⁩ وليس ⁦u₀⁩\n• إثبات الهندسية دون استعمال العلاقة\n▸ شرح مبسط\n• نريد أن نتخلص من الجزء «+b» ليبقى فقط الضرب. نبحث عن قيمة ثابتة α إذا بدأنا منها لم تتغير المتتالية. ثم ندرس البعد عن α: هذا البعد يُضرب في a في كل خطوة، فيصبح هندسيا.\n▸ طرق وقواعد\n• α حل المعادلة ⁦α = aα + b⁩.\n• برهان الهندسية: ⁦vₙ₊₁ = uₙ₊₁ - α = a(uₙ - α) = a·vₙ⁩.\n• في النهاية ارجع إلى ⁦uₙ = vₙ + α⁩.\n▸ تمارين محلولة\n• تمرين 1: ⁦u₀ = 1⁩ و ⁦uₙ₊₁ = 0.5uₙ + 3⁩. أوجد ⁦uₙ⁩ بدلالة n ثم نهايتها.\n• الحل:\n   – ⁦α = 3/(1 - 0.5) = 6⁩\n   – ⁦vₙ = uₙ - 6⁩ فـ ⁦vₙ₊₁ = 0.5uₙ + 3 - 6 = 0.5(uₙ - 6) = 0.5vₙ⁩\n   – هندسية أساسها 0.5 وحدها الأول ⁦v₀ = -5⁩\n   – ⁦vₙ = -5·0.5ⁿ⁩ و ⁦uₙ = 6 - 5·0.5ⁿ⁩\n   – تحقق: ⁦u₁ = 6 - 2.5 = 3.5⁩\n   – والنهاية 6\n• تمرين 2: ادخار: رصيد أول السنة 1000 دج، كل سنة يزيد 4% وتضاف 500 دج. ⁦uₙ₊₁ = 1.04uₙ + 500⁩. أوجد ⁦uₙ⁩ وقدّر ⁦u₅⁩.\n• الحل:\n   – ⁦α = 500/(1 - 1.04) = -12500⁩\n   – ⁦vₙ = uₙ + 12500⁩ هندسية أساسها 1.04 و ⁦v₀ = 13500⁩\n   – ⁦uₙ = 13500×1.04ⁿ - 12500⁩\n   – تحقق: ⁦u₁ = 14040 - 12500 = 1540⁩\n   – و ⁦u₅ = 13500×1.2167 - 12500 ≈ 3925⁩ دج\n▸ للحفظ\n• ⁦uₙ₊₁ = a·uₙ + b⁩: العدد ⁦α = b/(1 - a)⁩. ⁦vₙ = uₙ - α⁩ هندسية أساسها a و ⁦uₙ = α + (u₀ - α)·aⁿ⁩."},{"title":"14. الفوائد والتسديدات (رياضيات مالية)","content":"▸ الفائدة البسيطة\n• ⁦Cₙ = C(1 + n·t)⁩ (فائدة ثابتة)\n• متتالية حسابية\n• ⁦t⁩ معدل الفائدة السنوي\n▸ الفائدة المركبة\n• ⁦Cₙ = C(1 + t)ⁿ⁩\n• متتالية هندسية أساسها ⁦1 + t⁩\n• الفائدة تُضاف إلى الرأس المال كل سنة\n▸ دفعات منتظمة\n• قيمة نهائية لدفعات ⁦a⁩ في نهاية كل سنة\n• ⁦V = a·((1 + t)ⁿ - 1)/t⁩\n• مجموع هندسي\n▸ مدة المضاعفة\n• نحل ⁦(1 + t)ⁿ = 2⁩\n• ⁦n = ln 2 / ln(1 + t)⁩\n• نأخذ العدد الصحيح الأكبر\n▸ أخطاء شائعة\n• الخلط بين البسيطة والمركبة\n• تحويل المعدل: ⁦5% = 0.05⁩\n• نسيان تدوير المدة إلى عدد سنوات صحيح\n▸ شرح مبسط\n• في الفائدة البسيطة الفائدة تُحسب دائما على المبلغ الأصلي فنزيد مبلغا ثابتا كل سنة (حسابية). وفي المركبة نحسبها على كل ما تراكم فنضرب في نفس العدد كل سنة (هندسية). ولهذا المركبة أكبر على المدى الطويل.\n▸ طرق وقواعد\n• اكتب المعدل كعدد عشري: ⁦t = r/100⁩ (r المعدل).\n• البسيطة ⇒ حسابية، المركبة ⇒ هندسية.\n• للمدة استعمل ln.\n▸ تمارين محلولة\n• تمرين 1: وُضع مبلغ 50000 دج بمعدل 6% لمدة 3 سنوات. قارن الفائدة البسيطة بالمركبة.\n• الحل:\n   – البسيطة: ⁦50000×(1 + 3×0.06) = 50000×1.18 = 59000⁩ دج\n   – المركبة: ⁦50000×1.06³ = 50000×1.191016 ≈ 59551⁩ دج\n   – المركبة أكبر بنحو 551 دج\n• تمرين 2: يدفع شخص 2000 دج في نهاية كل سنة لمدة 5 سنوات بمعدل مركب 5%. ما القيمة النهائية؟\n• الحل:\n   – ⁦V = 2000×(1.05⁵ - 1)/0.05 = 2000×(0.27628/0.05) = 2000×5.5256 ≈ 11051⁩ دج\n• تمرين 3: بعد كم سنة يتضاعف مبلغ بمعدل مركب 7%؟\n• الحل:\n   – نحل ⁦1.07ⁿ ≥ 2⁩ فـ ⁦n ≥ ln 2 / ln 1.07 ≈ 0.6931/0.0677 ≈ 10.24⁩\n   – إذن بعد 11 سنة\n▸ للحفظ\n• بسيطة: ⁦C(1 + n·t)⁩. مركبة: ⁦C(1 + t)ⁿ⁩. دفعات: ⁦a·((1 + t)ⁿ - 1)/t⁩. مضاعفة: ⁦n = ln 2 / ln(1 + t)⁩."},{"title":"15. الدوال الأصلية","content":"▸ التعريف\n• ⁦F⁩ أصلية لـ ⁦f⁩ إذا ⁦F′ = f⁩\n• أي أصلية أخرى: ⁦F + C⁩\n• الشرط الابتدائي يحدد ⁦C⁩\n▸ أصليات مألوفة\n• ⁦xⁿ⁩ ⟶ ⁦xⁿ⁺¹/(n + 1)⁩\n• ⁦1/x⁩ ⟶ ⁦ln x⁩ (على ⁦x > 0⁩)\n• ⁦eˣ⁩ ⟶ ⁦eˣ⁩\n▸ أشكال مركبة\n• ⁦u′/u⁩ ⟶ ⁦ln u⁩ (⁦u > 0⁩)\n• ⁦u′·eᵘ⁩ ⟶ ⁦eᵘ⁩\n• ⁦eᵃˣ⁺ᵇ⁩ ⟶ ⁦eᵃˣ⁺ᵇ/a⁩\n▸ الخطوات\n• اقرأ شكل الدالة\n• طابقه مع الجدول\n• تحقق بالاشتقاق\n▸ أخطاء شائعة\n• نسيان الثابت ⁦C⁩\n• قسمة خاطئة على المعامل a في ⁦eᵃˣ⁺ᵇ⁩\n• نسيان ⁦u′⁩ في شكل ⁦u′/u⁩\n▸ شرح مبسط\n• إيجاد الأصلية هو عكس الاشتقاق: نبحث عن دالة مشتقتها هي الدالة المعطاة. ولهذا نتحقق دائما باشتقاق النتيجة. الثابت C يظهر لأن مشتقة أي عدد ثابت هي صفر.\n▸ طرق وقواعد\n• اكتب الدالة على شكل مجموع ثم أوجد أصلية كل حد.\n• تحقق بالاشتقاق.\n• استعمل شرطا ابتدائيا لإيجاد C.\n▸ تمارين محلولة\n• تمرين 1: أوجد الأصلية F للدالة ⁦f(x) = 3x² - 4x + 1⁩ التي تحقق ⁦F(1) = 5⁩.\n• الحل:\n   – ⁦F(x) = x³ - 2x² + x + C⁩\n   – ⁦F(1) = 1 - 2 + 1 + C = C = 5⁩\n   – إذن ⁦F(x) = x³ - 2x² + x + 5⁩\n• تمرين 2: أوجد أصلية ⁦f(x) = 2/x + e²ˣ⁩ على ⁦]0 ; +∞[⁩.\n• الحل:\n   – ⁦F(x) = 2 ln x + e²ˣ/2 + C⁩\n   – التحقق: ⁦F′(x) = 2/x + e²ˣ = f(x)⁩\n• تمرين 3: أوجد أصلية ⁦f(x) = 2x/(x² + 1)⁩.\n• الحل:\n   – هي من الشكل ⁦u′/u⁩ مع ⁦u = x² + 1 > 0⁩\n   – إذن ⁦F(x) = ln(x² + 1) + C⁩\n▸ للحفظ\n• ⁦F′ = f⁩. ⁦xⁿ⁩ ⟶ ⁦xⁿ⁺¹/(n + 1)⁩ و ⁦1/x⁩ ⟶ ⁦ln x⁩ و ⁦u′/u⁩ ⟶ ⁦ln u⁩ و ⁦eᵃˣ⁺ᵇ⁩ ⟶ ⁦eᵃˣ⁺ᵇ/a⁩. لا تنس الثابت C."},{"title":"16. الحساب التكاملي والمساحات","content":"▸ التعريف\n• ⁦∫ₐᵇ f(x)dx = F(b) - F(a)⁩\n• F أي أصلية لـ f\n• نكتب ⁦[F(x)]ₐᵇ⁩\n▸ الخواص\n• الخطية: ⁦∫(f + g) = ∫f + ∫g⁩\n• ⁦∫ₐᵇ f = -∫_(b)ᵃ f⁩\n• علاقة شال: ⁦∫ₐ^(c) = ∫ₐᵇ + ∫_(b)^(c)⁩\n▸ المساحة\n• ⁦f ≥ 0⁩: المساحة ⁦∫ₐᵇ f⁩\n• ⁦f ≤ 0⁩: المساحة ⁦-∫ₐᵇ f⁩\n• بين منحنيين: ⁦∫(f - g)⁩ مع ⁦f ≥ g⁩\n▸ القيمة المتوسطة\n• ⁦μ = (1/(b - a))·∫ₐᵇ f(x)dx⁩\n• تطبيق: متوسط التكلفة أو الإيراد\n• الوحدة: وحدة المساحة\n▸ أخطاء شائعة\n• نسيان الإشارة السالبة عند ⁦f ≤ 0⁩\n• خلط ترتيب ⁦F(b) - F(a)⁩\n• تكامل خطأ لدالة مركبة\n▸ شرح مبسط\n• التكامل المحدد يعطي المساحة المحصورة بين المنحنى ومحور الفواصل. نحسبه بإيجاد أصلية ثم الفرق بين قيمتيها عند الطرفين. وفي الاقتصاد يعطي التراكم: مثلا مجموع التكلفة الحدية يعطي التكلفة المتغيرة.\n▸ طرق وقواعد\n• أوجد أصلية ثم احسب ⁦F(b) - F(a)⁩.\n• للمساحة ادرس إشارة f أولا.\n• وحدة المساحة = وحدة الطول × وحدة الطول.\n▸ تمارين محلولة\n• تمرين 1: احسب ⁦∫₀² (3x² + 1)dx⁩.\n• الحل:\n   – أصلية الدالة ⁦x³ + x⁩\n   – ⁦[x³ + x]₀² = (8 + 2) - 0 = 10⁩\n• تمرين 2: احسب مساحة الحيز المحصور بين ⁦f(x) = x² - 4⁩ ومحور الفواصل على ⁦[-2 ; 2]⁩.\n• الحل:\n   – على هذا المجال ⁦f ≤ 0⁩ فالمساحة ⁦-∫₋₂²(x² - 4)dx = ∫₋₂²(4 - x²)dx⁩\n   – ⁦[4x - x³/3]₋₂² = (8 - 8/3) - (-8 + 8/3) = 16 - 16/3 = 32/3⁩ وحدة مساحة\n• تمرين 3: التكلفة الحدية ⁦C′(x) = 3x + 10⁩ والتكاليف الثابتة 50. أوجد ⁦C(x)⁩ والتكلفة المتغيرة لأول 10 وحدات.\n• الحل:\n   – ⁦C(x) = 1.5x² + 10x + 50⁩ لأن ⁦C(0) = 50⁩\n   – التكلفة المتغيرة ⁦∫₀¹⁰(3x + 10)dx = [1.5x² + 10x]₀¹⁰ = 150 + 100 = 250⁩\n• تمرين 4: احسب القيمة المتوسطة لـ ⁦f(x) = e²ˣ⁩ على ⁦[0 ; 1]⁩.\n• الحل:\n   – ⁦∫₀¹ e²ˣdx = [e²ˣ/2]₀¹ = (e² - 1)/2 ≈ 3.19⁩\n   – وطول المجال 1 فالقيمة المتوسطة ⁦≈ 3.19⁩\n▸ للحفظ\n• ⁦∫ₐᵇ f(x)dx = F(b) - F(a)⁩. المساحة للدالة الموجبة هي التكامل وللسالبة هي مقابله. المتوسط ⁦(1/(b - a))·∫f⁩."},{"title":"17. سلسلة إحصائية بمتغيرين","content":"▸ المعطيات\n• سلسلة أزواج ⁦(xᵢ ; yᵢ)⁩\n• سحابة النقاط في معلم\n• x متغير مفسِّر وy متغير مفسَّر\n▸ المتوسطات\n• ⁦x̄ = Σxᵢ/n⁩ و ⁦ȳ = Σyᵢ/n⁩\n• النقطة المتوسطة ⁦G(x̄ ; ȳ)⁩\n• تقع على مستقيم التعديل\n▸ التباين\n• ⁦V(x) = Σxᵢ²/n - x̄²⁩\n• ⁦σₓ = √V(x)⁩\n• نفس القانون لـ y\n▸ التغاير\n• ⁦cov(x,y) = Σxᵢ·yᵢ/n - x̄·ȳ⁩\n• إشارته تدل على اتجاه العلاقة\n• موجب: متغيران يتزايدان معا\n▸ أخطاء شائعة\n• خلط ⁦Σxᵢ²⁩ مع ⁦(Σxᵢ)²⁩\n• نسيان القسمة على n\n• تعويض x بدل y في التغاير\n▸ شرح مبسط\n• عندما نقيس متغيرين معا (مثل الإشهار والمبيعات) نرسم نقطة لكل زوج فنحصل على سحابة. نريد أن نعرف هل هناك علاقة تقريبية بينهما. نبدأ بحساب المتوسطين والتباين والتغاير، وهي مواد خام للتعديل الخطي.\n▸ طرق وقواعد\n• كوّن جدولا بالأعمدة ⁦x⁩ و ⁦y⁩ و ⁦x²⁩ و ⁦xy⁩.\n• احسب المجاميع ثم المتوسطات.\n• تحقق أن ⁦cov⁩ يحمل نفس إشارة ميل المستقيم.\n▸ تمارين محلولة\n• تمرين 1: النفقات الإشهارية x (بآلاف الدنانير): 1، 2، 3، 4، 5 والمبيعات y: 3، 5، 6، 8، 9. احسب ⁦x̄⁩ و ⁦ȳ⁩ و ⁦V(x)⁩ و ⁦cov(x,y)⁩.\n• الحل:\n   – ⁦x̄ = 15/5 = 3⁩ و ⁦ȳ = 31/5 = 6.2⁩\n   – ⁦Σx² = 55⁩ فـ ⁦V(x) = 55/5 - 9 = 2⁩\n   – ⁦Σxy = 3 + 10 + 18 + 32 + 45 = 108⁩ فـ ⁦cov = 108/5 - 3×6.2 = 21.6 - 18.6 = 3⁩\n• تمرين 2: في السلسلة السابقة احسب ⁦V(y)⁩ و ⁦σ_(y)⁩.\n• الحل:\n   – ⁦Σy² = 9 + 25 + 36 + 64 + 81 = 215⁩\n   – ⁦V(y) = 215/5 - 6.2² = 43 - 38.44 = 4.56⁩\n   – ⁦σ_(y) = √4.56 ≈ 2.135⁩\n▸ للحفظ\n• ⁦x̄ = Σxᵢ/n⁩ و ⁦V(x) = Σxᵢ²/n - x̄²⁩ و ⁦cov(x,y) = Σxᵢ·yᵢ/n - x̄·ȳ⁩. النقطة المتوسطة ⁦G(x̄ ; ȳ)⁩."},{"title":"18. التعديل الخطي والارتباط والتقدير","content":"▸ مستقيم الانحدار\n• ⁦y = a·x + b⁩ (المربعات الصغرى)\n• ⁦a = cov(x,y)/V(x)⁩\n• ⁦b = ȳ - a·x̄⁩\n▸ معامل الارتباط\n• ⁦r = cov(x,y)/(σₓ·σ_(y))⁩\n• ⁦-1 ≤ r ≤ 1⁩\n• ⁦|r|⁩ قريب من 1 ⇒ ارتباط قوي\n▸ التقدير\n• نعوض قيمة x في المعادلة فنجد y تقديريا\n• نحل ⁦y = y₀⁩ لنجد x\n• احذر التقدير بعيدا عن مجال المعطيات\n▸ التفسير\n• ⁦a⁩ هو الزيادة في y لكل وحدة في x\n• ⁦r > 0⁩ علاقة طردية و ⁦r < 0⁩ عكسية\n• يمر المستقيم بالنقطة ⁦G⁩\n▸ أخطاء شائعة\n• استعمال ⁦V(y)⁩ بدل ⁦V(x)⁩ في الميل\n• نسيان ⁦b = ȳ - a·x̄⁩\n• القول أن ارتباطا قويا يعني وجود سببية\n▸ شرح مبسط\n• نبحث عن المستقيم الأقرب لكل النقاط معا. ميله a هو التغاير مقسوما على تباين x، ويمر دائما من النقطة المتوسطة. أما معامل الارتباط r فيقيس مدى التصاق النقاط بالمستقيم: قريب من 1 أو -1 يعني التعديل جيد.\n▸ طرق وقواعد\n• احسب ⁦a⁩ ثم ⁦b⁩ بالترتيب.\n• قدّر y بتعويض x، أو أوجد x بحل المعادلة.\n• فسّر r بعبارات مرتبطة بالمسألة.\n▸ تمارين محلولة\n• تمرين 1: باستعمال معطيات الإشهار (x̄=3، ȳ=6.2، V(x)=2، cov=3) أوجد معادلة مستقيم الانحدار وقدّر المبيعات عند ⁦x = 7⁩.\n• الحل:\n   – ⁦a = 3/2 = 1.5⁩ و ⁦b = 6.2 - 1.5×3 = 1.7⁩\n   – المعادلة ⁦y = 1.5x + 1.7⁩\n   – عند ⁦x = 7⁩: ⁦y = 10.5 + 1.7 = 12.2⁩ أي 12200 دج تقريبا\n• تمرين 2: ما النفقات اللازمة لبلوغ مبيعات قيمتها 20؟\n• الحل:\n   – نحل ⁦1.5x + 1.7 = 20⁩ فـ ⁦x = 18.3/1.5 = 12.2⁩ أي نحو 12200 دج من الإشهار\n• تمرين 3: احسب معامل الارتباط وفسّره.\n• الحل:\n   – ⁦σₓ = √2 ≈ 1.414⁩ و ⁦σ_(y) ≈ 2.135⁩\n   – ⁦r = 3/(1.414×2.135) ≈ 0.994⁩\n   – قريب جدا من 1 فالارتباط طردي وقوي والتعديل الخطي مناسب\n▸ للحفظ\n• ⁦a = cov(x,y)/V(x)⁩ و ⁦b = ȳ - a·x̄⁩ و ⁦r = cov(x,y)/(σₓ·σ_(y))⁩. المستقيم يمر بالنقطة ⁦G⁩."},{"title":"19. مبادئ الاحتمال والعد","content":"▸ القانون الأساسي\n• ⁦P(A) = N_(A) / N⁩ (الملائمة على الممكنة)\n• ⁦0 ≤ P(A) ≤ 1⁩\n• ⁦P(Ā) = 1 - P(A)⁩\n▸ الاتحاد\n• ⁦P(A ∪ B) = P(A) + P(B) - P(A ∩ B)⁩\n• حادثتان غير متلائمتين: ⁦P(A ∩ B) = 0⁩\n• «على الأقل» ⇒ نستعمل الحادثة المعاكسة\n▸ العد\n• ⁦n! = n×(n-1)×...×1⁩\n• ترتيبات: ⁦A(n,p) = n!/(n-p)!⁩\n• توفيقات: ⁦C(n,p) = n!/(p!(n-p)!)⁩\n▸ اختيار\n• الترتيب مهم ⇒ ترتيبات\n• الترتيب غير مهم ⇒ توفيقات\n• سحب في آن واحد ⇒ توفيقات\n▸ أخطاء شائعة\n• الخلط بين الترتيبات والتوفيقات\n• نسيان الحالات المتساوية الاحتمال\n• حساب احتمال «على الأقل» مباشرة بدل المعاكسة\n▸ شرح مبسط\n• الاحتمال هو نسبة الحالات التي تعجبنا من كل الحالات الممكنة، بشرط أن تكون كلها متساوية الاحتمال. وفي العدّ نسأل سؤالا واحدا: هل الترتيب مهم؟ نعم فترتيبات، لا فتوفيقات.\n▸ طرق وقواعد\n• اعدّ الحالات الممكنة أولا.\n• «على الأقل واحد» = 1 - «ولا واحد».\n• اكتب النتيجة كسرا مختصرا.\n▸ تمارين محلولة\n• تمرين 1: كيس فيه 5 كرات حمراء و 3 زرقاء. نسحب كرتين في آن واحد. احسب احتمال أن تكونا حمراوين، وأن يكون لونهما مختلفا، وأن تكون واحدة زرقاء على الأقل.\n• الحل:\n   – عدد الحالات ⁦C(8,2) = 28⁩\n   – حمراوان: ⁦C(5,2)/28 = 10/28 = 5/14⁩\n   – مختلفان: ⁦5×3/28 = 15/28⁩\n   – على الأقل زرقاء: ⁦1 - 10/28 = 18/28 = 9/14⁩\n• تمرين 2: كم لجنة من 3 أعضاء يمكن تشكيلها من 10 أشخاص؟\n• الحل:\n   – الترتيب غير مهم\n   – ⁦C(10,3) = 120⁩ لجنة\n• تمرين 3: ⁦P(A) = 0.5⁩ و ⁦P(B) = 0.4⁩ و ⁦P(A ∩ B) = 0.2⁩. احسب ⁦P(A ∪ B)⁩ و ⁦P(Ā)⁩.\n• الحل:\n   – ⁦P(A ∪ B) = 0.5 + 0.4 - 0.2 = 0.7⁩\n   – و ⁦P(Ā) = 1 - 0.5 = 0.5⁩\n▸ للحفظ\n• ⁦P(A ∪ B) = P(A) + P(B) - P(A ∩ B)⁩. الاحتمال هو الملائمة على الممكنة. للتوفيقات ⁦C(n,p)⁩. «على الأقل» نستعمل المعاكسة."},{"title":"20. الاحتمال الشرطي والاستقلال","content":"▸ الاحتمال الشرطي\n• ⁦P(A|B) = P(A ∩ B)/P(B)⁩\n• ⁦P(A ∩ B) = P(B)·P(A|B)⁩\n• نقرأ: احتمال A علما أن B وقع\n▸ شجرة الاحتمالات\n• على كل فرع احتمال\n• جداء احتمالات الفروع على مسار\n• مجموع احتمالات فروع من نفس العقدة = 1\n▸ الاحتمالات الكلية\n• ⁦P(D) = P(M₁)P(D|M₁) + P(M₂)P(D|M₂)⁩\n• نجمع كل المسارات المؤدية للحادثة\n• تقسيم الفضاء إلى ⁦M₁, M₂⁩\n▸ الاستقلال\n• A و B مستقلتان ⇔ ⁦P(A ∩ B) = P(A)·P(B)⁩\n• عندئذ ⁦P(A|B) = P(A)⁩\n• لا تخلط بينه وبين التنافي\n▸ أخطاء شائعة\n• الخلط بين ⁦P(A|B)⁩ و ⁦P(B|A)⁩\n• جمع احتمالات الفروع بدل ضربها\n• القول أن حادثتين متنافيتين مستقلتان\n▸ شرح مبسط\n• الاحتمال الشرطي يعني: نغيّر الكون. بدل كل الحالات ننظر فقط للحالات التي وقع فيها B. والشجرة تنظم الحسابات: نضرب على الفرع ونجمع بين الفروع المختلفة التي تؤدي إلى نفس النتيجة.\n▸ طرق وقواعد\n• ارسم شجرة قبل أي حساب.\n• ضرب على المسار وجمع بين المسارات.\n• لإثبات الاستقلال قارن ⁦P(A ∩ B)⁩ بـ ⁦P(A)P(B)⁩.\n▸ تمارين محلولة\n• تمرين 1: آلة M1 تنتج 60% من القطع و 2% منها معيبة، وآلة M2 تنتج 40% و 5% منها معيبة. احسب احتمال أن تكون قطعة معيبة، ثم احتمال أنها من M2 علما أنها معيبة.\n• الحل:\n   – ⁦P(D) = 0.6×0.02 + 0.4×0.05 = 0.012 + 0.02 = 0.032⁩\n   – ⁦P(M₂|D) = 0.02/0.032 = 0.625⁩\n• تمرين 2: ⁦P(A) = 0.3⁩ و ⁦P(B) = 0.5⁩ و ⁦P(A ∩ B) = 0.15⁩. هل A و B مستقلتان؟\n• الحل:\n   – ⁦P(A)·P(B) = 0.15 = P(A ∩ B)⁩\n   – إذن مستقلتان\n• تمرين 3: ⁦P(A ∩ B) = 0.2⁩ و ⁦P(B) = 0.5⁩. احسب ⁦P(A|B)⁩.\n• الحل:\n   – ⁦P(A|B) = 0.2/0.5 = 0.4⁩\n▸ للحفظ\n• ⁦P(A|B) = P(A ∩ B)/P(B)⁩. في الشجرة نضرب على المسار ونجمع بين المسارات. استقلال: ⁦P(A ∩ B) = P(A)·P(B)⁩."},{"title":"21. المتغير العشوائي والأمل الرياضياتي والتباين","content":"▸ قانون الاحتمال\n• جدول القيم ⁦xᵢ⁩ واحتمالاتها ⁦pᵢ⁩\n• ⁦Σpᵢ = 1⁩\n• ⁦pᵢ ≥ 0⁩\n▸ الأمل\n• ⁦E(X) = Σxᵢ·pᵢ⁩\n• متوسط الربح على المدى الطويل\n• لعبة عادلة: ⁦E(X) = 0⁩\n▸ التباين\n• ⁦V(X) = E(X²) - (E(X))²⁩\n• ⁦E(X²) = Σxᵢ²·pᵢ⁩\n• ⁦σ = √V(X)⁩\n▸ تطبيق\n• القرار الاقتصادي بالأمل\n• مقارنة مشروعين بالأمل والتباين\n• التباين الأصغر مخاطرة أقل\n▸ أخطاء شائعة\n• نسيان الربح الصافي (طرح الثمن)\n• عدم التحقق من ⁦Σpᵢ = 1⁩\n• ⁦V = E(X²) - E(X)⁩ بدل التربيع\n▸ شرح مبسط\n• المتغير العشوائي هو نتيجة رقمية لتجربة عشوائية (ربح، عدد، تكلفة). الأمل الرياضياتي هو المتوسط الذي نتوقعه على المدى الطويل، والتباين يقيس مدى تشتت النتائج حوله، أي درجة المخاطرة.\n▸ طرق وقواعد\n• اكتب جدول القانون أولا وتحقق من مجموع الاحتمالات.\n• احسب ⁦E(X)⁩ ثم ⁦E(X²)⁩.\n• فسّر إشارة الأمل: سالب يعني خسارة متوسطة.\n▸ تمارين محلولة\n• تمرين 1: قيم X: 1 و 2 و 3 باحتمالات ⁦0.2⁩ و ⁦a⁩ و ⁦0.5⁩. أوجد a و ⁦E(X)⁩.\n• الحل:\n   – ⁦0.2 + a + 0.5 = 1⁩ فـ ⁦a = 0.3⁩\n   – ⁦E(X) = 1×0.2 + 2×0.3 + 3×0.5 = 0.2 + 0.6 + 1.5 = 2.3⁩\n• تمرين 2: لعبة: الربح X بالدينار يأخذ ⁦-10⁩ و ⁦0⁩ و ⁦20⁩ باحتمالات ⁦0.5⁩ و ⁦0.3⁩ و ⁦0.2⁩. احسب ⁦E(X)⁩ و ⁦V(X)⁩.\n• الحل:\n   – ⁦E(X) = -5 + 0 + 4 = -1⁩\n   – ⁦E(X²) = 100×0.5 + 0 + 400×0.2 = 130⁩\n   – ⁦V(X) = 130 - 1 = 129⁩ و ⁦σ ≈ 11.36⁩\n   – الأمل سالب فاللعبة غير مربحة\n• تمرين 3: تذكرة سحب ثمنها 5 دج تربح 100 دج باحتمال ⁦0.02⁩. ما الأمل الصافي؟\n• الحل:\n   – الربح الصافي ⁦95⁩ باحتمال ⁦0.02⁩ و ⁦-5⁩ باحتمال ⁦0.98⁩\n   – ⁦E = 95×0.02 - 5×0.98 = 1.9 - 4.9 = -3⁩ دج\n▸ للحفظ\n• ⁦E(X) = Σxᵢ·pᵢ⁩ و ⁦V(X) = E(X²) - (E(X))²⁩. لعبة عادلة: ⁦E(X) = 0⁩. الربح الصافي = الربح - الثمن."},{"title":"22. القانون الثنائي","content":"▸ الشروط\n• ⁦n⁩ تجربة مستقلة متطابقة\n• لكل تجربة نتيجتان: نجاح باحتمال ⁦p⁩ وفشل ⁦q = 1 - p⁩\n• X عدد النجاحات: ⁦X ~ B(n ; p)⁩\n▸ القانون\n• ⁦P(X = k) = C(n,k)·pᵏ·qⁿ⁻ᵏ⁩\n• ⁦k⁩ من 0 إلى n\n• ⁦P(X ≥ 1) = 1 - qⁿ⁩\n▸ الأمل والتباين\n• ⁦E(X) = n·p⁩\n• ⁦V(X) = n·p·q⁩\n• ⁦σ = √(npq)⁩\n▸ كيف أتعرف عليه؟\n• تكرار نفس الاختبار\n• احتمال النجاح ثابت\n• العد يخص النجاحات فقط\n▸ أخطاء شائعة\n• نسيان ⁦C(n,k)⁩\n• خلط ⁦p⁩ و ⁦q⁩\n• استعماله مع سحب دون إرجاع\n▸ شرح مبسط\n• نستعمل القانون الثنائي عندما نكرر نفس التجربة n مرة ونعدّ كم مرة نجحنا. كل نتيجة مفصلة (k نجاح و n-k فشل) لها احتمال ⁦pᵏ q^(n-k)⁩ وعدد طرق ترتيبها هو ⁦C(n,k)⁩.\n▸ طرق وقواعد\n• حدد n و p بوضوح.\n• «على الأقل واحد» ⇒ ⁦1 - qⁿ⁩.\n• الأمل ⁦np⁩ يعطي المتوسط المتوقع للنجاحات.\n▸ تمارين محلولة\n• تمرين 1: ⁦X ~ B(5 ; 0.3)⁩. احسب ⁦P(X = 2)⁩ و ⁦P(X ≥ 1)⁩ و ⁦E(X)⁩ و ⁦V(X)⁩.\n• الحل:\n   – ⁦P(X = 2) = C(5,2)×0.3²×0.7³ = 10×0.09×0.343 = 0.3087⁩\n   – ⁦P(X ≥ 1) = 1 - 0.7⁵ = 1 - 0.16807 = 0.83193⁩\n   – ⁦E(X) = 5×0.3 = 1.5⁩ و ⁦V(X) = 5×0.3×0.7 = 1.05⁩\n• تمرين 2: اختبار من 10 أسئلة كل منها 4 اختيارات. يجيب طالب عشوائيا. ما احتمال أن يصيب 3 أسئلة بالضبط؟\n• الحل:\n   – ⁦X ~ B(10 ; 0.25)⁩\n   – ⁦P(X = 3) = C(10,3)×0.25³×0.75⁷ = 120×0.015625×0.13348 ≈ 0.2503⁩\n▸ للحفظ\n• ⁦X ~ B(n ; p)⁩: ⁦P(X = k) = C(n,k)·pᵏ·qⁿ⁻ᵏ⁩ و ⁦E = n·p⁩ و ⁦V = n·p·q⁩ و ⁦P(X ≥ 1) = 1 - qⁿ⁩."}],maps:'mg'});
  try{var L1=LESSONS_DB['1AM'];if(L1){["math","ar","fr","en","hist","islam","civic","sci","phys","info","art"].forEach(function(k){if(L1[k])L1[k].maps='am1_'+k;});}}catch(e){}
  (function(){var o=A['genie-mecanique']||{};A['genie-mecanique']=Object.assign({name:'الهندسة الميكانيكية'},o,{lessons:[{"title":"1. قراءة الرسم التقني والإنشاء","content":"▸ ماذا نقرأ أولا؟\n• عنوان الرسم وجدول البيانات\n• المقياس والمساقط والمقاطع\n• الأبعاد والتفاوتات المكتوبة\n▸ المقياس\n• الطبيعي ⁦1:1⁩\n• التصغير مثل ⁦1:2⁩\n• التكبير مثل ⁦2:1⁩\n▸ الرسم التجميعي\n• حدد كل قطعة برقمها\n• استخرج وظيفتها\n• حدد علاقات التلامس والتثبيت\n▸ المسقط والمقطع\n• المسقط يمثل الشكل الخارجي\n• المقطع يكشف الداخل بقطع وهمي\n• خطوط التهشير تدل على المادة المقطوعة\n▸ أخطاء شائعة\n• قياس البعد من الورقة رغم أنه مكتوب\n• الخلط بين التصغير والتكبير\n• تجاهل التفاوتات\n▸ شرح مبسط\n• الرسم التقني لغة عالمية بين المصمم والعامل. قبل أي حل اقرأ العنوان والمقياس ثم المساقط. تذكر أن البعد المكتوب هو المرجع دائما، أما الورقة فقد تكون مصغرة أو مكبرة.\n▸ طرق وقواعد\n• الطول المرسوم = الطول الحقيقي × المقياس.\n• البعد المكتوب أولى من البعد المقاس.\n• في التجميعي ابدأ بالترقيم ثم الوظيفة ثم الوصلات.\n▸ تمارين محلولة\n• تمرين 1: المقياس ⁦1:2⁩ والطول الحقيقي للقطعة ⁦80 mm⁩. ما طولها المرسوم؟\n• الحل:\n   – المقياس ⁦1:2⁩ تصغير بالنصف\n   – الطول المرسوم ⁦80 × 1/2 = 40 mm⁩\n• تمرين 2: ما الفرق بين المسقط والمقطع؟ ولماذا تُستعمل خطوط التهشير؟\n• الحل:\n   – المسقط يعرض الشكل الخارجي كما نراه\n   – والمقطع نتخيل فيه قطع القطعة بمستو لإظهار الداخل\n   – خطوط التهشير تبين الأجزاء المقطوعة من المادة فنفرق بينها وبين الفراغات\n• تمرين 3: قطعة طولها الحقيقي ⁦120 mm⁩ رُسمت بمقياس ⁦2:1⁩. ما طولها المرسوم؟\n• الحل:\n   – المقياس ⁦2:1⁩ تكبير مرتين\n   – الطول المرسوم ⁦120 × 2 = 240 mm⁩\n▸ للحفظ\n• الطول المرسوم = الحقيقي × المقياس. البعد المكتوب هو المرجع. المقطع يكشف الداخل وتهشيره يدل على المادة."},{"title":"2. الوصلات الميكانيكية ودرجات الحرية","content":"▸ الوصلة\n• تربط قطعتين\n• تسمح بحركات نسبية محددة\n• وتمنع حركات أخرى\n▸ أنواع الوصلات\n• ثابتة (لا حركة)\n• محورية دورانية\n• انزلاقية\n▸ وصلات أخرى\n• لولبية (دوران وانتقال معا)\n• كروية (دوران حول نقطة)\n• متمحورة بالتدحرج\n▸ كيف أحلل آلية؟\n• اذكر القطع المتصلة\n• نوع الوصلة\n• الحركة المسموحة والممنوعة\n▸ المحامل\n• توجه الدوران\n• تقلل الاحتكاك\n• يُختار نوعها حسب الحمل والسرعة والدقة\n▸ شرح مبسط\n• كل وصلة قاعدة لعبة بين قطعتين: ما الذي يُسمح لإحداهما بفعله بالنسبة للأخرى. الباب مع إطاره يدور فقط، والمنزلق على سكة ينتقل فقط في اتجاه واحد. لا تخلط بين حركة القطعة وحركة نقطة عليها.\n▸ طرق وقواعد\n• لكل وصلة: حركة مسموحة وحركات ممنوعة.\n• حركة القطعة غير حركة نقطة منها.\n• اختر المحمل بحسب الحمل والسرعة والدقة.\n▸ تمارين محلولة\n• تمرين 1: محور يدور داخل محمل. ما الحركة المسموحة؟\n• الحل:\n   – الحركة المسموحة هي الدوران حول محور المحمل فقط\n   – أما الانتقالات الأخرى فتُمنع بحسب التركيب\n   – الوصلة محورية دورانية\n• تمرين 2: حدّد نوع الوصلة بين باب وإطاره، وبين منزلق وسكة خطية.\n• الحل:\n   – الباب والإطار: وصلة محورية (دورانية) حول محور المفصلة\n   – المنزلق والسكة: وصلة انزلاقية، انتقال في اتجاه السكة فقط\n• تمرين 3: ما فائدة المحمل في آلية تدور؟\n• الحل:\n   – يوجه الدوران ويقلل الاحتكاك ويتحمل الأحمال\n   – ويُختار حسب الحمل والسرعة والدقة المطلوبة\n▸ للحفظ\n• وصلة = حركة مسموحة + حركات ممنوعة. دورانية، انزلاقية، لولبية، كروية، ثابتة. المحمل يوجه الدوران ويقلل الاحتكاك."},{"title":"3. مقاومة المواد: الشد والضغط","content":"▸ الإجهاد العادي\n• ⁦σ = N/S⁩\n• ⁦N⁩ بالنيوتن و ⁦S⁩ بـ ⁦m²⁩ فالإجهاد بـ ⁦Pa⁩\n• أو ⁦N/mm²⁩ وهو يساوي ⁦MPa⁩\n▸ الاستطالة المرنة\n• ⁦ΔL = N·L/(E·S)⁩\n• ⁦E⁩ معامل يونغ\n• ⁦L⁩ الطول الأصلي\n▸ شرط المقاومة\n• ⁦σ ≤ σₐdm⁩\n• الإجهاد المحسوب أقل من المسموح\n• وحدات متجانسة دائما\n▸ حالة الشد والضغط\n• الشد يطيل القضيب\n• الضغط يقصّره\n• ⁦N⁩ موجبة للشد وسالبة للضغط عادة\n▸ أخطاء شائعة\n• خلط ⁦mm²⁩ مع ⁦m²⁩\n• خلط ⁦N⁩ مع ⁦kN⁩\n• نسيان مقارنة ⁦σ⁩ بـ ⁦σₐdm⁩\n▸ شرح مبسط\n• القوة المحورية تشد القضيب أو تضغطه. نقسمها على مساحة المقطع لنعرف الإجهاد، أي القوة لكل وحدة مساحة. إن كان الإجهاد أقل من الإجهاد الذي تتحمله المادة فالقطعة آمنة.\n▸ طرق وقواعد\n• حوّل ⁦kN⁩ إلى ⁦N⁩ أولا: ⁦1 kN = 1000 N⁩.\n• مع ⁦mm²⁩ تكون النتيجة بـ ⁦MPa⁩ مباشرة.\n• اكتب الشرط ⁦σ ≤ σₐdm⁩ واستنتج.\n▸ تمارين محلولة\n• تمرين 1: قضيب مساحته ⁦100 mm²⁩ تؤثر عليه قوة شد ⁦10 kN⁩. احسب الإجهاد.\n• الحل:\n   – ⁦σ = 10000/100 = 100 N/mm² = 100 MPa⁩\n• تمرين 2: قضيب مساحته ⁦200 mm²⁩ يتعرض إلى ⁦12 kN⁩. احسب الإجهاد بوحدة ⁦MPa⁩.\n• الحل:\n   – ⁦N = 12 kN = 12000 N⁩\n   – ⁦σ = 12000/200 = 60 MPa⁩\n• تمرين 3: قضيب فولاذي طوله ⁦2 m⁩ ومساحته ⁦200 mm²⁩ وقوة الشد ⁦20 kN⁩ و ⁦E = 200000 MPa⁩. احسب الاستطالة.\n• الحل:\n   – ⁦ΔL = N·L/(E·S) = 20000 × 2000/(200000 × 200) = 40000000/40000000 = 1 mm⁩\n▸ للحفظ\n• ⁦σ = N/S⁩ و ⁦ΔL = N·L/(E·S)⁩. الشرط ⁦σ ≤ σₐdm⁩. N/mm² = MPa."},{"title":"4. القص والانحناء والالتواء","content":"▸ القص\n• قوى متعاكسة متقاربة على المقطع\n• ⁦τ = T/S⁩\n• مثل مسمار أو برشام\n▸ الانحناء\n• أحمال عرضية تولد عزم انحناء\n• ألياف جانب في الشد والجانب الآخر في الضغط\n• استعمل مخططات العزم\n▸ الالتواء\n• عزم حول محور العمود\n• يظهر في أعمدة نقل الحركة\n• يرتبط بالقدرة والسرعة الزاوية\n▸ القدرة الدورانية\n• ⁦P = C·ω⁩\n• ⁦C⁩ عزم الدوران بـ ⁦N·m⁩\n• ⁦ω⁩ بـ ⁦rad/s⁩\n▸ تحويل السرعة\n• ⁦ω = 2π·n/60⁩\n• ⁦n⁩ بـ ⁦tr/min⁩\n• ⁦1 tr/min = 0.1047 rad/s⁩\n▸ شرح مبسط\n• القص يحدث عندما تحاول قوتان متعاكستان قص المقطع كما تقص المقص الورقة. الانحناء يثني العنصر فيشد جانبا ويضغط جانبا. الالتواء يلوي العمود حول محوره وهو يرتبط بالقدرة التي ينقلها.\n▸ طرق وقواعد\n• القص: قسّم القوة على مساحة المقطع المقصوص.\n• القدرة = العزم × السرعة الزاوية.\n• حوّل tr/min إلى rad/s قبل الحساب.\n▸ تمارين محلولة\n• تمرين 1: حوّل سرعة ⁦300 tr/min⁩ إلى ⁦rad/s⁩ باستعمال ⁦ω = 2πn/60⁩.\n• الحل:\n   – ⁦ω = 2π × 300/60 = 10π ≈ 31.4 rad/s⁩\n• تمرين 2: مسمار يتعرض لقوة قص ⁦6 kN⁩ ومساحة مقطعه ⁦50 mm²⁩. احسب ⁦τ⁩.\n• الحل:\n   – ⁦τ = T/S = 6000/50 = 120 N/mm² = 120 MPa⁩\n• تمرين 3: عمود ينقل عزما ⁦C = 20 N·m⁩ بسرعة ⁦300 tr/min⁩. احسب القدرة.\n• الحل:\n   – ⁦ω ≈ 31.4 rad/s⁩\n   – ⁦P = C·ω = 20 × 31.4 ≈ 628 W⁩\n▸ للحفظ\n• ⁦τ = T/S⁩ و ⁦P = C·ω⁩ و ⁦ω = 2πn/60⁩. الانحناء: شد في جانب وضغط في الجانب الآخر."},{"title":"5. نقل الحركة والقدرة والمردود","content":"▸ زوج تروس\n• ⁦n₁·Z₁ = n₂·Z₂⁩\n• ⁦n⁩ السرعة و ⁦Z⁩ عدد الأسنان\n• اتجاها الدوران متعاكسان في الخارجي\n▸ نسبة النقل\n• ⁦r = n₂/n₁ = Z₁/Z₂⁩\n• حسب اصطلاح الدرس\n• اكتب العلاقة المستعملة دائما\n▸ المردود\n• ⁦η = P_(u)/Pₐ⁩\n• ⁦P_(u)⁩ المفيدة و ⁦Pₐ⁩ الممتصة\n• ⁦η ≤ 1⁩ في النظام الحقيقي\n▸ الضياعات\n• الاحتكاك\n• الحرارة\n• ⁦Pₐ = P_(u) + P_(pertes)⁩ (الضياعات)\n▸ أخطاء شائعة\n• عكس نسبة النقل\n• خلط المدخل والمخرج\n• قول إن المردود أكبر من 1\n▸ شرح مبسط\n• الترس الصغير يدور أسرع من الكبير المتصل به. حاصل ضرب السرعة في عدد الأسنان ثابت. أما المردود فهو نسبة ما أخذناه فعلا من الآلة إلى ما أعطيناها، وهو دائما أقل من 1 بسبب الضياعات.\n▸ طرق وقواعد\n• ابدأ بتحديد المدخل والمخرج.\n• ⁦n₂ = n₁·Z₁/Z₂⁩.\n• المردود يُعطى نسبة أو مئوية.\n▸ تمارين محلولة\n• تمرين 1: ⁦Z₁ = 20⁩ و ⁦Z₂ = 60⁩ و ⁦n₁ = 900 tr/min⁩. احسب ⁦n₂⁩.\n• الحل:\n   – ⁦n₂ = n₁·Z₁/Z₂ = 900 × 20/60 = 300 tr/min⁩\n• تمرين 2: آلة تستقبل ⁦500 W⁩ وتقدم ⁦400 W⁩ مفيدة. احسب مردودها.\n• الحل:\n   – ⁦η = 400/500 = 0.8⁩ أي ⁦80%⁩\n   – الضياعات ⁦100 W⁩\n• تمرين 3: ⁦Z₁ = 18⁩ و ⁦Z₂ = 54⁩ و ⁦n₁ = 1200 tr/min⁩. احسب ⁦n₂⁩ ونسبة النقل.\n• الحل:\n   – ⁦n₂ = 1200 × 18/54 = 400 tr/min⁩\n   – نسبة النقل ⁦n₂/n₁ = 400/1200 = 1/3⁩\n   – الترس الثاني أبطأ ثلاث مرات\n▸ للحفظ\n• ⁦n₁·Z₁ = n₂·Z₂⁩ و ⁦η = P_(u)/Pₐ ≤ 1⁩. حدد المدخل والمخرج أولا."},{"title":"6. الإنتاج والتصنيع","content":"▸ العمليات\n• السباكة والتشكيل\n• التشغيل بالقطع\n• اللحام والمعالجة الحرارية\n▸ الخراطة\n• القطعة تدور غالبا\n• الأداة تتحرك\n• سطوح أسطوانية دقيقة\n▸ التفريز\n• الأداة تدور\n• القطعة أو الطاولة تتحرك\n• سطوح مستوية وأخاديد\n▸ معايير الاختيار\n• المادة والشكل\n• الدقة وجودة السطح\n• التكلفة والكمية\n▸ السلامة والجودة\n• نظارات واقية وتثبيت القطعة\n• عدم ارتداء قفازات قرب الأجزاء الدوارة\n• مراقبة الأبعاد والتفاوتات\n▸ شرح مبسط\n• نختار طريقة التصنيع بحسب الشكل المطلوب والدقة والتكلفة. القطعة الدوارة ذات السطح الأسطواني تناسبها الخراطة، والسطوح المستوية تناسبها آلة التفريز. وتبقى السلامة أولا في كل ورشة.\n▸ طرق وقواعد\n• ربط العملية بالشكل المطلوب.\n• قارن الدقة والتكلفة.\n• اذكر دائما إجراءات السلامة.\n▸ تمارين محلولة\n• تمرين 1: أي عملية تناسب سطحا أسطوانيا خارجيا دقيقا على قطعة دوارة؟\n• الحل:\n   – الخراطة، لأن القطعة تدور وتتحرك أداة القطع على طولها فتعطي سطحا أسطوانيا دقيقا\n• تمرين 2: اختر عملية مناسبة لثقب قطعة معدنية، ثم اذكر إجراءي سلامة.\n• الحل:\n   – العملية: الثقب بالمثقاب على آلة الثقب\n   – السلامة: ارتداء نظارات واقية، وتثبيت القطعة جيدا في الملزمة دون حملها باليد، وعدم ارتداء قفازات قرب المثقاب الدوار\n• تمرين 3: ما الفرق بين الخراطة والتفريز من حيث الحركة؟\n• الحل:\n   – في الخراطة تدور القطعة وتتحرك الأداة\n   – وفي التفريز تدور الأداة وتتحرك القطعة أو الطاولة\n▸ للحفظ\n• خراطة: القطعة تدور. تفريز: الأداة تدور. اختر العملية بالشكل والدقة والتكلفة. السلامة أولا."}].concat(o.lessons||[]),maps:'gmec'});})();
  (function(){var o=A['genie-electrique']||{};A['genie-electrique']=Object.assign({name:'الهندسة الكهربائية'},o,{lessons:[{"title":"1. سلسلة المعلومات وسلسلة الطاقة","content":"▸ سلسلة المعلومات\n• الحساسات تكتسب المعطيات\n• وحدة التحكم تعالجها\n• وتصدر الأوامر\n▸ سلسلة الطاقة\n• التغذية\n• التوزيع (مسبق المشغل)\n• التحويل والنقل ثم العضو المنفذ\n▸ الفرق بين العناصر\n• الحساس يكتشف حالة\n• المشغل ينفذ فعلا ماديا\n• مسبق المشغل يوزع الطاقة على المشغل\n▸ مثال: باب آلي\n• حساس نهاية الشوط\n• وحدة التحكم تقرر\n• مرحل أو موزع ثم المحرك\n▸ أخطاء شائعة\n• الخلط بين الحساس والمشغل\n• وضع المحرك في سلسلة المعلومات\n• نسيان مسبق المشغل\n▸ شرح مبسط\n• تخيل نظاما آليا كإنسان: الحواس (الحساسات) ترسل معلومة إلى الدماغ (وحدة التحكم) الذي يعطي أمرا للعضلات (المشغلات) فتتحرك. الأوامر تمر عبر سلسلة المعلومات، أما القوة فتمر عبر سلسلة الطاقة.\n▸ طرق وقواعد\n• الحساس يكتشف، وحدة التحكم تقرر، مسبق المشغل يوزع، المشغل ينفذ.\n• ارسم المخطط: حساس ثم تحكم ثم مسبق مشغل ثم مشغل.\n• قد تختلف العناصر من نظام لآخر.\n▸ تمارين محلولة\n• تمرين 1: صنّف حساس نهاية الشوط، وحدة التحكم، المحرك، وموزع القدرة ضمن السلسلتين.\n• الحل:\n   – حساس نهاية الشوط: سلسلة المعلومات (اكتساب)\n   – وحدة التحكم: سلسلة المعلومات (معالجة)\n   – موزع القدرة (المرحل): سلسلة الطاقة (توزيع)\n   – المحرك: سلسلة الطاقة (عضو منفذ يحول الطاقة)\n• تمرين 2: في باب آلي، صف تسلسل الإشارة من فتح الباب إلى حركته.\n• الحل:\n   – الحساس يكشف الشخص ويرسل معلومة\n   – وحدة التحكم تقرر الفتح\n   – المرحل أو الموزع يوجه الطاقة\n   – المحرك يحرك الباب\n   – وعند نهاية الشوط يرسل الحساس معلومة للإيقاف\n• تمرين 3: ما الفرق بين الحساس والمشغل؟\n• الحل:\n   – الحساس يحول كمية فيزيائية إلى إشارة (معلومة)\n   – أما المشغل فيحول الطاقة إلى فعل مادي (حركة، حرارة، ...)\n▸ للحفظ\n• معلومات: حساس ثم تحكم. طاقة: تغذية، توزيع، تحويل، عضو منفذ. الحساس يكتشف والمشغل ينفذ."},{"title":"2. أساسيات الدارات الكهربائية","content":"▸ قانون أوم\n• ⁦U = R·I⁩\n• ⁦U⁩ بالفولت و ⁦I⁩ بالأمبير و ⁦R⁩ بالأوم\n• للمقاومة فقط\n▸ القدرة\n• ⁦P = U·I⁩\n• ⁦P = R·I²⁩\n• ⁦P = U²/R⁩\n▸ التوالي\n• التيار نفسه في العناصر\n• الجهد الكلي مجموع الجهود\n• ⁦R = R₁ + R₂⁩\n▸ التوازي\n• الجهد نفسه على الفروع\n• التيارات تتجمع\n• ⁦1/R = 1/R₁ + 1/R₂⁩\n▸ أخطاء شائعة\n• خلط ⁦mA⁩ مع ⁦A⁩\n• استعمال علاقة توالي في توازي\n• نسيان وحدة القدرة ⁦W⁩\n▸ شرح مبسط\n• قانون أوم يقول إن التيار يزيد عندما يزيد الجهد ويقل عندما تزيد المقاومة. القدرة هي سرعة استهلاك الطاقة. في التوالي كل العناصر تتقاسم نفس التيار، وفي التوازي كل الفروع تتقاسم نفس الجهد.\n▸ طرق وقواعد\n• اكتب المعطيات بالوحدات الأساسية.\n• اختر علاقة القدرة المناسبة للمعطيات.\n• حدد التوالي أو التوازي قبل الحل.\n▸ تمارين محلولة\n• تمرين 1: مقاومة ⁦12 Ω⁩ تحت توتر ⁦24 V⁩. احسب التيار والقدرة.\n• الحل:\n   – ⁦I = U/R = 24/12 = 2 A⁩\n   – ⁦P = U·I = 24 × 2 = 48 W⁩\n• تمرين 2: احسب التيار في مقاومة ⁦30 Ω⁩ موصولة بمصدر ⁦15 V⁩.\n• الحل:\n   – ⁦I = U/R = 15/30 = 0.5 A⁩\n   – والقدرة ⁦P = 15 × 0.5 = 7.5 W⁩\n• تمرين 3: مقاومتان ⁦10 Ω⁩ و ⁦20 Ω⁩ ومصدر ⁦30 V⁩. احسب التيار على التوالي، ثم التيارات على التوازي.\n• الحل:\n   – التوالي: ⁦R = 30 Ω⁩ و ⁦I = 30/30 = 1 A⁩\n   – التوازي: ⁦I₁ = 30/10 = 3 A⁩ و ⁦I₂ = 30/20 = 1.5 A⁩ والتيار الكلي ⁦4.5 A⁩\n▸ للحفظ\n• ⁦U = R·I⁩ و ⁦P = U·I⁩. توالي: نفس التيار. توازي: نفس الجهد."},{"title":"3. المنطق التوافقي","content":"▸ المتغير المنطقي\n• يأخذ ⁦0⁩ أو ⁦1⁩\n• المداخل والمخرج\n• جدول الحقيقة يعرض كل الحالات\n▸ الدوال الأساسية\n• ⁦NOT⁩ النفي تعكس الحالة\n• ⁦AND⁩ تساوي 1 فقط إذا كل المداخل 1\n• ⁦OR⁩ تساوي 1 إذا مدخل واحد على الأقل 1\n▸ خطوات الحل\n• حدد المداخل والمخرج\n• أنشئ جدول الحقيقة\n• استخرج المعادلة وبسطها\n▸ عدد الحالات\n• ⁦n⁩ مداخل تعطي ⁦2ⁿ⁩ حالة\n• مدخلان: 4 حالات\n• ثلاثة مداخل: 8 حالات\n▸ أخطاء شائعة\n• نسيان بعض الحالات\n• الخلط بين ⁦AND⁩ و ⁦OR⁩\n• أخطاء في إشارة النفي\n▸ شرح مبسط\n• المنطق التوافقي يتعامل مع إشارات إما مغلقة 1 أو مفتوحة 0. AND تعني كل الشروط معا، OR تعني شرطا واحدا يكفي، NOT تقلب القيمة. جدول الحقيقة يفحص كل احتمالات المداخل.\n▸ طرق وقواعد\n• اكتب كل الحالات بالترتيب الثنائي.\n• احسب الخرج سطرا سطرا.\n• بسّط المعادلة بالقواعد المدروسة.\n▸ تمارين محلولة\n• تمرين 1: أنشئ جدول الحقيقة للعبارة ⁦Y = A + B̄⁩.\n• الحل:\n   – مدخلان فـ 4 حالات\n   – ⁦A=0,B=0⁩: ⁦Y = 0 + 1 = 1⁩\n   – ⁦A=0,B=1⁩: ⁦Y = 0 + 0 = 0⁩\n   – ⁦A=1,B=0⁩: ⁦Y = 1 + 1 = 1⁩\n   – ⁦A=1,B=1⁩: ⁦Y = 1 + 0 = 1⁩\n• تمرين 2: متى تكون ⁦Y = A·B⁩ مساوية 1؟\n• الحل:\n   – فقط عندما ⁦A = 1⁩ و ⁦B = 1⁩\n   – في كل الحالات الأخرى ⁦Y = 0⁩\n• تمرين 3: كم حالة في جدول حقيقة دالة بثلاثة مداخل؟\n• الحل:\n   – ⁦2³ = 8⁩ حالات\n▸ للحفظ\n• AND: كل المداخل 1. OR: واحد على الأقل. NOT: عكس. n مداخل ⇒ 2^n حالة."},{"title":"4. المنطق التتابعي والذاكرة","content":"▸ التتابعي\n• الخرج لا يعتمد على المداخل الحالية فقط\n• بل على الحالة السابقة\n• يحتاج ذاكرة\n▸ القلابات والسجلات\n• القلاب يحفظ بتا واحدا\n• السجل يحفظ مجموعة بتات\n• التزامن بإشارة الساعة\n▸ العدادات\n• تعد النبضات أو الأحداث\n• عدد حالات عداد ⁦n⁩ بت هو ⁦2ⁿ⁩\n• أكبر عدد ⁦2ⁿ - 1⁩\n▸ تحليل عداد\n• عدد الحالات\n• ترتيب الانتقال\n• حالة البدء وإشارة الساعة\n▸ أخطاء شائعة\n• الخلط بين التوافقي والتتابعي\n• نسيان الصفر ضمن الحالات\n• الخلط بين ⁦2ⁿ⁩ و ⁦2ⁿ - 1⁩\n▸ شرح مبسط\n• الفرق بين التوافقي والتتابعي كالفرق بين آلة حاسبة وذاكرة. الدارة التتابعية تتذكر ما جرى. القلاب يخزن بتا، والعداد يعد النبضات ويمر بسلسلة حالات منظمة.\n▸ طرق وقواعد\n• عداد من ⁦n⁩ بت له ⁦2ⁿ⁩ حالة.\n• أكبر عدد يمثله ⁦2ⁿ - 1⁩.\n• حدد حالة البدء وترتيب الانتقال.\n▸ تمارين محلولة\n• تمرين 1: عداد من 3 بتات. كم حالة له؟\n• الحل:\n   – ⁦2³ = 8⁩ حالات ثنائية مختلفة، من ⁦000⁩ إلى ⁦111⁩\n• تمرين 2: كم حالة يتيح عداد من 4 بتات؟ وما أكبر عدد غير سالب يمثله؟\n• الحل:\n   – ⁦2⁴ = 16⁩ حالة\n   – وأكبر عدد ⁦16 - 1 = 15⁩\n• تمرين 3: ما الفرق بين القلاب والسجل؟\n• الحل:\n   – القلاب يحفظ بتا واحدا\n   – السجل مجموعة قلابات يحفظ عدة بتات\n▸ للحفظ\n• تتابعي = خرج يعتمد على الحالة السابقة. عداد n بت: 2^n حالة وأكبر عدد 2^n - 1."},{"title":"5. الحساسات والمشغلات والتحكم","content":"▸ الحساس\n• يحول كمية فيزيائية إلى إشارة\n• موضع، حرارة، ضغط، ضوء، سرعة\n• قد يكون تماسيا أو عن بعد\n▸ المشغل\n• يحول الطاقة إلى فعل\n• محرك كهربائي\n• أسطوانة هوائية، صمام، مقاومة تسخين\n▸ قراءة المخطط\n• تتبع الإشارة من الحساس\n• إلى المعالجة ثم الأمر\n• تحقق من الأمان والتوقف الطارئ\n▸ اختيار حساس\n• نوع الجسم المراد كشفه\n• المسافة والبيئة\n• الدقة والتكلفة\n▸ أخطاء شائعة\n• الخلط بين الحساس والمشغل\n• إهمال التوقف الطارئ\n• اختيار حساس لا يناسب المادة\n▸ شرح مبسط\n• الحساس هو الحاسة التي تشعر بالعالم الخارجي والمشغل هو اليد التي تتحرك. في المخطط اتبع الإشارة من أولها: ماذا نقيس؟ وماذا نقرر؟ وماذا نشغل؟ وتذكر أن الأمان له أولوية.\n▸ طرق وقواعد\n• حدد الكمية المراد قياسها.\n• اربط كل حساس بمشغل في المخطط.\n• ضع شروط الأمان في الحسبان.\n▸ تمارين محلولة\n• تمرين 1: في نظام تعبئة، ما دور حساس المستوى؟\n• الحل:\n   – يكتشف بلوغ المستوى المطلوب فيرسل إشارة لإيقاف صمام التعبئة\n• تمرين 2: اقترح حساسا مناسبا لاكتشاف قطعة معدنية على ناقل، وعلّل اختيارك.\n• الحل:\n   – حساس تقاربي حثي\n   – لأنه يكشف المعادن دون تلامس فلا يتآكل ولا يعطل حركة القطع\n• تمرين 3: اذكر ثلاثة أمثلة على مشغلات.\n• الحل:\n   – محرك كهربائي، أسطوانة هوائية، صمام كهرومغناطيسي\n   – (ومقاومة تسخين أيضا)\n▸ للحفظ\n• حساس: كمية فيزيائية ⟵ إشارة. مشغل: طاقة ⟵ فعل. الأمان والتوقف الطارئ دائما."},{"title":"6. المحركات والطاقة الكهربائية","content":"▸ المحرك\n• يحول الكهربائية إلى ميكانيكية\n• يختار حسب القدرة والسرعة\n• وعزم البدء ونمط التغذية\n▸ لوحة المحرك\n• التوتر والتيار\n• التردد والقدرة\n• السرعة ونمط الربط\n▸ الربط\n• نجمة أو مثلث\n• قارن توتر اللوحة بتوتر الشبكة\n• لا تخمن الربط\n▸ قبل التشغيل\n• التوتر الاسمي\n• الحماية الحرارية والتأريض\n• استمرارية التوصيلات\n▸ أخطاء شائعة\n• ربط خاطئ يحرق المحرك\n• إهمال التأريض\n• عدم قراءة اللوحة\n▸ شرح مبسط\n• لوحة المحرك هي بطاقة هويته: تقول لك أي توتر يتحمل وما قدرته وسرعته. إذا كتب عليها مثلا ⁦230/400 V⁩ فمعناه أن الملف يتحمل 230 V. على شبكة 400 V نربط بنجمة، وعلى شبكة 230 V نربط بمثلث.\n▸ طرق وقواعد\n• اقرأ اللوحة قبل أي توصيل.\n• قارن توتر الملف بتوتر الشبكة.\n• تحقق من التأريض والحماية.\n▸ تمارين محلولة\n• تمرين 1: اذكر أربع معلومات أساسية يجب قراءتها من لوحة محرك كهربائي.\n• الحل:\n   – التوتر (V)، التيار الاسمي (A)، القدرة (kW)، السرعة (tr/min)\n   – (وكذلك التردد ونمط الربط)\n• تمرين 2: محرك لوحته ⁦230/400 V⁩ وشبكة ثلاثية الطور ⁦400 V⁩ بين الأطوار. أي ربط نستعمل؟\n• الحل:\n   – الملف يتحمل 230 V\n   – على شبكة 400 V نربطه بنجمة ليأخذ كل ملف ⁦400/√3 ≈ 230 V⁩\n• تمرين 3: ما الفحوصات قبل تشغيل محرك؟\n• الحل:\n   – التوتر الاسمي، الحماية الحرارية، التأريض، واستمرارية التوصيلات\n▸ للحفظ\n• لوحة المحرك: V، A، Hz، kW، tr/min، ربط. 230/400 V: نجمة على 400 V ومثلث على 230 V."}].concat(o.lessons||[]),maps:'gele'});})();
  (function(){var o=A['genie-civil']||{};A['genie-civil']=Object.assign({name:'الهندسة المدنية'},o,{lessons:[{"title":"1. قراءة المخططات","content":"▸ ماذا نقرأ؟\n• العنوان والمقياس\n• الاتجاهات والمستويات\n• المحاور والأبعاد والرموز والقطاعات\n▸ المخطط المعماري\n• تنظيم الفضاءات\n• الفتحات والأبعاد\n• الشكل العام\n▸ المخطط الإنشائي\n• العناصر الحاملة\n• التسليح\n• التفاصيل التنفيذية\n▸ المقياس\n• ⁦1:100⁩ يعني ⁦1 cm⁩ يمثل ⁦1 m⁩\n• الطول المرسوم = الحقيقي × المقياس\n• البعد المكتوب هو المرجع\n▸ أخطاء شائعة\n• قياس البعد من الورقة\n• الخلط بين المقياسين\n• إهمال المستويات\n▸ شرح مبسط\n• المخطط عقد بين المهندس والمنفذ. المعماري يقول كيف يبدو المبنى، والإنشائي يقول كيف يقف. اقرأ العنوان والمقياس أولا ثم الأبعاد المكتوبة، فهي المرجع.\n▸ طرق وقواعد\n• اكتب المقياس كنسبة.\n• حوّل الوحدات قبل الحساب.\n• فرّق بين المعماري والإنشائي.\n▸ تمارين محلولة\n• تمرين 1: مقياس ⁦1:100⁩. ماذا يمثل ⁦1 cm⁩ على المخطط؟\n• الحل:\n   – ⁦1 cm × 100 = 100 cm = 1 m⁩ في الواقع\n• تمرين 2: جدار طوله ⁦4.5 m⁩ بمقياس ⁦1:50⁩. ما طوله على المخطط؟\n• الحل:\n   – ⁦4.5 m = 450 cm⁩\n   – الطول على المخطط ⁦450/50 = 9 cm⁩\n• تمرين 3: ما الفرق بين المخطط المعماري والإنشائي؟\n• الحل:\n   – المعماري يبين الفضاءات والفتحات والأبعاد\n   – الإنشائي يبين العناصر الحاملة والتسليح والتفاصيل التنفيذية\n▸ للحفظ\n• الطول المرسوم = الحقيقي × المقياس. المعماري: فضاءات. الإنشائي: عناصر حاملة وتسليح."},{"title":"2. مواد البناء والخرسانة","content":"▸ الخرسانة\n• رابط إسمنتي + ماء + ركام\n• مقاومة الضغط أعلى من الشد\n• قد تضاف إضافات\n▸ الفولاذ\n• مقاومة جيدة للشد\n• ليونة\n• يستعمل في الخرسانة المسلحة\n▸ الخرسانة المسلحة\n• خرسانة تقاوم الضغط\n• فولاذ يقاوم الشد\n• تعاون المادتين\n▸ جودة الخرسانة\n• نسبة الماء إلى الإسمنت\n• نوع الركام والخلط والدمك\n• المعالجة وظروف التنفيذ\n▸ أخطاء شائعة\n• زيادة الماء بلا حساب\n• إهمال الدمك والمعالجة\n• وضع التسليح في منطقة الضغط\n▸ شرح مبسط\n• الخرسانة قوية جدا في الضغط وضعيفة في الشد. الفولاذ قوي في الشد. فنضع الفولاذ في المناطق المشدودة فنحصل على مادة تجمع الاثنين. ومن أهم أسباب ضعف الخرسانة زيادة الماء وسوء الدمك.\n▸ طرق وقواعد\n• الخرسانة تضغط والفولاذ يشد.\n• قلل نسبة الماء إلى الإسمنت.\n• لا تهمل الدمك والمعالجة.\n▸ تمارين محلولة\n• تمرين 1: لماذا توضع قضبان التسليح في مناطق الشد في الجائز؟\n• الحل:\n   – لأن الخرسانة ضعيفة في الشد، والفولاذ مقاوم جيد للشد\n   – فيتحمل الفولاذ قوى الشد في الجائز\n• تمرين 2: ما العوامل المؤثرة في جودة الخرسانة؟\n• الحل:\n   – نسبة الماء إلى الإسمنت، نوع الركام، الخلط، الدمك، المعالجة، وظروف التنفيذ\n• تمرين 3: لماذا تسمى الخرسانة المسلحة مادة مركبة؟\n• الحل:\n   – لأنها تجمع مادتين: الخرسانة التي تقاوم الضغط والفولاذ الذي يقاوم الشد\n▸ للحفظ\n• خرسانة: ضغط. فولاذ: شد. الخرسانة المسلحة تجمعهما. جودة الخرسانة: ماء/إسمنت، ركام، دمك، معالجة."},{"title":"3. القوى وردود الأفعال","content":"▸ شروط التوازن\n• ⁦ΣFx = 0⁩\n• ⁦ΣFy = 0⁩\n• ⁦ΣM = 0⁩\n▸ المساند\n• دعامة مفصلية تمنع الانتقالات\n• مسند متحرك يولد رد فعل عموديا\n• مسند مثبت (ظفر) يمنع كل شيء\n▸ مخطط الجسم الحر\n• ارسمه قبل المعادلات\n• حدد كل قوة واتجاهها\n• ونقطة تأثيرها\n▸ الخطوات\n• 1) الجسم الحر\n• 2) المعادلات الثلاث\n• 3) حل ردود الأفعال\n▸ أخطاء شائعة\n• نسيان رد فعل\n• إشارة العزم\n• اختيار نقطة عزم غير مناسبة\n▸ شرح مبسط\n• الجسم في التوازن لا يتحرك ولا يدور. لذلك مجموع القوى صفر ومجموع العزوم صفر. نبدأ دائما برسم الجسم وحده مع كل القوى عليه، ثم نكتب المعادلات الثلاث.\n▸ طرق وقواعد\n• خذ العزوم حول نقطة مجهولة لتبسيط الحل.\n• حافظ على اصطلاح الإشارات.\n• تحقق بمعادلة إضافية.\n▸ تمارين محلولة\n• تمرين 1: ما المعادلات الثلاث التي تستعمل عادة لدراسة توازن جسم في مستوى؟\n• الحل:\n   – ⁦ΣFx = 0⁩ و ⁦ΣFy = 0⁩ و ⁦ΣM = 0⁩\n• تمرين 2: جائز طوله ⁦4 m⁩ على مسندين ⁦A⁩ و ⁦B⁩ يحمل ⁦10 kN⁩ في المنتصف. احسب ردي الفعل.\n• الحل:\n   – بالتناظر ⁦R_(A) = R_(B) = 10/2 = 5 kN⁩\n   – تحقق: ⁦R_(A) + R_(B) = 10 kN⁩\n• تمرين 3: نفس الجائز يحمل ⁦12 kN⁩ على بعد ⁦1 m⁩ من ⁦A⁩. احسب ⁦R_(B)⁩ ثم ⁦R_(A)⁩.\n• الحل:\n   – ⁦ΣM_(A) = 0⁩: ⁦R_(B) × 4 - 12 × 1 = 0⁩ فـ ⁦R_(B) = 3 kN⁩\n   – ⁦ΣFy = 0⁩: ⁦R_(A) = 12 - 3 = 9 kN⁩\n▸ للحفظ\n• ⁦ΣFx = 0⁩، ⁦ΣFy = 0⁩، ⁦ΣM = 0⁩. ارسم الجسم الحر أولا. عزوم حول نقطة مجهولة."},{"title":"4. الإجهادات ومقاومة المواد","content":"▸ الإجهاد العادي\n• ⁦σ = N/S⁩\n• ⁦N⁩ القوة المحورية\n• ⁦S⁩ مساحة المقطع\n▸ الوحدات\n• ⁦N⁩ بالنيوتن و ⁦S⁩ بـ ⁦mm²⁩\n• النتيجة بـ ⁦N/mm²⁩\n• تساوي عدديا ⁦MPa⁩\n▸ شرط المقاومة\n• ⁦σ ≤ σₐdm⁩\n• ⁦σₐdm = σₑ/s⁩\n• ⁦s⁩ معامل الأمان\n▸ خطأ شائع\n• خلط مقاومة المادة بالإجهاد الفعلي\n• نسيان معامل الأمان\n• وحدات غير متجانسة\n▸ تطبيق\n• قوة محورية على مقطع\n• قارن بالإجهاد المسموح\n• استنتج الأمان\n▸ شرح مبسط\n• الإجهاد هو القوة لكل وحدة مساحة. إذا كان الإجهاد الفعلي أقل من الإجهاد المسموح (وهو حد المادة مقسوما على معامل أمان) فالعنصر آمن.\n▸ طرق وقواعد\n• ⁦kN⁩ إلى ⁦N⁩ ثم قسمة على ⁦mm²⁩.\n• احسب ⁦σₐdm⁩ من الحد المرن ومعامل الأمان.\n• قارن واكتب النتيجة.\n▸ تمارين محلولة\n• تمرين 1: قوة محورية ⁦20 kN⁩ على مقطع ⁦400 mm²⁩. احسب ⁦σ⁩.\n• الحل:\n   – ⁦σ = 20000/400 = 50 MPa⁩\n• تمرين 2: قوة ⁦30 kN⁩ على مساحة ⁦600 mm²⁩. احسب الإجهاد المتوسط.\n• الحل:\n   – ⁦σ = 30000/600 = 50 MPa⁩\n• تمرين 3: فولاذ حده المرن ⁦235 MPa⁩ ومعامل الأمان ⁦1.5⁩. احسب ⁦σₐdm⁩ وتحقق من مقطع تحمل ⁦σ = 100 MPa⁩.\n• الحل:\n   – ⁦σₐdm = 235/1.5 ≈ 156.7 MPa⁩\n   – بما أن ⁦100 ≤ 156.7⁩ فالمقطع آمن\n▸ للحفظ\n• ⁦σ = N/S⁩ و ⁦σ ≤ σₐdm = σₑ/s⁩. N/mm² = MPa."},{"title":"5. الجوائز والأعمدة والأساسات","content":"▸ الجائز\n• عنصر أفقي أو مائل\n• ينقل الأحمال إلى المساند\n• يتعرض للقص والانحناء\n▸ العمود\n• عنصر حامل\n• يتعرض للضغط المحوري\n• قد ينبعج إذا كان طويلا ونحيفا\n▸ الأساس\n• ينقل الأحمال إلى التربة\n• يوزعها ضمن قدرة تحملها\n• يتأثر بالتربة والمياه الجوفية\n▸ ضغط التربة\n• ⁦q = N/A⁩\n• ⁦N⁩ الحمل و ⁦A⁩ مساحة القاعدة\n• يجب أن يكون أقل من التحمل المسموح\n▸ أخطاء شائعة\n• الاكتفاء بمقاومة الخرسانة\n• إهمال الاستقرار والتربة\n• إهمال الانبعاج\n▸ شرح مبسط\n• المبنى سلسلة نقل أحمال: البلاطة تنقل للجائز، والجائز للعمود، والعمود للأساس، والأساس للتربة. كل حلقة يجب أن تتحمل، ولا يكفي أن تكون الخرسانة قوية بل يجب فحص الأبعاد والتسليح والتربة.\n▸ طرق وقواعد\n• تتبع مسار الحمل حتى التربة.\n• احسب ضغط التربة ⁦q = N/A⁩.\n• العمود النحيف يفحص للانبعاج.\n▸ تمارين محلولة\n• تمرين 1: اذكر وظيفتين للأساسات، وسبب احتمال انبعاج عمود نحيف.\n• الحل:\n   – الأساس ينقل أحمال المنشأ إلى التربة ويوزعها ضمن قدرة تحملها\n   – العمود النحيف قد ينبعج لأن طوله كبير بالنسبة لمقطعه فيفقد استقراره قبل أن يصل إلى مقاومة الضغط\n• تمرين 2: أساس مربع ⁦1.5 m × 1.5 m⁩ يحمل ⁦150 kN⁩. احسب ضغط التربة.\n• الحل:\n   – ⁦A = 1.5 × 1.5 = 2.25 m²⁩\n   – ⁦q = 150/2.25 ≈ 66.7 kPa⁩\n• تمرين 3: كيف ينتقل الحمل من بلاطة إلى التربة؟\n• الحل:\n   – من البلاطة إلى الجوائز ثم الأعمدة ثم الأساسات ثم التربة\n▸ للحفظ\n• حمل ⟵ جائز ⟵ عمود ⟵ أساس ⟵ تربة. ⁦q = N/A⁩. عمود نحيف قد ينبعج."},{"title":"6. الكميات والمقاييس","content":"▸ الحجوم\n• منشوري = مساحة المقطع × الطول\n• متوازي المستطيلات = الطول × العرض × الارتفاع\n• ⁦V = L × l × h⁩\n▸ الوحدات\n• وحّد الوحدات قبل الحساب\n• ⁦m⁩ مع ⁦m²⁩ و ⁦m³⁩\n• ⁦cm⁩ مع ⁦cm²⁩ و ⁦cm³⁩\n▸ تقدير الخرسانة\n• احسب كل عنصر على حدة\n• اجمع الأحجام\n• راعِ الفتحات المطلوبة\n▸ التحويل\n• ⁦1 m³ = 1000 L⁩\n• ⁦1 m = 100 cm⁩\n• ⁦1 m³ = 10⁶ cm³⁩\n▸ أخطاء شائعة\n• خلط ⁦cm⁩ مع ⁦m⁩\n• نسيان بعض العناصر\n• عدم طرح الفتحات\n▸ شرح مبسط\n• تقدير الكميات يعني حساب حجم الخرسانة أو الحديد أو غيرها قبل التنفيذ. نقسم المنشأ إلى عناصر بسيطة نحسب حجم كل منها ثم نجمعها. الشرط الأول: توحيد الوحدات.\n▸ طرق وقواعد\n• حوّل كل الأبعاد إلى المتر.\n• احسب كل عنصر بمفرده.\n• اجمع ثم راجع الفتحات.\n▸ تمارين محلولة\n• تمرين 1: بلاطة ⁦5 m × 4 m × 0.12 m⁩. احسب حجمها.\n• الحل:\n   – ⁦V = 5 × 4 × 0.12 = 2.4 m³⁩\n• تمرين 2: احسب حجم قاعدة أبعادها ⁦1.5 m × 1.5 m × 0.4 m⁩.\n• الحل:\n   – ⁦V = 1.5 × 1.5 × 0.4 = 0.9 m³⁩\n• تمرين 3: بلاطة ⁦2.4 m³⁩ وقاعدة ⁦0.9 m³⁩. ما الحجم الإجمالي من الخرسانة؟\n• الحل:\n   – ⁦2.4 + 0.9 = 3.3 m³⁩\n▸ للحفظ\n• ⁦V = L × l × h⁩. وحّد الوحدات. احسب كل عنصر ثم اجمع."}].concat(o.lessons||[]),maps:'gciv'});})();
  (function(){var o=A['genie-procedes']||{};A['genie-procedes']=Object.assign({name:'هندسة الطرائق'},o,{lessons:[{"title":"1. الفحوم الهيدروجينية","content":"▸ التعريف\n• مركبات من ⁦C⁩ و ⁦H⁩ فقط\n• ألكانات: روابط أحادية\n• ألكينات: رابطة مزدوجة\n▸ الصيغ العامة\n• ألكانات ⁦CₙH₂ₙ₊₂⁩\n• ألكينات ⁦CₙH₂ₙ⁩\n• ألكاينات ⁦CₙH₂ₙ₋₂⁩\n▸ التفاعلات\n• الاحتراق\n• الإضافة إلى الروابط المتعددة\n• الهلجنة والأكسدة\n▸ أمثلة\n• ⁦C₂H₆⁩ إيثان (ألكان)\n• ⁦C₂H₄⁩ إيثين (ألكين)\n• ⁦C₂H₂⁩ إيثاين (ألكاين)\n▸ أخطاء شائعة\n• الخلط بين الصيغ العامة\n• أخطاء في عدد ذرات ⁦H⁩\n• نسيان موازنة معادلة الاحتراق\n▸ شرح مبسط\n• الفحوم الهيدروجينية هي أبسط المركبات العضوية: كربون وهيدروجين فقط. كلما وُجدت روابط مضاعفة قل عدد ذرات الهيدروجين. الصيغ العامة تساعدك على إيجاد الصيغة الجزيئية من عدد ذرات الكربون.\n▸ طرق وقواعد\n• عوّض ⁦n⁩ في الصيغة العامة.\n• وازن معادلة الاحتراق: ⁦C⁩ ثم ⁦H⁩ ثم ⁦O⁩.\n• الرابطة المتعددة تعني تفاعلات إضافة.\n▸ تمارين محلولة\n• تمرين 1: اكتب الصيغة الجزيئية لألكان يحوي 5 ذرات كربون.\n• الحل:\n   – ⁦CₙH₂ₙ₊₂⁩ مع ⁦n = 5⁩: ⁦C₅H₁₂⁩\n• تمرين 2: اكتب صيغتي ألكين فيه 4 كربونات وألكاين فيه 3 كربونات.\n• الحل:\n   – الألكين ⁦C₄H₈⁩ (⁦2n = 8⁩)\n   – الألكاين ⁦C₃H₄⁩ (⁦2n - 2 = 4⁩)\n• تمرين 3: وازن احتراق الإيثان.\n• الحل:\n   – ⁦2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O⁩\n   – التحقق: ⁦C: 4 = 4⁩ و ⁦H: 12 = 12⁩ و ⁦O: 14 = 8 + 6⁩\n▸ للحفظ\n• ألكان ⁦CₙH₂ₙ₊₂⁩ وألكين ⁦CₙH₂ₙ⁩ وألكاين ⁦CₙH₂ₙ₋₂⁩. الاحتراق، الإضافة، الهلجنة."},{"title":"2. الوظائف الأكسجينية","content":"▸ الوظائف\n• كحول ⁦–OH⁩\n• ألدهيد ⁦–CHO⁩\n• كيتون ⁦C=O⁩ داخل السلسلة\n▸ الحمض الكربوكسيلي\n• ⁦–COOH⁩\n• ينتج من أكسدة الألدهيد\n• يتفاعل مع الكحول لإعطاء إستر\n▸ الأكسدة\n• كحول أولي ⟵ ألدهيد ⟵ حمض\n• كحول ثانوي ⟵ كيتون\n• تتوقف على شروط التفاعل\n▸ الأسترة\n• حمض + كحول ⇌ إستر + ماء\n• غالبا بحفاز حمضي\n• التفاعل عكوس\n▸ أخطاء شائعة\n• الخلط بين الألدهيد والكيتون\n• نسيان الماء في الأسترة\n• اعتبار الأسترة تامة\n▸ شرح مبسط\n• الوظيفة الكيميائية هي بطاقة المركب. المجموعة المميزة تقرر خواصه: هل هو كحول أم حمض. والأسترة كالزواج بين حمض وكحول ينتج إسترا وماء، لكنها عكوسة فلا تكتمل عادة.\n▸ طرق وقواعد\n• تعرف على المجموعة المميزة أولا.\n• الأولي يعطي ألدهيدا والثانوي كيتونا.\n• اكتب سهمي عكس في الأسترة.\n▸ تمارين محلولة\n• تمرين 1: ميّز بين الصيغة الوظيفية للكحول والألدهيد والحمض الكربوكسيلي.\n• الحل:\n   – الكحول ⁦R–OH⁩\n   – الألدهيد ⁦R–CHO⁩\n   – الحمض الكربوكسيلي ⁦R–COOH⁩\n• تمرين 2: اكتب معادلة أسترة حمض الإيثانويك مع الإيثانول.\n• الحل:\n   – ⁦CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O⁩\n   – الإستر: إيثانوات الإيثيل\n• تمرين 3: ماذا يعطي كحول ثانوي عند الأكسدة؟\n• الحل:\n   – يعطي كيتونا\n▸ للحفظ\n• ⁦–OH⁩ كحول، ⁦–CHO⁩ ألدهيد، ⁦–COOH⁩ حمض. أسترة: حمض + كحول ⇌ إستر + ماء."},{"title":"3. الأمينات والبوليميرات","content":"▸ الأمينات\n• مشتقات الأمونياك\n• أولية وثانوية وثالثية\n• بحسب مجموعات ⁦R⁩ المرتبطة بـ ⁦N⁩\n▸ البوليمير\n• جزيء كبير\n• تكرار وحدات بنائية\n• المونومير هو الجزيء الصغير\n▸ بلمرة بالإضافة\n• فتح رابطة متعددة\n• لا يُطرح جزيء صغير\n• مثل الإيثين\n▸ بلمرة بالتكاثف\n• قد يُطرح جزيء صغير\n• مثل الماء\n• أمثلة: النايلون\n▸ استعمالات\n• التغليف\n• الأنابيب\n• الألياف\n▸ شرح مبسط\n• البوليمير سلسلة من حلقات متشابهة (المونومير) كعقد من الخرز. في البلمرة بالإضافة تتصل الحلقات بفتح الرابطة المزدوجة فقط، أما بالتكاثف فتتصل مع خروج جزيء صغير مثل الماء.\n▸ طرق وقواعد\n• صنف الأمين حسب عدد مجموعات ⁦R⁩ على ⁦N⁩.\n• أضف: لا جزيء صغير. تكاثف: جزيء صغير.\n• اكتب المونومير ثم البوليمير.\n▸ تمارين محلولة\n• تمرين 1: ما الفرق الأساسي بين البلمرة بالإضافة والبلمرة بالتكاثف؟\n• الحل:\n   – في الإضافة تُفتح الرابطة المتعددة دون إطلاق جزيء صغير\n   – في التكاثف يُطرح جزيء صغير مثل الماء\n• تمرين 2: اكتب معادلة بلمرة الإيثين.\n• الحل:\n   – ⁦n CH₂=CH₂ → (–CH₂–CH₂–)ₙ⁩\n   – الناتج بولي إيثيلين\n• تمرين 3: كيف تصنف الأمين الذي يحمل مجموعتين عضويتين على النتروجين؟\n• الحل:\n   – أمين ثانوي\n▸ للحفظ\n• بوليمير = تكرار مونومير. إضافة: بلا جزيء صغير. تكاثف: مع طرح (مثل الماء)."},{"title":"4. الليبيدات","content":"▸ الليبيدات\n• قليلة الذوبان في الماء\n• دهون وزيوت\n• مركبات عضوية متنوعة\n▸ الغليسيريد الثلاثي\n• غليسرول + 3 أحماض دهنية\n• روابط إسترية\n• دهن أو زيت\n▸ التفاعلات\n• التصبن\n• الهدرجة\n• الحلمهة\n▸ القرائن\n• قرينة الحموضة: القاعدة لمعادلة الأحماض الحرة\n• قرينة التصبن: القاعدة لتصبن العينة\n• تقدر بـ ⁦mg KOH/g⁩\n▸ أخطاء شائعة\n• الخلط بين قرينة الحموضة والتصبن\n• وحدات ⁦mg⁩ و ⁦g⁩\n• خلط الأحماض الحرة بالإسترات\n▸ شرح مبسط\n• الدهن عبارة عن غليسرول يمسك ثلاثة أحماض دهنية. عندما نعالجه بقاعدة نكسر الروابط (التصبن) فنحصل على غليسرول وصابون. قرينة الحموضة تقول لنا كم من الأحماض الحرة في الدهن.\n▸ طرق وقواعد\n• قرينة الحموضة = كتلة ⁦KOH⁩ (mg) لكل غرام دهن.\n• التصبن حلمهة قاعدية للإسترات.\n• ⁦M(KOH) = 56.1 g/mol⁩.\n▸ تمارين محلولة\n• تمرين 1: اذكر مكوني الغليسيريد الثلاثي، وعرّف التصبن بإيجاز.\n• الحل:\n   – المكونان: الغليسرول وثلاثة أحماض دهنية\n   – التصبن حلمهة قاعدية للإسترات الدهنية تعطي الغليسرول وأملاح الأحماض الدهنية (الصابون)\n• تمرين 2: عُدّلت ⁦5 g⁩ من دهن بـ ⁦2.8 mL⁩ من ⁦KOH⁩ تركيزه ⁦0.1 mol/L⁩. احسب قرينة الحموضة.\n• الحل:\n   – ⁦n = 0.1 × 2.8 = 0.28 mmol⁩\n   – كتلة ⁦KOH⁩ ⁦= 0.28 × 56.1 ≈ 15.7 mg⁩\n   – القرينة ⁦15.7/5 ≈ 3.14 mg/g⁩\n• تمرين 3: ما المنتجات الرئيسية للتصبن؟\n• الحل:\n   – الغليسرول وأملاح الأحماض الدهنية (الصابون)\n▸ للحفظ\n• غليسيريد ثلاثي = غليسرول + 3 أحماض دهنية. تصبن: غليسرول + صابون. قرينة الحموضة mg KOH/g."},{"title":"5. الأحماض الأمينية والبروتينات","content":"▸ الحمض الأميني\n• مجموعة أمينية ⁦–NH₂⁩\n• مجموعة كربوكسيلية ⁦–COOH⁩\n• سلسلة جانبية ⁦R⁩ متغيرة\n▸ الرابطة الببتيدية\n• بين ⁦–COOH⁩ لحمض و ⁦–NH₂⁩ لآخر\n• تطرح جزيء ماء\n• تعطي ثنائي ببتيد\n▸ البروتين\n• عديد ببتيد\n• يتشكل بتتابع الأحماض\n• بنية ثلاثية الأبعاد\n▸ التمسخ\n• بالحرارة أو الحموضة أو مواد كيميائية\n• تتغير البنية والخواص\n• السلسلة الرئيسية غالبا سليمة\n▸ أخطاء شائعة\n• الخلط بين الرابطة الببتيدية والإسترية\n• نسيان الماء المطروح\n• عدد الروابط: ⁦n - 1⁩\n▸ شرح مبسط\n• الأحماض الأمينية كقطع ليغو لها وجهان: مجموعة أمين ومجموعة كربوكسيل. تتصل بينها برابطة ببتيدية وتطرح ماء. سلسلة طويلة منها تصنع البروتين. والحرارة قد تفتح بنيته (تمسخ) دون قطع السلسلة.\n▸ طرق وقواعد\n• اربط ⁦–COOH⁩ لأول بـ ⁦–NH₂⁩ للثاني.\n• عدد جزيئات الماء المطروحة = عدد الروابط.\n• لـ ⁦n⁩ حمضا: ⁦n - 1⁩ رابطة.\n▸ تمارين محلولة\n• تمرين 1: ما المجموعتان الوظيفيتان الأساسيتان في الحمض الأميني؟\n• الحل:\n   – المجموعة الأمينية ⁦–NH₂⁩ والمجموعة الكربوكسيلية ⁦–COOH⁩\n• تمرين 2: كم جزيء ماء يُطرح عند تكوين ثلاثي ببتيد من 3 أحماض؟\n• الحل:\n   – عدد الروابط ⁦3 - 1 = 2⁩ فيُطرح ⁦2⁩ جزيء ماء\n• تمرين 3: ما المقصود بالتمسخ؟\n• الحل:\n   – تغير بنية البروتين وخواصه بتأثير الحرارة أو الحموضة أو مواد كيميائية، غالبا دون كسر السلسلة الرئيسية\n▸ للحفظ\n• حمض أميني: ⁦–NH₂⁩ و ⁦–COOH⁩. رابطة ببتيدية بطرح ماء. n حمضا: n - 1 رابطة."},{"title":"6. الديناميكا الحرارية الكيميائية","content":"▸ نوعا التفاعل\n• ناشر للحرارة ⁦ΔH < 0⁩\n• ماص للحرارة ⁦ΔH > 0⁩\n• الطاقة تنتقل مع المحيط\n▸ الحرارة\n• ⁦Q = m·c·ΔT⁩\n• ⁦c ≈ 4.18 J·g⁻¹·°C⁻¹⁩ للماء\n• وحّد الوحدات\n▸ إنثالبي التفاعل\n• ⁦ΔH⁩ سالبة: ناشر\n• ⁦ΔH⁩ موجبة: ماص\n• وفق الاصطلاح الشائع\n▸ خطوات الحل\n• حدد ⁦m⁩ و ⁦c⁩ و ⁦ΔT⁩\n• احسب ⁦Q⁩\n• حوّل إلى ⁦kJ⁩ عند الحاجة\n▸ أخطاء شائعة\n• ⁦ΔT⁩ بإشارة خاطئة\n• وحدات ⁦g⁩ و ⁦kg⁩\n• الخلط بين ⁦ΔH⁩ و ⁦Q⁩\n▸ شرح مبسط\n• الطاقة تُكتب مع كل تفاعل: إما أن تخرج حرارة (نشر، ΔH سالبة) كما في الاحتراق، أو تدخل (امتصاص، ΔH موجبة). وفي التسخين البسيط نحسب الحرارة بضرب الكتلة في السعة الحرارية في الفرق في درجة الحرارة.\n▸ طرق وقواعد\n• ⁦ΔT = T_(f) - Tᵢ⁩.\n• ⁦Q⁩ بـ ⁦J⁩ مع ⁦g⁩ و ⁦J·g⁻¹·°C⁻¹⁩.\n• ⁦ΔH < 0⁩ يعني تسخين المحيط.\n▸ تمارين محلولة\n• تمرين 1: ماذا تعني إشارة ⁦ΔH⁩ السالبة؟\n• الحل:\n   – أن التفاعل ناشر للحرارة: يطلق طاقة نحو المحيط\n• تمرين 2: لتسخين ⁦200 g⁩ ماء من ⁦20°C⁩ إلى ⁦30°C⁩ مع ⁦c ≈ 4.18 J·g⁻¹·°C⁻¹⁩ احسب ⁦Q⁩.\n• الحل:\n   – ⁦Q = 200 × 4.18 × 10 = 8360 J⁩\n• تمرين 3: احسب الحرارة اللازمة لتسخين ⁦500 g⁩ ماء من ⁦15°C⁩ إلى ⁦65°C⁩.\n• الحل:\n   – ⁦ΔT = 50°C⁩\n   – ⁦Q = 500 × 4.18 × 50 = 104500 J = 104.5 kJ⁩\n▸ للحفظ\n• ⁦Q = m·c·ΔT⁩. ⁦ΔH < 0⁩ ناشر، ⁦ΔH > 0⁩ ماص."},{"title":"7. الكيمياء الحركية","content":"▸ السرعة\n• تغير التركيز مع الزمن\n• ⁦v = ΔC/Δt⁩\n• تُتبع بالتركيز أو الحجم أو الضغط\n▸ العوامل\n• درجة الحرارة\n• التركيز\n• مساحة سطح التلامس والحفاز\n▸ الحفاز\n• يزيد السرعة\n• يخفض طاقة التنشيط\n• لا يُستهلك في الحصيلة\n▸ المنحنى\n• ⁦C = f(t)⁩\n• الميل الأكبر يعني سرعة أكبر\n• السرعة أكبر في البداية غالبا\n▸ أخطاء شائعة\n• قول إن الحفاز يغير الحصيلة النهائية\n• عدم أخذ القيمة المطلقة\n• إهمال الوحدات\n▸ شرح مبسط\n• سرعة التفاعل هي مدى سرعة اختفاء المتفاعلات. الحرارة والتركيز يزيدان عدد التصادمات الفعالة فتزيد السرعة. الحفاز يفتح طريقا أسهل للتفاعل فيسرعه، لكنه لا يُستهلك.\n▸ طرق وقواعد\n• السرعة المتوسطة ⁦= |ΔC|/Δt⁩.\n• العوامل: حرارة، تركيز، سطح، حفاز.\n• ميل المنحنى يعطي السرعة اللحظية.\n▸ تمارين محلولة\n• تمرين 1: اذكر ثلاثة عوامل تؤثر في سرعة التفاعل، واشرح أثر أحدها.\n• الحل:\n   – درجة الحرارة والتركيز والحفاز\n   – ارتفاع الحرارة يزيد حركة الجزيئات وعدد التصادمات الفعالة فتزيد السرعة\n• تمرين 2: تركيز مادة ينتقل من ⁦0.50⁩ إلى ⁦0.30 mol/L⁩ خلال ⁦40 s⁩. احسب السرعة المتوسطة للاختفاء.\n• الحل:\n   – ⁦v = |0.30 - 0.50|/40 = 0.20/40 = 0.005 mol·L⁻¹·s⁻¹⁩\n• تمرين 3: كيف نعرف من منحنى التركيز متى يكون التفاعل أسرع؟\n• الحل:\n   – عندما يكون ميل المنحنى أكبر في القيمة المطلقة\n   – وهذا غالبا في البداية\n▸ للحفظ\n• ⁦v = |ΔC|/Δt⁩. العوامل: حرارة، تركيز، سطح، حفاز. الحفاز يخفض طاقة التنشيط."}].concat(o.lessons||[]),maps:'gpro'});})();
  A.physics=Object.assign({name:'العلوم الفيزيائية'},A.physics||{},{lessons:[{"title":"1. قوانين نيوتن","content":"▸ القانون الأول (العطالة)\n• ⁦ΣF = 0⁩ فالجسم ساكن أو في حركة مستقيمة منتظمة\n• الحفاظ على الحالة الحركية\n• يُطبق في معلم غاليلي\n▸ القانون الثاني\n• ⁦ΣF = m·a⁩\n• التسارع في اتجاه محصلة القوى\n• ⁦m⁩ بالكيلوغرام و ⁦F⁩ بالنيوتن\n▸ القانون الثالث\n• الفعل ورد الفعل متساويان ومتعاكسان\n• ⁦F_(A/B) = -F_(B/A)⁩\n• يؤثران على جسمين مختلفين\n▸ منهج الحل\n• 1) حدد الجملة والمعلم\n• 2) مثّل القوى\n• 3) طبّق القانون الثاني وسقط على المحاور\n▸ أخطاء شائعة\n• خلط القوة بالسرعة\n• نسيان قوة أو إشارتها\n• اعتبار الفعل ورد الفعل على نفس الجسم\n▸ شرح مبسط\n• كل جسم يقاوم تغيير حركته (العطالة). إذا أردنا تغيير سرعته نحتاج قوة محصلة، وكلما كانت كتلته أكبر احتجنا قوة أكبر لنفس التسارع. والقوة لا تأتي وحدها: كل جسم يدفع جسما آخر يُدفع في المقابل.\n▸ طرق وقواعد\n• ارسم القوى قبل أي معادلة.\n• سقّط المعادلة الشعاعية على محورين.\n• تسارع ثابت يعني حركة متغيرة بانتظام.\n▸ تمارين محلولة\n• تمرين 1: جسم كتلته ⁦2 kg⁩ تؤثر عليه قوتان ⁦10 N⁩ و ⁦4 N⁩ متعاكستان على نفس الحامل. احسب تسارعه.\n• الحل:\n   – المحصلة ⁦10 - 4 = 6 N⁩\n   – ⁦a = ΣF/m = 6/2 = 3 m/s²⁩ في اتجاه القوة الأكبر\n• تمرين 2: جسم كتلته ⁦5 kg⁩ على مستو مائل أملس بزاوية ⁦30°⁩. احسب تسارعه (⁦g = 9.8⁩).\n• الحل:\n   – القوة المؤثرة على امتداد المستوي ⁦P·sin α = m·g·sin α⁩\n   – ⁦a = g·sin 30° = 9.8 × 0.5 = 4.9 m/s²⁩\n• تمرين 3: سيارة كتلتها ⁦1000 kg⁩ تنتقل من السكون إلى ⁦20 m/s⁩ خلال ⁦10 s⁩ بتسارع ثابت. احسب القوة المحصلة.\n• الحل:\n   – ⁦a = Δv/Δt = 20/10 = 2 m/s²⁩\n   – ⁦ΣF = m·a = 1000 × 2 = 2000 N⁩\n▸ للحفظ\n• ⁦ΣF = m·a⁩. إذا ⁦ΣF = 0⁩ فحركة مستقيمة منتظمة أو سكون. فعل = رد فعل في المقدار ومعاكس في الاتجاه."},{"title":"2. السقوط الشاقولي ودافعة أرخميدس","content":"▸ السقوط الحر\n• القوة الوحيدة الثقل ⁦P = m·g⁩\n• ⁦a = g⁩ ثابت\n• ⁦v = g·t⁩ و ⁦y = (1/2)·g·t²⁩\n▸ دافعة أرخميدس\n• ⁦Π = ρ_(fl)·V·g⁩\n• موجهة نحو الأعلى\n• ⁦V⁩ حجم الجزء المغمور\n▸ السقوط في مائع\n• الثقل ⁦P⁩ والدافعة ⁦Π⁩ والاحتكاك ⁦f = k·v⁩\n• المعادلة التفاضلية للسرعة\n• تبلغ السرعة قيمة حدية\n▸ السرعة الحدية\n• تنعدم المحصلة: ⁦P - Π - k·v_(lim) = 0⁩\n• ⁦v_(lim) = (P - Π)/k⁩\n• حركة مستقيمة منتظمة بعدها\n▸ أخطاء شائعة\n• إهمال الدافعة في الماء\n• خلط حجم الجسم والجزء المغمور\n• نسيان اتجاه الاحتكاك\n▸ شرح مبسط\n• عندما نترك جسما في الفراغ يسقط بتسارع ثابت g. في مائع نضيف قوتين: الدافعة تدفع للأعلى والاحتكاك يزيد مع السرعة. عندما تتوازن القوى تتوقف السرعة عن الازدياد وتصبح ثابتة: هي السرعة الحدية.\n▸ طرق وقواعد\n• ارسم الثقل والدافعة والاحتكاك.\n• للسرعة الحدية ضع ⁦a = 0⁩.\n• في السقوط الحر الكتلة لا تؤثر في الزمن.\n▸ تمارين محلولة\n• تمرين 1: حجر يُترك من ارتفاع ⁦20 m⁩ (⁦g = 9.8⁩). احسب زمن السقوط والسرعة عند الأرض.\n• الحل:\n   – ⁦h = (1/2)g·t²⁩ فـ ⁦t = √(2h/g) = √(40/9.8) ≈ 2.02 s⁩\n   – ⁦v = g·t ≈ 19.8 m/s⁩\n• تمرين 2: جسم حجمه ⁦2 L⁩ مغمور كليا في الماء (⁦ρ = 1000 kg/m³⁩). احسب دافعة أرخميدس.\n• الحل:\n   – ⁦V = 2×10⁻³ m³⁩\n   – ⁦Π = 1000 × 2×10⁻³ × 9.8 = 19.6 N⁩\n• تمرين 3: كرة ثقلها ⁦2 N⁩ ودافعتها ⁦0.5 N⁩ وثابت الاحتكاك ⁦k = 3 kg/s⁩. احسب السرعة الحدية.\n• الحل:\n   – ⁦v_(lim) = (P - Π)/k = (2 - 0.5)/3 = 0.5 m/s⁩\n▸ للحفظ\n• سقوط حر: ⁦a = g⁩. ⁦Π = ρ·V·g⁩. سرعة حدية: ⁦P - Π - k·v = 0⁩."},{"title":"3. حركة القذيفة","content":"▸ المعادلات الزمنية\n• ⁦x = (v₀·cos α)·t⁩\n• ⁦y = -(1/2)g·t² + (v₀·sin α)·t⁩\n• ⁦aₓ = 0⁩ و ⁦a_(y) = -g⁩\n▸ المسار\n• قطع مكافئ\n• ⁦y = -g·x²/(2v₀²cos²α) + x·tan α⁩\n• في مجال ثقالة منتظم\n▸ القمة والمدى\n• الارتفاع الأقصى ⁦h = v₀²sin²α/(2g)⁩\n• المدى ⁦R = v₀²sin 2α/g⁩\n• زمن الطيران ⁦t = 2v₀ sin α/g⁩\n▸ إطلاق أفقي\n• ⁦v_(y)(0) = 0⁩\n• ⁦t = √(2h/g)⁩\n• ⁦x = v₀·t⁩\n▸ أخطاء شائعة\n• خلط ⁦cos⁩ و ⁦sin⁩\n• نسيان الإشارة السالبة لـ ⁦g⁩\n• استعمال السرعة الابتدائية كاملة على المحورين\n▸ شرح مبسط\n• القذيفة تتحرك في اتجاهين مستقلين: أفقيا بسرعة ثابتة وشاقوليا بتسارع الثقالة. نفصل الحركتين ثم نجمعهما في معادلة المسار. أعلى نقطة تكون عندما تنعدم السرعة الشاقولية.\n▸ طرق وقواعد\n• حلّل ⁦v₀⁩ إلى مركبتين.\n• عند القمة ⁦v_(y) = 0⁩.\n• المدى أعظمي عند ⁦α = 45°⁩.\n▸ تمارين محلولة\n• تمرين 1: قذيفة سرعتها ⁦20 m/s⁩ بزاوية ⁦30°⁩ (⁦g = 9.8⁩). احسب المدى والارتفاع الأقصى وزمن الطيران.\n• الحل:\n   – ⁦R = 400 × sin 60°/9.8 = 400 × 0.866/9.8 ≈ 35.4 m⁩\n   – ⁦h = 400 × 0.25/19.6 ≈ 5.10 m⁩\n   – ⁦t = 2 × 20 × 0.5/9.8 ≈ 2.04 s⁩\n• تمرين 2: جسم يُقذف أفقيا بسرعة ⁦10 m/s⁩ من ارتفاع ⁦45 m⁩. أوجد زمن السقوط والمدى.\n• الحل:\n   – ⁦t = √(2 × 45/9.8) = √9.18 ≈ 3.03 s⁩\n   – ⁦x = v₀·t = 10 × 3.03 ≈ 30.3 m⁩\n• تمرين 3: ما الزاوية التي تعطي أكبر مدى؟ ولماذا؟\n• الحل:\n   – ⁦R = v₀²sin 2α/g⁩ أعظمية عندما ⁦sin 2α = 1⁩ أي ⁦α = 45°⁩\n▸ للحفظ\n• ⁦x = v₀ cos α·t⁩ و ⁦y = -g t²/2 + v₀ sin α·t⁩. ⁦R = v₀²sin 2α/g⁩. القمة: ⁦v_(y) = 0⁩."},{"title":"4. حركة الكواكب والأقمار الاصطناعية","content":"▸ قانون الجذب\n• ⁦F = G·m₁·m₂/r²⁩\n• ⁦G = 6.67×10⁻¹¹ SI⁩\n• قوة جاذبة متبادلة\n▸ حركة دائرية منتظمة\n• ⁦v = √(G·M/r)⁩\n• ⁦T = 2π·√(r³/(G·M))⁩\n• التسارع جاذبي مركزي\n▸ قوانين كبلر\n• مسار الكوكب إهليلجي\n• المساحات المكتسحة متساوية في أزمنة متساوية\n• ⁦T²/r³ = 4π²/(G·M)⁩\n▸ القمر الجيو مستقر\n• ⁦T = 24 h⁩ تقريبا\n• في المستوي الاستوائي\n• يظهر ثابتا في السماء\n▸ أخطاء شائعة\n• استعمال الارتفاع بدل ⁦r⁩\n• نسيان تحويل ⁦km⁩ إلى ⁦m⁩\n• الخلط بين كتلة القمر وكتلة الأرض\n▸ شرح مبسط\n• القمر الاصطناعي يسقط دائما نحو الأرض لكنه يتحرك أفقيا بسرعة كبيرة فيخطئ الأرض باستمرار فيدور حولها. البعد عن مركز الأرض هو ⁦r⁩ وليس الارتفاع فقط. كلما كان المدار أعلى كانت السرعة أقل والدور أكبر.\n▸ طرق وقواعد\n• ⁦r = R_(T) + h⁩.\n• السرعة لا تتعلق بكتلة القمر.\n• استعمل ⁦T²/r³⁩ ثابتا لمقارنة مدارين.\n▸ تمارين محلولة\n• تمرين 1: قمر على ارتفاع ⁦400 km⁩ (⁦M_(T) = 5.97×10²⁴ kg⁩، ⁦R_(T) = 6.37×10⁶ m⁩). احسب سرعته ودوره.\n• الحل:\n   – ⁦r = 6.77×10⁶ m⁩\n   – ⁦v = √(6.67×10⁻¹¹ × 5.97×10²⁴/6.77×10⁶) = √(5.88×10⁷) ≈ 7670 m/s⁩\n   – ⁦T = 2πr/v ≈ 5547 s ≈ 92.5 min⁩\n• تمرين 2: أوجد نصف قطر مدار قمر جيو مستقر (⁦T = 86164 s⁩).\n• الحل:\n   – ⁦r³ = G·M·T²/4π² = 3.98×10¹⁴ × 7.42×10⁹/39.5 ≈ 7.49×10²²⁩\n   – ⁦r ≈ 4.22×10⁷ m⁩\n   – الارتفاع ⁦r - R_(T) ≈ 3.58×10⁷ m⁩ أي ⁦35800 km⁩\n• تمرين 3: لماذا لا يسقط القمر الاصطناعي على الأرض؟\n• الحل:\n   – لأنه في سقوط حر مستمر نحو الأرض لكن بسرعة أفقية كبيرة فيدور حولها بدل أن يصطدم بها\n▸ للحفظ\n• ⁦v = √(GM/r)⁩ و ⁦T = 2π√(r³/GM)⁩. كبلر: ⁦T²/r³ = 4π²/GM⁩. ⁦r = R_(T) + h⁩."},{"title":"5. ثنائي القطب RC","content":"▸ الشحن\n• ⁦u_(C)(t) = E(1 - e^(-t/τ))⁩\n• ⁦i(t) = (E/R)·e^(-t/τ)⁩\n• التيار أعظمي عند البداية\n▸ التفريغ\n• ⁦u_(C)(t) = E·e^(-t/τ)⁩\n• ⁦i⁩ عكسية الإشارة\n• يتناقص أسيا\n▸ ثابت الزمن\n• ⁦τ = R·C⁩\n• عند ⁦t = τ⁩ تبلغ ⁦u_(C)⁩ نسبة ⁦63%⁩ من ⁦E⁩\n• عند ⁦t = 5τ⁩ يُعتبر الشحن تاما\n▸ الطاقة والشحنة\n• ⁦q = C·u_(C)⁩\n• ⁦E_(C) = (1/2)C·u_(C)²⁩\n• ⁦u_(C)⁩ متصلة دائما\n▸ أخطاء شائعة\n• خلط ⁦τ⁩ مع الزمن الكلي\n• نسيان وحدات ⁦μF⁩ و ⁦kΩ⁩\n• قول إن ⁦i⁩ متصلة عند التبديل\n▸ شرح مبسط\n• المكثفة كخزان ماء: تمتلئ بسرعة في البداية ثم ببطء. الزمن المميز ⁦τ = RC⁩ يحدد سرعة الامتلاء: مقاومة أكبر أو سعة أكبر تعني امتلاء أبطأ. التوتر بين طرفي المكثفة لا يقفز أبدا.\n▸ طرق وقواعد\n• ⁦τ⁩ بالثواني من ⁦R⁩ بالأوم و ⁦C⁩ بالفاراد.\n• عند ⁦t = τ⁩ الشحن ⁦63%⁩ والتفريغ يبقى ⁦37%⁩.\n• في النظام الدائم لا يمر تيار في فرع المكثفة.\n▸ تمارين محلولة\n• تمرين 1: ⁦R = 10 kΩ⁩ و ⁦C = 100 μF⁩. احسب ⁦τ⁩.\n• الحل:\n   – ⁦τ = R·C = 10⁴ × 10⁻⁴ = 1 s⁩\n• تمرين 2: شحن مكثفة بـ ⁦E = 12 V⁩ مع ⁦τ = 1 s⁩. احسب ⁦u_(C)⁩ عند ⁦t = τ⁩ والطاقة المخزنة النهائية (⁦C = 100 μF⁩).\n• الحل:\n   – ⁦u_(C)(τ) = 12 × (1 - e⁻¹) = 12 × 0.632 ≈ 7.58 V⁩\n   – ⁦E_(C) = (1/2) × 10⁻⁴ × 144 = 7.2×10⁻³ J⁩\n• تمرين 3: متى تبلغ ⁦u_(C) = 9 V⁩ علما أن ⁦E = 12 V⁩ و ⁦τ = 1 s⁩؟\n• الحل:\n   – ⁦9 = 12(1 - e^(-t/τ))⁩ فـ ⁦e^(-t/τ) = 0.25⁩\n   – ⁦t = τ·ln 4 ≈ 1.39 s⁩\n▸ للحفظ\n• شحن ⁦u_(C) = E(1 - e^(-t/τ))⁩. تفريغ ⁦u_(C) = E e^(-t/τ)⁩. ⁦τ = RC⁩. ⁦u_(C)⁩ متصلة."},{"title":"6. ثنائي القطب RL","content":"▸ إقامة التيار\n• ⁦i(t) = (E/R)(1 - e^(-t/τ))⁩\n• ⁦u_(L)(t) = E·e^(-t/τ)⁩\n• ⁦i⁩ متصلة دائما\n▸ ثابت الزمن\n• ⁦τ = L/R⁩\n• عند ⁦t = τ⁩ يبلغ ⁦i⁩ نسبة ⁦63%⁩ من قيمته النهائية\n• ⁦L⁩ بالهنري\n▸ القوة المحركة الذاتية\n• ⁦u_(L) = L·di/dt + r·i⁩\n• تعاكس تغير التيار\n• في النظام الدائم ⁦u_(L) = r·i⁩\n▸ الطاقة\n• ⁦E_(L) = (1/2)L·i²⁩\n• مخزنة في الحقل المغناطيسي\n• لا تتغير فجأة\n▸ أخطاء شائعة\n• خلط ⁦τ = L/R⁩ مع ⁦RC⁩\n• اعتبار التيار يقفز\n• إهمال المقاومة الداخلية للوشيعة\n▸ شرح مبسط\n• الوشيعة تقاوم تغير التيار: لا تسمح له بالارتفاع أو الانخفاض فجأة. لذلك يرتفع التيار تدريجيا نحو ⁦E/R⁩ بزمن مميز ⁦L/R⁩. وهي تخزن الطاقة في حقل مغناطيسي.\n▸ طرق وقواعد\n• ⁦τ = L/R⁩ ثانية.\n• النظام الدائم: ⁦i = E/R⁩ و ⁦u_(L) = 0⁩ (وشيعة مثالية).\n• التيار متصل والتوتر قد يقفز.\n▸ تمارين محلولة\n• تمرين 1: وشيعة ⁦L = 0.5 H⁩ ومقاومة ⁦R = 50 Ω⁩. احسب ⁦τ⁩.\n• الحل:\n   – ⁦τ = L/R = 0.5/50 = 0.01 s = 10 ms⁩\n• تمرين 2: في الدارة السابقة ⁦E = 10 V⁩. احسب التيار النهائي والطاقة المخزنة.\n• الحل:\n   – ⁦I = E/R = 10/50 = 0.2 A⁩\n   – ⁦E_(L) = (1/2) × 0.5 × 0.2² = 0.01 J⁩\n• تمرين 3: احسب التيار عند ⁦t = τ⁩.\n• الحل:\n   – ⁦i = 0.2 × (1 - e⁻¹) = 0.2 × 0.632 ≈ 0.126 A⁩\n▸ للحفظ\n• ⁦τ = L/R⁩. ⁦i = (E/R)(1 - e^(-t/τ))⁩. ⁦E_(L) = (1/2)L i²⁩. التيار متصل."},{"title":"7. الدارة RLC والاهتزازات الكهربائية","content":"▸ الدارة المثالية LC\n• اهتزازات جيبية دائمة\n• ⁦T₀ = 2π·√(L·C)⁩\n• ⁦f₀ = 1/T₀⁩\n▸ الدارة RLC\n• المقاومة تضيع الطاقة (جول)\n• اهتزازات متخامدة\n• أنظمة: دورية، لادورية، حرجة\n▸ الطاقة\n• ⁦E = (1/2)C·u_(C)² + (1/2)L·i²⁩\n• تنحفظ إذا ⁦R = 0⁩\n• تتناقص إذا ⁦R ≠ 0⁩\n▸ المعادلة التفاضلية\n• ⁦L·d²q/dt² + R·dq/dt + q/C = 0⁩\n• LC: ⁦d²q/dt² + q/(LC) = 0⁩\n• حلها ⁦q = Qₘ cos(2πt/T₀ + φ)⁩\n▸ أخطاء شائعة\n• الخلط بين ⁦T₀⁩ و ⁦τ⁩\n• نسيان الجذر التربيعي\n• اعتبار الطاقة منحفظة مع وجود ⁦R⁩\n▸ شرح مبسط\n• الدارة LC تشبه نابضا: الطاقة تنتقل بين المكثفة (طاقة كهربائية) والوشيعة (طاقة مغناطيسية) ذهابا وإيابا. إذا لم تكن هناك مقاومة لا تضيع الطاقة فتستمر الاهتزازات. المقاومة تحول الطاقة إلى حرارة فتخمد الاهتزازات.\n▸ طرق وقواعد\n• ⁦T₀ = 2π√(LC)⁩ بالثانية.\n• الطاقة الكلية تساوي الطاقة العظمى للمكثفة.\n• التخامد = ضياع بمفعول جول.\n▸ تمارين محلولة\n• تمرين 1: ⁦L = 0.1 H⁩ و ⁦C = 10 μF⁩. احسب ⁦T₀⁩ و ⁦f₀⁩.\n• الحل:\n   – ⁦LC = 0.1 × 10⁻⁵ = 10⁻⁶⁩\n   – ⁦T₀ = 2π × 10⁻³ ≈ 6.28 ms⁩\n   – ⁦f₀ = 1/T₀ ≈ 159 Hz⁩\n• تمرين 2: في نفس الدارة شُحنت المكثفة تحت ⁦6 V⁩ (مثالية). احسب الطاقة الكلية والتيار الأعظمي.\n• الحل:\n   – ⁦E = (1/2) × 10⁻⁵ × 36 = 1.8×10⁻⁴ J⁩\n   – ⁦Iₘ = √(2E/L) = √(3.6×10⁻⁴/0.1) = √(3.6×10⁻³) ≈ 0.06 A⁩\n• تمرين 3: لماذا تتخامد الاهتزازات في دارة RLC؟\n• الحل:\n   – لأن المقاومة تحول جزءا من الطاقة إلى حرارة بمفعول جول فتتناقص الطاقة الكلية والسعة\n▸ للحفظ\n• ⁦T₀ = 2π√(LC)⁩. الطاقة ⁦E = C u²/2 + L i²/2⁩. المقاومة تخمد."},{"title":"8. المتذبذبات الميكانيكية","content":"▸ النواس المرن\n• ⁦T₀ = 2π·√(m/k)⁩\n• ⁦k⁩ ثابت صلابة النابض\n• ⁦x = Xₘ·cos(2πt/T₀ + φ)⁩\n▸ النواس البسيط\n• ⁦T₀ = 2π·√(l/g)⁩\n• زوايا صغيرة\n• لا يتعلق بالكتلة\n▸ المعادلة التفاضلية\n• ⁦d²x/dt² + (k/m)x = 0⁩\n• حركة جيبية\n• ⁦ω₀ = √(k/m)⁩\n▸ الطاقة\n• ⁦E = (1/2)k·x² + (1/2)m·v²⁩\n• تنحفظ بدون احتكاك\n• ⁦E = (1/2)k·Xₘ²⁩\n▸ أخطاء شائعة\n• الخلط بين ⁦T₀⁩ و ⁦f₀⁩\n• استعمال الكتلة في النواس البسيط\n• ⁦l⁩ غير بالمتر\n▸ شرح مبسط\n• النابض يحاول إرجاع الكتلة إلى موضع التوازن فتتحرك ذهابا وإيابا. الدور يزداد بزيادة الكتلة (أثقل فأبطأ) وينقص بزيادة الصلابة (أقوى فأسرع). والنواس البسيط يتحكم فيه الطول والثقالة فقط.\n▸ طرق وقواعد\n• ⁦T₀⁩ بالثواني.\n• ⁦ω₀ = 2π/T₀⁩.\n• للتحقق: الطاقة الكلية ثابتة.\n▸ تمارين محلولة\n• تمرين 1: نابض ⁦k = 20 N/m⁩ وكتلة ⁦m = 0.2 kg⁩. احسب الدور الخاص.\n• الحل:\n   – ⁦T₀ = 2π√(0.2/20) = 2π × 0.1 ≈ 0.628 s⁩\n• تمرين 2: نواس بسيط طوله ⁦1 m⁩ (⁦g = 9.8⁩). احسب دوره.\n• الحل:\n   – ⁦T₀ = 2π√(1/9.8) = 2π × 0.3194 ≈ 2.01 s⁩\n• تمرين 3: ما طول نواس بسيط دوره ⁦1 s⁩؟\n• الحل:\n   – ⁦l = g·T₀²/4π² = 9.8/39.5 ≈ 0.248 m⁩\n▸ للحفظ\n• ⁦T₀ = 2π√(m/k)⁩ و ⁦T₀ = 2π√(l/g)⁩. الطاقة: ⁦k Xₘ²/2⁩."},{"title":"9. الأمواج الميكانيكية","content":"▸ تعريف الموجة\n• انتشار اضطراب دون انتقال المادة\n• مستعرضة أو طولية\n• تحتاج وسطا ماديا\n▸ العلاقات\n• ⁦v = λ/T = λ·f⁩\n• التأخر ⁦τ = d/v⁩\n• ⁦λ⁩ طول الموجة بالمتر\n▸ الوسط\n• السرعة تتعلق بالوسط\n• التردد يتعلق بالمنبع\n• ⁦λ⁩ تتغير بتغير الوسط\n▸ الانعراج\n• تغير الاتجاه عند فتحة أو حاجز\n• يظهر عندما ⁦a ≈ λ⁩\n• خاصية الأمواج\n▸ أخطاء شائعة\n• قول إن الموجة تنقل المادة\n• خلط ⁦T⁩ و ⁦f⁩\n• نسيان تحويل ⁦mm⁩ إلى ⁦m⁩\n▸ شرح مبسط\n• الموجة تشبه ما يحدث في ملعب عندما تقف الجماهير بالتتابع: الاضطراب هو الذي يسافر وليس الأشخاص. سرعة الموجة تتعلق بالوسط، وترددها بالمنبع، وطول موجتها يساوي المسافة المقطوعة في دور واحد.\n▸ طرق وقواعد\n• ⁦v = λ·f⁩.\n• التأخر بين نقطتين ⁦= d/v⁩.\n• التردد لا يتغير عند تغيير الوسط.\n▸ تمارين محلولة\n• تمرين 1: صوت في الهواء ⁦v = 340 m/s⁩ وتردده ⁦170 Hz⁩. احسب طول موجته.\n• الحل:\n   – ⁦λ = v/f = 340/170 = 2 m⁩\n• تمرين 2: موجة على حبل ⁦v = 5 m/s⁩ و ⁦f = 2 Hz⁩. احسب ⁦λ⁩ وتأخر نقطة تبعد ⁦10 m⁩.\n• الحل:\n   – ⁦λ = 5/2 = 2.5 m⁩\n   – ⁦τ = d/v = 10/5 = 2 s⁩\n• تمرين 3: سونار يستقبل الصدى بعد ⁦0.8 s⁩ في الماء (⁦v = 1500 m/s⁩). احسب العمق.\n• الحل:\n   – الذهاب والإياب: ⁦d = v·t/2 = 1500 × 0.8/2 = 600 m⁩\n▸ للحفظ\n• ⁦v = λ/T = λf⁩. ⁦τ = d/v⁩. التردد للمنبع والسرعة للوسط."},{"title":"10. الأمواج الضوئية والانعراج","content":"▸ الطبيعة الموجية\n• الضوء موجة كهرمغناطيسية\n• ⁦c = 3×10⁸ m/s⁩ في الفراغ\n• ⁦λ⁩ تتعلق بالوسط\n▸ الانعراج بشق\n• ⁦θ ≈ λ/a⁩ (بالراديان)\n• عرض البقعة المركزية ⁦L = 2λD/a⁩\n• ⁦a⁩ عرض الشق\n▸ قرينة الانكسار\n• ⁦n = c/v⁩\n• ⁦λ = λ₀/n⁩\n• التردد ثابت\n▸ التجربة\n• شق أو خيط رفيع\n• شاشة على بعد ⁦D⁩\n• بقعة مركزية وبقع جانبية\n▸ أخطاء شائعة\n• نسيان العامل 2 في عرض البقعة المركزية\n• وحدات ⁦nm⁩ و ⁦mm⁩\n• اعتبار التردد يتغير في الوسط\n▸ شرح مبسط\n• عندما يمر الضوء بفتحة ضيقة جدا يتوزع بدل أن يبقى حزمة رفيعة: هذا الانعراج، ودليل على طبيعته الموجية. كلما ضاق الشق اتسعت البقعة المركزية. وهذا يسمح بقياس طول الموجة.\n▸ طرق وقواعد\n• ⁦L = 2λD/a⁩.\n• حوّل كل الأطوال إلى المتر.\n• ⁦θ⁩ صغيرة: ⁦tan θ ≈ θ⁩.\n▸ تمارين محلولة\n• تمرين 1: شق عرضه ⁦a = 0.1 mm⁩ وضوء ⁦λ = 600 nm⁩ وشاشة على ⁦D = 2 m⁩. احسب ⁦θ⁩ وعرض البقعة المركزية.\n• الحل:\n   – ⁦θ = λ/a = 6×10⁻⁷/10⁻⁴ = 6×10⁻³ rad⁩\n   – ⁦L = 2λD/a = 2 × 6×10⁻⁷ × 2/10⁻⁴ = 0.024 m = 2.4 cm⁩\n• تمرين 2: أوجد عرض الشق الذي يعطي ⁦L = 1 cm⁩ مع ⁦λ = 633 nm⁩ و ⁦D = 3 m⁩.\n• الحل:\n   – ⁦a = 2λD/L = 2 × 633×10⁻⁹ × 3/0.01 ≈ 3.8×10⁻⁴ m = 0.38 mm⁩\n• تمرين 3: ما طول موجة ضوء ⁦λ₀ = 600 nm⁩ في زجاج ⁦n = 1.5⁩؟\n• الحل:\n   – ⁦λ = λ₀/n = 600/1.5 = 400 nm⁩\n▸ للحفظ\n• ⁦θ = λ/a⁩ و ⁦L = 2λD/a⁩. ⁦n = c/v⁩ و ⁦λ = λ₀/n⁩. التردد ثابت."},{"title":"11. التحولات النووية","content":"▸ النواة\n• رمز النواة ⁦X⁩ مع ⁦A⁩ عدد النويات و ⁦Z⁩ عدد البروتونات\n• ⁦A⁩ عدد النويات و ⁦Z⁩ عدد البروتونات\n• انحفاظ ⁦A⁩ و ⁦Z⁩\n▸ التفكك الإشعاعي\n• ⁦N = N₀·e^(-λt)⁩\n• ⁦t_(1/2) = ln 2/λ⁩\n• النشاط ⁦A = λ·N⁩\n▸ أنماط التفكك\n• ⁦α⁩: خروج ⁦⁴₂He⁩\n• ⁦β⁻⁩: خروج إلكترون\n• ⁦γ⁩: طاقة دون تغير ⁦A⁩ و ⁦Z⁩\n▸ الطاقة\n• ⁦E = Δm·c²⁩\n• ⁦1 u = 931.5 MeV/c²⁩\n• طاقة الربط لكل نوية\n▸ أخطاء شائعة\n• خلط ⁦λ⁩ مع ⁦t_(1/2)⁩\n• عدم موازنة ⁦A⁩ و ⁦Z⁩\n• نسيان وحدة ⁦u⁩\n▸ شرح مبسط\n• النواة غير المستقرة تتفكك عشوائيا لكن بنسبة ثابتة في الزمن: نصف العينة يتفكك كل نصف عمر. عندما تتحول نواة إلى أخرى تتغير الكتلة قليلا فتتحرر طاقة كبيرة وفق علاقة أينشتاين.\n▸ طرق وقواعد\n• وازن ⁦A⁩ ثم ⁦Z⁩.\n• بعد ⁦n⁩ أنصاف أعمار: ⁦N = N₀/2ⁿ⁩.\n• حوّل ⁦u⁩ إلى ⁦MeV⁩ بـ ⁦931.5⁩.\n▸ تمارين محلولة\n• تمرين 1: عينة نصف عمرها ⁦8⁩ أيام. ما نسبة المتبقي بعد ⁦24⁩ يوما؟ وما ⁦λ⁩؟\n• الحل:\n   – ⁦24/8 = 3⁩ أنصاف أعمار فـ ⁦N/N₀ = 1/2³ = 1/8⁩\n   – ⁦λ = ln 2/8 ≈ 0.0866 d⁻¹⁩\n• تمرين 2: اكتب معادلة تفكك ⁦α⁩ لليورانيوم ⁦²³⁸₉₂U⁩.\n• الحل:\n   – ⁦²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He⁩\n   – التحقق: ⁦238 = 234 + 4⁩ و ⁦92 = 90 + 2⁩\n• تمرين 3: تفاعل نقص كتلته ⁦Δm = 0.03 u⁩. احسب الطاقة المحررة.\n• الحل:\n   – ⁦E = 0.03 × 931.5 ≈ 27.9 MeV⁩\n▸ للحفظ\n• ⁦N = N₀ e^(-λt)⁩ و ⁦t_(1/2) = ln 2/λ⁩. ⁦E = Δm c²⁩. انحفاظ ⁦A⁩ و ⁦Z⁩."},{"title":"12. المتابعة الزمنية للتحول الكيميائي","content":"▸ التقدم x\n• جدول تقدم التفاعل\n• ⁦xₘₐₓ⁩ عند اختفاء المتفاعل المحد\n• يربط الكميات بالتقدم\n▸ سرعة التفاعل\n• ⁦v = (1/V)·dx/dt⁩\n• تتناقص مع الزمن عادة\n• ميل المماس لمنحنى ⁦x(t)⁩\n▸ زمن نصف التفاعل\n• ⁦x(t_(1/2)) = xₘₐₓ/2⁩\n• يقيس سرعة التفاعل\n• أصغر ⟵ أسرع\n▸ العوامل الحركية\n• درجة الحرارة\n• التراكيز\n• الحفاز\n▸ أخطاء شائعة\n• خلط ⁦x⁩ مع التركيز\n• نسيان ⁦V⁩ في السرعة\n• تحديد ⁦xₘₐₓ⁩ خطأ\n▸ شرح مبسط\n• التحول الكيميائي يتم بسرعة تتناقص مع استهلاك المتفاعلات. نتابع تقدمه ⁦x⁩ عبر الزمن بقياس مقدار يتغير (ضغط، موصلية، حجم غاز). السرعة هي ميل منحنى ⁦x(t)⁩ عند اللحظة المعنية.\n▸ طرق وقواعد\n• أنشئ جدول التقدم.\n• السرعة من ميل المماس.\n• ⁦t_(1/2)⁩ من ⁦xₘₐₓ/2⁩.\n▸ تمارين محلولة\n• تمرين 1: تركيز يتناقص من ⁦0.40⁩ إلى ⁦0.25 mol/L⁩ خلال ⁦100 s⁩. احسب السرعة المتوسطة للاختفاء.\n• الحل:\n   – ⁦v = 0.15/100 = 1.5×10⁻³ mol·L⁻¹·s⁻¹⁩\n• تمرين 2: تفكك ⁦0.02 mol⁩ من الماء الأكسجيني ⁦2H₂O₂ → 2H₂O + O₂⁩. أوجد ⁦xₘₐₓ⁩ وحجم ⁦O₂⁩ (⁦Vₘ = 24 L/mol⁩).\n• الحل:\n   – ⁦xₘₐₓ = 0.02/2 = 0.01 mol⁩\n   – ⁦V(O₂) = 0.01 × 24 = 0.24 L⁩\n• تمرين 3: كيف نعرف ⁦t_(1/2)⁩ من المنحنى؟\n• الحل:\n   – نحدد النقطة التي يبلغ فيها ⁦x⁩ نصف ⁦xₘₐₓ⁩ ونقرأ زمنها\n▸ للحفظ\n• ⁦v = (1/V)dx/dt⁩. ⁦t_(1/2)⁩: ⁦x = xₘₐₓ/2⁩. الحرارة والتركيز والحفاز تزيد السرعة."},{"title":"13. التوازن الكيميائي","content":"▸ حالة التوازن\n• جملة لا تتغير مكوناتها\n• تفاعلان متعاكسان بنفس السرعة\n• حالة ديناميكية\n▸ كسر التفاعل\n• ⁦Q_(r)⁩ يحسب بالتراكيز\n• عند التوازن ⁦Q_(r,éq) = K⁩\n• ⁦K⁩ تتعلق بدرجة الحرارة فقط\n▸ اتجاه التطور\n• ⁦Q_(r) < K⁩: اتجاه مباشر\n• ⁦Q_(r) > K⁩: اتجاه عكسي\n• ⁦Q_(r) = K⁩: توازن\n▸ نسبة التقدم\n• ⁦τ_(f) = x_(f)/xₘₐₓ⁩\n• ⁦τ_(f) < 1⁩ تفاعل غير تام\n• ⁦τ_(f) = 1⁩ تفاعل تام\n▸ أخطاء شائعة\n• إدخال الماء والمذيب في ⁦Q_(r)⁩\n• قول إن التفاعل توقف عند التوازن\n• خلط ⁦K⁩ مع ⁦Q_(r)⁩\n▸ شرح مبسط\n• التوازن ليس سكونا بل تعادل: التفاعل المباشر والعكسي يحدثان بنفس السرعة فلا نرى تغيرا. نقارن ⁦Q_(r)⁩ بـ ⁦K⁩ لنعرف أين تتجه الجملة، ونستعمل ⁦τ_(f)⁩ لنقيس مدى تقدم التفاعل.\n▸ طرق وقواعد\n• اكتب ⁦Q_(r)⁩ بالتراكيز ثم قارنه بـ ⁦K⁩.\n• ⁦x_(f)⁩ من ⁦K⁩ بحل معادلة.\n• ⁦τ_(f)⁩ من ⁦x_(f)/xₘₐₓ⁩.\n▸ تمارين محلولة\n• تمرين 1: تفاعل ⁦A + B ⇌ C + D⁩ عند ⁦K = 4⁩ وكميات ابتدائية ⁦1 mol⁩ من ⁦A⁩ و ⁦B⁩ فقط. أوجد ⁦x_(f)⁩ ونسبة التقدم.\n• الحل:\n   – ⁦K = x²/(1 - x)² = 4⁩ فـ ⁦x/(1 - x) = 2⁩ و ⁦x = 2/3 ≈ 0.667 mol⁩\n   – ⁦τ_(f) = 0.667/1 ≈ 0.667⁩\n• تمرين 2: ⁦Q_(r) = 0.5⁩ و ⁦K = 4⁩. في أي اتجاه تتطور الجملة؟\n• الحل:\n   – ⁦Q_(r) < K⁩ فالتطور في الاتجاه المباشر\n• تمرين 3: هل التوازن حالة سكون؟\n• الحل:\n   – لا، هو حالة ديناميكية: التفاعل المباشر والعكسي مستمران بنفس السرعة\n▸ للحفظ\n• ⁦Q_(r) < K⁩ مباشر. ⁦Q_(r) = K⁩ توازن. ⁦τ_(f) = x_(f)/xₘₐₓ⁩."},{"title":"14. تفاعلات حمض أساس وpH","content":"▸ pH\n• ⁦pH = -log[H₃O⁺]⁩\n• ⁦[H₃O⁺] = 10^(-pH)⁩\n• الجداء الشاردي ⁦Kₑ = 10⁻¹⁴⁩ عند ⁦25°C⁩\n▸ حمض قوي\n• ⁦pH = -log c⁩\n• تفاعله تام\n• مثال ⁦HCl⁩\n▸ حمض ضعيف\n• ⁦Kₐ = [A⁻][H₃O⁺]/[AH]⁩\n• ⁦pKₐ = -log Kₐ⁩\n• نسبة التقدم ⁦< 1⁩\n▸ العلاقة\n• ⁦pH = pKₐ + log([A⁻]/[AH])⁩\n• عند ⁦pH = pKₐ⁩ يتساوى التركيزان\n• مجال الغلبة\n▸ المعايرة\n• نقطة التكافؤ: ⁦cₐ·Vₐ = c_(b)·V_(E)⁩\n• تغير لون الكاشف\n• منحنى ⁦pH = f(V)⁩\n▸ شرح مبسط\n• pH مقياس الحموضة: كلما كان أصغر كان المحلول أكثر حمضية. الحمض القوي يتفكك كليا، أما الضعيف فجزئيا، ولذلك يحتاج ثابت حموضة ⁦Kₐ⁩ لوصفه. وفي المعايرة نبحث عن اللحظة التي يتعادل فيها الحمض مع الأساس.\n▸ طرق وقواعد\n• من ⁦pH⁩ إلى التركيز: ⁦10^(-pH)⁩.\n• ⁦Kₐ⁩ من التراكيز عند التوازن.\n• التكافؤ: ⁦nₐ = n_(b)⁩.\n▸ تمارين محلولة\n• تمرين 1: محلول ⁦HCl⁩ تركيزه ⁦0.01 mol/L⁩. احسب ⁦pH⁩.\n• الحل:\n   – حمض قوي: ⁦[H₃O⁺] = 0.01⁩ فـ ⁦pH = -log 10⁻² = 2⁩\n• تمرين 2: حمض ضعيف ⁦0.1 mol/L⁩ له ⁦pH = 2.9⁩. احسب ⁦τ_(f)⁩ و ⁦Kₐ⁩ و ⁦pKₐ⁩.\n• الحل:\n   – ⁦[H₃O⁺] = 10^(-2.9) ≈ 1.26×10⁻³⁩\n   – ⁦τ_(f) = 1.26×10⁻³/0.1 ≈ 1.26%⁩\n   – ⁦Kₐ = (1.26×10⁻³)²/(0.1 - 1.26×10⁻³) ≈ 1.6×10⁻⁵⁩\n   – ⁦pKₐ ≈ 4.8⁩\n• تمرين 3: عُوير ⁦20 mL⁩ حمض ⁦0.1 mol/L⁩ بأساس ⁦NaOH⁩ ⁦0.1 mol/L⁩. ما حجم التكافؤ؟\n• الحل:\n   – ⁦cₐ·Vₐ = c_(b)·V_(E)⁩ فـ ⁦V_(E) = 0.1 × 20/0.1 = 20 mL⁩\n▸ للحفظ\n• ⁦pH = -log[H₃O⁺]⁩. ⁦pH = pKₐ + log([A⁻]/[AH])⁩. تكافؤ: ⁦cₐ Vₐ = c_(b) V_(E)⁩."},{"title":"15. الأعمدة والتحليل الكهربائي","content":"▸ العمود\n• مصعد: أكسدة\n• مهبط: إرجاع\n• جسر ملحي لإغلاق الدارة\n▸ عمود دانيال\n• ⁦Zn → Zn²⁺ + 2e⁻⁩ (مصعد)\n• ⁦Cu²⁺ + 2e⁻ → Cu⁩ (مهبط)\n• ⁦E ≈ 1.10 V⁩\n▸ التحليل الكهربائي\n• تفاعل قسري بمولد\n• مصعد: أكسدة والمهبط إرجاع\n• عكس العمود\n▸ قانون فاراداي\n• ⁦Q = I·t⁩\n• ⁦n(e⁻) = Q/F⁩\n• ⁦F = 96500 C/mol⁩\n▸ أخطاء شائعة\n• الخلط بين المصعد والمهبط\n• نسيان عدد الإلكترونات\n• ⁦t⁩ بغير الثواني\n▸ شرح مبسط\n• في العمود التفاعل يحدث تلقائيا فيعطينا تيارا، وفي التحليل الكهربائي نفرض التفاعل بمولد. في الحالتين الأكسدة (خسارة إلكترونات) عند المصعد والإرجاع (كسب إلكترونات) عند المهبط. وقانون فاراداي يربط الشحنة بكمية المادة.\n▸ طرق وقواعد\n• المصعد = أكسدة، المهبط = إرجاع.\n• ⁦n(e⁻) = I·t/F⁩.\n• ثم اقسم على عدد الإلكترونات.\n▸ تمارين محلولة\n• تمرين 1: تيار ⁦2 A⁩ لمدة ⁦965 s⁩ في محلول ⁦Cu²⁺⁩. احسب كتلة النحاس المترسب (⁦M = 63.5 g/mol⁩).\n• الحل:\n   – ⁦Q = 2 × 965 = 1930 C⁩\n   – ⁦n(e⁻) = 1930/96500 = 0.02 mol⁩\n   – ⁦n(Cu) = 0.02/2 = 0.01 mol⁩\n   – ⁦m = 0.01 × 63.5 = 0.635 g⁩\n• تمرين 2: اكتب نصفي المعادلة لعمود دانيال وحدد المصعد.\n• الحل:\n   – المصعد (أكسدة): ⁦Zn → Zn²⁺ + 2e⁻⁩\n   – المهبط (إرجاع): ⁦Cu²⁺ + 2e⁻ → Cu⁩\n• تمرين 3: ما الفرق بين العمود والتحليل الكهربائي؟\n• الحل:\n   – العمود يحول طاقة كيميائية إلى كهربائية بتفاعل تلقائي\n   – التحليل يستعمل طاقة كهربائية لفرض تفاعل غير تلقائي\n▸ للحفظ\n• مصعد: أكسدة. مهبط: إرجاع. ⁦n(e⁻) = I·t/F⁩ مع ⁦F = 96500 C/mol⁩."},{"title":"16. الأسترة والإماهة","content":"▸ الأسترة\n• حمض + كحول ⇌ إستر + ماء\n• بطيئة\n• محدودة (عكوسة)\n▸ الإماهة\n• إستر + ماء ⇌ حمض + كحول\n• عكس الأسترة\n• نفس ⁦K⁩\n▸ المردود\n• كحول أولي: ⁦67%⁩ من خليط متساوي المولات\n• كحول ثانوي: ⁦60%⁩\n• كحول ثالثي: ⁦5%⁩\n▸ تحسين المردود\n• زيادة أحد المتفاعلين\n• نزع أحد النواتج\n• الحفاز يسرع ولا يغير المردود\n▸ أخطاء شائعة\n• اعتبار الأسترة تامة\n• نسيان الماء\n• قول إن الحفاز يرفع المردود\n▸ شرح مبسط\n• الأسترة تفاعل بطيء ومحدود: يتوقف عندما يتوازن مع الإماهة. لا نستطيع تغيير حالة التوازن بالحفاز بل بتغيير الكميات (زيادة متفاعل أو نزع ناتج). وهذا ما نفعله في الصناعة.\n▸ طرق وقواعد\n• اكتب ⁦K⁩ للتحول.\n• مردود خليط متساوي المولات: ⁦x = 2/3⁩ للكحول الأولي.\n• الحفاز يغير السرعة فقط.\n▸ تمارين محلولة\n• تمرين 1: خليط من ⁦1 mol⁩ حمض و ⁦1 mol⁩ إيثانول (مردود ⁦67%⁩). احسب كتلة الإستر (إيثانوات الإيثيل ⁦M = 88 g/mol⁩).\n• الحل:\n   – ⁦n_(est) = 0.67 mol⁩ (الإستر)\n   – ⁦m = 0.67 × 88 ≈ 59 g⁩\n• تمرين 2: خليط من ⁦1 mol⁩ حمض و ⁦2 mol⁩ كحول و ⁦K = 4⁩. احسب ⁦x_(f)⁩.\n• الحل:\n   – ⁦K = x²/((1 - x)(2 - x)) = 4⁩ فـ ⁦3x² - 12x + 8 = 0⁩ و ⁦x = (12 - √48)/6 ≈ 0.845 mol⁩\n   – المردود ⁦84.5%⁩: أفضل من الخليط المتساوي\n• تمرين 3: اذكر طريقتين لتحسين مردود الأسترة.\n• الحل:\n   – زيادة كمية أحد المتفاعلين (الكحول مثلا)، ونزع أحد النواتج (الماء أو الإستر) أثناء التفاعل\n▸ للحفظ\n• أسترة ⇌ إماهة. كحول أولي: مردود 67% (متساوي المولات). الحفاز لا يغير المردود."}],maps:'phy'});
  A.tm_physics=Object.assign({name:'العلوم الفيزيائية'},A.tm_physics||{},{lessons:[{"title":"1. قوانين نيوتن","content":"▸ القانون الأول (العطالة)\n• ⁦ΣF = 0⁩ فالجسم ساكن أو في حركة مستقيمة منتظمة\n• الحفاظ على الحالة الحركية\n• يُطبق في معلم غاليلي\n▸ القانون الثاني\n• ⁦ΣF = m·a⁩\n• التسارع في اتجاه محصلة القوى\n• ⁦m⁩ بالكيلوغرام و ⁦F⁩ بالنيوتن\n▸ القانون الثالث\n• الفعل ورد الفعل متساويان ومتعاكسان\n• ⁦F_(A/B) = -F_(B/A)⁩\n• يؤثران على جسمين مختلفين\n▸ منهج الحل\n• 1) حدد الجملة والمعلم\n• 2) مثّل القوى\n• 3) طبّق القانون الثاني وسقط على المحاور\n▸ أخطاء شائعة\n• خلط القوة بالسرعة\n• نسيان قوة أو إشارتها\n• اعتبار الفعل ورد الفعل على نفس الجسم\n▸ شرح مبسط\n• كل جسم يقاوم تغيير حركته (العطالة). إذا أردنا تغيير سرعته نحتاج قوة محصلة، وكلما كانت كتلته أكبر احتجنا قوة أكبر لنفس التسارع. والقوة لا تأتي وحدها: كل جسم يدفع جسما آخر يُدفع في المقابل.\n▸ طرق وقواعد\n• ارسم القوى قبل أي معادلة.\n• سقّط المعادلة الشعاعية على محورين.\n• تسارع ثابت يعني حركة متغيرة بانتظام.\n▸ تمارين محلولة\n• تمرين 1: جسم كتلته ⁦2 kg⁩ تؤثر عليه قوتان ⁦10 N⁩ و ⁦4 N⁩ متعاكستان على نفس الحامل. احسب تسارعه.\n• الحل:\n   – المحصلة ⁦10 - 4 = 6 N⁩\n   – ⁦a = ΣF/m = 6/2 = 3 m/s²⁩ في اتجاه القوة الأكبر\n• تمرين 2: جسم كتلته ⁦5 kg⁩ على مستو مائل أملس بزاوية ⁦30°⁩. احسب تسارعه (⁦g = 9.8⁩).\n• الحل:\n   – القوة المؤثرة على امتداد المستوي ⁦P·sin α = m·g·sin α⁩\n   – ⁦a = g·sin 30° = 9.8 × 0.5 = 4.9 m/s²⁩\n• تمرين 3: سيارة كتلتها ⁦1000 kg⁩ تنتقل من السكون إلى ⁦20 m/s⁩ خلال ⁦10 s⁩ بتسارع ثابت. احسب القوة المحصلة.\n• الحل:\n   – ⁦a = Δv/Δt = 20/10 = 2 m/s²⁩\n   – ⁦ΣF = m·a = 1000 × 2 = 2000 N⁩\n▸ للحفظ\n• ⁦ΣF = m·a⁩. إذا ⁦ΣF = 0⁩ فحركة مستقيمة منتظمة أو سكون. فعل = رد فعل في المقدار ومعاكس في الاتجاه."},{"title":"2. السقوط الشاقولي ودافعة أرخميدس","content":"▸ السقوط الحر\n• القوة الوحيدة الثقل ⁦P = m·g⁩\n• ⁦a = g⁩ ثابت\n• ⁦v = g·t⁩ و ⁦y = (1/2)·g·t²⁩\n▸ دافعة أرخميدس\n• ⁦Π = ρ_(fl)·V·g⁩\n• موجهة نحو الأعلى\n• ⁦V⁩ حجم الجزء المغمور\n▸ السقوط في مائع\n• الثقل ⁦P⁩ والدافعة ⁦Π⁩ والاحتكاك ⁦f = k·v⁩\n• المعادلة التفاضلية للسرعة\n• تبلغ السرعة قيمة حدية\n▸ السرعة الحدية\n• تنعدم المحصلة: ⁦P - Π - k·v_(lim) = 0⁩\n• ⁦v_(lim) = (P - Π)/k⁩\n• حركة مستقيمة منتظمة بعدها\n▸ أخطاء شائعة\n• إهمال الدافعة في الماء\n• خلط حجم الجسم والجزء المغمور\n• نسيان اتجاه الاحتكاك\n▸ شرح مبسط\n• عندما نترك جسما في الفراغ يسقط بتسارع ثابت g. في مائع نضيف قوتين: الدافعة تدفع للأعلى والاحتكاك يزيد مع السرعة. عندما تتوازن القوى تتوقف السرعة عن الازدياد وتصبح ثابتة: هي السرعة الحدية.\n▸ طرق وقواعد\n• ارسم الثقل والدافعة والاحتكاك.\n• للسرعة الحدية ضع ⁦a = 0⁩.\n• في السقوط الحر الكتلة لا تؤثر في الزمن.\n▸ تمارين محلولة\n• تمرين 1: حجر يُترك من ارتفاع ⁦20 m⁩ (⁦g = 9.8⁩). احسب زمن السقوط والسرعة عند الأرض.\n• الحل:\n   – ⁦h = (1/2)g·t²⁩ فـ ⁦t = √(2h/g) = √(40/9.8) ≈ 2.02 s⁩\n   – ⁦v = g·t ≈ 19.8 m/s⁩\n• تمرين 2: جسم حجمه ⁦2 L⁩ مغمور كليا في الماء (⁦ρ = 1000 kg/m³⁩). احسب دافعة أرخميدس.\n• الحل:\n   – ⁦V = 2×10⁻³ m³⁩\n   – ⁦Π = 1000 × 2×10⁻³ × 9.8 = 19.6 N⁩\n• تمرين 3: كرة ثقلها ⁦2 N⁩ ودافعتها ⁦0.5 N⁩ وثابت الاحتكاك ⁦k = 3 kg/s⁩. احسب السرعة الحدية.\n• الحل:\n   – ⁦v_(lim) = (P - Π)/k = (2 - 0.5)/3 = 0.5 m/s⁩\n▸ للحفظ\n• سقوط حر: ⁦a = g⁩. ⁦Π = ρ·V·g⁩. سرعة حدية: ⁦P - Π - k·v = 0⁩."},{"title":"3. حركة القذيفة","content":"▸ المعادلات الزمنية\n• ⁦x = (v₀·cos α)·t⁩\n• ⁦y = -(1/2)g·t² + (v₀·sin α)·t⁩\n• ⁦aₓ = 0⁩ و ⁦a_(y) = -g⁩\n▸ المسار\n• قطع مكافئ\n• ⁦y = -g·x²/(2v₀²cos²α) + x·tan α⁩\n• في مجال ثقالة منتظم\n▸ القمة والمدى\n• الارتفاع الأقصى ⁦h = v₀²sin²α/(2g)⁩\n• المدى ⁦R = v₀²sin 2α/g⁩\n• زمن الطيران ⁦t = 2v₀ sin α/g⁩\n▸ إطلاق أفقي\n• ⁦v_(y)(0) = 0⁩\n• ⁦t = √(2h/g)⁩\n• ⁦x = v₀·t⁩\n▸ أخطاء شائعة\n• خلط ⁦cos⁩ و ⁦sin⁩\n• نسيان الإشارة السالبة لـ ⁦g⁩\n• استعمال السرعة الابتدائية كاملة على المحورين\n▸ شرح مبسط\n• القذيفة تتحرك في اتجاهين مستقلين: أفقيا بسرعة ثابتة وشاقوليا بتسارع الثقالة. نفصل الحركتين ثم نجمعهما في معادلة المسار. أعلى نقطة تكون عندما تنعدم السرعة الشاقولية.\n▸ طرق وقواعد\n• حلّل ⁦v₀⁩ إلى مركبتين.\n• عند القمة ⁦v_(y) = 0⁩.\n• المدى أعظمي عند ⁦α = 45°⁩.\n▸ تمارين محلولة\n• تمرين 1: قذيفة سرعتها ⁦20 m/s⁩ بزاوية ⁦30°⁩ (⁦g = 9.8⁩). احسب المدى والارتفاع الأقصى وزمن الطيران.\n• الحل:\n   – ⁦R = 400 × sin 60°/9.8 = 400 × 0.866/9.8 ≈ 35.4 m⁩\n   – ⁦h = 400 × 0.25/19.6 ≈ 5.10 m⁩\n   – ⁦t = 2 × 20 × 0.5/9.8 ≈ 2.04 s⁩\n• تمرين 2: جسم يُقذف أفقيا بسرعة ⁦10 m/s⁩ من ارتفاع ⁦45 m⁩. أوجد زمن السقوط والمدى.\n• الحل:\n   – ⁦t = √(2 × 45/9.8) = √9.18 ≈ 3.03 s⁩\n   – ⁦x = v₀·t = 10 × 3.03 ≈ 30.3 m⁩\n• تمرين 3: ما الزاوية التي تعطي أكبر مدى؟ ولماذا؟\n• الحل:\n   – ⁦R = v₀²sin 2α/g⁩ أعظمية عندما ⁦sin 2α = 1⁩ أي ⁦α = 45°⁩\n▸ للحفظ\n• ⁦x = v₀ cos α·t⁩ و ⁦y = -g t²/2 + v₀ sin α·t⁩. ⁦R = v₀²sin 2α/g⁩. القمة: ⁦v_(y) = 0⁩."},{"title":"4. حركة الكواكب والأقمار الاصطناعية","content":"▸ قانون الجذب\n• ⁦F = G·m₁·m₂/r²⁩\n• ⁦G = 6.67×10⁻¹¹ SI⁩\n• قوة جاذبة متبادلة\n▸ حركة دائرية منتظمة\n• ⁦v = √(G·M/r)⁩\n• ⁦T = 2π·√(r³/(G·M))⁩\n• التسارع جاذبي مركزي\n▸ قوانين كبلر\n• مسار الكوكب إهليلجي\n• المساحات المكتسحة متساوية في أزمنة متساوية\n• ⁦T²/r³ = 4π²/(G·M)⁩\n▸ القمر الجيو مستقر\n• ⁦T = 24 h⁩ تقريبا\n• في المستوي الاستوائي\n• يظهر ثابتا في السماء\n▸ أخطاء شائعة\n• استعمال الارتفاع بدل ⁦r⁩\n• نسيان تحويل ⁦km⁩ إلى ⁦m⁩\n• الخلط بين كتلة القمر وكتلة الأرض\n▸ شرح مبسط\n• القمر الاصطناعي يسقط دائما نحو الأرض لكنه يتحرك أفقيا بسرعة كبيرة فيخطئ الأرض باستمرار فيدور حولها. البعد عن مركز الأرض هو ⁦r⁩ وليس الارتفاع فقط. كلما كان المدار أعلى كانت السرعة أقل والدور أكبر.\n▸ طرق وقواعد\n• ⁦r = R_(T) + h⁩.\n• السرعة لا تتعلق بكتلة القمر.\n• استعمل ⁦T²/r³⁩ ثابتا لمقارنة مدارين.\n▸ تمارين محلولة\n• تمرين 1: قمر على ارتفاع ⁦400 km⁩ (⁦M_(T) = 5.97×10²⁴ kg⁩، ⁦R_(T) = 6.37×10⁶ m⁩). احسب سرعته ودوره.\n• الحل:\n   – ⁦r = 6.77×10⁶ m⁩\n   – ⁦v = √(6.67×10⁻¹¹ × 5.97×10²⁴/6.77×10⁶) = √(5.88×10⁷) ≈ 7670 m/s⁩\n   – ⁦T = 2πr/v ≈ 5547 s ≈ 92.5 min⁩\n• تمرين 2: أوجد نصف قطر مدار قمر جيو مستقر (⁦T = 86164 s⁩).\n• الحل:\n   – ⁦r³ = G·M·T²/4π² = 3.98×10¹⁴ × 7.42×10⁹/39.5 ≈ 7.49×10²²⁩\n   – ⁦r ≈ 4.22×10⁷ m⁩\n   – الارتفاع ⁦r - R_(T) ≈ 3.58×10⁷ m⁩ أي ⁦35800 km⁩\n• تمرين 3: لماذا لا يسقط القمر الاصطناعي على الأرض؟\n• الحل:\n   – لأنه في سقوط حر مستمر نحو الأرض لكن بسرعة أفقية كبيرة فيدور حولها بدل أن يصطدم بها\n▸ للحفظ\n• ⁦v = √(GM/r)⁩ و ⁦T = 2π√(r³/GM)⁩. كبلر: ⁦T²/r³ = 4π²/GM⁩. ⁦r = R_(T) + h⁩."},{"title":"5. ثنائي القطب RC","content":"▸ الشحن\n• ⁦u_(C)(t) = E(1 - e^(-t/τ))⁩\n• ⁦i(t) = (E/R)·e^(-t/τ)⁩\n• التيار أعظمي عند البداية\n▸ التفريغ\n• ⁦u_(C)(t) = E·e^(-t/τ)⁩\n• ⁦i⁩ عكسية الإشارة\n• يتناقص أسيا\n▸ ثابت الزمن\n• ⁦τ = R·C⁩\n• عند ⁦t = τ⁩ تبلغ ⁦u_(C)⁩ نسبة ⁦63%⁩ من ⁦E⁩\n• عند ⁦t = 5τ⁩ يُعتبر الشحن تاما\n▸ الطاقة والشحنة\n• ⁦q = C·u_(C)⁩\n• ⁦E_(C) = (1/2)C·u_(C)²⁩\n• ⁦u_(C)⁩ متصلة دائما\n▸ أخطاء شائعة\n• خلط ⁦τ⁩ مع الزمن الكلي\n• نسيان وحدات ⁦μF⁩ و ⁦kΩ⁩\n• قول إن ⁦i⁩ متصلة عند التبديل\n▸ شرح مبسط\n• المكثفة كخزان ماء: تمتلئ بسرعة في البداية ثم ببطء. الزمن المميز ⁦τ = RC⁩ يحدد سرعة الامتلاء: مقاومة أكبر أو سعة أكبر تعني امتلاء أبطأ. التوتر بين طرفي المكثفة لا يقفز أبدا.\n▸ طرق وقواعد\n• ⁦τ⁩ بالثواني من ⁦R⁩ بالأوم و ⁦C⁩ بالفاراد.\n• عند ⁦t = τ⁩ الشحن ⁦63%⁩ والتفريغ يبقى ⁦37%⁩.\n• في النظام الدائم لا يمر تيار في فرع المكثفة.\n▸ تمارين محلولة\n• تمرين 1: ⁦R = 10 kΩ⁩ و ⁦C = 100 μF⁩. احسب ⁦τ⁩.\n• الحل:\n   – ⁦τ = R·C = 10⁴ × 10⁻⁴ = 1 s⁩\n• تمرين 2: شحن مكثفة بـ ⁦E = 12 V⁩ مع ⁦τ = 1 s⁩. احسب ⁦u_(C)⁩ عند ⁦t = τ⁩ والطاقة المخزنة النهائية (⁦C = 100 μF⁩).\n• الحل:\n   – ⁦u_(C)(τ) = 12 × (1 - e⁻¹) = 12 × 0.632 ≈ 7.58 V⁩\n   – ⁦E_(C) = (1/2) × 10⁻⁴ × 144 = 7.2×10⁻³ J⁩\n• تمرين 3: متى تبلغ ⁦u_(C) = 9 V⁩ علما أن ⁦E = 12 V⁩ و ⁦τ = 1 s⁩؟\n• الحل:\n   – ⁦9 = 12(1 - e^(-t/τ))⁩ فـ ⁦e^(-t/τ) = 0.25⁩\n   – ⁦t = τ·ln 4 ≈ 1.39 s⁩\n▸ للحفظ\n• شحن ⁦u_(C) = E(1 - e^(-t/τ))⁩. تفريغ ⁦u_(C) = E e^(-t/τ)⁩. ⁦τ = RC⁩. ⁦u_(C)⁩ متصلة."},{"title":"6. ثنائي القطب RL","content":"▸ إقامة التيار\n• ⁦i(t) = (E/R)(1 - e^(-t/τ))⁩\n• ⁦u_(L)(t) = E·e^(-t/τ)⁩\n• ⁦i⁩ متصلة دائما\n▸ ثابت الزمن\n• ⁦τ = L/R⁩\n• عند ⁦t = τ⁩ يبلغ ⁦i⁩ نسبة ⁦63%⁩ من قيمته النهائية\n• ⁦L⁩ بالهنري\n▸ القوة المحركة الذاتية\n• ⁦u_(L) = L·di/dt + r·i⁩\n• تعاكس تغير التيار\n• في النظام الدائم ⁦u_(L) = r·i⁩\n▸ الطاقة\n• ⁦E_(L) = (1/2)L·i²⁩\n• مخزنة في الحقل المغناطيسي\n• لا تتغير فجأة\n▸ أخطاء شائعة\n• خلط ⁦τ = L/R⁩ مع ⁦RC⁩\n• اعتبار التيار يقفز\n• إهمال المقاومة الداخلية للوشيعة\n▸ شرح مبسط\n• الوشيعة تقاوم تغير التيار: لا تسمح له بالارتفاع أو الانخفاض فجأة. لذلك يرتفع التيار تدريجيا نحو ⁦E/R⁩ بزمن مميز ⁦L/R⁩. وهي تخزن الطاقة في حقل مغناطيسي.\n▸ طرق وقواعد\n• ⁦τ = L/R⁩ ثانية.\n• النظام الدائم: ⁦i = E/R⁩ و ⁦u_(L) = 0⁩ (وشيعة مثالية).\n• التيار متصل والتوتر قد يقفز.\n▸ تمارين محلولة\n• تمرين 1: وشيعة ⁦L = 0.5 H⁩ ومقاومة ⁦R = 50 Ω⁩. احسب ⁦τ⁩.\n• الحل:\n   – ⁦τ = L/R = 0.5/50 = 0.01 s = 10 ms⁩\n• تمرين 2: في الدارة السابقة ⁦E = 10 V⁩. احسب التيار النهائي والطاقة المخزنة.\n• الحل:\n   – ⁦I = E/R = 10/50 = 0.2 A⁩\n   – ⁦E_(L) = (1/2) × 0.5 × 0.2² = 0.01 J⁩\n• تمرين 3: احسب التيار عند ⁦t = τ⁩.\n• الحل:\n   – ⁦i = 0.2 × (1 - e⁻¹) = 0.2 × 0.632 ≈ 0.126 A⁩\n▸ للحفظ\n• ⁦τ = L/R⁩. ⁦i = (E/R)(1 - e^(-t/τ))⁩. ⁦E_(L) = (1/2)L i²⁩. التيار متصل."},{"title":"7. الدارة RLC والاهتزازات الكهربائية","content":"▸ الدارة المثالية LC\n• اهتزازات جيبية دائمة\n• ⁦T₀ = 2π·√(L·C)⁩\n• ⁦f₀ = 1/T₀⁩\n▸ الدارة RLC\n• المقاومة تضيع الطاقة (جول)\n• اهتزازات متخامدة\n• أنظمة: دورية، لادورية، حرجة\n▸ الطاقة\n• ⁦E = (1/2)C·u_(C)² + (1/2)L·i²⁩\n• تنحفظ إذا ⁦R = 0⁩\n• تتناقص إذا ⁦R ≠ 0⁩\n▸ المعادلة التفاضلية\n• ⁦L·d²q/dt² + R·dq/dt + q/C = 0⁩\n• LC: ⁦d²q/dt² + q/(LC) = 0⁩\n• حلها ⁦q = Qₘ cos(2πt/T₀ + φ)⁩\n▸ أخطاء شائعة\n• الخلط بين ⁦T₀⁩ و ⁦τ⁩\n• نسيان الجذر التربيعي\n• اعتبار الطاقة منحفظة مع وجود ⁦R⁩\n▸ شرح مبسط\n• الدارة LC تشبه نابضا: الطاقة تنتقل بين المكثفة (طاقة كهربائية) والوشيعة (طاقة مغناطيسية) ذهابا وإيابا. إذا لم تكن هناك مقاومة لا تضيع الطاقة فتستمر الاهتزازات. المقاومة تحول الطاقة إلى حرارة فتخمد الاهتزازات.\n▸ طرق وقواعد\n• ⁦T₀ = 2π√(LC)⁩ بالثانية.\n• الطاقة الكلية تساوي الطاقة العظمى للمكثفة.\n• التخامد = ضياع بمفعول جول.\n▸ تمارين محلولة\n• تمرين 1: ⁦L = 0.1 H⁩ و ⁦C = 10 μF⁩. احسب ⁦T₀⁩ و ⁦f₀⁩.\n• الحل:\n   – ⁦LC = 0.1 × 10⁻⁵ = 10⁻⁶⁩\n   – ⁦T₀ = 2π × 10⁻³ ≈ 6.28 ms⁩\n   – ⁦f₀ = 1/T₀ ≈ 159 Hz⁩\n• تمرين 2: في نفس الدارة شُحنت المكثفة تحت ⁦6 V⁩ (مثالية). احسب الطاقة الكلية والتيار الأعظمي.\n• الحل:\n   – ⁦E = (1/2) × 10⁻⁵ × 36 = 1.8×10⁻⁴ J⁩\n   – ⁦Iₘ = √(2E/L) = √(3.6×10⁻⁴/0.1) = √(3.6×10⁻³) ≈ 0.06 A⁩\n• تمرين 3: لماذا تتخامد الاهتزازات في دارة RLC؟\n• الحل:\n   – لأن المقاومة تحول جزءا من الطاقة إلى حرارة بمفعول جول فتتناقص الطاقة الكلية والسعة\n▸ للحفظ\n• ⁦T₀ = 2π√(LC)⁩. الطاقة ⁦E = C u²/2 + L i²/2⁩. المقاومة تخمد."},{"title":"8. المتذبذبات الميكانيكية","content":"▸ النواس المرن\n• ⁦T₀ = 2π·√(m/k)⁩\n• ⁦k⁩ ثابت صلابة النابض\n• ⁦x = Xₘ·cos(2πt/T₀ + φ)⁩\n▸ النواس البسيط\n• ⁦T₀ = 2π·√(l/g)⁩\n• زوايا صغيرة\n• لا يتعلق بالكتلة\n▸ المعادلة التفاضلية\n• ⁦d²x/dt² + (k/m)x = 0⁩\n• حركة جيبية\n• ⁦ω₀ = √(k/m)⁩\n▸ الطاقة\n• ⁦E = (1/2)k·x² + (1/2)m·v²⁩\n• تنحفظ بدون احتكاك\n• ⁦E = (1/2)k·Xₘ²⁩\n▸ أخطاء شائعة\n• الخلط بين ⁦T₀⁩ و ⁦f₀⁩\n• استعمال الكتلة في النواس البسيط\n• ⁦l⁩ غير بالمتر\n▸ شرح مبسط\n• النابض يحاول إرجاع الكتلة إلى موضع التوازن فتتحرك ذهابا وإيابا. الدور يزداد بزيادة الكتلة (أثقل فأبطأ) وينقص بزيادة الصلابة (أقوى فأسرع). والنواس البسيط يتحكم فيه الطول والثقالة فقط.\n▸ طرق وقواعد\n• ⁦T₀⁩ بالثواني.\n• ⁦ω₀ = 2π/T₀⁩.\n• للتحقق: الطاقة الكلية ثابتة.\n▸ تمارين محلولة\n• تمرين 1: نابض ⁦k = 20 N/m⁩ وكتلة ⁦m = 0.2 kg⁩. احسب الدور الخاص.\n• الحل:\n   – ⁦T₀ = 2π√(0.2/20) = 2π × 0.1 ≈ 0.628 s⁩\n• تمرين 2: نواس بسيط طوله ⁦1 m⁩ (⁦g = 9.8⁩). احسب دوره.\n• الحل:\n   – ⁦T₀ = 2π√(1/9.8) = 2π × 0.3194 ≈ 2.01 s⁩\n• تمرين 3: ما طول نواس بسيط دوره ⁦1 s⁩؟\n• الحل:\n   – ⁦l = g·T₀²/4π² = 9.8/39.5 ≈ 0.248 m⁩\n▸ للحفظ\n• ⁦T₀ = 2π√(m/k)⁩ و ⁦T₀ = 2π√(l/g)⁩. الطاقة: ⁦k Xₘ²/2⁩."},{"title":"9. الأمواج الميكانيكية","content":"▸ تعريف الموجة\n• انتشار اضطراب دون انتقال المادة\n• مستعرضة أو طولية\n• تحتاج وسطا ماديا\n▸ العلاقات\n• ⁦v = λ/T = λ·f⁩\n• التأخر ⁦τ = d/v⁩\n• ⁦λ⁩ طول الموجة بالمتر\n▸ الوسط\n• السرعة تتعلق بالوسط\n• التردد يتعلق بالمنبع\n• ⁦λ⁩ تتغير بتغير الوسط\n▸ الانعراج\n• تغير الاتجاه عند فتحة أو حاجز\n• يظهر عندما ⁦a ≈ λ⁩\n• خاصية الأمواج\n▸ أخطاء شائعة\n• قول إن الموجة تنقل المادة\n• خلط ⁦T⁩ و ⁦f⁩\n• نسيان تحويل ⁦mm⁩ إلى ⁦m⁩\n▸ شرح مبسط\n• الموجة تشبه ما يحدث في ملعب عندما تقف الجماهير بالتتابع: الاضطراب هو الذي يسافر وليس الأشخاص. سرعة الموجة تتعلق بالوسط، وترددها بالمنبع، وطول موجتها يساوي المسافة المقطوعة في دور واحد.\n▸ طرق وقواعد\n• ⁦v = λ·f⁩.\n• التأخر بين نقطتين ⁦= d/v⁩.\n• التردد لا يتغير عند تغيير الوسط.\n▸ تمارين محلولة\n• تمرين 1: صوت في الهواء ⁦v = 340 m/s⁩ وتردده ⁦170 Hz⁩. احسب طول موجته.\n• الحل:\n   – ⁦λ = v/f = 340/170 = 2 m⁩\n• تمرين 2: موجة على حبل ⁦v = 5 m/s⁩ و ⁦f = 2 Hz⁩. احسب ⁦λ⁩ وتأخر نقطة تبعد ⁦10 m⁩.\n• الحل:\n   – ⁦λ = 5/2 = 2.5 m⁩\n   – ⁦τ = d/v = 10/5 = 2 s⁩\n• تمرين 3: سونار يستقبل الصدى بعد ⁦0.8 s⁩ في الماء (⁦v = 1500 m/s⁩). احسب العمق.\n• الحل:\n   – الذهاب والإياب: ⁦d = v·t/2 = 1500 × 0.8/2 = 600 m⁩\n▸ للحفظ\n• ⁦v = λ/T = λf⁩. ⁦τ = d/v⁩. التردد للمنبع والسرعة للوسط."},{"title":"10. الأمواج الضوئية والانعراج","content":"▸ الطبيعة الموجية\n• الضوء موجة كهرمغناطيسية\n• ⁦c = 3×10⁸ m/s⁩ في الفراغ\n• ⁦λ⁩ تتعلق بالوسط\n▸ الانعراج بشق\n• ⁦θ ≈ λ/a⁩ (بالراديان)\n• عرض البقعة المركزية ⁦L = 2λD/a⁩\n• ⁦a⁩ عرض الشق\n▸ قرينة الانكسار\n• ⁦n = c/v⁩\n• ⁦λ = λ₀/n⁩\n• التردد ثابت\n▸ التجربة\n• شق أو خيط رفيع\n• شاشة على بعد ⁦D⁩\n• بقعة مركزية وبقع جانبية\n▸ أخطاء شائعة\n• نسيان العامل 2 في عرض البقعة المركزية\n• وحدات ⁦nm⁩ و ⁦mm⁩\n• اعتبار التردد يتغير في الوسط\n▸ شرح مبسط\n• عندما يمر الضوء بفتحة ضيقة جدا يتوزع بدل أن يبقى حزمة رفيعة: هذا الانعراج، ودليل على طبيعته الموجية. كلما ضاق الشق اتسعت البقعة المركزية. وهذا يسمح بقياس طول الموجة.\n▸ طرق وقواعد\n• ⁦L = 2λD/a⁩.\n• حوّل كل الأطوال إلى المتر.\n• ⁦θ⁩ صغيرة: ⁦tan θ ≈ θ⁩.\n▸ تمارين محلولة\n• تمرين 1: شق عرضه ⁦a = 0.1 mm⁩ وضوء ⁦λ = 600 nm⁩ وشاشة على ⁦D = 2 m⁩. احسب ⁦θ⁩ وعرض البقعة المركزية.\n• الحل:\n   – ⁦θ = λ/a = 6×10⁻⁷/10⁻⁴ = 6×10⁻³ rad⁩\n   – ⁦L = 2λD/a = 2 × 6×10⁻⁷ × 2/10⁻⁴ = 0.024 m = 2.4 cm⁩\n• تمرين 2: أوجد عرض الشق الذي يعطي ⁦L = 1 cm⁩ مع ⁦λ = 633 nm⁩ و ⁦D = 3 m⁩.\n• الحل:\n   – ⁦a = 2λD/L = 2 × 633×10⁻⁹ × 3/0.01 ≈ 3.8×10⁻⁴ m = 0.38 mm⁩\n• تمرين 3: ما طول موجة ضوء ⁦λ₀ = 600 nm⁩ في زجاج ⁦n = 1.5⁩؟\n• الحل:\n   – ⁦λ = λ₀/n = 600/1.5 = 400 nm⁩\n▸ للحفظ\n• ⁦θ = λ/a⁩ و ⁦L = 2λD/a⁩. ⁦n = c/v⁩ و ⁦λ = λ₀/n⁩. التردد ثابت."},{"title":"11. التحولات النووية","content":"▸ النواة\n• رمز النواة ⁦X⁩ مع ⁦A⁩ عدد النويات و ⁦Z⁩ عدد البروتونات\n• ⁦A⁩ عدد النويات و ⁦Z⁩ عدد البروتونات\n• انحفاظ ⁦A⁩ و ⁦Z⁩\n▸ التفكك الإشعاعي\n• ⁦N = N₀·e^(-λt)⁩\n• ⁦t_(1/2) = ln 2/λ⁩\n• النشاط ⁦A = λ·N⁩\n▸ أنماط التفكك\n• ⁦α⁩: خروج ⁦⁴₂He⁩\n• ⁦β⁻⁩: خروج إلكترون\n• ⁦γ⁩: طاقة دون تغير ⁦A⁩ و ⁦Z⁩\n▸ الطاقة\n• ⁦E = Δm·c²⁩\n• ⁦1 u = 931.5 MeV/c²⁩\n• طاقة الربط لكل نوية\n▸ أخطاء شائعة\n• خلط ⁦λ⁩ مع ⁦t_(1/2)⁩\n• عدم موازنة ⁦A⁩ و ⁦Z⁩\n• نسيان وحدة ⁦u⁩\n▸ شرح مبسط\n• النواة غير المستقرة تتفكك عشوائيا لكن بنسبة ثابتة في الزمن: نصف العينة يتفكك كل نصف عمر. عندما تتحول نواة إلى أخرى تتغير الكتلة قليلا فتتحرر طاقة كبيرة وفق علاقة أينشتاين.\n▸ طرق وقواعد\n• وازن ⁦A⁩ ثم ⁦Z⁩.\n• بعد ⁦n⁩ أنصاف أعمار: ⁦N = N₀/2ⁿ⁩.\n• حوّل ⁦u⁩ إلى ⁦MeV⁩ بـ ⁦931.5⁩.\n▸ تمارين محلولة\n• تمرين 1: عينة نصف عمرها ⁦8⁩ أيام. ما نسبة المتبقي بعد ⁦24⁩ يوما؟ وما ⁦λ⁩؟\n• الحل:\n   – ⁦24/8 = 3⁩ أنصاف أعمار فـ ⁦N/N₀ = 1/2³ = 1/8⁩\n   – ⁦λ = ln 2/8 ≈ 0.0866 d⁻¹⁩\n• تمرين 2: اكتب معادلة تفكك ⁦α⁩ لليورانيوم ⁦²³⁸₉₂U⁩.\n• الحل:\n   – ⁦²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He⁩\n   – التحقق: ⁦238 = 234 + 4⁩ و ⁦92 = 90 + 2⁩\n• تمرين 3: تفاعل نقص كتلته ⁦Δm = 0.03 u⁩. احسب الطاقة المحررة.\n• الحل:\n   – ⁦E = 0.03 × 931.5 ≈ 27.9 MeV⁩\n▸ للحفظ\n• ⁦N = N₀ e^(-λt)⁩ و ⁦t_(1/2) = ln 2/λ⁩. ⁦E = Δm c²⁩. انحفاظ ⁦A⁩ و ⁦Z⁩."},{"title":"12. المتابعة الزمنية للتحول الكيميائي","content":"▸ التقدم x\n• جدول تقدم التفاعل\n• ⁦xₘₐₓ⁩ عند اختفاء المتفاعل المحد\n• يربط الكميات بالتقدم\n▸ سرعة التفاعل\n• ⁦v = (1/V)·dx/dt⁩\n• تتناقص مع الزمن عادة\n• ميل المماس لمنحنى ⁦x(t)⁩\n▸ زمن نصف التفاعل\n• ⁦x(t_(1/2)) = xₘₐₓ/2⁩\n• يقيس سرعة التفاعل\n• أصغر ⟵ أسرع\n▸ العوامل الحركية\n• درجة الحرارة\n• التراكيز\n• الحفاز\n▸ أخطاء شائعة\n• خلط ⁦x⁩ مع التركيز\n• نسيان ⁦V⁩ في السرعة\n• تحديد ⁦xₘₐₓ⁩ خطأ\n▸ شرح مبسط\n• التحول الكيميائي يتم بسرعة تتناقص مع استهلاك المتفاعلات. نتابع تقدمه ⁦x⁩ عبر الزمن بقياس مقدار يتغير (ضغط، موصلية، حجم غاز). السرعة هي ميل منحنى ⁦x(t)⁩ عند اللحظة المعنية.\n▸ طرق وقواعد\n• أنشئ جدول التقدم.\n• السرعة من ميل المماس.\n• ⁦t_(1/2)⁩ من ⁦xₘₐₓ/2⁩.\n▸ تمارين محلولة\n• تمرين 1: تركيز يتناقص من ⁦0.40⁩ إلى ⁦0.25 mol/L⁩ خلال ⁦100 s⁩. احسب السرعة المتوسطة للاختفاء.\n• الحل:\n   – ⁦v = 0.15/100 = 1.5×10⁻³ mol·L⁻¹·s⁻¹⁩\n• تمرين 2: تفكك ⁦0.02 mol⁩ من الماء الأكسجيني ⁦2H₂O₂ → 2H₂O + O₂⁩. أوجد ⁦xₘₐₓ⁩ وحجم ⁦O₂⁩ (⁦Vₘ = 24 L/mol⁩).\n• الحل:\n   – ⁦xₘₐₓ = 0.02/2 = 0.01 mol⁩\n   – ⁦V(O₂) = 0.01 × 24 = 0.24 L⁩\n• تمرين 3: كيف نعرف ⁦t_(1/2)⁩ من المنحنى؟\n• الحل:\n   – نحدد النقطة التي يبلغ فيها ⁦x⁩ نصف ⁦xₘₐₓ⁩ ونقرأ زمنها\n▸ للحفظ\n• ⁦v = (1/V)dx/dt⁩. ⁦t_(1/2)⁩: ⁦x = xₘₐₓ/2⁩. الحرارة والتركيز والحفاز تزيد السرعة."},{"title":"13. التوازن الكيميائي","content":"▸ حالة التوازن\n• جملة لا تتغير مكوناتها\n• تفاعلان متعاكسان بنفس السرعة\n• حالة ديناميكية\n▸ كسر التفاعل\n• ⁦Q_(r)⁩ يحسب بالتراكيز\n• عند التوازن ⁦Q_(r,éq) = K⁩\n• ⁦K⁩ تتعلق بدرجة الحرارة فقط\n▸ اتجاه التطور\n• ⁦Q_(r) < K⁩: اتجاه مباشر\n• ⁦Q_(r) > K⁩: اتجاه عكسي\n• ⁦Q_(r) = K⁩: توازن\n▸ نسبة التقدم\n• ⁦τ_(f) = x_(f)/xₘₐₓ⁩\n• ⁦τ_(f) < 1⁩ تفاعل غير تام\n• ⁦τ_(f) = 1⁩ تفاعل تام\n▸ أخطاء شائعة\n• إدخال الماء والمذيب في ⁦Q_(r)⁩\n• قول إن التفاعل توقف عند التوازن\n• خلط ⁦K⁩ مع ⁦Q_(r)⁩\n▸ شرح مبسط\n• التوازن ليس سكونا بل تعادل: التفاعل المباشر والعكسي يحدثان بنفس السرعة فلا نرى تغيرا. نقارن ⁦Q_(r)⁩ بـ ⁦K⁩ لنعرف أين تتجه الجملة، ونستعمل ⁦τ_(f)⁩ لنقيس مدى تقدم التفاعل.\n▸ طرق وقواعد\n• اكتب ⁦Q_(r)⁩ بالتراكيز ثم قارنه بـ ⁦K⁩.\n• ⁦x_(f)⁩ من ⁦K⁩ بحل معادلة.\n• ⁦τ_(f)⁩ من ⁦x_(f)/xₘₐₓ⁩.\n▸ تمارين محلولة\n• تمرين 1: تفاعل ⁦A + B ⇌ C + D⁩ عند ⁦K = 4⁩ وكميات ابتدائية ⁦1 mol⁩ من ⁦A⁩ و ⁦B⁩ فقط. أوجد ⁦x_(f)⁩ ونسبة التقدم.\n• الحل:\n   – ⁦K = x²/(1 - x)² = 4⁩ فـ ⁦x/(1 - x) = 2⁩ و ⁦x = 2/3 ≈ 0.667 mol⁩\n   – ⁦τ_(f) = 0.667/1 ≈ 0.667⁩\n• تمرين 2: ⁦Q_(r) = 0.5⁩ و ⁦K = 4⁩. في أي اتجاه تتطور الجملة؟\n• الحل:\n   – ⁦Q_(r) < K⁩ فالتطور في الاتجاه المباشر\n• تمرين 3: هل التوازن حالة سكون؟\n• الحل:\n   – لا، هو حالة ديناميكية: التفاعل المباشر والعكسي مستمران بنفس السرعة\n▸ للحفظ\n• ⁦Q_(r) < K⁩ مباشر. ⁦Q_(r) = K⁩ توازن. ⁦τ_(f) = x_(f)/xₘₐₓ⁩."},{"title":"14. تفاعلات حمض أساس وpH","content":"▸ pH\n• ⁦pH = -log[H₃O⁺]⁩\n• ⁦[H₃O⁺] = 10^(-pH)⁩\n• الجداء الشاردي ⁦Kₑ = 10⁻¹⁴⁩ عند ⁦25°C⁩\n▸ حمض قوي\n• ⁦pH = -log c⁩\n• تفاعله تام\n• مثال ⁦HCl⁩\n▸ حمض ضعيف\n• ⁦Kₐ = [A⁻][H₃O⁺]/[AH]⁩\n• ⁦pKₐ = -log Kₐ⁩\n• نسبة التقدم ⁦< 1⁩\n▸ العلاقة\n• ⁦pH = pKₐ + log([A⁻]/[AH])⁩\n• عند ⁦pH = pKₐ⁩ يتساوى التركيزان\n• مجال الغلبة\n▸ المعايرة\n• نقطة التكافؤ: ⁦cₐ·Vₐ = c_(b)·V_(E)⁩\n• تغير لون الكاشف\n• منحنى ⁦pH = f(V)⁩\n▸ شرح مبسط\n• pH مقياس الحموضة: كلما كان أصغر كان المحلول أكثر حمضية. الحمض القوي يتفكك كليا، أما الضعيف فجزئيا، ولذلك يحتاج ثابت حموضة ⁦Kₐ⁩ لوصفه. وفي المعايرة نبحث عن اللحظة التي يتعادل فيها الحمض مع الأساس.\n▸ طرق وقواعد\n• من ⁦pH⁩ إلى التركيز: ⁦10^(-pH)⁩.\n• ⁦Kₐ⁩ من التراكيز عند التوازن.\n• التكافؤ: ⁦nₐ = n_(b)⁩.\n▸ تمارين محلولة\n• تمرين 1: محلول ⁦HCl⁩ تركيزه ⁦0.01 mol/L⁩. احسب ⁦pH⁩.\n• الحل:\n   – حمض قوي: ⁦[H₃O⁺] = 0.01⁩ فـ ⁦pH = -log 10⁻² = 2⁩\n• تمرين 2: حمض ضعيف ⁦0.1 mol/L⁩ له ⁦pH = 2.9⁩. احسب ⁦τ_(f)⁩ و ⁦Kₐ⁩ و ⁦pKₐ⁩.\n• الحل:\n   – ⁦[H₃O⁺] = 10^(-2.9) ≈ 1.26×10⁻³⁩\n   – ⁦τ_(f) = 1.26×10⁻³/0.1 ≈ 1.26%⁩\n   – ⁦Kₐ = (1.26×10⁻³)²/(0.1 - 1.26×10⁻³) ≈ 1.6×10⁻⁵⁩\n   – ⁦pKₐ ≈ 4.8⁩\n• تمرين 3: عُوير ⁦20 mL⁩ حمض ⁦0.1 mol/L⁩ بأساس ⁦NaOH⁩ ⁦0.1 mol/L⁩. ما حجم التكافؤ؟\n• الحل:\n   – ⁦cₐ·Vₐ = c_(b)·V_(E)⁩ فـ ⁦V_(E) = 0.1 × 20/0.1 = 20 mL⁩\n▸ للحفظ\n• ⁦pH = -log[H₃O⁺]⁩. ⁦pH = pKₐ + log([A⁻]/[AH])⁩. تكافؤ: ⁦cₐ Vₐ = c_(b) V_(E)⁩."},{"title":"15. الأعمدة والتحليل الكهربائي","content":"▸ العمود\n• مصعد: أكسدة\n• مهبط: إرجاع\n• جسر ملحي لإغلاق الدارة\n▸ عمود دانيال\n• ⁦Zn → Zn²⁺ + 2e⁻⁩ (مصعد)\n• ⁦Cu²⁺ + 2e⁻ → Cu⁩ (مهبط)\n• ⁦E ≈ 1.10 V⁩\n▸ التحليل الكهربائي\n• تفاعل قسري بمولد\n• مصعد: أكسدة والمهبط إرجاع\n• عكس العمود\n▸ قانون فاراداي\n• ⁦Q = I·t⁩\n• ⁦n(e⁻) = Q/F⁩\n• ⁦F = 96500 C/mol⁩\n▸ أخطاء شائعة\n• الخلط بين المصعد والمهبط\n• نسيان عدد الإلكترونات\n• ⁦t⁩ بغير الثواني\n▸ شرح مبسط\n• في العمود التفاعل يحدث تلقائيا فيعطينا تيارا، وفي التحليل الكهربائي نفرض التفاعل بمولد. في الحالتين الأكسدة (خسارة إلكترونات) عند المصعد والإرجاع (كسب إلكترونات) عند المهبط. وقانون فاراداي يربط الشحنة بكمية المادة.\n▸ طرق وقواعد\n• المصعد = أكسدة، المهبط = إرجاع.\n• ⁦n(e⁻) = I·t/F⁩.\n• ثم اقسم على عدد الإلكترونات.\n▸ تمارين محلولة\n• تمرين 1: تيار ⁦2 A⁩ لمدة ⁦965 s⁩ في محلول ⁦Cu²⁺⁩. احسب كتلة النحاس المترسب (⁦M = 63.5 g/mol⁩).\n• الحل:\n   – ⁦Q = 2 × 965 = 1930 C⁩\n   – ⁦n(e⁻) = 1930/96500 = 0.02 mol⁩\n   – ⁦n(Cu) = 0.02/2 = 0.01 mol⁩\n   – ⁦m = 0.01 × 63.5 = 0.635 g⁩\n• تمرين 2: اكتب نصفي المعادلة لعمود دانيال وحدد المصعد.\n• الحل:\n   – المصعد (أكسدة): ⁦Zn → Zn²⁺ + 2e⁻⁩\n   – المهبط (إرجاع): ⁦Cu²⁺ + 2e⁻ → Cu⁩\n• تمرين 3: ما الفرق بين العمود والتحليل الكهربائي؟\n• الحل:\n   – العمود يحول طاقة كيميائية إلى كهربائية بتفاعل تلقائي\n   – التحليل يستعمل طاقة كهربائية لفرض تفاعل غير تلقائي\n▸ للحفظ\n• مصعد: أكسدة. مهبط: إرجاع. ⁦n(e⁻) = I·t/F⁩ مع ⁦F = 96500 C/mol⁩."},{"title":"16. الأسترة والإماهة","content":"▸ الأسترة\n• حمض + كحول ⇌ إستر + ماء\n• بطيئة\n• محدودة (عكوسة)\n▸ الإماهة\n• إستر + ماء ⇌ حمض + كحول\n• عكس الأسترة\n• نفس ⁦K⁩\n▸ المردود\n• كحول أولي: ⁦67%⁩ من خليط متساوي المولات\n• كحول ثانوي: ⁦60%⁩\n• كحول ثالثي: ⁦5%⁩\n▸ تحسين المردود\n• زيادة أحد المتفاعلين\n• نزع أحد النواتج\n• الحفاز يسرع ولا يغير المردود\n▸ أخطاء شائعة\n• اعتبار الأسترة تامة\n• نسيان الماء\n• قول إن الحفاز يرفع المردود\n▸ شرح مبسط\n• الأسترة تفاعل بطيء ومحدود: يتوقف عندما يتوازن مع الإماهة. لا نستطيع تغيير حالة التوازن بالحفاز بل بتغيير الكميات (زيادة متفاعل أو نزع ناتج). وهذا ما نفعله في الصناعة.\n▸ طرق وقواعد\n• اكتب ⁦K⁩ للتحول.\n• مردود خليط متساوي المولات: ⁦x = 2/3⁩ للكحول الأولي.\n• الحفاز يغير السرعة فقط.\n▸ تمارين محلولة\n• تمرين 1: خليط من ⁦1 mol⁩ حمض و ⁦1 mol⁩ إيثانول (مردود ⁦67%⁩). احسب كتلة الإستر (إيثانوات الإيثيل ⁦M = 88 g/mol⁩).\n• الحل:\n   – ⁦n_(est) = 0.67 mol⁩ (الإستر)\n   – ⁦m = 0.67 × 88 ≈ 59 g⁩\n• تمرين 2: خليط من ⁦1 mol⁩ حمض و ⁦2 mol⁩ كحول و ⁦K = 4⁩. احسب ⁦x_(f)⁩.\n• الحل:\n   – ⁦K = x²/((1 - x)(2 - x)) = 4⁩ فـ ⁦3x² - 12x + 8 = 0⁩ و ⁦x = (12 - √48)/6 ≈ 0.845 mol⁩\n   – المردود ⁦84.5%⁩: أفضل من الخليط المتساوي\n• تمرين 3: اذكر طريقتين لتحسين مردود الأسترة.\n• الحل:\n   – زيادة كمية أحد المتفاعلين (الكحول مثلا)، ونزع أحد النواتج (الماء أو الإستر) أثناء التفاعل\n▸ للحفظ\n• أسترة ⇌ إماهة. كحول أولي: مردود 67% (متساوي المولات). الحفاز لا يغير المردود."}],maps:'phy'});
  function reg(o,tag,data){var nk=o.key+'_'+tag;o.key=nk;A[nk]=Object.assign({},A[nk]||{},data);}
  function runReg(){try{(function w(o,d,ctx){if(!o||typeof o!=='object'||d>12)return;
   if(Array.isArray(o.subjects)&&typeof o.name==='string'&&/ثالثة/.test(ctx)&&/ثانوي/.test(ctx)&&/آداب|ادب|لغات/.test(o.name)&&!/علوم|تقني|تسيير|اقتصاد/.test(o.name)){
     var hasM=o.subjects.some(function(x){return x&&/رياضيات/.test(x.name||'')});
     if(!hasM){o.subjects.push({key:'maths',name:'الرياضيات',icon:'➕',links:[{label:'دروس وتمارين وفروض — eddirasa',url:'https://eddirasa.com/ens-sec/3as/maths/',icon:'📘',verified:false}]});}
   }
   if(o.key&&typeof o.name==='string'&&/ثالثة/.test(ctx)&&/ثانوي/.test(ctx)){
     var lit=/آداب|ادب|لغات|لغة/.test(ctx), sci=/علوم|رياض|تقني|هندس|تجريب|تسيير|اقتصاد|إدارة/.test(ctx);
     if(o.name.indexOf('فلسف')>-1){ if(lit)reg(o,'lit',pLit); else if(sci)reg(o,'sci',pSci); }
     else if(/اللغة العربية|^العربية/.test(o.name)){ if(lit)reg(o,'lit',pAr); else if(sci)reg(o,'sci',pArS); }
     else if(/رياضيات/.test(o.name)&&lit&&!/علوم|تقني|هندس|تجريب|تسيير|اقتصاد/.test(ctx)){reg(o,'lit',pMath);}
     else if(/رياضيات/.test(o.name)&&(/(^|\s)رياضيات(\s|$)/.test(ctx)||/تقني رياضي/.test(ctx))){reg(o,/تقني رياضي/.test(ctx)?'tm':'mth',pMM);}
   }
   for(var k in o){if(o[k]&&typeof o[k]==='object')w(o[k],d+1,ctx+' '+(typeof o.name==='string'?o.name:''))}})(typeof DB!=='undefined'&&DB.secondary,0,'')}catch(e){}}
  if(typeof DB!=='undefined')runReg();else{document.addEventListener('DOMContentLoaded',runReg);window.addEventListener('load',function(){if(!window.__zadReg)runReg()});}
  window.__zadReg=1;
})();
