R:[[PQ,['هل يجب أن تخضع السياسة للأخلاق؟ أم أن للسياسة منطقها الخاص القائم على المصلحة؟']],['الموقف الفاصل (الواقعي)',['السياسة ميدان القوة والمصلحة','ميكيافيلي: الحاكم يوازن بين الأخلاق ونجاح الدولة','الأخلاق للأفراد لا للدول']],['الموقف الرابط',['السياسة لا تقوم بدون عدالة وشرعية','أفلاطون: الحاكم الفيلسوف الفاضل','كانط: السلام الدائم']]],
L:[['التركيب',['أخلاق المسؤولية (فيبر)','السياسة وسيلة لتحقيق الخير العام','رقابة الشعب والقانون']],[NQ,[c1('فصل السياسة عن الأخلاق يبرر الظلم ويفقد الحكم شرعيته'),c2('المثالية المحضة قد تهمل ضرورات الواقع والمصلحة العامة')]],[NT,['السياسة','الأخلاق','المصلحة','الشرعية','العدالة']]],
E:['هل السياسة منفصلة عن الأخلاق؟','هل يجب أن تخضع السياسة للأخلاق؟','دافع عن أطروحة ارتباط السياسة بالأخلاق'],
K:'السياسة تحتاج الأخلاق لتكون عادلة وشرعية، والأخلاق تحتاج السياسة لتتجسد في الواقع.',
X:'يقول الواقعيون إن الحاكم الذي يتقيد بالفضائل المطلقة قد يفشل في حماية دولته، لذلك يقدمون المصلحة والفعالية، وهو ما يعرف في الفكر الميكيافيلي. أما المثاليون فيرون أن الحكم بلا أخلاق يتحول إلى استبداد ويفقد شرعيته. ويرى ماكس فيبر أن السياسي يحتاج إلى «أخلاق المسؤولية» أي إلى تحمل نتائج قراراته. والصواب أن السياسة لا تنفصل عن الأخلاق، لأن الغاية من الدولة تحقيق العدل والأمن والخير العام.',
P:['أفلاطون في «الجمهورية» يرى أن يحكم الفلاسفة لأنهم أعرف بالخير.','ميكيافيلي في «الأمير» يشرح كيف يحافظ الحاكم على سلطته ولو خالف الفضائل أحيانًا.','كانط في «مشروع السلام الدائم» يرى أن السلام غاية أخلاقية للسياسة.']},
{s:3,i:'🎲',t:'الحتمية واللاحتمية',q:'هل مبدأ الحتمية مطلق في العلوم؟',
R:[[PQ,['هل تخضع الظواهر لقوانين صارمة ثابتة (حتمية) أم يسودها الاحتمال واللايقين؟']],['مفهوم الحتمية',['كل ظاهرة لها سبب، وبنفس الأسباب نفس النتائج','لابلاس: العالم قابل للتنبؤ الكامل','كلود برنار: حتمية الظواهر الحية والجامدة']],['اللاحتمية',['هايزنبرغ: مبدأ اللايقين في الفيزياء الذرية','ميكانيكا الكم: قوانين احتمالية','حرية الإنسان تتعارض مع الحتمية الصارمة']]],
L:[['التركيب',['الحتمية قائمة في الفيزياء الكلاسيكية','الاحتمال في الميكروفيزياء','الحتمية النسبية لا تلغي العلم']],[NQ,[c1('عجزت أمام اللايقين في فيزياء الذرة وتتعارض مع الحرية'),c2('اللايقين لا يعني غياب القوانين فالاحتمال قانون دقيق')]],[NT,['الحتمية','السببية','الاحتمال','اللايقين','القانون العلمي']]],
E:['هل مبدأ الحتمية مطلق في العلوم؟','هل تتعارض الحتمية مع حرية الإنسان؟','دافع عن مبدأ الحتمية'],
K:'الحتمية مبدأ العلم الكلاسيكي، والاحتمال سمة الفيزياء الذرية، والموقف: حتمية نسبية.',
X:'قامت العلوم الكلاسيكية على أن لكل ظاهرة سببًا ثابتًا، حتى تخيّل لابلاس عقلًا يعرف حالة الكون الآن فيتنبأ بكل ما سيحدث. وجاءت فيزياء الذرة فبينت أن قياس موضع الجسيم وسرعته معًا لا يمكن أن يكون دقيقًا، كما في مبدأ اللايقين لهايزنبرغ، فصارت القوانين احتمالية. ومع ذلك لم يلغِ ذلك العلم، فهو في الظواهر الكبرى ما زال يعتمد على قوانين دقيقة. وفي ميدان الإنسان يفرق الفلاسفة بين الحتمية الطبيعية وحرية الإرادة التي تقتضي إمكان الاختيار.',
P:['لابلاس: عقل يعرف كل القوى والحالات يستطيع التنبؤ بالمستقبل كالماضي.','هايزنبرغ: لا يمكن تحديد موضع الإلكترون وسرعته بدقة في آنٍ واحد.','كلود برنار: الحتمية شرط العلم.']},
{s:5,i:'✍️',t:'منهجية المقالة الفلسفية وتحليل النص',q:'',
R:[['المقالة الجدلية',['مقدمة: تمهيد، مشكلة، سؤال','عرض الأطروحة الأولى بحججها وأمثلتها ثم نقدها','عرض الأطروحة المقابلة ثم نقدها','التركيب (الحل المتجاوز)','خاتمة: حل المشكلة والموقف الشخصي']],['مقالة المقارنة',['مقدمة تحدد المفهومين','أوجه الشبه','أوجه الاختلاف','العلاقة والتقييم','خاتمة']],['الاستقصاء بالوضع',['مقدمة وطرح المشكلة','عرض الأطروحة المراد الدفاع عنها','الحجج والبراهين والأمثلة','الرد على الشبهات والاعتراضات','خاتمة']]],
L:[['الاستقصاء بالرفع',['مقدمة','عرض الأطروحة المراد نقضها','إبطال حججها وبيان تناقضها','عرض البديل','خاتمة']],['تحليل النص',['المقدمة: صاحب النص وموضوعه','المشكلة والأطروحة','الحجج والمفاهيم الأساسية','المناقشة (التقييم)','الخاتمة']]],
E:[],
K:'المقالة = مقدمة ثم عرض (أطروحتان وتركيب) ثم خاتمة، مع الاستعانة بأقوال الفلاسفة وأمثلتهم.',
X:'ابدأ دائمًا بفهم السؤال وتحديد مفاهيمه وحصر المشكلة الفلسفية قبل الكتابة، ثم ضع خطة واضحة من مقدمة وعرض وخاتمة. اعتمد في كل فقرة على فكرة واحدة مدعومة بالحجة والمثال والمرجع الفلسفي (اسم الفيلسوف وفكرته). تجنب سرد الدرس كما هو، بل اربط المعلومات بسؤال المقالة. وفي الجدلية يجب أن يكون التركيب إضافة جديدة لا تلخيصًا. وفي النص ابدأ بفهم فكرته المحورية قبل التعليق. وتأكد من توزيع الوقت واحترام الترقيم وجودة الأسلوب.',
P:['نموذج مقدمة جدلية: تمهيد عام عن الموضوع، ثم ظهور التعارض (فمن جهة يرى البعض... ومن جهة أخرى...)، ثم صياغة المشكلة في سؤال: هل... أم...؟']}
];
