MM.push({s:2,i:'↩️',t:'الدوال الأصلية',
B:[['التعريف',['F دالة أصلية لـ f على مجال I إذا `F′ = f`','لكل دالة مستمرة دوال أصلية','دالتان أصليتان تختلفان بثابت: `F + C`']],
['جدول الدوال الأصلية',['`x^n → x^{n+1}/(n+1)` و `1/x → ln|x|`','`e^{ax} → e^{ax}/a` و `sin → -cos` و `cos → sin`','`u′·e^u → e^u` و `u′/u → ln|u|` و `u′·u^n → u^{n+1}/(n+1)`']],
['الشرط الابتدائي',['الدالة الأصلية التي تحقق `F(a) = b` وحيدة','نكتب `F + C` ثم نعين C']],
['كيف نبرهن؟',['أن F أصلية لـ f: نشتق F ونجد f','نتعرف على الشكل `u′·g(u)`']],
['أخطاء شائعة',['نسيان الثابت C','الخلط بين `x^n` و `(ax+b)^n`','نسيان القسمة على المعامل a']]],
X:'إيجاد الدالة الأصلية هو عكس الاشتقاق: لدينا السرعة ونريد المسافة. نتعرف على الشكل: إذا رأيت جداء دالة في مشتق دالة أخرى (مثل `x·e^{x^2}`) فهو غالبا من الشكل `u′e^u`.',
M:['اشتق الجواب للتأكد.','جرّب أن تتعرف على `u′` داخل العبارة.','للشرط الابتدائي استعمل `F(a) = b`.'],
EX:[['أوجد الدالة الأصلية لـ `f(x) = 2x + 1` التي تأخذ القيمة 3 عند 0.','`F(x) = x^2 + x + C`. `F(0) = C = 3` فـ `F(x) = x^2 + x + 3`.'],['أوجد دالة أصلية لـ `f(x) = x·e^{x^2}`.','`f(x) = (1/2)·(2x)·e^{x^2}` من الشكل `(1/2)u′e^u` فـ `F(x) = (1/2)e^{x^2}`.'],['أوجد دالة أصلية لـ `f(x) = 2x/(x^2 + 1)`.','من الشكل `u′/u` فـ `F(x) = ln(x^2 + 1)`.'],['بيّن أن `F(x) = x·ln x - x` دالة أصلية لـ `ln x` على `]0 ; +∞[`.','`F′(x) = ln x + x·(1/x) - 1 = ln x`. إذن F دالة أصلية.']],
K:'F أصلية لـ f ⇔ F′ = f. لا تنس + C. تعرف على u′·g(u).'});
MM.push({s:2,i:'∫',t:'التكامل وخواصه والتكامل بالتجزئة',
B:[['التعريف',['`∫_{a}^{b} f(x)dx = F(b) - F(a)`','F أي دالة أصلية لـ f','يرمز `[F(x)]_{a}^{b}` للفرق']],
['الخواص',['خطي: `∫(αf + βg) = α∫f + β∫g`','شال: `∫_{a}^{b} + ∫_{b}^{c} = ∫_{a}^{c}`','`∫_{a}^{a} f = 0` و `∫_{b}^{a} f = -∫_{a}^{b} f`']],
['الترتيب',['`f ≥ 0` على `[a;b]` ⇒ `∫f ≥ 0`','`f ≤ g` ⇒ `∫f ≤ ∫g`','`|∫f| ≤ ∫|f|`']],
['التكامل بالتجزئة',['`∫_{a}^{b} u·v′ = [u·v]_{a}^{b} - ∫_{a}^{b} u′·v`','نستعملها عند جداء كثير حدود في `e^x` أو `sin` أو `cos` أو عند `ln`']],
['كيف نختار u و v′؟',['كثير الحدود هو `u` (يبسط بالاشتقاق)','عند ln: `u = ln x` و `v′ = 1`']]],
X:'التكامل المحدد يعطي عددا يمثل مساحة (موجبة إذا كانت الدالة فوق المحور). نحسبه بالدالة الأصلية: القيمة عند الطرف الأعلى ناقص القيمة عند الأدنى. والتجزئة تحول تكاملا صعبا إلى آخر أبسط.',
M:['احسب الدالة الأصلية ثم عوّض الحدين.','عند التجزئة اكتب `u` و `v` و `u′` و `v′` في سطر.','احسب التكامل الجديد بعد التجزئة.'],
