K:'∫f = F(b) − F(a). التجزئة: ∫uv′ = [uv] − ∫u′v.'});
MM.push({s:2,i:'📏',t:'المساحة والحجم والقيمة المتوسطة',
B:[['المساحة بين منحنى والمحور',['`A = ∫_{a}^{b} |f(x)| dx` (بوحدة المساحة)','إن تغيرت إشارة f قسّم التكامل عند الجذور']],
['بين منحنيين',['`A = ∫_{a}^{b} |f(x) - g(x)| dx`','`f ≥ g` على المجال: `A = ∫(f - g)`']],
