MG.push({s:3,i:'➕',t:'المتتالية الحسابية',
B:[['التعريف',['`u_{n+1} = u_n + r` حيث r الأساس','`r > 0` متزايدة و `r < 0` متناقصة','نبرهن بإثبات أن `u_{n+1} - u_n` ثابت']],
['الحد العام',['`u_n = u_0 + n·r`','`u_n = u_p + (n - p)·r`','مثال: `u_0 = 4` و `r = 3` فـ `u_5 = 19`']],
['المجموع',['`S = k × (u_p + u_n)/2` حيث `k` عدد الحدود','عدد الحدود من p إلى n هو `n - p + 1`','`1 + 2 + ... + n = n(n + 1)/2`']],
['خاصية الوسط',['`b` وسط حسابي لـ `a` و `c` إذا `2b = a + c`','الفرق بين حدين متتاليين ثابت','تطبيق: الأجور والادخار بزيادة ثابتة']],
['أخطاء شائعة',['خطأ في عدد الحدود في المجموع','الخلط بين `u_0` و `u_1` كحد أول','نسيان `-p` في الصيغة العامة']]],
X:'المتتالية الحسابية هي سلم: تصعد (أو تنزل) بنفس الخطوة r في كل مرة. وللمجموع حيلة غاوس المشهورة: نجمع الحد الأول والأخير فنضرب الناتج في نصف عدد الحدود.',
M:['اكتب `u_n` بدلالة حد معلوم.','للمجموع احسب عدد الحدود ثم الحد الأخير.','لإثبات أنها حسابية احسب `u_{n+1} - u_n`.'],
EX:[['متتالية حسابية فيها `u_2 = 5` و `u_7 = 20`. أوجد r و `u_0` و `u_n` ثم مجموع `u_0` إلى `u_9`.','`u_7 = u_2 + 5r` فـ `20 = 5 + 5r` أي `r = 3`. `u_0 = u_2 - 2r = 5 - 6 = -1`. `u_n = -1 + 3n`. `u_9 = 26`. عدد الحدود 10. `S = 10 × (-1 + 26)/2 = 125`.'],['راتب موظف في السنة الأولى 30000 دج ويزيد 1500 دج كل سنة. ما راتبه في السنة 10 وما مجموع ما يتقاضاه في 10 سنوات؟','`u_1 = 30000` و `r = 1500`. `u_{10} = 30000 + 9×1500 = 43500` دج. `S = 10 × (30000 + 43500)/2 = 367500` دج.'],['بيّن أن `u_n = 5 - 2n` متتالية حسابية.','`u_{n+1} - u_n = 5 - 2(n + 1) - (5 - 2n) = -2`. فرق ثابت إذن حسابية أساسها `-2` وهي متناقصة.']],
K:'حسابية: `u_{n+1} = u_n + r` و `u_n = u_p + (n - p)·r`. المجموع `S = k × (u_p + u_n)/2` حيث k عدد الحدود.'});
MG.push({s:3,i:'✖️',t:'المتتالية الهندسية',
B:[['التعريف',['`u_{n+1} = q·u_n` حيث q الأساس','نبرهن بإثبات أن `u_{n+1}/u_n` ثابت','`q > 1` تزايد، `0 < q < 1` تناقص']],
['الحد العام',['`u_n = u_0·q^{n}`','`u_n = u_p·q^{n-p}`','مثال: `u_0 = 3` و `q = 2` فـ `u_4 = 48`']],
['المجموع',['`S = u_p × (1 - q^{k})/(1 - q)` لـ `q ≠ 1` حيث `k` عدد الحدود','إذا `q = 1` فـ `S = k × u_p`','`1 + q + ... + q^{n} = (1 - q^{n+1})/(1 - q)`']],
['النهاية',['`|q| < 1` ⇒ `q^{n} → 0`','`q > 1` ⇒ `q^{n} → +∞`','تطبيق: تناقص الأسعار وتزايد السكان']],
['أخطاء شائعة',['الخلط بين `1 - q` و `q - 1` في المجموع','عدد الحدود غير صحيح','خطأ في تحويل النسبة المئوية إلى معامل']]],
X:'المتتالية الهندسية تُضرب في نفس العدد q في كل خطوة. زيادة بنسبة 3 بالمئة تعني الضرب في 1.03 ونقصان بنسبة 5 بالمئة يعني الضرب في 0.95. وهي الأداة الطبيعية للنمو والتناقص بالنسب.',
M:['أساس النسبة: زيادة `t%` ⇒ `q = 1 + t/100`، نقصان ⇒ `q = 1 - t/100`.','لحساب q من حدين: اقسم ثم خذ الجذر المناسب.','تحقق من إشارة الحدود قبل اختيار الجذر.'],
EX:[['متتالية هندسية حدودها موجبة فيها `v_1 = 3` و `v_3 = 12`. أوجد q و `v_n` ثم مجموع الحدود الستة الأولى.','`v_3 = v_1·q^{2}` فـ `q^{2} = 4` و `q = 2` لأن الحدود موجبة. `v_n = 3·2^{n-1}`. `S = 3×(1 - 2^{6})/(1 - 2) = 3×63 = 189`.'],['سعر آلة 20000 دج ينقص 5% كل سنة. احسب سعرها بعد 4 سنوات.','النقصان 5% يعني الضرب في `0.95`. `20000×0.95^{4} = 20000×0.8145 ≈ 16290` دج.'],['متتالية هندسية أساسها `1/2` وحدها الأول 8. احسب `u_5` ومجموع الستة الأولى.','`u_5 = 8×(1/2)^{5} = 8/32 = 0.25`. المجموع `8×(1 - (1/2)^{6})/(1 - 1/2) = 16×(63/64) = 15.75`.']],
K:'هندسية: `u_{n+1} = q·u_n` و `u_n = u_p·q^{n-p}`. المجموع `S = u_p × (1 - q^{k})/(1 - q)`. زيادة `t%` تعني `q = 1 + t/100`.'});
MG.push({s:3,i:'🔁',t:'المتتالية من الشكل u_{n+1} = a·u_n + b',
B:[['الفكرة',['علاقة تراجعية تجمع ضربا وجمعا','نبحث عن العدد الثابت `α` الذي يحقق `α = aα + b`','`α = b/(1 - a)` لـ `a ≠ 1`']],
['المتتالية المساعدة',['نضع `v_n = u_n - α`','فنحصل على `v_{n+1} = a·v_n`','إذن `(v_n)` هندسية أساسها a']],
['الحد العام',['`v_n = v_0·a^{n}`','`u_n = α + (u_0 - α)·a^{n}`','النهاية `α` إذا `|a| < 1`']],
['خطوات الحل',['1) احسب α','2) عرّف `v_n` وأثبت أنها هندسية','3) اكتب `v_n` ثم `u_n`']],
['أخطاء شائعة',['خطأ في حساب α','نسيان أن `v_0 = u_0 - α` وليس `u_0`','إثبات الهندسية دون استعمال العلاقة']]],
X:'نريد أن نتخلص من الجزء «+b» ليبقى فقط الضرب. نبحث عن قيمة ثابتة α إذا بدأنا منها لم تتغير المتتالية. ثم ندرس البعد عن α: هذا البعد يُضرب في a في كل خطوة، فيصبح هندسيا.',
M:['α حل المعادلة `α = aα + b`.','برهان الهندسية: `v_{n+1} = u_{n+1} - α = a(u_n - α) = a·v_n`.','في النهاية ارجع إلى `u_n = v_n + α`.'],
EX:[['`u_0 = 1` و `u_{n+1} = 0.5u_n + 3`. أوجد `u_n` بدلالة n ثم نهايتها.','`α = 3/(1 - 0.5) = 6`. `v_n = u_n - 6` فـ `v_{n+1} = 0.5u_n + 3 - 6 = 0.5(u_n - 6) = 0.5v_n`. هندسية أساسها 0.5 وحدها الأول `v_0 = -5`. `v_n = -5·0.5^{n}` و `u_n = 6 - 5·0.5^{n}`. تحقق: `u_1 = 6 - 2.5 = 3.5`. والنهاية 6.'],['ادخار: رصيد أول السنة 1000 دج، كل سنة يزيد 4% وتضاف 500 دج. `u_{n+1} = 1.04u_n + 500`. أوجد `u_n` وقدّر `u_5`.','`α = 500/(1 - 1.04) = -12500`. `v_n = u_n + 12500` هندسية أساسها 1.04 و `v_0 = 13500`. `u_n = 13500×1.04^{n} - 12500`. تحقق: `u_1 = 14040 - 12500 = 1540`. و `u_5 = 13500×1.2167 - 12500 ≈ 3925` دج.']],
K:'`u_{n+1} = a·u_n + b`: العدد `α = b/(1 - a)`. `v_n = u_n - α` هندسية أساسها a و `u_n = α + (u_0 - α)·a^{n}`.'});
MG.push({s:3,i:'🏦',t:'الفوائد والتسديدات (رياضيات مالية)',
B:[['الفائدة البسيطة',['`C_n = C(1 + n·t)` (فائدة ثابتة)','متتالية حسابية','`t` معدل الفائدة السنوي']],
['الفائدة المركبة',['`C_n = C(1 + t)^{n}`','متتالية هندسية أساسها `1 + t`','الفائدة تُضاف إلى الرأس المال كل سنة']],
['دفعات منتظمة',['قيمة نهائية لدفعات `a` في نهاية كل سنة','`V = a·((1 + t)^{n} - 1)/t`','مجموع هندسي']],
['مدة المضاعفة',['نحل `(1 + t)^{n} = 2`','`n = ln 2 / ln(1 + t)`','نأخذ العدد الصحيح الأكبر']],
['أخطاء شائعة',['الخلط بين البسيطة والمركبة','تحويل المعدل: `5% = 0.05`','نسيان تدوير المدة إلى عدد سنوات صحيح']]],
X:'في الفائدة البسيطة الفائدة تُحسب دائما على المبلغ الأصلي فنزيد مبلغا ثابتا كل سنة (حسابية). وفي المركبة نحسبها على كل ما تراكم فنضرب في نفس العدد كل سنة (هندسية). ولهذا المركبة أكبر على المدى الطويل.',
M:['اكتب المعدل كعدد عشري: `t = r/100` (r المعدل).','البسيطة ⇒ حسابية، المركبة ⇒ هندسية.','للمدة استعمل ln.'],
EX:[['وُضع مبلغ 50000 دج بمعدل 6% لمدة 3 سنوات. قارن الفائدة البسيطة بالمركبة.','البسيطة: `50000×(1 + 3×0.06) = 50000×1.18 = 59000` دج. المركبة: `50000×1.06^{3} = 50000×1.191016 ≈ 59551` دج. المركبة أكبر بنحو 551 دج.'],['يدفع شخص 2000 دج في نهاية كل سنة لمدة 5 سنوات بمعدل مركب 5%. ما القيمة النهائية؟','`V = 2000×(1.05^{5} - 1)/0.05 = 2000×(0.27628/0.05) = 2000×5.5256 ≈ 11051` دج.'],['بعد كم سنة يتضاعف مبلغ بمعدل مركب 7%؟','نحل `1.07^{n} ≥ 2` فـ `n ≥ ln 2 / ln 1.07 ≈ 0.6931/0.0677 ≈ 10.24`. إذن بعد 11 سنة.']],
K:'بسيطة: `C(1 + n·t)`. مركبة: `C(1 + t)^{n}`. دفعات: `a·((1 + t)^{n} - 1)/t`. مضاعفة: `n = ln 2 / ln(1 + t)`.'});
MG.push({s:4,i:'🔄',t:'الدوال الأصلية',
B:[['التعريف',['`F` أصلية لـ `f` إذا `F′ = f`','أي أصلية أخرى: `F + C`','الشرط الابتدائي يحدد `C`']],
['أصليات مألوفة',['`x^{n}` ⟶ `x^{n+1}/(n + 1)`','`1/x` ⟶ `ln x` (على `x > 0`)','`e^{x}` ⟶ `e^{x}`']],
['أشكال مركبة',['`u′/u` ⟶ `ln u` (`u > 0`)','`u′·e^{u}` ⟶ `e^{u}`','`e^{ax+b}` ⟶ `e^{ax+b}/a`']],
['الخطوات',['اقرأ شكل الدالة','طابقه مع الجدول','تحقق بالاشتقاق']],
['أخطاء شائعة',['نسيان الثابت `C`','قسمة خاطئة على المعامل a في `e^{ax+b}`','نسيان `u′` في شكل `u′/u`']]],
X:'إيجاد الأصلية هو عكس الاشتقاق: نبحث عن دالة مشتقتها هي الدالة المعطاة. ولهذا نتحقق دائما باشتقاق النتيجة. الثابت C يظهر لأن مشتقة أي عدد ثابت هي صفر.',
M:['اكتب الدالة على شكل مجموع ثم أوجد أصلية كل حد.','تحقق بالاشتقاق.','استعمل شرطا ابتدائيا لإيجاد C.'],
EX:[['أوجد الأصلية F للدالة `f(x) = 3x^{2} - 4x + 1` التي تحقق `F(1) = 5`.','`F(x) = x^{3} - 2x^{2} + x + C`. `F(1) = 1 - 2 + 1 + C = C = 5`. إذن `F(x) = x^{3} - 2x^{2} + x + 5`.'],['أوجد أصلية `f(x) = 2/x + e^{2x}` على `]0 ; +∞[`.','`F(x) = 2 ln x + e^{2x}/2 + C`. التحقق: `F′(x) = 2/x + e^{2x} = f(x)`.'],['أوجد أصلية `f(x) = 2x/(x^{2} + 1)`.','هي من الشكل `u′/u` مع `u = x^{2} + 1 > 0`. إذن `F(x) = ln(x^{2} + 1) + C`.']],
K:'`F′ = f`. `x^{n}` ⟶ `x^{n+1}/(n + 1)` و `1/x` ⟶ `ln x` و `u′/u` ⟶ `ln u` و `e^{ax+b}` ⟶ `e^{ax+b}/a`. لا تنس الثابت C.'});
MG.push({s:4,i:'📏',t:'الحساب التكاملي والمساحات',
B:[['التعريف',['`∫_a^b f(x)dx = F(b) - F(a)`','F أي أصلية لـ f','نكتب `[F(x)]_a^b`']],
['الخواص',['الخطية: `∫(f + g) = ∫f + ∫g`','`∫_a^b f = -∫_b^a f`','علاقة شال: `∫_a^c = ∫_a^b + ∫_b^c`']],
['المساحة',['`f ≥ 0`: المساحة `∫_a^b f`','`f ≤ 0`: المساحة `-∫_a^b f`','بين منحنيين: `∫(f - g)` مع `f ≥ g`']],
['القيمة المتوسطة',['`μ = (1/(b - a))·∫_a^b f(x)dx`','تطبيق: متوسط التكلفة أو الإيراد','الوحدة: وحدة المساحة']],
['أخطاء شائعة',['نسيان الإشارة السالبة عند `f ≤ 0`','خلط ترتيب `F(b) - F(a)`','تكامل خطأ لدالة مركبة']]],
X:'التكامل المحدد يعطي المساحة المحصورة بين المنحنى ومحور الفواصل. نحسبه بإيجاد أصلية ثم الفرق بين قيمتيها عند الطرفين. وفي الاقتصاد يعطي التراكم: مثلا مجموع التكلفة الحدية يعطي التكلفة المتغيرة.',
M:['أوجد أصلية ثم احسب `F(b) - F(a)`.','للمساحة ادرس إشارة f أولا.','وحدة المساحة = وحدة الطول × وحدة الطول.'],
EX:[['احسب `∫_0^2 (3x^{2} + 1)dx`.','أصلية الدالة `x^{3} + x`. `[x^{3} + x]_0^2 = (8 + 2) - 0 = 10`.'],['احسب مساحة الحيز المحصور بين `f(x) = x^{2} - 4` ومحور الفواصل على `[-2 ; 2]`.','على هذا المجال `f ≤ 0` فالمساحة `-∫_{-2}^{2}(x^{2} - 4)dx = ∫_{-2}^{2}(4 - x^{2})dx`. `[4x - x^{3}/3]_{-2}^{2} = (8 - 8/3) - (-8 + 8/3) = 16 - 16/3 = 32/3` وحدة مساحة.'],['التكلفة الحدية `C′(x) = 3x + 10` والتكاليف الثابتة 50. أوجد `C(x)` والتكلفة المتغيرة لأول 10 وحدات.','`C(x) = 1.5x^{2} + 10x + 50` لأن `C(0) = 50`. التكلفة المتغيرة `∫_0^{10}(3x + 10)dx = [1.5x^{2} + 10x]_0^{10} = 150 + 100 = 250`.'],['احسب القيمة المتوسطة لـ `f(x) = e^{2x}` على `[0 ; 1]`.','`∫_0^1 e^{2x}dx = [e^{2x}/2]_0^1 = (e^{2} - 1)/2 ≈ 3.19`. وطول المجال 1 فالقيمة المتوسطة `≈ 3.19`.']],
K:'`∫_a^b f(x)dx = F(b) - F(a)`. المساحة للدالة الموجبة هي التكامل وللسالبة هي مقابله. المتوسط `(1/(b - a))·∫f`.'});
MG.push({s:5,i:'📍',t:'سلسلة إحصائية بمتغيرين',
B:[['المعطيات',['سلسلة أزواج `(x_i ; y_i)`','سحابة النقاط في معلم','x متغير مفسِّر وy متغير مفسَّر']],
['المتوسطات',['`x̄ = Σx_i/n` و `ȳ = Σy_i/n`','النقطة المتوسطة `G(x̄ ; ȳ)`','تقع على مستقيم التعديل']],
['التباين',['`V(x) = Σx_i^{2}/n - x̄^{2}`','`σ_x = √V(x)`','نفس القانون لـ y']],
['التغاير',['`cov(x,y) = Σx_i·y_i/n - x̄·ȳ`','إشارته تدل على اتجاه العلاقة','موجب: متغيران يتزايدان معا']],
['أخطاء شائعة',['خلط `Σx_i^{2}` مع `(Σx_i)^{2}`','نسيان القسمة على n','تعويض x بدل y في التغاير']]],
X:'عندما نقيس متغيرين معا (مثل الإشهار والمبيعات) نرسم نقطة لكل زوج فنحصل على سحابة. نريد أن نعرف هل هناك علاقة تقريبية بينهما. نبدأ بحساب المتوسطين والتباين والتغاير، وهي مواد خام للتعديل الخطي.',
M:['كوّن جدولا بالأعمدة `x` و `y` و `x^{2}` و `xy`.','احسب المجاميع ثم المتوسطات.','تحقق أن `cov` يحمل نفس إشارة ميل المستقيم.'],
EX:[['النفقات الإشهارية x (بآلاف الدنانير): 1، 2، 3، 4، 5 والمبيعات y: 3، 5، 6، 8، 9. احسب `x̄` و `ȳ` و `V(x)` و `cov(x,y)`.','`x̄ = 15/5 = 3` و `ȳ = 31/5 = 6.2`. `Σx^{2} = 55` فـ `V(x) = 55/5 - 9 = 2`. `Σxy = 3 + 10 + 18 + 32 + 45 = 108` فـ `cov = 108/5 - 3×6.2 = 21.6 - 18.6 = 3`.'],['في السلسلة السابقة احسب `V(y)` و `σ_y`.','`Σy^{2} = 9 + 25 + 36 + 64 + 81 = 215`. `V(y) = 215/5 - 6.2^{2} = 43 - 38.44 = 4.56`. `σ_y = √4.56 ≈ 2.135`.']],
K:'`x̄ = Σx_i/n` و `V(x) = Σx_i^{2}/n - x̄^{2}` و `cov(x,y) = Σx_i·y_i/n - x̄·ȳ`. النقطة المتوسطة `G(x̄ ; ȳ)`.'});
MG.push({s:5,i:'📈',t:'التعديل الخطي والارتباط والتقدير',
B:[['مستقيم الانحدار',['`y = a·x + b` (المربعات الصغرى)','`a = cov(x,y)/V(x)`','`b = ȳ - a·x̄`']],
['معامل الارتباط',['`r = cov(x,y)/(σ_x·σ_y)`','`-1 ≤ r ≤ 1`','`|r|` قريب من 1 ⇒ ارتباط قوي']],
['التقدير',['نعوض قيمة x في المعادلة فنجد y تقديريا','نحل `y = y_0` لنجد x','احذر التقدير بعيدا عن مجال المعطيات']],
['التفسير',['`a` هو الزيادة في y لكل وحدة في x','`r > 0` علاقة طردية و `r < 0` عكسية','يمر المستقيم بالنقطة `G`']],
['أخطاء شائعة',['استعمال `V(y)` بدل `V(x)` في الميل','نسيان `b = ȳ - a·x̄`','القول أن ارتباطا قويا يعني وجود سببية']]],
X:'نبحث عن المستقيم الأقرب لكل النقاط معا. ميله a هو التغاير مقسوما على تباين x، ويمر دائما من النقطة المتوسطة. أما معامل الارتباط r فيقيس مدى التصاق النقاط بالمستقيم: قريب من 1 أو -1 يعني التعديل جيد.',
M:['احسب `a` ثم `b` بالترتيب.','قدّر y بتعويض x، أو أوجد x بحل المعادلة.','فسّر r بعبارات مرتبطة بالمسألة.'],
EX:[['باستعمال معطيات الإشهار (x̄=3، ȳ=6.2، V(x)=2، cov=3) أوجد معادلة مستقيم الانحدار وقدّر المبيعات عند `x = 7`.','`a = 3/2 = 1.5` و `b = 6.2 - 1.5×3 = 1.7`. المعادلة `y = 1.5x + 1.7`. عند `x = 7`: `y = 10.5 + 1.7 = 12.2` أي 12200 دج تقريبا.'],['ما النفقات اللازمة لبلوغ مبيعات قيمتها 20؟','نحل `1.5x + 1.7 = 20` فـ `x = 18.3/1.5 = 12.2` أي نحو 12200 دج من الإشهار.'],['احسب معامل الارتباط وفسّره.','`σ_x = √2 ≈ 1.414` و `σ_y ≈ 2.135`. `r = 3/(1.414×2.135) ≈ 0.994`. قريب جدا من 1 فالارتباط طردي وقوي والتعديل الخطي مناسب.']],
K:'`a = cov(x,y)/V(x)` و `b = ȳ - a·x̄` و `r = cov(x,y)/(σ_x·σ_y)`. المستقيم يمر بالنقطة `G`.'});
MG.push({s:6,i:'🧮',t:'مبادئ الاحتمال والعد',
B:[['القانون الأساسي',['`P(A) = N_A / N` (الملائمة على الممكنة)','`0 ≤ P(A) ≤ 1`','`P(Ā) = 1 - P(A)`']],
['الاتحاد',['`P(A ∪ B) = P(A) + P(B) - P(A ∩ B)`','حادثتان غير متلائمتين: `P(A ∩ B) = 0`','«على الأقل» ⇒ نستعمل الحادثة المعاكسة']],
['العد',['`n! = n×(n-1)×...×1`','ترتيبات: `A(n,p) = n!/(n-p)!`','توفيقات: `C(n,p) = n!/(p!(n-p)!)`']],
['اختيار',['الترتيب مهم ⇒ ترتيبات','الترتيب غير مهم ⇒ توفيقات','سحب في آن واحد ⇒ توفيقات']],
['أخطاء شائعة',['الخلط بين الترتيبات والتوفيقات','نسيان الحالات المتساوية الاحتمال','حساب احتمال «على الأقل» مباشرة بدل المعاكسة']]],
X:'الاحتمال هو نسبة الحالات التي تعجبنا من كل الحالات الممكنة، بشرط أن تكون كلها متساوية الاحتمال. وفي العدّ نسأل سؤالا واحدا: هل الترتيب مهم؟ نعم فترتيبات، لا فتوفيقات.',
M:['اعدّ الحالات الممكنة أولا.','«على الأقل واحد» = 1 - «ولا واحد».','اكتب النتيجة كسرا مختصرا.'],
EX:[['كيس فيه 5 كرات حمراء و 3 زرقاء. نسحب كرتين في آن واحد. احسب احتمال أن تكونا حمراوين، وأن يكون لونهما مختلفا، وأن تكون واحدة زرقاء على الأقل.','عدد الحالات `C(8,2) = 28`. حمراوان: `C(5,2)/28 = 10/28 = 5/14`. مختلفان: `5×3/28 = 15/28`. على الأقل زرقاء: `1 - 10/28 = 18/28 = 9/14`.'],['كم لجنة من 3 أعضاء يمكن تشكيلها من 10 أشخاص؟','الترتيب غير مهم. `C(10,3) = 120` لجنة.'],['`P(A) = 0.5` و `P(B) = 0.4` و `P(A ∩ B) = 0.2`. احسب `P(A ∪ B)` و `P(Ā)`.','`P(A ∪ B) = 0.5 + 0.4 - 0.2 = 0.7`. و `P(Ā) = 1 - 0.5 = 0.5`.']],
K:'`P(A ∪ B) = P(A) + P(B) - P(A ∩ B)`. الاحتمال هو الملائمة على الممكنة. للتوفيقات `C(n,p)`. «على الأقل» نستعمل المعاكسة.'});
MG.push({s:6,i:'🌳',t:'الاحتمال الشرطي والاستقلال',
B:[['الاحتمال الشرطي',['`P(A|B) = P(A ∩ B)/P(B)`','`P(A ∩ B) = P(B)·P(A|B)`','نقرأ: احتمال A علما أن B وقع']],
['شجرة الاحتمالات',['على كل فرع احتمال','جداء احتمالات الفروع على مسار','مجموع احتمالات فروع من نفس العقدة = 1']],
['الاحتمالات الكلية',['`P(D) = P(M_1)P(D|M_1) + P(M_2)P(D|M_2)`','نجمع كل المسارات المؤدية للحادثة','تقسيم الفضاء إلى `M_1, M_2`']],
['الاستقلال',['A و B مستقلتان ⇔ `P(A ∩ B) = P(A)·P(B)`','عندئذ `P(A|B) = P(A)`','لا تخلط بينه وبين التنافي']],
['أخطاء شائعة',['الخلط بين `P(A|B)` و `P(B|A)`','جمع احتمالات الفروع بدل ضربها','القول أن حادثتين متنافيتين مستقلتان']]],
X:'الاحتمال الشرطي يعني: نغيّر الكون. بدل كل الحالات ننظر فقط للحالات التي وقع فيها B. والشجرة تنظم الحسابات: نضرب على الفرع ونجمع بين الفروع المختلفة التي تؤدي إلى نفس النتيجة.',
M:['ارسم شجرة قبل أي حساب.','ضرب على المسار وجمع بين المسارات.','لإثبات الاستقلال قارن `P(A ∩ B)` بـ `P(A)P(B)`.'],
EX:[['آلة M1 تنتج 60% من القطع و 2% منها معيبة، وآلة M2 تنتج 40% و 5% منها معيبة. احسب احتمال أن تكون قطعة معيبة، ثم احتمال أنها من M2 علما أنها معيبة.','`P(D) = 0.6×0.02 + 0.4×0.05 = 0.012 + 0.02 = 0.032`. `P(M_2|D) = 0.02/0.032 = 0.625`.'],['`P(A) = 0.3` و `P(B) = 0.5` و `P(A ∩ B) = 0.15`. هل A و B مستقلتان؟','`P(A)·P(B) = 0.15 = P(A ∩ B)`. إذن مستقلتان.'],['`P(A ∩ B) = 0.2` و `P(B) = 0.5`. احسب `P(A|B)`.','`P(A|B) = 0.2/0.5 = 0.4`.']],
K:'`P(A|B) = P(A ∩ B)/P(B)`. في الشجرة نضرب على المسار ونجمع بين المسارات. استقلال: `P(A ∩ B) = P(A)·P(B)`.'});
MG.push({s:6,i:'💵',t:'المتغير العشوائي والأمل الرياضياتي والتباين',
B:[['قانون الاحتمال',['جدول القيم `x_i` واحتمالاتها `p_i`','`Σp_i = 1`','`p_i ≥ 0`']],
['الأمل',['`E(X) = Σx_i·p_i`','متوسط الربح على المدى الطويل','لعبة عادلة: `E(X) = 0`']],
['التباين',['`V(X) = E(X^{2}) - (E(X))^{2}`','`E(X^{2}) = Σx_i^{2}·p_i`','`σ = √V(X)`']],
['تطبيق',['القرار الاقتصادي بالأمل','مقارنة مشروعين بالأمل والتباين','التباين الأصغر مخاطرة أقل']],
['أخطاء شائعة',['نسيان الربح الصافي (طرح الثمن)','عدم التحقق من `Σp_i = 1`','`V = E(X^{2}) - E(X)` بدل التربيع']]],
X:'المتغير العشوائي هو نتيجة رقمية لتجربة عشوائية (ربح، عدد، تكلفة). الأمل الرياضياتي هو المتوسط الذي نتوقعه على المدى الطويل، والتباين يقيس مدى تشتت النتائج حوله، أي درجة المخاطرة.',
M:['اكتب جدول القانون أولا وتحقق من مجموع الاحتمالات.','احسب `E(X)` ثم `E(X^{2})`.','فسّر إشارة الأمل: سالب يعني خسارة متوسطة.'],
EX:[['قيم X: 1 و 2 و 3 باحتمالات `0.2` و `a` و `0.5`. أوجد a و `E(X)`.','`0.2 + a + 0.5 = 1` فـ `a = 0.3`. `E(X) = 1×0.2 + 2×0.3 + 3×0.5 = 0.2 + 0.6 + 1.5 = 2.3`.'],['لعبة: الربح X بالدينار يأخذ `-10` و `0` و `20` باحتمالات `0.5` و `0.3` و `0.2`. احسب `E(X)` و `V(X)`.','`E(X) = -5 + 0 + 4 = -1`. `E(X^{2}) = 100×0.5 + 0 + 400×0.2 = 130`. `V(X) = 130 - 1 = 129` و `σ ≈ 11.36`. الأمل سالب فاللعبة غير مربحة.'],['تذكرة سحب ثمنها 5 دج تربح 100 دج باحتمال `0.02`. ما الأمل الصافي؟','الربح الصافي `95` باحتمال `0.02` و `-5` باحتمال `0.98`. `E = 95×0.02 - 5×0.98 = 1.9 - 4.9 = -3` دج.']],
K:'`E(X) = Σx_i·p_i` و `V(X) = E(X^{2}) - (E(X))^{2}`. لعبة عادلة: `E(X) = 0`. الربح الصافي = الربح - الثمن.'});
MG.push({s:6,i:'🎯',t:'القانون الثنائي',
B:[['الشروط',['`n` تجربة مستقلة متطابقة','لكل تجربة نتيجتان: نجاح باحتمال `p` وفشل `q = 1 - p`','X عدد النجاحات: `X ~ B(n ; p)`']],
['القانون',['`P(X = k) = C(n,k)·p^{k}·q^{n-k}`','`k` من 0 إلى n','`P(X ≥ 1) = 1 - q^{n}`']],
['الأمل والتباين',['`E(X) = n·p`','`V(X) = n·p·q`','`σ = √(npq)`']],
['كيف أتعرف عليه؟',['تكرار نفس الاختبار','احتمال النجاح ثابت','العد يخص النجاحات فقط']],
['أخطاء شائعة',['نسيان `C(n,k)`','خلط `p` و `q`','استعماله مع سحب دون إرجاع']]],
X:'نستعمل القانون الثنائي عندما نكرر نفس التجربة n مرة ونعدّ كم مرة نجحنا. كل نتيجة مفصلة (k نجاح و n-k فشل) لها احتمال `p^k q^(n-k)` وعدد طرق ترتيبها هو `C(n,k)`.',
M:['حدد n و p بوضوح.','«على الأقل واحد» ⇒ `1 - q^{n}`.','الأمل `np` يعطي المتوسط المتوقع للنجاحات.'],
EX:[['`X ~ B(5 ; 0.3)`. احسب `P(X = 2)` و `P(X ≥ 1)` و `E(X)` و `V(X)`.','`P(X = 2) = C(5,2)×0.3^{2}×0.7^{3} = 10×0.09×0.343 = 0.3087`. `P(X ≥ 1) = 1 - 0.7^{5} = 1 - 0.16807 = 0.83193`. `E(X) = 5×0.3 = 1.5` و `V(X) = 5×0.3×0.7 = 1.05`.'],['اختبار من 10 أسئلة كل منها 4 اختيارات. يجيب طالب عشوائيا. ما احتمال أن يصيب 3 أسئلة بالضبط؟','`X ~ B(10 ; 0.25)`. `P(X = 3) = C(10,3)×0.25^{3}×0.75^{7} = 120×0.015625×0.13348 ≈ 0.2503`.']],
K:'`X ~ B(n ; p)`: `P(X = k) = C(n,k)·p^{k}·q^{n-k}` و `E = n·p` و `V = n·p·q` و `P(X ≥ 1) = 1 - q^{n}`.'});

function mgCard(l,i){const sc=MGSEC[l.s];
 const ex=l.EX.map((e,j)=>'<div class="ex"><b>تمرين '+(j+1)+':</b> '+esc(e[0])+'<div class="sol"><b>الحل:</b>'+steps(e[1]).map(z=>'<div class="st">'+esc(z)+'</div>').join('')+'</div></div>').join('');
 const x='<div class="extra"><b>طرق وقواعد:</b><ul>'+l.M.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul><div class="how"><b>شرح مبسط:</b> '+esc(l.X)+'</div></div><div class="extra"><b>تمارين محلولة بالتفصيل:</b>'+ex+'</div>';
 return card('الدرس '+(i+1),sc[1],l.i,l.t,l.B,l.K,x,sc[0]);}
function kfix(k){if(k.indexOf('`')>-1)return k;
 return k.replace(/[A-Za-z0-9ΔΩαβθπℓμσ∞≤≥≠≡⇒⇔≈∈ℝℕℤℂ√∫±|+\-−×÷=<>\/^_(){}\[\];:·′.²³⁰¹⁴-⁹ₙⁿ₀-₉ˣᵗᵃᵇᵘʸᶻᵐᶿ][A-Za-z0-9ΔΩαβθπℓμσ∞≤≥≠≡⇒⇔≈∈ℝℕℤℂ√∫±|+\-−×÷=<>\/^_(){}\[\];:·′.,²³⁰¹⁴-⁹ₙⁿ₀-₉ˣᵗᵃᵇᵘʸᶻᵐᶿ ]*/g,function(r){
  var t=r.replace(/[\s.,;:]+$/,''), tail=r.slice(t.length);
  if(!/[A-Za-z0-9Δ=<>≤≥⇒⇔√∫]/.test(t)||t.length<2)return r;
  return '`'+t+'`'+tail;});}

