const AM1={"math":{"name":"الرياضيات","c":"#1565c0","i":"➗","L":[{"t":"الأعداد الطبيعية والأعداد العشرية","bs":[["الأعداد الطبيعية",["0، 1، 2، 3، … تُستعمل في العدّ."]],["الفكرة الأساسية",["العدد العشري له فاصلة: مثل 14,27. جزؤه الصحيح 14 وجزؤه العشري 27."]],["الأرقام بعد الفاصلة",["الأعشار، ثم أجزاء المئة، ثم أجزاء الألف."]],["أمثلة",["مثال: في العدد 36,482 → الرقم 3 للعشرات، 6 للوحدات، 4 للأعشار، 8 لأجزاء المئة، 2 لأجزاء الألف."]],["الكسر العشري",["7/10 = 0,7 ؛ 25/100 = 0,25 ؛ 3/1000 = 0,003."]]],"k":"0، 1، 2، 3، … تُستعمل في العدّ."},{"t":"مقارنة الأعداد العشرية وترتيبها","bs":[["الفكرة الأساسية",["نقارن الجزء الصحيح أولًا، فإن تساوى نقارن الأرقام بعد الفاصلة من اليسار.","يمكن إضافة أصفار على يمين الجزء العشري دون تغيير القيمة: 2,5 = 2,50."]],["أمثلة",["مثال: رتّب تصاعديًا 4,09 ؛ 4,9 ؛ 3,99."]],["تطبيق",["الحل: نكتب 4,9 = 4,90. الجزء الصحيح: 3 < 4 فـ 3,99 هو الأصغر. ثم 4,09 < 4,90. إذن: 3,99 < 4,09 < 4,9."]]],"k":"نقارن الجزء الصحيح أولًا، فإن تساوى نقارن الأرقام بعد الفاصلة من اليسار."},{"t":"جمع الأعداد العشرية وطرحها","bs":[["الفكرة الأساسية",["نضع الفواصل تحت بعضها، ونكمل الأرقام الناقصة بأصفار، ثم نجمع أو نطرح كالمعتاد."]],["أمثلة",["مثال 1: 12,7 + 3,85 = 12,70 + 3,85 = 16,55.","مثال 2: 9,4 − 2,75 = 9,40 − 2,75 = 6,65."]],["تطبيق",["مسألة: اشترى تلميذ دفترًا بـ 85,50 دج وقلمًا بـ 27,25 دج. كم دفع؟","الحل: 85,50 + 27,25 = 112,75 دج."]]],"k":"نضع الفواصل تحت بعضها، ونكمل الأرقام الناقصة بأصفار، ثم نجمع أو نطرح كالمعتاد."},{"t":"ضرب الأعداد العشرية","bs":[["الفكرة الأساسية",["الضرب في 10 أو 100 أو 1000: تتحرك الفاصلة إلى اليمين بمنزلة أو منزلتين أو ثلاث منازل."]],["ضرب عددين عشريين",["نضرب الأرقام كأنها طبيعية، ثم نضع الفاصلة بعدد الأرقام العشرية في العاملين معًا."]],["أمثلة",["مثال: 2,4 × 1,3: نحسب 24 × 13 = 312، وفي العاملين رقمان عشريان، إذن الناتج 3,12.","مثال: 4,25 × 2 = 8,50 = 8,5."]]],"k":"الضرب في 10 أو 100 أو 1000: تتحرك الفاصلة إلى اليمين بمنزلة أو منزلتين أو ثلاث منازل."},{"t":"أولويات العمليات الحسابية","bs":[["الفكرة الأساسية",["نحسب أولًا ما بين الأقواس، ثم الضرب والقسمة (من اليسار إلى اليمين)، ثم الجمع والطرح."]],["أمثلة",["مثال: 7 + 5 × 3 = 7 + 15 = 22. أما (7 + 5) × 3 = 12 × 3 = 36 لأن الأقواس تُحسب أولًا."]]],"k":"نحسب أولًا ما بين الأقواس، ثم الضرب والقسمة (من اليسار إلى اليمين)، ثم الجمع والطرح."},{"t":"القسمة الإقليدية وقابلية القسمة","bs":[["القسمة الإقليدية",["المقسوم = المقسوم عليه × الحاصل + الباقي، والباقي أصغر من المقسوم عليه."]],["أمثلة",["مثال: 47 ÷ 6: أكبر مضاعف لـ 6 لا يتجاوز 47 هو 42 = 6 × 7، والباقي 5. إذن 47 = 6 × 7 + 5.","مثال: 234 → 2 + 3 + 4 = 9، فهو يقبل القسمة على 3 وعلى 9."]],["الفكرة الأساسية",["يقبل العدد القسمة على: 2 إذا كان رقم آحاده زوجيًا ؛ 5 إذا انتهى بـ 0 أو 5 ؛ 10 إذا انتهى بـ 0 ؛ 3 إذا كان مجموع أرقامه يقبل القسمة على 3 ؛ 9 إذا كان مجموع أرقامه يقبل …"]]],"k":"المقسوم = المقسوم عليه × الحاصل + الباقي، والباقي أصغر من المقسوم عليه."},{"t":"الكسور والكتابات الكسرية","bs":[["الكسر a/b",["a البسط، b المقام (غير معدوم). يمثّل خارج قسمة a على b."]],["الفكرة الأساسية",["الكسور المتكافئة لها القيمة نفسها: 1/2 = 2/4 = 3/6 (نضرب البسط والمقام في العدد نفسه).","لإيجاد كسر من كمية: نقسم الكمية على المقام ثم نضرب في البسط."]],["أمثلة",["مثال: 3/5 من 40: 40 ÷ 5 = 8 ثم 8 × 3 = 24."]]],"k":"a البسط، b المقام (غير معدوم). يمثّل خارج قسمة a على b."},{"t":"الأعداد النسبية والمستقيم المدرّج","bs":[["الأعداد النسبية",["موجبة وسالبة وصفر. الأعداد الأكبر على المستقيم المدرّج تقع على اليمين."]],["الفكرة الأساسية",["−2 < 1 لأن −2 على يسار 1. وبين −5 و −1 يكون −5 هو الأصغر."]],["أمثلة",["مثال: رتّب تصاعديًا: 2 ؛ 0 ؛ −1 ؛ −3."]],["تطبيق",["الحل: −3 < −1 < 0 < 2."]]],"k":"موجبة وسالبة وصفر. الأعداد الأكبر على المستقيم المدرّج تقع على اليمين."},{"t":"التناسبية","bs":[["الفكرة الأساسية",["يكون جدول تناسبيًا إذا انتقلنا من أعداد السطر الأول إلى أعداد السطر الثاني بالضرب في العدد نفسه (معامل التناسبية).","طريقة الرجوع إلى الوحدة: نحسب ثمن الواحدة ثم نضرب."]],["أمثلة",["مثال: ثمن 3 كراريس 150 دج. ثمن الواحد = 150 ÷ 3 = 50 دج. ثمن 5 كراريس = 5 × 50 = 250 دج."]]],"k":"يكون جدول تناسبيًا إذا انتقلنا من أعداد السطر الأول إلى أعداد السطر الثاني بالضرب في العدد نفسه (معامل التناسبية)."},{"t":"تنظيم المعطيات والمتوسط الحسابي","bs":[["الفكرة الأساسية",["نستعمل الجداول لتجميع القيم وقراءة المعطيات بدقة.","المتوسط الحسابي = مجموع القيم ÷ عددها."]],["أمثلة",["مثال: علامات تلميذ: 10، 14، 12. المجموع = 36، عددها 3، المتوسط = 36 ÷ 3 = 12."]]],"k":"نستعمل الجداول لتجميع القيم وقراءة المعطيات بدقة."},{"t":"المستقيمات: التوازي والتعامد","bs":[["القطعة المستقيمة لها",["القطعة المستقيمة لها طرفان وطول. نصف المستقيم له بداية فقط. المستقيم لا بداية له ولا نهاية."]],["المستقيمان المتوازيان لا",["المستقيمان المتوازيان لا يتقاطعان. المتعامدان يتقاطعان بزاوية قائمة (90°)."]],["للتحقق من التعامد",["للتحقق من التعامد نستعمل الكوس (المنقلة)."]],["أمثلة",["مثال: إذا كانت الزاوية بين مستقيمين 90° فهما متعامدان."]]],"k":"القطعة المستقيمة لها طرفان وطول. نصف المستقيم له بداية فقط. المستقيم لا بداية له ولا نهاية."},{"t":"الزوايا والمثلثات","bs":[["زاوية حادة",["أصغر من 90°. قائمة: 90°. منفرجة: بين 90° و180°. مستقيمة: 180°."]],["الفكرة الأساسية",["مجموع زوايا المثلث = 180°."]],["أمثلة",["مثال: زاويتان في مثلث 45° و65°، فالثالثة = 180° − (45° + 65°) = 180° − 110° = 70°."]]],"k":"أصغر من 90°. قائمة: 90°. منفرجة: بين 90° و180°. مستقيمة: 180°."},{"t":"المثلثات الخاصة والرباعيات","bs":[["المثلث المتقايس الأضلاع",["أضلاعه الثلاثة متساوية. المتساوي الساقين: ضلعان متساويان. القائم: زاوية قائمة."]],["المربع",["4 أضلاع متساوية و4 زوايا قائمة. المستطيل: 4 زوايا قائمة وأضلاعه المتقابلة متساوية. المعين: 4 أضلاع متساوية."]],["أمثلة",["مثال: شكل رباعي أضلاعه متساوية وزواياه قائمة هو مربع."]]],"k":"أضلاعه الثلاثة متساوية. المتساوي الساقين: ضلعان متساويان. القائم: زاوية قائمة."},{"t":"المحيط والمساحة","bs":[["محيط المربع =",["محيط المربع = 4 × الضلع ؛ مساحته = الضلع × الضلع."]],["محيط المستطيل =",["محيط المستطيل = 2 × (الطول + العرض) ؛ مساحته = الطول × العرض."]],["مساحة المثلث =",["مساحة المثلث = (القاعدة × الارتفاع) ÷ 2."]],["أمثلة",["مثال: مستطيل طوله 8 سم وعرضه 3 سم: المحيط = 2 × (8 + 3) = 22 سم، المساحة = 8 × 3 = 24 سم². تنبيه: المحيط بوحدة الطول (سم) والمساحة بوحدة مربعة (سم²)."]]],"k":"محيط المربع = 4 × الضلع ؛ مساحته = الضلع × الضلع."},{"t":"متوازي المستطيلات والحجم","bs":[["الفكرة الأساسية",["متوازي المستطيلات مجسم له 6 أوجه مستطيلة و8 رؤوس و12 حرفًا.","الحجم = الطول × العرض × الارتفاع."]],["أمثلة",["مثال: صندوق 5 سم × 3 سم × 2 سم: الحجم = 5 × 3 × 2 = 30 سم³."]]],"k":"متوازي المستطيلات مجسم له 6 أوجه مستطيلة و8 رؤوس و12 حرفًا."},{"t":"التناظر المحوري","bs":[["في التناظر المحوري،",["في التناظر المحوري، المحور هو واسط (عمودي ومنصّف) القطعة التي تصل نقطة بصورتها."]],["النقطة وصورتها على",["النقطة وصورتها على بعدين متساويين من المحور."]],["لإنشاء صورة A",["نرسم عمودًا من A على المحور، ثم نضع A' على الجهة الأخرى بالبعد نفسه."]]],"k":"في التناظر المحوري، المحور هو واسط (عمودي ومنصّف) القطعة التي تصل نقطة بصورتها."},{"t":"الحساب الحرفي والمعادلات البسيطة","bs":[["الفكرة الأساسية",["الحرف قد يمثّل عددًا مجهولًا. 3x تعني 3 × x.","المعادلة مساواة فيها مجهول. نحلّها بإيجاد القيمة التي تجعل المساواة صحيحة."]],["أمثلة",["مثال: x + 7 = 15 ⟸ نطرح 7 من الطرفين: x = 15 − 7 = 8. التحقق: 8 + 7 = 15 ✓."]]],"k":"الحرف قد يمثّل عددًا مجهولًا. 3x تعني 3 × x."}]},"ar":{"name":"اللغة العربية","c":"#c62828","i":"📖","L":[{"t":"كيف ندرس النص؟","bs":[["خطوات الفهم",["اقرأ النص قراءة أولى لفهم الموضوع العام، ثم أعد القراءة لتحديد الأفكار المهمة.","استخرج الفكرة العامة في جملة موجزة تشمل موضوع النص كله.","قسّم النص إلى أفكار أساسية حسب الفقرات أو تغيّر المعنى.","اشرح الكلمات من سياقها، ثم استعملها في جمل من إنشائك."]],["مثال مبسط",["النص: «يحافظ أمين على نظافة حيه، فيجمع النفايات مع أصدقائه ويضعها في الحاوية.»","الفكرة العامة: مساهمة أمين وأصدقائه في المحافظة على نظافة الحي.","معنى «يحافظ»: يصون ويعتني."]]],"k":"اقرأ النص قراءة أولى لفهم الموضوع العام، ثم أعد القراءة لتحديد الأفكار المهمة."},{"t":"الفعل والزمن","bs":[["القاعدة",["الفعل الماضي يدل على حدث وقع وانتهى: كتبَ، نجحَ.","الفعل المضارع يدل غالبا على حدث يقع الآن أو في المستقبل: يكتبُ، ينجحُ.","فعل الأمر يطلب القيام بعمل: اكتبْ، اجتهدْ.","تذكّر: قد يتغير إعراب الفعل المضارع بحسب الأدوات الداخلة عليه."]],["تطبيق",["«عاد التلميذ، يراجع دروسه، ثم اكتب واجبك.» الأفعال: عاد (ماض)، يراجع (مضارع)، اكتب (أمر)."]]],"k":"الفعل الماضي يدل على حدث وقع وانتهى: كتبَ، نجحَ."},{"t":"الجملة الاسمية والجملة الفعلية","bs":[["القاعدة",["الجملة الاسمية تبدأ باسم، وتتكون غالبا من مبتدأ وخبر: العلمُ نورٌ.","المبتدأ مرفوع، والخبر مرفوع في الأصل.","الجملة الفعلية تبدأ بفعل، وتتكون غالبا من فعل وفاعل وقد يأتي بعدها مفعول به: قرأَ التلميذُ القصةَ.","الفاعل هو من قام بالفعل، والمفعول به هو من وقع عليه الفعل."]],["إعراب نموذجي",["العلمُ نورٌ: العلمُ مبتدأ مرفوع وعلامة رفعه الضمة؛ نورٌ خبر مرفوع وعلامة رفعه الضمة.","كتبَ التلميذُ الدرسَ: كتب فعل ماض؛ التلميذ فاعل مرفوع؛ الدرس مفعول به منصوب."]]],"k":"الجملة الاسمية تبدأ باسم، وتتكون غالبا من مبتدأ وخبر: العلمُ نورٌ."},{"t":"النعت والمنعوت","bs":[["النعت صفة تذكر",["النعت صفة تذكر لتوضيح اسم قبلها يسمى المنعوت."]],["يتبع النعت منعوته",["يتبع النعت منعوته في التذكير والتأنيث، والإفراد والتثنية والجمع، والتعريف والتنكير، والإعراب في الأمثلة المقررة."]],["مثال",["قرأتُ قصةً ممتعةً. قصةً: منعوت، ممتعةً: نعت منصوب."]]],"k":"النعت صفة تذكر لتوضيح اسم قبلها يسمى المنعوت."},{"t":"الضمائر وأسماء الإشارة","bs":[["الضمير يدل على",["الضمير يدل على متكلم أو مخاطب أو غائب: أنا، نحن، أنت، هو، هي، هم."]],["من الضمائر المتصلة",["ـه، ـها، ـهم، ـك، ـنا، مثل: كتابه، رأيتها، ساعدنا."]],["من أسماء الإشارة",["هذا للمفرد المذكر، هذه للمفرد المؤنث، هاتان/هذان للمثنى، هؤلاء للجمع، ذلك وتلك للبعيد."]]],"k":"الضمير يدل على متكلم أو مخاطب أو غائب: أنا، نحن، أنت، هو، هي، هم."},{"t":"المفرد والمثنى والجمع","bs":[["المفرد يدل على",["المفرد يدل على واحد أو واحدة: تلميذ، تلميذة."]],["المثنى يدل على",["المثنى يدل على اثنين أو اثنتين: تلميذين/تلميذان، تلميذتين/تلميذتان."]],["جمع المذكر السالم",["معلمين/معلمون، وجمع المؤنث السالم: معلمات، وجمع التكسير: رجال، كتب."]],["تختلف علامة الإعراب",["تختلف علامة الإعراب حسب موقع الكلمة ونوع الجمع."]]],"k":"المفرد يدل على واحد أو واحدة: تلميذ، تلميذة."},{"t":"الفاعل والمفعول به","bs":[["الفاعل اسم مرفوع",["الفاعل اسم مرفوع يدل على من قام بالفعل: زرعَ الفلاحُ الشجرةَ."]],["المفعول به اسم",["المفعول به اسم منصوب وقع عليه الفعل: زرع الفلاحُ الشجرةَ."]],["في المثال",["الفلاحُ فاعل مرفوع، الشجرةَ مفعول به منصوب."]]],"k":"الفاعل اسم مرفوع يدل على من قام بالفعل: زرعَ الفلاحُ الشجرةَ."},{"t":"الإملاء: التاء المفتوحة والمربوطة والهاء","bs":[["القاعدة",["التاء المربوطة (ة) تظهر غالبا في آخر الأسماء المؤنثة: مدرسة، شجرة. عند الوقف تُنطق هاء غالبا.","التاء المفتوحة (ت) تبقى تاء عند الوقف: بنت، بيت، كتبتْ.","الهاء (ه) ضمير أو حرف أصلي: كتابه، وجه، مياه. لا تخلط بين «مدرسة» .و«مدرسته»"]],["طريقة التحقق",["ضع الكلمة في جملة أو صِلْ بها ضميرا: شجرة ← شجرتها؛ بنت ← بنتها. انتبه إلى أصل الكلمة ومعناها."]]],"k":"التاء المربوطة (ة) تظهر غالبا في آخر الأسماء المؤنثة: مدرسة، شجرة. عند الوقف تُنطق هاء غالبا."},{"t":"التعبير الكتابي","bs":[["مقدمة قصيرة تعرّف",["مقدمة قصيرة تعرّف بالموضوع."]],["عرض يتضمن فكرتين",["عرض يتضمن فكرتين أو ثلاثا مرتبة مع أمثلة."]],["خاتمة تلخص الفكرة",["خاتمة تلخص الفكرة أو تقدم نصيحة."]],["استعمل جملا واضحة",["استعمل جملا واضحة وعلامات ترقيم، وتجنب تكرار الكلمات."]],["راجع الإملاء، واتفاق",["راجع الإملاء، واتفاق الفعل والفاعل، وترابط الجمل. نموذج موضوع: المحافظة على البيئة"]],["البيئة بيتنا الكبير،",["البيئة بيتنا الكبير، لذلك يجب أن نحافظ عليها نظيفة وجميلة. أضع النفايات في الأماكن المخصصة، وأقتصد في الماء، وأشارك في غرس الأشجار. كما أنصح أصدقائي بعدم تلويث الشوارع …"]]],"k":"مقدمة قصيرة تعرّف بالموضوع."},{"t":"التشبيه والصورة الفنية – مدخل مبسط","bs":[["التشبيه يقارن شيئا",["التشبيه يقارن شيئا بشيء آخر لوجود صفة مشتركة بينهما."]],["مثال",["«العلم كالنور.» المشبّه: العلم، المشبّه به: النور، أداة التشبيه: الكاف، وجه الشبه: الهداية أو الإضاءة بحسب السياق."]],["في تحليل النص،",["في تحليل النص، لا تكتف بتسمية الصورة؛ اشرح المعنى الذي تضيفه."]]],"k":"التشبيه يقارن شيئا بشيء آخر لوجود صفة مشتركة بينهما."}]},"fr":{"name":"الفرنسية","c":"#6a1b9a","i":"📘","L":[{"t":"Se présenter – Présentation personnelle","bs":[["Vocabulaire et phrases …",["`Bonjour ! Salut ! Au revoir ! À bientôt !`","`Je m’appelle Lina. J’ai onze ans. J’habite à Tlemcen. Je suis élève en première année moyenne.`","`Pour demander le nom : Comment tu t’appelles ? Pour demander l’âge : Quel âge as-tu ?`","`Attention : « je suis » exprime l’identité ou la profession ; « j’ai » exprime l’âge.`"]],["أمثلة",["Exemple"]]],"k":"`Bonjour ! Salut ! Au revoir ! À bientôt !`"},{"t":"Les pronoms personnels sujets","bs":[["Je, tu, il,",["`Je, tu, il, elle, on, nous, vous, ils, elles remplacent les noms et accompagnent le verbe conjugué.`"]],["Exemple",["`Amine est élève.`"]],["Il est élève.",["`Il est élève.`"]],["Sara et Lina",["`Sara et Lina sont amies.`"]],["Elles sont amies.",["`Elles sont amies.`"]]],"k":"`Je, tu, il, elle, on, nous, vous, ils, elles remplacent les noms et accompagnent le verbe conjugué.`"},{"t":"Les verbes être et avoir au présent","bs":[["ÊTRE",["`je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont.`"]],["AVOIR",["`j’ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont.`"]],["Exemples",["`Nous sommes en classe. Vous avez un livre. Elles sont contentes.`"]]],"k":"`ÊTRE : je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont.`"},{"t":"Le présent des verbes réguliers en -ER","bs":[["Pour parler d’une",["`Pour parler d’une action habituelle, on utilise souvent le présent.`"]],["Parler",["`je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent.`"]],["Les terminaisons habituelles",["`Les terminaisons habituelles sont : -e, -es, -e, -ons, -ez, -ent.`"]],["Exemples",["`J’écoute le professeur. Nous aimons la lecture.`"]]],"k":"`Pour parler d’une action habituelle, on utilise souvent le présent.`"},{"t":"Le nom, le déterminant et l’adjectif","bs":[["Le nom désigne",["`Le nom désigne une personne, un animal, un lieu ou une chose : élève, chat, école, cahier.`"]],["Le déterminant accompagne",["`Le déterminant accompagne le nom : un, une, le, la, les, des, mon, ma, mes.`"]],["L’adjectif donne une",["`L’adjectif donne une précision sur le nom : un petit jardin, une maison propre.`"]],["L’adjectif s’accorde …",["`L’adjectif s’accorde généralement en genre et en nombre avec le nom : un garçon gentil, une fille gentille.`"]]],"k":"`Le nom désigne une personne, un animal, un lieu ou une chose : élève, chat, école, cahier.`"},{"t":"Masculin, féminin, singulier et pluriel","bs":[["Souvent, on forme",["`Souvent, on forme le féminin en ajoutant -e : petit/petite, grand/grande. Il existe des exceptions.`"]],["Souvent, on forme",["`Souvent, on forme le pluriel en ajoutant -s : un livre/des livres. Les mots en -eau prennent souvent -x : un bateau/des bateaux.`"]],["Exemples",["`un élève sérieux / une élève sérieuse ; un cahier bleu / des cahiers bleus.`"]]],"k":"`Souvent, on forme le féminin en ajoutant -e : petit/petite, grand/grande. Il existe des exceptions.`"},{"t":"La phrase déclarative, interrogative et impérative","bs":[["La phrase déclarative",["`La phrase déclarative donne une information : J’aime le français.`"]],["La phrase interrogative",["`La phrase interrogative pose une question : Où habites-tu ?`"]],["La phrase impérative",["`La phrase impérative donne un ordre ou un conseil : Écoute bien !`"]],["Une phrase commence",["`Une phrase commence par une majuscule et se termine par un signe de ponctuation.`"]]],"k":"`La phrase déclarative donne une information : J’aime le français.`"},{"t":"Comprendre un texte court","bs":[["Lis le texte",["`Lis le texte une première fois pour comprendre le sujet général.`"]],["Souligne les mots",["`Souligne les mots importants : personnes, lieux, temps et actions.`"]],["Réponds avec une",["`Réponds avec une phrase complète lorsque la question le demande.`"]],["Exemple",["`« Nadia habite à Oran. Elle va au collège à pied. » Où habite Nadia ? — Elle habite à Oran.`"]]],"k":"`Lis le texte une première fois pour comprendre le sujet général.`"},{"t":"Production écrite : ma journée scolaire","bs":[["Méthode",["`Organise le texte en début, déroulement et fin.`","`Utilise des connecteurs simples : d’abord, ensuite, puis, enfin.`","`Vérifie les majuscules, les points, les accords et les verbes.`"]],["Modèle",["`Je me réveille à sept heures. D’abord, je prends mon petit-déjeuner et je prépare mon cartable. Ensuite, je vais au collège. En classe, j’écoute les professeurs et je …`"]]],"k":"`Organise le texte en début, déroulement et fin.`"},{"t":"Projet 1 · Vocabulaire : La nominalisation","bs":[["À retenir",["`On forme des noms d'action à partir de verbes en ajoutant un suffixe au radical : -age, -ement, -tion, -ation.`","`Verbes en -er : radical + -age ou -ment (laver → lavage ; entraîner → entraînement). Verbes en -er aussi : -ation (vacciner → vaccination).`"]],["Exemples",["`laver → lavage`","`nettoyer → nettoyage`","`brosser → brossage`","`arroser → arrosage`"]]],"k":"`On forme des noms d'action à partir de verbes en ajoutant un suffixe au radical : -age, -ement, -tion, -ation.`"},{"t":"Projet 1 · Grammaire : La phrase déclarative (forme affirmative et négative)","bs":[["À retenir",["`La phrase déclarative sert à déclarer quelque chose, raconter un événement ou donner son avis. Elle commence par une majuscule et se termine par un point.`","`Forme affirmative : on affirme ou on exprime son accord. Forme négative : on nie ou on exprime son désaccord.`","`Pour passer à la forme négative, on encadre le verbe : ne … pas, ne … plus, ne … jamais, ne … rien, ne … personne. Devant une voyelle : n'.`"]],["Exemples",["`J'aime les sucreries. → Je n'aime pas les sucreries.`","`Je n'aime plus les sodas.`","`Je n'ai jamais aimé les frites.`","`Je n'aime rien à part les fruits.`"]]],"k":"`La phrase déclarative sert à déclarer quelque chose, raconter un événement ou donner son avis. Elle commence par une majuscule et se termine par un point.`"},{"t":"Projet 1 · Grammaire : Les substituts grammaticaux","bs":[["À retenir",["`Pour éviter les répétitions, on remplace un nom ou un groupe nominal par un substitut grammatical : pronom personnel (il, elle, le, la, les, lui…), pronom possessif (le …`"]],["Exemples",["`Rends visite à ta grand-mère, elle est malade.`","`Mes gants sont rouges, ceux de ma sœur sont jaunes.`","`Prête-moi ta serviette, j'ai oublié la mienne.`"]]],"k":"`Pour éviter les répétitions, on remplace un nom ou un groupe nominal par un substitut grammatical : pronom personnel (il, elle, le, la, les, lui…), pronom possessif (le mien, la tienne, les leurs…), …`"},{"t":"Projet 1 · Conjugaison : Les verbes du 1er groupe au présent de l'indicatif","bs":[["À retenir",["`Les verbes du 1er groupe se terminent par -er à l'infinitif (sauf aller, qui est du 3e groupe).`","`Terminaisons au présent : -e, -es, -e, -ons, -ez, -ent. Radical = infinitif sans -er.`","`Particularités : manger → nous mangeons ; commencer → nous commençons ; nettoyer → je nettoie ; appeler → j'appelle.`"]],["Exemples",["`constituer : je constitue, tu constitues, il/elle constitue, nous constituons, vous constituez, ils/elles constituent`","`se brosser : je me brosse, tu te brosses, il se brosse, nous nous brossons, vous vous brossez, ils se brossent`"]]],"k":"`Les verbes du 1er groupe se terminent par -er à l'infinitif (sauf aller, qui est du 3e groupe).`"},{"t":"Projet 1 · Orthographe : L'accord du verbe avec le sujet","bs":[["À retenir",["`Le verbe s'accorde toujours en personne et en nombre avec son sujet.`","`Si le sujet est composé (Fatiha et toi), le verbe se met au pluriel. Moi + un autre = nous ; toi + un autre = vous.`","`Plusieurs verbes pour un seul sujet : chaque verbe s'accorde avec ce sujet.`"]],["Exemples",["`Le médecin accueille son patient, l'ausculte puis lui prescrit un traitement.`","`Mon frère et moi aimons les revues scientifiques.`"]]],"k":"`Le verbe s'accorde toujours en personne et en nombre avec son sujet.`"},{"t":"Projet 1 · Vocabulaire : Les synonymes et les périphrases","bs":[["À retenir",["`Les synonymes sont des mots de sens proche qui appartiennent à la même classe grammaticale (manger / se nourrir).`","`Une périphrase est un groupe de mots qui remplace un mot (le Roi des animaux = le lion).`"]],["Exemples",["`bon / délicieux`","`boire / se désaltérer`","`le lait = le liquide blanc produit par la vache`"]]],"k":"`Les synonymes sont des mots de sens proche qui appartiennent à la même classe grammaticale (manger / se nourrir).`"},{"t":"Projet 1 · Vocabulaire : Les connecteurs d'énumération","bs":[["À retenir",["`Ils organisent un texte explicatif ou prescriptif : d'abord / premièrement, ensuite / puis / deuxièmement, enfin / pour finir / en dernier lieu.`","`Avant une énumération, on met souvent deux-points ; les éléments sont séparés par des virgules ou des points-virgules.`"]],["Exemples",["`D'abord, je mouille mes mains. Ensuite, je les savonne. Enfin, je les rince.`"]]],"k":"`Ils organisent un texte explicatif ou prescriptif : d'abord / premièrement, ensuite / puis / deuxièmement, enfin / pour finir / en dernier lieu.`"},{"t":"Projet 1 · Grammaire : L'expansion du groupe nominal : l'adjectif qualificatif et le complément du nom","bs":[["À retenir",["`Le groupe nominal (GN) = déterminant + nom. On peut l'enrichir : adjectif qualificatif (une brosse électrique), complément du nom introduit par de, à, en… (une brosse à …`","`Les adjectifs qualificatifs s'accordent en genre et en nombre avec le nom.`"]],["Exemples",["`une salle de bain moderne`","`des gants de toilette rouges`"]]],"k":"`Le groupe nominal (GN) = déterminant + nom. On peut l'enrichir : adjectif qualificatif (une brosse électrique), complément du nom introduit par de, à, en… (une brosse à dents, un gant de toilette).`"},{"t":"Projet 1 · Conjugaison : Les verbes du 2e et du 3e groupe au présent de l'indicatif","bs":[["À retenir",["`2e groupe : infinitif en -ir, participe présent en -issant (finir → finissant). Terminaisons : -is, -is, -it, -issons, -issez, -issent.`","`3e groupe : tous les autres verbes (aller, venir, prendre, faire, dire, voir, pouvoir, vouloir, savoir…). Terminaisons variables : -s, -s, -t, -ons, -ez, -ent (ou -x, …`"]],["Exemples",["`finir : je finis, tu finis, il finit, nous finissons, vous finissez, ils finissent`","`prendre : je prends, tu prends, il prend, nous prenons, vous prenez, ils prennent`","`aller : je vais, tu vas, il va, nous allons, vous allez, ils vont`"]]],"k":"`2e groupe : infinitif en -ir, participe présent en -issant (finir → finissant). Terminaisons : -is, -is, -it, -issons, -issez, -issent.`"},{"t":"Projet 1 · Orthographe : L'accord de l'adjectif qualificatif","bs":[["À retenir",["`L'adjectif s'accorde avec le nom qu'il qualifie. Féminin : +e (grand → grande). Pluriel : +s (grands). Cas particuliers : -eux → -euse ; -er → -ère ; -if → -ive ; -al → …`"]],["Exemples",["`un repas équilibré, une alimentation équilibrée, des repas équilibrés`","`un geste simple → des gestes simples`"]]],"k":"`L'adjectif s'accorde avec le nom qu'il qualifie. Féminin : +e (grand → grande). Pluriel : +s (grands). Cas particuliers : -eux → -euse ; -er → -ère ; -if → -ive ; -al → -aux au pluriel masculin.`"},{"t":"Projet 1 · Orthographe : Les signes de ponctuation : le point, la virgule, deux-points","bs":[["À retenir",["`Le point (.) termine une phrase. La virgule (,) sépare les éléments d'une énumération. Les deux-points (:) introduisent une énumération, une explication ou une …`"]],["Exemples",["`Pour rester en forme, il faut : manger équilibré, bouger et dormir.`"]]],"k":"`Le point (.) termine une phrase. La virgule (,) sépare les éléments d'une énumération. Les deux-points (:) introduisent une énumération, une explication ou une définition. Le point-virgule (;) sépare …`"},{"t":"Projet 2 · Vocabulaire : La reformulation par « c'est-à-dire » et « autrement dit »","bs":[["À retenir",["`Reformuler, c'est redire autrement pour expliquer. On utilise : c'est-à-dire, autrement dit, en d'autres termes.`"]],["Exemples",["`Le TGV est un train à grande vitesse, c'est-à-dire un train très rapide.`","`La pollution, autrement dit la dégradation de l'environnement, menace la santé.`"]]],"k":"`Reformuler, c'est redire autrement pour expliquer. On utilise : c'est-à-dire, autrement dit, en d'autres termes.`"},{"t":"Projet 2 · Grammaire : L'expression de la cause","bs":[["À retenir",["`La cause répond à la question « pourquoi ? ». Elle s'exprime avec : parce que, car, puisque, comme, en effet, à cause de (cause négative), grâce à (cause positive).`"]],["Exemples",["`Il est en retard parce qu'il a raté le bus.`","`Grâce aux robots, le travail est plus rapide.`"]]],"k":"`La cause répond à la question « pourquoi ? ». Elle s'exprime avec : parce que, car, puisque, comme, en effet, à cause de (cause négative), grâce à (cause positive).`"},{"t":"Projet 2 · Grammaire : L'expression de la conséquence","bs":[["À retenir",["`La conséquence répond à « avec quel résultat ? ». Mots : donc, alors, c'est pourquoi, si bien que, de sorte que, tellement… que, si… que.`"]],["Exemples",["`Il pleut, donc je reste à la maison.`","`Il y a tant de pollution que l'air est irrespirable.`"]]],"k":"`La conséquence répond à « avec quel résultat ? ». Mots : donc, alors, c'est pourquoi, si bien que, de sorte que, tellement… que, si… que.`"},{"t":"Projet 2 · Grammaire : L'expression du but","bs":[["À retenir",["`Le but répond à « dans quel but ? ». Mots : pour, afin de (+ infinitif), pour que, afin que (+ subjonctif).`"]],["Exemples",["`Je trie mes déchets pour protéger la planète.`","`On recycle afin que la nature soit préservée.`"]]],"k":"`Le but répond à « dans quel but ? ». Mots : pour, afin de (+ infinitif), pour que, afin que (+ subjonctif).`"},{"t":"Projet 2 · Conjugaison : Le passé composé (1er, 2e et 3e groupe)","bs":[["À retenir",["`Passé composé = auxiliaire (avoir ou être au présent) + participe passé.`","`Participes passés : 1er groupe -é (parler → parlé) ; 2e groupe -i (finir → fini) ; 3e groupe variables : -u (voir → vu), -is (prendre → pris), -it (dire → dit), -ert …`","`Auxiliaire être : verbes de mouvement (aller, venir, partir, arriver, entrer, sortir, monter, descendre, naître, mourir, tomber, rester) et verbes pronominaux.`"]],["Exemples",["`J'ai mangé. Tu as fini. Il a pris. Nous sommes allés. Elles se sont lavées.`"]]],"k":"`Passé composé = auxiliaire (avoir ou être au présent) + participe passé.`"},{"t":"Projet 2 · Orthographe : L'accord du participe passé avec « être » et avec « avoir »","bs":[["À retenir",["`Avec être : le participe passé s'accorde avec le sujet (Elle est partie. Ils sont partis).`","`Avec avoir : il ne s'accorde pas avec le sujet. Il s'accorde avec le COD seulement si le COD est placé avant le verbe (Les fleurs que j'ai cueillies).`"]],["Exemples",["`Les élèves sont arrivés. Elle a mangé des pommes. Les pommes qu'elle a mangées.`"]]],"k":"`Avec être : le participe passé s'accorde avec le sujet (Elle est partie. Ils sont partis).`"},{"t":"Projet 2 · Vocabulaire : Les synonymes et les antonymes","bs":[["À retenir",["`Synonymes : mots de sens proche (rapide / vite). Antonymes : mots de sens contraire (grand ≠ petit, chaud ≠ froid, lent ≠ rapide). On forme aussi des antonymes avec des …`"]],["Exemples",["`propre ≠ sale`","`pollué ≠ propre`","`construire ≠ détruire`"]]],"k":"`Synonymes : mots de sens proche (rapide / vite). Antonymes : mots de sens contraire (grand ≠ petit, chaud ≠ froid, lent ≠ rapide). On forme aussi des antonymes avec des préfixes : in-, im-, dé-, mal- …`"},{"t":"Projet 3 · Grammaire : La phrase impérative","bs":[["À retenir",["`La phrase impérative sert à donner un ordre, un conseil, une consigne ou une interdiction. Elle se termine par un point ou un point d'exclamation.`","`Le verbe est à l'impératif, sans sujet exprimé.`"]],["Exemples",["`Ferme le robinet ! Éteignez la lumière. Ne jetez pas vos déchets par terre.`"]]],"k":"`La phrase impérative sert à donner un ordre, un conseil, une consigne ou une interdiction. Elle se termine par un point ou un point d'exclamation.`"},{"t":"Projet 3 · Conjugaison : L'impératif présent pour exprimer une consigne","bs":[["À retenir",["`L'impératif a trois personnes : 2e sing. (tu), 1re plur. (nous), 2e plur. (vous). Il s'emploie sans sujet.`","`1er groupe : pas de -s à la 2e personne du singulier (Parle ! Ferme !). Sauf devant y et en : Vas-y ! Manges-en !`","`Avoir : aie, ayons, ayez. Être : sois, soyons, soyez. Aller : va, allons, allez.`"]],["Exemples",["`Économise l'eau. Économisons l'énergie. Économisez le papier.`","`Sois attentif ! Ayez du courage.`"]]],"k":"`L'impératif a trois personnes : 2e sing. (tu), 1re plur. (nous), 2e plur. (vous). Il s'emploie sans sujet.`"},{"t":"Projet 3 · Orthographe : Les adverbes en -ment","bs":[["À retenir",["`On forme les adverbes en -ment à partir de l'adjectif au féminin + -ment (lent → lentement ; doux → doucement).`","`Adjectifs en -ant → -amment (constant → constamment) ; en -ent → -emment (récent → récemment). Adjectifs en -i, -é, -u : +ment (vrai → vraiment, poli → poliment).`"]],["Exemples",["`Mange lentement. Il agit prudemment. Elle travaille sérieusement.`"]]],"k":"`On forme les adverbes en -ment à partir de l'adjectif au féminin + -ment (lent → lentement ; doux → doucement).`"},{"t":"Projet 3 · Conjugaison : Le mode infinitif, le mode subjonctif, le futur simple pour exprimer une consigne","bs":[["À retenir",["`L'infinitif exprime une consigne générale (Ne pas jeter.). Le subjonctif présent s'emploie après il faut que, pour que : Il faut que tu sois attentif.`","`Futur simple : radical + -rai, -ras, -ra, -rons, -rez, -ront (parler → je parlerai ; être → je serai ; avoir → j'aurai ; aller → j'irai ; faire → je ferai).`"]],["Exemples",["`Ne pas jeter les papiers par terre.`","`Il faut que tu éteignes la lumière.`","`Tu trieras tes déchets.`"]]],"k":"`L'infinitif exprime une consigne générale (Ne pas jeter.). Le subjonctif présent s'emploie après il faut que, pour que : Il faut que tu sois attentif.`"},{"t":"Projet 3 · Grammaire : La tournure impersonnelle avec le verbe « falloir »","bs":[["À retenir",["`Il faut + infinitif ou il faut que + subjonctif exprime une obligation, une nécessité. Le verbe falloir ne s'emploie qu'à la 3e personne du singulier avec le sujet …`"]],["Exemples",["`Il faut économiser l'eau. Il faut que nous protégions la nature.`"]]],"k":"`Il faut + infinitif ou il faut que + subjonctif exprime une obligation, une nécessité. Le verbe falloir ne s'emploie qu'à la 3e personne du singulier avec le sujet impersonnel « il » (il fallait, il …`"},{"t":"Projet 3 · Orthographe : Les homophones grammaticaux : a/à, et/est, ce/se, ces/ses","bs":[["À retenir",["`a = verbe avoir (peut se mettre à « avait »). à = préposition.`","`et = conjonction (on peut dire « et puis »). est = verbe être (on peut dire « était »).`","`ce = déterminant/pronom démonstratif (ce jardin). se = pronom réfléchi devant un verbe (il se lave).`","`ces = déterminant démonstratif pluriel (ces fleurs). ses = déterminant possessif (ses fleurs = les fleurs de lui/elle).`"]],["Exemples",["`Il a un vélo. Il va à l'école.`","`Elle est gentille et drôle.`","`Ce garçon se lave les mains.`","`Ces enfants aiment leurs jeux ; ses amis aussi.`"]]],"k":"`a = verbe avoir (peut se mettre à « avait »). à = préposition.`"},{"t":"Projet 3 · Vocabulaire : La famille de mots","bs":[["À retenir",["`Une famille de mots regroupe des mots formés à partir d'un même radical : terre, terrain, terrasse, enterrer, déterrer, souterrain.`","`On les forme avec des préfixes (avant le radical) et des suffixes (après).`"]],["Exemples",["`eau : aquatique, arroser, eau-de-vie… (selon radical) ; propre : propreté, nettoyer… ; vert : verdure, verdir, reverdir`"]]],"k":"`Une famille de mots regroupe des mots formés à partir d'un même radical : terre, terrain, terrasse, enterrer, déterrer, souterrain.`"},{"t":"Projet 3 · Vocabulaire : La consigne et l'interdiction","bs":[["À retenir",["`La consigne indique ce qu'il faut faire (impératif, infinitif, il faut). L'interdiction indique ce qu'il ne faut pas faire (ne pas + infinitif, défense de, interdit de, …`"]],["Exemples",["`Interdit de fumer. Défense de jeter des papiers. Ne pas marcher sur la pelouse.`"]]],"k":"`La consigne indique ce qu'il faut faire (impératif, infinitif, il faut). L'interdiction indique ce qu'il ne faut pas faire (ne pas + infinitif, défense de, interdit de, ne … pas à l'impératif).`"}]},"en":{"name":"الإنجليزية","c":"#2e7d32","i":"🔤","L":[{"t":"Greetings and introductions — التحية والتعارف","bs":[["Useful expressions",["Hello! / Hi! = مرحبا","Good morning. = صباح الخير","Good afternoon. = مساء الخير (بعد الظهر)","Good evening. = مساء الخير"]],["أمثلة",["Example"]]],"k":"Hello! / Hi! = مرحبا"},{"t":"Personal pronouns and the verb BE — الضمائر والفعل to be","bs":[["الضمائر والفعل BE (يكون)",["I am = أنا","We are = نحن","You are = أنت/أنتم","They are = هم"]],["أمثلة",["Examples"]]],"k":"I am = أنا"},{"t":"The verb HAVE GOT — الفعل have got","bs":[["للتعبير عن الملكية (يملك / …",["`I / you / we / they + have got: I have got a book.`","`He / she / it + has got: She has got a blue bag.`","النفي: `haven't got / hasn't got: He hasn't got a ruler.`","السؤال: `Have you got a pen? — Yes, I have. / No, I haven't. Has she got a bag? — Yes, she has. / No, she hasn't.`"]],["أمثلة",["Examples"]]],"k":"`I / you / we / they + have got: I have got a book.`"},{"t":"Articles, plural and classroom objects — أدوات التنكير والجمع","bs":[["أدوات التنكير",["a قبل صوت ساكن غالبا: a pen, a book, a ruler.","`an قبل صوت متحرك (a, e, i, o, u): an apple, an egg, an orange.`"]],["الجمع",["غالبا نضيف s: `pen → pens, book → books.`","بعد s, x, ch, sh نضيف es: `box → boxes, class → classes.`","جموع شاذة: `child → children, man → men, woman → women. Classroom objects: board (سبورة), desk (طاولة), chair (كرسي), bag (حقيبة), pencil (قلم رصاص), eraser (ممحاة).`"]]],"k":"a قبل صوت ساكن غالبا: a pen, a book, a ruler."},{"t":"Adjectives and colours — الصفات والألوان","bs":[["الصفة تأتي قبل",["الصفة تأتي قبل الاسم في الإنجليزية وهي لا تتغير بالجمع:"]],["a red bag",["a red bag · two red bags · a small house. الألوان: red (أحمر), blue (أزرق), green (أخضر), yellow (أصفر), black (أسود), white (أبيض), orange (برتقالي), brown (بني). صفات …"]],["I have got",["`I have got a blue pen.`"]],["She has a",["`She has a big green bag.`"]],["أمثلة",["Examples"]]],"k":"الصفة تأتي قبل الاسم في الإنجليزية وهي لا تتغير بالجمع:"},{"t":"There is / There are and prepositions — يوجد وحروف الجر","bs":[["Grammar",["`There is + مفرد: There is a board in the classroom.`","`There are + جمع: There are twenty pupils in the class.`","النفي: `There isn't a window. · There aren't any chairs.`","السؤال: `Is there a clock? — Yes, there is. / Are there any books? — No, there aren't.`"]],["حروف الجر المكانية",["in = في","on = على (فوق سطح)","under = تحت","next to = بجانب"]],["أمثلة",["`Example: The book is on the desk. The bag is under the chair.`"]]],"k":"`There is + مفرد: There is a board in the classroom.`"},{"t":"Daily routine and simple present — الروتين اليومي والمضارع البسيط","bs":[["المضارع البسيط للعادات",["المضارع البسيط للعادات والحقائق."]],["I / you",["`I / you / we / they + الفعل: I get up at seven.`"]],["He / she / it + الفعل مع s",["`She plays football. · He reads a book.`"]],["go → goes,",["`go → goes, watch → watches (نضيف es بعد s, sh, ch, x, o).`"]],["النفي",["`do not (don't) / does not (doesn't) + الفعل الأصلي: He doesn't play.`"]],["السؤال",["Do you play? / Does she play? Daily routine: get up (يستيقظ), have breakfast (يتناول الفطور), go to school (يذهب للمدرسة), do homework (يؤدي الواجب), go to bed (ينام). …"]]],"k":"المضارع البسيط للعادات والحقائق."},{"t":"Writing a short paragraph — كتابة فقرة قصيرة","bs":[["خطوات كتابة فقرة",["خطوات كتابة فقرة تعريف بالنفس 1) ابدئي بالاسم والعمر: My name is Sami."]],["I am eleven.",["`I am eleven.`"]],["2) أضيفي المكان",["`I live in Algiers.`"]],["I am from",["`I am from Algeria.`"]],["3) تحدثي عن",["3) تحدثي عن العائلة أو الهواية: I have got a sister."]],["I like football.",["`I like football.`"]]],"k":"خطوات كتابة فقرة تعريف بالنفس 1) ابدئي بالاسم والعمر: My name is Sami. I am eleven. 2) أضيفي المكان: I live in Algiers. I am from Algeria. 3) تحدثي عن العائلة أو الهواية: I have got a sister. I like …"}]},"hist":{"name":"التاريخ والجغرافيا","c":"#e65100","i":"🌍","L":[{"t":"ما التاريخ؟","bs":[["مفاهيم أساسية",["التاريخ دراسة ماضي الإنسان اعتمادا على الأدلة والمصادر.","من المصادر التاريخية: الوثائق المكتوبة، النقوش، الآثار، العملات، الروايات الشفوية والصور.","المؤرخ يجمع المعلومات ويفحصها ويقارن بينها قبل استخلاص النتائج."]],["الخط الزمني",["الخط الزمني طريقة لترتيب الأحداث حسب وقوعها من الأقدم إلى الأحدث.","القرن يساوي مئة سنة، والألفية تساوي ألف سنة.","عند قراءة خط زمني، انتبه إلى تاريخ البداية والنهاية ووحدة القياس."]]],"k":"التاريخ دراسة ماضي الإنسان اعتمادا على الأدلة والمصادر."},{"t":"ما قبل التاريخ والتاريخ","bs":[["يستعمل مصطلح ما",["يستعمل مصطلح ما قبل التاريخ للفترة السابقة لظهور الكتابة في منطقة معينة."]],["تساعد الأدوات الحجرية",["تساعد الأدوات الحجرية والعظام والرسوم والآثار على معرفة أنماط عيش الإنسان القديم."]],["تختلف بداية التاريخ",["تختلف بداية التاريخ المكتوب من منطقة إلى أخرى بسبب اختلاف زمن ظهور الكتابة."]]],"k":"يستعمل مصطلح ما قبل التاريخ للفترة السابقة لظهور الكتابة في منطقة معينة."},{"t":"مصادر دراسة تاريخ الجزائر","bs":[["كيف ندرس الماضي؟",["كيف ندرس الماضي؟"]],["تساعد الآثار والمواقع",["تساعد الآثار والمواقع القديمة واللقى والكتابات في التعرف إلى حياة السكان عبر العصور."]],["يجب تحديد مكان",["يجب تحديد مكان العثور على الأثر وزمنه المحتمل ومقارنته بمصادر أخرى."]],["لا يكفي أثر",["لا يكفي أثر واحد دائما لإثبات تفسير تاريخي؛ ينبغي الاستناد إلى أدلة متعددة."]]],"k":"كيف ندرس الماضي؟"},{"t":"مهارات الإجابة في التاريخ","bs":[["عرّف المصطلح تعريفا",["عرّف المصطلح تعريفا واضحا ومباشرا."]],["عند سؤال",["علّل، اذكر السبب ثم اربطه بالنتيجة."]],["عند دراسة وثيقة،",["عند دراسة وثيقة، حدّد طبيعتها وصاحبها أو مصدرها إن عُرف، وموضوعها، ثم استخرج المعلومات المطلوبة."]]],"k":"عرّف المصطلح تعريفا واضحا ومباشرا."},{"t":"ما الجغرافيا؟","bs":[["الجغرافيا دراسة الظواهر",["الجغرافيا دراسة الظواهر الطبيعية والبشرية وتوزعها في المجال والعلاقات بينها."]],["الجغرافيا الطبيعية تدرس",["الجغرافيا الطبيعية تدرس التضاريس والمناخ والمياه والغطاء النباتي."]],["الجغرافيا البشرية تدرس",["الجغرافيا البشرية تدرس السكان والأنشطة الاقتصادية والعمران والتنقل."]]],"k":"الجغرافيا دراسة الظواهر الطبيعية والبشرية وتوزعها في المجال والعلاقات بينها."},{"t":"الخريطة وعناصرها","bs":[["العنوان يبين موضوع",["العنوان يبين موضوع الخريطة ومجالها."]],["المفتاح يفسر الرموز",["المفتاح يفسر الرموز والألوان المستخدمة."]],["المقياس يربط المسافة",["المقياس يربط المسافة على الخريطة بالمسافة الحقيقية."]],["الاتجاهات تساعد على",["الاتجاهات تساعد على تحديد المواقع؛ وغالبا يشير أعلى الخريطة إلى الشمال ما لم يوضح خلاف ذلك."]],["الإحداثيات أو أسماء",["الإحداثيات أو أسماء الأماكن تساعد على تحديد الموقع بدقة."]]],"k":"العنوان يبين موضوع الخريطة ومجالها."},{"t":"الموقع والتضاريس والمناخ","bs":[["الموقع الفلكي يحدد",["الموقع الفلكي يحدد بالإحداثيات، أما الموقع الجغرافي فيصف مكان المنطقة بالنسبة إلى ما يحيط بها."]],["من أشكال التضاريس",["الجبال والهضاب والسهول والأحواض."]],["الطقس حالة الجو",["الطقس حالة الجو خلال مدة قصيرة، أما المناخ فهو خصائص الجو المعتادة خلال مدة طويلة."]],["تؤثر التضاريس والارتفاع",["تؤثر التضاريس والارتفاع والقرب من البحر في خصائص المناخ وتوزيع السكان والأنشطة."]]],"k":"الموقع الفلكي يحدد بالإحداثيات، أما الموقع الجغرافي فيصف مكان المنطقة بالنسبة إلى ما يحيط بها."},{"t":"السكان والأنشطة","bs":[["يتوزع السكان بشكل",["يتوزع السكان بشكل غير متساو بسبب عوامل طبيعية واقتصادية وتاريخية."]],["تجذب بعض المناطق",["تجذب بعض المناطق السكان بسبب فرص العمل والمياه والخدمات وسهولة النقل."]],["من الأنشطة الاقتصادية",["الزراعة والصناعة والخدمات والتجارة."]],["تساعد الخرائط والرسوم",["تساعد الخرائط والرسوم البيانية والجداول في وصف التوزع والمقارنة بين المناطق."]]],"k":"يتوزع السكان بشكل غير متساو بسبب عوامل طبيعية واقتصادية وتاريخية."},{"t":"منهجية الإجابة في الجغرافيا","bs":[["اقرأ عنوان الوثيقة",["اقرأ عنوان الوثيقة ومفتاحها ومقياسها قبل تفسيرها."]],["استخرج معلومة محددة",["استخرج معلومة محددة من الخريطة أو الجدول، ثم فسّرها بعامل مناسب إذا طُلب منك ذلك."]],["عند المقارنة، اذكر",["عند المقارنة، اذكر أوجه التشابه والاختلاف بوضوح ولا تكتف بعبارة عامة."]]],"k":"اقرأ عنوان الوثيقة ومفتاحها ومقياسها قبل تفسيرها."}]},"islam":{"name":"التربية الإسلامية","c":"#2e7d32","i":"🕌","L":[{"t":"القرآن الكريم وأدب التلاوة","bs":[["القرآن الكريم كلام",["القرآن الكريم كلام الله تعالى، وتلاوته عبادة."]],["من آداب التلاوة",["الإخلاص، الإنصات، احترام المصحف، والتدبر في المعاني."]],["عند حفظ سورة",["عند حفظ سورة مقررة، تُراجع من المصحف المدرسي وتُضبط ألفاظها كما وردت دون الاعتماد على الملخص وحده."]]],"k":"القرآن الكريم كلام الله تعالى، وتلاوته عبادة."},{"t":"الإيمان بالله تعالى","bs":[["الإيمان بالله هو",["الإيمان بالله هو التصديق بوجود الله تعالى وربوبيته وألوهيته وأسمائه وصفاته كما يليق به."]],["من آثار الإيمان",["مراقبة الله، الصدق، الأمانة، شكر النعم، والابتعاد عن الظلم."]],["تظهر العقيدة الصحيحة",["تظهر العقيدة الصحيحة في السلوك والعمل، لا في الكلام فقط."]]],"k":"الإيمان بالله هو التصديق بوجود الله تعالى وربوبيته وألوهيته وأسمائه وصفاته كما يليق به."},{"t":"أركان الإيمان","bs":[["الإيمان بالله، وملائكته،",["الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره."]],["الإيمان بالملائكة تصديق",["الإيمان بالملائكة تصديق بوجودهم وأنهم عباد مكرمون لا يعصون الله فيما أمرهم."]],["الإيمان بالرسل يقتضي",["الإيمان بالرسل يقتضي تصديقهم واحترامهم والإيمان بما أرسلوا به."]]],"k":"الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره."},{"t":"الطهارة والوضوء","bs":[["الطهارة تشمل رفع",["الطهارة تشمل رفع الحدث وإزالة النجاسة بحسب أحكامها."]],["من فرائض الوضوء",["من فرائض الوضوء في الفقه المالكي المتداول في الجزائر: النية، غسل الوجه، غسل اليدين إلى المرفقين، مسح الرأس، غسل الرجلين إلى الكعبين، والدلك والفور مع مراعاة التفصيل …"]],["يُستحسن الرجوع إلى",["يُستحسن الرجوع إلى شرح الأستاذ والكتاب المدرسي عند حفظ الفرائض والسنن ونواقض الوضوء، لأن تفاصيل التصنيف قد تختلف بين المذاهب."]]],"k":"الطهارة تشمل رفع الحدث وإزالة النجاسة بحسب أحكامها."},{"t":"الصلاة وأهميتها","bs":[["الصلاة ركن من",["الصلاة ركن من أركان الإسلام، وهي صلة بين العبد وربه."]],["يحافظ المسلم على",["يحافظ المسلم على أوقاتها وشروطها وأركانها ويتعلم أحكامها بالتدرج."]],["من آثار الصلاة",["تهذيب السلوك، تنظيم الوقت، وتعويد المسلم على الطاعة."]]],"k":"الصلاة ركن من أركان الإسلام، وهي صلة بين العبد وربه."},{"t":"الأخلاق الإسلامية","bs":[["الصدق مطابقة القول",["الصدق مطابقة القول للواقع، وهو سبب للثقة بين الناس."]],["الأمانة أداء الحقوق",["الأمانة أداء الحقوق وحفظ ما اؤتمن عليه الإنسان."]],["التعاون يكون على",["التعاون يكون على الخير والمصلحة، واحترام الآخرين من حسن الخلق."]],["تطبيق",["إذا وجدت غرضا ليس لك، فابحث عن صاحبه أو سلّمه للمسؤول بدل الاحتفاظ به."]]],"k":"الصدق مطابقة القول للواقع، وهو سبب للثقة بين الناس."},{"t":"بر الوالدين واحترام الآخرين","bs":[["بر الوالدين يكون",["بر الوالدين يكون بالكلام الطيب والطاعة في المعروف ومساعدتهما."]],["يُحترم المعلم والجيران",["يُحترم المعلم والجيران والزملاء، ويُبتعد عن السخرية والغيبة والإيذاء."]],["لا طاعة لمخلوق",["لا طاعة لمخلوق في معصية الخالق، ويكون الاختلاف بأدب وحكمة."]]],"k":"بر الوالدين يكون بالكلام الطيب والطاعة في المعروف ومساعدتهما."},{"t":"السيرة النبوية والاقتداء","bs":[["نتعلم من سيرة",["نتعلم من سيرة النبي محمد صلى الله عليه وسلم الصدق والرحمة والصبر والوفاء بالعهد."]],["الاقتداء بالسيرة يكون",["الاقتداء بالسيرة يكون بتطبيق الأخلاق في البيت والمدرسة والمجتمع."]],["عند مراجعة حدث",["عند مراجعة حدث تاريخي محدد، احفظ أسباب الحدث ووقائعه ونتائجه كما وردت في الكتاب المدرسي."]]],"k":"نتعلم من سيرة النبي محمد صلى الله عليه وسلم الصدق والرحمة والصبر والوفاء بالعهد."},{"t":"العبادة والمسؤولية","bs":[["العبادة تشمل أعمالا",["العبادة تشمل أعمالا ظاهرة وأعمالا قلبية، وتنعكس على سلوك المسلم."]],["المسؤولية تعني أداء",["المسؤولية تعني أداء الواجبات وتحمل نتائج التصرفات."]],["من أمثلة المسؤولية",["المحافظة على أدوات المدرسة، الصدق في الواجب، ومساعدة المحتاج بما تستطيع."]]],"k":"العبادة تشمل أعمالا ظاهرة وأعمالا قلبية، وتنعكس على سلوك المسلم."}]},"civic":{"name":"التربية المدنية","c":"#1565c0","i":"🏛️","L":[{"t":"الفرد والجماعة","bs":[["الفرد شخص له",["الفرد شخص له حقوق وعليه واجبات، ويعيش ضمن جماعات مثل الأسرة والمدرسة والمجتمع."]],["تقوم الحياة الجماعية",["تقوم الحياة الجماعية على التعاون والاحترام وتحمل المسؤولية."]],["احترام الاختلاف في",["احترام الاختلاف في الآراء والقدرات يساعد على التعايش ويقلل النزاعات."]]],"k":"الفرد شخص له حقوق وعليه واجبات، ويعيش ضمن جماعات مثل الأسرة والمدرسة والمجتمع."},{"t":"الأسرة ودورها","bs":[["توفر الأسرة الرعاية",["توفر الأسرة الرعاية والتربية والتوجيه والحماية لأفرادها."]],["من واجبات الأبناء",["من واجبات الأبناء احترام الوالدين، المساعدة حسب الاستطاعة، والمحافظة على الحوار الهادئ."]],["تُحل الخلافات الأسرية",["تُحل الخلافات الأسرية بالحوار والتفاهم وطلب المساعدة من شخص موثوق عند الحاجة."]]],"k":"توفر الأسرة الرعاية والتربية والتوجيه والحماية لأفرادها."},{"t":"المدرسة والحياة المدرسية","bs":[["من حقوق التلميذ",["من حقوق التلميذ التعلم في بيئة آمنة واحترام كرامته."]],["من واجباته احترام",["من واجباته احترام المعلمين والزملاء، المحافظة على الممتلكات، الالتزام بالنظام الداخلي، وإنجاز العمل المدرسي."]],["الممتلكات العامة مثل",["الممتلكات العامة مثل الطاولات والكتب والأدوات المشتركة مسؤولية الجميع."]]],"k":"من حقوق التلميذ التعلم في بيئة آمنة واحترام كرامته."},{"t":"الحقوق والواجبات","bs":[["كيف نميز بينهما؟",["كيف نميز بينهما؟"]],["الحق منفعة أو",["الحق منفعة أو حماية يقرها القانون أو القواعد المنظمة للمجتمع."]],["الواجب مسؤولية ينبغي",["الواجب مسؤولية ينبغي أداؤها تجاه النفس والآخرين والمجتمع."]],["الحقوق والواجبات متكاملة،",["الحقوق والواجبات متكاملة، ولا يبرر حق الفرد الاعتداء على حقوق غيره."]],["مثال",["للتلميذ حق التعلم، وعليه واجب احترام النظام المدرسي وعدم تعطيل تعلم الآخرين."]]],"k":"كيف نميز بينهما؟"},{"t":"الحوار وحل النزاعات","bs":[["الاستماع دون مقاطعة،",["الاستماع دون مقاطعة، وشرح المشكلة بهدوء، واحترام الطرف الآخر."]],["البحث عن حل",["البحث عن حل عادل ومقبول وتجنب السب والعنف."]],["إذا تعذر الحل،",["إذا تعذر الحل، يمكن اللجوء إلى المعلم أو الإدارة أو شخص بالغ موثوق."]]],"k":"الاستماع دون مقاطعة، وشرح المشكلة بهدوء، واحترام الطرف الآخر."},{"t":"المواطنة والمحافظة على الممتلكات العامة","bs":[["المواطنة مشاركة مسؤولة",["المواطنة مشاركة مسؤولة في الحياة الجماعية واحترام القواعد والحقوق."]],["من مظاهرها المحافظة",["من مظاهرها المحافظة على النظافة، احترام الإشارات والقوانين، حماية الممتلكات العامة، والمشاركة الإيجابية."]],["الممتلكات العامة ملك",["الممتلكات العامة ملك مشترك، وإتلافها يضر بالجميع."]]],"k":"المواطنة مشاركة مسؤولة في الحياة الجماعية واحترام القواعد والحقوق."},{"t":"قواعد العيش المشترك","bs":[["أمثلة",["أمثلة يومية"]],["احترام الدور في",["احترام الدور في الطابور، خفض الضوضاء في الأماكن العامة، وعدم نشر الشائعات أو الإساءة للآخرين."]],["التعاون لا يعني",["التعاون لا يعني القيام بكل شيء عن الآخرين، بل تقديم مساعدة مناسبة مع احترام كرامتهم."]],["المسؤولية تعني التفكير",["المسؤولية تعني التفكير في نتائج أفعالنا قبل القيام بها."]]],"k":"احترام الدور في الطابور، خفض الضوضاء في الأماكن العامة، وعدم نشر الشائعات أو الإساءة للآخرين."},{"t":"المؤسسات والقواعد المنظمة للحياة","bs":[["توجد مؤسسات وقواعد",["توجد مؤسسات وقواعد لتنظيم شؤون المجتمع وحماية الحقوق وحل الخلافات."]],["تُراجع أسماء المؤسسات",["تُراجع أسماء المؤسسات وصلاحياتها كما وردت في الكتاب المدرسي، لأن التفاصيل القانونية والإدارية قد تتغير."]],["القانون ينظم العلاقات",["القانون ينظم العلاقات بين الأفراد والمؤسسات، ويجب احترامه وعدم استبدال المعلومات المدرسية بتخمينات."]]],"k":"توجد مؤسسات وقواعد لتنظيم شؤون المجتمع وحماية الحقوق وحل الخلافات."}]},"sci":{"name":"علوم الطبيعة والحياة","c":"#388e3c","i":"🌱","L":[{"t":"منهجية دراسة الظواهر الطبيعية","bs":[["الملاحظة",["وصف ما نراه أو نقيسه دون تفسير مسبق."]],["طرح المشكلة",["صياغة سؤال واضح حول الظاهرة."]],["الفرضية",["تفسير مؤقت يمكن اختباره."]],["التجربة أو البحث",["جمع أدلة مناسبة مع احترام السلامة."]],["النتيجة",["قبول الفرضية أو تعديلها بناء على الأدلة."]]],"k":"الملاحظة: وصف ما نراه أو نقيسه دون تفسير مسبق."},{"t":"الوسط الحي ومكوناته","bs":[["الوسط الحي يضم",["الوسط الحي يضم كائنات حية وعناصر لا حية تتفاعل فيما بينها."]],["العناصر الحية",["نباتات، حيوانات، فطريات وكائنات دقيقة."]],["العناصر اللاحيوية",["الماء، الهواء، الضوء، التربة ودرجة الحرارة."]],["الموطن هو المكان",["الموطن هو المكان الذي يعيش فيه الكائن الحي وتتوفر فيه حاجاته."]]],"k":"الوسط الحي يضم كائنات حية وعناصر لا حية تتفاعل فيما بينها."},{"t":"حاجات الكائنات الحية","bs":[["تحتاج الحيوانات إلى",["تحتاج الحيوانات إلى الماء والغذاء والهواء وظروف مناسبة للعيش."]],["تحتاج النباتات الخضراء",["تحتاج النباتات الخضراء إلى الماء والأملاح المعدنية والضوء وثاني أكسيد الكربون لتنمو وتصنع مادتها العضوية."]],["تختلف حاجات الكائنات",["تختلف حاجات الكائنات بحسب نوعها ووسط عيشها."]],["تؤثر عوامل مثل",["تؤثر عوامل مثل الضوء والماء والحرارة في نمو الكائنات وتوزعها."]]],"k":"تحتاج الحيوانات إلى الماء والغذاء والهواء وظروف مناسبة للعيش."},{"t":"العلاقات الغذائية والسلاسل الغذائية","bs":[["توضح السلسلة الغذائية",["توضح السلسلة الغذائية انتقال المادة والطاقة من كائن إلى آخر."]],["مثال مبسط",["عشب ← أرنب ← ثعلب. يُقرأ السهم من الغذاء إلى الكائن الذي يتغذى عليه."]],["النبات الأخضر منتج،",["النبات الأخضر منتج، والحيوان مستهلك، وتقوم المحللات بتفكيك البقايا العضوية وإعادة المواد إلى الوسط."]],["اختفاء نوع من",["اختفاء نوع من السلسلة قد يؤثر في توازن الوسط."]]],"k":"توضح السلسلة الغذائية انتقال المادة والطاقة من كائن إلى آخر."},{"t":"التنفس عند الكائنات الحية – مدخل","bs":[["تحتاج كثير من",["تحتاج كثير من الكائنات الحية إلى الأكسجين في عملية التنفس الخلوي لتحرير الطاقة من الغذاء."]],["تختلف أعضاء تبادل الغازات",["الرئتان لدى الإنسان وكثير من الثدييات، والخياشيم لدى الأسماك، وقد تتبادل بعض الكائنات الغازات عبر سطح الجسم."]],["لا تخلط بين",["لا تخلط بين التنفس الخارجي (تبادل الغازات) والتنفس الخلوي الذي يحدث داخل الخلايا."]]],"k":"تحتاج كثير من الكائنات الحية إلى الأكسجين في عملية التنفس الخلوي لتحرير الطاقة من الغذاء."},{"t":"جسم الإنسان والصحة","bs":[["الغذاء المتوازن يوفر",["الغذاء المتوازن يوفر عناصر متنوعة يحتاجها الجسم للنمو والطاقة."]],["النظافة وغسل اليدين",["النظافة وغسل اليدين والماء النظيف والتهوية تساعد في الحد من انتقال بعض الأمراض."]],["النشاط البدني والنوم",["النشاط البدني والنوم الكافي والعادات الصحية تدعم النمو والتعلم."]],["في حال المرض",["في حال المرض أو الحاجة الطبية، تُطلب مساعدة ولي الأمر أو مختص صحي؛ هذا الملخص ليس تشخيصا طبيا."]]],"k":"الغذاء المتوازن يوفر عناصر متنوعة يحتاجها الجسم للنمو والطاقة."},{"t":"التكيف مع الوسط","bs":[["أمثلة",["أمثلة"]],["قد تساعد صفات",["قد تساعد صفات شكلية أو سلوكية الكائن الحي على البقاء في وسطه."]],["لدى بعض النباتات",["لدى بعض النباتات الصحراوية صفات تقلل فقد الماء، ولدى بعض الحيوانات ألوان أو سلوكيات تساعدها على التمويه أو تنظيم الحرارة."]],["التكيف لا يعني",["التكيف لا يعني أن الكائن يختار صفته بإرادته؛ بل إن الصفات الملائمة قد تساعد أفراد النوع على البقاء والتكاثر."]]],"k":"قد تساعد صفات شكلية أو سلوكية الكائن الحي على البقاء في وسطه."},{"t":"حماية البيئة والتوازن الطبيعي","bs":[["كيف نحمي الوسط؟",["كيف نحمي الوسط؟"]],["عدم رمي النفايات",["عدم رمي النفايات في الطبيعة أو مجاري المياه."]],["ترشيد استعمال الماء",["ترشيد استعمال الماء والطاقة وفرز النفايات حيث تتوفر الخدمة."]],["حماية النباتات والحيوانات",["حماية النباتات والحيوانات وعدم تخريب المواطن الطبيعية."]],["التوازن الطبيعي يتأثر",["التوازن الطبيعي يتأثر بالتلوث والإفراط في الصيد وتدمير المواطن، وتساعد الإجراءات الجماعية على الحد من هذه الأضرار."]]],"k":"كيف نحمي الوسط؟"}]},"phys":{"name":"الفيزياء والتكنولوجيا","c":"#c62828","i":"⚙️","L":[{"t":"قواعد العمل والأمن في المخبر","bs":[["لا تلمس الأجهزة",["لا تلمس الأجهزة أو المواد قبل سماع تعليمات الأستاذ."]],["لا تتذوق أي",["لا تتذوق أي مادة ولا تشمها مباشرة، ولا توجه أنبوب اختبار نحو الوجه."]],["استعمل الأدوات حسب",["استعمل الأدوات حسب وظيفتها، وأبلغ الأستاذ عن أي كسر أو انسكاب."]],["في النشاط التجريبي",["حدّد السؤال، اقترح فرضية، أنجز التجربة بأمان، سجّل الملاحظات، ثم استنتج."]]],"k":"لا تلمس الأجهزة أو المواد قبل سماع تعليمات الأستاذ."},{"t":"المادة وحالاتها الفيزيائية","bs":[["توجد المادة في حالات شائعة",["صلبة، سائلة، غازية."]],["الصلب يحتفظ عادة",["الصلب يحتفظ عادة بشكله وحجمه؛ السائل يحتفظ بحجمه ويأخذ شكل الإناء؛ الغاز لا يحتفظ بشكل أو حجم ثابتين ويملأ الحيز المتاح."]],["أمثلة",["الثلج صلب، الماء السائل سائل، بخار الماء غاز."]]],"k":"توجد المادة في حالات شائعة: صلبة، سائلة، غازية."},{"t":"التحولات الفيزيائية للمادة","bs":[["الانصهار",["صلب ← سائل، مثل ذوبان الثلج."]],["التجمد",["سائل ← صلب، مثل تحول الماء إلى جليد."]],["التبخر",["سائل ← غاز، ويحدث من سطح السائل."]],["الغليان",["تحول سريع للسائل إلى غاز في كامل السائل عند شروط محددة."]],["التكاثف أو الإسالة",["غاز ← سائل، مثل قطرات الماء على سطح بارد."]],["في التحول الفيزيائي",["في التحول الفيزيائي تتغير الحالة أو الهيئة، بينما تبقى طبيعة المادة نفسها في المثال البسيط للماء."]]],"k":"الانصهار: صلب ← سائل، مثل ذوبان الثلج."},{"t":"الحجم والكتلة","bs":[[".g 1000 =",[".g 1000 = kg 1 .)kgوالكيلوغرام ( )gالكتلة تقاس بالميزان، ومن وحداتها الغرام ("]],[")Lالحجم يقاس بأدوات",[")Lالحجم يقاس بأدوات مناسبة مثل المخبار المدرج للسوائل، ومن وحداته اللتر ( .)³cmوالسنتيمتر المكعب ( )mLوالميليلتر ("]],["تقريبا في القياس",["تقريبا في القياس المدرسي. ³cm 1 = mL 1 و ،mL 1000 = L 1"]],["لقياس حجم جسم",["لقياس حجم جسم صلب غير منتظم يمكن استعمال طريقة الإزاحة بالماء: الحجم النهائي الحجم الابتدائي. −"]]],"k":".g 1000 = kg 1 .)kgوالكيلوغرام ( )gالكتلة تقاس بالميزان، ومن وحداتها الغرام ("},{"t":"المخاليط وفصل مكوناتها","bs":[["المزيج المتجانس يبدو",["المزيج المتجانس يبدو كمادة واحدة، مثل الماء المالح بعد ذوبان الملح."]],["المزيج غير المتجانس",["المزيج غير المتجانس تظهر فيه مكونات مختلفة، مثل الماء والرمل."]],["الترشيح يفصل جسما",["الترشيح يفصل جسما صلبا غير ذائب عن سائل، مثل الرمل والماء."]],["الترويق أو الترسيب",["الترويق أو الترسيب يساعد على فصل مكونات تختلف في الكثافة أو تترسب مع الزمن."]],["التبخير يمكن أن",["التبخير يمكن أن يستعمل لاسترجاع مادة صلبة مذابة، مثل الملح من الماء المالح، مع الانتباه إلى شروط السلامة."]]],"k":"المزيج المتجانس يبدو كمادة واحدة، مثل الماء المالح بعد ذوبان الملح."},{"t":"الهواء والاحتراق – مبادئ عامة","bs":[["الهواء خليط من",["الهواء خليط من الغازات، ويحتوي على الأكسجين والآزوت وغازات أخرى."]],["الأكسجين يساعد على",["الأكسجين يساعد على الاحتراق، لكنه ليس هواءً 