 سريع إخراج،",["ملخص سريع إخراج، مع إمكانية التخزين."]],["+معالجة +الحاسوب =",["+معالجة +الحاسوب = إدخال والقرص."]]],"k":"شغّل الجهاز بطريقة صحيحة، وافتح البرنامج المناسب، ثم أنشئ مستندا جديدا. اكتب عنوانا ومحتوى قصيرا، واحفظ العمل في المجلد المناسب باسم مفهوم. راجع الملف قبل إغلاقه، ثم أغلق البرنامج وأوقف تشغيل الجهاز …"}]},"art":{"name":"التربية التشكيلية","c":"#ad1457","i":"🎨","L":[{"t":"ما هي التربية التشكيلية؟","bs":[["التربية التشكيلية مجال",["التربية التشكيلية مجال للتعبير بالأشكال والخطوط والألوان والخامات. تساعدنا على الملاحظة والتخيل وتنظيم العناصر داخل مساحة العمل."]],["لا يعتمد العمل",["لا يعتمد العمل الفني على الموهبة فقط؛ فالتدرب والملاحظة والتجريب تساعد على تحسين النتائج."]],["قبل البدء، افهم",["قبل البدء، افهم المطلوب، وجهز الأدوات، ثم نفذ العمل وراجعه في النهاية."]]],"k":"التربية التشكيلية مجال للتعبير بالأشكال والخطوط والألوان والخامات. تساعدنا على الملاحظة والتخيل وتنظيم العناصر داخل مساحة العمل."},{"t":"عناصر العمل التشكيلي","bs":[["النقطة",["أثر صغير يمكن أن يتكرر ليكوّن إيقاعا أو ملمسا."]],["الخط",["قد يكون مستقيما أو منحنيا أو متعرجا أو متقطعا، ويستخدم لتحديد الشكل أو التعبير عن الحركة."]],["الشكل",["مساحة لها حدود، وقد يكون هندسيا مثل المربع والدائرة أو عضويا مستوحى من الطبيعة."]],["اللون",["يساعد على إبراز العناصر وخلق التباين والانسجام."]],["الملمس",["مظهر سطح الشيء أو إحساسه، مثل الناعم والخشن."]]],"k":"أثر صغير يمكن أن يتكرر ليكوّن إيقاعا أو ملمسا."},{"t":"الألوان الأساسية والثانوية","bs":[["في دروس الألوان",["في دروس الألوان التقليدية للرسم، تعد الأحمر والأصفر والأزرق ألوانا أساسية."]],["ينتج عن مزج",["ينتج عن مزج لونين أساسيين لون ثانوي: الأصفر مع الأزرق يعطي الأخضر، والأصفر مع الأحمر يعطي البرتقالي، والأحمر مع الأزرق يعطي البنفسجي."]],["الألوان الدافئة مثل",["الألوان الدافئة مثل الأحمر والبرتقالي والأصفر توحي غالبا بالدفء والحيوية، والباردة مثل الأزرق والأخضر والبنفسجي توحي غالبا بالهدوء."]],["تختلف النتيجة حسب",["تختلف النتيجة حسب نوع الألوان وكمياتها؛ أضف اللون تدريجيا وسجل ما تلاحظه."]]],"k":"في دروس الألوان التقليدية للرسم، تعد الأحمر والأصفر والأزرق ألوانا أساسية."},{"t":"التوازن والتكوين","bs":[["التكوين هو طريقة",["التكوين هو طريقة ترتيب الأشكال والألوان داخل مساحة الرسم."]],["يتحقق التوازن عندما",["يتحقق التوازن عندما تبدو العناصر موزعة بطريقة مريحة بصريا، وقد يكون متماثلا أو غير متماثل."]],["التباين هو الاختلاف",["التباين هو الاختلاف الواضح بين العناصر، مثل الفاتح والغامق أو الكبير والصغير."]],["الوحدة تعني أن",["الوحدة تعني أن أجزاء العمل تبدو مترابطة، بينما التنوع يمنع الرتابة."]]],"k":"التكوين هو طريقة ترتيب الأشكال والألوان داخل مساحة الرسم."},{"t":"المنظور والملاحظة","bs":[["الأشياء القريبة تبدو",["الأشياء القريبة تبدو عادة أكبر وأكثر وضوحا، والأشياء البعيدة تبدو أصغر وأقل تفصيلا."]],["عند رسم طريق",["عند رسم طريق أو صف أشجار، يمكن جعل العناصر أصغر تدريجيا كلما ابتعدت لإظهار العمق."]],["ابدأ بملاحظة الشكل",["ابدأ بملاحظة الشكل العام والنسب، ثم أضف التفاصيل تدريجيا."]]],"k":"الأشياء القريبة تبدو عادة أكبر وأكثر وضوحا، والأشياء البعيدة تبدو أصغر وأقل تفصيلا."},{"t":"الأدوات والخامات والسلامة","bs":[["من الأدوات",["قلم الرصاص، الممحاة، المسطرة، الألوان الخشبية أو المائية، الورق والمقص."]],["استعمل المقص بحذر،",["استعمل المقص بحذر، ولا توجهه نحو الآخرين. لا تضع الألوان أو المواد الفنية في الفم أو العينين."]],["حافظ على نظافة",["حافظ على نظافة الطاولة، وأغلق علب الألوان بعد استعمالها، ولا تهدر الورق والخامات."]],["يمكن استخدام مواد",["يمكن استخدام مواد معاد تدويرها في أعمال فنية بشرط أن تكون نظيفة وآمنة."]]],"k":"قلم الرصاص، الممحاة، المسطرة، الألوان الخشبية أو المائية، الورق والمقص."},{"t":"خطوات إنجاز عمل تشكيلي","bs":[["اقرأ التعليمة وحدد",["اقرأ التعليمة وحدد الموضوع والمساحة والأدوات. )1"]],["ارسم تخطيطا خفيفا",["ارسم تخطيطا خفيفا بالقلم الرصاص. )2"]],["وزع العناصر داخل",["وزع العناصر داخل الورقة مع مراعاة التوازن والحجم. )3"]],["أضف الخطوط والتفاصيل",["أضف الخطوط والتفاصيل ثم الألوان أو الخامات. )4"]],["راجع العمل ونظف",["راجع العمل ونظف مكانك، ثم اكتب اسم العمل إذا طُلب منك ذلك. )5"]],["ملخص للحفظ",["عناصر العمل التشكيلي: النقطة، الخط، الشكل، اللون، الملمس.","مبادئ التكوين: التوازن، التباين، الوحدة، التنوع.","الألوان الثانوية في المزج التقليدي: الأخضر، البرتقالي، البنفسجي.","الأفضل التخطيط الخفيف أولا، ثم إضافة التفاصيل والألوان."]]],"k":"اقرأ التعليمة وحدد الموضوع والمساحة والأدوات. )1"}]}};
function am1Tab(k){const d=AM1[k];return d.L.map((l,i)=>card('الدرس '+(i+1),d.c,d.i,l.t,l.bs,l.k,'',d.name+' · السنة الأولى متوسط')).join('')}
const TG={"mec":{"key":"genie-mecanique","map":"gmec","name":"الهندسة الميكانيكية","c":"#455a64","i":"⚙️","L":[{"i":"📐","t":"قراءة الرسم التقني والإنشاء","B":[["ماذا نقرأ أولا؟",["عنوان الرسم وجدول البيانات","المقياس والمساقط والمقاطع","الأبعاد والتفاوتات المكتوبة"]],["المقياس",["الطبيعي `1:1`","التصغير مثل `1:2`","التكبير مثل `2:1`"]],["الرسم التجميعي",["حدد كل قطعة برقمها","استخرج وظيفتها","حدد علاقات التلامس والتثبيت"]],["المسقط والمقطع",["المسقط يمثل الشكل الخارجي","المقطع يكشف الداخل بقطع وهمي","خطوط التهشير تدل على المادة المقطوعة"]],["أخطاء شائعة",["قياس البعد من الورقة رغم أنه مكتوب","الخلط بين التصغير والتكبير","تجاهل التفاوتات"]]],"X":"الرسم التقني لغة عالمية بين المصمم والعامل. قبل أي حل اقرأ العنوان والمقياس ثم المساقط. تذكر أن البعد المكتوب هو المرجع دائما، أما الورقة فقد تكون مصغرة أو مكبرة.","M":["الطول المرسوم = الطول الحقيقي × المقياس.","البعد المكتوب أولى من البعد المقاس.","في التجميعي ابدأ بالترقيم ثم الوظيفة ثم الوصلات."],"EX":[["المقياس `1:2` والطول الحقيقي للقطعة `80 mm`. ما طولها المرسوم؟","المقياس `1:2` تصغير بالنصف. الطول المرسوم `80 × 1/2 = 40 mm`."],["ما الفرق بين المسقط والمقطع؟ ولماذا تُستعمل خطوط التهشير؟","المسقط يعرض الشكل الخارجي كما نراه. والمقطع نتخيل فيه قطع القطعة بمستو لإظهار الداخل. خطوط التهشير تبين الأجزاء المقطوعة من المادة فنفرق بينها وبين الفراغات."],["قطعة طولها الحقيقي `120 mm` رُسمت بمقياس `2:1`. ما طولها المرسوم؟","المقياس `2:1` تكبير مرتين. الطول المرسوم `120 × 2 = 240 mm`."]],"K":"الطول المرسوم = الحقيقي × المقياس. البعد المكتوب هو المرجع. المقطع يكشف الداخل وتهشيره يدل على المادة."},{"i":"🔩","t":"الوصلات الميكانيكية ودرجات الحرية","B":[["الوصلة",["تربط قطعتين","تسمح بحركات نسبية محددة","وتمنع حركات أخرى"]],["أنواع الوصلات",["ثابتة (لا حركة)","محورية دورانية","انزلاقية"]],["وصلات أخرى",["لولبية (دوران وانتقال معا)","كروية (دوران حول نقطة)","متمحورة بالتدحرج"]],["كيف أحلل آلية؟",["اذكر القطع المتصلة","نوع الوصلة","الحركة المسموحة والممنوعة"]],["المحامل",["توجه الدوران","تقلل الاحتكاك","يُختار نوعها حسب الحمل والسرعة والدقة"]]],"X":"كل وصلة قاعدة لعبة بين قطعتين: ما الذي يُسمح لإحداهما بفعله بالنسبة للأخرى. الباب مع إطاره يدور فقط، والمنزلق على سكة ينتقل فقط في اتجاه واحد. لا تخلط بين حركة القطعة وحركة نقطة عليها.","M":["لكل وصلة: حركة مسموحة وحركات ممنوعة.","حركة القطعة غير حركة نقطة منها.","اختر المحمل بحسب الحمل والسرعة والدقة."],"EX":[["محور يدور داخل محمل. ما الحركة المسموحة؟","الحركة المسموحة هي الدوران حول محور المحمل فقط. أما الانتقالات الأخرى فتُمنع بحسب التركيب. الوصلة محورية دورانية."],["حدّد نوع الوصلة بين باب وإطاره، وبين منزلق وسكة خطية.","الباب والإطار: وصلة محورية (دورانية) حول محور المفصلة. المنزلق والسكة: وصلة انزلاقية، انتقال في اتجاه السكة فقط."],["ما فائدة المحمل في آلية تدور؟","يوجه الدوران ويقلل الاحتكاك ويتحمل الأحمال. ويُختار حسب الحمل والسرعة والدقة المطلوبة."]],"K":"وصلة = حركة مسموحة + حركات ممنوعة. دورانية، انزلاقية، لولبية، كروية، ثابتة. المحمل يوجه الدوران ويقلل الاحتكاك."},{"i":"⛓️","t":"مقاومة المواد: الشد والضغط","B":[["الإجهاد العادي",["`σ = N/S`","`N` بالنيوتن و `S` بـ `m²` فالإجهاد بـ `Pa`","أو `N/mm²` وهو يساوي `MPa`"]],["الاستطالة المرنة",["`ΔL = N·L/(E·S)`","`E` معامل يونغ","`L` الطول الأصلي"]],["شرط المقاومة",["`σ ≤ σ_adm`","الإجهاد المحسوب أقل من المسموح","وحدات متجانسة دائما"]],["حالة الشد والضغط",["الشد يطيل القضيب","الضغط يقصّره","`N` موجبة للشد وسالبة للضغط عادة"]],["أخطاء شائعة",["خلط `mm²` مع `m²`","خلط `N` مع `kN`","نسيان مقارنة `σ` بـ `σ_adm`"]]],"X":"القوة المحورية تشد القضيب أو تضغطه. نقسمها على مساحة المقطع لنعرف الإجهاد، أي القوة لكل وحدة مساحة. إن كان الإجهاد أقل من الإجهاد الذي تتحمله المادة فالقطعة آمنة.","M":["حوّل `kN` إلى `N` أولا: `1 kN = 1000 N`.","مع `mm²` تكون النتيجة بـ `MPa` مباشرة.","اكتب الشرط `σ ≤ σ_adm` واستنتج."],"EX":[["قضيب مساحته `100 mm²` تؤثر عليه قوة شد `10 kN`. احسب الإجهاد.","`σ = 10000/100 = 100 N/mm² = 100 MPa`."],["قضيب مساحته `200 mm²` يتعرض إلى `12 kN`. احسب الإجهاد بوحدة `MPa`.","`N = 12 kN = 12000 N`. `σ = 12000/200 = 60 MPa`."],["قضيب فولاذي طوله `2 m` ومساحته `200 mm²` وقوة الشد `20 kN` و `E = 200000 MPa`. احسب الاستطالة.","`ΔL = N·L/(E·S) = 20000 × 2000/(200000 × 200) = 40000000/40000000 = 1 mm`."]],"K":"`σ = N/S` و `ΔL = N·L/(E·S)`. الشرط `σ ≤ σ_adm`. N/mm² = MPa."},{"i":"🔧","t":"القص والانحناء والالتواء","B":[["القص",["قوى متعاكسة متقاربة على المقطع","`τ = T/S`","مثل مسمار أو برشام"]],["الانحناء",["أحمال عرضية تولد عزم انحناء","ألياف جانب في الشد والجانب الآخر في الضغط","استعمل مخططات العزم"]],["الالتواء",["عزم حول محور العمود","يظهر في أعمدة نقل الحركة","يرتبط بالقدرة والسرعة الزاوية"]],["القدرة الدورانية",["`P = C·ω`","`C` عزم الدوران بـ `N·m`","`ω` بـ `rad/s`"]],["تحويل السرعة",["`ω = 2π·n/60`","`n` بـ `tr/min`","`1 tr/min = 0.1047 rad/s`"]]],"X":"القص يحدث عندما تحاول قوتان متعاكستان قص المقطع كما تقص المقص الورقة. الانحناء يثني العنصر فيشد جانبا ويضغط جانبا. الالتواء يلوي العمود حول محوره وهو يرتبط بالقدرة التي ينقلها.","M":["القص: قسّم القوة على مساحة المقطع المقصوص.","القدرة = العزم × السرعة الزاوية.","حوّل tr/min إلى rad/s قبل الحساب."],"EX":[["حوّل سرعة `300 tr/min` إلى `rad/s` باستعمال `ω = 2πn/60`.","`ω = 2π × 300/60 = 10π ≈ 31.4 rad/s`."],["مسمار يتعرض لقوة قص `6 kN` ومساحة مقطعه `50 mm²`. احسب `τ`.","`τ = T/S = 6000/50 = 120 N/mm² = 120 MPa`."],["عمود ينقل عزما `C = 20 N·m` بسرعة `300 tr/min`. احسب القدرة.","`ω ≈ 31.4 rad/s`. `P = C·ω = 20 × 31.4 ≈ 628 W`."]],"K":"`τ = T/S` و `P = C·ω` و `ω = 2πn/60`. الانحناء: شد في جانب وضغط في الجانب الآخر."},{"i":"🔁","t":"نقل الحركة والقدرة والمردود","B":[["زوج تروس",["`n_1·Z_1 = n_2·Z_2`","`n` السرعة و `Z` عدد الأسنان","اتجاها الدوران متعاكسان في الخارجي"]],["نسبة النقل",["`r = n_2/n_1 = Z_1/Z_2`","حسب اصطلاح الدرس","اكتب العلاقة المستعملة دائما"]],["المردود",["`η = P_u/P_a`","`P_u` المفيدة و `P_a` الممتصة","`η ≤ 1` في النظام الحقيقي"]],["الضياعات",["الاحتكاك","الحرارة","`P_a = P_u + P_{pertes}` (الضياعات)"]],["أخطاء شائعة",["عكس نسبة النقل","خلط المدخل والمخرج","قول إن المردود أكبر من 1"]]],"X":"الترس الصغير يدور أسرع من الكبير المتصل به. حاصل ضرب السرعة في عدد الأسنان ثابت. أما المردود فهو نسبة ما أخذناه فعلا من الآلة إلى ما أعطيناها، وهو دائما أقل من 1 بسبب الضياعات.","M":["ابدأ بتحديد المدخل والمخرج.","`n_2 = n_1·Z_1/Z_2`.","المردود يُعطى نسبة أو مئوية."],"EX":[["`Z_1 = 20` و `Z_2 = 60` و `n_1 = 900 tr/min`. احسب `n_2`.","`n_2 = n_1·Z_1/Z_2 = 900 × 20/60 = 300 tr/min`."],["آلة تستقبل `500 W` وتقدم `400 W` مفيدة. احسب مردودها.","`η = 400/500 = 0.8` أي `80%`. الضياعات `100 W`."],["`Z_1 = 18` و `Z_2 = 54` و `n_1 = 1200 tr/min`. احسب `n_2` ونسبة النقل.","`n_2 = 1200 × 18/54 = 400 tr/min`. نسبة النقل `n_2/n_1 = 400/1200 = 1/3`. الترس الثاني أبطأ ثلاث مرات."]],"K":"`n_1·Z_1 = n_2·Z_2` و `η = P_u/P_a ≤ 1`. حدد المدخل والمخرج أولا."},{"i":"🏭","t":"الإنتاج والتصنيع","B":[["العمليات",["السباكة والتشكيل","التشغيل بالقطع","اللحام والمعالجة الحرارية"]],["الخراطة",["القطعة تدور غالبا","الأداة تتحرك","سطوح أسطوانية دقيقة"]],["التفريز",["الأداة تدور","القطعة أو الطاولة تتحرك","سطوح مستوية وأخاديد"]],["معايير الاختيار",["المادة والشكل","الدقة وجودة السطح","التكلفة والكمية"]],["السلامة والجودة",["نظارات واقية وتثبيت القطعة","عدم ارتداء قفازات قرب الأجزاء الدوارة","مراقبة الأبعاد والتفاوتات"]]],"X":"نختار طريقة التصنيع بحسب الشكل المطلوب والدقة والتكلفة. القطعة الدوارة ذات السطح الأسطواني تناسبها الخراطة، والسطوح المستوية تناسبها آلة التفريز. وتبقى السلامة أولا في كل ورشة.","M":["ربط العملية بالشكل المطلوب.","قارن الدقة والتكلفة.","اذكر دائما إجراءات السلامة."],"EX":[["أي عملية تناسب سطحا أسطوانيا خارجيا دقيقا على قطعة دوارة؟","الخراطة، لأن القطعة تدور وتتحرك أداة القطع على طولها فتعطي سطحا أسطوانيا دقيقا."],["اختر عملية مناسبة لثقب قطعة معدنية، ثم اذكر إجراءي سلامة.","العملية: الثقب بالمثقاب على آلة الثقب. السلامة: ارتداء نظارات واقية، وتثبيت القطعة جيدا في الملزمة دون حملها باليد، وعدم ارتداء قفازات قرب المثقاب الدوار."],["ما الفرق بين الخراطة والتفريز من حيث الحركة؟","في الخراطة تدور القطعة وتتحرك الأداة. وفي التفريز تدور الأداة وتتحرك القطعة أو الطاولة."]],"K":"خراطة: القطعة تدور. تفريز: الأداة تدور. اختر العملية بالشكل والدقة والتكلفة. السلامة أولا."}],"O":[{"t":"نقل الحركة: التروس والسيور","bs":[["الترس",["المعامل `m` وعدد الأسنان `Z`","القطر القاسم `d = m × Z`","لا بد من نفس `m` للترسين المتعالقين"]],["المسافة بين المحورين",["`a = (d_1 + d_2)/2`","من الترسين المتعالقين","`a` بالمليمتر"]],["نسبة النقل",["`r = ω_{out}/ω_{in} = Z_{in}/Z_{out}`","`r < 1` تخفيض السرعة","`r > 1` زيادة السرعة"]],["السير",["يوصل الحركة بين محورين بعيدين","ينقل بالاحتكاك أو بالأسنان","مرن ويمتص الصدمات"]]],"k":"`d = m·Z` و `a = (d_1 + d_2)/2` و `r = Z_{in}/Z_{out}`. نفس `m` للترسين المتعالقين."},{"t":"الاستطاعة والمردود","bs":[["الاستطاعة الدورانية",["`P = C × ω`","`C` العزم بـ `N·m`","`ω` السرعة الزاوية بـ `rad/s`"]],["السرعة الزاوية",["`ω = 2π·N/60`","`N` بالدورة في الدقيقة","`300 tr/min ≈ 31.4 rad/s`"]],["المردود",["`η = P_u/P_a`","`P_u` المفيدة و `P_a` الممتصة","`η ≤ 1`"]],["سلسلة النقل",["المردود الكلي جداء المردودات","`η = η_1 × η_2 × ...`","كل مرحلة تضيّع جزءا"]]],"k":"`P = C·ω` و `ω = 2πN/60` و `η = P_u/P_a`. سلسلة: `η` جداء المردودات."},{"t":"الروابط والتصميم الميكانيكي","bs":[["الربط المفكوك",["براغي ومسامير ولوالب","يمكن فكه دون إتلاف","للصيانة والتبديل"]],["الربط غير المفكوك",["لحام وتثبيت دائم","لا يفك إلا بإتلاف","للتجميعات الدائمة"]],["المحامل والاحتكاك",["المحامل تؤمن الدوران وتقلل الاحتكاك","احتكاك انزلاقي وتدحرجي","التدحرجي أقل"]],["الرسم الصناعي",["الإسقاطات","المقاطع","التأطير"]]],"k":"ربط مفكوك (براغي) وغير مفكوك (لحام). المحامل تقلل الاحتكاك والتدحرجي أقل من الانزلاقي."}]},"ele":{"key":"genie-electrique","map":"gele","name":"الهندسة الكهربائية","c":"#f9a825","i":"⚡","L":[{"i":"🔗","t":"سلسلة المعلومات وسلسلة الطاقة","B":[["سلسلة المعلومات",["الحساسات تكتسب المعطيات","وحدة التحكم تعالجها","وتصدر الأوامر"]],["سلسلة الطاقة",["التغذية","التوزيع (مسبق المشغل)","التحويل والنقل ثم العضو المنفذ"]],["الفرق بين العناصر",["الحساس يكتشف حالة","المشغل ينفذ فعلا ماديا","مسبق المشغل يوزع الطاقة على المشغل"]],["مثال: باب آلي",["حساس نهاية الشوط","وحدة التحكم تقرر","مرحل أو موزع ثم المحرك"]],["أخطاء شائعة",["الخلط بين الحساس والمشغل","وضع المحرك في سلسلة المعلومات","نسيان مسبق المشغل"]]],"X":"تخيل نظاما آليا كإنسان: الحواس (الحساسات) ترسل معلومة إلى الدماغ (وحدة التحكم) الذي يعطي أمرا للعضلات (المشغلات) فتتحرك. الأوامر تمر عبر سلسلة المعلومات، أما القوة فتمر عبر سلسلة الطاقة.","M":["الحساس يكتشف، وحدة التحكم تقرر، مسبق المشغل يوزع، المشغل ينفذ.","ارسم المخطط: حساس ثم تحكم ثم مسبق مشغل ثم مشغل.","قد تختلف العناصر من نظام لآخر."],"EX":[["صنّف حساس نهاية الشوط، وحدة التحكم، المحرك، وموزع القدرة ضمن السلسلتين.","حساس نهاية الشوط: سلسلة المعلومات (اكتساب). وحدة التحكم: سلسلة المعلومات (معالجة). موزع القدرة (المرحل): سلسلة الطاقة (توزيع). المحرك: سلسلة الطاقة (عضو منفذ يحول الطاقة)."],["في باب آلي، صف تسلسل الإشارة من فتح الباب إلى حركته.","الحساس يكشف الشخص ويرسل معلومة. وحدة التحكم تقرر الفتح. المرحل أو الموزع يوجه الطاقة. المحرك يحرك الباب. وعند نهاية الشوط يرسل الحساس معلومة للإيقاف."],["ما الفرق بين الحساس والمشغل؟","الحساس يحول كمية فيزيائية إلى إشارة (معلومة). أما المشغل فيحول الطاقة إلى فعل مادي (حركة، حرارة، ...)."]],"K":"معلومات: حساس ثم تحكم. طاقة: تغذية، توزيع، تحويل، عضو منفذ. الحساس يكتشف والمشغل ينفذ."},{"i":"🔌","t":"أساسيات الدارات الكهربائية","B":[["قانون أوم",["`U = R·I`","`U` بالفولت و `I` بالأمبير و `R` بالأوم","للمقاومة فقط"]],["القدرة",["`P = U·I`","`P = R·I²`","`P = U²/R`"]],["التوالي",["التيار نفسه في العناصر","الجهد الكلي مجموع الجهود","`R = R_1 + R_2`"]],["التوازي",["الجهد نفسه على الفروع","التيارات تتجمع","`1/R = 1/R_1 + 1/R_2`"]],["أخطاء شائعة",["خلط `mA` مع `A`","استعمال علاقة توالي في توازي","نسيان وحدة القدرة `W`"]]],"X":"قانون أوم يقول إن التيار يزيد عندما يزيد الجهد ويقل عندما تزيد المقاومة. القدرة هي سرعة استهلاك الطاقة. في التوالي كل العناصر تتقاسم نفس التيار، وفي التوازي كل الفروع تتقاسم نفس الجهد.","M":["اكتب المعطيات بالوحدات الأساسية.","اختر علاقة القدرة المناسبة للمعطيات.","حدد التوالي أو التوازي قبل الحل."],"EX":[["مقاومة `12 Ω` تحت توتر `24 V`. احسب التيار والقدرة.","`I = U/R = 24/12 = 2 A`. `P = U·I = 24 × 2 = 48 W`."],["احسب التيار في مقاومة `30 Ω` موصولة بمصدر `15 V`.","`I = U/R = 15/30 = 0.5 A`. والقدرة `P = 15 × 0.5 = 7.5 W`."],["مقاومتان `10 Ω` و `20 Ω` ومصدر `30 V`. احسب التيار على التوالي، ثم التيارات على التوازي.","التوالي: `R = 30 Ω` و `I = 30/30 = 1 A`. التوازي: `I_1 = 30/10 = 3 A` و `I_2 = 30/20 = 1.5 A` والتيار الكلي `4.5 A`."]],"K":"`U = R·I` و `P = U·I`. توالي: نفس التيار. توازي: نفس الجهد."},{"i":"🧩","t":"المنطق التوافقي","B":[["المتغير المنطقي",["يأخذ `0` أو `1`","المداخل والمخرج","جدول الحقيقة يعرض كل الحالات"]],["الدوال الأساسية",["`NOT` النفي تعكس الحالة","`AND` تساوي 1 فقط إذا كل المداخل 1","`OR` تساوي 1 إذا مدخل واحد على الأقل 1"]],["خطوات الحل",["حدد المداخل والمخرج","أنشئ جدول الحقيقة","استخرج المعادلة وبسطها"]],["عدد الحالات",["`n` مداخل تعطي `2^{n}` حالة","مدخلان: 4 حالات","ثلاثة مداخل: 8 حالات"]],["أخطاء شائعة",["نسيان بعض الحالات","الخلط بين `AND` و `OR`","أخطاء في إشارة النفي"]]],"X":"المنطق التوافقي يتعامل مع إشارات إما مغلقة 1 أو مفتوحة 0. AND تعني كل الشروط معا، OR تعني شرطا واحدا يكفي، NOT تقلب القيمة. جدول الحقيقة يفحص كل احتمالات المداخل.","M":["اكتب كل الحالات بالترتيب الثنائي.","احسب الخرج سطرا سطرا.","بسّط المعادلة بالقواعد المدروسة."],"EX":[["أنشئ جدول الحقيقة للعبارة `Y = A + B̄`.","مدخلان فـ 4 حالات. `A=0,B=0`: `Y = 0 + 1 = 1`. `A=0,B=1`: `Y = 0 + 0 = 0`. `A=1,B=0`: `Y = 1 + 1 = 1`. `A=1,B=1`: `Y = 1 + 0 = 1`."],["متى تكون `Y = A·B` مساوية 1؟","فقط عندما `A = 1` و `B = 1`. في كل الحالات الأخرى `Y = 0`."],["كم حالة في جدول حقيقة دالة بثلاثة مداخل؟","`2^{3} = 8` حالات."]],"K":"AND: كل المداخل 1. OR: واحد على الأقل. NOT: عكس. n مداخل ⇒ 2^n حالة."},{"i":"💾","t":"المنطق التتابعي والذاكرة","B":[["التتابعي",["الخرج لا يعتمد على المداخل الحالية فقط","بل على الحالة السابقة","يحتاج ذاكرة"]],["القلابات والسجلات",["القلاب يحفظ بتا واحدا","السجل يحفظ مجموعة بتات","التزامن بإشارة الساعة"]],["العدادات",["تعد النبضات أو الأحداث","عدد حالات عداد `n` بت هو `2^{n}`","أكبر عدد `2^{n} - 1`"]],["تحليل عداد",["عدد الحالات","ترتيب الانتقال","حالة البدء وإشارة الساعة"]],["أخطاء شائعة",["الخلط بين التوافقي والتتابعي","نسيان الصفر ضمن الحالات","الخلط بين `2^{n}` و `2^{n} - 1`"]]],"X":"الفرق بين التوافقي والتتابعي كالفرق بين آلة حاسبة وذاكرة. الدارة التتابعية تتذكر ما جرى. القلاب يخزن بتا، والعداد يعد النبضات ويمر بسلسلة حالات منظمة.","M":["عداد من `n` بت له `2^{n}` حالة.","أكبر عدد يمثله `2^{n} - 1`.","حدد حالة البدء وترتيب الانتقال."],"EX":[["عداد من 3 بتات. كم حالة له؟","`2^{3} = 8` حالات ثنائية مختلفة، من `000` إلى `111`."],["كم حالة يتيح عداد من 4 بتات؟ وما أكبر عدد غير سالب يمثله؟","`2^{4} = 16` حالة. وأكبر عدد `16 - 1 = 15`."],["ما الفرق بين القلاب والسجل؟","القلاب يحفظ بتا واحدا. السجل مجموعة قلابات يحفظ عدة بتات."]],"K":"تتابعي = خرج يعتمد على الحالة السابقة. عداد n بت: 2^n حالة وأكبر عدد 2^n - 1."},{"i":"📡","t":"الحساسات والمشغلات والتحكم","B":[["الحساس",["يحول كمية فيزيائية إلى إشارة","موضع، حرارة، ضغط، ضوء، سرعة","قد يكون تماسيا أو عن بعد"]],["المشغل",["يحول الطاقة إلى فعل","محرك كهربائي","أسطوانة هوائية، صمام، مقاومة تسخين"]],["قراءة المخطط",["تتبع الإشارة من الحساس","إلى المعالجة ثم الأمر","تحقق من الأمان والتوقف الطارئ"]],["اختيار حساس",["نوع الجسم المراد كشفه","المسافة والبيئة","الدقة والتكلفة"]],["أخطاء شائعة",["الخلط بين الحساس والمشغل","إهمال التوقف الطارئ","اختيار حساس لا يناسب المادة"]]],"X":"الحساس هو الحاسة التي تشعر بالعالم الخارجي والمشغل هو اليد التي تتحرك. في المخطط اتبع الإشارة من أولها: ماذا نقيس؟ وماذا نقرر؟ وماذا نشغل؟ وتذكر أن الأمان له أولوية.","M":["حدد الكمية المراد قياسها.","اربط كل حساس بمشغل في المخطط.","ضع شروط الأمان في الحسبان."],"EX":[["في نظام تعبئة، ما دور حساس المستوى؟","يكتشف بلوغ المستوى المطلوب فيرسل إشارة لإيقاف صمام التعبئة."],["اقترح حساسا مناسبا لاكتشاف قطعة معدنية على ناقل، وعلّل اختيارك.","حساس تقاربي حثي. لأنه يكشف المعادن دون تلامس فلا يتآكل ولا يعطل حركة القطع."],["اذكر ثلاثة أمثلة على مشغلات.","محرك كهربائي، أسطوانة هوائية، صمام كهرومغناطيسي. (ومقاومة تسخين أيضا)."]],"K":"حساس: كمية فيزيائية ⟵ إشارة. مشغل: طاقة ⟵ فعل. الأمان والتوقف الطارئ دائما."},{"i":"⚙️","t":"المحركات والطاقة الكهربائية","B":[["المحرك",["يحول الكهربائية إلى ميكانيكية","يختار حسب القدرة والسرعة","وعزم البدء ونمط التغذية"]],["لوحة المحرك",["التوتر والتيار","التردد والقدرة","السرعة ونمط الربط"]],["الربط",["نجمة أو مثلث","قارن توتر اللوحة بتوتر الشبكة","لا تخمن الربط"]],["قبل التشغيل",["التوتر الاسمي","الحماية الحرارية والتأريض","استمرارية التوصيلات"]],["أخطاء شائعة",["ربط خاطئ يحرق المحرك","إهمال التأريض","عدم قراءة اللوحة"]]],"X":"لوحة المحرك هي بطاقة هويته: تقول لك أي توتر يتحمل وما قدرته وسرعته. إذا كتب عليها مثلا `230/400 V` فمعناه أن الملف يتحمل 230 V. على شبكة 400 V نربط بنجمة، وعلى شبكة 230 V نربط بمثلث.","M":["اقرأ اللوحة قبل أي توصيل.","قارن توتر الملف بتوتر الشبكة.","تحقق من التأريض والحماية."],"EX":[["اذكر أربع معلومات أساسية يجب قراءتها من لوحة محرك كهربائي.","التوتر (V)، التيار الاسمي (A)، القدرة (kW)، السرعة (tr/min). (وكذلك التردد ونمط الربط)."],["محرك لوحته `230/400 V` وشبكة ثلاثية الطور `400 V` بين الأطوار. أي ربط نستعمل؟","الملف يتحمل 230 V. على شبكة 400 V نربطه بنجمة ليأخذ كل ملف `400/√3 ≈ 230 V`."],["ما الفحوصات قبل تشغيل محرك؟","التوتر الاسمي، الحماية الحرارية، التأريض، واستمرارية التوصيلات."]],"K":"لوحة المحرك: V، A، Hz، kW، tr/min، ربط. 230/400 V: نجمة على 400 V ومثلث على 230 V."}],"O":[{"t":"النظام الثلاثي الطور","bs":[["التعريف",["ثلاثة توترات جيبية","نفس القيمة الفعالة","مزاحة بـ `120°`"]],["التوترات",["`U = √3 × V`","`V` بين طور والحيادي","`U` بين طورين"]],["الاستطاعة",["`P = √3·U·I·cos φ`","فعالة بالواط","`cos φ` معامل الاستطاعة"]],["التركيب",["نجمي `Y` أو مثلثي `Δ`","يتعلق بتوتر الشبكة وتوتر الجهاز","نجمي: `I = J`، مثلثي: `I = √3·J`"]]],"k":"`U = √3·V` و `P = √3·U·I·cos φ`. نجمي `I = J` ومثلثي `I = √3·J`."},{"t":"المحولة الكهربائية","bs":[["الوظيفة",["تغير التوتر المتناوب","دون تغيير التردد","ابتدائي وثانوي"]],["نسبة التحويل",["`m = U_2/U_1 = N_2/N_1`","`m > 1` رافعة","`m < 1` خافضة"]],["المحولة المثالية",["`U_1·I_1 = U_2·I_2`","انحفاظ الاستطاعة","المردود 1"]],["الضياعات والمردود",["فقد النحاس (جول)","فقد الحديد (هستيريزيس وفوكو)","`η = P_2/P_1`"]]],"k":"`m = U_2/U_1 = N_2/N_1` و `U_1 I_1 = U_2 I_2` (مثالية) و `η = P_2/P_1`."},{"t":"الإلكترونيك: الديود والترانزستور","bs":[["الديود",["يمرر التيار في اتجاه واحد","التوصيل الأمامي","يحجب في العكس"]],["التقويم",["تحويل المتناوب إلى مستمر","بديود أو جسر","يتبعه ترشيح"]],["الترانزستور",["كقاطعة: إشباع وانسداد","أو كمضخم","ثنائي القطبية"]],["العلاقة والمنطق",["`I_C = β × I_B` في النظام الخطي","`AND` و `OR` و `NOT`","بوابات منطقية"]]],"k":"ديود: اتجاه واحد. ترانزستور: قاطعة أو مضخم، `I_C = β·I_B`."}]},"civ":{"key":"genie-civil","map":"gciv","name":"الهندسة المدنية","c":"#6d4c41","i":"🏗️","L":[{"i":"📃","t":"قراءة المخططات","B":[["ماذا نقرأ؟",["العنوان والمقياس","الاتجاهات والمستويات","المحاور والأبعاد والرموز والقطاعات"]],["المخطط المعماري",["تنظيم الفضاءات","الفتحات والأبعاد","الشكل العام"]],["المخطط الإنشائي",["العناصر الحاملة","التسليح","التفاصيل التنفيذية"]],["المقياس",["`1:100` يعني `1 cm` يمثل `1 m`","الطول المرسوم = الحقيقي × المقياس","البعد المكتوب هو المرجع"]],["أخطاء شائعة",["قياس البعد من الورقة","الخلط بين المقياسين","إهمال المستويات"]]],"X":"المخطط عقد بين المهندس والمنفذ. المعماري يقول كيف يبدو المبنى، والإنشائي يقول كيف يقف. اقرأ العنوان والمقياس أولا ثم الأبعاد المكتوبة، فهي المرجع.","M":["اكتب المقياس كنسبة.","حوّل الوحدات قبل الحساب.","فرّق بين المعماري والإنشائي."],"EX":[["مقياس `1:100`. ماذا يمثل `1 cm` على المخطط؟","`1 cm × 100 = 100 cm = 1 m` في الواقع."],["جدار طوله `4.5 m` بمقياس `1:50`. ما طوله على المخطط؟","`4.5 m = 450 cm`. الطول على المخطط `450/50 = 9 cm`."],["ما الفرق بين المخطط المعماري والإنشائي؟","المعماري يبين الفضاءات والفتحات والأبعاد. الإنشائي يبين العناصر الحاملة والتسليح والتفاصيل التنفيذية."]],"K":"الطول المرسوم = الحقيقي × المقياس. المعماري: فضاءات. الإنشائي: عناصر حاملة وتسليح."},{"i":"🧱","t":"مواد البناء والخرسانة","B":[["الخرسانة",["رابط إسمنتي + ماء + ركام","مقاومة الضغط أعلى من الشد","قد تضاف إضافات"]],["الفولاذ",["مقاومة جيدة للشد","ليونة","يستعمل في الخرسانة المسلحة"]],["الخرسانة المسلحة",["خرسانة تقاوم الضغط","فولاذ يقاوم الشد","تعاون المادتين"]],["جودة الخرسانة",["ن