grep -q 'lessons_3as_ge.js' index.html || sed -i 's#<script src="lessons.js"></script>#<script src="lessons.js"></script>\n<script src="lessons_3as_ge.js"></script>\n<script src="maps_hook.js"></script>#' index.html
grep -q 'maps_hook.js' index.html || sed -i 's#<script src="lessons_3as_ge.js"></script>#<script src="lessons_3as_ge.js"></script>\n<script src="maps_hook.js"></script>#' index.html

# إضافة الزر الخامس بعد زر الكويز
if grep -q "openMaps(" index.html; then
  echo "الزر موجود مسبقًا، تخطيت إضافته"
else
  cat > ../.ins_sj.txt <<'ZAD_EOF'
      hubBtn('🗺️','الخرائط الذهنية', hasMaps(sj.key)?'خريطة لكل درس':'قيد الإعداد', hasMaps(sj.key), `openMaps('${sj.key}')`) +
ZAD_EOF
  cat > ../.ins_k.txt <<'ZAD_EOF'
      hubBtn('🗺️','الخرائط الذهنية', hasMaps(key)?'خريطة لكل درس':'قيد الإعداد', hasMaps(key), `openMaps('${key}')`) +
ZAD_EOF
  for N in $(grep -nF "openQuiz('\${sj.key}')" index.html | cut -d: -f1 | sort -rn); do sed -i "${N}r ../.ins_sj.txt" index.html; done
  for N in $(grep -nF "openQuiz('\${key}')" index.html | cut -d: -f1 | sort -rn); do sed -i "${N}r ../.ins_k.txt" index.html; done
  rm -f ../.ins_sj.txt ../.ins_k.txt
fi

echo "---- النتيجة ----"
grep -n "lessons_3as_ge\|maps_hook" index.html | cut -c1-120
grep -n "openMaps" index.html | cut -c1-160
ls -l lessons_3as_ge.js maps.html maps_hook.js
echo "---- مواد فلسفة/عربية ----"; grep -o "key[^,]*,[^,]*\(فلسف\|العربية\)[^,]*" db.js | head -12; ls -l maps.html lessons_3as_ge.js
echo "تم. نسخة احتياطية: index.html.bak_maps"
